#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BAUD 1000000
#define GPIO_CS_LINE "gpiochip0"
#define GPIO_CS_LINE_NUM 8

int spi_fd, gpio_fd;
struct spi_ioc_transfer transfers[1];
char spi_buffer[3];

void setup_gpio() {
    gpio_fd = gpiod_open_name_with_label(GPIO_CS_LINE, "cs");
    if (gpio_fd < 0) {
        perror("Failed to open GPIO line");
        exit(EXIT_FAILURE);
    }

    gpiod_set_value_cansleep(gpio_fd, GPIO_CS_LINE_NUM, 1);
}

void cleanup_gpio() {
    gpiod_close(gpio_fd);
}

void setup_spi() {
    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    struct spi_device_interface spi_interface = {
        .mode = SPI_MODE,
        .max_speed_hz = SPI_BAUD,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_SET_DEV, &spi_interface) < 1) {
        perror("Failed to configure SPI interface");
        exit(EXIT_FAILURE);
    }
}

void cleanup_spi() {
    close(spi_fd);
}

void send_command(uint8_t command) {
    spi_buffer[0] = command;
    transfers[0].tx_buf = &spi_buffer[0];
    transfers[0].len = 1;

    if (xfer(spi_fd, transfers, 1) != 1) {
        perror("Failed to send command");
        exit(EXIT_FAILURE);
    }
}

uint16_t read_adc() {
    send_command(0x00);
    usleep(10);
    send_command(0x03);

    transfers[0].rx_buf = &spi_buffer[1];
    transfers[0].len = 3;

    if (xfer(spi_fd, transfers, 1) != 1) {
        perror("Failed to read ADC value");
        exit(EXIT_FAILURE);
    }

    uint16_t adc_value = (spi_buffer[1] << 8) | spi_buffer[2];
    return adc_value;
}

int main() {
    setup_gpio();
    setup_spi();

    while (1) {
        gpiod_set_value_cansleep(gpio_fd, GPIO_CS_LINE_NUM, 0);
        uint16_t adc_value = read_adc();
        gpiod_set_value_cansleep(gpio_fd, GPIO_CS_LINE_NUM, 1);

        printf("Moisture level: %d (raw ADC value)\n", adc_value);
        sleep(1);
    }

    cleanup_spi();
    cleanup_gpio();
    return 0;
}

