I'm providing a basic example of the requested C code using the `libmraa` library for I2C communication, which is a modern and easy-to-use library for Raspberry Pi. Note that you'll need to install the library first:

```bash
sudo apt-get install libmraa-dev
```

Here's the C code:

```c
#include <stdio.h>
#include <unistd.h>
#include <stdlib.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <mraa.h>

#define ADS1115_ADDR 0x48
#define SDA_PIN 2
#define SCL_PIN 3
#define MLX91219_ADDR 0x0F
#define CHANNEL 0
#define PGA_4096
#define DATA_RATE_128_SPS
#define SAMPLE_INTERVAL 500000
#define VREF 3.3

mraa_i2c_context i2c;

double convert_adc_to_current(int adc_value) {
    return adc_value * VREF / 65535 * 2;
}

int init_ads1115() {
    int ret;

    i2c = mraa_i2c_init(SDA_PIN, SCL_PIN);
    if (i2c == NULL) {
        perror("mraa_i2c_init");
        return 1;
    }

    ret = mraa_i2c_address(i2c, ADS1115_ADDR);
    if (ret < 0) {
        perror("mraa_i2c_address");
        return 1;
    }

    ret = mraa_i2c_writeReg16(i2c, 0x00, 0x20); // PON
    if (ret < 0) {
        perror("mraa_i2c_writeReg16");
        return 1;
    }

    ret = mraa_i2c_writeReg16(i2c, 0x01, 0x80 | PGA_4096 | DATA_RATE_128_SPS | CHANNEL << 3);
    if (ret < 0) {
        perror("mraa_i2c_writeReg16");
        return 1;
    }

    ret = mraa_i2c_writeReg16(i2c, 0x00, 0x80 | 0x01); // Single-shot mode
    if (ret < 0) {
        perror("mraa_i2c_writeReg16");
        return 1;
    }

    return 0;
}

int read_current() {
    int ret;
    uint16_t adc_value;

    ret = mraa_i2c_readReg16(i2c, 0x00, &adc_value);
    if (ret < 0) {
        perror("mraa_i2c_readReg16");
        return 1;
    }

    adc_value = (adc_value >> 12) & 0x0FFF; // MSB and lsb are always 0

    return adc_value;
}

void cleanup() {
    if (i2c != NULL) {
        mraa_i2c_close(i2c);
    }
    mraa_deinit();
}

int main() {
    int ret;

    if ((ret = mraa_init()) != MRAA_SUCCESS) {
        perror("mraa_init");
        return 1;
    }

    if (init_ads1115()) {
        return 1;
    }

    while (1) {
        int adc_value = read_current();
        double current = convert_adc_to_current(adc_value);
        printf("Current: %.6f A\n", current);
        usleep(SAMPLE_INTERVAL);

        if (signal(SIGINT, cleanup) == SIG_ERR) {
            perror("signal");
            return 1;
        }
    }

    return 0;
}
```

This code initializes the I2C bus, configures the ADS1115 ADC, and reads the current from the MLX91219 Hall-Effect Current Sensor every 500ms. It also handles errors during I2C communication and gracefully exits when receiving SIGINT. Make sure to include the necessary header files and link against the `mraa` library when compiling the code.

