#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <time.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <gpiod.h>
#include <spidev.h>

#define GPIO_BASE "/dev/gpiochip"
#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_FLAME_SENSOR 4
#define GPIO_MCP3008_CE 8
#define GPIO_MCP3008_CS 7
#define SPI_DEVICE_NAME "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define TEMP_MIN 0
#define TEMP_MAX 1023
#define DATA_FILE "flame_data.csv"

int spi_fd, gpio_fd, adc_value;
struct spi_ioc_transfer transfer[1];
char data_file[128];

void cleanup(void) {
    if (gpio_fd >= 0) gpiod_chip_close(gpio_fd);
    if (spi_fd >= 0) close(spi_fd);
    if (access(DATA_FILE, F_OK) == 0) remove(DATA_FILE);
}

void signal_handler(int sig) {
    printf("\nReceived SIGINT, cleaning up and exiting...\n");
    cleanup();
    exit(0);
}

int open_gpio(const char *chip_name) {
    gpio_fd = gpiod_chip_open_with_label(chip_name, "flame_sensor");
    if (gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    gpiod_line_request_dt(gpio_fd, GPIO_FLAME_SENSOR, GPIOD_LINE_REQUEST_INPUT, "flame_sensor");
    gpiod_line_request_dt(gpio_fd, GPIO_MCP3008_CE, GPIOD_LINE_REQUEST_OUTPUT, "mcp3008_ce");
    gpiod_line_request_dt(gpio_fd, GPIO_MCP3008_CS, GPIOD_LINE_REQUEST_OUTPUT, "mcp3008_cs");

    return 0;
}

int open_spi(void) {
    spi_fd = open(SPI_DEVICE_NAME, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_device_interface spi_interface = {
        .mode = SPI_MODE,
        .max_speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_SET_DEV, &spi_interface) < 1) {
        perror("Failed to configure SPI interface");
        return -1;
    }

    return 0;
}

void write_ce(int state) {
    gpiod_line_set_value(gpio_fd, GPIO_MCP3008_CE, state);
}

void write_cs(int state) {
    gpiod_line_set_value(gpio_fd, GPIO_MCP3008_CS, state);
}

int read_adc(void) {
    write_ce(0);
    usleep(10);
    write_cs(0);
    usleep(10);

    transfer[0].tx_buf = (unsigned char*)&adc_value;
    transfer[0].len = sizeof(adc_value);
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = 8;

    if (xfer(spi_fd, transfer, 1) != 1) {
        perror("Failed to read ADC value");
        return -1;
    }

    write_cs(1);

    return adc_value;
}

int main(void) {
    signal(SIGINT, signal_handler);

    if (open_gpio(GPIO_CHIP_NAME) < 0) return 1;
    if (open_spi() < 0) return 1;

    snprintf(data_file, sizeof(data_file), "%s", DATA_FILE);
    FILE *file = fopen(data_file, "w");
    if (!file) {
        perror("Failed to open data file");
        return 1;
    }

    fprintf(file, "Time,Flame Detected,Temperature\n");

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    int flame_detected = 0;

    while (1) {
        gpiod_line_get_value_async(gpio_fd, GPIO_FLAME_SENSOR, NULL, &flame_detected);
        write_ce(1);
        adc_value = read_adc();
        if (adc_value < 0) {
            perror("Failed to read ADC value");
            continue;
        }

        double temperature = (double)adc_value * (TEMP_MAX - TEMP_MIN) / 1023 * 100;
        clock_gettime(CLOCK_REALTIME, &ts);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        fprintf(file, "%s,%d,%.2f\n", timestamp, flame_detected, temperature);

        usleep(1000000); // Sleep for 1 second
    }

    fclose(file);
    cleanup();
    return 0;
}

