code:
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <time.h>
#include <string.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 4
#define TEMP_SENSOR_AIN0 0
#define BUZZER_GPIO 27
#define SAMPLE_INTERVAL 100
#define DEBOUNCE_INTERVAL 50
#define TEMP_THRESHOLD 60
#define FIRE_LOG "/fire_log.txt"

static volatile sig_atomic_t running = 1;
static time_t last_flame = 0;
static time_t last_temp = 0;
static int log_fd = -1;

void flame_cb(int gpio, uint32_t events, void *user_data) {
    if (events & PI_INPUT_RISING_EDGE) {
        last_flame = time(NULL);
    }
}

void temp_read_cb(int status, float *data, void *user_data) {
    if (status != 0) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(status));
        return;
    }

    time_t now = time(NULL);
    if (now - last_temp > SAMPLE_INTERVAL) {
        last_temp = now;
        if (*data > TEMP_THRESHOLD) {
            fprintf(stderr, "Temperature exceeded threshold: %.2f°C\n", *data);
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        exit(1);
    }

    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set flame sensor GPIO mode\n");
        goto cleanup;
    }

    gpioSetAlertFunc(FLAME_SENSOR_GPIO, flame_cb, NULL);

    struct i2c_config i2c_config = {
        .address_10bit = 1,
        .speed = 100000,
    };

    if (i2cOpen(1, ADS1115_DEFAULT_ADDRESS, &i2c_config) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        goto cleanup;
    }

    if (i2cSetGain(1, ADS1115_PGA_6_144) < 0) {
        fprintf(stderr, "Failed to set ADC gain\n");
        goto i2c_close;
    }

    if (i2cConfigSingleRead(1, TEMP_SENSOR_AIN0, 2, temp_read_cb, NULL) < 0) {
        fprintf(stderr, "Failed to read temperature\n");
        goto i2c_config_single_read;
    }

    if (log_fd = open(FIRE_LOG, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH) < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        goto log_close;
    }

    while (running) {
        usleep(DEBOUNCE_INTERVAL * 1000);

        if (gpioRead(FLAME_SENSOR_GPIO) == 1 && last_temp > 0 && time(NULL) - last_flame > DEBOUNCE_INTERVAL) {
            fprintf(log_fd, "%s: %.2f°C\n", ctime(&time(NULL)), last_temp);
            gpioWrite(BUZZER_GPIO, 1);
            sleep(2);
            gpioWrite(BUZZER_GPIO, 0);
        }

        usleep(SAMPLE_INTERVAL * 1000 - DEBOUNCE_INTERVAL * 2);
    }

log_close:
    close(log_fd);

i2c_config_single_read:
    i2cClose(1);

i2c_close:
    gpioTerm();

cleanup:
    return 1;
}

void signal_handler(int sig) {
    running = 0;
}

int main(void) {
    signal(SIGINT, signal_handler);
    return main();
}

