        fprintf(stderr, "Failed to initialize pigpio library\n");
        exit(1);
    }

    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set flame sensor GPIO mode\n");
        goto cleanup;
    }

    gpioSetAlertFunc(FLAME_SENSOR_GPIO, flame_cb, NULL);

    struct i2c_config i2c_config = {
        .address_10bit = 1,
        .speed = 100000,
    };

    if (i2cOpen(1, ADS1115_DEFAULT_ADDRESS, &i2c_config) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        goto cleanup;
    }

    if (i2cSetGain(1, ADS1115_PGA_6_144) < 0) {
        fprintf(stderr, "Failed to set ADC gain\n");
        goto i2c_close;
    }

    if (i2cConfigSingleRead(1, TEMP_SENSOR_AIN0, 2, temp_read_cb, NULL) < 0) {
        fprintf(stderr, "Failed to read temperature\n");
        goto i2c_config_single_read;
    }

    if (log_fd = open(FIRE_LOG, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH) < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        goto log_close;
    }

    while (running) {
        usleep(DEBOUNCE_INTERVAL * 1000);

        if (gpioRead(FLAME_SENSOR_GPIO) == 1 && last_temp > 0 && time(NULL) - last_flame > DEBOUNCE_INTERVAL) {
            fprintf(log_fd, "%s: %.2f°C\n", ctime(&time(NULL)), last_temp);
            gpioWrite(BUZZER_GPIO, 1);
            sleep(2);
            gpioWrite(BUZZER_GPIO, 0);
        }

        usleep(SAMPLE_INTERVAL * 1000 - DEBOUNCE_INTERVAL * 2);
    }

log_close:
    close(log_fd);

i2c_config_single_read:
    i2cClose(1);

i2c_close:
    gpioTerm();

cleanup:
    return 1;
}

void signal_handler(int sig) {
    running = 0;
}

int main(void) {
    signal(SIGINT, signal_handler);
    return main();
}
```

This code initializes the pigpio library, sets up the flame sensor as an input, configures the ADS1115 ADC, and opens a log file. It then enters a main loop that checks both sensors every 100ms with a 50ms debounce applied to the flame sensor. If both sensors indicate a fire condition at the same time, it activates the buzzer for 2 seconds and logs the event with a timestamp to the fire_log.txt file. If only the flame sensor is active, it logs "Flame detected!". If only the temperature exceeds 60°C, it logs the temperature reading.

The code also handles SIGINT by clearing the running flag so the main loop exits cleanly. On exit, it turns off the buzzer, deregisters the interrupt service routine, closes the I2C handle, closes the log file, and invokes the driver library's cleanup call.

Compile the code with:

```sh
gcc -Wall -o fire_detector fire_detector.c -lwiringPiDev -lpthread
```

Please note that you need to have the pigpio library installed on your Raspberry Pi to compile this code. If you don't have it installed, you can find the installation instructions here: https://abyz.co.uk/rpi/pigpio/downloads.html

