static int spi_fd;
static struct spi_ioc_transfer transfers[1];
static gpiod_line_request_lines_data_v1 fan_request;
static gpiod_line_data fan_line;

int init_spi() {
    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Can't open SPI device");
        return -1;
    }

    memset(transfers, 0, sizeof(transfers));

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)NULL,
        .rx_buf = (unsigned long)NULL,
        .len = 0,
        .delay_usecs = 0,
        .speed_hz = 1000000,
        .bits_per_word = 8,
    };

    transfers[0] = transfer;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfers) < 1) {
        perror("Can't configure SPI");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int init_gpio() {
    int ret;
    gpiod_chip *chip;
    gpiod_line_request_data request_data = {
        .consumer = "current_sensor_fan_controller",
        .direction = GPIOD_IN | GPIOD_ASIS,
        .flags = GPIOD_LINE_REQUEST_INPUT,
    };

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Can't open GPIO chip");
        return -1;
    }

    ret = gpiod_chip_get_line_byindex(chip, GPIO_FAN, &fan_line);
    if (ret < 0) {
        perror("Can't get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_chip_request_lines(chip, 1, &fan_request, &request_data);
    if (ret < 0) {
        perror("Can't request GPIO line");
