    transfers[0].tx_buf = (unsigned long)&ADC_MOSI;
    transfers[0].rx_buf = (unsigned long)&ADC_MISO;
    transfers[0].len = 1;

    int ret = write(spi_fd, &transfers, sizeof(transfers));
    if (ret < 0) {
        perror("SPI write error");
        return 0;
    }

    ret = read(spi_fd, &transfers, sizeof(transfers));
    if (ret < 0) {
        perror("SPI read error");
        return 0;
    }

    uint16_t adc_value = transfers[0].rx_buf[0];
    if (adc_value == 0xFFFF || adc_value == 0x0000) {
        fprintf(stderr, "ADC value is all-zero or all-ones\n");
        return 0;
    }

    return adc_value;
}

int main() {
    if (init_spi() < 0) {
        return 1;
    }

    if (init_gpio() < 0) {
        deinit_spi();
        return 1;
    }

    FILE *log_file = fopen("current_log.txt", "w");
    if (!log_file) {
        perror("Can't open log file");
        deinit_gpio();
        deinit_spi();
        return 1;
    }

    time_t timestamp;
    while (1) {
        uint16_t adc_value = read_adc();
        double current = (adc_value * 3.3) / 1023 * 10;

