        char timestamp_str[32];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S.%N", localtime(&timestamp));
        fprintf(log_file, "%s,%f\n", timestamp_str, current);

        if (current > THRESHOLD) {
            gpiod_line_set_value(&fan_line, 1);
        } else {
            gpiod_line_set_value(&fan_line, 0);
        }

        usleep(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    deinit_gpio();
    deinit_spi();

    return 0;
}

