code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <time.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define GPIO_FLAME_SENSOR 4
#define SPI_DEVICE_0 "/dev/spidev0.0"
#define MCP3008_CS_GPIO 8
#define MCP3008_CH_0 0
#define MCP3008_ADC_MAX 1023
#define SAMPLE_INTERVAL 1000000 /* 1 second in microseconds */
#define BUFFER_SIZE 1024

static gpiod_line_request_lines_data_t flame_sensor_req = { .lines = { { .offset = GPIO_FLAME_SENSOR } } };
static gpiod_line_data_t flame_sensor_data = { .active_low = 1 };
static struct spi_device *mcp3008;
static int spi_fd;
static char spi_buffer[BUFFER_SIZE];

void log_data(int flame, int temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    char line[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    snprintf(line, sizeof(line), "%s,%d,%d\n", timestamp, flame, temperature);
    fputs(line, stderr);
    fputs(line, stdout);
    fputs(line, flame_data_file);
}

int init_gpio() {
    int ret;

    ret = gpiod_library_open();
    if (ret < 0) {
        perror("gpiod_library_open");
        return -1;
    }

    ret = gpiod_chip_open_by_name("gpiochip0");
    if (ret < 0) {
        perror("gpiod_chip_open_by_name");
        goto cleanup_libgpiod;
    }

    ret = gpiod_line_request_dt_nodes(&flame_sensor_req, "flame_sensor");
    if (ret < 0) {
        perror("gpiod_line_request_dt_nodes");
        goto cleanup_gpiochip;
    }

    ret = gpiod_line_get_value_cansleep(&flame_sensor_data);
    if (ret < 0) {
        perror("gpiod_line_get_value_cansleep");
        goto cleanup_line_request;
    }

    return 0;

cleanup_line_request:
    gpiod_line_release_request(&flame_sensor_req);

cleanup_gpiochip:
    gpiod_chip_close(flame_sensor_req.chip);

cleanup_libgpiod:
    gpiod_library_close();

    return -1;
}

int init_spi() {
    int ret;

    spi_fd = open(SPI_DEVICE_0, O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &mode);
    if (ret < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        goto cleanup_spi_fd;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_MODE, &mode);
    if (ret < 0) {
        perror("ioctl(SPI_IOC_RD_MODE)");
        goto cleanup_spi_fd;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits);
    if (ret < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        goto cleanup_spi_fd;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &bits);
    if (ret < 0) {
        perror("ioctl(SPI_IOC_RD_BITS_PER_WORD)");
        goto cleanup_spi_fd;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed);
    if (ret < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        goto cleanup_spi_fd;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &speed);
    if (ret < 0) {
        perror("ioctl(SPI_IOC_RD_MAX_SPEED_HZ)");
        goto cleanup_spi_fd;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_LSB_FIRST, &lsb_first);
    if (ret < 0) {
        perror("ioctl(SPI_IOC_WR_LSB_FIRST)");
        goto cleanup_spi_fd;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_LSB_FIRST, &lsb_first);
    if (ret < 0) {
        perror("ioctl(SPI_IOC_RD_LSB_FIRST)");
        goto cleanup_spi_fd;
    }

    ret = gpiod_line_get_value_cansleep(&flame_sensor_data);
    if (ret < 0) {
        perror("gpiod_line_get_value_cansleep");
        goto cleanup_spi_fd;
    }

    if (flame_sensor_data.value != 0) {
        fprintf(stderr, "Flame sensor not connected\n");
        goto cleanup_spi_fd;
    }

    mcp3008 = spi_dev_claim_static(spi_fd, MCP3008_CS_GPIO);
    if (!mcp3008) {
        perror("spi_dev_claim_static");
        goto cleanup_spi_fd;
    }

    return 0;

cleanup_spi_fd:
    close(spi_fd);

    return -1;
}

int read_temperature() {
    int ret;

    spi_buffer[0] = (MCP3008_CH_0 << 5) | 0x01;
    ret = xfer(mcp3008, spi_buffer, spi_buffer, 2);
    if (ret != 2) {
        perror("xfer");
        return -1;
    }

    return (spi_buffer[1] << 8) | spi_buffer[0];
}

void cleanup() {
    if (mcp3008) {
        spi_dev_release(mcp3008);
    }

    if (spi_fd >= 0) {
        close(spi_fd);
    }

    if (flame_sensor_req.chip) {
        gpiod_line_release_request(&flame_sensor_req);
        gpiod_chip_close(flame_sensor_req.chip);
    }

    gpiod_library_close();

    if (flame_data_file) {
        fclose(flame_data_file);
    }

    exit(EXIT_FAILURE);
}

void signal_handler(int signum) {
    cleanup();
}

int main() {
    int ret;
    FILE *flame_data_file;
    int flame = 0;
    int temperature;

    signal(SIGINT, signal_handler);

    flame_data_file = fopen("flame_data.csv", "w");
    if (!flame_data_file) {
        perror("fopen");
        return EXIT_FAILURE;
    }

    ret = init_gpio();
    if (ret < 0) {
        return EXIT_FAILURE;
    }

    ret = init_spi();
    if (ret < 0) {
        return EXIT_FAILURE;
    }

    while (1) {
        ret = gpiod_line_get_value_cansleep(&flame_sensor_data);
        if (ret < 0) {
            perror("gpiod_line_get_value_cansleep");
            cleanup();
        }

        if (flame_sensor_data.value != flame) {
            flame = flame_sensor_data.value;
            if (flame) {
                temperature = read_temperature();
                if (temperature < 0) {
                    perror("read_temperature");
                    cleanup();
                }
                log_data(flame, temperature);
            }
        }

        usleep(SAMPLE_INTERVAL);
    }

    return EXIT_SUCCESS;
}

