static int i2c_write(int file, uint8_t reg, uint8_t data) {
    uint8_t buf[2];
    buf[0] = reg | 0x01;
    buf[1] = data;

    if (write(file, buf, 2) != 2) {
        perror("i2c_write");
        return -1;
    }

    return 0;
}

static int i2c_read(int file, uint8_t reg, uint8_t *data) {
    uint8_t buf[1];

    if (i2c_write(file, reg, 0) == -1) {
        return -1;
    }

    if (read(file, buf, 1) != 1) {
        perror("i2c_read");
        return -1;
    }

    *data = buf[0];
    return 0;
}

static double read_mic(int addr) {
    int file = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (file == -1) {
        perror("open");
        return -999.0;
    }

    if (ioctl(file, I2C_SLAVE, addr) == -1) {
        perror("ioctl");
        close(file);
        return -999.0;
    }

    uint16_t data;
    if (i2c_read(file, 0x00, &data) == -1) {
        perror("i2c_read");
        close(file);
        return -999.0;
    }

    close(file);

    double level = (double)data / 65536 * 2 * 3.3 * 20 * log10(10) / log10(2);
    return level;
}

static void log_entry(double avg) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);

