        return;
    }

    fprintf(file, "%s: Mic1: %.2f dB, Mic2: %.2f dB\n", time_str, avg, avg);
    fclose(file);
}

static void sigint_handler(int signum) {
    gpiod_set_value_cansleep(gpio_get_array_byname("i2c_sda", 1), 1);
    gpiod_set_value_cansleep(gpio_get_array_byname("i2c_scl", 1), 1);
    gpiod_set_value_cansleep(gpio_get_array_byname("i2c_sda", 0), 1);
