#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <time.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BAUD 1000000
#define CS_MIC1_LINE "gpiochip0\0/gpio24"
#define CS_MIC2_LINE "gpiochip0\0/gpio25"
#define LED_LINE "gpiochip0\0/gpio27"
#define FILE_NAME "audio_events.csv"

int spi_write(int fd, const unsigned char *buf, size_t len) {
    if (write(fd, buf, len) != len) {
        perror("SPI write error");
        return -1;
    }
    return 0;
}

int spi_read(int fd, unsigned char *buf, size_t len) {
    if (read(fd, buf, len) != len) {
        perror("SPI read error");
        return -1;
    }
    return 0;
}

double adc_read(int spi_fd, const char *cs_line) {
    gpiod_line_request_lines(1, &cs_line, GPIOD_LINE_REQUEST_INPUT, NULL);
    gpiod_line_set_value(cs_line, 0);
    usleep(10);
    gpiod_line_set_value(cs_line, 1);

    unsigned char data[3];
    if (spi_write(spi_fd, &data, 1) || spi_read(spi_fd, data, 3)) {
        gpiod_line_release_lines(1, &cs_line, NULL);
        return NAN;
    }

    gpiod_line_release_lines(1, &cs_line, NULL);

    double adc_value = (data[1] << 8 | data[2]) * 3.3 / (1 << 12);
    return adc_value;
}

void log_event(const char *timestamp, double mic1_rms, double mic2_rms) {
    FILE *file = fopen(FILE_NAME, "a");
    if (!file) {
        perror("File open error");
        return;
    }

    fprintf(file, "%s,%f,%f\n", timestamp, mic1_rms, mic2_rms);
    fclose(file);
}

int main() {
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("SPI device open error");
        return 1;
    }

    if (spi_open(spi_fd, SPI_MODE, SPI_BAUD)) {
        perror("SPI open error");
        close(spi_fd);
        return 1;
    }

    gpiod_line_request_lines(2, &CS_MIC1_LINE, GPIOD_LINE_REQUEST_OUTPUT, NULL);
    gpiod_line_request_lines(2, &CS_MIC2_LINE, GPIOD_LINE_REQUEST_OUTPUT, NULL);
    gpiod_line_request_line(LED_LINE, GPIOD_LINE_REQUEST_OUTPUT, NULL);

    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    double samples[100][2];
    for (int i = 0; i < 100; ++i) {
        gpiod_line_set_value(CS_MIC1_LINE, 0);
        gpiod_line_set_value(CS_MIC2_LINE, 0);
        usleep(10);

        double mic1_sample = adc_read(spi_fd, CS_MIC1_LINE);
        double mic2_sample = adc_read(spi_fd, CS_MIC2_LINE);

        if (isnan(mic1_sample) || isnan(mic2_sample)) {
            perror("ADC read error");
            break;
        }

        samples[i][0] = mic1_sample;
        samples[i][1] = mic2_sample;

        gpiod_line_set_value(CS_MIC1_LINE, 1);
        gpiod_line_set_value(CS_MIC2_LINE, 1);
        usleep(900);
    }

    clock_gettime(CLOCK_MONOTONIC, &end);
    double timestamp_sec = start.tv_sec + (end.tv_nsec - start.tv_nsec) / 1_e9;

    double mic1_rms = 0;
    double mic2_rms = 0;
    for (int i = 0; i < 100; ++i) {
        mic1_rms += samples[i][0] * samples[i][0];
        mic2_rms += samples[i][1] * samples[i][1];
    }
    mic1_rms /= 100;
    mic2_rms /= 100;

    log_event(ctime(&timestamp_sec), mic1_rms, mic2_rms);

    double high_level_threshold = 0.5;
    if (mic1_rms > high_level_threshold || mic2_rms > high_level_threshold) {
        gpiod_line_set_value(LED_LINE, 1);
        usleep(500000);
    }

    gpiod_line_release_lines(2, &CS_MIC1_LINE, NULL);
    gpiod_line_release_lines(2, &CS_MIC2_LINE, NULL);
    gpiod_line_release_line(LED_LINE, NULL);
    close(spi_fd);

    return 0;
}
