#define TCS34725_ID 0x85

static int i2c_file;
static struct gpiod_chip *chip;
static gpiod_line_request_lines_data lines;

static void i2c_error(const char *msg) {
    perror(msg);
    fprintf(stderr, "Error: %s\n", strerror(errno));
}

static int i2c_write(uint8_t reg, uint16_t value) {
    uint8_t data[2];
    data[0] = reg;
    data[1] = value;

    if (write(i2c_file, data, 2) != 2) {
        i2c_error("i2c_write");
        return -1;
    }

    return 0;
}

static int i2c_read(uint8_t reg, uint16_t *value) {
    uint8_t data[2];

    if (read(i2c_file, data, 2) != 2) {
        i2c_error("i2c_read");
        return -1;
    }

    *value = (data[1] << 8) | data[0];
    return 0;
}

static int init_i2c() {
    const char *dev_name = "/dev/i2c-" I2C_BUS;

    if ((i2c_file = open(dev_name, O_RDWR)) < 0) {
        i2c_error("open");
        return -1;
    }

    if (ioctl(i2c_file, I2C_SLAVE, TCS34725_ADDR) < 0) {
        i2c_error("ioctl");
        return -1;
    }

    return 0;
}

static int init_gpio() {
    const char *chip_name = "gpiochip0";

    if (!(chip = gpiod_chip_open_by_name(chip_name))) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_strerror(errno));
        return -1;
    }

    lines.flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_RISING;
    lines.consumer = "tcs34725";

    if (gpiod_chip_request_lines(chip, 1, &lines, NULL) < 0) {
        fprintf(stderr, "Failed to request GPIO lines: %s\n", gpiod_strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup() {
    gpiod_line_release_request(lines.lines[0]);
    gpiod_chip_close(chip);
    close(i2c_file);
}

static void signal_handler(int signum) {
    (void)signum;
    cleanup();
    exit(1);
}

static void log_color(const char *timestamp, uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    char line[256];
    snprintf(line, sizeof(line), "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);

    FILE *file = fopen("color_log.csv", "a");
    if (!file) {
        fprintf(stderr, "Failed to open color_log.csv: %s\n", strerror(errno));
        return;
    }

    if (fputs(line, file) == EOF) {
        fprintf(stderr, "Failed to write to color_log.csv: %s\n", strerror(errno));
    }

    fclose(file);
}

static int read_sensor() {
    uint16_t id;

    if (i2c_write(0x0A, 0x00) < 0) {
        return -1;
    }

    if (i2c_read(0x09, &id) < 0) {
        return -1;
    }

    if (id != TCS34725_ID) {
        fprintf(stderr, "Sensor ID mismatch: expected 0x%04x, got 0x%04x\n", TCS34725_ID, id);
        return -1;
    }

    uint16_t clear, red, green, blue;
    if (i2c_read(0x0C, &clear) < 0) {
        return -1;
    }
    if (i2c_read(0x0D, &red) < 0) {
        return -1;
    }
    if (i2c_read(0x0E, &green) < 0) {
        return -1;
    }
    if (i2c_read(0x0F, &blue) < 0) {
        return -1;
    }

    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_gpio() < 0) {
        return 1;
    }

    if (init_i2c() < 0) {
        return 1;
    }

    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[64];

    if (read_sensor() < 0) {
        fprintf(stderr, "Failed to read sensor data\n");
        goto cleanup_and_exit;
    }

    FILE *file = fopen("color_log.csv", "a");
    if (!file) {
        fprintf(stderr, "Failed to open color_log.csv: %s\n", strerror(errno));
        goto cleanup_and_exit;
    }

    if (fputs("Year,Month,Day,Hour,Minute,Second,Clear,Red,Green,Blue\n", file) == EOF) {
        fprintf(stderr, "Failed to write header to color_log.csv: %s\n", strerror(errno));
        goto cleanup_and_exit;
    }

    while (1) {
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        if (read_sensor() < 0) {
            if (errno != EAGAIN) {
                fprintf(stderr, "Failed to read sensor data\n");
            }
            continue;
        }

        log_color(timestamp, read_sensor() < 0 ? 0 : clear, read_sensor() < 0 ? 0 : red, read_sensor() < 0 ? 0 : green, read_sensor() < 0 ? 0 : blue);
    }

cleanup_and_exit:
    cleanup();
    return 1;
}
