    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }

    if (ce_gpio != MRAA_INVALID_HANDLE) {
        mraa_gpio_close(ce_gpio);
        ce_gpio = MRAA_INVALID_HANDLE;
    }

