int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(spi_fd, SPI_OPEN, 0) < 0) {
        perror("Failed to open SPI bus");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_CPOL, 0) < 0) {
        perror("Failed to set SPI mode 0");
        goto close_spi;
    }

    if (ioctl(spi_fd, SPI_CPHA, 0) < 0) {
        perror("Failed to set SPI mode 0");
        goto close_spi;
    }

    if (ioctl(spi_fd, SPI_MODE32BIT, 0) < 0) {
        perror("Failed to set SPI mode 32-bit");
        goto close_spi;
    }

    return 0;

close_spi:
    close(spi_fd);
    return -1;
}

int init_gpio() {
    ce_gpio = mraa_gpio_init(GPIO_CE0);
    if (ce_gpio == MRAA_INVALID_HANDLE) {
        perror("Failed to initialize GPIO");
        return -1;
    }

    mraa_gpio_dir(ce_gio, MRAA_GPIO_OUT);
    mraa_gpio_write(ce_gpio, 1);

    return 0;
}

int read_moisture(int channel) {
    int adc_value;
    int data[3];

    mraa_gpio_write(ce_gpio, 0);
    usleep(10);

    if (write(spi_fd, &adc_value, sizeof(adc_value)) != sizeof(adc_value)) {
        perror("Failed to write to SPI device");
        return -1;
    }

    if (read(spi_fd, data, sizeof(data)) != sizeof(data)) {
        perror("Failed to read from SPI device");
        return -1;
    }

    adc_value = (data[2] << 8) | data[3];

    mraa_gpio_write(ce_gpio, 1);

    return adc_value;
}

