static gpiod_line_request_linenum_t reset_line;
static gpiod_line_request_data_t pressure_en_data = GPIOD_LINE_REQUEST_INPUT;
static gpiod_line_request_data_t reset_data = GPIOD_LINE_REQUEST_OUTPUT_LOW;

static int i2c_fd;
static FILE *log_file;

void i2c_init() {
    const char *const bus_path = "/dev/i2c-1";
    i2c_fd = open(bus_path, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (gpiod_chip_open_by_name("gpiochip0") < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    pressure_en_line = gpiod_chip_get_line(gpiod_chip_get_by_name("gpiochip0"), 18);
    reset_line = gpiod_chip_get_line(gpiod_chip_get_by_name("gpiochip0"), 17);

    if (gpiod_line_request_enable(pressure_en_line, &pressure_en_data, GPIOD_LINE_REQUEST_DIRECTION_IN) < 0) {
        perror("Failed to request pressure enable line");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_enable(reset_line, &reset_data, GPIOD_LINE_REQUEST_DIRECTION_OUT) < 0) {
        perror("Failed to request reset line");
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(reset_line, 1);
    usleep(100000);
    gpiod_line_set_value(reset_line, 0);
    usleep(100000);
    gpiod_line_set_value(reset_line, 1);
    usleep(100000);
}

int i2c_read(uint8_t *data, size_t len) {
    int ret;
    if ((ret = i2c_smbus_read_i2c_block_data(i2c_fd, I2C_ADDR, len, data)) < 0) {
        perror("I2C read error");
        return ret;
    }
    return 0;
}

