    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    snprintf(line, sizeof(line), "%s,%d\n", timestamp, pressure / 10);
    if (fputs(line, log_file) == EOF) {
        perror("Failed to write to log file");
    }
    fflush(log_file);
}

void signal_handler(int sig) {
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (pressure_en_line >= 0) {
        gpiod_line_request_deactivate(pressure_en_line);
    }
    if (reset_line >= 0) {
        gpiod_line_request_deactivate(reset_line);
    }
    gpiod_chip_close(gpiod_chip_get_by_name("gpiochip0"));
    exit(0);
}

