#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <wiringPiI2C.h>

#define ADS1115_ADDR 0x48 // ADS1115 I2C address
#define MLX90834_ADDR 0x5A // MLX90834 I2C address
#define PRESSURE_CHANNEL 0
#define TEMPERATURE_CHANNEL 1
#define NUM_I2C_RETRIES 3
#define WARNING_PRESSURE 105000 // Pressure in micro-Pa
#define GPIO_WARNING_PIN 17

int i2c_file;
int gpio_warning_pin;

int init_i2c() {
    if ((i2c_file = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_file, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to acquire I2C address");
        return -1;
    }

    return 0;
}

int init_gpio() {
    if (wiringPiSetup() == -1) {
        perror("Failed to initialize wiringPi");
        return -1;
    }

    gpio_warning_pin = wiringPiSetupGPIO(GPIO_WARNING_PIN);
    pinMode(gpio_warning_pin, OUTPUT);

    return 0;
}

int read_adc(uint8_t channel) {
    uint8_t config = 0x20 | (channel << 6); // Single-ended, 16-bit resolution
    int retries = 0;

    do {
        if (writeReg16(config) < 0) {
            usleep(100000); // Wait 100ms before retrying
            retries++;
            if (retries >= NUM_I2C_RETRIES) {
                perror("Failed to write ADC configuration");
                return -1;
            }
            continue;
        }

        usleep(100000); // Wait 100ms for conversion to complete

        if (readReg16(0x00) < 0) {
            perror("Failed to read ADC data");
            return -1;
        }
    } while (retries > 0);

    return readReg16(0x02);
}

int read_mlx90834() {
    uint8_t data[6];
    int retries = 0;

    do {
        if (i2c_smbus_read_i2c_block_data(i2c_file, MLX90834_ADDR, 6, data) != 6) {
            usleep(100000); // Wait 100ms before retrying
            retries++;
            if (retries >= NUM_I2C_RETRIES) {
                perror("Failed to read MLX90834 data");
                return -1;
            }
            continue;
        }

        break;
    } while (retries > 0);

    if (retries > 0) {
        perror("Failed to read MLX90834 data");
        return -1;
    }

    int16_t pressure = (data[1] << 8) | data[2];
    int16_t temperature = (data[4] << 8) | data[5];

    return pressure * 100 / 16384 + 25 + 273.15 + (temperature * 500 / 65536);
}

int writeReg16(uint16_t value) {
    return i2c_smbus_write_word_data(i2c_file, ADS1115_ADDR, value);
}

int readReg16(uint8_t reg) {
    return i2c_smbus_read_word_data(i2c_file, ADS1115_ADDR << 1 | (1 << 0)); // I2C read with acknowledge
}

int main() {
    if (init_i2c() < 0 || init_gpio() < 0) {
        return 1;
    }

    int pressure, temperature;
    double last_pressure = 0.0;

    while (1) {
        if (read_adc(PRESSURE_CHANNEL) < 0 || read_adc(TEMPERATURE_CHANNEL) < 0 ||
            (pressure = read_mlx90834()) < 0) {
            perror("Failed to read sensor data");
            continue;
        }

        if (pressure > WARNING_PRESSURE) {
            digitalWrite(gpio_warning_pin, HIGH);
        }

        double delta_pressure = pressure - last_pressure;
        last_pressure = pressure;

        printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure / 100.0, temperature - 273.15);
        printf("Pressure change: %.2f kPa/s\n", delta_pressure / 1.0);
        fflush(stdout);

        sleep(1);
    }

    close(i2c_file);
    digitalWrite(gpio_warning_pin, LOW);
    wiringPiTerminate();

    return 0;
}

