#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <libgpiod/gpiod.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define CHIP_SELECT 8
#define MCP3008_REG_ADC0 0x00

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int lines,
                                const char *consumer, const char *label)
{
    struct gpiod_line_request *request;
    int ret;

    request = gpiod_chip_get_line_request_by_number(chip, lines);
    if (request) {
        fprintf(stderr, "Line %d already requested by %s\n", lines, consumer);
        return NULL;
    }

    request = gpiod_chip_request_line(chip, lines, consumer, label);
    if (IS_ERR(request)) {
        fprintf(stderr, "Failed to request line %d: %s\n", lines,
                gpiod_strerror(ptr_err(request)));
        return NULL;
    }

    return request;
}

int main() {
    int spi_fd, ret;
    struct spi_ioc_transfer transfers[1];
    unsigned int adc_value;
    float voltage;
    struct timespec ts;
    struct gpiod_chip *chip;
    struct gpiod_line_request *alarm_request, *cs_request;
    FILE *log_file;
    char log_filename[] = "co_log.txt";

    clock_gettime(CLOCK_REALTIME, &ts);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (IS_ERR(chip)) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_strerror(ptr_err(chip)));
        return 1;
    }

    cs_request = gpiod_line_request_lines(chip, 1, "co_sensor", "CE0");
    if (!cs_request) {
        gpiod_chip_put(chip);
        return 1;
    }

    alarm_request = gpiod_line_request_lines(chip, 1, "co_alarm", "Alarm");
    if (!alarm_request) {
        gpiod_line_release(cs_request);
        gpiod_chip_put(chip);
        return 1;
    }

    gpiod_line_set_value(alarm_request, 0);

    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        gpiod_line_release(alarm_request);
        gpiod_line_release(cs_request);
        gpiod_chip_put(chip);
        return 1;
    }

    transfers[0].tx_buf = (unsigned char*)&MCP3008_REG_ADC0;
    transfers[0].len = sizeof(MCP3008_REG_ADC0);
    transfers[0].speed_hz = SPI_SPEED;
    transfers[0].bits_per_word = 8;

    ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfers);
    if (ret < 1) {
        fprintf(stderr, "Failed to send SPI transfer: %s\n", strerror(errno));
        close(spi_fd);
        gpiod_line_release(alarm_request);
        gpiod_line_release(cs_request);
        gpiod_chip_put(chip);
        return 1;
    }

    ret = read(spi_fd, &adc_value, sizeof(adc_value));
    if (ret != sizeof(adc_value)) {
        fprintf(stderr, "Failed to read SPI transfer: %s\n", strerror(errno));
        close(spi_fd);
        gpiod_line_release(alarm_request);
        gpiod_line_release(cs_request);
        gpiod_chip_put(chip);
        return 1;
    }

    voltage = (adc_value * 3.3f) / 1023 * 2.5f;

    log_file = fopen(log_filename, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(spi_fd);
        gpiod_line_release(alarm_request);
        gpiod_line_release(cs_request);
        gpiod_chip_put(chip);
        return 1;
    }

    fprintf(log_file, "%4d-%02d-%02d %02d:%02d:%02d,Voltage: %.2f V\n",
            ts.tv_year, ts.tv_mon, ts.tv_mday, ts.tv_hour, ts.tv_min, ts.tv_sec, voltage);
    fclose(log_file);

    if (voltage > 2.5f)
        gpiod_line_set_value(alarm_request, 1);
    else
        gpiod_line_set_value(alarm_request, 0);

    clock_gettime(CLOCK_REALTIME, &ts);
    while (1) {
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfers);
        if (ret < 1) {
            fprintf(stderr, "Failed to send SPI transfer: %s\n", strerror(errno));
            if (errno != EAGAIN) {
                gpiod_line_set_value(alarm_request, 0);
                sleep(1);
            }
            continue;
        }

        ret = read(spi_fd, &adc_value, sizeof(adc_value));
        if (ret != sizeof(adc_value)) {
            fprintf(stderr, "Failed to read SPI transfer: %s\n", strerror(errno));
            if (errno != EAGAIN) {
                gpiod_line_set_value(alarm_request, 0);
                sleep(1);
            }
            continue;
        }

        voltage = (adc_value * 3.3f) / 1023 * 2.5f;

        if (voltage > 2.5f)
            gpiod_line_set_value(alarm_request, 1);
        else
            gpiod_line_set_value(alarm_request, 0);

        clock_gettime(CLOCK_REALTIME, &ts);

        log_file = fopen(log_filename, "a");
        if (!log_file) {
            fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
            continue;
        }

        fprintf(log_file, "%4d-%02d-%02d %02d:%02d:%02d,Voltage: %.2f V\n",
                ts.tv_year, ts.tv_mon, ts.tv_mday, ts.tv_hour, ts.tv_min, ts.tv_sec, voltage);
        fclose(log_file);

        sleep(1);
    }

    close(spi_fd);
    gpiod_line_release(alarm_request);
    gpiod_line_release(cs_request);
    gpiod_chip_put(chip);

    return 0;
