static int spi_fd;
static struct spi_ioc_transfer transfers[1];

void spi_init() {
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Can't open spi device");
        exit(EXIT_FAILURE);
    }

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long*)&ADDR,
        .rx_buf = (unsigned long*)&transfers[0].rx_buf,
        .len = sizeof(ADDR),
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED_1MHZ,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Can't send SPI command");
        exit(EXIT_FAILURE);
    }
}

int read_sensor() {
    transfers[0].tx_buf = NULL;
    transfers[0].rx_buf = malloc(3);

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfers) != 1) {
        perror("Can't read SPI data");
        return -1;
    }

    int reading = (transfers[0].rx_buf[1] << 8) | transfers[0].rx_buf[0];
    free(transfers[0].rx_buf);
    return reading;
}

