    fprintf(file, "%s,%d\n", timestamp, reading);
    fclose(file);
}

void alarm_leak(const char *message) {
    fprintf(stderr, "%s\n", message);
}

int main() {
    gpiod_line_request_lines(1, "mcp3008_cs", GPIOD_LINE_REQUEST_INPUT, "MCP3008 CS");
    gpiod_line_get_value(gpiod_get_line_byname("mcp3008_cs"));

