#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <linux/i2c-bit.h>
#include <sys/time.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <gpiod.h>

#define I2C_BUS 1
#define ADC_ADDR 0x48
#define SDA_GPIO 2
#define SCL_GPIO 3
#define ADC_CHANNEL 0
#define SAMPLE_RATE 1000
#define MAX_PRESSURE 100000

static gpiod_line_request_lines(1, "gpio", SDA_GPIO, GPIOD_IN, NULL);
static gpiod_line_request_lines(1, "gpio", SCL_GPIO, GPIOD_IN, NULL);

int i2c_init(void) {
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADC_ADDR) < 0) {
        perror("Failed to acquire bus access");
        close(i2c_fd);
        return -1;
    }

    return i2c_fd;
}

uint16_t adc_read(int i2c_fd) {
    uint8_t buf[2];
    buf[0] = 0x00;
    buf[1] = 0x00;

    if (i2c_smbus_write_byte_data(i2c_fd, 0x00, ADC_CHANNEL << 6 | 0x01) < 0) {
        perror("Failed to write ADC configuration");
        return 0;
    }

    if (i2c_smbus_read_i2c_block_data(i2c_fd, buf, 2) != 2) {
        perror("Failed to read ADC data");
        return 0;
    }

    return (buf[1] << 8) | buf[0];
}

void log_pressure(const char *timestamp, uint16_t pressure) {
    FILE *log_file = fopen("pressure_log.txt", "a");
    if (!log_file) {
        perror("Failed to open pressure log file");
        return;
    }

    fprintf(log_file, "%s,%d\n", timestamp, pressure);
    fclose(log_file);
}

void handle_signal(int sig) {
    gpiod_line_release_request_lines(1, "gpio", SDA_GPIO, SCL_GPIO);
    exit(0);
}

int main(void) {
    signal(SIGINT, handle_signal);

    gpiod_line_request_lines(1, "gpio", SDA_GPIO, GPIOD_IN, NULL);
    gpiod_line_request_lines(1, "gpio", SCL_GPIO, GPIOD_IN, NULL);

    int i2c_fd = i2c_init();
    if (i2c_fd < 0) {
        return 1;
    }

    struct timeval tv;
    gettimeofday(&tv, NULL);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%f", localtime(&tv.tv_sec));

    uint16_t pressure;
    while (1) {
        pressure = adc_read(i2c_fd);
        if (pressure > 0 && pressure <= MAX_PRESSURE) {
            log_pressure(timestamp, pressure);
        }

        tv.tv_usec += SAMPLE_RATE * 1000000;
        tv.tv_sec += tv.tv_usec / 1000000;
        tv.tv_usec %= 1000000;
        usleep(tv.tv_usec - (tv.tv_usec = SAMPLE_RATE * 1000000));
    }

    close(i2c_fd);
    gpiod_line_release_request_lines(1, "gpio", SDA_GPIO, SCL_GPIO);

    return 0;
}
