code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BAUD 1000000
#define GPIO_CHIP "gpiochip4"
#define GPIO_LINE "8"
#define TMP36_ADC_CHANNEL 0
#define TMP36_ADC_RESOLUTION 1024
#define TMP36_ADC_MIN 0
#define TMP36_ADC_MAX 1023
#define TMP36_MIN_TEMP -40.0
#define TMP36_MAX_TEMP 125.0
#define LOG_FILE "temperature_log.csv"

gpiod_line_request_linestate_t gpio_state;
int spi_fd;
struct spi_ioc_transfer transfers[2];

void sigint_handler(int signum) {
    gpiod_line_set_value(gpio_chip, GPIO_LINE, 0);
    close(spi_fd);
    gpiod_line_release(gpio_line);
    gpiod_chip_unclaim(gpio_chip);
    fclose(log_file);
    exit(0);
}

void setup_gpio() {
    gpiod_chip *chip = gpiod_chip_open_byname(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(1);
    }

    gpio_line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        exit(1);
    }

    gpiod_line_request_flags_mbus(gpio_line, GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW);
    gpiod_line_request_consumer(gpio_line, "TMP36 ADC CE");
    gpiod_line_get_value(gpio_line, &gpio_state);
}

void setup_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(1);
    }

    struct spi_device_interface spi_interface = {
        .mode = SPI_MODE,
        .max_speed_hz = SPI_BAUD,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_WRITE_INTERFACE, &spi_interface) < 1) {
        perror("Failed to configure SPI interface");
        exit(1);
    }
}

uint16_t read_adc() {
    transfers[0].tx_buf = (unsigned char*)&gpio_state;
    transfers[0].len = sizeof(gpio_state);
    transfers[0].speed_hz = SPI_BAUD;
    transfers[0].bits.cs_set = 0;
    transfers[0].bits.cs_hold = 0;

    transfers[1].tx_buf = NULL;
    transfers[1].len = 0;
    transfers[1].speed_hz = SPI_BAUD;
    transfers[1].bits.cs_set = 1;
    transfers[1].bits.cs_hold = 1;

    int xfer_count = spi_xfer(spi_fd, transfers, 2);
    if (xfer_count != 2) {
        perror("Failed to transfer data");
        exit(1);
    }

    uint16_t adc_value = (transfers[1].rx_buf[TMP36_ADC_CHANNEL] & 0x00FF) << 8 | transfers[1].rx_buf[TMP36_ADC_CHANNEL + 1];
    return adc_value;
}

float convert_temp(uint16_t adc_value) {
    float voltage = (adc_value * 3.3f) / TMP36_ADC_RESOLUTION;
    float temperature_celsius = (voltage - 0.5) * 100;
    return temperature_celsius;
}

void log_temp(float temperature_celsius) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(1);
    }

    fprintf(log_file, "%s,%f\n", time_str, temperature_celsius);
    fclose(log_file);
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    setup_gpio();
    setup_spi();

    float last_temp = NAN;
    while (1) {
        uint16_t adc_value = read_adc();
        float temperature_celsius = convert_temp(adc_value);

        if (isnan(last_temp) || temperature_celsius < TMP36_MIN_TEMP || temperature_celsius > TMP36_MAX_TEMP) {
            printf("Sensor out of range or absent\n");
            gpiod_line_set_value(gpio_chip, GPIO_LINE, 0);
            close(spi_fd);
            gpiod_line_release(gpio_line);
            gpiod_chip_unclaim(gpio_chip);
            fclose(log_file);
            exit(1);
        }

        if (last_temp == NAN || fabs(last_temp - temperature_celsius) > 0.5) {
            log_temp(temperature_celsius);
            last_temp = temperature_celsius;
        }

        sleep(1);
    }

    return 0;
}

