code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <sys/stat.h>
#include <errno.h>
#include <libgpiod.h>

#define SI1172_ADDR 0x62
#define SI1172_REG_CMD 0x80
#define SI1172_REG_DATA 0x81
#define SI1172_REG_STATUS 0x82
#define SI1172_REG_IR_DATA 0x83
#define SI1172_REG_RED_DATA 0x84
#define SI1172_REG_GREEN_DATA 0x85
#define SI1172_REG_BLUE_DATA 0x86
#define SI1172_REG_HR_RAW 0x87
#define SI1172_REG_SP02_RAW 0x88
#define SI1172_CMD_START_HR_MEASUREMENT 0x01
#define SI1172_CMD_START_SP02_MEASUREMENT 0x02
#define SI1172_CMD_STOP_MEASUREMENT 0x00

int main() {
    int i2c_fd, ret;
    char filename[] = "biometric_log.csv";
    FILE *log_file;
    struct timespec ts;
    gpiod_line_request_linenum_data_vlinemask_flags_data_vlinemask_flags_data_vlinemask_flags *gpio_request;
    struct i2c_rdwr_ioctl_data i2c_data;
    i2c_rdwr_ioctl_data_t *msg;
    uint16_t ir_data, red_data;
    time_t rawtime;
    struct tm *timeinfo;
    int error_flag = 0;

    // Open I2C bus
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Request GPIO line for resetting the sensor
    gpio_request = gpiod_chip_get_line_request_linenum(gpiod_chip_get_by_name("gpiochip0"), 17);
    gpiod_line_request_enable(gpio_request, GPIOD_LINE_REQUEST_DIRECTION_OUT | GPIOD_LINE_REQUEST_ACTIVE_LOW);

    // Reset the sensor
    gpiod_line_set_value(gpio_request, 1);
    usleep(100000);
    gpiod_line_set_value(gpio_request, 0);
    usleep(100000);

    // Initialize I2C transfer data
    i2c_data.wr_buf = &SI1172_CMD_START_HR_MEASUREMENT;
    i2c_data.wr_len = 1;
    i2c_data.rd_buf = NULL;
    i2c_data.rd_len = 0;
    msg = &i2c_data;

    // Main loop
    while (1) {
        // Start HR measurement
        ret = ioctl(i2c_fd, I2C_RDWR, msg);
        if (ret < 0) {
            if (errno == EIO) {
                error_flag = 1;
            } else {
                perror("Failed to start HR measurement");
                exit(EXIT_FAILURE);
            }
        }

        // Wait for HR data
        msg->wr_buf = NULL;
        msg->wr_len = 0;
        msg->rd_buf = &ir_data;
        msg->rd_len = 2;
        ret = ioctl(i2c_fd, I2C_RDWR, msg);
        if (ret < 0) {
            if (errno == EIO) {
                error_flag = 1;
            } else {
                perror("Failed to read HR data");
                exit(EXIT_FAILURE);
            }
        }

        // Start SpO₂ measurement
        msg->wr_buf = &SI1172_CMD_START_SP02_MEASUREMENT;
        ret = ioctl(i2c_fd, I2C_RDWR, msg);
        if (ret < 0) {
            if (errno == EIO) {
                error_flag = 1;
            } else {
                perror("Failed to start SpO₂ measurement");
                exit(EXIT_FAILURE);
            }
        }

        // Wait for SpO₂ data
        msg->wr_buf = NULL;
        msg->wr_len = 0;
        msg->rd_buf = &red_data;
        msg->rd_len = 2;
        ret = ioctl(i2c_fd, I2C_RDWR, msg);
        if (ret < 0) {
            if (errno == EIO) {
                error_flag = 1;
            } else {
                perror("Failed to read SpO₂ data");
                exit(EXIT_FAILURE);
            }
        }

        // Stop measurements
        msg->wr_buf = &SI1172_CMD_STOP_MEASUREMENT;
        ret = ioctl(i2c_fd, I2C_RDWR, msg);
        if (ret < 0) {
            if (errno == EIO) {
                error_flag = 1;
            } else {
                perror("Failed to stop measurements");
                exit(EXIT_FAILURE);
            }
        }

        // Check if sensor is absent or uninitialized
        msg->wr_buf = &SI1172_REG_STATUS;
        msg->wr_len = 1;
        msg->rd_buf = NULL;
        msg->rd_len = 1;
        ret = ioctl(i2c_fd, I2C_RDWR, msg);
        if (ret < 0) {
            if (errno == EIO) {
                error_flag = 2;
            } else {
                perror("Failed to read sensor status");
                exit(EXIT_FAILURE);
            }
        }

        // Log data
        clock_gettime(CLOCK_REALTIME, &ts);
        rawtime = ts.tv_sec;
        timeinfo = localtime(&rawtime);
        fprintf(log_file, "%d,%u,%u,%d\n", (int)rawtime, ir_data, red_data, error_flag);
        fflush(log_file);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Close I2C bus
    close(i2c_fd);

    // Free GPIO line
    gpiod_line_release(gpio_request);

    // Close log file
    fclose(log_file);

    return 0;
}

