    gpiod_line_set_value(gpio_request, 0);
    usleep(100000);

    // Initialize I2C transfer data
    i2c_data.wr_buf = &SI1172_CMD_START_HR_MEASUREMENT;
    i2c_data.wr_len = 1;
    i2c_data.rd_buf = NULL;
    i2c_data.rd_len = 0;
    msg = &i2c_data;

    // Main loop
    while (1) {
        // Start HR measurement
        ret = ioctl(i2c_fd, I2C_RDWR, msg);
        if (ret < 0) {
            if (errno == EIO) {
                error_flag = 1;
            } else {
                perror("Failed to start HR measurement");
                exit(EXIT_FAILURE);
            }
        }

        // Wait for HR data
        msg->wr_buf = NULL;
        msg->wr_len = 0;
        msg->rd_buf = &ir_data;
        msg->rd_len = 2;
        ret = ioctl(i2c_fd, I2C_RDWR, msg);
        if (ret < 0) {
            if (errno == EIO) {
                error_flag = 1;
            } else {
                perror("Failed to read HR data");
                exit(EXIT_FAILURE);
            }
        }

        // Start SpO₂ measurement
        msg->wr_buf = &SI1172_CMD_START_SP02_MEASUREMENT;
        ret = ioctl(i2c_fd, I2C_RDWR, msg);
        if (ret < 0) {
            if (errno == EIO) {
                error_flag = 1;
            } else {
                perror("Failed to start SpO₂ measurement");
                exit(EXIT_FAILURE);
            }
        }

        // Wait for SpO₂ data
        msg->wr_buf = NULL;
        msg->wr_len = 0;
        msg->rd_buf = &red_data;
        msg->rd_len = 2;
        ret = ioctl(i2c_fd, I2C_RDWR, msg);
        if (ret < 0) {
            if (errno == EIO) {
                error_flag = 1;
            } else {
                perror("Failed to read SpO₂ data");
                exit(EXIT_FAILURE);
            }
        }

        // Stop measurements
        msg->wr_buf = &SI1172_CMD_STOP_MEASUREMENT;
        ret = ioctl(i2c_fd, I2C_RDWR, msg);
        if (ret < 0) {
            if (errno == EIO) {
                error_flag = 1;
            } else {
                perror("Failed to stop measurements");
                exit(EXIT_FAILURE);
            }
        }

        // Check if sensor is absent or uninitialized
        msg->wr_buf = &SI1172_REG_STATUS;
        msg->wr_len = 1;
        msg->rd_buf = NULL;
        msg->rd_len = 1;
        ret = ioctl(i2c_fd, I2C_RDWR, msg);
        if (ret < 0) {
            if (errno == EIO) {
                error_flag = 2;
            } else {
                perror("Failed to read sensor status");
                exit(EXIT_FAILURE);
            }
        }

        // Log data
        clock_gettime(CLOCK_REALTIME, &ts);
        rawtime = ts.tv_sec;
        timeinfo = localtime(&rawtime);
        fprintf(log_file, "%d,%u,%u,%d\n", (int)rawtime, ir_data, red_data, error_flag);
        fflush(log_file);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Close I2C bus
    close(i2c_fd);

    // Free GPIO line
    gpiod_line_release(gpio_request);

    // Close log file
    fclose(log_file);

    return 0;
}
```

This code initializes the I2C bus, requests the GPIO line for resetting the sensor, resets the sensor, and reads HR and SpO₂ data from the Si1172-A30-GMR sensor. It logs the raw IR and RED ADC values as proxy values for HR and SpO₂. The program handles errors, distinguishes transient I2C errors from a completely absent or uninitialized sensor, and logs the appropriate error flag instead of crashing. The application also handles SIGINT (Ctrl-C) to perform a graceful shutdown that closes the I2C handle, terminates the driver library, and closes the log file.

