        usleep(10);
        gpioWrite(GPIO_NUM_8, 1);
        usleep(1);
        gpioRead(GPIO_NUM_8);
        if (gpioRead(GPIO_NUM_8) != 0) {
            adc_value = (uint16_t)(gpioRead(GPIO_NUM_8) * (ADC_FULL_SCALE - 1) / 2);
        } else {
            adc_value = 0;
        }
    } else {
        adc_value = 0;
    }
    return (adc_value * FS_MV * R2_MIN * R1) / (ADC_FULL_SCALE * (R1 + R2_MIN));
}

