    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];
    char line[128];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.", timeinfo);
    snprintf(line, sizeof(line), "%s%06lu,%f\n", timestamp, (unsigned long)us_now(), flow);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    fputs(line, log_file);
    fflush(log_file);
    fclose(log_file);
}

