        fprintf(stderr, "pigpio_init: %s\n", strerror(-ret));
        return 1;
    }

    if ((adc_fd = open("/dev/mem", O_RDONLY | O_SYNC)) < 0) {
        perror("open");
        fprintf(stderr, "Failed to open /dev/mem: %s\n", strerror(errno));
        return 1;
    }

    if ((gpioInitialise() < 0) || (gpioSetMode(GPIO_NUM_8, PI_INPUT) < 0) ||
        (gpioSetMode(GPIO_NUM_18, PI_OUTPUT) < 0) || (gpioWrite(GPIO_NUM_18, 1) < 0)) {
        fprintf(stderr, "gpioInitialise or gpioSetMode failed\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (running) {
        flow = flow_rate();
        if (!isnan(flow)) {
            log_flow_rate(flow);
        }
        usleep(1000000);
    }

    gpioTerm();
    close(adc_fd);
    pigpio_terminate();
    return 0;
}

