#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/time.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1E
#define SENSOR_ID 0x01
#define DATA_LENGTH 6
#define DELAY_MS 5000
#define LOG_FILE "environmental_data.csv"

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int nlines,
                                const char *const *consumer,
                                unsigned int flags) {
    return gpiod_chip_request_lines(chip, nlines, consumer, flags);
}

static void i2c_write_bytes(int file, const uint8_t *data, size_t len) {
    int ret;
    for (size_t i = 0; i < len; ++i) {
        ret = write(file, &data[i], 1);
        if (ret != 1) {
            perror("I2C write");
            exit(EXIT_FAILURE);
        }
    }
}

static int i2c_read_bytes(int file, uint8_t *data, size_t len) {
    int ret;
    for (size_t i = 0; i < len; ++i) {
        ret = read(file, &data[i], 1);
        if (ret != 1) {
            perror("I2C read");
            exit(EXIT_FAILURE);
        }
    }
    return ret;
}

static void i2c_init(void) {
    int file;
    if ((file = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire bus access");
        exit(EXIT_FAILURE);
    }
}

static void log_data(const char *tag, const uint8_t *data) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    struct timeval tv;
    gettimeofday(&tv, NULL);
    fprintf(file, "%lu,%s,%02X,%02X,%02X,%02X,%02X,%02X\n",
            tv.tv_sec * 1000 + tv.tv_usec / 1000, tag, data[0], data[1],
            data[2], data[3], data[4], data[5]);
    fclose(file);
}

static void sensor_error_handler(void) {
    log_data("ERROR", NULL);
    sleep(5);
    i2c_init();
}

static void sigint_handler(int signum) {
    printf("\nShutting down...\n");
    gpiod_chip_release_lines(gpiod_chip_get_by_label("gpiochip0"));
    remove(LOG_FILE);
    close(i2c_file);
    exit(EXIT_SUCCESS);
}

int main(void) {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    struct gpiod_line *gpio_led = gpiod_get_line_byname(gpiod_chip_get_by_label("gpiochip0"), "gpio18");
    if (!gpio_led) {
        perror("Failed to get GPIO line");
        exit(EXIT_FAILURE);
    }

    int ret = gpiod_line_request_line(gpio_led, GPIOD_LINE_REQUEST_DIRECTION_OUT, "sensor_led");
    if (ret < 0) {
        perror("Failed to request GPIO line");
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(gpio_led, 0);

    i2c_init();

    uint8_t data[DATA_LENGTH];
    struct timeval tv;
    gettimeofday(&tv, NULL);

    while (1) {
        i2c_write_bytes(i2c_file, &SENSOR_ID, 1);
        i2c_write_bytes(i2c_file, (const uint8_t[]) {0x01, 0x00, 0x00}, 3);
        i2c_read_bytes(i2c_file, data, DATA_LENGTH);

        if (data[0] != 0x01 || data[1] != 0xAA || data[5] != (data[0] + data[1] + data[2] + data[3] + data[4])) {
            sensor_error_handler();
            continue;
        }

        int16_t pressure = (data[2] << 8) | data[3];
        pressure = (pressure * 256 + 128) / 257;
        float temperature = (data[4] * 256 + data[5]) / 256f * 125 - 40;

        printf("Pressure: %.2f Pa, Temperature: %.1f °C\n", pressure, temperature);
        log_data("DATA", data);

        gettimeofday(&tv, NULL);
        gpiod_line_set_value(gpio_led, !gpio_led->value);
        sleep(DELAY_MS / 1000.0);
    }

    gpiod_line_release(gpio_led);
    close(i2c_file);
    return 0;
}

