#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <gpiod.h>
#include <spidev.h>

#define SPI_DEVICE_0 "/dev/spidev0.0"
#define MCP3008_CS 8
#define SAMPLE_RATE 8000
#define CHANNELS 2
#define GAIN 1.0 // Command-line argument for gain control

int main(int argc, char *argv[]) {
    if (argc != 3) {
        printf("Usage: %s <gain> <samples>\n", argv[0]);
        return 1;
    }

    double gain = atof(argv[1]);
    int samples = atoi(argv[2]);

    int spi_fd = open(SPI_DEVICE_0, O_RDWR);
    if (spi_fd < 0) {
        perror("Cannot open SPI device");
        return 1;
    }

    struct spi_ioc_transfer transfers[2];
    memset(transfers, 0, sizeof(transfers));

    // Configure MCP3008 for 8-bit resolution, single-ended input, and SPI mode 0
    struct spi_ioc_message msg = {
        .tx_buf = (unsigned long)NULL,
        .rx_buf = (unsigned long)NULL,
        .len = 0,
        .delay_usecs = 0,
        .speed_hz = 100000,
        .bits_per_word = 8,
    };
    if (ioctl(spi_fd, SPI_IOC_WR_MODE32, &msg) < 1) {
        perror("Cannot set SPI mode");
        close(spi_fd);
        return 1;
    }

    msg.tx_buf = (unsigned long)&MCP3008_CS;
    msg.len = sizeof(MCP3008_CS);
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &msg) < 1) {
        perror("Cannot set chip select");
        close(spi_fd);
        return 1;
    }

    transfers[0].tx_buf = (unsigned long)&(0x00 | (MCP3008_CS << 24));
    transfers[0].len = sizeof(unsigned int);
    transfers[0].speed_hz = msg.speed_hz;
    transfers[0].bits_per_word = msg.bits_per_word;

    transfers[1].rx_buf = malloc(2 * samples * sizeof(unsigned int));
    if (!transfers[1].rx_buf) {
        perror("Cannot allocate buffer");
        close(spi_fd);
        return 1;
    }

    for (int i = 0; i < CHANNELS; ++i) {
        transfers[i + 1].tx_buf = (unsigned long)&(0x4000 | (i << 24));
        transfers[i + 1].len = sizeof(unsigned int);
    }

    int xfer_count = 0;
    while (xfer_count < samples) {
        xfer_count += ioctl(spi_fd, SPI_IOC_MESSAGE(2 + CHANNELS), transfers);
        if (xfer_count < samples) {
            perror("SPI transfer error");
            free(transfers[1].rx_buf);
            close(spi_fd);
