```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <gpiod.h>
#include <spidev.h>

#define MCP3008_SPI_BUS 0
#define MCP3008_SPI_CS 0
#define VH400_GPIO_CH 17

static const char *const gpio_label = "VH400_CS";
static const char *const spi_device_name = "/dev/spidev0.0";

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct spi_device *spi;
    struct spidev *spidev;
    char filename[] = "moisture_log.txt";
    int fd_spi, adc_value;
    int ret;
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[32];

    // Initialize GPIO
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    line = gpiod_chip_get_line(chip, gpio_label);
    if (!line) {
        perror("Failed to get line");
        gpiod_chip_close(chip);
        return 1;
    }

    gpiod_line_request_output_high(line, GPIOD_LINE_REQUEST_ACTIVE_HIGH);
    gpiod_line_set_value(line, 1);

    // Initialize SPI
    spidev = spidev_open(MCP3008_SPI_BUS, MCP3008_SPI_CS, 0);
    if (spidev == NULL) {
        perror("Failed to open SPI device");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open the SPI device
    spi = spidev_to_spi(spidev);
    fd_spi = spi_open(spi->dev.path, O_RDWR, 0);
    if (fd_spi < 0) {
        perror("Failed to open SPI device");
        spidev_close(spidev);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    while (1) {
        // Set the CS line low to select the MCP3008
        gpiod_line_set_value(line, 0);

        // Send the SPI command for reading the ADC value
        ret = spi_write_read(fd_spi, 0x00, &adc_value, 2);
        if (ret < 0) {
            perror("Failed to read ADC value");
            spi_close(fd_spi);
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return 1;
        }

        // Set the CS line high to deselect the MCP3008
        gpiod_line_set_value(line, 1);

        // Check if the reading is within the valid ADC range
        if (adc_value < 0 || adc_value > 1023) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            continue;
        }

        // Get the current time
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(time_str, sizeof(time_str), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

        // Append the measurement to the log file
        FILE *file = fopen(filename, "a");
        if (file == NULL) {
            perror("Failed to open log file");
            spi_close(fd_spi);
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return 1;
        }

        fprintf(file, "%s,%d\n", time_str, adc_value);
        fclose(file);
    }

    // On SIGINT or SIGTERM, cleanly release resources
    signal(SIGINT, [](int signum) {
        spi_close(fd_spi);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(0);
    });

    signal(SIGTERM, [](int signum) {
        spi_close(fd_spi);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(0);
    });

    return 0;
}
```

