int init_spi() {
    spi = mraa_spi_init(ADC_MOSI_PIN, ADC_MISO_PIN, ADC_SCLK_PIN);
    if (!spi) {
        return -1;
    }

    if (mraa_spi_frequency(spi, 1000000) != MRAA_SUCCESS) {
        return -1;
    }

    cs = mraa_gpio_init(ADC_CS_PIN);
    if (!cs) {
        return -1;
    }

    return MRAA_SUCCESS;
}

float adc_read() {
    int data[3];
    mraa_spi_write_then_read(spi, &cs->addr, &ADC_CS_PIN, 4, data, 3);
    int adc_value = (data[1] << 8) | data[2];
    float vref = 3.3f;
    float scale = 3.3f / (1 << 10);
    return adc_value * scale;
}

float flow_to_lpm(float adc_value) {
    // Replace this formula with the correct one for your specific sensor
    return adc_value * 0.001f;
}

void log_flow_reading(float flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_str, sizeof(time_str), "%Y-%m-%dT%H:%M:%S", timeinfo);
    FILE *file = fopen(FILENAME, "a");

    if (!file) {
        die("fopen");
    }

    if (fprintf(file, "%s,%f\n", time_str, flow_rate) < 0) {
        die("fprintf");
    }

    fclose(file);
}

int main() {
    if (init_spi() != MRAA_SUCCESS) {
        die("init_spi");
    }

    float last_flow_rate = 0.0f;
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    long last_timestamp = ts.tv_sec * 1000 + ts.tv_nsec / 1000000;

    for (;;) {
        float adc_value = adc_read();
        float flow_rate = flow_to_lpm(adc_value);

        if (last_flow_rate == 0.0f || (ts.tv_sec - last_timestamp) >= SAMPLE_INTERVAL_MS / 1000) {
            last_flow_rate = flow_rate;
            log_flow_reading(last_flow_rate);
            last_timestamp = ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
        }

        clock_nanosleep(CLOCK_MONOTONIC, 0, &ts, NULL);
        ts.tv_nsec += 1000000000;

        if (signal_pending(SIGINT) || signal_pending(SIGTERM)) {
