#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <mraa.hpp>
#include <Adafruit_MCP3008.h>

#define SPI_BUS 0
#define SPI_CS 0
#define ADC_CHANNEL 0
#define CAL_MIN 100
#define CAL_MAX 900
#define MOISTURE_THRESHOLD 30
#define LOG_INTERVAL 60
#define MSMTP_CMD "msmtp -C /path/to/msmtp.rc"

static gpiod_line_request_lines_t *moisture_sensor_request;
static Adafruit_MCP3008 adc;
static int spi_fd;
static FILE *log_file;
static char email_address[256];

void die(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

void log_moisture(int moisture) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    fprintf(log_file, "%s, %d\n", timestamp, moisture);
    fflush(log_file);
}

void send_email(const char *body) {
    pid_t pid = fork();
    if (pid == -1) {
        die("fork");
    } else if (pid > 0) {
        waitpid(pid, NULL, 0);
    } else {
        char cmd[strlen(MSMTP_CMD) + strlen(email_address) + strlen(body) + 2];
        snprintf(cmd, sizeof(cmd), "%s %s < %s", MSMTP_CMD, email_address, body);
        execlp("sh", "sh", "-c", cmd, NULL);
        die("execlp");
    }
}

int read_moisture() {
    int adc_value = adc.read(SPI_BUS, ADC_CHANNEL);
    if (adc_value == -1) {
        fprintf(stderr, "Failed to read ADC value\n");
        return -1;
    }

    int moisture = (adc_value - CAL_MIN) * 100 / (CAL_MAX - CAL_MIN);
    return moisture;
}

int main(int argc, char *argv[]) {
    if (argc < 7) {
        fprintf(stderr, "Usage: %s <SPI bus> <ADC channel> <calibration min> <calibration max> <threshold> <interval> <email address> <msmtp config file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int spi_bus = atoi(argv[1]);
    int adc_channel = atoi(argv[2]);
    int cal_min = atoi(argv[3]);
    int cal_max = atoi(argv[4]);
    int threshold = atoi(argv[5]);
    int interval = atoi(argv[6]);
    strcpy(email_address, argv[7]);

    if (interval <= 0) {
        fprintf(stderr, "Invalid logging interval\n");
        return EXIT_FAILURE;
    }

    if (cal_min >= cal_max) {
        fprintf(stderr, "Invalid calibration values (min >= max)\n");
        return EXIT_FAILURE;
    }

    if (threshold < 0 || threshold > 100) {
        fprintf(stderr, "Invalid moisture threshold (0 <= threshold <= 100)\n");
        return EXIT_FAILURE;
    }

    if (gpiod_library_open() < 0) {
        die("gpiod_library_open");
    }

    moisture_sensor_request = gpiod_chip_get_line_request_byname(gpiod_chip_get_bylabel("gpiochip0"), "GPIO0");
    if (!moisture_sensor_request) {
        die("Failed to get moisture sensor GPIO line request");
    }

    if (gpiod_line_request_enable(moisture_sensor_request, GPIOD_LINE_REQUEST_DIRECTION_IN, GPIOD_LINE_STATE_HIGH) < 0) {
        die("gpiod_line_request_enable");
    }

    if ((spi_fd = open("/dev/spidev" + to_string(spi_bus), O_RDWR)) < 0) {
        die("open");
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE_0) != 0) {
        die("ioctl(SPI_IOC_WR_MODE)");
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &8) != 0) {
        die("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &500000) != 0) {
        die("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
    }

    adc.begin(spi_fd, SPI_CS);

    log_file = fopen("plant_data.txt", "a");
    if (!log_file) {
        die("fopen");
    }

    while (true) {
        int moisture = read_moisture();
        if (moisture < 0) {
            continue;
        }

        if (moisture < threshold) {
            char body[256];
            snprintf(body, sizeof(body), "Soil moisture is critically low: %d%%\n", moisture);
            send_email(body);
        }

        log_moisture(moisture);
        sleep(interval);
    }

    adc.end();
    close(spi_fd);
    gpiod_line_request_release(moisture_sensor_request);
    gpiod_library_close();
    fclose(log_file);

    return EXIT_SUCCESS;
}
