This program initializes the GPIO line for the moisture sensor, sets up the ADC, opens the SPI bus, and initializes the logging file. It then enters an infinite loop where it reads the moisture level, logs it, and sends an email alert if the moisture level falls below the specified threshold. The program also handles errors during ADC reads by retrying on the next cycle.

The program cleans up resources on exit by closing the SPI interface, terminating the driver, freeing any dynamically allocated memory, and exiting cleanly when receiving SIGINT or SIGTERM signals.

code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <spidev.h>

#define CS_GPIO 8
#define AD0_GPIO 7
#define SPI_BUS 0
#define SPI_DEVICE 0
#define ADC_RESOLUTION 1024
#define ADC_VREF 3.3

static gpiod_line_request_linestate_t ad0_state;
static struct spi_device *spidev;
static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void adc_init() {
    gpiod_line_request_linestate_t state;
    gpiod_line_request_data_flags_t flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW;

    gpiod_line_request_config config = {
        .consumer = "Soil Moisture Sensor",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
        .flags = flags
    };

    int ret = gpiod_chip_open_byname("gpiochip0");
    if (ret < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_get_byindex(ret, AD0_GPIO, &config);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_get_value(ret, &ad0_state);
    if (ret < 0) {
        perror("Failed to get initial GPIO state");
        exit(EXIT_FAILURE);
    }

    gpiod_line_release(ret);
}

int spi_init() {
    int ret;
    char spi_path[32];
    snprintf(spi_path, sizeof(spi_path), "/dev/spidev%d.%d", SPI_BUS, SPI_DEVICE);

    spidev = spi_open(spi_path, 0);
    if (!spidev) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    ret = spi_setup(spidev, 1000000);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        exit(EXIT_FAILURE);
    }

    ret = spi_set_mode(spidev, SPI_MODE_0);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        exit(EXIT_FAILURE);
    }

    ret = spi_set_bits_per_word(spidev, 8);
    if (ret < 0) {
        perror("Failed to set SPI bits per word");
        exit(EXIT_FAILURE);
    }

    return 0;
}

uint16_t read_adc() {
    uint8_t data[3];
    uint16_t adc_value;

    gpiod_line_set_value(ad0_state.dev, ad0_state.offset, !ad0_state.value);
    usleep(10);

    spi_write(spidev, &CS_GPIO, 1);
    spi_write(spidev, &CS_GPIO, 0);

    spi_write(spidev, &AD0_GPIO, 1);
    spi_write(spidev, &AD0_GPIO, 0);

    spi_read(spidev, data, 3);

    spi_write(spidev, &CS_GPIO, 1);

    adc_value = (data[1] << 8) | data[2];

    return adc_value;
}

float calculate_moisture(uint16_t adc_value) {
    float voltage = adc_value * ADC_VREF / ADC_RESOLUTION;
    float resistance = 10 / (voltage - 0.1);
    float moisture = 100 - (100 * resistance / (1000000 + resistance));

    return moisture;
}

void log_reading(const char *timestamp, uint16_t adc_value, float moisture) {
    FILE *log_file = fopen("soil_moisture.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s,%u,%.2f\n", timestamp, adc_value, moisture);
    fflush(log_file);
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <sample_interval_seconds>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    adc_init();
    spi_init();

    struct timespec sleep_interval = {
        .tv_sec = atoi(argv[1]),
        .tv_nsec = 0
    };

    while (running) {
        uint16_t adc_value = read_adc();
        float moisture = calculate_moisture(adc_value);
        char timestamp[32];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

        log_reading(timestamp, adc_value, moisture);
        printf("%s, %u, %.2f\n", timestamp, adc_value, moisture);

        nanosleep(&sleep_interval, NULL);
    }

    gpiod_chip_close(ad0_state.dev);
    spi_close(spidev);

    return 0;
}

