Here's the C code:

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <time.h>
#include <errno.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define MCP3008_CS_GPIO 8
#define MCP3008_SPI_BUS 0
#define MCP3008_SPI_DEVICE 0
#define MLX90823_VREF 3.3
#define MLX90823_ADC_MAX 1023
#define MLX90823_ADC_MIN 0

static gpiod_line_request_lines_data_t cs_request_data = { .flags = GPIOD_LINE_REQUEST_INPUT };
static gpiod_line_data_t cs_line_data;
static int spi_fd;

int init_gpio(void) {
    gpiod_line_request_err_t err;
    struct gpiod_chip *chip;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return -1;
    }

    err = gpiod_chip_request_line(chip, MCP3008_CS_GPIO, "MCP3008_CS", &cs_request_data, &cs_line_data);
    if (err) {
        perror("Failed to request MCP3008_CS GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_set_value(cs_line_data, 0);

    return 0;
}

int init_spi(void) {
    spi_fd = open("/dev/spidev" MCP3008_SPI_BUS, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(spi_fd, SPI_OPEN, MCP3008_SPI_DEVICE) < 0) {
        perror("Failed to open SPI device");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_CPOL, 0) < 0) {
        perror("Failed to set SPI mode 0");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_CPHA, 0) < 0) {
        perror("Failed to set SPI mode 0");
        close(spi_fd);
        return -1;
    }

    return 0;
}

uint16_t read_adc(void) {
    uint8_t buf[3];
    ssize_t len;
    uint16_t adc_value;

    gpiod_line_set_value(cs_line_data, 1);
    usleep(10);

    len = write(spi_fd, "\x00", 1);
    if (len != 1) {
        perror("Failed to write to SPI device");
        return 0;
    }

    len = read(spi_fd, buf, 3);
    if (len != 3) {
        perror("Failed to read from SPI device");
        return 0;
    }

    gpiod_line_set_value(cs_line_data, 0);

    adc_value = (buf[1] << 8) | buf[2];

    return adc_value;
}

float convert_adc_to_pressure(uint16_t adc_value) {
    float pressure;

    adc_value -= MLX90823_ADC_MIN;
    pressure = (adc_value * MLX90823_VREF) / MLX90823_ADC_MAX;

    return pressure;
}

void log_pressure(const char *timestamp, float pressure) {
    printf("%s: Pressure: %.2f Pa\n", timestamp, pressure);
}

void handle_signal(int sig) {
    printf("Received signal %d, exiting...\n", sig);

    close(spi_fd);
    gpiod_chip_release_line(cs_line_data.chip, cs_line_data.number);
    gpiod_chip_close(cs_line_data.chip);

    exit(0);
}

int main(void) {
    char timestamp[32];
    uint16_t adc_value;
    float pressure;
    struct timespec ts;

    if (init_gpio() < 0) {
        return 1;
    }

    if (init_spi() < 0) {
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);
        snprintf(timestamp, sizeof(timestamp), "%ld-%.6d-%.6dT%.6dZ",
                 ts.tv_sec, ts.tv_nsec / 1000000, (ts.tv_nsec % 1000000) / 1000, (ts.tv_sec % 60) * 1000 + (ts.tv_nsec / 1000000));

        adc_value = read_adc();
        if (adc_value == 0 || adc_value == MLX90823_ADC_MAX) {
            printf("Sensor absent, voltage is either 0V or 3.3V\n");
            continue;
        }

        pressure = convert_adc_to_pressure(adc_value);
        log_pressure(timestamp, pressure);

        sleep(1);
    }

    return 0;
}
```

This code reads the pressure from the MLX90823 sensor every second and logs the readings with an ISO-8601 timestamp. It also handles errors, SIGINT, and SIGTERM signals, and releases all resources on exit.

