#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>
#include <spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_LINE_CE "gpiochip0"
#define GPIO_CE_LINE 8

struct spi_ioc_transfer spi_transfers[] = {
    {
        .tx_buf      = (unsigned char*) &adc_value,
        .rx_buf      = (unsigned char*) &adc_value,
        .len         = 2,
        .delay_usecs = 10,
        .speed_hz    = 1000000,
        .bits_per_word = 8,
    },
};

int main() {
    int spi_fd, gpio_fd, ret;
    struct gpiod_line *gpio_line;
    struct timespec ts;
    unsigned int adc_value;

    // Open the SPI device
    if ((spi_fd = open(SPI_DEVICE, O_RDWR)) < 0) {
        perror("Can't open SPI device");
        exit(EXIT_FAILURE);
    }

    // Set the SPI mode, data size, and clock speed
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) != 0) {
        perror("Can't set SPI mode");
        exit(EXIT_FAILURE);
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) != 0) {
        perror("Can't set SPI data size");
        exit(EXIT_FAILURE);
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) != 0) {
        perror("Can't set SPI speed");
        exit(EXIT_FAILURE);
    }

    // Request the GPIO line
    if ((gpio_fd = gpiod_open(gpio_line, GPIO_CE_LINE)) < 0) {
        perror("Can't open GPIO line");
        exit(EXIT_FAILURE);
    }

    gpio_line = gpiod_get_line(gpio_fd, GPIOD_ASIS);

    // Main loop
    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);
        printf("%ld.%09ld: Reading ADC value...\n", ts.tv_sec, ts.tv_nsec);

        // Set the GPIO line to output
        gpiod_direction_output(gpio_line, 1);

        // Send the SPI command to read the ADC value
        ret = spi_xfer(spi_fd, spi_transfers, sizeof(spi_transfers) / sizeof(struct spi_ioc_transfer));
        if (ret != sizeof(spi_transfers)) {
            perror("Error during SPI transfer");
            exit(EXIT_FAILURE);
        }

        // Check if the ADC value is out of range
        if (adc_value == 0 || adc_value == 1023) {
            printf("ADC value out of range, possibly a sensor or wiring fault\n");
        } else {
            printf("ADC value: %d\n", adc_value);
        }

        // Set the GPIO line to input
        gpiod_direction_input(gpio_line);

        sleep(5);
    }

    // Clean up
    gpiod_put_line(gpio_line);
    close(gpio_fd);
    close(spi_fd);

    // Handle SIGINT and SIGTERM
    while (1) {
        sigset_t set;
        sigemptyset(&set);
        sigaddset(&set, SIGINT);
        sigaddset(&set, SIGTERM);
        sigsuspend(&set);
    }

    return 0;
}

