    struct spi_device_interface spi_interface = {
        .mode = SPI_MODE_0,
        .max_speed_hz = SPI_SPEED_HZ,
        .bits_per_word = 8,
        .chip_select = CHIP_SELECT,
    };

    if (ioctl(spifd, SPI_IOC_WRITE_INTERFACE, &spi_interface) < 1) {
        perror("Can't set SPI mode");
        close(spifd);
        return 1;
    }

    // Map the SPI buffer
    spibuf = mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_SHARED, spifd, 0);
    if (spibuf == MAP_FAILED) {
        perror("Can't mmap");
        close(spifd);
        return 1;
    }

    // Set up the SPI transfer
    transfers[0].tx_buf = &ADDR;
    transfers[0].rx_buf = &spibuf[0];
    transfers[0].len = 1;
    transfers[0].delay_usecs = 0;

    transfers[1].tx_buf = &COMMAND;
    transfers[1].rx_buf = &spibuf[1];
    transfers[1].len = 1;
    transfers[1].delay_usecs = 0;

    transfers[2].tx_buf = &DUMMY;
    transfers[2].rx_buf = &spibuf[2];
    transfers[2].len = 1;
    transfers[2].delay_usecs = 0;

    // Perform the SPI transfer
    ret = ioctl(spifd, SPI_IOC_MESSAGE(1), transfers);
    if (ret < 1) {
        perror("Can't perform SPI transfer");
        munmap(spibuf, 4096);
        close(spifd);
        return 1;
    }

    // Compute the moisture percentage
    int moisture = (spibuf[1] & 0x00FF) * 3.3 / 1023 * 100;
    if (moisture < 0) moisture = 0;
    if (moisture > 100) moisture = 100;

    printf("Soil moisture: %d%%\n", moisture);

    // Clean up and exit
    munmap(spibuf, 4096);
    close(spifd);

    // Log the moisture every 5 seconds
    while (1) {
        sleep(5);
        moisture = (spibuf[1] & 0x00FF) * 3.3 / 1023 * 100;
        if (moisture < 0) moisture = 0;
        if (moisture > 100) moisture = 100;
        printf("Soil moisture: %d%%\n", moisture);

        // Handle SIGINT and SIGTERM
        if (signal(SIGINT, SIG_IGN) == SIG_ERR || signal(SIGTERM, SIG_IGN) == SIG_ERR) {
            perror("Can't ignore signals");
            return 1;
        }
    }

    return 0;
}
