    gpiod_line_get_value(line);
    if (gpiod_line_get_value(line) != 0) {
        fprintf(stderr, "CS GPIO is not active low\n");
        exit(EXIT_FAILURE);
    }

    uint8_t tx_buf[2] = {0, 0};
    uint8_t rx_buf[6];

