    spidev->max_speed_hz = speed;

    spidev->chip_select = MCP3008_CS_GPIO;
    spi_xcv(spi_fd, &buf[0], 1, &buf[1], 3);

    int moisture = (buf[1] << 8) | buf[2];
    return moisture;
