    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_gpio(MCP3008_CS_GPIO) < 0 ||
        init_gpio(MCP3008_MOSI_GPIO) < 0 ||
        init_gpio(MCP3008_MISO_GPIO) < 0 ||
        init_gpio(MCP3008_SCLK_GPIO) < 0 ||
        init_spi() < 0) {
