            last_pump_state = 0;
        }

        printf("\nBuffer:\n");
        for (int i = buffer_tail; i != buffer_head; i = (i + 1) % BUFFER_SIZE) {
            printf("%ld: Moisture=%d, Pump=%d\n", buffer[i].timestamp, buffer[i].moisture, buffer[i].pump_state);
        }

        clock_gettime(CLOCK_MONOTONIC, &ts);
        ts.tv_sec += SAMPLE_INTERVAL / 1000000;
        ts.tv_nsec = (SAMPLE_INTERVAL % 1000000) * 1000;
        nanosleep(&ts, NULL);
    }

    return 0;
}

