Here's the C code:

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/time.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define MAX30102_ADDR 0x57
#define ID_REG 0x0A
#define ADC_RESOLUTION 2048
#define SAMPLES_PER_MEASUREMENT 4
#define HEART_RATE_MIN_SAMPLES 10
#define HEART_RATE_SAMPLE_INTERVAL_MS 1000
#define SPO2_MIN_SAMPLES 30
#define SPO2_SAMPLE_INTERVAL_MS 1000

static gpiod_line_request_linestate_t gpio_state;
static gpiod_line_request_data_direction_t gpio_direction;
static gpiod_line_request_data_flags_t gpio_flags;
static gpiod_line_request *gpio_request;
static int i2c_fd;

void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_string[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(stderr, "%s: %s\n", time_string, message);
}

int init_gpio(const char *gpio_pin) {
    int ret;
    gpiod_line_request_config config = GPIOD_LINE_REQUEST_CONFIG_DIRECTION_IN |
                                       GPIOD_LINE_REQUEST_CONFIG_EDGE_RISING |
                                       GPIOD_LINE_REQUEST_CONFIG_ACTIVE_LOW;

    gpio_request = gpiod_chip_get_line_request_byname(gpiod_chip_get_bylabel("gpiochip0"), gpio_pin);
    if (!gpio_request) {
        log_error("Failed to get GPIO line request");
        return -1;
    }

    ret = gpiod_line_request_get_lines(gpio_request, 1, &gpio_state);
    if (ret < 0) {
        log_error("Failed to get GPIO line state");
        goto cleanup;
    }

    ret = gpiod_line_request_get_direction(gpio_request, &gpio_direction);
    if (ret < 0) {
        log_error("Failed to get GPIO direction");
        goto cleanup;
    }

    ret = gpiod_line_request_get_flags(gpio_request, &gpio_flags);
    if (ret < 0) {
        log_error("Failed to get GPIO flags");
        goto cleanup;
    }

    ret = gpiod_line_request_set_config(gpio_request, &config);
    if (ret < 0) {
        log_error("Failed to set GPIO configuration");
        goto cleanup;
    }

    ret = gpiod_line_request_enable(gpio_request);
    if (ret < 0) {
        log_error("Failed to enable GPIO request");
        goto cleanup;
    }

    return 0;

cleanup:
    gpiod_line_request_release(gpio_request);
    return -1;
}

int init_i2c() {
    int ret;

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, MAX30102_ADDR << 1);
    if (ret < 0) {
        log_error("Failed to set I2C slave address");
        goto cleanup;
    }

    return 0;

cleanup:
    close(i2c_fd);
    return -1;
}

uint16_t read_part_id() {
    uint8_t data[2];
    int ret;

    ret = i2c_smbus_read_i2c_block_data(i2c_fd, ID_REG, 2, data);
    if (ret != 2) {
        log_error("Failed to read ID register");
        return 0;
    }

    return (data[0] << 8) | data[1];
}

void write_register(uint8_t reg, uint8_t value) {
    uint8_t data[] = {reg, value};
    int ret;

    ret = i2c_smbus_write_i2c_block_data(i2c_fd, reg, 2, data);
    if (ret != 2) {
        log_error("Failed to write to register");
    }
}

void read_samples(uint16_t *samples, size_t count) {
    uint8_t data[2 * SAMPLES_PER_MEASUREMENT];
    int ret;

    write_register(0x01, 0x01); // Start measurement
    usleep(SPO2_SAMPLE_INTERVAL_MS * 1000);

    ret = i2c_smbus_read_i2c_block_data(i2c_fd, 0x03, 2 * SAMPLES_PER_MEASUREMENT, data);
    if (ret != 2 * SAMPLES_PER_MEASUREMENT) {
        log_error("Failed to read samples");
        return;
    }

    for (size_t i = 0; i < count; ++i) {
        samples[i] = (data[2 * i] << 8) | data[2 * i + 1];
    }
}

float calculate_heart_rate(const uint16_t *samples, size_t count) {
    uint64_t time_diff = 0;
    uint64_t time_sum = 0;
    uint64_t ir_sum = 0;
    uint64_t red_sum = 0;
    size_t index = 0;

    for (size_t i = 0; i < count - HEART_RATE_MIN_SAMPLES; ++i) {
        time_diff += (samples[i + HEART_RATE_MIN_SAMPLES] - samples[i]) * 1000;
        time_sum += time_diff;
        ir_sum += samples[i + HEART_RATE_MIN_SAMPLES] & 0xFFF;
        red_sum += (samples[i + HEART_RATE_MIN_SAMPLES] >> 12) & 0xFFF;
        index = i + HEART_RATE_MIN_SAMPLES;
    }

    float heart_rate = 60.0 * (65536 * ir_sum - red_sum) / (time_sum * ADC_RESOLUTION);

    if (heart_rate > 100.0) {
        log_error("Heart rate is too high");
        heart_rate = 0.0;
    }

    return heart_rate;
}

float calculate_spo2(const uint16_t *samples, size_t count) {
    uint64_t ir_sum = 0;
    uint64_t red_sum = 0;
    size_t index = 0;

    for (size_t i = 0; i < count - SPO2_MIN_SAMPLES; ++i) {
        ir_sum += samples[i + SPO2_MIN_SAMPLES] & 0xFFF;
        red_sum += (samples[i + SPO2_MIN_SAMPLES] >> 12) & 0xFFF;
        index = i + SPO2_MIN_SAMPLES;
    }

    float spo2 = 100.0 * (65536 * ir_sum - red_sum) / (count * ADC_RESOLUTION * 255);

    if (spo2 < 95.0) {
        log_error("SpO₂ is too low");
        spo2 = 0.0;
    }

    return spo2;
}

int main() {
    int ret;
    uint16_t samples[SAMPLES_PER_MEASUREMENT];
    FILE *log_file;
    char log_filename[] = "health_log.txt";
    time_t rawtime;
    struct tm *timeinfo;
    char time_string[80];

    if (init_gpio("gpio0") < 0) {
        return 1;
    }

    if (init_i2c() < 0) {
        goto cleanup_gpio;
    }

    if (read_part_id() != 0x0F30) {
        log_error("Invalid MAX30102 part ID");
        goto cleanup_i2c;
    }

    log_file = fopen(log_filename, "w");
    if (!log_file) {
        log_error("Failed to open log file");
        goto cleanup_i2c;
    }

    while (1) {
        read_samples(samples, SAMPLES_PER_MEASUREMENT);

        float heart_rate = calculate_heart_rate(samples, SAMPLES_PER_MEASUREMENT);
        float spo2 = calculate_spo2(samples, SAMPLES_PER_MEASUREMENT);

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", timeinfo);

        if (heart_rate > 100.0 || spo2 < 95.0) {
            fprintf(log_file, "%s: Heart rate: %.2f SpO₂: %.2f\n", time_string, heart_rate, spo2);
        }

        usleep(HEART_RATE_SAMPLE_INTERVAL_MS * 1000);
    }

cleanup_i2c:
    close(i2c_fd);
cleanup_gpio:
    gpiod_line_request_release(gpio_request);

    return 0;
}
