```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define ADC_CS_GPIO 8
#define BUZZER_GPIO 24
#define THRESHOLD 500
#define SAMPLE_INTERVAL 500000

int main() {
    int adc_fd, spi_fd;
    struct spi_ioc_transfer transfer[1];
    gpiod_line_request_lines_data_v2_devdata lines_data = {0};
    gpiod_line_request_lines_data_v2 lines_data_v2 = {0};
    gpiod_line_request_data request_data = {0};
    gpiod_line_state state = GPIOD_LINE_STATE_LOW;
    int ret;

    // Initialize GPIO
    gpiod_line_request_init_v2(&lines_data_v2, 1);
    lines_data_v2.request_flags = GPIOD_LINE_REQUEST_DIRECTION_OUT |
                                   GPIOD_LINE_REQUEST_ACTIVE_LOW;
    lines_data_v2.lines[0].number = ADC_CS_GPIO;
    lines_data_v2.lines[0].flags = GPIOD_LINE_FLAG_INPUT;

    gpiod_line_request_init_v2(&request_data, 1);
    request_data.lines[0].number = BUZZER_GPIO;
    request_data.lines[0].flags = GPIOD_LINE_FLAG_OUTPUT;

    gpiod_line_request_set_request_data(gpiod_chip_get_request_manager(
        gpiod_chip_open_by_name("gpiochip0")), &request_data);
    gpiod_line_request_set_request_data(gpiod_chip_get_request_manager(
        gpiod_chip_open_by_name("gpiochip0")), &lines_data_v2);

    // Open ADC and SPI
    if ((adc_fd = open("/dev/mem", O_RDWR | O_SYNC)) < 0) {
        perror("Failed to open /dev/mem");
        exit(EXIT_FAILURE);
    }

    if ((spi_fd = open(SPI_DEV, O_RDWR)) < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    // Map the ADC register
    void *map_base = mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_SHARED, adc_fd, 0x20000000);
    if (map_base == MAP_FAILED) {
        perror("Failed to map ADC register");
        exit(EXIT_FAILURE);
    }

    // Configure SPI
    transfer[0].tx_buf = (unsigned char*)&(SPI_MODE);
    transfer[0].len = sizeof(SPI_MODE);
    transfer[0].speed_hz = SPI_SPEED;
    ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer);
    if (ret < 1) {
        perror("Failed to configure SPI");
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Set ADC CS low
        gpiod_line_set_value_by_index(gpiod_chip_get_line_by_number(
            gpiod_chip_get_line_request_data(
                gpiod_chip_get_request_manager(
                    gpiod_chip_open_by_name("gpiochip0")),
                ADC_CS_GPIO), 0), state);

        // Read ADC value
        unsigned int adc_value = *(unsigned int*)(map_base + 0x0000);
        gpiod_line_set_value_by_index(gpiod_chip_get_line_by_number(
            gpiod_chip_get_line_request_data(
                gpiod_chip_get_request_manager(
                    gpiod_chip_open_by_name("gpiochip0")),
                ADC_CS_GPIO), 0), state);

        // Set buzzer state
        if (adc_value >= THRESHOLD) {
            state = GPIOD_LINE_STATE_HIGH;
        } else {
            state = GPIOD_LINE_STATE_LOW;
        }
        gpiod_line_set_value_by_index(gpiod_chip_get_line_by_number(
            gpiod_chip_get_line_request_data(
                gpiod_chip_get_request_manager(
                    gpiod_chip_open_by_name("gpiochip0")),
                BUZZER_GPIO), 0), state);

        usleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    munmap(map_base, 4096);
    close(adc_fd);
    close(spi_fd);
    gpiod_chip_close(gpiod_chip_open_by_name("gpiochip0"));

    // Handle SIGINT
    signal(SIGINT, [](int sig) {
        gpiod_line_request_cancel(gpiod_chip_get_request_manager(
            gpiod_chip_open_by_name("gpiochip0")));
        exit(EXIT_SUCCESS);
    });

    return 0;
}
```

