#include <linux/i2c-dev.h>
#include <sys/time.h>
#include <signal.h>
#include <pthread.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define GP2Y0A21YK0F_ADC_CHANNEL 0
#define RELAY_GPIO 17
#define REED_SENSOR_GPIO 27
#define LOG_FILE "/var/log/door_events.log"
#define CALIBRATION_SAMPLES 10
#define SAMPLE_INTERVAL_MS 50
#define SAMPLE_PERIOD_MS 200
#define THRESHOLD_DISTANCE_MM 100
#define RELAY_ON_MS 3000
#define REED_SENSOR_DEBOUNCE_MS 10

int i2c_fd;
int relay_gpio;
int reed_sensor_gpio;
struct timeval start_time, end_time;
long long calibration_samples[CALIBRATION_SAMPLES];
long long baseline_average;
long long current_sample;
int reed_sensor_state;

void i2c_init() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to acquire I2C slave address");
        exit(EXIT_FAILURE);
    }
}

void gpio_init() {
    if (gpio_tlv320aic3106_setup() < 0) {
        perror("Failed to setup GPIO");
        exit(EXIT_FAILURE);
    }

    relay_gpio = gpio_to_line(RELAY_GPIO);
    reed_sensor_gpio = gpio_to_line(REED_SENSOR_GPIO);

    gpio_set_direction(relay_gpio, GPIO_OUT);
    gpio_set_direction(reed_sensor_gpio, GPIO_IN);
    gpio_set_pull_up(reed_sensor_gpio, 1);
}

void log_event(const char *event) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    struct timeval current_time;
    gettimeofday(&current_time, NULL);
    char timestamp[30];
    snprintf(timestamp, sizeof(timestamp), "%ld.%06ld: ", current_time.tv_sec, current_time.tv_usec);
    fprintf(log_file, "%s%s\n", timestamp, event);
    fclose(log_file);
}

void i2c_read_adc() {
    char buffer[2];
    buffer[0] = 0x00;
    buffer[1] = (GP2Y0A21YK0F_ADC_CHANNEL << 6) | 0x01;

    if (write(i2c_fd, buffer, 2) != 2) {
        perror("Failed to write to I2C device");
        return;
    }

    if (read(i2c_fd, buffer, 2) != 2) {
        perror("Failed to read from I2C device");
        return;
    }

    current_sample = (buffer[1] << 8) | buffer[0];
}

void calibrate() {
    for (int i = 0; i < CALIBRATION_SAMPLES; ++i) {
        usleep(SAMPLE_INTERVAL_MS * 1000);
        i2c_read_adc();
        calibration_samples[i] = current_sample;
    }

    baseline_average = 0;
    for (int i = 0; i < CALIBRATION_SAMPLES; ++i) {
        baseline_average += calibration_samples[i];
    }
    baseline_average /= CALIBRATION_SAMPLES;
}

void check_door() {
    gpio_get(reed_sensor_gpio, &reed_sensor_state);

    if (reed_sensor_state == 0) {
        log_event("door opened");
    } else {
        log_event("door not opened");
    }
}

void control_relay(int state) {
    if (state) {
        gpio_write(relay_gpio, 1);
    } else {
        gpio_write(relay_gpio, 0);
    }
}

void door_opening_handler() {
    if (current_sample < baseline_average * THRESHOLD_DISTANCE_MM / 100) {
        control_relay(1);
        usleep(RELAY_ON_MS * 1000);
        control_relay(0);

        check_door();
    }
}

int main() {
    signal(SIGINT, door_opening_handler);
    signal(SIGTERM, door_opening_handler);

    i2c_init();
    gpio_init();
    calibrate();

    struct timeval last_sample_time;
    gettimeofday(&last_sample_time, NULL);

    while (1) {
        gettimeofday(&current_time, NULL);
        long long elapsed_ms = (current_time.tv_sec - last_sample_time.tv_sec) * 1000 + (current_time.tv_usec - last_sample_time.tv_usec) / 1000;

        if (elapsed_ms >= SAMPLE_PERIOD_MS) {
            i2c_read_adc();
            last_sample_time = current_time;
        }

        usleep(100000);
    }

    close(i2c_fd);
    gpio_cleanup();

    return 0;
}

