    if (reed_sensor_state == 0) {
        log_event("door opened");
    } else {
        log_event("door not opened");
    }
}

void control_relay(int state) {
    if (state) {
        gpio_write(relay_gpio, 1);
    } else {
        gpio_write(relay_gpio, 0);
    }
}

void door_opening_handler() {
    if (current_sample < baseline_average * THRESHOLD_DISTANCE_MM / 100) {
        control_relay(1);
        usleep(RELAY_ON_MS * 1000);
        control_relay(0);

        check_door();
    }
}

int main() {
    signal(SIGINT, door_opening_handler);
    signal(SIGTERM, door_opening_handler);

    i2c_init();
    gpio_init();
    calibrate();

    struct timeval last_sample_time;
    gettimeofday(&last_sample_time, NULL);

    while (1) {
        gettimeofday(&current_time, NULL);
        long long elapsed_ms = (current_time.tv_sec - last_sample_time.tv_sec) * 1000 + (current_time.tv_usec - last_sample_time.tv_usec) / 1000;

        if (elapsed_ms >= SAMPLE_PERIOD_MS) {
            i2c_read_adc();
            last_sample_time = current_time;
        }

        usleep(100000);
    }

    close(i2c_fd);
    gpio_cleanup();

    return 0;
}
```

This code initializes the I2C bus, sets up the GPIO pins for the ADC, relay, and reed sensor, and reads the ADC samples at the specified interval. It also logs events to a file and handles SIGINT and SIGTERM signals. The `door_opening_handler` function is called when the program receives a SIGINT or SIGTERM signal, and it checks the current distance reading and door sensor state before de-energizing the relay and releasing resources.

Please note that this code uses the `gpio` library, which is part of the Raspberry Pi OS. If you want to avoid using any external driver library, you'll need to implement the GPIO functions manually using sysfs.

Also, this code does not handle the case where the ADC read fails (sensor absent). You can add error handling for that by checking the return value of `i2c_read_adc()` and logging an error message when it fails.

Lastly, this code does not debounce the reed sensor. You may want to add a debouncing mechanism to ensure the door state is accurate.

