    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(spi_fd, SPI_OPEN_MODE32_CS0) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

