#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <time.h>
#include <getopt.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/spi/spidev-util.h>
#include <sys/time.h>
#include <gpiod.h>

#define SPI_DEVICE_PATH "/dev/spidev0.0"
#define GPIO_PWM_PATH "/dev/gpiod/chip/gpiochip0"
#define GPIO_PUM_PIN "pwm0"
#define ADC_CHANNEL 0
#define DEFAULT_THRESHOLD 0.3
#define DEFAULT_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60
#define MAX_RETRIES 3
#define LOG_FILE "irrigation.log"

int spi_fd, gpio_fd, retries = 0;
struct spi_ioc_transfer transfers[2];
struct gpiod_line *gpio_line;
struct timespec sleep_interval;
struct timespec pump_duration;
struct timespec current_time;

void log_timestamped(const char *message) {
    char timestamp[20];
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(stderr, "%s: %s\n", timestamp, message);
}

int read_adc(void) {
    int i;
    int bits = 8;
    int data = 0;

    for (i = 0; i < bits; i++) {
        if (retries++ > MAX_RETRIES) {
            log_timestamped("Error reading ADC data. Skipping irrigation cycle.");
            return -1;
        }

        if (spi_xfer(spi_fd, &transfers[0], 2) < 0) {
            log_timestamped("Error reading ADC data. Retrying...");
            continue;
        }

        data |= (transfers[0].rx_buf[0] & (1 << (bits - i - 1))) << i;
    }

    return data;
}

void set_pwm(int duty_cycle) {
    struct gpiod_line_request request;
    struct gpiod_line_state state;

    gpiod_line_request_configure(&request, gpio_fd, GPIO_PUM_PIN, GPIOD_LINE_REQ_DIRECTION_OUT,
                                 GPIOD_LINE_STATE_HIGH, GPIOD_LINE_FLAGS_NONE);
    gpiod_line_request_enable(&request);

    state.value = duty_cycle > 100 ? 1 : duty_cycle * 100 / 1023;
    gpiod_line_set_value(gpio_line, state);
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;
    int duration = DEFAULT_DURATION;
    int sleep_interval = DEFAULT_SLEEP_INTERVAL;
    int c;

    while ((c = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (c) {
            case 't':
                threshold = atof(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            case 's':
                sleep_interval = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t THRESHOLD] [-d DURATION] [-s SLEEP_INTERVAL]\n", argv[0]);
                exit(1);
        }
    }

    spi_fd = spidev_open(SPI_DEVICE_PATH, 0);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        exit(1);
    }

    gpio_fd = gpiod_open_chip(GPIO_PWM_PATH, 0, 0);
    if (gpio_fd < 0) {
        perror("Error opening GPIO chip");
        exit(1);
    }

    gpio_line = gpiod_chip_get_line(gpio_fd, GPIO_PUM_PIN);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        exit(1);
    }

    transfers[0].tx_buf = (unsigned char *) &ADC_CHANNEL;
    transfers[0].len = sizeof(ADC_CHANNEL);
    transfers[1].tx_buf = NULL;
    transfers[1].len = 0;
    transfers[1].speed_hz = 1000000;

    while (1) {
        float adc_value = read_adc() / 1024.0;
        if (adc_value < threshold) {
            log_timestamped("Moisture level is below threshold.");

            set_pwm(100);
            nanosleep(&pump_duration, NULL);
            set_pwm(0);

            log_timestamped("Pump activated.");
        }

        clock_gettime(CLOCK_REALTIME, &current_time);
        nanosleep(&sleep_interval, NULL);
    }

    close(spi_fd);
    gpiod_line_release(gpio_line);
    gpiod_close(gpio_fd);

    return 0;
}

