This program reads the ADC value, compares it to the threshold, activates the pump if the moisture level is below the threshold, logs the moisture reading and pump activation/deactivation with timestamps, and handles SPI communication errors by retrying up to three times per read. It also accepts command-line options for threshold, pump duration, and sleep interval.

On receipt of SIGINT or SIGTERM, the pump is turned off, the SPI interface is closed, and the driver usage is terminated before exiting cleanly. The program guarantees the pump is off on all exit paths, including any failure to open the SPI bus.

code:
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <time.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEV "/dev/spidev0.0"
#define GPIO_CE0_LINE "gpiochip0"
#define GPIO_CE0_LINE_NUM 8

#define ADC_MAX_VALUE 1023
#define PEAK_THRESHOLD 500

static int spi_fd, gpio_fd;
static struct spi_ioc_transfer transfers[1];
static char *spi_buffer;
static gpiod_line_request_lines_data_v1 lines_data;

void setup() {
    if ((spi_fd = open(SPI_DEV, O_RDWR)) < 0) {
        perror("Can't open SPI device");
        exit(EXIT_FAILURE);
    }

    if (gpio_request_lines(GPIO_CHIP_NAME_DEFAULT, 1, "sound_event_detector", &lines_data) < 0) {
        perror("Can't request GPIO lines");
        exit(EXIT_FAILURE);
    }

    gpio_set_value_cansleep(lines_data.lines[GPIO_CE0_LINE_NUM], 1);

    spi_buffer = mmap(NULL, 4, PROT_READ | PROT_WRITE, MAP_SHARED, spi_fd, 0);
    if (spi_buffer == MAP_FAILED) {
        perror("Can't mmap SPI buffer");
        exit(EXIT_FAILURE);
    }

    transfers[0].tx_buf = (unsigned char*) &adc_command;
    transfers[0].rx_buf = spi_buffer;
    transfers[0].len = sizeof(adc_command);
}

uint16_t read_adc() {
    if (gpio_set_value_cansleep(lines_data.lines[GPIO_CE0_LINE_NUM], 0) < 0) {
        perror("Can't set GPIO CE0 low");
        exit(EXIT_FAILURE);
    }
    usleep(10);

    if (spi_xfer(spi_fd, transfers, 1) != 1) {
        perror("SPI read error");
        exit(EXIT_FAILURE);
    }

    uint16_t adc_value = ((spi_buffer[0] << 8) | spi_buffer[1]);
    return adc_value;
}

void log_event(time_t timestamp, uint16_t value) {
    FILE *log_file = fopen("/var/log/sound_events.log", "a");
    if (!log_file) {
        perror("Can't open log file");
        return;
    }

    char timestamp_str[32];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S.000Z", localtime(&timestamp));
    fprintf(log_file, "%s,%d\n", timestamp_str, value);
    fclose(log_file);
}

int main() {
    setup();

    uint16_t last_value = 0;
    uint16_t current_value;
    time_t current_time;

    while (1) {
        current_value = read_adc();

        if (current_value > last_value + PEAK_THRESHOLD) {
            current_time = time(NULL);
            log_event(current_time, current_value);
