    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S.000Z", localtime(&timestamp));
    fprintf(log_file, "%s,%d\n", timestamp_str, value);
    fclose(log_file);
}

int main() {
    setup();

    uint16_t last_value = 0;
    uint16_t current_value;
    time_t current_time;

    while (1) {
        current_value = read_adc();

        if (current_value > last_value + PEAK_THRESHOLD) {
            current_time = time(NULL);
            log_event(current_time, current_value);
            last_value = current_value;
