#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <math.h>
#include <rpd/gpiod.h>

#define I2C_BUS 1
#define ADC_ADDR 0x48
#define ADC_CH 0
#define BUFFER_SIZE 1024
#define THRESHOLD 500.0f
#define GPIO_LINE_27 "/dev/gpioclass0/gpiochip0/gpio27"

struct adc_value {
    float voltage;
    time_t timestamp;
};

int i2c_file;
struct gpiod_line *gpio_line;
struct adc_value buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;

void syslog_error(const char *message) {
    openlog("adc_monitor", LOG_PERROR | LOG_CONS, LOG_USER);
    vsyslog(LOG_ERR, message, 0);
    closelog();
}

float adc_read() {
    int data[2];
    if (i2c_smbus_read_word_data(i2c_file, ADC_CH) < 0) {
        syslog_error("I2C read error\n");
        return NAN;
    }

    data[0] = (data[0] >> 6) & 0x1F;
    data[1] = (data[0] << 6) | (data[1] & 0x3F);

    float voltage = (data[1] * 3.3f) / 4096.0f;
    if (voltage < 0.0f || voltage > 3.3f) {
        syslog_error("Out-of-range voltage\n");
        return NAN;
    }

    return voltage;
}

float magnetic_field(float voltage) {
    // Replace this formula with the one that corresponds to your SS49E sensor
    return voltage * 0.1f * 0.00225f * 1000.0f;
}

void gpio_setup() {
    gpio_line = gpiod_get_line(0, "gpio27", GPIOD_LINE_REQUEST_INPUT);
    if (!gpio_line) {
        syslog_error("Failed to get GPIO line\n");
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(gpio_line, 0);
}

void gpio_shutdown() {
    if (gpio_line) {
        gpiod_line_set_value(gpio_line, 1);
        gpiod_line_put(gpio_line);
        gpio_line = NULL;
    }
}

int main() {
    int i2c_fd;
    struct i2c_dev *i2c_dev;

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        syslog_error("Failed to open I2C bus\n");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADC_ADDR) < 0) {
        syslog_error("Failed to set I2C slave address\n");
        exit(EXIT_FAILURE);
    }

    i2c_file = i2c_fd;
    gpio_setup();

    while (1) {
        float voltage = adc_read();
        if (isnan(voltage)) {
            continue;
        }

        float magnetic_field_value = magnetic_field(voltage);
        struct adc_value *entry = &buffer[buffer_head];
        entry->voltage = voltage;
        entry->timestamp = time(NULL);
        buffer_head = (buffer_head + 1) % BUFFER_SIZE;

        float rolling_average = 0.0f;
        int count = 0;
        for (int i = buffer_tail; i != buffer_head; i = (i + 1) % BUFFER_SIZE) {
            rolling_average += buffer[i].voltage;
            count++;
        }
        rolling_average /= count;

        if (magnetic_field_value > THRESHOLD && rolling_average > THRESHOLD) {
            gpio_shutdown();
            syslog_error("Magnetic field exceeded threshold\n");
            break;
        }

        usleep(1e6);
    }

    close(i2c_file);
    gpio_shutdown();

    return 0;
}

