```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <Adafruit_MCP3008.h>

#define ADC_CS 0
#define PUMP_GPIO 18
#define THRESHOLD 300
#define SAMPLES_COUNT 10
#define MOISTURE_FILE "watering_events.txt"

Adafruit_MCP3008 adc = Adafruit_MCP3008();
gpiod_line_request_linestate_callback_t pump_cb;
gpiod_line_request *pump_req;
struct timespec last_check = {0, 0};
int adc_fd;

void pump_on(void) {
    gpiod_line_set_value(pump_req, 1);
}

void pump_off(void) {
    gpiod_line_set_value(pump_req, 0);
}

void pump_cb(struct gpiod_chan *chan, int event, void *user_data) {
    if (event == GD_LINE_EVENT_EDGE_FALLING) {
        pump_off();
    }
}

void log_event(int moisture, time_t timestamp) {
    FILE *file = fopen(MOISTURE_FILE, "a");
    if (file) {
        fprintf(file, "%lu,%d\n", timestamp, moisture);
        fclose(file);
    }
}

int read_adc(void) {
    int samples[SAMPLES_COUNT];
    int i;
    int sum = 0;

    for (i = 0; i < SAMPLES_COUNT; i++) {
        samples[i] = adc.readADC(ADC_CS);
        if (samples[i] < 0 || samples[i] > 1023) {
            return -1;
        }
    }

    for (i = 0; i < SAMPLES_COUNT; i++) {
        sum += samples[i];
    }

    return sum / SAMPLES_COUNT;
}

int init_adc(void) {
    if ((adc_fd = open("/dev/spidev0.0", O_RDWR)) < 0) {
        perror("Can't open spi device");
        return -1;
    }

    if (adc.begin(adc_fd) < 0) {
        perror("Can't initialize ADC");
        return -1;
    }

    return 0;
}

int init_gpio(void) {
    int ret;

    ret = gpiod_chip_open_byname("gpiochip0");
    if (ret < 0) {
        perror("Can't open GPIO chip");
        return -1;
    }

    ret = gpiod_line_request_array_acquire(ret, "pump", 1, &pump_req, GPIOD_LINE_REQUEST_DIRECTION_OUT | GPIOD_LINE_REQUEST_ACTIVE_LOW);
    if (ret < 0) {
        perror("Can't request GPIO line");
        return -1;
    }

    ret = gpiod_line_request_set_debounce(pump_req, 10);
    if (ret < 0) {
        perror("Can't set debounce");
        return -1;
    }

    ret = gpiod_line_request_set_callback(pump_req, pump_cb, NULL);
    if (ret < 0) {
        perror("Can't set callback");
        return -1;
    }

    pump_on();

    return 0;
}

int main(void) {
    int moisture;
    time_t timestamp;
    int ret;

    if (init_gpio() < 0) {
        return 1;
    }

    signal(SIGINT, SIG_IGN);
    signal(SIGTERM, SIG_IGN);

    while (1) {
        timestamp = time(NULL);
        moisture = read_adc();

        if (moisture < THRESHOLD) {
            pump_off();
            sleep(10);
            pump_on();
            log_event(moisture, timestamp);
        }

        if (difftime(timestamp, last_check) > 60) {
            last_check = timestamp;
            printf("Current moisture level: %d\n", moisture);
        }
    }

    gpiod_line_request_release(pump_req);
    gpiod_chip_close(pump_req->chip);
    close(adc_fd);

    return 0;
}
