#define FULL_SCALE 1023
#define RAIN_THRESHOLD 500

struct spi_ioc_transfer spi_transfers[] = {
    {
        .tx_buf = (unsigned char*)&CHIP_SELECT,
        .len = sizeof(CHIP_SELECT),
        .delay_usecs = 5,
    },
    {
        .rx_buf = (unsigned char*)malloc(3),
        .len = 3,
    },
    {
        .tx_buf = NULL,
        .rx_buf = NULL,
        .len = 0,
    },
};

int main() {
    int spi_fd, adc_value, rain_level;
    struct gpiod_line *cs_line;
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    if ((spi_fd = open(SPI_DEVICE, O_RDWR)) < 0) {
        perror("Can't open SPI device");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) != 0) {
        perror("Can't set SPI mode");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED) != 0) {
        perror("Can't get max SPI speed");
        return 1;
    }

