            perror("SPI transfer failed");
            continue;
        }

        gpiod_line_set_value(cs_line, 0);
        if (xfer(spi_fd, spi_transfers, sizeof(spi_transfers) / sizeof(struct spi_ioc_transfer)) != sizeof(spi_transfers)) {
            perror("SPI transfer failed");
            continue;
        }

        adc_value = (spi_transfers[1].rx_buf[1] << 8) | spi_transfers[1].rx_buf[0];
        rain_level = (adc_value / FULL_SCALE) * RAIN_THRESHOLD;

        clock_gettime(CLOCK_REALTIME, &ts);
        printf("%ld.%09ld: ADC=%d, Rain level=%d\n", ts.tv_sec, ts.tv_nsec, adc_value, rain_level);

        usleep(1000000); // Sleep for 1 second
    }

    gpiod_line_release(cs_line);
    close(spi_fd);
    return 0;
}

int xfer(int spi_fd, struct spi_ioc_transfer *transfers, unsigned int num_transfers) {
    return ioctl(spi_fd, SPI_IOC_MESSAGE(num_transfers), transfers);
}
```

This code initializes the SPI device, sets up the MCP3008 chip select GPIO, and reads the ADC value from the YL-83 rain sensor once per second. It maps the ADC value to a rainfall intensity level and logs the timestamp, raw ADC value, and computed intensity to stdout. The program checks for successful initialization of the driver, opening of the SPI device, and every subsequent API call. If any SPI transfer fails, it prints an error message and skips that reading, retrying on the next cycle. The program also handles SIGINT (Ctrl-C) to perform a graceful shutdown by closing the SPI handle and terminating the driver library.

