#include <gpiod.h>

#define ADC_CS_GPIO 8
#define PWM_GPIO 18
#define SPI_BUS 0
#define SPI_DEVICE 0
#define ADC_CH 0
#define PWM_FREQ 1000
#define PWM_MIN 0
#define PWM_MAX 1023
#define ADC_RES 1024
#define ADC_READ_INTERVAL 100000
#define PWM_UPDATE_INTERVAL 10000

gpiod_line_request_linestate_t adc_cs_state = GPIOD_LINE_ACTIVE_LOW;
gpiod_line_request_flags_t adc_cs_flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_DISABLE_PULL;
gpiod_line_request_linestate_t pwm_state = GPIOD_LINE_ACTIVE_HIGH;
gpiod_line_request_flags_t pwm_flags = GPIOD_LINE_REQUEST_DIR_OUT | GPIOD_LINE_REQUEST_INIT_HIGH;

int spi_fd, adc_val, pwm_duty;
struct spi_ioc_transfer spi_transfers[2];

void sigint_handler(int signum) {
    gpiod_line_set_value(pwm_line, 0);
    gpiod_line_release(pwm_line);
    gpiod_line_release(adc_cs_line);
    close(spi_fd);
    exit(0);
}

int init_gpio() {
    gpiod_line_request_data_vlinestate_t data;
    gpiod_line_request_data_vlinestate_t *data_ptr = &data;

    adc_cs_line = gpiod_get_byname("gpiochip0" GPIOD_SPEC_GPIO(ADC_CS_GPIO));
    if (!adc_cs_line) {
        perror("Failed to get ADC CS GPIO line");
        return -1;
    }

    if (gpiod_line_request_desc(adc_cs_line, adc_cs_state, adc_cs_flags, data_ptr) < 0) {
        perror("Failed to request ADC CS GPIO line");
        goto cleanup_adc_cs;
    }

    pwm_line = gpiod_get_byname("gpiochip0" GPIOD_SPEC_GPIO(PWM_GPIO));
    if (!pwm_line) {
        perror("Failed to get PWM GPIO line");
        goto cleanup_adc_cs;
    }

    if (gpiod_line_request_desc(pwm_line, pwm_state, pwm_flags, data_ptr) < 0) {
        perror("Failed to request PWM GPIO line");
        goto cleanup_pwm;
    }

    return 0;

cleanup_pwm:
    gpiod_line_release(pwm_line);

cleanup_adc_cs:
    gpiod_line_release(adc_cs_line);

    return -1;
}

int init_spi() {
    char spi_dev_path[32];
    snprintf(spi_dev_path, sizeof(spi_dev_path), "/dev/spidev%d.%d", SPI_BUS, SPI_DEVICE);

    spi_fd = open(spi_dev_path, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    spi_transfers[0].tx_buf = (unsigned char*)&ADC_CH;
    spi_transfers[0].len = sizeof(ADC_CH);
    spi_transfers[0].speed_hz = 1000000;

    spi_transfers[1].rx_buf = (unsigned char*)&adc_val;
    spi_transfers[1].len = 3;
    spi_transfers[1].speed_hz = 1000000;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), spi_transfers) < 0) {
        perror("Failed to configure SPI transfer");
        goto cleanup_spi;
    }

    return 0;

cleanup_spi:
    close(spi_fd);

    return -1;
}

int main() {
    struct sigaction sa;
    struct timespec ts;

    if (init_gpio() < 0) {
        return -1;
    }

    if (init_spi() < 0) {
        goto cleanup_gpio;
    }

    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set SIGINT/SIGTERM handler");
        goto cleanup_spi;
    }

    while (1) {
        gpiod_line_set_value(adc_cs_line, 0);
        usleep(10000);
        gpiod_line_set_value(adc_cs_line, 1);
        usleep(10000);

        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), spi_transfers) < 0) {
            perror("Failed to perform SPI transfer");
            continue;
        }

        adc_val = (adc_val >> 4) & 0x0FFF;
        pwm_duty = (adc_val * PWM_MAX) / ADC_RES;
        pwm_duty = (pwm_duty < PWM_MIN) ? PWM_MIN : (pwm_duty > PWM_MAX) ? PWM_MAX : pwm_duty;

        gpiod_line_set_value(pwm_line, pwm_duty * (GPIOD_LINE_ACTIVE_HIGH - GPIOD_LINE_ACTIVE_LOW) / PWM_MAX);

        printf("ADC reading: %d, PWM duty: %d\n", adc_val, pwm_duty);

        ts.tv_sec = ADC_READ_INTERVAL / 1000000;
        ts.tv_nsec = (ADC_READ_INTERVAL % 1000000) * 1000;
        nanosleep(&ts, NULL);
    }

cleanup_spi:
    gpiod_line_release(adc_cs_line);
    gpiod_line_release(pwm_line);
    close(spi_fd);

cleanup_gpio:
    return 0;
}

