#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <Adafruit_ADS1x15.h>

#define ADS1115_ADDRESS 0x48
#define GPIO_LED_PIN 17

Adafruit_ADS1115 ads;
struct gpiod_line *gpio_led;
double threshold = 100.0;

void setup() {
    if (!ads.begin()) {
        fprintf(stderr, "Couldn't find ADS1115 chip.\n");
        exit(1);
    }

    if (gpio_led = gpiod_chip_open_byname("gpiochip0")) {
        gpiod_line_request_line(gpio_led, GPIO_LED_PIN, "led", GPIOD_LINE_REQUEST_DIRECTION_OUT | GPIOD_LINE_REQUEST_ACTIVE_LOW);
    } else {
        perror("Failed to open GPIO chip");
        exit(1);
    }

    signal(SIGINT, clean_exit);
    signal(SIGTERM, clean_exit);
}

void clean_exit(int signum) {
    gpiod_line_set_value(gpio_led, 0);
    gpiod_line_release(gpio_led);
    ads.end();
    exit(0);
}

double read_adc(uint8_t channel) {
    ads.setGain(GAIN_4_096);
    uint16_t adc_value = ads.readADC_SingleEnded(channel);
    return (double)adc_value * 3.3 / 4096;
}

void blink_led(int on_ms, int off_ms) {
    gpiod_line_set_value(gpio_led, 1);
    usleep(on_ms * 1000);
    gpiod_line_set_value(gpio_led, 0);
    usleep(off_ms * 1000);
}

int main(int argc, char *argv[]) {
    if (argc > 2) {
        fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
        exit(1);
    }

    if (argc == 2) {
        threshold = atof(argv[1]);
    }

    setup();

    while (1) {
        double magnetic_field = read_adc(0);
        if (magnetic_field > threshold) {
            blink_led(50, 50);
        }
        printf("Magnetic field: %.2f Gauss\n", magnetic_field);
        usleep(100000);
    }

    return 0;
}

