code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <pigpio.h>
#include <pthread.h>
#include <syslog.h>
#include <mqtt/async_client.h>

#define ADC_CS_GPIO 8
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define MQTT_TOPIC_SOIL_MOISTURE "soil_moisture"
#define MQTT_TOPIC_PUMP_CONTROL "pump_control"
#define MQTT_KEEPALIVE 60
#define MQTT_QOS 1

static gpiod_line_request_lines_data_t gpio_data[] = {
    { .flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_HIGH },
    { .flags = GPIOD_LINE_REQUEST_OUTPUT },
};

static gpiod_line_handle_t gpio_handles[2];
static struct spi_device *spidev;
static struct mqtt_async_client *client;
static pthread_t mqtt_thread;

void gpio_cb(struct gpiod_line_event_info *info) {
    if (info->line == gpio_handles[0].handle) {
        // Handle soil moisture sensor event
    } else if (info->line == gpio_handles[1].handle) {
        // Handle pump relay event
    }
}

int adc_read(void) {
    uint8_t data[3];
    int ret;

    ret = spi_xfer(spidev, data, sizeof(data));
    if (ret != sizeof(data)) {
        syslog(LOG_ERR, "ADC read error: %d", ret);
        return -1;
    }

    return (data[1] << 8) | data[2];
}

void mqtt_publish(const char *topic, int value) {
    char msg[16];
    snprintf(msg, sizeof(msg), "%d", value);
    mqtt_message_t msg_obj;

    msg_obj.qos = MQTT_QOS;
    msg_obj.retained = 0;
    msg_obj.dup = 0;
    msg_obj.payload = (void *)msg;
    msg_obj.payloadlen = strlen(msg);

    mqtt_client_publish(client, topic, &msg_obj, MQTT_QOS, 0, 0);
}

void mqtt_callback(struct mqtt_async_client *client, struct mqtt_message *message) {
    char topic[64];
    char cmd[16];

    strncpy(topic, message->topicname, sizeof(topic));
    strncpy(cmd, (char *)message->payload, sizeof(cmd));

    syslog(LOG_INFO, "Received MQTT message: topic=%s, command=%s", topic, cmd);

    if (strcmp(topic, MQTT_TOPIC_PUMP_CONTROL) == 0) {
        if (strcmp(cmd, "pump_on") == 0) {
            gpiod_line_set_value(gpio_handles[1].handle, 1);
        } else if (strcmp(cmd, "pump_off") == 0) {
            gpiod_line_set_value(gpio_handles[1].handle, 0);
        }
    }
}

int main(void) {
    int ret;

    openlog("soil_moisture_pump", LOG_PID, LOG_USER);

    ret = gpiod_for_each_line(gpio_data, ARRAY_SIZE(gpio_data), &gpio_data[0].consumer, gpio_cb);
    if (ret < 0) {
        syslog(LOG_ERR, "GPIO request error: %d", ret);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_claim_lines(gpio_data, ARRAY_SIZE(gpio_data), &gpio_data[0].consumer);
    if (ret < 0) {
        syslog(LOG_ERR, "GPIO claim error: %d", ret);
        exit(EXIT_FAILURE);
    }

    gpio_handles[0] = gpio_data[0].handle;
    gpio_handles[1] = gpio_data[1].handle;

    ret = pigpio_init();
    if (ret < 0) {
        syslog(LOG_ERR, "pigpio init error: %d", ret);
        exit(EXIT_FAILURE);
    }

    spidev = pigpio_spidevopen(0, 0, 1000000);
    if (!spidev) {
        syslog(LOG_ERR, "SPI open error");
        exit(EXIT_FAILURE);
    }

    ret = mqtt_async_init(NULL, MQTT_KEEPALIVE, true);
    if (ret != MQTT_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT init error: %d", ret);
        exit(EXIT_FAILURE);
    }

    client = mqtt_async_create("soil_moisture_pump", CLIENT_ID_GENERATE(1), MQTT_KEEPALIVE, NULL);
    if (!client) {
        syslog(LOG_ERR, "MQTT client creation error");
        exit(EXIT_FAILURE);
    }

    ret = mqtt_async_subscribe(client, MQTT_TOPIC_PUMP_CONTROL, MQTT_QOS);
    if (ret != MQTT_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT subscription error: %d", ret);
        exit(EXIT_FAILURE);
    }

    pthread_create(&mqtt_thread, NULL, mqtt_async_run_standalone, client);

    while (1) {
        int moisture = adc_read();
        if (moisture < 0) {
            syslog(LOG_ERR, "ADC read error");
            continue;
        }

        if (moisture < MOISTURE_THRESHOLD_LOW) {
            gpiod_line_set_value(gpio_handles[1].handle, 1);
        } else if (moisture > MOISTURE_THRESHOLD_HIGH) {
            gpiod_line_set_value(gpio_handles[1].handle, 0);
        }

        mqtt_publish(MQTT_TOPIC_SOIL_MOISTURE, moisture);
        sleep(60);
    }

    mqtt_async_disconnect(client, MQTT_ASYNC_DISCONNECT_IMMEDIATE);
    mqtt_async_destroy(client);
    pigpio_spidevclose(spidev);
    pigpio_terminate();
    gpiod_release_lines(gpio_data, ARRAY_SIZE(gpio_data), &gpio_data[0].consumer);
    pthread_join(mqtt_thread, NULL);

    syslog(LOG_INFO, "Exiting...");
    closelog();
    return 0;
}

