```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BAUD 1000000
#define CS_GPIO 8
#define DIN_GPIO 10
#define DOUT_GPIO 9
#define CLK_GPIO 11

#define VDD 3.3
#define VREF 3.3

int main() {
    int spi_fd, gpio_fd;
    struct spi_ioc_transfer transfer = {};
    char *spi_buf;
    struct gpiod_chip *chip;
    struct gpiod_line *line_cs, *line_din, *line_dout, *line_clk;
    int ret;

    // Open SPI device
    if ((spi_fd = open(SPI_DEV, O_RDWR)) < 0) {
        perror("Can't open SPI device");
        return 1;
    }

    // Set SPI mode, data rate, bits per word, and transfer delay
    transfer.tx_buf = (unsigned char *) &VDD;
    transfer.rx_buf = (unsigned char *) malloc(3);
    transfer.len = 1;
    transfer.speed_hz = SPI_BAUD;
    transfer.bits_per_word = 8;
    ret = ioctl(spi_fd, SPI_IOC_WRITE_MODE32, &transfer);
    if (ret < 1) {
        perror("Can't set SPI mode");
        close(spi_fd);
        return 1;
    }

    ret = ioctl(spi_fd, SPI_IOC_READ_MODE32, &transfer);
    if (ret < 1) {
        perror("Can't get SPI mode");
        close(spi_fd);
        return 1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WRITE_MAX_SPEED_HZ, &SPI_BAUD);
    if (ret < 0) {
        perror("Can't set max speed");
        close(spi_fd);
        return 1;
    }

    ret = ioctl(spi_fd, SPI_IOC_READ_MAX_SPEED_HZ, &SPI_BAUD);
    if (ret < 0) {
        perror("Can't get max speed");
        close(spi_fd);
        return 1;
    }

    // Map GPIO chip and lines
    if ((gpio_fd = gpiod_chip_open_byname("gpiochip0")) < 0) {
        perror("Can't open GPIO chip");
        close(spi_fd);
        return 1;
    }

    chip = gpiod_chip_get_byindex(gpio_fd, 0);

    line_cs = gpiod_chip_get_line(chip, CS_GPIO);
    line_din = gpiod_chip_get_line(chip, DIN_GPIO);
    line_dout = gpiod_chip_get_line(chip, DOUT_GPIO);
    line_clk = gpiod_chip_get_line(chip, CLK_GPIO);

    // Set GPIO lines direction
    gpiod_line_request_output(line_cs, "cs");
    gpiod_line_request_output(line_din, "din");
    gpiod_line_request_output(line_dout, "dout");
    gpiod_line_request_output(line_clk, "clk");

    // Set GPIO lines to output low
    gpiod_line_set_value(line_cs, 0);
    gpiod_line_set_value(line_din, 0);
    gpiod_line_set_value(line_dout, 0);
    gpiod_line_set_value(line_clk, 0);

    // Main loop
    while (1) {
        // Set CS low
        gpiod_line_set_value(line_cs, 0);
        usleep(10);

        // Send command to read channel 0
        transfer.tx_buf[0] = 0x01;
        ret = write(spi_fd, &transfer, sizeof(transfer));
        if (ret != sizeof(transfer)) {
            perror("Can't write to SPI device");
            close(spi_fd);
            gpiod_chip_close(gpio_fd);
            return 1;
        }

        // Wait for data
        usleep(10);

        // Set CS high
        gpiod_line_set_value(line_cs, 1);

        // Read data
        ret = read(spi_fd, transfer.rx_buf, transfer.len);
        if (ret != transfer.len) {
            perror("Can't read from SPI device");
            close(spi_fd);
            gpiod_chip_close(gpio_fd);
            return 1;
        }

        // Convert raw value to voltage
        double raw = (transfer.rx_buf[0] & 0x03FF) * 3.3 / 1023.0;
        printf("Raw value: %d, Voltage: %.2fV\n", transfer.rx_buf[0] & 0x03FF, raw);

        usleep(500000);
    }

    // Cleanup
    free(spi_buf);
    gpiod_line_release(line_cs);
    gpiod_line_release(line_din);
    gpiod_line_release(line_dout);
    gpiod_line_release(line_clk);
    gpiod_chip_close(gpio_fd);
    close(spi_fd);

    return 0;
}
```

This code reads the raw value from channel 0 of an MCP3008 connected to the Raspberry Pi's SPI bus and prints the corresponding voltage. It also handles errors and properly closes resources on exit paths. The program will exit when it receives a SIGINT signal.

