```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define ADC_CS 0
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27
#define NOISE_THRESHOLD 500
#define SAMPLES_PER_ITERATION 16
#define TIMEOUT_US 10000
#define LOG_FILE "vibration_log.txt"

int spi_fd, adc_fd;
volatile sig_atomic_t running = 1;
gpiod_line_request_lines_data_t motor_lines[2];
FILE *log_file;

void setup() {
    if ((spi_fd = open("/dev/spidev0.0", O_RDWR)) < 0) {
        perror("Can't open SPI device");
        exit(EXIT_FAILURE);
    }

    struct spi_ioc_transfer transfers[SAMPLES_PER_ITERATION];
    for (int i = 0; i < SAMPLES_PER_ITERATION; ++i) {
        transfers[i].tx_buf = (unsigned char *)&zero;
        transfers[i].rx_buf = (unsigned char *)&adc_data;
        transfers[i].len = 2;
        transfers[i].speed_hz = 1000000;
        transfers[i].bits_per_word = 8;
        transfers[i].cs_change = 0;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(16), transfers) < 0) {
        perror("Can't set up SPI transfers");
        exit(EXIT_FAILURE);
    }

    if ((adc_fd = open("/dev/mem", O_RDWR | O_SYNC)) < 0) {
        perror("Can't open /dev/mem");
        exit(EXIT_FAILURE);
    }

    void *reg_base = mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_SHARED, adc_fd, 0x20000000);
    if (reg_base == MAP_FAILED) {
        perror("Can't mmap /dev/mem");
        exit(EXIT_FAILURE);
    }

    gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Can't open GPIO chip");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_array_probed(chip, motor_lines, 2) < 0) {
        perror("Can't request GPIO lines");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_lines(chip, motor_lines, 2, GPIOD_LINE_REQUEST_DIRECTION_OUT, NULL) < 0) {
        perror("Can't set GPIO lines direction");
        exit(EXIT_FAILURE);
    }

    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        perror("Can't open log file");
        exit(EXIT_FAILURE);
    }
}

void motor_off(int gpio) {
    gpiod_line_set_value_cansleep(motor_lines[gpio - MOTOR1_GPIO].lines[0], 0);
}

void motor_on(int gpio) {
    gpiod_line_set_value_cansleep(motor_lines[gpio - MOTOR1_GPIO].lines[0], 1);
}

void log_event() {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(log_file, "%s: Motor 1: %d, Motor 2: %d\n", timestamp, motor1_on, motor2_on);
}

int main() {
    setup();

    int adc_data[SAMPLES_PER_ITERATION];
    int motor1_on = 0, motor2_on = 0;
    unsigned short zero = 0;

    while (running) {
        int sum = 0;
        for (int i = 0; i < SAMPLES_PER_ITERATION; ++i) {
            spi_ioc_message_t msg = {
                .tx_buf = (unsigned long *)&ADC_CS,
                .rx_buf = (unsigned long *)&adc_data[i],
                .len = 2,
                .speed_hz = 1000000,
                .bits_per_word = 16,
                .cs_change = 1 << ADC_CS
            };

            if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &msg) < 0) {
                perror("Can't send SPI message");
                continue;
            }

            sum += adc_data[i];
        }

        int noise_level = sum / SAMPLES_PER_ITERATION;
        if (noise_level > NOISE_THRESHOLD) {
            if (!motor1_on) {
                motor_on(MOTOR1_GPIO);
                motor1_on = 1;
            }
            if (!motor2_on) {
                motor_on(MOTOR2_GPIO);
                motor2_on = 1;
            }
            if (!motor1_on && !motor2_on) {
                log_event();
            }
        } else {
            if (motor1_on) {
                motor_off(MOTOR1_GPIO);
                motor1_on = 0;
            }
            if (motor2_on) {
                motor_off(MOTOR2_GPIO);
                motor2_on = 0;
            }
        }

        usleep(10000);
    }

    close(spi_fd);
    munmap(reg_base, 4096);
    close(adc_fd);
    gpiod_line_release_probed(motor_lines, 2);
    gpiod_chip_close(chip);
    fclose(log_file);

