static gpiod_line_data_t relay_line_data;

static int spi_fd, relay_fd;
static struct spi_ioc_transfer spi_transfers[2];
static uint16_t adc_value;
static time_t last_log_time = 0;

void handle_signal(int signum) {
    printf("Exiting...\n");
    gpiod_line_set_value(relay_fd, 0);
    close(spi_fd);
    close(relay_fd);
    gpiod_line_release(relay_fd, &relay_line_data);
    exit(0);
}

int init_gpio() {
    relay_fd = gpiod_chip_open_byname("gpiochip0");
    if (relay_fd < 0) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    if (gpiod_line_request_index(relay_fd, RELAY_GPIO, &relay_request_data, &relay_line_data) < 0) {
        perror("Failed to request GPIO line");
        goto cleanup_gpio;
    }

    gpiod_line_set_value(relay_fd, 0);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    return 0;

cleanup_gpio:
    gpiod_line_release(relay_fd, &relay_line_data);
    close(relay_fd);
    return -1;
}

int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    spi_transfers[0].tx_buf = (unsigned char*)&ADC_CHANNEL;
    spi_transfers[0].len = sizeof(ADC_CHANNEL);
    spi_transfers[0].speed_hz = SPI_SPEED;
    spi_transfers[0].bits_per_word = 8;

    spi_transfers[1].rx_buf = (unsigned char*)&adc_value;
    spi_transfers[1].len = 2;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), spi_transfers) < 1) {
        perror("Failed to configure SPI transfer");
        goto cleanup_spi;
    }

    return 0;

cleanup_spi:
    close(spi_fd);
    return -1;
}

int main() {
    if (init_gpio() < 0) {
        return 1;
    }

    if (init_spi() < 0) {
        goto cleanup_gpio;
    }

    while (1) {
        int retries = 3;
        while (retries > 0) {
            if (xfer(spi_fd, spi_transfers, 2) == 2) {
                break;
            }
            retries--;
        }

        if (retries == 0) {
            perror("Failed to read ADC value");
            continue;
        }

        float moisture = adc_value * 3.3 / 1023 * 100;
        time_t current_time = time(NULL);

        if (moisture < MOISTURE_THRESHOLD) {
            gpiod_line_set_value(relay_fd, 1);
