#include <sys/mman.h>
#include <time.h>
#include <errno.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define GPIO_RELAY 17
#define GPIO_SENSOR_CE 0
#define SENSOR_CH 0
#define LOG_FILE "door_events.log"

static int spi_fd, gpio_relay_fd, gpio_sensor_fd;
static struct spi_ioc_transfer spi_transfers[1];
static char spi_buffer[3];

void log_event(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        return;
    }

    time_t rawtime;
    struct tm *timeinfo;
    char time_string[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s: %s\n", time_string, message);
    fclose(log_file);
}

int init_gpio(int gpio) {
    gpiod_line_request_dt_byname("rpi,gpio", gpio);
    gpiod_line_set_value_cansleep(gpio_get_line_byname("rpi,gpio", gpio), 1);
    gpiod_line_set_debounce(gpio_get_line_byname("rpi,gpio", gpio), 10);
    return gpiod_line_get_fd(gpio_get_line_byname("rpi,gpio", gpio));
}

int init_spi() {
    if ((spi_fd = open(SPI_DEV, O_RDWR)) < 0) {
        perror("Can't open spi device");
        exit(EXIT_FAILURE);
    }

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long*)&spi_buffer,
        .rx_buf = (unsigned long*)&spi_buffer,
        .len = 3,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &transfer) < 1) {
        perror("Can't set spi mode");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MODE, &transfer) < 1) {
        perror("Can't get spi mode");
        exit(EXIT_FAILURE);
    }

    spi_transfers[0] = transfer;

    return 0;
}

void cleanup() {
    if (gpio_relay_fd >= 0) {
        gpiod_line_release(gpio_get_line_byname("rpi,gpio", GPIO_RELAY));
        close(gpio_relay_fd);
    }

    if (gpio_sensor_fd >= 0) {
        gpiod_line_release(gpio_get_line_byname("rpi,gpio", GPIO_SENSOR_CE));
        close(gpio_sensor_fd);
    }

    if (spi_fd >= 0) {
        close(spi_fd);
    }

    exit(EXIT_SUCCESS);
}

void handle_sigint(int signum) {
    printf("\nReceived SIGINT. Exiting gracefully...\n");
    cleanup();
}

int main() {
    signal(SIGINT, handle_sigint);

    gpio_relay_fd = init_gpio(GPIO_RELAY);
    gpio_sensor_fd = init_gpio(GPIO_SENSOR_CE);

    if (init_spi() < 0) {
        return EXIT_FAILURE;
    }

    int previous_state = gpiod_line_get_value_cansleep(gpio_get_line_byname("rpi,gpio", GPIO_RELAY));

    while (1) {
        gpiod_line_set_value_cansleep(gpio_get_line_byname("rpi,gpio", GPIO_SENSOR_CE), 0);
        usleep(100000);
        write(spi_fd, &spi_transfers, sizeof(spi_transfers));
        usleep(9000000);
        gpiod_line_set_value_cansleep(gpio_get_line_byname("rpi,gpio", GPIO_SENSOR_CE), 1);

        if (spi_buffer[1] < 20 * 16) {
            if (gpiod_line_get_value_cansleep(gpio_get_line_byname("rpi,gpio", GPIO_RELAY) == previous_state) {
                gpiod_line_set_value_cansleep(gpio_get_line_byname("rpi,gpio", GPIO_RELAY), 1);
                log_event("Door opened");
                usleep(1000000);
            }
        }

        previous_state = gpiod_line_get_value_cansleep(gpio_get_line_byname("rpi,gpio", GPIO_RELAY));
    }

    return EXIT_SUCCESS;
}
