This code assumes that the Vegetronix VH400 sensor is connected to the MCP3008 ADC on SPI channel 0, and the ASCO RedHat 8210 series proportional solenoid valve is connected to GPIO17 (BCM numbering). Make sure to adjust the connections according to your setup.

code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_SPEED_HZ 1000000
#define GPIO_CE0_LINE "gpiochip0"
#define GPIO_CE0_LINE_NUM 8
#define CHANNEL 0
#define SAMPLE_INTERVAL 5
#define MAX_RETRIES 5
#define ERROR_MESSAGE_LENGTH 32

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int num_lines,
                                const char *const *lines, unsigned int flags)
{
    return gpiod_chip_request_lines(chip, num_lines, lines, flags, NULL);
}

static void gpio_cleanup(struct gpiod_line *ce0_line)
{
    gpiod_line_release(ce0_line);
    gpiod_chip_deinitialize(ce0_line->chip);
}

static int spi_xfer(int spi_fd, const unsigned char *tx_buf, unsigned char *rx_buf, size_t len)
{
    struct spi_ioc_transfer transfers[1] = {
        {
            .tx_buf = (unsigned long)tx_buf,
            .rx_buf = (unsigned long)rx_buf,
            .len = len,
            .delay_usecs = 0,
            .speed_hz = SPI_SPEED_HZ,
        },
    };

    return ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfers);
}

static unsigned int read_adc(int spi_fd, struct gpiod_line *ce0_line)
{
    unsigned char cmd[3] = {0, 0x4C, CHANNEL << 6};
    unsigned char data[3];
    unsigned int i, retries = 0;
    unsigned int adc_value = 0;

    gpiod_line_set_value(ce0_line, 1);
    usleep(10);
    gpiod_line_set_value(ce0_line, 0);

    do {
        if (spi_xfer(spi_fd, cmd, data, sizeof(data)) < 0) {
            perror("SPI transfer failed");
            usleep(pow(2, retries) * 100);
            retries++;
            if (retries == MAX_RETRIES) {
                return 0;
            }
            continue;
        }

        adc_value = (data[1] << 8) | data[2];

        if (adc_value > 1023 || adc_value < 0) {
            fprintf(stderr, "Invalid ADC value: %u\n", adc_value);
            return 0;
        }

        break;
    } while (retries < MAX_RETRIES);

    return adc_value;
}

static void log_data(const char *filename, time_t timestamp, unsigned int moisture)
{
    FILE *file = fopen(filename, "a");

    if (!file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(file, "%s - %lu - Moisture: %u\n", ctime(&timestamp), timestamp, moisture);
    fclose(file);
}

int main(void)
{
    int spi_fd, ret;
    struct gpiod_chip *chip;
    struct gpiod_line *ce0_line;
    struct timespec sleep_interval;
    time_t timestamp;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    ce0_line = gpiod_line_get_byname(chip, GPIO_CE0_LINE_NUM);
    if (!ce0_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_deinitialize(chip);
        return 1;
    }

    ret = gpio_request_lines(chip, 1, &GPIO_CE0_LINE, GPIOD_LINE_REQUEST_INPUT);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(ce0_line);
        gpiod_chip_deinitialize(chip);
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpio_cleanup(ce0_line);
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) != 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        gpio_cleanup(ce0_line);
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ) != 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        gpio_cleanup(ce0_line);
        return 1;
    }

    sleep_interval.tv_sec = SAMPLE_INTERVAL;
    sleep_interval.tv_nsec = 0;

    while (1) {
        unsigned int moisture = read_adc(spi_fd, ce0_line);

        if (moisture > 0) {
            timestamp = time(NULL);
            log_data("soil_data.txt", timestamp, moisture);
        } else {
            char error_message[ERROR_MESSAGE_LENGTH];
            snprintf(error_message, sizeof(error_message), "Failed to read ADC value at %s", ctime(&timestamp));
            log_data("soil_data.txt", timestamp, 0);
        }

        nanosleep(&sleep_interval, NULL);

        if (signal_pending(SIGINT) || signal_pending(SIGTERM)) {
            break;
        }
    }

    close(spi_fd);
    gpio_cleanup(ce0_line);
    gpiod_chip_deinitialize(chip);

    return 0;
}

