    fprintf(file, "%s - %lu - Moisture: %u\n", ctime(&timestamp), timestamp, moisture);
    fclose(file);
}

int main(void)
{
    int spi_fd, ret;
    struct gpiod_chip *chip;
    struct gpiod_line *ce0_line;
    struct timespec sleep_interval;
    time_t timestamp;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    ce0_line = gpiod_line_get_byname(chip, GPIO_CE0_LINE_NUM);
    if (!ce0_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_deinitialize(chip);
        return 1;
    }

    ret = gpio_request_lines(chip, 1, &GPIO_CE0_LINE, GPIOD_LINE_REQUEST_INPUT);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(ce0_line);
        gpiod_chip_deinitialize(chip);
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpio_cleanup(ce0_line);
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) != 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        gpio_cleanup(ce0_line);
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ) != 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        gpio_cleanup(ce0_line);
        return 1;
    }

    sleep_interval.tv_sec = SAMPLE_INTERVAL;
    sleep_interval.tv_nsec = 0;

    while (1) {
        unsigned int moisture = read_adc(spi_fd, ce0_line);

        if (moisture > 0) {
            timestamp = time(NULL);
            log_data("soil_data.txt", timestamp, moisture);
        } else {
            char error_message[ERROR_MESSAGE_LENGTH];
            snprintf(error_message, sizeof(error_message), "Failed to read ADC value at %s", ctime(&timestamp));
            log_data("soil_data.txt", timestamp, 0);
        }

        nanosleep(&sleep_interval, NULL);

        if (signal_pending(SIGINT) || signal_pending(SIGTERM)) {
            break;
        }
    }

    close(spi_fd);
    gpio_cleanup(ce0_line);
    gpiod_chip_deinitialize(chip);

    return 0;
}
