#include <gpiod.h>

#define ADC_CS 0
#define FAN_GPIO 18
#define ADC_MAX_COUNT 1024
#define ADC_VREF 3.3
#define MQ135_R0 10
#define MQ135_B 0.02
#define MQ135_A 0.048
#define MQ135_T0 298.15
#define MQ135_LOG_E 2.302585
#define MQ135_AQI_THRESHOLD 100

static int spi_fd;
static struct spi_device *spi;
static char *spi_dev_path = "/dev/spidev0.0";

static gpio_td *fan_gpio;

void sigint_handler(int signum) {
    gpiod_set_value_cansleep(fan_gpio, 0);
    spi_close(spi_fd);
    gpiod_release(fan_gpio);
    exit(0);
}

void sigterm_handler(int signum) {
    sigint_handler(signum);
}

void spi_init() {
    spi_fd = open(spi_dev_path, O_RDWR);
    if (spi_fd < 0) {
        perror("Can't open spi device");
        exit(1);
    }

    if ((spi = spi_open(spi_fd, 0)) == NULL) {
        perror("Can't open spi device");
        exit(1);
    }

    spi->mode = SPI_MODE_0;
    spi->max_speed_hz = 1000000;
    if (spi_ioctl(spi, SPI_IOC_WR_MODE, &spi->mode) < 0) {
        perror("Can't set spi mode");
        exit(1);
    }
    if (spi_ioctl(spi, SPI_IOC_WR_MAX_SPEED_HZ, &spi->max_speed_hz) < 0) {
        perror("Can't set spi max speed");
        exit(1);
    }
}

float read_adc() {
    char buf[3];
    int retries = 3;

    while (retries > 0) {
        spi_write(spi, &ADC_CS, 1);
        spi_write(spi, &ADC_CS, 0);
        spi_write(spi, &ADC_MAX_COUNT, 2);
        spi_read(spi, buf, 3);
        spi_write(spi, &ADC_CS, 1);

        if (buf[0] == 0x05 && buf[1] == 0x00) {
            return (buf[2] << 8 | buf[3]) * ADC_VREF / (float)ADC_MAX_COUNT;
        }

        retries--;
        usleep(1000000);
    }

    perror("Failed to read ADC");
    exit(1);
}

float calculate_aqi(float co2) {
    float aqi = 50.0 * (co2 - 400) / (12.5 - 400);
    if (aqi > 500) {
        aqi = 500;
    }
    return aqi;
}

int main() {
    float co2;
    time_t timestamp;
    FILE *log_file;
    int retries = 3;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    spi_init();

    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        perror("Can't open log file");
        exit(1);
    }

    fan_gpio = gpiod_chip_open_named_global("gpiochip0");
    if (!fan_gpio) {
        perror("Can't open gpiochip0");
        exit(1);
    }

    gpiod_line_request_output(fan_gpio, FAN_GPIO, "fan", GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW);
    gpiod_set_value_cansleep(fan_gpio, 0);

    while (1) {
        co2 = read_adc() / MQ135_R0;
        co2 = 1 / (1 + exp((MQ135_LOG_E - MQ135_A * co2 - MQ135_B * co2 * co2) / (co2 + MQ135_T0)));
        float aqi = calculate_aqi(co2);

        time(&timestamp);
        fprintf(log_file, "%s AQI: %.2f\n", ctime(&timestamp), aqi);

        if (aqi > MQ135_AQI_THRESHOLD) {
            gpiod_set_value_cansleep(fan_gpio, 1);
        } else {
            gpiod_set_value_cansleep(fan_gpio, 0);
        }

        sleep(5);

        if (retries > 0) {
            retries--;
        } else {
            spi_init();
            retries = 3;
        }
    }

    fclose(log_file);
    gpiod_release(fan_gpio);
    spi_close(spi_fd);

    return 0;
}
