```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <libgpiod.h>
#include <spidev/spidev.h>

#define ADC_CS_GPIO 8
#define ADC_CHANNEL 0
#define SAMPLE_INTERVAL 1000
#define MAX_RETRIES 3
#define ADC_RESOLUTION 1024
#define ADC_MIN_VOLTAGE 0
#define ADC_MAX_VOLTAGE (ADC_RESOLUTION - 1)
#define ADC_VREF 3.3
#define ADC_SENSITIVITY 10
#define ADC_LOW_THRESHOLD 20
#define ADC_HIGH_THRESHOLD 50
#define LOG_FILE "alcohol_log.txt"

gpiod_line_request_linestate_cb_t gpio_cb;
struct gpiod_line_request *gpio_req;
struct spi_device *spidev;

void gpio_cb(struct gpiod_line_request *req, int event, void *data) {
    (void)data;
    if (event == GPIOD_LINE_EVENT_EDGE_FALLING) {
        gpiod_line_set_value(gpio_req, 1);
    }
}

int adc_read() {
    char buf[4];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (spidev_xfer(spidev, &buf, sizeof(buf), NULL) < 0) {
            if (errno != EAGAIN) {
                perror("Failed to read ADC");
                retries++;
                usleep(100000);
                continue;
            }
        }

        if (buf[1] & 0x01) {
            return -1; // ADC error
        }

        int adc_value = (buf[1] & ~0x01) >> 3;
        double voltage = (adc_value / ADC_RESOLUTION) * ADC_VREF * ADC_SENSITIVITY;

        if (voltage < ADC_MIN_VOLTAGE || voltage > ADC_MAX_VOLTAGE) {
            return -1; // ADC out of range
        }

        return adc_value;
    }

    perror("Failed to read ADC after retries");
    return -1;
}

void log_measurement(const char *message, int adc_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s: %d\n", timestamp, adc_value);
    fclose(log_file);
}

void signal_handler(int sig) {
    if (gpio_req) {
        gpiod_line_release(gpio_req);
        gpiod_line_request_free(gpio_req);
        gpio_req = NULL;
    }

    if (spidev) {
        close(spidev->fd);
        spidev = NULL;
    }

    if (gpio_cb) {
        gpiod_line_request_set_callback(gpio_req, NULL);
        gpio_cb = NULL;
    }

    fclose(log_file);
    exit(0);
}

int main() {
    int ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpio_req = gpiod_chip_get_line_request_byname(gpiod_chip_get_bylabel("gpiochip0"), "gpio8");
    if (!gpio_req) {
        perror("Failed to get GPIO line request");
        return 1;
    }

    ret = gpiod_line_request_enable(gpio_req, GPIOD_LINE_REQUEST_DIRECTION_IN);
    if (ret < 0) {
        perror("Failed to enable GPIO line request");
        goto cleanup;
    }

    gpio_cb = gpiod_line_request_get_callback(gpio_req);
    gpiod_line_request_set_callback(gpio_req, gpio_cb);

    gpiod_line_set_value(gpio_req, 0);

    spidev = spi_open(0, ADC_CS_GPIO);
    if (!spidev) {
        perror("Failed to open SPI device");
        goto cleanup;
    }

    spi_setup(spidev);

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        goto cleanup;
    }

    while (1) {
        int adc_value = adc_read();
        if (adc_value < 0) {
            perror("Failed to read ADC");
            continue;
        }

        double voltage = (adc_value / ADC_RESOLUTION) * ADC_VREF * ADC_SENSITIVITY;

        if (voltage > ADC_HIGH_THRESHOLD) {
            printf("Alcohol detected! Limit exceeded.\n");
        } else if (voltage < ADC_LOW_THRESHOLD) {
            printf("Sobriety confirmed.\n");
        } else {
            printf("Alcohol level within acceptable range.\n");
        }

        log_measurement(ctime(&rawtime), adc_value);
        sleep(SAMPLE_INTERVAL / 1000);
    }

cleanup:
    if (gpio_req) {
        gpiod_line_release(gpio_req);
        gpiod_line_request_free(gpio_req);
    }

    if (spidev) {
        close(spidev->fd);
    }

    if (gpio_cb) {
        gpiod_line_request_set_callback(gpio_req, NULL);
    }

    if (log_file) {
        fclose(log_file);
    }

    return ret;
}
