code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define MCP3008_ADDR 0x68
#define MCP3008_REG_CONFIG 0x00
#define MCP3008_REG_CS 0x00
#define MCP3008_REG_DATA 0x02
#define MOTOR_PWM_FREQ 50
#define MOTOR_PWM_RANGE 100
#define POT_MIN 0
#define POT_MAX 1023
#define SPEED_FACTOR 10
#define DELAY_BETWEEN_DIRECTION_CHANGE 100000
#define NUM_ITERATIONS 5

struct adc_chan {
    int fd;
    struct spi_ioc_transfer transfer[3];
};

struct motor {
    int gpio_en;
    int gpio_dir;
    int pwm;
};

struct adc_chan adc[2];
struct motor motor[2];

void setup_adc(struct adc_chan *adc_chan, int channel) {
    adc_chan->fd = open("/dev/spidev0.0", O_RDWR);
    if (adc_chan->fd < 0) {
        perror("Can't open SPI device");
        exit(EXIT_FAILURE);
    }

    spi_ioc_transfer t = {
        .tx_buf = (unsigned char *)&channel,
        .bits_per_word = 8,
        .speed_hz = 1000000,
        .delay_usecs = 0,
        .len = sizeof(channel),
    };

    adc_chan->transfer[0] = t;

    t.tx_buf = (unsigned char *) &MCP3008_REG_CS;
    adc_chan->transfer[1] = t;

    t.tx_buf = (unsigned char *) &MCP3008_REG_DATA;
    adc_chan->transfer[2] = t;

    if (ioctl(adc_chan->fd, SPI_IOC_MESSAGE(3), adc_chan->transfer) < 1) {
        perror("Can't configure SPI transfer");
        exit(EXIT_FAILURE);
    }
}

int read_adc(struct adc_chan *adc_chan) {
    int data;
    if (ioctl(adc_chan->fd, SPI_IOC_MESSAGE(1), &adc_chan->transfer[1]) < 0) {
        perror("Can't read from ADC");
        exit(EXIT_FAILURE);
    }

    if (ioctl(adc_chan->fd, SPI_IOC_MESSAGE(1), &adc_chan->transfer[2]) < 0) {
        perror("Can't read from ADC");
        exit(EXIT_FAILURE);
    }

    memcpy(&data, adc_chan->transfer[2].rx_buf, sizeof(data));
    return data;
}

void setup_motor(struct motor *motor, int gpio_en, int gpio_dir) {
    motor->gpio_en = gpio_open_named(gpio_get_array_index(gpio_en));
    if (motor->gpio_en < 0) {
        perror("Can't open GPIO");
        exit(EXIT_FAILURE);
    }

    gpio_set_direction_output(motor->gpio_en, GPIOD_OUTPUT_HIGH);

    motor->gpio_dir = gpio_open_named(gpio_get_array_index(gpio_dir));
    if (motor->gpio_dir < 0) {
        perror("Can't open GPIO");
        exit(EXIT_FAILURE);
    }

    gpio_set_direction_output(motor->gpio_dir, GPIOD_OUTPUT_HIGH);

    motor->pwm = gpiod_claim_line(gpio_get_array_index(gpio_en), "motor_pwm");
    if (!motor->pwm) {
        perror("Can't claim PWM line");
        exit(EXIT_FAILURE);
    }

    gpiod_set_pwm_range(motor->pwm, MOTOR_PWM_RANGE);
    gpiod_set_pwm_frequency(motor->pwm, MOTOR_PWM_FREQ);
}

void drive_motor(struct motor *motor, int speed) {
    gpiod_set_pwm_duty_cycle(motor->pwm, speed * MOTOR_PWM_RANGE / SPEED_FACTOR);
}

void change_motor_direction(struct motor *motor) {
    gpio_write_raw(motor->gpio_dir, !gpio_read_raw(motor->gpio_dir));
}

void cleanup_adc(struct adc_chan *adc_chan) {
    close(adc_chan->fd);
}

void cleanup_motor(struct motor *motor) {
    gpiod_release_line(motor->pwm);
    gpio_free(motor->gpio_en);
    gpio_free(motor->gpio_dir);
}

void signal_handler(int signum) {
    printf("Received signal %d, exiting gracefully\n", signum);
    cleanup_adc(adc);
    cleanup_motor(motor);
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    setup_adc(adc + 0, 0);
    setup_adc(adc + 1, 1);

    setup_motor(motor + 0, 18, 23);
    setup_motor(motor + 1, 24, 25);

    for (int i = 0; i < NUM_ITERATIONS; ++i) {
        for (int j = POT_MIN; j <= POT_MAX; ++j) {
            int speed = (j - POT_MIN) * SPEED_FACTOR / (POT_MAX - POT_MIN);
            drive_motor(motor + 0, speed);
            drive_motor(motor + 1, speed);

            usleep(2000000); // 2 seconds

            for (int k = speed; k > 0; --k) {
                drive_motor(motor + 0, k);
                drive_motor(motor + 1, k);
                usleep(10000);
            }

            usleep(DELAY_BETWEEN_DIRECTION_CHANGE);

            change_motor_direction(motor + 0);
            change_motor_direction(motor + 1);
        }
    }

    cleanup_adc(adc);
    cleanup_motor(motor);

    return EXIT_SUCCESS;
}

