Create a file named `airflow_sensor.c` and paste the following code:

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include "mcp3008.h"

#define CS_GPIO 0
#define SPI_BUS 0
#define SPI_DEVICE 0
#define ADC_RESOLUTION 10
#define SAMPLE_INTERVAL_US 100000
#define ADC_MAX_VALUE 1023

static gpiod_line_request_lines_data_t cs_request_data = { .flags = GPIOD_LINE_REQUEST_INPUT };
static gpiod_line_data_t cs_line_data;
static gpiod_line_handle_t cs_line_handle;

static int spi_fd;
static struct spi_device *spi_dev;

static void handle_error(const char *message) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(stderr, "%s: %s\n", timestamp, message);
}

static int init_gpio() {
    gpiod_line_request_err err;

    err = gpiod_chip_open_byname("gpiochip0");
    if (err) {
        handle_error("Failed to open GPIO chip");
        return -1;
    }

    err = gpiod_line_request_get_byindex(err, CS_GPIO, &cs_request_data, &cs_line_handle);
    if (err) {
        handle_error("Failed to request GPIO line");
        gpiod_chip_close(err);
        return -1;
    }

    err = gpiod_line_get_data(cs_line_handle, &cs_line_data);
    if (err) {
        handle_error("Failed to get GPIO line data");
        gpiod_line_release(cs_line_handle);
        gpiod_chip_close(err);
        return -1;
    }

    cs_line_data.flags |= GPIOD_LINE_FLAG_INPUT;
    err = gpiod_line_set_data(cs_line_handle, &cs_line_data);
    if (err) {
        handle_error("Failed to set GPIO line data");
        gpiod_line_release(cs_line_handle);
        gpiod_chip_close(err);
        return -1;
    }

    return 0;
}

static int init_spi() {
    spi_dev = spi_open(SPI_BUS, SPI_DEVICE, 0);
    if (spi_dev < 0) {
        handle_error("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer transfer[1] = {
        {
            .tx_buf = (unsigned char*)&cs_line_data.value,
            .rx_buf = NULL,
            .len = sizeof(cs_line_data.value),
            .delay_usecs = 0,
            .speed_hz = 1000000,
            .bits_per_word = 8,
        }
    };

    if (spi_ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 1) {
        handle_error("Failed to configure SPI");
        spi_close(spi_fd);
        return -1;
    }

    return 0;
}

static int init_adc() {
    spi_fd = spi_open(SPI_BUS, SPI_DEVICE, 0);
    if (spi_fd < 0) {
        handle_error("Failed to open ADC SPI device");
        return -1;
    }

    return mcp3008_init(spi_fd, ADC_RESOLUTION);
}

static int init_log() {
    FILE *log_file = fopen("airflow_log.txt", "w");
    if (!log_file) {
        handle_error("Failed to open log file");
        return -1;
    }

    return 0;
}

static void cleanup() {
    if (spi_fd >= 0) {
        spi_close(spi_fd);
    }

    if (cs_line_handle >= 0) {
        gpiod_line_release(cs_line_handle);
    }

    if (gpiod_chip_is_open()) {
        gpiod_chip_close(0);
    }

    if (log_file) {
        fclose(log_file);
    }
}

static void signal_handler(int sig) {
    cleanup();
    exit(0);
}

int main() {
    int err;
    FILE *log_file;
    time_t now;
    char timestamp[20];

    signal(SIGINT, signal_handler);

    err = init_gpio();
    if (err) {
        return err;
    }

    err = init_spi();
    if (err) {
        return err;
    }

    err = init_adc();
    if (err) {
        return err;
    }

    err = init_log();
    if (err) {
        return err;
    }

    log_file = stdout;

    while (1) {
        int adc_value = mcp3008_read(spi_fd);
        if (adc_value < 0) {
            now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(log_file, "ERROR: ADC read failed at %s\n", timestamp);
        } else {
            now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            double airflow = convert_adc_to_airflow(adc_value);
            fprintf(log_file, "%s: ADC value: %d, Airflow: %.2f\n", timestamp, adc_value, airflow);
        }

        usleep(SAMPLE_INTERVAL_US);

        gpiod_line_set_value(cs_line_handle, !cs_line_data.value);
        struct spi_ioc_transfer transfer[1] = {
            {
                .tx_buf = NULL,
                .rx_buf = (unsigned char*)&cs_line_data.value,
                .len = sizeof(cs_line_data.value),
                .delay_usecs = 0,
                .speed_hz = 1000000,
                .bits_per_word = 8,
            }
        };

        if (spi_ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 1) {
            handle_error("Failed to configure SPI");
            break;
        }
    }

    cleanup();
    return 0;
}
