    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(ce0_chip);
        return 1;
    }

    gpiod_line_set_value(ce0_chip, ce0_request_data.line, 1);

    gpiod_chip *adc_cs_chip = gpiod_chip_open_byname(ADC_CS_GPIO_LINE);
    if (!adc_cs_chip) {
        perror("Failed to open ADC CS GPIO chip");
        gpiod_line_release(ce0_request_data.chip, ce0_request_data.line);
