    gpiod_line_set_value(gpio_chip_name, SPI_CS, 1);
    close(spi_fd);
    gpiod_line_release(gpio_chip_name, SPI_CS);
    exit(0);
}

int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Can't open SPI device");
        return -1;
    }

    transfer[0].tx_buf = (unsigned char*)&ADC_CHANNEL;
    transfer[0].rx_buf = (unsigned char*)malloc(sizeof(unsigned int));
    transfer[0].len = sizeof(ADC_CHANNEL);
    transfer[0].speed_hz = 1000000;

