    if (spi_xcv(spi_fd, transfer, 1) < 0) {
        perror("Can't read ADC");
        usleep(100000);
        return read_adc();
    }
    gpiod_line_set_value(gpio_chip_name, SPI_CS, 1);

    return *(unsigned int*)transfer[0].rx_buf;
}

void log_data(const char *filename, unsigned int voltage, unsigned int ppm) {
    FILE *file = fopen(filename, "a");
    if (!file) {
        perror("Can't open log file");
        return;
    }

    time_t rawtime;
    struct tm *timeinfo;
    char time_string[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(file, "%s, %u, %u\n", time_string, voltage, ppm);
