            perror("Failed to read ADC data");
            break;
        }

        dt = (float)clock() / CLOCKS_PER_SEC - last_time;
        last_time = (float)clock() / CLOCKS_PER_SEC;

        kalman_filter_update(&kf_x, x_raw * GRAVITY / ADC_REFERENCE);
        kalman_filter_update(&kf_y, y_raw * GRAVITY / ADC_REFERENCE);
        kalman_filter_update(&kf_z, z_raw * GRAVITY / ADC_REFERENCE);

        print_values(kf_x.x, kf_y.x, kf_z.x);
        usleep(100000);
    }

    mraa_spi_close(spi);
    mraa_gpio_close(cs);
    mraa_finalize();

    return 0;
