#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEV "/dev/spidev0.0"
#define GPIO_PIPE "gpiochip0"
#define GPIO_LINE "line17"
#define ADC_CHANNEL 0
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "watering.log"
#define LOG_BUFFER_SIZE 256

static gpiod_line_request_lines_data_t gpio_data;
static struct spidev *spidev;
static char spi_buffer[3];

void log_event(const char *event) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_string[80];
    char log_line[LOG_BUFFER_SIZE];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(log_line, sizeof(log_line), "%s: %s\n", time_string, event);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fputs(log_line, log_file);
        fclose(log_file);
    }
}

int adc_read() {
    if (spidev_xsputc(spidev, 0b11100001) < 0) {
        perror("Failed to write SPI command");
        return -1;
    }

    if (spidev_xread(spidev, spi_buffer, 3) != 3) {
        perror("Failed to read SPI data");
        return -1;
    }

    int adc_value = (spi_buffer[1] << 8) | spi_buffer[2];
    return adc_value / 1024.0 * 5.0;
}

int main() {
    int ret;

    spidev = spidev_open(SPI_DEV, 0);
    if (!spidev) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_lines(&gpio_data, 1, GPIO_PIPE, GPIO_LINE, GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_HIGH);
    if (gpio_data.lines[0].consumer_data == -1) {
        perror("Failed to request GPIO line");
        exit(EXIT_FAILURE);
    }

    log_event("Program started");

    while (1) {
        double moisture = adc_read();
        if (moisture < MOISTURE_THRESHOLD) {
            if (gpio_line_set_value_cansleep(&gpio_data.lines[0], 1) < 0) {
                perror("Failed to set GPIO line");
            }
            log_event("Pump turned on");
        } else if (gpio_line_get_value_cansleep(&gpio_data.lines[0]) == 1) {
            if (gpio_line_set_value_cansleep(&gpio_data.lines[0], 0) < 0) {
                perror("Failed to set GPIO line");
            }
            log_event("Pump turned off");
        }

        sleep(60);
    }

    gpiod_line_release_lines(&gpio_data, 1);
    spidev_close(spidev);

    log_event("Program terminated");
    return 0;
}

void signal_handler(int signum) {
    log_event("Received SIGINT or SIGTERM");
    gpiod_line_set_value_cansleep(&gpio_data.lines[0], 0);
    exit(EXIT_SUCCESS);
}

void setup_signals() {
    struct sigaction sa;

    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set up signal handlers");
    }
}

