#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_CS 27
#define SPI_SPEED 1000000
#define CHIP_SELECT (1 << SPI_CS)
#define BUFFER_SIZE 3

gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int lines,
                          const char *label, unsigned int flags)

int spi_xfer(int spi_fd, const unsigned char *tx_buf, unsigned char *rx_buf, size_t len)
{
    struct spi_ioc_transfer transfers[] = {
        {
            .tx_buf = tx_buf,
            .rx_buf = rx_buf,
            .len = len,
            .delay_usecs = 0,
            .speed_hz = SPI_SPEED,
        },
    };

    return ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfers);
}

void sigint_handler(int sig)
{
    printf("\nClosing SPI device and CSV file...\n");
    close(spi_fd);
    fclose(csv_file);
    gpiod_line_release_request(cs);
    exit(0);
}

int main()
{
    int spi_fd, csv_file;
    unsigned char read_buf[BUFFER_SIZE];
    unsigned char write_buf[BUFFER_SIZE];
    struct gpiod_chip *chip;
    struct gpiod_line *cs;
    struct timespec ts;
    int ret;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    cs = gpiod_chip_get_line(chip, SPI_CS);
    if (!cs) {
        perror("Failed to get GPIO line");
        gpiod_chip_put(chip);
        return 1;
    }

    ret = gpiod_line_request_active_low(cs, "SPI_CS");
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_put(cs);
        gpiod_chip_put(chip);
        return 1;
    }

    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpiod_line_release_request(cs);
        gpiod_chip_put(chip);
        return 1;
    }

    csv_file = fopen("sensor_data.csv", "w");
    if (!csv_file) {
        perror("Failed to open CSV file");
        close(spi_fd);
        gpiod_line_release_request(cs);
        gpiod_chip_put(chip);
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        write_buf[0] = 0b00100000 | (0 << 3); // Set CS low and select channel 0
        write_buf[1] = 0x00;
        write_buf[2] = 0x00;
        ret = spi_xfer(spi_fd, write_buf, NULL, BUFFER_SIZE);
        if (ret < 0) {
            perror("Failed to write to SPI device");
            fclose(csv_file);
            close(spi_fd);
            gpiod_line_release_request(cs);
            gpiod_chip_put(chip);
            return 1;
        }

        usleep(10); // Delay for MCP3008 to stabilize

        ret = spi_xfer(spi_fd, NULL, read_buf, BUFFER_SIZE);
        if (ret < 0) {
            perror("Failed to read from SPI device");
            fclose(csv_file);
            close(spi_fd);
            gpiod_line_release_request(cs);
            gpiod_chip_put(chip);
            return 1;
        }

        write_buf[0] = 0b00100001 | (1 << 3); // Set CS low and select channel 1
        ret = spi_xfer(spi_fd, write_buf, NULL, BUFFER_SIZE);
        if (ret < 0) {
            perror("Failed to write to SPI device");
            fclose(csv_file);
            close(spi_fd);
            gpiod_line_release_request(cs);
            gpiod_chip_put(chip);
            return 1;
        }

        usleep(10);

        ret = spi_xfer(spi_fd, NULL, read_buf + 2, BUFFER_SIZE - 2);
        if (ret < 0) {
            perror("Failed to read from SPI device");
            fclose(csv_file);
            close(spi_fd);
            gpiod_line_release_request(cs);
            gpiod_chip_put(chip);
            return 1;
        }

        write_buf[0] = 0b00100010 | (2 << 3); // Set CS low and select channel 2
        ret = spi_xfer(spi_fd, write_buf, NULL, BUFFER_SIZE);
        if (ret < 0) {
            perror("Failed to write to SPI device");
            fclose(csv_file);
            close(spi_fd);
            gpiod_line_release_request(cs);
            gpiod_chip_put(chip);
            return 1;
        }

        usleep(10);

        ret = spi_xfer(spi_fd, NULL, read_buf + 4, BUFFER_SIZE - 4);
        if (ret < 0) {
            perror("Failed to read from SPI device");
            fclose(csv_file);
            close(spi_fd);
            gpiod_line_release_request(cs);
            gpiod_chip_put(chip);
            return 1;
        }

        fprintf(csv_file, "%d,%d,%d\n", read_buf[0], read_buf[1], read_buf[2]);

        ts.tv_sec = 1;
        ts.tv_nsec = 0;
        nanosleep(&ts, NULL);
    }

    fclose(csv_file);
    close(spi_fd);
    gpiod_line_release_request(cs);
    gpiod_chip_put(chip);

    return 0;
}

