#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/types.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define GPIO_SENSOR_LINE 17
#define GPIO_ALARM_LINE 18

int main(void) {
    int ret;
    gpiod_line_request_flags_t flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_FALLING;
    gpiod_line_data_t sensor_data, alarm_data;
    gpiod_line_handle_t *sensor_line, *alarm_line;
    struct timespec delay = {0, 100 * 1e6};

    if ((ret = gpiod_library_open()) < 0) {
        perror("Failed to open gpiod library");
        return 1;
    }

    if ((sensor_line = gpiod_chip_get_line_byname("gpiochip0", GPIO_SENSOR_LINE)) == NULL) {
        perror("Failed to get sensor line");
        goto cleanup;
    }

    if ((ret = gpiod_line_request_dt(sensor_line, flags, "sound_sensor")) < 0) {
        perror("Failed to request sensor line");
        goto cleanup;
    }

    if ((alarm_line = gpiod_chip_get_line_byname("gpiochip0", GPIO_ALARM_LINE)) == NULL) {
        perror("Failed to get alarm line");
        goto cleanup;
    }

    if ((ret = gpiod_line_request_dt(alarm_line, GPIOD_LINE_REQUEST_OUTPUT, "alarm_led")) < 0) {
        perror("Failed to request alarm line");
        goto cleanup;
    }

    while (1) {
        ret = gpiod_line_get_value(sensor_line, &sensor_data);
        if (ret < 0) {
            perror("Failed to read sensor line");
            goto cleanup;
        }

        if (sensor_data.value == 0) {
            ret = gpiod_line_set_value(alarm_line, 1);
            if (ret < 0) {
                perror("Failed to set alarm line");
                goto cleanup;
            }

            nanosleep(&delay, NULL);

            ret = gpiod_line_set_value(alarm_line, 0);
            if (ret < 0) {
                perror("Failed to reset alarm line");
                goto cleanup;
            }
        }

        usleep(100000);
    }

cleanup:
    if (alarm_line) gpiod_line_release(alarm_line);
    if (sensor_line) gpiod_line_release(sensor_line);
    gpiod_library_close();

    return ret < 0 ? EXIT_FAILURE : EXIT_SUCCESS;
}

