#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <linux/types.h>
#include <libgpiod.h>

#define GPIO_CHIP_FILE "/dev/gpiochip0"
#define GPIO_LINE_NAME "vibration-monitor"
#define LOG_FILE "/var/log/vibration_shutdown.log"

volatile sig_atomic_t shutdown_requested = 0;

static void sigint_handler(int signum) {
    shutdown_requested = 1;
}

static void sigterm_handler(int signum) {
    shutdown_requested = 1;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line_request *request;
    struct gpiod_line_event event;
    int fd_log;
    char log_message[128];

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    if ((chip = gpiod_chip_open(GPIO_CHIP_FILE)) == NULL) {
        perror("gpiod_chip_open");
        return 1;
    }

    if ((request = gpiod_chip_get_line_request_byname(chip, GPIO_LINE_NAME)) == NULL) {
        perror("gpiod_chip_get_line_request_byname");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_direction_set(request, GPIOD_LINE_REQUEST_INPUT) < 0) {
        perror("gpiod_line_request_direction_set");
        gpiod_line_request_release(request);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_edge_detect_set(request, GPIOD_EDGE_FALLING) < 0) {
        perror("gpiod_line_request_edge_detect_set");
        gpiod_line_request_direction_set(request, GPIOD_LINE_REQUEST_OUTPUT);
        gpiod_line_request_release(request);
        gpiod_chip_close(chip);
        return 1;
    }

    if ((fd_log = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH)) < 0) {
        perror("open");
        gpiod_line_request_direction_set(request, GPIOD_LINE_REQUEST_OUTPUT);
        gpiod_line_request_release(request);
        gpiod_chip_close(chip);
        return 1;
    }

    while (!shutdown_requested) {
        if (gpiod_line_event_read(request, &event) >= 0) {
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            strftime(log_message, sizeof(log_message), "%Y-%m-%d %H:%M:%S - Vibration detected: %s\n", asctime(tm));
            write(fd_log, log_message, strlen(log_message));
            printf("%s", log_message);
            system("sudo shutdown -h now");
        }

        usleep(100000);
    }

    close(fd_log);
    gpiod_line_request_direction_set(request, GPIOD_LINE_REQUEST_OUTPUT);
    gpiod_line_request_release(request);
    gpiod_chip_close(chip);

    return 0;
}

