```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/time.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_ID 0x56

#define SDA_GPIO 2
#define SCL_GPIO 3

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int num_lines,
                                const char *const labels, unsigned int flags)
{
    return gpiod_chip_get_lines_request_array(chip, num_lines, labels, flags);
}

int main(void) {
    int i2c_fd, ret;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct timespec ts;
    struct gpiod_chip *chip;
    gpiod_line_request_lines_data_array_t gpio_req;
    uint8_t data[2];
    uint16_t chip_id;
    FILE *log_file;
    char timestamp[32];

    // Initialize GPIO
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    gpio_req.lines = calloc(2, sizeof(struct gpiod_line_request_data));
    gpio_req.num_lines = 2;
    gpio_req.labels = calloc(2, sizeof(const char*));
    gpio_req.flags = GPIOD_LINE_REQUEST_INPUT;
    gpio_req.lines[0].consumer = "BMP280 SDA";
    gpio_req.lines[1].consumer = "BMP280 SCL";

    ret = gpiod_chip_request_lines(chip, &gpio_req);
    if (ret < 0) {
        perror("Failed to request GPIO lines");
        goto cleanup_gpio;
    }

    gpiod_line_set_value_cansleep(chip->lines[gpio_req.lines[SDA_GPIO].offset], 1);
    gpiod_line_set_value_cansleep(chip->lines[gpio_req.lines[SCL_GPIO].offset], 1);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        goto cleanup_gpio;
    }

    // Initialize BMP280
    i2c_data.write_buf[0] = 0x2E; // Write to register 0x2E (software reset)
    ret = ioctl(i2c_fd, I2C_RDWR, &i2c_data);
    if (ret < 0) {
        perror("Failed to write to BMP280");
        goto cleanup_i2c;
    }

    usleep(100000); // Wait for BMP280 to reset

    i2c_data.write_buf[0] = 0xF4; // Write to register 0xF4 (write to control Measurement Mode 1)
    i2c_data.write_buf[1] = 0x26; // Oversampling settings: 16x pressure, 2x temperature
    ret = ioctl(i2c_fd, I2C_RDWR, &i2c_data);
    if (ret < 0) {
        perror("Failed to write to BMP280");
        goto cleanup_i2c;
    }

    // Read BMP280 chip ID
    i2c_data.write_buf[0] = 0xAA; // Write to register 0xAA (read chip ID)
    i2c_data.read_buf = data;
    i2c_data.nmsgs = 1;
    ret = ioctl(i2c_fd, I2C_RDWR, &i2c_data);
