#define BH1750_ADDR 0x23
#define MAX4466_CHAN0 0
#define MCP3008_ADDR 0x68

#define BUFFER_SIZE 1

int open_i2c_device(int addr) {
    int file;
    if ((file = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(file, I2C_SLAVE, addr) < 0) {
        perror("Failed to acquire I2C bus access");
        close(file);
        return -1;
    }

    return file;
}

int read_bh1750(int file) {
    char buf[2];
    int ret;

    ret = i2c_smbus_read_word_data(file, 0x23);
    if (ret < 0) {
        perror("Failed to read BH1750");
        return -1;
    }

    return (ret >> 4) * 25 + (ret & 0x0F);
}

int read_max4466(int spi_fd, int channel) {
    unsigned int data;
    char buf[3];

    buf[0] = 0x01 | (channel << 2);
    buf[1] = 0x00;
    buf[2] = 0x00;

    if (write(spi_fd, buf, 3) != 3) {
        perror("Failed to write to MAX4466");
        return -1;
    }

    if (read(spi_fd, &data, 3) != 3) {
        perror("Failed to read from MAX4466");
        return -1;
    }

    data = (data >> (8 - channel * 2)) & ((1 << channel * 2) - 1);

    return data;
}

int open_spi_device(int dev_id, int mode) {
    int fd;

    if ((fd = open("/dev/spidev" + to_string(dev_id), O_RDWR)) < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &8) < 0) {
        perror("Failed to set SPI data bits");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &1000000) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

int main() {
    int i2c_file, spi_fd, file;
    char log_file[] = "environmental_log.txt";
    struct spi_device_id *id;
    int ret;

    i2c_file = open_i2c_device(BH1750_ADDR);
    if (i2c_file < 0) {
        exit(EXIT_FAILURE);
    }

    spi_fd = open_spi_device(0, SPI_MODE_0);
    if (spi_fd < 0) {
        exit(EXIT_FAILURE);
    }

    if ((file = open(log_file, O_WRONLY | O_APPEND | O_CREAT, 0644)) < 0) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    while (1) {
        int light = read_bh1750(i2c_file);
        int sound = read_max4466(spi_fd, MAX4466_CHAN0);

        if (light < 0 || sound < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char time_str[32];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm);

        fprintf(file, "%s, Light: %d, Sound: %d\n", time_str, light, sound);
        fflush(file);

        sleep(1);
    }

    close(file);
    close(spi_fd);
    close(i2c_file);

    return 0;
}

