#define TMP36_BCOEF 3300
#define TMP36_MCOEF 100

struct adc_data {
    int raw;
    double temp_c;
    double dac_voltage;
};

int init_gpio(int gpio) {
    int ret;
    gpiod_line_request_dt_byname("rpi", "gpio-" + std::to_string(gpio));
    gpiod_line_get_raw_value_cansleep(gpio_get_line_data(gpio));
    ret = gpiod_line_set_value(gpio_get_line_data(gpio), 0);
    if (ret < 0) {
        perror("Failed to set MCP3008 CS low");
        return -1;
    }
    return 0;
}

int init_spi(const char *device) {
    int ret, fd;
    struct spi_ioc_transfer transfers[1];

    fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    transfers[0].tx_buf = (unsigned char*)&(uint8_t){0};
    transfers[0].rx_buf = (unsigned char*)&(uint16_t){0};
    transfers[0].len = 0;
    transfers[0].speed_hz = 500000;

    ret = ioctl(fd, SPI_IOC_MESSAGE(1), transfers);
    if (ret < 1) {
        perror("Failed to configure SPI");
        close(fd);
        return -1;
    }

    return fd;
}

int init_i2c(int addr) {
    int ret, fd;

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to acquire I2C address");
        close(fd);
        return -1;
    }

    return fd;
}

double read_tmp36(int spi_fd) {
    int ret;
    uint16_t adc_value;

    ret = write(spi_fd, (const char*)&(uint8_t){(TMP36_ADC_CHANNEL << 6) | (1 << 3) | (1 << 2)}, 3);
    if (ret != 3) {
        perror("Failed to write to ADC");
        return NAN;
    }

    ret = read(spi_fd, (char*)&adc_value, 2);
    if (ret != 2) {
        perror("Failed to read from ADC");
        return NAN;
    }

    adc_value = (adc_value >> 2) & 0x0FFF;
    return (adc_value / TMP36_BCOEF) - (273.15 + (adc_value % TMP36_BCOEF) / TMP36_MCOEF / TMP36_BCOEF * TMP36_VREF);
}

void write_dac(int i2c_fd, double voltage) {
    uint16_t dac_value = (voltage / TMP36_VREF) * 4095;
    uint8_t data[2];

    data[0] = (dac_value >> 8) & 0xFF;
    data[1] = dac_value & 0xFF;

    write(i2c_fd, data, 2);
}

int main() {
    int gpio_fd, spi_fd, i2c_fd;
    struct adc_data data;
    time_t timestamp;
    FILE *log_file;

    gpio_fd = gpiod_get_index_from_name("rpi", "gpio-" + std::to_string(MCP3008_CS_GPIO));
    if (gpio_fd < 0) {
        perror("Failed to get GPIO handle");
        return -1;
    }

    spi_fd = init_spi("/dev/spidev0.0");
    if (spi_fd < 0) {
        return -1;
    }

    i2c_fd = init_i2c(MCP4725_ADDR);
    if (i2c_fd < 0) {
        return -1;
    }

    if (init_gpio(MCP3008_CS_GPIO) < 0) {
        return -1;
    }

    log_file = fopen("temperature_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return -1;
    }

    while (1) {
        data.raw = read_tmp36(spi_fd);
        if (data.raw == NAN) {
            continue;
        }

        data.temp_c = data.raw;
        data.dac_voltage = data.temp_c * TMP36_VREF / 300;
        write_dac(i2c_fd, data.dac_voltage);

        timestamp = time(NULL);
        fprintf(log_file, "%s %d %f %f\n", ctime(&timestamp), data.raw, data.temp_c, data.dac_voltage);
        fprintf(stdout, "%s %d %f %f\n", ctime(&timestamp), data.raw, data.temp_c, data.dac_voltage);

        usleep(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    gpiod_line_release(gpio_get_line_data(MCP3008_CS_GPIO));
    close(spi_fd);
    close(i2c_fd);

    return 0;
}

