#include <libgpiod.h>

#define SPI_BUS 0
#define SPI_DEVICE 0
#define CS_GPIO 18
#define MOISTURE_SENSORS 3

static const char *const gpio_label[] = { "SENSOR_0", "SENSOR_1", "SENSOR_2" };

int init_gpio(void) {
    gpiod_line_request_array_withflags(3, gpio_label, GPIOD_LINE_REQUEST_INPUT, NULL);
    if (gpiod_line_get_value(gpio_get_line_byname("SENSOR_0")) ||
        gpiod_line_get_value(gpio_get_line_byname("SENSOR_1")) ||
        gpiod_line_get_value(gpio_get_line_byname("SENSOR_2"))) {
        fprintf(stderr, "Error: All GPIO lines should be in a high state\n");
        return 1;
    }
    return 0;
}

int init_spi(void) {
    int spi_fd = open("/dev/spidev" SPI_BUS, O_RDWR);
    if (spi_fd < 0) {
        perror("Cannot open SPI device");
        return 1;
    }

    if (ioctl(spi_fd, SPI_OPEN_MODE, SPI_MODE_0) < 0) {
        perror("Cannot set SPI mode");
        close(spi_fd);
        return 1;
    }

    if (ioctl(spi_fd, SPI_CPHA, 0) < 0) {
        perror("Cannot set SPI CPHA");
        close(spi_fd);
        return 1;
    }

    if (ioctl(spi_fd, SPI_CPOL, 0) < 0) {
        perror("Cannot set SPI CPOL");
        close(spi_fd);
        return 1;
    }

    if (ioctl(spi_fd, SPI_MAX_SPEED_HZ, 1000000) < 0) {
        perror("Cannot set SPI speed");
        close(spi_fd);
        return 1;
    }

    if (gpio_set_value(gpio_get_line_byname(CS_GPIO), 1)) {
        perror("Cannot set CS GPIO high");
        close(spi_fd);
        return 1;
    }

    return spi_fd;
}

uint16_t read_adc(int spi_fd) {
    const uint8_t command = 0x01;
    uint8_t buffer[3];

    if (gpio_set_value(gpio_get_line_byname(CS_GPIO), 0)) {
        perror("Cannot set CS GPIO low");
        close(spi_fd);
        return 0;
    }

    if (write(spi_fd, &command, 1) != 1) {
        perror("Cannot write command");
        gpio_set_value(gpio_get_line_byname(CS_GPIO), 1);
        close(spi_fd);
        return 0;
    }

    if (read(spi_fd, buffer, 3) != 3) {
        perror("Cannot read data");
        gpio_set_value(gpio_get_line_byname(CS_GPIO), 1);
        close(spi_fd);
        return 0;
    }

    gpio_set_value(gpio_get_line_byname(CS_GPIO), 1);

    uint16_t result = (buffer[1] << 8) | buffer[2];

    if (result > 0x3FF) {
        fprintf(stderr, "Error: Invalid ADC value\n");
        return 0;
    }

    return result;
}

void log_data(const char *filename, uint16_t *data, size_t size) {
    FILE *file = fopen(filename, "a");
    if (!file) {
        perror("Cannot open log file");
        return;
    }

    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(file, "%s ", timestamp);

    for (size_t i = 0; i < size; ++i) {
        fprintf(file, "%u ", data[i]);
    }
    fprintf(file, "\n");
    fclose(file);
}

void signal_handler(int signum) {
    if (signum == SIGINT) {
        gpiod_line_release(gpio_get_line_byname(CS_GPIO));
        gpiod_line_release_array(3, gpio_label);
        close(spi_fd);
        fprintf(stderr, "Goodbye\n");
        exit(0);
    }
}

int main(void) {
    if (init_gpio()) {
        return 1;
    }

    spi_fd = init_spi();
    if (spi_fd < 0) {
        return 1;
    }

    signal(SIGINT, signal_handler);

    for (int cycle = 1; ; ++cycle) {
        uint16_t data[MOISTURE_SENSORS];
        for (size_t i = 0; i < MOISTURE_SENSORS; ++i) {
            data[i] = read_adc(spi_fd);
            if (!data[i]) {
                fprintf(stderr, "Error: Failed to read ADC value\n");
                goto cleanup;
            }
        }

        log_data("soil_data.txt", data, MOISTURE_SENSORS);
        sleep(60);
    }

cleanup:
    gpiod_line_release(gpio_get_line_byname(CS_GPIO));
    gpiod_line_release_array(3, gpio_label);
    close(spi_fd);

    return 1;
}

