Here's the C code for the light sequencer:

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <linux/gpio/consumer.h>
#include <sys/ioctl.h>

#define RELAY_PIN_1 17
#define RELAY_PIN_2 22
#define RELAY_PIN_3 23
#define RELAY_PIN_4 24
#define DELAY_MS 1000

gpiod_line_request_linestate_vlinestate_cb_t relay_cb;
gpiod_line_request_data_t relay_req[4];
gpiod_line_data_vlinestate_t relay_state[4];

void relay_cb(struct gpiod_line *line, int event, void *user_data) {
    if (event == GPIOD_LINE_EVENT_LEVEL_CHANGE) {
        printf("Relay %d state changed\n", line->number);
    }
}

void deinit_relays() {
    for (int i = 0; i < 4; i++) {
        gpiod_line_release(relay_req[i].lines[0]);
    }
}

void handle_signal(int sig) {
    printf("Received signal %d, deactivating all relays and exiting...\n", sig);
    deinit_relays();
    exit(0);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int fd = gpiod_library_open();
    if (fd < 0) {
        perror("Failed to open gpiod library");
        return 1;
    }

    for (int i = 0; i < 4; i++) {
        relay_req[i].flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_HIGH;
        relay_req[i].consumer = "relay_sequencer";

        int ret = gpiod_chip_request_line(fd, bcm2835_gpio_get_chip(RELAY_PIN_1 + i), &relay_req[i]);
        if (ret < 0) {
            perror("Failed to request line");
            deinit_relays();
            return 1;
        }

        gpiod_line_get_value(relay_req[i].lines[0], relay_state + i);
        printf("Relay %d initial state: %s\n", i + 1, relay_state[i] ? "active" : "inactive");
    }

    for (int i = 0; i < 4; i++) {
        gpiod_line_set_value(relay_req[i].lines[0], 1);
        gpiod_line_get_value(relay_req[i].lines[0], relay_state + i);
        printf("Activating relay %d\n", i + 1);
        sleep(DELAY_MS / 1000.0);
        gpiod_line_set_value(relay_req[i].lines[0], 0);
        gpiod_line_get_value(relay_req[i].lines[0], relay_state + i);
        printf("Deactivating relay %d\n", i + 1);
        sleep(DELAY_MS / 1000.0);
    }

    deinit_relays();
    gpiod_library_close(fd);

    return 0;
}
