#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define ADC_CS_GPIO 8
#define LED_GPIO 16
#define ADC_CHANNEL 0
#define SAMPLE_INTERVAL 10000
#define THRESHOLD 500
#define DEBOUNCE_DELAY 500000
#define LOG_FILE "sound_events.log"

static int spi_fd;
static struct spi_device *spi;
static gpiod_line_request_lines_data_t gpio_req_data[] = {
    {LED_GPIO, GPIOD_LINE_REQUEST_DIRECTION_OUT, GPIOD_LINE_STATE_LOW},
};
static gpiod_line_handle_t gpio_handles[ARRAY_SIZE(gpio_req_data)];

void sigint_handler(int signum) {
    printf("Received SIGINT, cleaning up...\n");

    gpiod_line_set_value_cansleep(gpio_handles[LED_GPIO], 0);
    gpiod_line_release(gpio_handles[LED_GPIO]);

    gpiod_line_release_request(gpio_req_data, ARRAY_SIZE(gpio_req_data));
    close(spi_fd);

    exit(0);
}

int init_gpio() {
    int ret;

    ret = gpiod_library_open();
    if (ret < 0) {
        perror("gpiod_library_open");
        return -1;
    }

    ret = gpiod_chip_open_byname("gpiochip0");
    if (ret < 0) {
        perror("gpiod_chip_open_byname");
        return -1;
    }

    ret = gpiod_line_request_array_data(gpio_req_data, ARRAY_SIZE(gpio_req_data), &gpio_handles[0]);
    if (ret < 0) {
        perror("gpiod_line_request_array_data");
        return -1;
    }

    signal(SIGINT, sigint_handler);

    return 0;
}

int init_spi() {
    char spi_dev_path[32];
    snprintf(spi_dev_path, sizeof(spi_dev_path), "/dev/spidev%d.0", ADC_CS_GPIO);

    spi_fd = open(spi_dev_path, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    spi = spi_open(spi_fd, 0);
    if (!spi) {
        perror("Failed to open SPI device");
        return -1;
    }

    spi->mode = SPI_MODE_0;
    spi->max_speed_hz = 1000000;
    spi->bits_per_word = 8;

    if (spi_xcv(spi, &spi->max_speed_hz) < 0) {
        perror("Failed to set SPI speed");
        return -1;
    }

    return 0;
}

uint16_t read_adc() {
    uint8_t buf[3];
    int ret;

    buf[0] = 0x00;
    buf[1] = (ADC_CHANNEL << 6) | (0x03 & 0x3F);

    ret = write(spi_fd, buf, 2);
    if (ret != 2) {
        perror("Failed to write to SPI device");
        return 0;
    }

    ret = read(spi_fd, buf + 2, 1);
    if (ret != 1) {
        perror("Failed to read from SPI device");
        return 0;
    }

    return (buf[2] << 8) | buf[3];
}

void log_event(const char *message) {
    FILE *log_file;
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[26];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s: %s\n", time_str, message);
    fclose(log_file);
}

int main() {
    int ret;
    uint16_t adc_value;
    struct timespec delay;

    if (init_gpio() < 0) {
        return 1;
    }

    if (init_spi() < 0) {
        return 1;
    }

    gpiod_line_set_value_cansleep(gpio_handles[LED_GPIO], 0);

    while (1) {
        adc_value = read_adc();
        if (adc_value > THRESHOLD) {
            gpiod_line_set_value_cansleep(gpio_handles[LED_GPIO], 1);
            log_event("Sound event detected");
            nanosleep(&delay, NULL);
            nanosleep(&DEBOUNCE_DELAY, NULL);
            gpiod_line_set_value_cansleep(gpio_handles[LED_GPIO], 0);
        }

        nanosleep(&SAMPLE_INTERVAL, NULL);
    }

    return 0;
}
