#define RAIN_THRESHOLD 5
#define MOTOR_FORWARD 1
#define MOTOR_REVERSE 0
#define PWM_DUTY_MAX 255
#define PWM_DUTY_MIN 150

volatile sig_atomic_t stop = 0;

void motor_control(int dir, int duty_cycle) {
    static gpiod_line_request_linestate_v2_t state = GPIOD_LINE_REQUEST_LINESTATE_LOW;
    static gpiod_line_request_data_v2_t data = { .flags = GPIOD_LINE_REQUEST_DATA_OUTPUT };
    gpiod_line_handle_v2_t *gpio_handle;
    int ret;

    if ((ret = gpiod_get_array_size(gpio_chip)) < 0) {
        perror("gpiod_get_array_size");
        exit(EXIT_FAILURE);
    }

    if ((gpio_handle = gpiod_get_line_v2(gpio_chip, GPIO_MFD_LINE(17))) < 0) {
        perror("gpiod_get_line_v2");
        exit(EXIT_FAILURE);
    }

    if ((ret = gpiod_line_request_dbus(gpio_handle, "motor", GPIOD_LINE_REQUEST_DIRECTION_OUT, &data)) < 0) {
        perror("gpiod_line_request_dbus");
        exit(EXIT_FAILURE);
    }

    data.u32 = (dir == MOTOR_FORWARD) ? PWM_DUTY_MAX : PWM_DUTY_MIN;
    data.u32 = (data.u32 * duty_cycle) / PWM_DUTY_MAX;

    if ((ret = gpiod_line_set_value_cansleep(gpio_handle, data.u32, -1)) < 0) {
        perror("gpiod_line_set_value_cansleep");
        exit(EXIT_FAILURE);
    }

    usleep(3000000); // Sleep for 3 seconds

    if ((ret = gpiod_line_set_value_cansleep(gpio_handle, state.u32, -1)) < 0) {
        perror("gpiod_line_set_value_cansleep");
        exit(EXIT_FAILURE);
    }

    if ((ret = gpiod_line_release(gpio_handle)) < 0) {
        perror("gpiod_line_release");
        exit(EXIT_FAILURE);
    }
}

void log_rain_level(int level) {
    FILE *log_file;
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[80];

    if ((log_file = fopen("rain_log.txt", "a")) == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    rawtime = time(NULL);
    timeinfo = localtime(&rawtime);

    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s: Rain level: %d\n", time_str, level);
    fflush(log_file);

    if (fclose(log_file) != 0) {
        perror("fclose");
        exit(EXIT_FAILURE);
    }
}

void spi_transfer(unsigned char *tx_buf, unsigned char *rx_buf, size_t len) {
    int spi_fd;
    struct spi_ioc_transfer spi_transfers[1];
    int ret;

    if ((spi_fd = open(SPI_DEVICE, O_RDWR)) < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    spi_transfers[0].tx_buf = tx_buf;
    spi_transfers[0].rx_buf = rx_buf;
    spi_transfers[0].len = len;
    spi_transfers[0].speed_hz = SPI_SPEED_HZ;
    spi_transfers[0].bits_per_word = 8;
    spi_transfers[0].cs_change = SPI_LO_POLARITY_MODE3;

    if ((ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), spi_transfers)) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    if (close(spi_fd) < 0) {
        perror("close");
        exit(EXIT_FAILURE);
    }
}

void read_rain_level() {
    unsigned char tx_buf[2] = {0};
    unsigned char rx_buf[3] = {0};
    int ret;

    tx_buf[0] = 0x00;
    tx_buf[1] = MCP3008_CS << 5;

    spi_transfer(tx_buf, rx_buf, sizeof(rx_buf));

    if (rx_buf[1] & (1 << 7)) {
        fprintf(stderr, "Error reading ADC\n");
        exit(EXIT_FAILURE);
    }

    int level = (rx_buf[2] << 8) | rx_buf[3];
    level >>= (8 - 10); // Shift right by 2 bits to get 10-bit value

    if (level > RAIN_THRESHOLD) {
        motor_control(MOTOR_FORWARD, PWM_DUTY_MAX - PWM_DUTY_MIN);
    } else {
        motor_control(MOTOR_REVERSE, PWM_DUTY_MAX - PWM_DUTY_MIN);
    }

    log_rain_level(level);
}

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    struct gpiod_chip *gpio_chip;
    int ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if ((gpio_chip = gpiod_chip_open_by_name("gpiochip0")) < 0) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    while (!stop) {
        read_rain_level();
        sleep(1);
    }

    if ((ret = gpiod_chip_close(gpio_chip)) < 0) {
        perror("gpiod_chip_close");
        exit(EXIT_FAILURE);
    }

    return 0;
}

