This code assumes that the MCP3008 is connected to the Raspberry Pi's SPI bus on channel 0 and the L298N DC motor driver is connected to GPIO17, GPIO18, and GPIO27. Make sure to adjust the GPIO pins if you're using a different setup.

code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <time.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define ADC_GPIO_LINE "gpiochip0"
#define ADC_GPIO_PIN 26
#define LED_GPIO_LINE "gpiochip0"
#define LED_GPIO_PIN 16
#define SAMPLES_PER_READ 128
#define ADC_RESOLUTION 12
#define DEBOUNCE_INTERVAL 50
#define LED_ON_DURATION 500
#define I2C_ADDR 0x36 // MAX9814 I2C address

struct adc_data {
    uint16_t samples[SAMPLES_PER_READ];
    uint32_t sum;
};

void sigint_handler(int sig) {
    gpiod_set_value_cansleep(led_gpio_handle, 0);
    gpiod_release(led_gpio_handle);
    gpiod_release(adc_gpio_handle);
    exit(0);
}

int read_adc(struct adc_data *data) {
    int i;
    uint32_t adc_value;

    gpiod_line_request_dt_byname(adc_gpio_handle, "gpio-gpiochip0-line26");

    for (i = 0; i < SAMPLES_PER_READ; i++) {
        gpiod_line_set_value(adc_gpio_handle, ADC_GPIO_PIN, 1);
        usleep(2);
        gpiod_line_set_value(adc_gpio_handle, ADC_GPIO_PIN, 0);
        usleep(1);

        adc_value = gpiod_line_get_value(adc_gpio_handle, ADC_GPIO_PIN);
        data->samples[i] = (adc_value > 1) ? (adc_value - 1) : 0;
    }

    gpiod_line_release(adc_gpio_handle, ADC_GPIO_PIN);

    data->sum = 0;
    for (i = 0; i < SAMPLES_PER_READ; i++)
        data->sum += data->samples[i];
    data->sum /= SAMPLES_PER_READ;

    return 0;
}

int main() {
    int i2c_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct adc_data adc_data;
    struct timespec ts_start, ts_end;
    int clap_detected = 0;

    signal(SIGINT, sigint_handler);

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    if (i2c_smbus_write_byte_data(i2c_fd, I2C_ADDR, 0x01) < 0) {
        perror("Failed to write to I2C device");
        exit(1);
    }

    if ((adc_gpio_handle = gpiod_open(ADC_GPIO_LINE, GPIOD_LINE_REQUEST_INPUT, "max9814-adc")) < 0) {
        perror("Failed to open ADC GPIO line");
        exit(1);
    }

    if ((led_gpio_handle = gpiod_open(LED_GPIO_LINE, GPIOD_LINE_REQUEST_OUTPUT, "clap-detection-led")) < 0) {
        perror("Failed to open LED GPIO line");
        exit(1);
    }

    gpiod_line_set_value(led_gpio_handle, LED_GPIO_PIN, 0);

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts_start);

        if (read_adc(&adc_data) < 0) {
            perror("Failed to read ADC");
            continue;
        }

        if (adc_data.sum > 1000) {
            clock_gettime(CLOCK_MONOTONIC, &ts_end);
            double elapsed = (ts_end.tv_sec - ts_start.tv_sec) +
                             (ts_end.tv_nsec - ts_start.tv_nsec) / 1_ billion;

            if (elapsed > DEBOUNCE_INTERVAL) {
                clap_detected = 1;
                gpiod_line_set_value(led_gpio_handle, LED_GPIO_PIN, 1);
                printf("Clap detected at %f seconds\n", ts_start.tv_sec + ts_start.tv_nsec / 1_ billion);
            }
        } else {
            if (clap_detected) {
                gpiod_line_set_value(led_gpio_handle, LED_GPIO_PIN, 1);
                usleep(LED_ON_DURATION * 1000);
                gpiod_line_set_value(led_gpio_handle, LED_GPIO_PIN, 0);
                clap_detected = 0;
            }
        }

        usleep(10000); // 10ms loop delay
    }

    gpiod_line_release(led_gpio_handle, LED_GPIO_PIN);
    gpiod_release(adc_gpio_handle);
    close(i2c_fd);

    return 0;
}

