        perror("Failed to open ADC GPIO line");
        exit(1);
    }

    if ((led_gpio_handle = gpiod_open(LED_GPIO_LINE, GPIOD_LINE_REQUEST_OUTPUT, "clap-detection-led")) < 0) {
        perror("Failed to open LED GPIO line");
        exit(1);
    }

    gpiod_line_set_value(led_gpio_handle, LED_GPIO_PIN, 0);

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts_start);

        if (read_adc(&adc_data) < 0) {
            perror("Failed to read ADC");
            continue;
        }

        if (adc_data.sum > 1000) {
            clock_gettime(CLOCK_MONOTONIC, &ts_end);
            double elapsed = (ts_end.tv_sec - ts_start.tv_sec) +
                             (ts_end.tv_nsec - ts_start.tv_nsec) / 1_ billion;

            if (elapsed > DEBOUNCE_INTERVAL) {
                clap_detected = 1;
                gpiod_line_set_value(led_gpio_handle, LED_GPIO_PIN, 1);
                printf("Clap detected at %f seconds\n", ts_start.tv_sec + ts_start.tv_nsec / 1_ billion);
            }
        } else {
            if (clap_detected) {
                gpiod_line_set_value(led_gpio_handle, LED_GPIO_PIN, 1);
                usleep(LED_ON_DURATION * 1000);
                gpiod_line_set_value(led_gpio_handle, LED_GPIO_PIN, 0);
                clap_detected = 0;
            }
        }

        usleep(10000); // 10ms loop delay
    }

    gpiod_line_release(led_gpio_handle, LED_GPIO_PIN);
    gpiod_release(adc_gpio_handle);
    close(i2c_fd);

    return 0;
}
