```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <time.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BAUD 1000000
#define ADC_CS_GPIO 11
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "soil_moisture.log"

int spi_xfer(unsigned char *tx_buf, unsigned char *rx_buf, int len) {
    int fd = open(SPI_DEV, O_RDWR);
    if (fd < 0) {
        perror("Can't open SPI device");
        return -1;
    }

    struct spi_ioc_transfer tr = {
        .tx_buf = tx_buf,
        .rx_buf = rx_buf,
        .len = len,
        .delay_usecs = 0,
        .speed_hz = SPI_BAUD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Can't perform SPI xfer");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int main() {
    gpiod_line_request_lines(NULL, 2, "moisture_sensor_and_pump", GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_HIGH, NULL);
    gpio_t moisture_sensor = gpiod_get_line(0, "moisture_sensor");
    gpio_t pump = gpiod_get_line(0, "pump");

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    int last_moisture = 0;

    while (1) {
        unsigned char adc_data[3];
        spi_xfer(&(unsigned char){0x00, 0x00, 0x00}, adc_data, 3);
        int moisture = (adc_data[1] << 8) | adc_data[2];

        if (moisture < 0 || moisture > 1023) {
            printf("Invalid ADC reading: %d\n", moisture);
            continue;
        }

        gpiod_line_get_value_async(moisture_sensor, NULL, [moisture](int value, void *user_data) {
            if (value == 1) {
                last_moisture = moisture;
                if (last_moisture < MOISTURE_THRESHOLD) {
                    gpiod_line_set_value(pump, 1);
                }
            }
        });

        clock_gettime(CLOCK_REALTIME, &ts);
        char log_line[128];
        snprintf(log_line, sizeof(log_line), "%lld, %d, %s\n", ts.tv_sec, last_moisture, (last_moisture < MOISTURE_THRESHOLD) ? "ON" : "OFF");
        FILE *log_file = fopen(LOG_FILE, "a");
        fputs(log_line, log_file);
        fclose(log_file);

        sleep(60);
    }

    gpiod_line_release(moisture_sensor);
    gpiod_line_release(pump);
    gpiod_shutdown();

    return 0;
}
```

This code initializes the SPI device, requests the GPIO lines for the moisture sensor and pump, and sets up an asynchronous callback to handle the moisture sensor's value changes. It samples the moisture level every 60 seconds, logs the moisture percentage and pump status to a file, and activates the pump when the moisture level falls below the defined threshold.

Please note that this code does not include the ADC conversion function, as it would require additional libraries and is beyond the scope of this example. You can find an example of ADC conversion using the MCP3008 with the `spidev` library in the Raspberry Pi documentation: https://www.raspberrypi.org/documentation/usage/spi/wiringpi.md#mcp3008-adc-chip

