    struct spi_ioc_master spi = {
        .mode = SPI_MODE,
        .max_speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_WRITE_MODE, &spi) < 1) {
