    spi_transfers[0].rx_buf = spi_buffer;
    spi_transfers[0].len = SPI_BITS / 8;
    spi_transfers[0].speed_hz = SPI_SPEED;
    spi_transfers[0].bits_per_word = SPI_BITS;

    return 0;

cleanup_spi:
    close(spi_fd);
    return -1;
}

int read_adc() {
    int ret = xfer(spi_fd, spi_transfers, 1);
    if (ret < 0) {
