        return -1;
    }

    uint16_t adc_value = (uint16_t)spi_buffer[0];
    return adc_value;
}

float convert_adc_to_magnetic_field(uint16_t adc_value) {
    // Replace this formula with the correct one for the DRV5055-A1 sensor
    return adc_value * 0.0005f;
}

int main() {
