        goto cleanup_gpio;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        goto cleanup_spi;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    uint64_t last_sample_time = ts.tv_sec * 1000000 + ts.tv_nsec / 1000;

    while (1) {
        gpiod_line_get_value_cansleep(gpio_fd, GPIO_LINE);

        uint16_t adc_value = read_adc();
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC\n");
            continue;
        }

        float magnetic_field = convert_adc_to_magnetic_field(adc_value);
        struct timespec current_time;
        clock_gettime(CLOCK_REALTIME, &current_time);
        uint64_t current_sample_time = current_time.tv_sec * 1000000 + current_time.tv_nsec / 1000;

        if (current_sample_time - last_sample_time >= SAMPLE_INTERVAL) {
            fprintf(log_file, "%llu,%f\n", last_sample_time, magnetic_field);
            last_sample_time = current_sample_time;
        }

        usleep(SAMPLE_INTERVAL - (current_sample_time - last_sample_time));
    }

cleanup_spi:
    close(spi_fd);
cleanup_gpio:
    gpiod_line_release_lines(gpio_fd, 1, gpio_lines, NULL);
    close(gpio_fd);
    fclose(log_file);

    return 0;
}

