    if (gpiod_line_request_direction_output(ce_request, 0) < 0) {
        perror("Can't set GPIO line direction");
        gpiod_line_request_free(ce_request);
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
