        gpiod_line_set_value(ce_request, 1);

        // Extract raw ADC value from received data
        int raw_value = (buf[0] << 8) | buf[1];

        // Format and write the timestamp and raw value to the log file
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL)));
        fprintf(log_file, "%s %d\n", timestamp, raw_value);

        // Sleep for 60 seconds
        ts.tv_sec = 60;
        ts.tv_nsec = 0;
        nanosleep(&ts, NULL);
    }

    // Clean up resources on SIGINT
    signal(SIGINT, [](int signum) {
        gpiod_line_request_free(ce_request);
        gpiod_chip_close(chip);
        close(spi_fd);
        fclose(log_file);
        exit(EXIT_SUCCESS);
    });

    return 0;
}

