```

Here's the C code:

```c
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <linux/spi/spidev.h>

#define SPI_DEV "/dev/spidev0.0"
#define GPIO_PIN 17
#define CS 0
#define AD0 1
#define MODE3 3

int spi_fd, gpio_fd;
char current_log_path[] = "current_log.txt";

void sigint_handler(int signum) {
    printf("\nClean shutdown initiated...\n");

    if (gpio_fd != -1) {
        if (ioctl(gpio_fd, GPIO_CLR, GPIO_PIN) < 0) {
            perror("Failed to clear GPIO");
        }
        close(gpio_fd);
    }

    if (spi_fd != -1) {
        close(spi_fd);
    }

    if (remove(current_log_path) != 0) {
        perror("Failed to remove log file");
    }

    exit(0);
}

int main() {
    int ret;
    unsigned int adc_value;
    float current_mA;
    char timestamp[20];
    struct spi_ioc_transfer xfer[1];

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    if ((gpio_fd = open("/dev/gpiochip0", O_RDWR)) < 0) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    if (ioctl(gpio_fd, GPIO_GET_LINE, GPIO_PIN) < 0) {
        perror("Failed to get GPIO line");
        goto cleanup;
    }

    if (ioctl(gpio_fd, GPIO_SET_DIR, GPIO_PIN | GPIO_OUT) < 0) {
        perror("Failed to set GPIO direction");
        goto cleanup;
    }

    if (ioctl(gpio_fd, GPIO_CLR, GPIO_PIN) < 0) {
        perror("Failed to clear GPIO");
        goto cleanup;
    }

    if ((spi_fd = open(SPI_DEV, O_RDWR)) < 0) {
        perror("Failed to open SPI device");
        goto cleanup;
    }

    xfer[0].tx_buf = (unsigned char*)&(0x40 | (MODE3 << 8) | (CS << 16) | (AD0 << 24));
    xfer[0].rx_buf = &adc_value;
    xfer[0].len = 4;

    while (1) {
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), xfer);
        if (ret < 1) {
            perror("Failed to read ADC value");
            goto cleanup;
        }

        current_mA = (adc_value * 5.0 / 1023.0) * 100.0;

        time_t rawtime;
        struct tm * timeinfo;
        char time_string[20];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("%s,%.2f\n", timestamp, current_mA);

        FILE * log_file = fopen(current_log_path, "a");
        if (log_file == NULL) {
            perror("Failed to open log file");
            goto cleanup;
        }

        fprintf(log_file, "%s,%.2f\n", timestamp, current_mA);
        fclose(log_file);

        usleep(1000000); // Sleep for 1 second

        if (ioctl(gpio_fd, GPIO_SET, GPIO_PIN)) {
            perror("Failed to set GPIO");
            goto cleanup;
        }
        usleep(100000); // Wait for 100ms
        if (ioctl(gpio_fd, GPIO_CLR, GPIO_PIN)) {
            perror("Failed to clear GPIO");
            goto cleanup;
        }
    }

cleanup:
    if (gpio_fd != -1) {
        close(gpio_fd);
    }

    if (spi_fd != -1) {
        close(spi_fd);
    }

    return 0;
}
```

