I'll provide a basic example using the `libgpiod` library for GPIO management and the `spidev` library for SPI communication. Note that you'll need to install the required libraries using the following commands:

```bash
sudo apt-get install libgpiod-dev
sudo apt-get install libspidev-dev
```

Here's the C code:

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <time.h>
#include <spidev.h>
#include <gpiod.h>

#define MCP3008_CS_GPIO 8
#define MCP3008_MOSI_GPIO 10
#define MCP3008_MISO_GPIO 9
#define MCP3008_SCLK_GPIO 11
#define MLX91211_VDD_GPIO 12

#define SPI_DEVICE_0 "/dev/spidev0.0"
#define SPI_MODE_0 0
#define SPI_SPEED_1MHZ 1000000

volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int init_gpio(int gpio) {
    gpiod_line_request_dt_byname("rpi", "gpio" + std::to_string(gpio));
    gpiod_line_set_value_byname("rpi", "gpio" + std::to_string(gpio), 1);
    return gpiod_line_get_fd_byname("rpi", "gpio" + std::to_string(gpio));
}

int init_spi() {
    int spi_fd = open(SPI_DEVICE_0, O_RDWR);
    if (spi_fd < 0) {
        perror("Can't open SPI device");
        return -1;
    }

    if (ioctl(spi_fd, SPI_OPEN_MODE, SPI_MODE_0) < 0) {
        perror("Can't set SPI mode");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_CPOL, 0) < 0) {
        perror("Can't set SPI CPOL");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_CPHA, 0) < 0) {
        perror("Can't set SPI CPHA");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_CRC_POLY, 0) < 0) {
        perror("Can't set SPI CRC");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_MAX_SPEED_HZ, SPI_SPEED_1MHZ) < 0) {
        perror("Can't set SPI speed");
        close(spi_fd);
        return -1;
    }

    return spi_fd;
}

float read_adc(int spi_fd, int cs_gpio) {
    char buf[3];
    int xfer_len = 3;

    gpiod_line_set_value(cs_gpio_fd, 0);
    usleep(10);

    if (write(spi_fd, &xfer_len, sizeof(xfer_len)) != sizeof(xfer_len)) {
        perror("Can't write to SPI device");
        return NAN;
    }

    if (write(spi_fd, &xfer_len, sizeof(xfer_len)) != sizeof(xfer_len)) {
        perror("Can't write to SPI device");
        return NAN;
    }

    if (read(spi_fd, buf, xfer_len) != xfer_len) {
        perror("Can't read from SPI device");
        return NAN;
    }

    gpiod_line_set_value(cs_gpio_fd, 1);

    float adc_value = (buf[1] << 8 | buf[2]) * 3.3 / (1023 * 4096);
    return adc_value;
}

float convert_current(float adc_value) {
    const float mlx91211_resistance = 10;
    const float pi = 3.14159265358979323846;
    const float mlx91211_current_sensitivity = 1.0 / (2 * pi * mlx91211_resistance);

    return mlx91211_current_sensitivity * adc_value;
}

int main() {
    signal(SIGINT, sigint_handler);

    int cs_gpio_fd = init_gpio(MCP3008_CS_GPIO);
    if (cs_gpio_fd < 0) {
        return 1;
    }

    int spi_fd = init_spi();
    if (spi_fd < 0) {
        return 1;
    }

    FILE *log_file = fopen("current_log.txt", "w");
    if (!log_file) {
        perror("Can't open log file");
        close(spi_fd);
        gpiod_line_release(cs_gpio_fd);
        return 1;
    }

    while (running) {
        float adc_value = read_adc(spi_fd, cs_gpio_fd);
        if (isnan(adc_value)) {
            perror("Error reading ADC");
            continue;
        }

        float current = convert_current(adc_value);
        if (current < 0 || current > 5.0) {
            printf("Warning: Measured current out of range (%.2f A)\n", current);
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm_now = localtime(&now);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);
        fprintf(log_file, "%s %.2f A\n", timestamp, current);
        fflush(log_file);
    }

    fclose(log_file);
    close(spi_fd);
    gpiod_line_release(cs_gpio_fd);

    return 0;
}
