            last_log_time = get_monotonic_ns();
        }

        if (majority_value == 0 && sensor1_value == 0 &&
            sensor2_value == 0) {
            printf("ALERT: Both sensors detect object\n");
        }
    }

    gpiod_line_release(sensor1_line);
    gpiod_line_release(sensor2_line);
    gpiod_chip_release(sensor2_chip);
    gpiod_chip_release(sensor1_chip);

