#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/spi/spidev.h>
#include "driver_library.h"

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

int spi_fd;
struct spi_ioc_transfer transfer;
volatile sig_atomic_t running = 1;

void signal_handler(int signal) {
    running = 0;
    close(spi_fd);
    gpiod_chip_shutdown(gpiochip);
    exit(0);
}

int read_mcp3008(int channel) {
    transfer.tx_buf = (unsigned char*)&channel;
    transfer.rx_buf = (unsigned char*)malloc(3);
    transfer.len = 3;
    transfer.delay_usecs = 10;
    transfer.bits_per_word = 8;
    transfer.cs_change = 0;

    if (spi_xfer(spi_fd, &transfer, 1) < 0) {
        perror("SPI transfer failed");
        sleep(1);
        return -1;
    }

    return ((transfer.rx_buf[1] << 8) | transfer.rx_buf[2]);
}

double calculate_moisture_level(int adc_value) {
    double moisture_level = (adc_value - MIN_ADC) * 100.0 / (MAX_ADC - MIN_ADC);
    return moisture_level < 0 ? 0 : (moisture_level > 100 ? 100 : moisture_level);
}

void log_data(double moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(stderr, "%s,%f\n", timestamp, moisture_level);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s,%f\n", timestamp, moisture_level);
    fclose(log_file);
}

int spi_setup(spi_config_t config) {
    spi_fd = spi_open(config.bus_num, config.chip_select, 0);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (spi_ioctl(spi_fd, SPI_IOC_WR_MODE, &config.mode) != 0) {
        perror("Failed to set SPI mode");
        goto cleanup;
    }

    if (spi_ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &config.bits_per_word) != 0) {
        perror("Failed to set SPI bits per word");
        goto cleanup;
    }

    if (spi_ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &config.max_speed_hz) != 0) {
        perror("Failed to set SPI max speed");
        goto cleanup;
    }

    return 0;

cleanup:
    close(spi_fd);
    return -1;
}

int main() {
    signal(SIGINT, signal_handler);

    spi_config_t config = {
        .bus_num = 0,
        .chip_select = SPI_CHANNEL,
        .mode = SPI_MODE_0,
        .bits_per_word = 8,
        .max_speed_hz = SPI_BAUD
    };

    if (spi_setup(config) < 0) {
        perror("Failed to initialize SPI");
        return 1;
    }

    while (running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            continue;
        }

        double moisture_level = calculate_moisture_level(adc_value);
        log_data(moisture_level);
        sleep(READ_DELAY);
    }

    close(spi_fd);
    gpiod_chip_shutdown(gpiochip);
    return 0;
}

