#include <libcamera/camera-still.h>

#define PIR_GPIO 17
#define DEBOUNCE_MS 200
#define POLL_MS 50
#define CAPTURE_DIR "/home/pi/security_cam"
#define LOG_FACILITY LOG_USER

static gpiod_line_request_lines_data_t pir_lines[] = {
    { .offset = PIR_GPIO, .flags = GPIOD_LINE_REQUEST_INPUT },
};

static int init_gpiod(void) {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line_request *request;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %m");
        return -1;
    }

    request = gpiod_chip_request_lines(chip, 1, pir_lines, NULL);
    if (!request) {
        syslog(LOG_ERR, "Failed to request GPIO%d: %m", PIR_GPIO);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_get_value_cansleep(request->lines[0]);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to get initial GPIO%d value: %m", PIR_GPIO);
        gpiod_line_release(request->lines[0]);
        gpiod_chip_release_request(request);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

static void cleanup_gpiod(gpiod_line_request *request) {
    if (request) {
        gpiod_line_release(request->lines[0]);
        gpiod_chip_release_request(request);
    }
}

static void cleanup_syslog(void) {
    openlog("security_cam", LOG_PID, LOG_USER);
    closelog();
}

static void signal_handler(int sig) {
    syslog(LOG_INFO, "Received signal %d, shutting down...", sig);
    cleanup_gpiod(pir_lines[0].request);
    cleanup_syslog();
    exit(0);
}

static void create_capture_path(char *path) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", timeinfo);
    snprintf(path, sizeof(path), "%s/motion_%08ld_%s.jpg", CAPTURE_DIR, (long)time(NULL), timestamp);
}

static int init_capture(void) {
    int ret;
    camera_still_context_t *ctx;

    ctx = camera_still_context_create();
    if (!ctx) {
        syslog(LOG_ERR, "Failed to create camera_still_context: %s", strerror(errno));
        return -1;
    }

    ret = camera_still_context_init(ctx);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to initialize camera_still_context: %s", strerror(errno));
        camera_still_context_destroy(ctx);
        return -1;
    }

    return 0;
}

static void cleanup_capture(camera_still_context_t *ctx) {
    camera_still_context_destroy(ctx);
}

static void capture_image(void) {
    int ret;
    camera_still_request_t *req;
    camera_still_response_t *resp;
    camera_still_context_t *ctx;

    ctx = camera_still_context_create();
    if (!ctx) {
        syslog(LOG_ERR, "Failed to create camera_still_context: %s", strerror(errno));
        return;
    }

    ret = camera_still_context_init(ctx);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to initialize camera_still_context: %s", strerror(errno));
        camera_still_context_destroy(ctx);
        return;
    }

    req = camera_still_request_create(ctx);
    if (!req) {
        syslog(LOG_ERR, "Failed to create camera_still_request: %s", strerror(errno));
        camera_still_context_destroy(ctx);
        return;
    }

    ret = camera_still_request_set_format(req, CAMERA_STILL_FORMAT_JPEG);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set camera_still_request format: %s", strerror(errno));
        camera_still_request_destroy(req);
        camera_still_context_destroy(ctx);
        return;
    }

    ret = camera_still_request_set_quality(req, 80);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set camera_still_request quality: %s", strerror(errno));
        camera_still_request_destroy(req);
        camera_still_context_destroy(ctx);
        return;
    }

    ret = camera_still_request_set_filename(req, "motion_%ld.jpg");
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set camera_still_request filename: %s", strerror(errno));
        camera_still_request_destroy(req);
        camera_still_context_destroy(ctx);
        return;
    }

    ret = camera_still_request_set_mode(req, CAMERA_STILL_MODE_SINGLE);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set camera_still_request mode: %s", strerror(errno));
        camera_still_request_destroy(req);
        camera_still_context_destroy(ctx);
        return;
    }

    ret = camera_still_request_set_callback(req, NULL, NULL);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set camera_still_request callback: %s", strerror(errno));
        camera_still_request_destroy(req);
        camera_still_context_destroy(ctx);
        return;
    }

    ret = camera_still_context_capture(ctx, req, &resp);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to capture image: %s", strerror(errno));
        camera_still_request_destroy(req);
        camera_still_response_destroy(resp);
        camera_still_context_destroy(ctx);
        return;
    }

    camera_still_request_destroy(req);
    camera_still_response_destroy(resp);
    camera_still_context_destroy(ctx);
