#include <sys/select.h>
#include <linux/videodev2.h>
#include <gpiod.h>

#define CSI_DEVICE "/dev/video0"
#define BUFFER_COUNT 4
#define BUFFER_SIZE 1920 * 1080 * 2
#define PGM_HEADER_SIZE 54

static const char *pgm_header = "P5\n# Raspberry Pi OV5647 CSI camera\n%d %d\n255\n";

int camera_fd, buffer_fd[BUFFER_COUNT];
void *buffers[BUFFER_COUNT];
gpiod_line_request_lines_data lines_data = {0};

void handle_signal(int signum) {
    printf("Received signal %d, stopping capture...\n", signum);
    for (int i = 0; i < BUFFER_COUNT; ++i) {
        if (buffer_fd[i] >= 0) {
            lseek(buffer_fd[i], 0, SEEK_SET);
            close(buffer_fd[i]);
            buffer_fd[i] = -1;
        }
    }
    if (camera_fd >= 0) {
        close(camera_fd);
        camera_fd = -1;
    }
    exit(0);
}

int main(int argc, char **argv) {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    camera_fd = open(argc > 1 ? argv[1] : CSI_DEVICE, O_RDWR | O_NONBLOCK);
    if (camera_fd < 0) {
        perror("Failed to open camera device");
        return 1;
    }

    struct v4l2_format format = {0};
    format.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(camera_fd, VIDIOC_G_FMT, &format) < 0) {
        perror("Failed to get camera format");
        goto error;
    }

    format.fmt.pix.width = 1920;
    format.fmt.pix.height = 1080;
    format.fmt.pix.pixelformat = V4L2_PIX_FMT_GRAY;
    if (ioctl(camera_fd, VIDIOC_S_FMT, &format) < 0) {
        perror("Failed to set camera format");
        goto error;
    }

    struct v4l2_requestbuffers req = {0};
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (ioctl(camera_fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Failed to request camera buffers");
        goto error;
    }

    for (int i = 0; i < req.count; ++i) {
        buffer_fd[i] = buffer_fd[i] >= 0 ? buffer_fd[i] : -1;
        if (buffer_fd[i] < 0) {
            buffer_fd[i] = memfd_create("buffer", 0);
            if (buffer_fd[i] < 0) {
                perror("Failed to create buffer memory file");
                goto error;
            }
        }

        if (ioctl(camera_fd, VIDIOC_QBUF, &req.buffers[i]) < 0) {
            perror("Failed to queue camera buffer");
            goto error;
        }
    }

    if (ioctl(camera_fd, VIDIOC_STREAMON, &format.type) < 0) {
        perror("Failed to start camera streaming");
        goto error;
    }

    fd_set fds;
    struct timeval tv = {2, 0};
    int ready_fds;

    for (int i = 0; i < BUFFER_COUNT; ++i) {
        FD_ZERO(&fds);
        FD_SET(camera_fd, &fds);
        FD_SET(buffer_fd[i], &fds);

        ready_fds = select(camera_fd > buffer_fd[i] ? camera_fd : buffer_fd[i] + 1, &fds, NULL, NULL, &tv);
        if (ready_fds < 0) {
            perror("Failed to wait for camera or buffer");
            goto error;
        }

        if (FD_ISSET(camera_fd, &fds)) {
            if (ioctl(camera_fd, VIDIOC_DQBUF, &req.buffers[i]) < 0) {
                perror("Failed to dequeue camera buffer");
                continue;
            }

            buffers[i] = mmap(NULL, BUFFER_SIZE, PROT_READ, MAP_SHARED, buffer_fd[i], req.buffers[i].m.offset);
            if (buffers[i] == MAP_FAILED) {
                perror("Failed to map camera buffer");
                continue;
            }

            int file = open("image_0001.pgm", O_WRONLY | O_CREAT | O_TRUNC, 0644);
            if (file < 0) {
                perror("Failed to open output file");
                continue;
            }

            snprintf(pgm_header, sizeof(pgm_header), pgm_header, format.fmt.pix.width, format.fmt.pix.height);
            if (write(file, pgm_header, PGM_HEADER_SIZE) != PGM_HEADER_SIZE) {
                perror("Failed to write PGM header");
                close(file);
                continue;
            }

            if (write(file, buffers[i], BUFFER_SIZE) != BUFFER_SIZE) {
                perror("Failed to write image data");
                close(file);
                continue;
            }

            close(file);
            if (munmap(buffers[i], BUFFER_SIZE) < 0) {
                perror("Failed to unmap camera buffer");
                continue;
            }

            if (ioctl(camera_fd, VIDIOC_QBUF, &req.buffers[i]) < 0) {
                perror("Failed to queue camera buffer");
                continue;
            }
        }

        if (FD_ISSET(buffer_fd[i], &fds)) {
            if (ioctl(camera_fd, VIDIOC_QBUF, &req.buffers[i]) < 0) {
                perror("Failed to queue camera buffer");
                continue;
            }
        }
    }

    for (int i = 0; i < BUFFER_COUNT; ++i) {
        if (buffer_fd[i] >= 0) {
            close(buffer_fd[i]);
            buffer_fd[i] = -1;
        }
    }

    if (ioctl(camera_fd, VIDIOC_STREAMOFF, &format.type) < 0) {
        perror("Failed to stop camera streaming");
        goto error;
    }

    close(camera_fd);
    camera_fd = -1;

    return 0;

error:
