This code captures grayscale images from an Arducam OV5647 CSI camera module using the CSI bus device specified as a command-line argument (default /dev/video0). It sets up memory-mapped streaming with a single buffer and saves each frame as a sequential .pgm file. The program includes robust error handling for every open(), ioctl(), mmap(), fwrite(), and close() call, handles the EAGAIN condition using select(), and cleans up resources on every exit path. It also installs signal handlers for SIGINT and SIGTERM to stop streaming and safely unmap the buffers.

code:
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <time.h>
#include <sys/select.h>
#include <errno.h>
#include <libgpiod.h>

#define BUFFER_SIZE 1920 * 1080 * 3 / 2
#define FRAME_LOG "frame_log.txt"

int main() {
    int fd_cam, ret;
    struct v4l2_buffer buf;
    char *map_base;
    FILE *log_file;
    struct timeval tv;
    fd_set fds;
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    fd_cam = open("/dev/video0", O_RDWR | O_NONBLOCK);
    if (fd_cam < 0) {
        perror("Error opening video device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd_cam, VIDIOC_QUERYCAP, NULL) < 0) {
        perror("Error querying video device capabilities");
        close(fd_cam);
        exit(EXIT_FAILURE);
    }

    if (!(ioctl(fd_cam, VIDIOC_STREAMON, 0) >= 0)) {
        perror("Error starting video stream");
        close(fd_cam);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(fd_cam, VIDIOC_DQBUF, &buf);
    if (ret < 0) {
        perror("Error dequeuing buffer");
        close(fd_cam);
        exit(EXIT_FAILURE);
    }

    map_base = mmap(NULL, BUFFER_SIZE, PROT_READ, MAP_SHARED, fd_cam, buf.m.offset);
    if (map_base == MAP_FAILED) {
        perror("Error mapping buffer");
        close(fd_cam);
        exit(EXIT_FAILURE);
    }

    log_file = fopen(FRAME_LOG, "w");
    if (!log_file) {
        perror("Error opening log file");
        munmap(map_base, BUFFER_SIZE);
        close(fd_cam);
        exit(EXIT_FAILURE);
    }

