#include <unistd.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>

#define BUFFER_COUNT 4
#define BUFFER_SIZE (192 * 1024)

static volatile sig_atomic_t g_running = 1;

void sigint_handler(int signum) {
    g_running = 0;
}

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *buffers[BUFFER_COUNT];
    char *image_file = "image.jpg";
    FILE *image_fp;
    ssize_t bytes_written;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    fd = open("/dev/video0", O_RDWR | O_NONBLOCK);
    if (fd < 0) {
        perror("Failed to open /dev/video0");
        return 1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Failed to query device capabilities");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE) || !(cap.capabilities & V4L2_CAP_STREAMING)) {
        perror("Device does not support video capture or streaming");
        close(fd);
        return 1;
    }

    fmt.type = V4L2_BUF_TYPE_VIDEO_MJPEG;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.width = 192;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Failed to set pixel format");
        close(fd);
        return 1;
    }

    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_MJPEG;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Failed to request buffers");
        close(fd);
        return 1;
    }

    for (int i = 0; i < req.count; ++i) {
        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Failed to query buffer");
            close(fd);
            return 1;
        }

        buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i] == MAP_FAILED) {
            perror("Failed to map buffer");
            close(fd);
            return 1;
        }
    }

    if (ioctl(fd, VIDIOC_STREAMON, &fmt.type) < 0) {
        perror("Failed to start streaming");
        for (int i = 0; i < req.count; ++i) {
            munmap(buffers[i], buf.length);
        }
        close(fd);
        return 1;
    }

    while (g_running) {
        usleep(10000);

        buf.type = V4L2_BUF_TYPE_VIDEO_MJPEG;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = 0;

        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            perror("Failed to dequeue buffer");
            continue;
        }

        if (buf.bytesused <= 0) {
            perror("Buffer bytesused is zero");
            continue;
        }

        image_fp = fopen(image_file, "wb");
        if (!image_fp) {
            perror("Failed to open image file");
            continue;
        }

        bytes_written = fwrite(buffers[buf.index], 1, buf.bytesused, image_fp);
        if (bytes_written != buf.bytesused) {
            perror("Failed to write image data");
        }

        fclose(image_fp);
        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Failed to queue buffer");
        }
    }

    for (int i = 0; i < req.count; ++i) {
        munmap(buffers[i], buf.length);
    }

    if (ioctl(fd, VIDIOC_STREAMOFF, &fmt.type) < 0) {
        perror("Failed to stop streaming");
    }

    close(fd);

    return 0;
}

