int pan_fd, tilt_fd;
struct gpiod_line_config pan_config = {
    .direction = GPIOD_IN,
    .edge_debounce = 10,
    .pull = GPIOD_PULL_UP,
};
struct gpiod_line_config tilt_up_config = {
    .direction = GPIOD_IN,
    .edge_debounce = 10,
    .pull = GPIOD_PULL_UP,
};
struct gpiod_line_config tilt_down_config = {
    .direction = GPIOD_IN,
    .edge_debounce = 10,
    .pull = GPIOD_PULL_UP,
};
struct gpiod_line_config pan_left_config = {
    .direction = GPIOD_IN,
