    .pull = GPIOD_PULL_UP,
};
struct gpiod_line_config pan_right_config = {
    .direction = GPIOD_IN,
    .edge_debounce = 10,
    .pull = GPIOD_PULL_UP,
};
struct gpiod_pwm_config pwm_config = {
    .period_ns = PWM_PERIOD_NS,
    .duty_ns = PWM_MID_DUTY_NS,
};

void setup_servos(void) {
    if (gpiochip_request_line(pan_fd, PAN_GPIO, "pan") < 0 ||
        gpiochip_request_line(tilt_fd, TILT_GPIO, "tilt") < 0) {
        perror("Failed to request servo lines");
        exit(EXIT_FAILURE);
    }

    if (gpio_setup_pwm(pan_fd, PAN_GPIO, &pwm_config) < 0 ||
        gpio_setup_pwm(tilt_fd, TILT_GPIO, &pwm_config) < 0) {
        perror("Failed to setup PWM for servos");
        exit(EXIT_FAILURE);
    }
}

void setup_buttons(void) {
    if (gpiochip_request_line(pan_fd, PAN_GPIO, "pan_button") < 0 ||
        gpiochip_request_line(tilt_fd, TILT_UP_GPIO, "tilt_up_button") < 0 ||
        gpiochip_request_line(tilt_fd, TILT_DOWN_GPIO, "tilt_down_button") < 0 ||
        gpiochip_request_line(pan_fd, PAN_LEFT_GPIO, "pan_left_button") < 0 ||
