        gpio_line_configure_async(tilt_fd, TILT_UP_GPIO, &tilt_up_config) < 0 ||
        gpio_line_configure_async(tilt_fd, TILT_DOWN_GPIO, &tilt_down_config) < 0 ||
        gpio_line_configure_async(pan_fd, PAN_LEFT_GPIO, &pan_left_config) < 0 ||
        gpio_line_configure_async(pan_fd, PAN_RIGHT_GPIO, &pan_right_config) < 0) {
        perror("Failed to configure button lines");
        exit(EXIT_FAILURE);
    }
}

void adjust_servo(int gpio, int* duty, int min_duty, int max_duty, int step) {
    int new_duty = *duty + step;
    if (new_duty < min_duty) {
        new_duty = min_duty;
    } else if (new_duty > max_duty) {
        new_duty = max_duty;
    }
    gpio_set_pwm_duty_ns(gpio, &pwm_config, new_duty);
    *duty = new_duty;
}

int main(void) {
    int pan_duty = PWM_MID_DUTY_NS;
    int tilt_duty = PWM_MID_DUTY_NS;
    int pan_last_state = -1;
    int tilt_up_last_state = -1;
    int tilt_down_last_state = -1;
    int pan_left_last_state = -1;
    int pan_right_last_state = -1;

    pan_fd = gpiochip_open_byname("gpiochip0");
    if (pan_fd < 0) {
        perror("Failed to open gpiochip0");
        exit(EXIT_FAILURE);
    }

    tilt_fd = gpiochip_open_byname("gpiochip1");
    if (tilt_fd < 0) {
