    setup_buttons();

    while (1) {
        int pan_state = gpio_get_value(pan_fd, PAN_GPIO);
        int tilt_up_state = gpio_get_value(tilt_fd, TILT_UP_GPIO);
        int tilt_down_state = gpio_get_value(tilt_fd, TILT_DOWN_GPIO);
        int pan_left_state = gpio_get_value(pan_fd, PAN_LEFT_GPIO);
        int pan_right_state = gpio_get_value(pan_fd, PAN_RIGHT_GPIO);

        if (pan_state != pan_last_state) {
            adjust_servo(PAN_GPIO, &pan_duty, PWM_MIN_DUTY_NS, PWM_MAX_DUTY_NS, SERVO_ADJUST_STEP);
            pan_last_state = pan_state;
        }

        if (tilt_up_state != tilt_up_last_state) {
            adjust_servo(TILT_GPIO, &tilt_duty, PWM_MIN_DUTY_NS, PWM_MAX_DUTY_NS, SERVO_ADJUST_STEP);
            tilt_up_last_state = tilt_up_state;
        }

        if (tilt_down_state != tilt_down_last_state) {
            adjust_servo(TILT_GPIO, &tilt_duty, PWM_MIN_DUTY_NS, PWM_MAX_DUTY_NS, -SERVO_ADJUST_STEP);
            tilt_down_last_state = tilt_down_state;
        }

        if (pan_left_state != pan_left_last_state) {
            adjust_servo(PAN_GPIO, &pan_duty, PWM_MIN_DUTY_NS, PWM_MAX_DUTY_NS, -SERVO_ADJUST_STEP);
            pan_left_last_state = pan_left_state;
        }

        if (pan_right_state != pan_right_last_state) {
            adjust_servo(PAN_GPIO, &pan_duty, PWM_MIN_DUTY_NS, PWM_MAX_DUTY_NS, SERVO_ADJUST_STEP);
            pan_right_last_state = pan_right_state;
        }

        usleep(BUTTON_POLL_MS * 1000);
    }

    gpio_line_unconfigure_async(pan_fd, PAN_GPIO, &pan_config);
    gpio_line_unconfigure_async(tilt_fd, TILT_UP_GPIO, &tilt_up_config);
    gpio_line_unconfigure_async(tilt_fd, TILT_DOWN_GPIO, &tilt_down_config);
    gpio_line_unconfigure_async(pan_fd, PAN_LEFT_GPIO, &pan_left_config);
    gpio_line_unconfigure_async(pan_fd, PAN_RIGHT_GPIO, &pan_right_config);
    gpio_close(pan_fd);
    gpio_close(tilt_fd);

    return 0;
}

