#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/v4l2-common.h>
#include <linux/v4l2-control.h>
#include <linux/v4l2-types.h>
#include <linux/videodev2.h>

#define DEVICE_NODE "/dev/video0"

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_fmtdesc fmt_desc;
    struct v4l2_frmsizeenum frm_size;
    struct v4l2_frmivalenum frm_interval;
    struct v4l2_queryctrl query_ctrl;
    int i, j;

    fd = open(DEVICE_NODE, O_RDWR | O_NONBLOCK);
    if (fd < 0) {
        perror("Failed to open device node");
        return 1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Failed to query device capabilities");
        close(fd);
        return 1;
    }

    if (strcmp(cap.driver, "")) {
        printf("Driver: %s\n", cap.driver);
    }
    if (strcmp(cap.card, "")) {
        printf("Card: %s\n", cap.card);
    }
    if (strcmp(cap.bus_info, "")) {
        printf("Bus Info: %s\n", cap.bus_info);
    }

    if (cap.capabilities & V4L2_CAP_VIDEO_CAPTURE) {
        printf("Capabilities: Video Capture\n");
    }
    if (cap.capabilities & V4L2_CAP_STREAMING) {
        printf("Capabilities: Streaming\n");
    }

    memset(&fmt_desc, 0, sizeof(fmt_desc));
    fmt_desc.index = 0;
    fmt_desc.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    for (i = 0; ioctl(fd, VIDIOC_ENUM_FMT, &fmt_desc) == 0; ++fmt_desc.index) {
        printf("Format %d: %s\n", fmt_desc.index, fmt_desc.description);

        memset(&frm_size, 0, sizeof(frm_size));
        frm_size.index = 0;
        frm_size.pixel_format = fmt_desc.pixelformat;
        frm_size.index = 0;

        for (j = 0; ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frm_size) == 0; ++frm_size.index) {
            printf("  Resolution %dx%d\n", frm_size.discrete.width, frm_size.discrete.height);

            memset(&frm_interval, 0, sizeof(frm_interval));
            frm_interval.index = 0;
            frm_interval.pixel_format = fmt_desc.pixelformat;
            frm_interval.width = frm_size.discrete.width;
            frm_interval.height = frm_size.discrete.height;

            for (; ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frm_interval) == 0; ++frm_interval.index) {
                printf("    Frame Interval %d.%06d\n", frm_interval.numerator, frm_interval.denominator);
            }
        }
    }

    memset(&query_ctrl, 0, sizeof(query_ctrl));
    query_ctrl.id = V4L2_CID_FOCUS_AUTO;

    if (ioctl(fd, VIDIOC_QUERYCTRL, &query_ctrl) == 0) {
        printf("Autofocus supported\n");
    } else {
        printf("Autofocus not supported\n");
    }

    close(fd);
    return 0;
}
```

This program opens the `/dev/video0` device node, checks that it exists and can be opened, queries the device capabilities, enumerates all supported frame sizes and frame intervals, and determines whether autofocus is supported. It prints a clear, human-readable summary of the resolutions, frame rates, and autofocus capability to stdout. The program verifies every ioctl return value, handles the cases where the device node is missing, cannot be opened, the camera does not support frame-size or interval enumeration, or the focus control is absent, and exits with a non-zero status on any fatal error.

