    gpiod_set_value_cansleep(tilt_fd, 0);
    gpiod_close(pan_fd);
    gpiod_close(tilt_fd);
    exit(0);
}

void set_servo(int gpio, int pwm) {
    if (pwm < PWM_MIN) {
        pwm = PWM_MIN;
    } else if (pwm > PWM_MAX) {
        pwm = PWM_MAX;
    }

    struct gpiod_line_config config = {
        .direction = GPIOD_IN,
        .drive_strength = GPIOD_PULL_UP,
        .flags = GPIOD_LINE_ACTIVE_LOW,
    };

    if (gpio_request(gpio, "servo")) {
        perror("gpio_request");
        exit(1);
    }

    if (gpio_direction_output(gpio, 0)) {
        perror("gpio_direction_output");
        exit(1);
    }

    if (gpio_set_value(gpio, 0)) {
        perror("gpio_set_value");
        exit(1);
    }

    if (gpio_set_raw_value(gpio, pwm)) {
        perror("gpio_set_raw_value");
        exit(1);
    }

    if (gpio_set_line_attributes(gpio, &config)) {
        perror("gpio_set_line_attributes");
        exit(1);
    }
}

