    signal(SIGTERM, sigint_handler);

    if ((pan_fd = gpiod_open_name_with_flags("gpiochip0", PAN_GPIO, GPIOD_OUTPUT_HIGH | GPIOD_LINE_REQUEST_INVERT_POLARITY)) < 0) {
        perror("gpiod_open_name_with_flags");
        exit(1);
    }

    if ((tilt_fd = gpiod_open_name_with_flags("gpiochip0", TILT_GPIO, GPIOD_OUTPUT_HIGH | GPIOD_LINE_REQUEST_INVERT_POLARITY)) < 0) {
