    printf("Center position: %d\n", PWM_CENTER);

    struct gpiod_line_config config = {
        .direction = GPIOD_IN,
        .drive_strength = GPIOD_PULL_UP,
        .flags = GPIOD_LINE_ACTIVE_LOW,
    };

    if (gpio_request(UP_GPIO, "up_button")) {
        perror("gpio_request");
        exit(1);
    }

    if (gpio_request(DOWN_GPIO, "down_button")) {
        perror("gpio_request");
        exit(1);
    }

    if (gpio_request(LEFT_GPIO, "left_button")) {
        perror("gpio_request");
        exit(1);
    }

    if (gpio_request(RIGHT_GPIO, "right_button")) {
        perror("gpio_request");
        exit(1);
    }

    if (gpio_set_line_attributes(UP_GPIO, &config)) {
        perror("gpio_set_line_attributes");
        exit(1);
    }

    if (gpio_set_line_attributes(DOWN_GPIO, &config)) {
        perror("gpio_set_line_attributes");
        exit(1);
    }

    if (gpio_set_line_attributes(LEFT_GPIO, &config)) {
        perror("gpio_set_line_attributes");
        exit(1);
    }

    if (gpio_set_line_attributes(RIGHT_GPIO, &config)) {
        perror("gpio_set_line_attributes");
        exit(1);
    }

    while (1) {
        usleep(DELAY_US * 1000);

        if (gpio_get_value(UP_GPIO)) {
            if (pan_pwm < PWM_MAX) {
                pan_pwm += PWM_STEP;
            }
        } else if (gpio_get_value(DOWN_GPIO)) {
            if (pan_pwm > PWM_MIN) {
                pan_pwm -= PWM_STEP;
            }
        }

        if (gpio_get_value(LEFT_GPIO)) {
            if (tilt_pwm < PWM_MAX) {
                tilt_pwm += PWM_STEP;
            }
        } else if (gpio_get_value(RIGHT_GPIO)) {
            if (tilt_pwm > PWM_MIN) {
                tilt_pwm -= PWM_STEP;
            }
        }

        set_servo(PAN_GPIO, pan_pwm);
        set_servo(TILT_GPIO, tilt_pwm);
    }

    return 0;
}

