```

Here's the C code:

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <boost/asio.hpp>
#include <libgpiod.h>
#include <time.h>
#include <unistd.h>
#include <sys/stat.h>
#include <cstdio>
#include <cstdlib>
#include <cstring>

using boost::asio::ip::tcp;

constexpr int PIR_GPIO = 17;
constexpr int POLL_INTERVAL_MS = 100;
constexpr int DEBOUNCE_INTERVAL_MS = 2000;
constexpr int QUALITY = 85;
constexpr int BUFFER_SIZE = 4096;

static gpiod_line_request_linestate_cb_t line_cb;
static gpiod_line_request *line_request;
static gpiod_chip *chip;
static gpiod_line *line;
static bool is_debouncing = false;
static bool is_motion_detected = false;
static std::string motion_captures_dir = "motion_captures";
static std::string image_filename;
static std::ofstream image_file;
static tcp::iostream stream;

void line_cb(struct gpiod_line_request *request, enum gpiod_line_event event,
             unsigned int value, unsigned int flags) {
    if (event == GPIOD_LINE_EVENT_EDGE_FALLING) {
        if (!is_debouncing) {
            is_motion_detected = true;
            is_debouncing = true;
            std::cout << "Motion detected!" << std::endl;
            capture_image();
        }
    } else if (event == GPIOD_LINE_EVENT_EDGE_RISING && is_debouncing) {
        is_debouncing = false;
        if (is_motion_detected) {
            std::cout << "Motion ended." << std::endl;
            is_motion_detected = false;
            upload_image();
        }
    }
}

void capture_image() {
    std::string command = "raspistill -o ";
    command += image_filename;
    command += " -q ";
    command += std::to_string(QUALITY);

    std::system(command.c_str());
}

void upload_image() {
    if (!stream.is_open()) {
        stream.expires_from_now(boost::posix_time::seconds(5));
        stream.connect(tcp::endpoint(tcp::v4(), std::stoi(std::getenv("UPLOAD_PORT"))));
        if (!stream.good()) {
            std::cerr << "Failed to connect to the upload server." << std::endl;
            return;
        }
    }

    time_t rawtime;
    struct tm *timeinfo;
    char time_buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(time_buffer, sizeof(time_buffer), "%Y-%m-%dT%H:%M:%S.%f", timeinfo);

    std::string payload = "{\"filename\":\"" + image_filename + "\",\"timestamp\":\"" +
                          time_buffer + "\",\"motion\":\"" +
                          (is_motion_detected ? "true" : "false") + "\",\"gpio\":" +
                          std::to_string(PIR_GPIO) + "}";

    stream << payload << std::endl;
    if (!stream.good()) {
        std::cerr << "Failed to send the payload to the upload server." << std::endl;
    }

    stream.close();
}

void create_motion_captures_dir() {
    struct stat st;

    if (stat(motion_captures_dir.c_str(), &st) == 0 && S_ISDIR(st.st_mode)) {
        std::cout << "motion_captures directory already exists." << std::endl;
        return;
    }

    if (mkdir(motion_captures_dir.c_str(), 0755) != 0) {
        std::cerr << "Failed to create the motion_captures directory." << std::endl;
        exit(EXIT_FAILURE);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        std::cerr << "Usage: " << argv[0] << " <IP> <UPLOAD_PORT>" << std::endl;
        return EXIT_FAILURE;
    }

    const char *ip = argv[1];
    const char *upload_port = argv[2];

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        std::cerr << "Failed to open the GPIO chip." << std::endl;
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, PIR_GPIO);
    if (!line) {
        std::cerr << "Failed to get the GPIO line." << std::endl;
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line_request = gpiod_line_request_clone(line->request);
    line_request->flags |= GPIOD_LINE_REQUEST_INPUT;
    line_request->flags |= GPIOD_LINE_REQUEST_EDGE_FALLING;
    line_request->flags |= GPIOD_LINE_REQUEST_DEBOUNCE;
    line_request->debounce_timeout_ns = DEBOUNCE_INTERVAL_MS * 1000000;
    line_request->consumer = "Motion detection";

    if (gpiod_line_request_validate(line_request) < 0) {
        std::cerr << "Failed to validate the GPIO line request." << std::endl;
        gpiod_line_request_free(line_request);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_enable(line_request) < 0) {
        std::cerr << "Failed to enable the GPIO line request." << std::endl;
        gpiod_line_request_free(line_request);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line->consumer_data = line_request;
    line->line_event_cb = line_cb;

    create_motion_captures_dir();

    while (true) {
        gpiod_line_get_value(line);
        usleep(POLL_INTERVAL_MS * 1000);
    }

    gpiod_line_request_free(line_request);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}
