#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <errno.h>
#include <libgpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_NAME "line17"
#define CAMERA_CMD "raspistill -o /home/pi/images/%Y%m%d_%H%M%S_%3.3f.jpg --width 640 --height 480 -q 85 --timeout 2000 --nopreview"
#define LOG_FILE "/home/pi/motion_capture.log"

static gpiod_line_request_lines_data_t lines_data = { .lines = { { .direction = GPIOD_LINE_INPUT, .edge_detected_callback = NULL, .debounce_timeout_ns = 50 * NSEC_PER_MSEC } } };
static gpiod_line_request_lines_data_array_t lines_data_array = { .lines = &lines_data, .n_lines = 1 };

void edge_detected_callback(struct gpiod_line *line, unsigned int value, unsigned int event_type, void *user_data) {
    if (event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
        capture_image();
    }
}

void capture_image() {
    char filename[32];
    time_t rawtime;
    struct tm *timeinfo;
    char time_string[20];
    snprintf(filename, sizeof(filename), "/home/pi/images/%Y%m%d_%H%M%S_%3.3f.jpg", time(&rawtime));
    system(CAMERA_CMD);

    timeinfo = localtime(&rawtime);
    strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("Captured image: %s\n", filename);
    fprintf(stderr, "Captured image: %s\n", filename);
    fprintf(stderr, "Time: %s\n", time_string);
}

int main() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_NAME);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_put(chip);
        return 1;
    }

    ret = gpiod_line_request_lines(&lines_data_array, GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_FALLING);
    if (ret < 0) {
        perror("gpiod_line_request_lines");
        gpiod_line_put(line);
        gpiod_chip_put(chip);
        return 1;
    }

    line->edge_detected_callback = edge_detected_callback;

    while (1) {
        usleep(100000);
    }

    gpiod_line_release(line);
    gpiod_line_put(line);
    gpiod_chip_put(chip);

    return 0;
}

