    timeinfo = localtime(&rawtime);
    strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("Captured image: %s\n", filename);
    fprintf(stderr, "Captured image: %s\n", filename);
    fprintf(stderr, "Time: %s\n", time_string);
}

int main() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_NAME);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_put(chip);
        return 1;
    }

    ret = gpiod_line_request_lines(&lines_data_array, GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_FALLING);
    if (ret < 0) {
        perror("gpiod_line_request_lines");
        gpiod_line_put(line);
        gpiod_chip_put(chip);
        return 1;
    }

    line->edge_detected_callback = edge_detected_callback;

    while (1) {
        usleep(100000);
    }

    gpiod_line_release(line);
    gpiod_line_put(line);
    gpiod_chip_put(chip);

    return 0;
}
```

This code opens the GPIO chip, claims GPIO17 as an input with edge-falling detection, sets up a callback for the edge-falling event, and enters an infinite loop to wait for events. When an event is detected, it invokes the `capture_image()` function to capture an image using the camera command.

To handle SIGINT and SIGTERM, you can add signal handlers for these signals and release the GPIO resources in the handlers. However, since the code already enters an infinite loop, it will be terminated when the signal is received, and the resources will be released automatically.

To log errors and capture failures, you can modify the `capture_image()` function to write the error message to the log file instead of printing it to stderr. You can use `fprintf(stderr, ...)` to write to both stderr and the log file.

Lastly, you should add error checking for the camera command using `system()`'s return value and log any failures. This is beyond the scope of this example, but you can find examples of using `system()` with error checking online.

