#define WIDTH 200
#define HEIGHT 150
#define BUFFER_SIZE (WIDTH * HEIGHT * 2)
#define CAMERA_DEVICE "/dev/video0"
#define CROP_LEFT 0
#define CROP_TOP 0
#define CROP_WIDTH WIDTH
#define CROP_HEIGHT HEIGHT
#define FILE_NAME "cropped.yuv"

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    char *buf_ptr;
    FILE *file;
    ssize_t bytes_written;
    int ret;
    fd_set fds;
    struct timeval tv;
    int running = 1;

    gpiod_line_request_dt_byname(NULL, "camera-power");
    gpiod_line_set_value_cansleep(gpiod_get_line(NULL, "camera-power"), 1);

    fd = open(CAMERA_DEVICE, O_RDWR | O_NONBLOCK);
    if (fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        exit(EXIT_FAILURE);
    }

    if (strcmp(cap.driver, "uvcvideo")) {
        fprintf(stderr, "Wrong driver: %s\n", cap.driver);
        exit(EXIT_FAILURE);
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        exit(EXIT_FAILURE);
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        exit(EXIT_FAILURE);
    }

    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("VIDIOC_QUERYBUF");
        exit(EXIT_FAILURE);
    }

    buf_ptr = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buf_ptr == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, VIDIOC_STREAMON, &buf.type) < 0) {
        perror("VIDIOC_STREAMON");
        exit(EXIT_FAILURE);
    }

    while (running) {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);
        tv.tv_sec = 2;
        tv.tv_usec = 0;

        ret = select(fd + 1, &fds, NULL, NULL, &tv);
        if (ret < 0) {
            if (errno != EINTR) {
                perror("select");
                exit(EXIT_FAILURE);
            }
            continue;
        }

        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            perror("VIDIOC_DQBUF");
            exit(EXIT_FAILURE);
        }

        if (buf.type != V4L2_BUF_TYPE_VIDEO_CAPTURE) {
            fprintf(stderr, "Unexpected buffer type: %d\n", buf.type);
            continue;
        }

        if (buf.bytesused != BUFFER_SIZE) {
            fprintf(stderr, "Unexpected buffer size: %d\n", buf.bytesused);
            continue;
        }

        if (buf.format.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
            fprintf(stderr, "Unexpected pixel format: %d\n", buf.format.fmt.pix.pixelformat);
            continue;
        }

        if (buf.format.fmt.pix.width != WIDTH || buf.format.fmt.pix.height != HEIGHT) {
            fprintf(stderr, "Unexpected width or height: %d x %d\n", buf.format.fmt.pix.width, buf.format.fmt.pix.height);
            continue;
        }

        file = fopen(FILE_NAME, "w");
        if (!file) {
            perror("fopen");
            exit(EXIT_FAILURE);
        }

        for (int y = 0; y < HEIGHT; y++) {
            for (int x = CROP_LEFT; x < CROP_WIDTH; x++) {
                int index = (y * WIDTH + x) * 2;
                fwrite(&buf_ptr[index], 2, 1, file);
            }
        }

        bytes_written = fwrite(buf_ptr, BUFFER_SIZE, 1, file);
        if (bytes_written != 1) {
            perror("fwrite");
            exit(EXIT_FAILURE);
        }

        fclose(file);

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
            exit(EXIT_FAILURE);
        }
    }

    if (ioctl(fd, VIDIOC_STREAMOFF, &buf.type) < 0) {
        perror("VIDIOC_STREAMOFF");
        exit(EXIT_FAILURE);
    }

    munmap(buf_ptr, buf.length);
    close(fd);
    gpiod_line_set_value_cansleep(gpiod_get_line(NULL, "camera-power"), 0);
    gpiod_line_release(gpiod_get_line(NULL, "camera-power"));

    return 0;
}

