To compile the code, install libv4l2-dev and libgpiod-dev on your Raspberry Pi:

```sh
sudo apt-get install libv4l2-dev libgpiod-dev
```

Then compile the code with:

```sh
gcc -o capture capture.c -lv4l2 -lgpiod
```

Run the compiled program with:

```sh
./capture
```

To stop the program, press Ctrl+C. The program will cleanly stop streaming, unmap the buffer, close the file descriptor, and free any allocated memory. The cropped frames will be saved in a file named `cropped.yuv`.

code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/types.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define PAN_SERVO_GPIO 17
#define TILT_SERVO_GPIO 18
#define SERVO_MIN_PWM 1000
#define SERVO_MAX_PWM 2000
#define SERVO_NEUTRAL_PWM (SERVO_MIN_PWM + (SERVO_MAX_PWM - SERVO_MIN_PWM) / 2)
#define SERVO_STEP 5
#define DELAY_MS 100

gpiod_line_request_linestate_vlinestate_callback_t servo_callback;
gpiod_line_request_data_t servo_data;
gpiod_line_request *pan_servo_request, *tilt_servo_request;

void servo_callback(struct gpiod_line_request *request, unsigned int value, unsigned int event) {
    if (event == GPIOD_LINE_EVENT_EDGE_FALLING) {
        servo_data.flags = GPIOD_LINE_REQUEST_FLAG_SET_LOW;
        gpiod_line_request_data(request, &servo_data);
    }
}

int init_servos() {
    pan_servo_request = gpiod_request_line(0, PAN_SERVO_GPIO, "pan_servo", GPIOD_LINE_REQUEST_DIRECTION_OUT, NULL);
    if (!pan_servo_request) {
        perror("Failed to request pan servo line");
        return 1;
    }

    tilt_servo_request = gpiod_request_line(0, TILT_SERVO_GPIO, "tilt_servo", GPIOD_LINE_REQUEST_DIRECTION_OUT, NULL);
    if (!tilt_servo_request) {
        perror("Failed to request tilt servo line");
        gpiod_line_release(pan_servo_request);
        return 1;
    }

    servo_data.flags = GPIOD_LINE_REQUEST_FLAG_SET_LOW;
    gpiod_line_request_data(pan_servo_request, &servo_data);
    gpiod_line_request_data(tilt_servo_request, &servo_data);
    gpiod_line_request_set_debounce(pan_servo_request, 10);
    gpiod_line_request_set_debounce(tilt_servo_request, 10);
    gpiod_line_request_set_glitch_filter(pan_servo_request, 10);
    gpiod_line_request_set_glitch_filter(tilt_servo_request, 10);
    gpiod_line_request_set_callback(pan_servo_request, servo_callback);
    gpiod_line_request_set_callback(tilt_servo_request, servo_callback);

    return 0;
}

void set_servo_pwm(int gpio, int pwm) {
    if (pwm < SERVO_MIN_PWM || pwm > SERVO_MAX_PWM) {
        fprintf(stderr, "Invalid PWM value: %d\n", pwm);
        return;
    }

    servo_data.value = pwm;
    gpiod_line_request_data(gpio_get_line_request(gpio, gpio), &servo_data);
}

void move_servos(int pan_angle, int tilt_angle) {
    int pan_pwm = SERVO_NEUTRAL_PWM + (pan_angle - 90) * SERVO_STEP;
    int tilt_pwm = SERVO_NEUTRAL_PWM + (tilt_angle - 90) * SERVO_STEP;

    if (pan_pwm < SERVO_MIN_PWM || pan_pwm > SERVO_MAX_PWM) {
        fprintf(stderr, "Invalid pan angle: %d\n", pan_angle);
        return;
    }

    if (tilt_pwm < SERVO_MIN_PWM || tilt_pwm > SERVO_MAX_PWM) {
        fprintf(stderr, "Invalid tilt angle: %d\n", tilt_angle);
        return;
    }

    set_servo_pwm(pan_servo_request->gpiod, pan_pwm);
    usleep(DELAY_MS * 1000);
    set_servo_pwm(tilt_servo_request->gpiod, tilt_pwm);
    usleep(DELAY_MS * 1000);
}

void cleanup() {
    set_servo_pwm(pan_servo_request->gpiod, SERVO_NEUTRAL_PWM);
    set_servo_pwm(tilt_servo_request->gpiod, SERVO_NEUTRAL_PWM);
    gpiod_line_release(pan_servo_request);
    gpiod_line_release(tilt_servo_request);
}

int main() {
    if (init_servos()) {
        fprintf(stderr, "Failed to initialize servos\n");
        return 1;
    }

    move_servos(90, 90);

    char c;
    while (1) {
        if (scanf("%c", &c) != 1) {
            perror("Failed to read input");
            goto cleanup_and_exit;
        }

        switch (c) {
            case 'w':
                move_servos(90 + SERVO_STEP, 90);
                break;
            case 's':
                move_servos(90 - SERVO_STEP, 90);
                break;
            case 'a':
                move_servos(90, 90 + SERVO_STEP);
                break;
            case 'd':
                move_servos(90, 90 - SERVO_STEP);
                break;
            case 'q':
                goto cleanup_and_exit;
            default:
                fprintf(stderr, "Invalid input: %c\n", c);
        }
    }

cleanup_and_exit:
    cleanup();
    gpiod_unprobe(0);
    return 1;
}

