#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/i2c-dev.h>
#include <spidev.h>
#include <gpiod.h>
#include <pigpio.h>

#define ADC_ADDR 0x60 // MCP3008 I2C address
#define ADC_CH 0 // ADC channel
#define LCD_ADDR 0x27 // PCF8574 I2C address
#define LCD_RS 0x00
#define LCD_RW 0x01
#define LCD_EN 0x02
#define LCD_D4 0x04
#define LCD_D5 0x05
#define LCD_D6 0x06
#define LCD_D7 0x07

struct spi_ioc_transfer spi_transfers[] = {
    {
        .tx_buf = (unsigned char*)&ADC_CH,
        .rx_buf = (unsigned char*)&adc_value,
        .len = sizeof(ADC_CH),
        .delay_usecs = 10,
    },
};

int main() {
    int spi_fd, i2c_fd, gpio_fd;
    struct gpiod_line *line;
    int adc_value = 0;
    unsigned int wind_speed = 0;
    unsigned int wind_direction = 0;
    int samples = 0;
    int pulse_count = 0;
    int ret;

    // Initialize SPI
    if ((spi_fd = spi_open(0, O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        exit(1);
    }

    if (spi_xfer(spi_fd, spi_transfers, sizeof(spi_transfers) / sizeof(struct spi_ioc_transfer)) < 0) {
        fprintf(stderr, "Failed to read ADC value\n");
        exit(1);
    }

    // Initialize I2C
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        exit(1);
    }

    // Initialize GPIO
    if ((gpio_fd = gpiod_open_name("gpiochip0", "gpio17")) < 0) {
        fprintf(stderr, "Failed to open GPIO line 17\n");
        exit(1);
    }

    line = gpiod_get_line(gpio_fd, GPIOD_ASIS);
    gpiod_line_request_interrupt_edge(line, GPIOD_EDGE_RISING);

    // Initialize LCD
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize LCD\n");
        exit(1);
    }

    while (1) {
        // Read anemometer pulse
        if (gpiod_line_get_value(line)) {
            pulse_count++;
        }

        // Sample wind speed over 500ms
        if (++samples >= 100) {
            samples = 0;
            wind_speed = pulse_count * 2 * 10; // Convert to m/s (assuming 2 pulses per revolution and 2.2m per pulse)
            pulse_count = 0;
        }

        // Read wind direction from ADC
        if (spi_xfer(spi_fd, spi_transfers, sizeof(spi_transfers) / sizeof(struct spi_ioc_transfer)) < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue;
        }

        // Map ADC value to wind direction (assuming 0-1023 corresponds to 0-360 degrees)
        wind_direction = (adc_value / 10.24) % 360;

        // Update LCD
        lcd_clear();
        lcd_home();
        sprintf(lcd_str, "Wind: %d m/s", wind_speed);
        lcd_puts(lcd_str);
        lcd_home();
        sprintf(lcd_str, "Dir: %d deg", wind_direction);
        lcd_puts(lcd_str);

        usleep(500000); // Wait 500ms
    }

    // Cleanup
    gpiod_line_put(line);
    gpiod_line_release(line);
    close(gpio_fd);
    close(i2c_fd);
    close(spi_fd);
    gpioTerm();

    return 0;
}

