static const char *i2c_dev_name = "/dev/i2c-" I2C_BUS;
static const char *log_file = "depth_log.csv";

int i2c_fd, log_fd;
struct i2c_rdwr_ioctl_data {
    struct i2c_msg msgs[1];
};

void log_timestamped_distance(double distance) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char log_line[64];
    snprintf(log_line, sizeof(log_line), "%lu,%f\n", tv.tv_sec, distance);

    if (log_fd < 0) {
        log_fd = open(log_file, O_WRONLY | O_APPEND | O_CREAT, 0644);
        if (log_fd < 0) {
            perror("Failed to open log file");
            return;
        }
        dprintf(log_fd, "Timestamp,Distance\n");
    }

    dprintf(log_fd, "%s", log_line);
}

int i2c_read(uint8_t *buf, size_t len) {
    struct i2c_rdwr_ioctl_data rw;
    rw.msgs[0].addr = MLX75031_I2C_ADDR;
    rw.msgs[0].flags = 0;
    rw.msgs[0].len = len;
    rw.msgs[0].buf = buf;

    if (ioctl(i2c_fd, I2C_RDWR, &rw) < 0) {
        perror("Failed to read from I2C");
        log_timestamped_distance(-1.0);
        return -1;
    }

    return 0;
}

int main(void) {
    int gpio_fd, ret;
    struct gpiod_line_request *gpio_req;
    struct gpiod_line_state gpio_state;

    gpio_fd = gpiod_open_name("gpiochip0", GPIO_LED_PIN);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO");
        exit(EXIT_FAILURE);
    }

    gpio_req = gpiod_chip_get_line_request(gpio_fd, GPIO_LED_PIN);
    if (!gpio_req) {
