        exit(EXIT_FAILURE);
    }

    gpiod_line_request_direction_output(gpio_req, GPIOD_LINE_ACTIVE_HIGH);
    gpiod_line_request_enable(gpio_req, 1);

    i2c_fd = open(i2c_dev_name, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (i2c_read(NULL, 0) < 0) {
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    struct itimerval timer;
    timer.it_interval.tv_usec = 100000;
    timer.it_value.tv_usec = timer.it_interval.tv_usec;
