    if (gpio_fd < 0) {
        perror("Failed to open GPIO");
        exit(EXIT_FAILURE);
    }

    gpio_req = gpiod_chip_get_line_request(gpio_fd, GPIO_LED_PIN);
    if (!gpio_req) {
