        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    struct itimerval timer;
    timer.it_interval.tv_usec = 100000;
    timer.it_value.tv_usec = timer.it_interval.tv_usec;
    if (setitimer(ITIMER_REAL, &timer, NULL) < 0) {
        perror("Failed to set timer");
        exit(EXIT_FAILURE);
