#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <time.h>
#include <linux/i2c-dev.h>
#include <sys/stat.h>
#include <gpiod.h>

#define I2C_BUS 1
#define SI1145_ADDR 0x29
#define AMBIENT_LIGHT_REG 0x0C
#define PROXIMITY_REG 0x0F

static const char *log_file = "biometric_log.txt";

int init_i2c(void) {
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("Failed to acquire I2C address");
        close(i2c_fd);
        return 1;
    }

    return i2c_fd;
}

void log_data(int i2c_fd, uint16_t ambient_light, uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%f", timeinfo);

    FILE *log_file_fd = fopen(log_file, "a");
    if (log_file_fd == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file_fd, "%s,Ambient Light: %u, Proximity: %u\n", timestamp, ambient_light, proximity);
    fclose(log_file_fd);
}

void sigint_handler(int signum) {
    int i2c_fd = -1;
    if ((i2c_fd = gpiod_get_fd(0)) >= 0) {
        gpiod_set_value_cansleep(i2c_sda, 0);
        gpiod_set_value_cansleep(i2c_scl, 0);
        close(i2c_fd);
    }

    FILE *log_file_fd = fopen(log_file, "r+");
    if (log_file_fd != NULL) {
        fseek(log_file_fd, 0, SEEK_SET);
        ftruncate(fileno(log_file_fd), 0);
        fclose(log_file_fd);
    }

    remove(log_file);
    exit(0);
}

int main(void) {
    int i2c_fd = -1;
    uint16_t ambient_light = 0;
    uint16_t proximity = 0;
    struct gpiod_line_request sda_req = GPIOD_LINE_REQUEST_DIRECTION_IN | GPIOD_LINE_REQUEST_EDGE_RISING | GPIOD_LINE_REQUEST_ACTIVE_LOW;
    struct gpiod_line_request scl_req = GPIOD_LINE_REQUEST_DIRECTION_OUT | GPIOD_LINE_REQUEST_EDGE_RISING | GPIOD_LINE_REQUEST_ACTIVE_LOW;

    if (gpiod_chip_open_byname("gpiochip0") < 0) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    if (gpiod_line_request_get_fd(gpiod_chip_get_line(GPIOD_CHIP_NAME_GPIOCHIP0, 2), &sda_req) < 0) {
        perror("Failed to request SDA line");
        goto cleanup;
    }

    if (gpiod_line_request_get_fd(gpiod_chip_get_line(GPIOD_CHIP_NAME_GPIOCHIP0, 3), &scl_req) < 0) {
        perror("Failed to request SCL line");
        goto cleanup;
    }

    i2c_fd = init_i2c();
    if (i2c_fd < 0) {
        goto cleanup;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        if (read_i2c_reg16(i2c_fd, AMBIENT_LIGHT_REG, &ambient_light) < 0) {
            perror("Failed to read ambient light data");
            continue;
        }

        if (read_i2c_reg16(i2c_fd, PROXIMITY_REG, &proximity) < 0) {
            perror("Failed to read proximity data");
            continue;
        }

        log_data(i2c_fd, ambient_light, proximity);
        usleep(500000);
    }

cleanup:
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    if (gpiod_line_request_get_fd(gpiod_chip_get_line(GPIOD_CHIP_NAME_GPIOCHIP0, 2), NULL) >= 0) {
        gpiod_line_release(gpiod_line_request_get_fd(gpiod_chip_get_line(GPIOD_CHIP_NAME_GPIOCHIP0, 2)));
    }

    if (gpiod_line_request_get_fd(gpiod_chip_get_line(GPIOD_CHIP_NAME_GPIOCHIP0, 3), NULL) >= 0) {
        gpiod_line_release(gpiod_line_request_get_fd(gpiod_chip_get_line(GPIOD_CHIP_NAME_GPIOCHIP0, 3)));
    }

    gpiod_chip_close(gpiod_chip_get_fd(0));

    return 0;
}

int read_i2c_reg16(int i2c_fd, uint8_t reg, uint16_t *data) {
    uint8_t buf[2];

    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(i2c_fd, buf, 2) != 2) {
        perror("Failed to read data");
        return -1;
    }

    *data = (buf[0] << 8) | buf[1];
    return 0;
}

