code:
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/types.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SENSOR_GPIO 4
#define LED_GPIO 17
#define GPIO_LINE_ACTIVE_LOW 0

static const char *const gpiochip_name = "gpiochip0";
static gpiod_line_request_lines_data_t lines_data = {
    .lines = (const gpiod_line_request_data_t[]) {
        [SENSOR_GPIO] = { .direction = GPIOD_IN, .edge_detected_callback = NULL },
        [LED_GPIO] = { .direction = GPIOD_OUT_INVERSE, .value = GPIO_LINE_ACTIVE_LOW },
    },
    .n_lines = 2,
};

static gpiod_line_handle_t sensor_line, led_line;
static FILE *log_file;

void sensor_edge_callback(struct gpiod_line_request *request, unsigned int line, unsigned int value, unsigned int events)
{
    if (events & GPIOD_EDGE_FALLING) {
        time_t rawtime;
        struct tm *timeinfo;
        char time_str[32];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(time_str, sizeof(time_str), "%Y-%m-%dT%H:%M:%S", timeinfo);
        strftime(time_str + 14, sizeof(time_str) - 14, "%z", timeinfo);

        if (log_file) {
            fprintf(log_file, "%s Object detected\n", time_str);
            fflush(log_file);
        }

        gpiod_line_set_value(led_line, !GPIO_LINE_ACTIVE_LOW);
        usleep(100000);
        gpiod_line_set_value(led_line, GPIO_LINE_ACTIVE_LOW);
    }
}

int main(void)
{
    int ret;
    int spi_fd;

    log_file = fopen("proximity.log", "w");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        goto cleanup_log;
    }

    ret = gpiod_chip_open_by_name(gpiochip_name, &gpiod_chip);
    if (ret < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_strerror(ret));
        ret = gpiod_chip_open(0, &gpiod_chip);
        if (ret < 0) {
            perror("gpiod_chip_open");
            goto cleanup_spi;
        }
    }

    ret = gpiod_line_request_lines(&gpiod_chip, &lines_data, GPIOD_PROBE_ONE_LINE);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO lines: %s\n", gpiod_strerror(ret));
        goto cleanup_chip;
    }

    sensor_line = lines_data.lines[SENSOR_GPIO].handle;
    led_line = lines_data.lines[LED_GPIO].handle;

    gpiod_line_enable_edge(sensor_line, GPIOD_EDGE_FALLING);
    gpiod_line_set_debounce(sensor_line, 10);
    gpiod_line_set_edge_callback(sensor_line, sensor_edge_callback);

    while (1) {
        usleep(100000);
        gpiod_line_get_value(sensor_line, NULL);
    }

cleanup_chip:
    gpiod_line_release(sensor_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(gpiod_chip);

cleanup_spi:
    close(spi_fd);

cleanup_log:
    if (log_file) {
        fclose(log_file);
    }

    return ret;
}

