#include <sys/mman.h>

#define I2C_BUS 1
#define SI1145_ADDR 0x29
#define PROX_REG 0x01
#define AMB_LIGHT_REG 0x03
#define BUFFER_SIZE 256

gpiod_line_request_linenum_data_v2_devdata_t *gpio_line;
int i2c_fd;

void sigint_handler(int signum) {
    if (gpio_line) gpiod_line_release(gpio_line);
    if (i2c_fd >= 0) close(i2c_fd);
    if (gpio_line->data->consumer_data) free(gpio_line->data->consumer_data);
    free(gpio_line);
    exit(0);
}

int init_gpio() {
    int ret;
    gpiod_line_request_flags_t flags = GPIOD_LINE_REQUEST_DIRECTION_IN | GPIOD_LINE_REQUEST_EDGE_RISING | GPIOD_LINE_REQUEST_ACTIVE_LOW;

    gpio_line = calloc(1, sizeof(gpiod_line_request_linenum_data_v2_devdata_t));
    if (!gpio_line) return -1;

    ret = gpiod_chip_open_byname("gpiochip0");
    if (ret < 0) {
        perror("Failed to open gpiochip0");
        free(gpio_line);
        return ret;
    }

    ret = gpiod_chip_get_line_bylabel(gpio_line->chip, "GPIO18");
    if (ret < 0) {
        perror("Failed to get GPIO18");
        gpiod_chip_close(gpio_line->chip);
        free(gpio_line);
        return ret;
    }

    ret = gpiod_line_request_dt(gpio_line, flags, "si1145_reset");
    if (ret < 0) {
        perror("Failed to request GPIO18");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_line->chip);
        free(gpio_line);
        return ret;
    }

    gpio_line->data->consumer_data = malloc(sizeof(struct timespec));
    if (!gpio_line->data->consumer_data) {
        perror("Failed to allocate consumer data");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_line->chip);
        free(gpio_line);
        return -1;
    }

    return 0;
}

int init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("Failed to acquire I2C bus address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

int read_sensor() {
    uint8_t buf[2];
    int ret;

    ret = read(i2c_fd, buf, 2);
    if (ret != 2) {
        perror("Failed to read from Si1145 sensor");
        return -1;
    }

    return (buf[0] << 8) | buf[1];
}

int main() {
    int ret;
    struct timespec ts;
    FILE *log_file;
    char log_filename[32];

    if (init_gpio() < 0) return 1;

    if (init_i2c() < 0) return 1;

    signal(SIGINT, sigint_handler);

    log_file = fopen("biometric_data.log", "w");
    if (!log_file) {
        perror("Failed to open log file");
        goto cleanup;
    }

    while (1) {
        gpiod_line_get_value_with_timeout(gpio_line, &ts);
        if (gpiod_line_get_value(gpio_line)) {
            gpiod_line_get_value_with_timeout(gpio_line, &ts);
            ret = read_sensor();
            if (ret < 0) continue;

            snprintf(log_filename, sizeof(log_filename), "%ld-%09d,%d,%d\n",
                     (long)ts.tv_sec, ts.tv_nsec, ret & 0xFFF, (ret >> 12) & 0xFFF);
            fwrite(log_filename, strlen(log_filename), 1, log_file);
            fflush(log_file);
        }

        usleep(100000);
    }

cleanup:
    if (log_file) fclose(log_file);

    sigint_handler(SIGINT);

    return 0;
}
```

This code initializes the GPIO line for the Si1145 reset, opens the I2C bus, and reads the proximity and ambient light data from the sensor. It logs the data to a CSV file with an ISO-8601 timestamp. The program also handles errors gracefully and installs a SIGINT handler to clean up resources upon termination.

