#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/types.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define TRIGGER_GPIO 17
#define ECHO_GPIO 27
#define VOLTAGE_DIVIDER_R1 1000
#define VOLTAGE_DIVIDER_R2 2000
#define MAX_DISTANCE 400
#define MIN_DISTANCE 2
#define LOG_FILE "distance_log.txt"
#define LOG_INTERVAL 60
#define TIME_TO_WATER 15

struct gpiod_line_request *trigger, *echo;
struct timespec timeout;

void log_timestamped(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_string[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(time_string, sizeof(time_string), "%Y-%m-%dT%H:%M:%S", timeinfo);
    fprintf(stderr, "%s: %s\n", time_string, message);
}

void log_distance(float distance) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        return;
    }

    time_t rawtime;
    struct tm *timeinfo;
    char time_string[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(time_string, sizeof(time_string), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(log_file, "%s: Distance out of range: %.2f cm\n", time_string, distance);
    } else if (distance < TIME_TO_WATER) {
        fprintf(log_file, "%s: Time to water the plant!\n", time_string);
    } else {
        fprintf(log_file, "%s: Distance: %.2f cm\n", time_string, distance);
    }

    fclose(log_file);
}

void gpiod_init() {
    int ret;

    ret = gpiod_library_get("gpiochip0");
    if (ret < 0) {
        perror("gpiod_library_get");
        exit(EXIT_FAILURE);
    }

    trigger = gpiod_chip_get_line(gpiod_library_get_data(), TRIGGER_GPIO);
    if (!trigger) {
        perror("gpiod_chip_get_line");
        exit(EXIT_FAILURE);
    }

    echo = gpiod_chip_get_line(gpiod_library_get_data(), ECHO_GPIO);
    if (!echo) {
        perror("gpiod_chip_get_line");
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_direction_output(trigger, GPIOD_LINE_ACTIVE_HIGH);
    gpiod_line_request_direction_input(echo, GPIOD_LINE_ACTIVE_HIGH);
}

float measure_distance() {
    float distance;
    uint32_t start_time, end_time;

    gpiod_line_set_value(trigger, 1);
    usleep(10);
    gpiod_line_set_value(trigger, 0);

    timeout.tv_sec = 30;
    timeout.tv_nsec = 0;

    if (gpiod_line_get_value(echo) == 0) {
        log_timestamped("Sensor absent");
        return NAN;
    }

    nanosleep(&timeout, NULL);

    if (gpiod_line_get_value(echo)) {
        log_timestamped("Timeout");
        return NAN;
    }

    start_time = gpiod_line_get_event_time(echo, GPIOD_LINE_EVENT_RISING_EDGE);
    nanosleep(&timeout, NULL);
    end_time = gpiod_line_get_event_time(echo, GPIOD_LINE_EVENT_FALLING_EDGE);

    if (start_time == -1 || end_time == -1) {
        log_timestamped("Error getting event times");
        return NAN;
    }

    float pulse_width = (end_time - start_time) * 1e-9;
    distance = pulse_width * 17150;

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        log_distance(NAN);
        return NAN;
    }

    return distance;
}

void cleanup() {
    if (trigger) gpiod_line_release(trigger);
    if (echo) gpiod_line_release(echo);
    gpiod_library_put(gpiod_library_get_data());
}

int main() {
    float distance;
    struct timespec last_log_time;

    gpiod_init();

    clock_gettime(CLOCK_REALTIME, &last_log_time);

    while (1) {
        distance = measure_distance();
        if (isnan(distance)) continue;

        log_distance(distance);

        clock_gettime(CLOCK_REALTIME, &last_log_time);
        if (difftime(last_log_time.tv_sec, time(NULL)) > LOG_INTERVAL) {
            last_log_time = *localtime(&time(NULL));
            continue;
        }

        sleep(1);
    }

    cleanup();
    return 0;
}

