#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <sys/time.h>
#include <errno.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define APDS9960_ADDR 0x39
#define PROX_THRESHOLD 200
#define CSV_FILE "color_proximity_log.csv"

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int num_lines,
                                const char *const *lines, unsigned int flags)
{
    return gpiod_chip_get_lines_request_array(chip, num_lines, lines, flags);
}

int main(void) {
    int i2c_fd, ret;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg i2c_msgs[2];
    struct timespec ts;
    struct gpiod_chip *chip;
    struct gpiod_line_request *proximity_req;
    FILE *csv_file;
    char csv_line[128];
    uint8_t data[6];

    // Initialize GPIO
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    proximity_req = CSV_FILE(chip, "gpio17", GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_RISING);
    if (!proximity_req) {
        perror("Failed to request GPIO line");
        gpiod_chip_put(chip);
        return 1;
    }

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpiod_line_request_free(proximity_req);
        gpiod_chip_put(chip);
        return 1;
    }

    // Initialize APDS9960
    i2c_msgs[0].addr = APDS9960_ADDR;
    i2c_msgs[0].flags = 0;
    i2c_msgs[0].len = 1;
    i2c_msgs[0].buf = (uint8_t*)&(0x80); // Enable all sensors
    i2c_msgs[1].addr = APDS9960_ADDR;
    i2c_msgs[1].flags = 0;
    i2c_msgs[1].len = 0;

    if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) < 0) {
        perror("Failed to initialize APDS9960");
        close(i2c_fd);
        gpiod_line_request_free(proximity_req);
        gpiod_chip_put(chip);
        return 1;
    }

    csv_file = fopen(CSV_FILE, "w");
    if (!csv_file) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        gpiod_line_request_free(proximity_req);
        gpiod_chip_put(chip);
        return 1;
    }

    while (1) {
        // Read data from APDS9960
        i2c_msgs[0].addr = APDS9960_ADDR;
        i2c_msgs[0].flags = 0;
        i2c_msgs[0].len = 6;
        i2c_msgs[1].addr = APDS9960_ADDR;
        i2c_msgs[1].flags = I2C_M_RD;
        i2c_msgs[1].len = 6;

        if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) < 0) {
            perror("Failed to read data from APDS9960");
            continue;
        }

        memcpy(data, i2c_data.msgs[1].buf, 6);

        // Check proximity
        if (data[0] & (1 << 6)) {
            if (data[1] > PROX_THRESHOLD) {
                // Format and write CSV line
                ts.tv_sec = time(NULL);
                ts.tv_nsec = (data[2] << 16) | (data[3] << 8) | data[4];
                snprintf(csv_line, sizeof(csv_line), "%ld,%06x,%06x,%06x,%d\n", ts.tv_sec * 1e9 + ts.tv_nsec, data[2], data[3], data[4], data[1]);
                fwrite(csv_line, 1, strlen(csv_line), csv_file);
            }
        }

        // Sleep for 100ms
        ts.tv_sec = 0;
        ts.tv_nsec = 100 * 1e6;
        nanosleep(&ts, NULL);
    }

    // Cleanup
    fclose(csv_file);
    close(i2c_fd);
    gpiod_line_request_free(proximity_req);
    gpiod_chip_put(chip);

    return 0;
}

