#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <sys/time.h>
#include <errno.h>
#include <signal.h>
#include <gpiod.h>

#define SI1182_ADDR 0x29
#define PROX_REG 0x00
#define HR_REG 0x01

volatile sig_atomic_t running = 1;

static int i2c_file;
static gpiod_line_request_lines_data_v1 lines_data = { .lines = { { .direction = GPIOD_LINE_DIR_IN, .edge_detected_callback = NULL, .debounce_timeout_ns = 10000000 } } };
static gpiod_line_handle_v1 *heart_rate_led;

void sigint_handler(int signum) {
    running = 0;
}

int init_i2c() {
    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

