#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <sys/time.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod.h>
#include <i2c/smbus.h>
#include <sys/mman.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x29
#define TRIG_PIN 18
#define ECHO_PIN 17
#define BUFFER_SIZE 64
#define LOG_FILE "distance_log.txt"

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int nlines,
                                const char *const *lines, unsigned int flags)
{
    return gpiod_chip_get_lines_request_array(chip, nlines, lines, flags);
}

static void i2c_write_byte(int file, unsigned char reg, unsigned char data)
{
    struct i2c_smbus_msg msg = {
        .read_write = I2C_SMBUS_WRITE,
        .addr = SENSOR_ADDR << 1,
        .data = data,
        .flags = 0,
        .len = 1,
        .buf = &data,
    };

    if (i2c_smbus_xfer(file, &msg, 1) < 0) {
        perror("i2c_write_byte");
    }
}

static unsigned char i2c_read_byte(int file, unsigned char reg)
{
    struct i2c_smbus_msg msg = {
        .read_write = I2C_SMBUS_READ,
        .addr = SENSOR_ADDR << 1,
        .data = reg,
        .flags = 0,
        .len = 1,
        .buf = malloc(1),
    };

    if (i2c_smbus_xfer(file, &msg, 1) < 0) {
        perror("i2c_read_byte");
        free(msg.buf);
        return 0;
    }

    return *msg.buf;
}

static void setup_gpio(void)
{
    struct gpiod_chip *chip;
    struct gpiod_line_request *request;
    int ret;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("gpiochip0");
        exit(EXIT_FAILURE);
    }

    request = gpiod_line_request_array_get(
        chip, TRIG_PIN, GPIOD_LINE_REQUEST_DIRECTION_OUT,
        GPIOD_LINE_REQUEST_ACTIVE_LOW, NULL);
    if (!request) {
        perror("TRIG_PIN");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_enable(request);
    if (ret < 0) {
        perror("TRIG_PIN enable");
        exit(EXIT_FAILURE);
    }

    request = gpiod_line_request_array_get(
        chip, ECHO_PIN, GPIOD_LINE_REQUEST_INPUT, 0, NULL);
    if (!request) {
        perror("ECHO_PIN");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_enable(request);
    if (ret < 0) {
        perror("ECHO_PIN enable");
        exit(EXIT_FAILURE);
    }
}

static void log_distance(const char *timestamp, unsigned short distance)
{
    FILE *file;
    char buffer[BUFFER_SIZE];

    file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("fopen");
        return;
    }

    snprintf(buffer, BUFFER_SIZE, "%s, %hu\n", timestamp, distance);
    fputs(buffer, file);
    fclose(file);

    printf("%s, %hu\n", timestamp, distance);
}

static void i2c_init(void)
{
    int file;
    if ((file = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }
}

static void sigint_handler(int signum)
{
    gpiod_chip_release(chip);
    close(i2c_file);
    fclose(log_file);
    exit(EXIT_SUCCESS);
}

int main(void)
{
    struct timeval tv;
    unsigned char data;
    unsigned short distance;
    int i2c_file;
    FILE *log_file;
    struct gpiod_chip *chip;
    struct gpiod_line_request *request;

    signal(SIGINT, sigint_handler);

    setup_gpio();
    i2c_init();

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    while (1) {
        gettimeofday(&tv, NULL);
        char timestamp[32];
        snprintf(timestamp, sizeof(timestamp), "%04d-%02d-%02d %02d:%02d:%02d",
                 tv.tv_year, tv.tv_mon, tv.tv_mday, tv.tv_hour, tv.tv_min, tv.tv_sec);

        gpiod_line_set_value(request, 0);
        usleep(50 * 1000);
        gpiod_line_set_value(request, 1);
        usleep(200 * 1000);

        data = i2c_read_byte(i2c_file, 0x04);
        if (data == 0xFF) {
            perror("i2c_read_byte");
            continue;
        }

        distance = (data << 8) | i2c_read_byte(i2c_file, 0x05);
        log_distance(timestamp, distance);
    }

    gpiod_chip_release(chip);
    close(i2c_file);
    fclose(log_file);

    return 0;
}

