#include <linux/i2c-dev.h>
#include <sys/time.h>
#include <time.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <gpiod.h>

#define I2C_BUS 1
#define ICU20201_ADDR 0x28
#define GPIO_LINE_LED 17

static int i2c_fd;
static struct gpiod_line_data gpio_data;
static gpiod_line_handle_t gpio_handle;

void i2c_init() {
    const char *i2c_dev = "/dev/i2c-" + std::to_string(I2C_BUS);
    if ((i2c_fd = open(i2c_dev.c_str(), O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ICU20201_ADDR) < 0) {
        perror("Failed to acquire bus access");
        exit(EXIT_FAILURE);
    }
}

void gpio_init() {
    const char *gpio_dev = "/dev/gpiochip0";
    if (gpiod_chip_open_byname(gpio_dev, &gpio_data) < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output_raw_byname(&gpio_data, "gpiochip0\0" GPIO_LINE_LED, &gpio_handle, GPIOD_LINE_REQUEST_ACTIVE_LOW) < 0) {
        perror("Failed to request GPIO line");
        exit(EXIT_FAILURE);
    }
}

void log_distance(float distance) {
    char timestamp[32];
    struct timeval tv;
    gettimeofday(&tv, NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%f", localtime(&tv.tv_sec));
    printf("%s,%f\n", timestamp, distance);

    FILE *log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    fprintf(log_file, "%s,%f\n", timestamp, distance);
    fclose(log_file);
}

float read_distance() {
    uint8_t buf[2];
    if (write(i2c_fd, &ICU20201_MEASURE_CMD, 1) != 1) {
        perror("Failed to write to I2C device");
        exit(EXIT_FAILURE);
    }

    if (read(i2c_fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        exit(EXIT_FAILURE);
    }

    uint16_t distance = (buf[0] << 8) | buf[1];
    return distance * 0.01f; // Convert from 10-bit raw value to cm
}

void signal_handler(int sig) {
    gpiod_line_put_raw(gpio_handle, !gpio_data.lines[GPIO_LINE_LED].active);
    gpiod_line_release(gpio_handle);
    close(i2c_fd);
    gpiod_chip_close(&gpio_data);
    exit(0);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_init();
    gpio_init();

    while (true) {
        float distance = read_distance();
        gpiod_line_put_raw(gpio_handle, distance < 20.0f);
        log_distance(distance);
        usleep(100000); // Sleep for 100ms
    }

    return 0;
}

