#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <sys/time.h>
#include <gpiod.h>

#define I2C_BUS 1
#define SI1182_ADDR 0x29
#define AMBIENT_LIGHT_REG 0x0C
#define PROXIMITY_REG 0x0F
#define LOG_FILE "biometric_log.txt"

static int i2c_file;
static struct gpiod_chip *chip;
static gpiod_line_request_lines_data_v1 lines_data = {0};

void sigint_handler(int signum) {
    gpiod_line_release_request(chip, lines_data.requests[0]);
    close(i2c_file);
    remove(LOG_FILE);
    exit(0);
}

int init_i2c() {
    const char *i2c_dev = "/dev/i2c-" I2C_BUS;
    if ((i2c_file = open(i2c_dev, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(i2c_file, I2C_SLAVE, SI1182_ADDR) < 0) {
        perror("Failed to acquire I2C bus");
        close(i2c_file);
        return -1;
    }

    return 0;
}

int init_gpio() {
    if ((chip = gpiod_chip_open_byname("gpiochip0")) == NULL) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    lines_data.n_lines = 1;
    lines_data.requests = calloc(lines_data.n_lines, sizeof(struct gpiod_line_request));
    lines_data.lines = calloc(lines_data.n_lines, sizeof(struct gpiod_line));

    lines_data.requests[0].consumer = "Si1182 sensor";
    lines_data.requests[0].flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW;

    if (gpiod_chip_request_lines(chip, &lines_data, GPIOD_LINE_REQUEST_SLEW_FAST) < 0) {
        perror("Failed to request GPIO lines");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

int read_sensor() {
    int retries = 3;
    int ambient_light = 0;
    int proximity = 0;

    while (retries > 0) {
        if (write(i2c_file, &AMBIENT_LIGHT_REG, 1) != 1) {
            perror("Failed to write AMBIENT_LIGHT_REG");
            usleep(500000);
            retries--;
            continue;
        }

        if (read(i2c_file, &ambient_light, 2) != 2) {
            perror("Failed to read AMBIENT_LIGHT_REG");
            usleep(500000);
            retries--;
            continue;
        }

        if (write(i2c_file, &PROXIMITY_REG, 1) != 1) {
            perror("Failed to write PROXIMITY_REG");
            usleep(500000);
            retries--;
            continue;
        }

        if (read(i2c_file, &proximity, 2) != 2) {
            perror("Failed to read PROXIMITY_REG");
            usleep(500000);
            retries--;
            continue;
        }

        break;
    }

    if (retries == 0) {
        perror("Failed to read sensor after retries");
        return -1;
    }

    return (ambient_light << 8) | proximity;
}

int main() {
    struct timeval tv;
    struct tm *tm;
    char timestamp[32];
    int result;

    signal(SIGINT, sigint_handler);

    if (init_gpio() < 0) {
        perror("Failed to initialize GPIO");
        return -1;
    }

    if (init_i2c() < 0) {
        perror("Failed to initialize I2C");
        goto cleanup_gpio;
    }

    if ((FILE *log_file = fopen(LOG_FILE, "w")) == NULL) {
        perror("Failed to open log file");
        goto cleanup_i2c;
    }

    while (1) {
        gettimeofday(&tv, NULL);
        tm = localtime(&tv.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        result = read_sensor();
        if (result < 0) {
            perror("Failed to read sensor data");
            continue;
        }

        fprintf(log_file, "%s: ambient_light=%d, proximity=%d\n", timestamp, (result >> 8) & 0xFF, result & 0xFF);
        fflush(log_file);

        usleep(500000);
    }

cleanup_i2c:
    close(i2c_file);
cleanup_gpio:
    gpiod_chip_release_request(chip, lines_data.requests[0]);
    gpiod_chip_close(chip);
    free(lines_data.requests);
    free(lines_data.lines);

    return 0;
}

