#include <time.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define ICU_ADDR 0x20
#define WHO_AM_I 0x00
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100

int main(int argc, char *argv[]) {
    int i2c_fd, ret;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct gpiod_line *gpio_line;
    struct timespec ts;
    unsigned char who_am_i;
    unsigned short read_data[2];
    double distance, threshold;
    char log_str[128];
    time_t rawtime;
    struct tm *time_info;

    if (argc > 2) {
        fprintf(stderr, "Usage: %s [threshold]\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    if (argc == 2)
        threshold = atof(argv[1]);
    else
        threshold = DEFAULT_THRESHOLD;

    // Open I2C bus
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Initialize I2C data structure
    i2c_data.wr_buf = &WHO_AM_I;
    i2c_data.wr_len = 1;
    i2c_data.rd_buf = &who_am_i;
    i2c_data.rd_len = 1;

    // Verify sensor's WHO_AM_I register
    if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) < 0) {
        perror("Failed to read WHO_AM_I register");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (who_am_i != 0x01) {
        fprintf(stderr, "Incorrect WHO_AM_I value\n");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Configure GPIO for output
    gpio_line = gpiod_chip_get_line(libgpiod_get_chip_by_name("gpiochip0"), LED_GPIO);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_output(gpio_line, "tof_led", GPIOD_LINE_ACTIVE_LOW);
    gpiod_line_set_value(gpio_line, 1);

    while (1) {
        // Read data from sensor
        i2c_data.wr_buf = &ICU_CMD_TOF_MEASURE; // ICU command for TOF measurement
        i2c_data.wr_len = 1;
        i2c_data.rd_buf = read_data;
        i2c_data.rd_len = 2;

        if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) < 0) {
            perror("Failed to read TOF data");
            gpiod_line_release(gpio_line);
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        // Calculate distance
        distance = (read_data[0] << 8 | read_data[1]) * 0.001;

        // Log distance and check if threshold is breached
        rawtime = time(NULL);
        time_info = localtime(&rawtime);
        strftime(log_str, sizeof(log_str), "%Y-%m-%d %H:%M:%S ", time_info);
        snprintf(log_str + strlen(log_str), sizeof(log_str) - strlen(log_str), "%f mm\n", distance);

        if (distance < threshold) {
            gpiod_line_set_value(gpio_line, 0);
            fprintf(stderr, "Distance below threshold: %.2f mm\n", distance);
        }

        // Log distance to file
        FILE *log_file = fopen("tof_log.txt", "a");
        if (log_file) {
            fputs(log_str, log_file);
            fclose(log_file);
        } else {
            perror("Failed to open log file");
        }

        // Sleep for 50 ms
        ts.tv_sec = 0;
        ts.tv_nsec = 50 * 1e6;
        nanosleep(&ts, NULL);
    }

    // Cleanup
    gpiod_line_release(gpio_line);
    close(i2c_fd);

    return 0;
}

