#include <string.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x20
#define COMMAND_LENGTH 4
#define RESPONSE_LENGTH 15
#define HEADER 0x55
#define DISTANCE_OFFSET 11

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int nlines,
                                const char *const names, unsigned int flags) {
    return gpiod_chip_get_lines_request_array(chip, nlines, names, flags);
}

void sigint_handler(int signum) {
    printf("\nExiting...\n");
    close(i2c_fd);
    fclose(log_file);
    gpiod_line_release_request(gpio_request);
    gpiod_chip_deinitialize(gpio_chip);
    gpiod_deinitialize();
    exit(0);
}

int main() {
    int i2c_fd, ret;
    char command[COMMAND_LENGTH] = {0x55, 0x00, 0x00, 0x00};
    char response[RESPONSE_LENGTH];
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg messages[2];
    struct timespec delay;
    int average_distance = 0;
    FILE *log_file;
    struct gpiod_chip *gpio_chip;
    struct gpiod_line_request *gpio_request;
    struct timespec ts;

    if ((gpio_chip = gpiod_chip_open_byname("gpiochip0")) == NULL) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    if ((gpio_request = gpiod_line_request_array(gpio_chip, 1, "led", GPIOD_LINE_REQUEST_DIRECTION_OUT)) == NULL) {
        perror("Failed to request GPIO line");
        gpiod_chip_deinitialize(gpio_chip);
        gpiod_deinitialize();
        return 1;
    }

    if (gpiod_line_set_value(gpio_request, 1) < 0) {
        perror("Failed to set GPIO line");
        gpiod_line_release_request(gpio_request);
        gpiod_chip_deinitialize(gpio_chip);
        gpiod_deinitialize();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        gpiod_line_release_request(gpio_request);
        gpiod_chip_deinitialize(gpio_chip);
        gpiod_deinitialize();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpiod_line_release_request(gpio_request);
        gpiod_chip_deinitialize(gpio_chip);
        gpiod_deinitialize();
        return 1;
    }

    memset(&i2c_data, 0, sizeof(i2c_data));
    messages[0].addr = SENSOR_ADDR;
    messages[0].flags = 0;
    messages[0].len = COMMAND_LENGTH;
    messages[0].buf = command;

    messages[1].addr = SENSOR_ADDR;
    messages[1].flags = I2C_M_RD;
    messages[1].len = RESPONSE_LENGTH;
    messages[1].buf = response;

    i2c_data.wr_msgs = &messages[0];
    i2c_data.nr_msgs = 1;
    i2c_data.rd_msgs = &messages[1];
    i2c_data.nmsgs = 2;

    while (1) {
        ret = ioctl(i2c_fd, I2C_RDWR, &i2c_data);
        if (ret < 0) {
            perror("Failed to read from I2C device");
            continue;
        }

        if (response[0] != HEADER) {
            printf("Invalid response header\n");
            continue;
        }

        average_distance = 0;
        for (int i = 0; i < 10; i++) {
            average_distance += (response[DISTANCE_OFFSET] << 8) | response[DISTANCE_OFFSET + 1];
            delay.tv_sec = 0;
            delay.tv_nsec = 100 * 1e6;
            nanosleep(&delay, NULL);

            ret = ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR);
            if (ret < 0) {
                perror("Failed to set I2C slave address");
                break;
            }

            memset(command, 0, COMMAND_LENGTH);
            command[0] = 0x55;
            command[1]++;
            ret = write(i2c_fd, command, COMMAND_LENGTH);
            if (ret != COMMAND_LENGTH) {
                perror("Failed to write to I2C device");
                break;
            }
        }

        if (average_distance < 1000) {
            clock_gettime(CLOCK_REALTIME, &ts);
            if ((log_file = fopen("intrusion_log.txt", "a")) == NULL) {
                perror("Failed to open log file");
            } else {
                fprintf(log_file, "%ld.%09ld, %d\n", ts.tv_sec, ts.tv_nsec, average_distance);
                fclose(log_file);
            }
        }

        average_distance /= 10;
        printf("Average distance: %d mm\n", average_distance);
    }

    close(i2c_fd);
    gpiod_line_release_request(gpio_request);
    gpiod_chip_deinitialize(gpio_chip);
    gpiod_deinitialize();

    return 0;
}

