#define VL53L0X_MODEL_ID_REG 0x00
#define VL53L0X_RESULT_INTERRUPT_STATUS 0x01
#define VL53L0X_RESULT_RANGE_STATUS_REG 0x05
#define VL53L0X_RESULT_RANGE_VALUE_REG_MSB 0x06
#define VL53L0X_RESULT_RANGE_VALUE_REG_LSB 0x07
#define VL53L0X_RESULT_RANGE_VALUE_REG_XH 0x08

