int init_i2c(int *i2c_fd) {
    const char *i2c_bus = "/dev/i2c-1";
    if ((*i2c_fd = open(i2c_bus, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(*i2c_fd, I2C_SLAVE, VL53L0X_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access");
        close(*i2c_fd);
        return -1;
    }

    return 0;
}

int read_model_id(int i2c_fd, char *model_id) {
    if (i2c_smbus_read_byte_data(i2c_fd, VL53L0X_MODEL_ID_REG) != VL53L0X_MODEL_ID[0]) {
        fprintf(stderr, "Sensor model ID mismatch\n");
        return -1;
    }

    if (i2c_smbus_read_byte_data(i2c_fd, VL53L0X_MODEL_ID_REG + 1) != VL53L0X_MODEL_ID[1]) {
        fprintf(stderr, "Sensor model ID mismatch\n");
        return -1;
    }

    strcpy(model_id, VL53L0X_MODEL_ID);
    return 0;
}

int read_distance(int i2c_fd, uint16_t *distance) {
    uint16_t status;

    if (i2c_smbus_read_byte_data(i2c_fd, VL53L0X_RESULT_INTERRUPT_STATUS) != 0) {
        fprintf(stderr, "Interrupt status read error: %s\n", strerror(errno));
        return -1;
    }

    if (i2c_smbus_read_word_data(i2c_fd, VL53L0X_RESULT_RANGE_VALUE_REG_MSB) == -1) {
        fprintf(stderr, "Distance value read error: %s\n", strerror(errno));
        return -1;
    }

    status = i2c_smbus_read_byte_data(i2c_fd, VL53L0X_RESULT_RANGE_STATUS_REG);
    if ((status & (1 << 7)) != 0) { // Check for range status error
        fprintf(stderr, "Range status error: %s\n", strerror(errno));
        return -1;
    }

    *distance = (i2c_smbus_read_word_data(i2c_fd, VL53L0X_RESULT_RANGE_VALUE_REG_MSB) << 8) |
                i2c_smbus_read_word_data(i2c_fd, VL53L0X_RESULT_RANGE_VALUE_REG_LSB);

    return 0;
}

void cleanup(int i2c_fd, gpiod_line_request_lines_t *gpio_lines) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    if (gpio_lines != NULL) {
        gpiod_line_release_request_lines(gpio_lines);
    }
}

void signal_handler(int signum) {
    cleanup(i2c_fd, gpio_lines);
    exit(0);
}

int main() {
    int i2c_fd = -1;
    gpiod_line_request_lines_t *gpio_lines = NULL;
    char model_id[3];
    uint16_t distance;
    struct timespec timeout = { .tv_sec = 0, .tv_nsec = 100 * NANOSHELL };
    struct tm *time_info;
    char time_str[32];

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_i2c(&i2c_fd) < 0) {
        return 1;
    }

    if (read_model_id(i2c_fd, model_id) < 0) {
        return 1;
    }

    gpio_lines = gpiod_chip_get_line_request_lines(0, "gpiochip0", 1);
    if (gpio_lines == NULL) {
        perror("Failed to get GPIO lines");
        goto cleanup_i2c;
    }

    if (gpiod_line_request_line(gpio_lines, 0, GPIOD_LINE_REQUEST_DIRECTION_IN, "distance_interrupt") < 0) {
        perror("Failed to request GPIO line");
        goto cleanup_gpio;
    }

    while (1) {
        nanosleep(&timeout, NULL);

        if (gpiod_line_get_value(gpio_lines, 0) == 0) {
            if (read_distance(i2c_fd, &distance) < 0) {
                continue;
            }

            time_info = localtime(&time(NULL));
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", time_info);
            printf("%s Distance: %d mm\n", time_str, distance);
        }
    }

cleanup_gpio:
    gpiod_line_release_request_lines(gpio_lines);
cleanup_i2c:
    cleanup(i2c_fd, gpio_lines);

    return 0;
}

