    uint16_t proximity_data;

    if (i2c_smbus_read_word_data(i2c_file, SI1182_REG_PROX_DATA_LSB) < 0) {
        perror("Failed to read proximity data");
        return;
    }

    proximity_data = (i2c_smbus_read_word_data(i2c_file, SI1182_REG_PROX_DATA_MSB) << 8) | i2c_smbus_read_word_data(i2c_file, SI1182_REG_PROX_DATA_LSB);
    printf("Proximity data: 0x%04x\n", proximity_data);
}

int main() {
