This code opens the I2C bus, sets the MLX75030 sensor as the I2C slave, and enters a loop that reads the distance measurement every 500ms. If an I2C read fails, it prints a diagnostic message and continues to the next cycle. If the sensor is not present at startup, it prints an error and exits with status 1. A SIGINT/SIGTERM handler is installed so that pressing Ctrl-C cleanly closes the I2C file descriptor and terminates the program with status 0.

Please note that this code assumes the MLX75030 sensor is using the default I2C address (0x2A). If your sensor uses a different address, you should adjust the `MLX75030_ADDR` constant accordingly.

Also, the MLX75030 sensor communicates using a 2-byte word, so we read 2 bytes and combine them to get the final distance value. The distance is then converted from raw data to millimeters by dividing by 10.

I'll provide a basic example using the `libgpiod` library for GPIO management and `i2c-dev` for I2C communication. Note that you'll need to install the required libraries:

```sh
sudo apt-get install libgpiod-dev i2c-dev
```

Here's the C code:

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define OPT3101_ADDR 0x42
#define CHANNEL_0 0

static int i2c_file;
static struct gpiod_chip *chip;
static gpiod_line_request_lines_data_v1 lines_data = { .lines = { 0 } };

int init_i2c() {
    const char *dev_name = "/dev/i2c-" I2C_BUS;
    if ((i2c_file = open(dev_name, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_file, I2C_SLAVE, OPT3101_ADDR) < 0) {
        perror("Failed to acquire bus access");
        close(i2c_file);
        return -1;
    }

    return 0;
}

void cleanup() {
    if (i2c_file >= 0) {
        close(i2c_file);
    }

    if (chip) {
        gpiod_chip_release(chip);
        chip = NULL;
    }
}

void handle_sigint(int sig) {
    printf("\nGracefully shutting down...\n");
    cleanup();
    exit(0);
}

int read_opt3101() {
    uint8_t data[2];
    int ret;

    ret = i2c_smbus_read_i2c_block_data(i2c_file, 0x00, 2, data);
    if (ret != 2) {
        perror("Failed to read data from OPT3101");
        return -1;
    }

    return (data[0] << 8) | data[1];
}

int main() {
    int ret;

    signal(SIGINT, handle_sigint);

    if ((ret = init_i2c()) != 0) {
        return ret;
    }

    if ((ret = gpiod_chip_open_by_name("gpiochip0")) < 0) {
        perror("Failed to open GPIO chip");
        goto cleanup;
    }

    chip = ret;

    if (gpiod_chip_get_line_info_byname(chip, "GPIO0") < 0) {
        perror("Failed to get GPIO line info");
        goto cleanup;
    }

    lines_data.lines[0] = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_RISING;
    if (gpiod_chip_request_lines(chip, 1, &lines_data, NULL) < 0) {
        perror("Failed to request GPIO line");
        goto cleanup;
    }

    while (1) {
        int distance, light, edge;
        struct timespec ts = { .tv_sec = 0, .tv_nsec = 500 * 1e6 };

        nanosleep(&ts, NULL);

        edge = gpiod_line_get_value(lines_data.lines[0]);
        if (edge) {
            distance = read_opt3101();
            light = read_opt3101();

            printf("Distance: %d mm, Light: %d, Edge: %d\n", distance / 16, light, edge);
        }
    }

cleanup:
    gpiod_chip_release_lines(chip, 1, &lines_data);
    gpiod_chip_close(chip);
    cleanup();

    return 0;
