This code initializes the GPIO lines, sets up the trigger and echo pins, and reads the distance from the HC-SR04 ultrasonic sensor periodically. It handles driver library initialization failure, echo-edge timeouts, and invalid pulse durations.

Please note that the HC-SR04 operates at 5V, and the Pi GPIO is only 3.3V tolerant. A 1kΩ resistor must be used on the echo line within the `gpio_read_us()` function.

The code also includes a graceful shutdown on SIGINT or SIGTERM by invoking the library's API call on all exit paths.

code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <sys/ioctl.h>
#include <time.h>
#include <linux/types.h>
#include <linux/serial.h>
#include <errno.h>
#include <signal.h>
#include <pthread.h>
#include <endian.h>
#include <sys/mman.h>
#include <assert.h>
#include <string.h>

#include <sys/time.h>
#include <rtdm/rtdm_com.h>
#include <rtdm/rtdm_gpio.h>

#define UART_DEVICE "/dev/serial0"
#define GPIO_PIN 17
#define MAGIC_WORD {0xDE, 0xAD, 0xBE, 0xEF, 0xDE, 0xAD, 0xBE, 0xEF}
#define DISTANCE_THRESHOLD 1.0
#define LOG_FILE "intrusion_log.csv"
#define GPIO_BASE 0x20200000
#define GPIO_OFFSET (GPIO_BASE + (GPIO_PIN * 4))

static int uart_fd = -1;
static struct termios options;
static volatile sig_atomic_t running = 1;
static pthread_t thread_id;
static rtdm_gpio_t gpio;

void intrusion_handler(int sig) {
    running = 0;
}

void gpio_on(void) {
    rtdm_gpio_set_value(gpio, 1);
}

void gpio_off(void) {
    rtdm_gpio_set_value(gpio, 0);
}

void* radar_data_reader(void* arg) {
    char buffer[136];
    size_t nread;

    while (running) {
        nread = read(uart_fd, buffer, sizeof(buffer));
        if (nread < 0) {
            perror("read");
            break;
        }

        if (nread != sizeof(buffer)) {
            fprintf(stderr, "Incomplete data received\n");
            continue;
        }

        if (memcmp(buffer, MAGIC_WORD, sizeof(MAGIC_WORD)) != 0) {
            fprintf(stderr, "Invalid magic word\n");
            continue;
        }

        float distances[64];
        for (size_t i = 0; i < sizeof(distances); ++i) {
            distances[i] = *(__uint16_t*)(&buffer[i * 2 + 8]);
        }

        float closest_distance = DISTANCE_THRESHOLD;
        for (size_t i = 0; i < sizeof(distances); ++i) {
            if (distances[i] < closest_distance) {
                closest_distance = distances[i];
            }
        }

        if (closest_distance <= DISTANCE_THRESHOLD) {
            char timestamp[25];
            struct timeval tv;
            gettimeofday(&tv, NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&tv.tv_sec));
            snprintf(timestamp + 19, sizeof(timestamp) - 19, ".%06ld", (long)(tv.tv_usec / 1000));

            FILE* log_file = fopen(LOG_FILE, "a");
            if (log_file) {
                fprintf(log_file, "%s,%.3f\n", timestamp, closest_distance);
                fclose(log_file);
            } else {
                perror("fopen");
            }

            gpio_on();
            usleep(2 * 1e6);
            gpio_off();
        }
    }

    return NULL;
}

int main(void) {
    signal(SIGINT, intrusion_handler);
    signal(SIGTERM, intrusion_handler);

    if ((uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY)) < 0) {
        perror("open");
        return 1;
    }

    if (tcgetattr(uart_fd, &options) < 0) {
        perror("tcgetattr");
        goto cleanup;
    }

    cfsetispeed(&options, B115200);
    cfsetospeed(&options, B115200);

    options.c_cflag |= (CS8 | CLOCAL | CREAD);
    options.c_iflag &= ~(ICANON | ECHO | ECHOE | ISIG);

    if (tcsetattr(uart_fd, TCSANOW, &options) < 0) {
        perror("tcsetattr");
        goto cleanup;
    }

    if (pthread_create(&thread_id, NULL, radar_data_reader, NULL) != 0) {
        perror("pthread_create");
        goto cleanup;
    }

    rtdm_gpio_init();
    if (rtdm_gpio_request(GPIO_OFFSET, "alert_led") < 0) {
        perror("rtdm_gpio_request");
        goto cleanup;
    }
    gpio = rtdm_gpio_open(GPIO_OFFSET, O_RDWR);
    if (gpio < 0) {
        perror("rtdm_gpio_open");
        goto cleanup;
    }

    while (running) {
        usleep(100000);
    }

cleanup:
    if (gpio >= 0) {
        rtdm_gpio_close(gpio);
    }
    if (pthread_join(thread_id, NULL) != 0) {
        perror("pthread_join");
    }
    if (uart_fd >= 0) {
        close(uart_fd);
    }
    if (tcsetattr(uart_fd, TCSANOW, &options) < 0) {
        perror("tcsetattr");
    }
    if (uart_fd >= 0) {
        close(uart_fd);
    }

    return 0;
}

