#include <linux/types.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define GPIO_SENSOR 17
#define GPIO_BUZZER 18

static gpiod_line_request_lines_data_v1 lines_data = {
    .lines = (const gpiod_line_info_v1[]) {
        [GPIO_SENSOR] = { .direction = GPIOD_IN, .edge_detected_callback = NULL },
        [GPIO_BUZZER] = { .direction = GPIOD_OUT_IN, .value = 0 },
    },
    .n_lines = 2,
};

static gpiod_line_request_lines_data_v1* lines_data_ptr = &lines_data;
static gpiod_line_request* request;

static void signal_handler(int signum) {
    gpiod_line_set_value(request, GPIO_BUZZER, 0);
    gpiod_line_release(request, GPIO_BUZZER);
    gpiod_line_request_release(request);
    gpiod_chip_close(request->chip);
    exit(0);
}

int main() {
    struct timeval tv;
    struct tm* time_info;
    char timestamp[32];
    char log_file[] = "obstacle_log.txt";
    int fd_log;
    int ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if ((request = gpiod_chip_request_lines_v1(0, lines_data_ptr)) == NULL) {
        perror("gpiod_chip_request_lines_v1");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_validate(request) < 0) {
        perror("gpiod_line_request_validate");
        goto cleanup;
    }

    if (gpiod_line_request_enable(request) < 0) {
        perror("gpiod_line_request_enable");
        goto cleanup;
    }

    while (1) {
        gpiod_line_get_value(request, GPIO_SENSOR, &ret);
        if (ret < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }

        if (ret == 0) {
            gpiod_line_set_value(request, GPIO_BUZZER, 1);

            gettimeofday(&tv, NULL);
            time_info = localtime(&tv.tv_sec);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%03uZ", time_info);
            printf("Obstacle detected at %s\n", timestamp);

            if ((fd_log = open(log_file, O_WRONLY | O_APPEND | O_CREAT, 0644)) < 0) {
                perror("open");
                goto cleanup;
            }

            if (write(fd_log, timestamp, strlen(timestamp)) < 0) {
                perror("write");
                goto cleanup_close_log;
            }

        close_log:
            close(fd_log);
        }

        usleep(100000);
    }

cleanup_close_chip:
    gpiod_line_request_release(request);
cleanup_close:
    gpiod_chip_close(request->chip);
    return 0;

cleanup:
    goto cleanup_close_chip;
}

