#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <sys/stat.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_LED_PIN 18

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int num_lines,
                                const char *const *lines, unsigned int flags) {
    return gpiod_chip_get_lines_request_array(chip, num_lines, lines, flags);
}

int main() {
    int i2c_file, ret;
    char filename[64] = "distance_log.csv";
    FILE *log_file;
    struct i2c_rdwr_ioctl_data xfer_data;
    struct i2c_msg xfer_msg[2];
    char write_buf[2] = {0};
    char read_buf[8];
    struct timespec ts;
    struct gpiod_line_request *led_request;
    struct gpiod_line *led_line;

    // Initialize GPIO
    struct gpiod_chip *chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    led_request = gpiod_line_request_array(chip, 1, &GPIO_LED_PIN, GPIOD_LINE_REQUEST_DIRECTION_OUT | GPIOD_LINE_REQUEST_ACTIVE_LOW);
    if (!led_request) {
        perror("Failed to request GPIO line");
        gpiod_chip_put(chip);
        return 1;
    }

    led_line = gpiod_line_get_byindex(led_request, 0);
    gpiod_line_set_value(led_line, 1);

    // Open I2C device
    if ((i2c_file = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        gpiod_line_release(led_line);
        gpiod_line_request_free(led_request);
        gpiod_chip_put(chip);
        return 1;
    }

    // Configure I2C transfer
    xfer_msg[0].addr = VL53L1X_ADDR;
    xfer_msg[0].flags = 0;
    xfer_msg[0].len = 2;
    xfer_msg[0].buf = write_buf;

    xfer_msg[1].addr = VL53L1X_ADDR;
    xfer_msg[1].flags = I2C_M_RD;
    xfer_msg[1].len = 8;
    xfer_msg[1].buf = read_buf;

    // Create log file and write header
    log_file = fopen(filename, "w");
    if (log_file) {
        fprintf(log_file, "timestamp,distance_mm\n");
        fclose(log_file);
    }

    signal(SIGINT, graceful_shutdown);
    signal(SIGTERM, graceful_shutdown);

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        write_buf[0] = 0x01;
        write_buf[1] = 0x00;

        ret = i2c_rdwr(i2c_file, &xfer_msg, 2, I2C_TIMEOUT);
        if (ret < 0) {
            perror("Failed to perform I2C read");
            break;
        }

        double distance_mm = (read_buf[0] << 8 | read_buf[1]) / 16.0;
        printf("%lld,%f\n", ts.tv_sec * 1000 + ts.tv_nsec / 1000000, distance_mm);

        if (distance_mm < 300) {
            printf("STOP\n");
        } else if (distance_mm >= 300 && distance_mm < 600) {
            printf("APPROACH\n");
        } else if (distance_mm >= 600 && distance_mm < 1200) {
            printf("SLOW\n");
        } else {
            printf("CLEAR\n");
        }

        usleep(100000); // Sleep for 100ms
    }

    // Cleanup
    close(i2c_file);
    gpiod_line_release(led_line);
    gpiod_line_request_free(led_request);
    gpiod_chip_put(chip);

    return 0;
}

void graceful_shutdown(int signum) {
    printf("Received signal %d, shutting down...\n", signum);

    // Release I2C handle, close log file, and de-initialize sensor driver
    // ...

    exit(0);
}

