void i2c_write_byte_data(uint8_t addr, uint8_t reg, uint8_t value) {
    int retries = 0;
    while (retries < MAX_I2C_RETRIES) {
        if (i2c_smbus_write_byte_data(i2c_file, addr, reg) < 0) {
            if (errno != EAGAIN) {
                perror("i2c_smbus_write_byte_data");
            }
            usleep(I2C_RETRY_DELAY_US);
            retries++;
        } else {
            if (i2c_smbus_write_byte_data(i2c_file, addr, value) < 0) {
                perror("i2c_smbus_write_byte_data");
            }
            break;
        }
    }
}

uint8_t i2c_read_byte_data(uint8_t addr, uint8_t reg) {
    int retries = 0;
    uint8_t data;
    while (retries < MAX_I2C_RETRIES) {
        if ((data = i2c_smbus_read_byte_data(i2c_file, addr)) < 0) {
            if (errno != EAGAIN) {
                perror("i2c_smbus_read_byte_data");
            }
            usleep(I2C_RETRY_DELAY_US);
            retries++;
        } else {
            break;
        }
    }
    return data;
}

void setup_gpio(void) {
    if ((chip = gpiod_chip_open_by_name("gpiochip0")) == NULL) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    if ((line = gpiod_chip_get_line(chip, LED_GPIO)) == NULL) {
        perror("gpiod_chip_get_line");
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_output(line, "led", GPIOD_LINE_ACTIVE_HIGH);
    gpiod_line_set_value(line, 0);
}

void teardown_gpio(void) {
    gpiod_line_release(line);
    gpiod_chip_close(chip);
