I'll provide a basic example using the `libgpiod` library for GPIO management and `i2c-dev` for I2C communication. This example assumes you have the necessary libraries installed on your Raspberry Pi. If not, you can install them using:

```bash
sudo apt-get install libgpiod-dev i2c-dev
```

Here's the C code for the Time-of-Flight sensor (MLX75030) on I2C bus 1:

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define I2C_BUS 1
#define MLX75030_ADDR 0x2A
#define TRIGGER_REG 0x00
#define DISTANCE_REG 0x02
#define DELAY_US 10
#define SAMPLE_INTERVAL_MS 100
#define BUFFER_SIZE 256

gpiod_line_request_linenum_t trigger_line;
int i2c_file;

void handle_error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

int init_gpio(const char *gpio_pin) {
    int ret;
    gpiod_line_request_data_flags_t flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW;

    ret = gpiod_chip_open_byname("gpiochip0");
    if (ret < 0)
        handle_error("Failed to open GPIO chip");

    ret = gpiod_line_request_get(ret, gpio_pin, flags, NULL);
    if (ret < 0)
        handle_error("Failed to request GPIO line");

    return ret;
}

int init_i2c() {
    int ret;
    const char *i2c_bus_path = "/dev/i2c-";
    char path[sizeof(i2c_bus_path) + 3];

    snprintf(path, sizeof(path), "%s%d", i2c_bus_path, I2C_BUS);

    i2c_file = open(path, O_RDWR);
    if (i2c_file < 0)
        handle_error("Failed to open I2C bus");

    if (ioctl(i2c_file, I2C_SLAVE, MLX75030_ADDR) < 0)
        handle_error("Failed to acquire I2C slave address");

    return 0;
}

void cleanup() {
    if (i2c_file >= 0)
        close(i2c_file);
    if (trigger_line.request_fd >= 0)
        gpiod_line_request_free(trigger_line.request_fd);
}

void log_distance(const char *timestamp, uint16_t distance) {
    char log_line[BUFFER_SIZE];
    snprintf(log_line, sizeof(log_line), "%s,%d\n", timestamp, distance);
    write(STDOUT_FILENO, log_line, strlen(log_line));

    FILE *log_file = fopen("distance_log.csv", "a");
    if (log_file) {
        fputs(log_line, log_file);
        fclose(log_file);
    }
}

int main() {
    char gpio_pin[32];
    int ret;

    snprintf(gpio_pin, sizeof(gpio_pin), "gpio%d", 18); // Replace 18 with the GPIO pin connected to the sensor's trigger

    ret = init_gpio(gpio_pin);
    if (ret < 0)
        handle_error("Failed to initialize GPIO");

    ret = init_i2c();
    if (ret < 0)
        handle_error("Failed to initialize I2C");

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        gpiod_line_set_value(trigger_line, 0);
        usleep(DELAY_US * 1000);
        gpiod_line_set_value(trigger_line, 1);
        usleep(DELAY_US * 1000);
        gpiod_line_set_value(trigger_line, 0);

        uint8_t data[2];
        ret = read(i2c_file, data, 2);
        if (ret != 2) {
            if (errno == EAGAIN || errno == ETIMEDOUT) {
                fprintf(stderr, "I2C read/write timeout, retrying...\n");
                continue;
            }
            handle_error("I2C read/write error");
        }

        uint16_t distance = (data[0] << 8) | data[1];
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL)));

        log_distance(timestamp, distance);
        sleep(SAMPLE_INTERVAL_MS / 1000.0);
    }

    return 0;
}
```

This code initializes the GPIO pin connected to the sensor's trigger, opens the I2C bus, and continuously reads distance data from the sensor. It logs the data to a file named `distance_log.csv` and handles errors gracefully, including transient I2C communication errors. The program also releases resources on exit paths, including when receiving SIGINT or SIGTERM signals.

I'll provide a basic example using the `libgpiod` library. This code assumes you have libgpiod installed and the necessary headers. If not, you can install it using the following command:

```bash
sudo apt-get install libgpiod-dev
```

Here's the C code:

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <gpiod.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define DEBOUNCE_MS 50
#define POLL_MS 10
#define LOG_FILE "proximity_log.txt"

static gpiod_line_request_lines(struct gpiod_chip *chip, size_t nlines,
                                const char *const *names, uint32_t flags) {
    struct gpiod_line_request *request;
    int i;

    request = gpiod_chip_get_request(chip, names, nlines, flags);
    if (!request) {
        perror("gpiod_chip_get_request");
        exit(EXIT_FAILURE);
    }

    for (i = 0; i < nlines; i++) {
        if (gpiod_line_request_validate(request, i)) {
            perror("gpiod_line_request_validate");
            exit(EXIT_FAILURE);
        }
    }

    return request;
}

static void gpio_cleanup(struct gpiod_line_request *request) {
    size_t i;

    for (i = 0; i < request->n_lines; i++) {
        gpiod_line_release(request->lines[i]);
    }

    gpiod_line_request_free(request);
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line_request *request;
    struct timespec ts;
    FILE *log_file;
    int sensor_1_line, sensor_2_line;
    uint32_t prev_state[2] = {0, 0};
    int i;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_byname");
        exit(EXIT_FAILURE);
    }

    request = gpio_line_request(chip, SENSOR_1_GPIO, GPIOD_LINE_REQUEST_DIRECTION_IN,
                                GPIOD_LINE_REQUEST_EDGE_RISING | GPIOD_LINE_REQUEST_ACTIVE_LOW);
    if (!request) {
        perror("gpio_line_request");
        exit(EXIT_FAILURE);
    }

    sensor_1_line = request->lines[0];

    request = gpio_line_request(chip, SENSOR_2_GPIO, GPIOD_LINE_REQUEST_DIRECTION_IN,
                                GPIOD_LINE_REQUEST_EDGE_RISING | GPIOD_LINE_REQUEST_ACTIVE_LOW);
    if (!request) {
        perror("gpio_line_request");
        exit(EXIT_FAILURE);
    }

    sensor_2_line = request->lines[0];

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    while (1) {
        nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = POLL_MS * 1000000}, &ts);

        if (gpiod_line_get_value(sensor_1_line) != prev_state[0]) {
            prev_state[0] = gpiod_line_get_value(sensor_1_line);
            nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = DEBOUNCE_MS * 1000000}, &ts);
            if (gpiod_line_get_value(sensor_1_line) != prev_state[0]) {
                fprintf(log_file, "%sT %d SENSOR_1 %s\n", ctime(&ts.tv_sec), (int)ts.tv_nsec / 1000000,
                        prev_state[0] ? "DETECTED" : "CLEARED");
            }
        }

        if (gpiod_line_get_value(sensor_2_line) != prev_state[1]) {
            prev_state[1] = gpiod_line_get_value(sensor_2_line);
            nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = DEBOUNCE_MS * 1000000}, &ts);
            if (gpiod_line_get_value(sensor_2_line) != prev_state[1]) {
                fprintf(log_file, "%sT %d SENSOR_2 %s\n", ctime(&ts.tv_sec), (int)ts.tv_nsec / 1000000,
                        prev_state[1] ? "DETECTED" : "CLEARED");
            }
        }
    }

    fclose(log_file);
    gpio_cleanup(request);
    gpiod_chip_close(chip);

    return 0;
}

void signal_handler(int signum) {
    gpio_cleanup(request);
    gpiod_chip_close(chip);
    exit(EXIT_SUCCESS);
}

int main(void) {
    struct sigaction sa;

    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    return main();
}
```

This code initializes the GPIO lines, opens a log file, and enters an infinite loop to poll the sensors. It debounces the sensor readings and logs state transitions with an ISO 8601 UTC timestamp. The program also handles graceful shutdown on SIGINT or SIGTERM signals by releasing the GPIO resources and closing the log file.

