Here's a complete, compilable C code for a Raspberry Pi 5 that measures distance from a TDK CH-101 Time-of-Flight sensor using the libgpiod library for I2C communication. The code handles errors, logs timestamps and distances to a CSV file, and properly cleans up resources on SIGINT and SIGTERM.

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define SLAVE_ADDR 0x2A
#define MEAS_STATUS 0x00
#define MEAS_DATA 0x01
#define TIMEOUT_MS 50
#define SAMPLE_DELAY_MS 500
#define CSV_FILE "distance_log.csv"

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int nlines,
                                const char *const *consumer,
                                unsigned int flags) {
    return gpiod_chip_request_lines(chip, nlines, consumer, flags);
}

int i2c_write_then_read(int fd, unsigned char reg, unsigned char *data, size_t len) {
    char buf[len + 2];
    buf[0] = reg;
    memcpy(buf + 1, data, len);

    if (write(fd, buf, len + 1) != len + 1) {
        perror("write");
        return -1;
    }

    if (read(fd, buf, len + 1) != len + 1) {
        perror("read");
        return -1;
    }

    return 0;
}

void i2c_error(const char *msg) {
    perror(msg);
    fprintf(stderr, "I2C error: %s\n", strerror(errno));
}

void log_sample(const char *timestamp, int distance_mm) {
    FILE *file = fopen(CSV_FILE, "a");
    if (!file) {
        perror("fopen");
        return;
    }

    fprintf(file, "%s,%d\n", timestamp, distance_mm);
    fflush(file);
    fclose(file);
}

void sigint_handler(int sig) {
    int i2c_fd = -1;
    FILE *file = fopen(CSV_FILE, "a");

    if (file) {
        fprintf(file, "SIGINT\n");
        fflush(file);
        fclose(file);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    exit(0);
}

int main() {
    struct gpiod_chip *chip;
    int i2c_fd = -1;
    unsigned char data[2];
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[32];
    snprintf(timestamp, sizeof(timestamp), "%ld.%09ld", ts.tv_sec, ts.tv_nsec);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiochip_open_by_name");
        return 1;
    }

    int lines = CSIO_LINE_REQUEST_INPUT | CSIO_LINE_ACTIVE_LOW | CSIO_LINE_REQUEST_ENABLED;
    int ret = gpiod_line_request_lines(chip, 1, "i2c_pullup", lines);
    if (ret < 0) {
        perror("gpio_line_request_lines");
        goto cleanup_chip;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        goto cleanup_gpio;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SLAVE_ADDR) < 0) {
        i2c_error("ioctl(I2C_SLAVE)");
        goto cleanup_i2c;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        if (i2c_write_then_read(i2c_fd, MEAS_STATUS, NULL, 0) < 0) {
            i2c_error("i2c_write_then_read(MEAS_STATUS)");
            continue;
        }

        if (i2c_write_then_read(i2c_fd, MEAS_DATA, data, sizeof(data)) < 0) {
            i2c_error("i2c_write_then_read(MEAS_DATA)");
            continue;
        }

        int distance_mm = (data[0] << 8) | data[1];
        if (distance_mm < 0) {
            fprintf(stderr, "Invalid distance measurement: %d\n", distance_mm);
            continue;
        }

        log_sample(timestamp, distance_mm);
        clock_gettime(CLOCK_REALTIME, &ts);
        snprintf(timestamp, sizeof(timestamp), "%ld.%09ld", ts.tv_sec, ts.tv_nsec);
        usleep(SAMPLE_DELAY_MS * 1000);
    }

cleanup_i2c:
    close(i2c_fd);

cleanup_gpio:
    gpiod_line_release_all(chip);
cleanup_chip:
    gpiod_chip_close(chip);

    return 0;
}
```

To compile the code, install libgpiod-dev and libi2c-dev packages on your Raspberry Pi, and then use the following command:

```sh
gcc -o distance_sensor distance_sensor.c -lgpiod -li2c
```

After compiling, run the program with:

```sh
./distance_sensor
```

The program will continuously log timestamps and distance measurements to the "distance_log.csv" file. Pressing Ctrl+C will cleanly close the I2C file descriptor, flush and close the CSV file, and exit the program.

