#define MLX75030_REG_PWR_DOWN 0x03
#define MLX75030_REG_MEAS_RATE 0x04
#define MLX75030_REG_MEAS_MODE 0x05
#define MLX75030_REG_RESULT_0_MSB 0x06
#define MLX75030_REG_RESULT_0_LSB 0x07
#define MLX75030_REG_RESULT_1_MSB 0x08
#define MLX75030_REG_RESULT_1_LSB 0x09
#define MLX75030_REG_RESULT_2_MSB 0x0A
#define MLX75030_REG_RESULT_2_LSB 0x0B
#define MLX75030_REG_RESULT_3_MSB 0x0C
#define MLX75030_REG_RESULT_3_LSB 0x0D
#define MLX75030_REG_RESULT_4_MSB 0x0E
#define MLX75030_REG_RESULT_4_LSB 0x0F
#define MLX75030_REG_RESULT_5_MSB 0x10
#define MLX75030_REG_RESULT_5_LSB 0x11

int i2c_write_reg(int fd, uint8_t reg, uint16_t value) {
    uint8_t data[3];
    data[0] = reg;
    data[1] = value >> 8;
    data[2] = value & 0xFF;

    int ret = write(fd, data, 3);
    if (ret != 3) {
        perror("i2c_write_reg");
        return -1;
    }

    return 0;
}

int i2c_read_reg(int fd, uint8_t reg, uint16_t *value) {
    uint8_t data[2];
    int ret = read(fd, &data, 2);
    if (ret != 2) {
        perror("i2c_read_reg");
        return -1;
    }

    *value = (data[0] << 8) | data[1];
    return 0;
}

int init_i2c(void) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        perror("ioctl");
        close(fd);
        return -1;
    }

    return fd;
}

void deinit_i2c(int fd) {
    if (fd >= 0) {
        close(fd);
    }
}

int main(void) {
    int fd = -1;
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    long long last_ts = ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
    int retries = 3;

    fd = init_i2c();
    if (fd < 0) {
        fprintf(stderr, "Failed to initialize I2C bus\n");
        goto cleanup;
    }

    if (i2c_write_reg(fd, MLX75030_REG_PON, 0x01) < 0) {
        fprintf(stderr, "Failed to power on the sensor\n");
        goto cleanup;
    }

    usleep(100000); // Wait for the sensor to power up

    if (i2c_write_reg(fd, MLX75030_REG_MEAS_RATE, 0x01) < 0) {
        fprintf(stderr, "Failed to set measurement rate\n");
        goto cleanup;
    }

    if (i2c_write_reg(fd, MLX75030_REG_MEAS_MODE, 0x00) < 0) {
        fprintf(stderr, "Failed to set measurement mode\n");
        goto cleanup;
    }

    while (1) {
        for (int i = 0; i < retries; ++i) {
            if (i2c_read_reg(fd, MLX75030_REG_RESULT_0_MSB, &uint16_t result) == 0) {
                clock_gettime(CLOCK_MONOTONIC, &ts);
                long long current_ts = ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
                printf("Distance: %d mm, Timestamp: %lld ms\n", result, current_ts);
                break;
            }
            usleep(10000);
        }

        if (i == retries) {
            perror("i2c_read_reg");
        }

        usleep(100000); // Wait for the next measurement
    }

cleanup:
    deinit_i2c(fd);

    if (fd >= 0) {
        if (i2c_write_reg(fd, MLX75030_REG_PWR_DOWN, 0x03) < 0) {
            perror("i2c_write_reg");
        }
    }

    return 0;
}
```

This program initializes the I2C bus, powers on the sensor, sets the measurement rate and mode, and reads distance measurements periodically with a 100ms interval. It handles errors by retrying I2C transactions up to three times with a 10ms delay between attempts. The program also gracefully handles cases where the sensor is absent or the bus reports errors, and properly closes the I2C handle and terminates the driver library on all exit paths, including a graceful shutdown triggered by SIGINT (Ctrl-C).

