#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

#define VL53L1X_ADDR 0x29
#define GPIO_NUMBER 22

static int i2c_file;
static struct i2c_rdwr_ioctl_data vl53l1x_data[] = {
    { .addr = VL53L1X_ADDR, .len = 2, .buf = (caddr_t)&measurement_config },
    { .addr = VL53L1X_ADDR, .len = 1, .buf = (caddr_t)&num_read },
};

struct measurement_config {
    uint8_t ssp_control;
    uint16_t i2c_master_speed;
    uint8_t device_id;
    uint16_t measurement_timing_budget;
    uint8_t interrupt_configuration;
    uint8_t interrupt_enable_reg;
    uint16_t interrupt_threshold;
    uint8_t interrupt_op_mode;
    uint8_t interrupt_le_timeout_macro_control;
    uint8_t software_reset;
    uint8_t key_source;
    uint8_t key_type;
    uint8_t reserved;
};

int main() {
    int ret;
    struct gpiod_line *gpio;
    struct i2c_rdwr_result *result;
    uint16_t distance;
    struct measurement_config measurement_config = {};

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file < 0) {
        perror("Failed to open I2C device");
        exit(1);
    }

    if (ioctl(i2c_file, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        perror("Failed to acquire bus access");
        close(i2c_file);
        exit(1);
    }

    gpio = gpiod_chip_get_line(0, GPIO_NUMBER);
    if (!gpio) {
        perror("Failed to get GPIO line");
        close(i2c_file);
        exit(1);
    }

    gpiod_line_request_output(gpio, "vl53l1x_buzzer", GPIOD_LINE_ACTIVE_HIGH);
    gpiod_line_set_value(gpio, 0);

    measurement_config.ssp_control = 0x00;
    measurement_config.i2c_master_speed = 100000;
    measurement_config.device_id = 0x00;
    measurement_config.measurement_timing_budget = 40000;
    measurement_config.interrupt_configuration = 0x00;
    measurement_config.interrupt_enable_reg = 0x00;
    measurement_config.interrupt_threshold = 100;
    measurement_config.interrupt_op_mode = 0x00;
    measurement_config.interrupt_le_timeout_macro_control = 0x00;
    measurement_config.software_reset = 0x00;
    measurement_config.key_source = 0x00;
    measurement_config.key_type = 0x03;
    measurement_config.reserved = 0x00;

    ret = ioctl(i2c_file, I2C_RDWR, (unsigned long)&vl53l1x_data);
    if (ret < 0) {
        perror("Failed to write to VL53L1X");
        close(i2c_file);
        gpiod_line_release(gpio);
        exit(1);
    }

    while (1) {
        num_read = 1;
        ret = ioctl(i2c_file, I2C_RDWR, (unsigned long)&vl53l1x_data);
        if (ret < 0) {
            perror("Failed to read from VL53L1X");
            continue;
        }

        if (vl53l1x_data[1].buf[0] < 100) {
            gpiod_line_set_value(gpio, 1);
        } else {
            gpiod_line_set_value(gpio, 0);
        }

        sleep(0.5);
    }

    gpiod_line_release(gpio);
    close(i2c_file);

    return 0;
}

