#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <time.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <sys/mman.h>
#include <gpiod.h>

#define TRIGGER_GPIO 23
#define ECHO_GPIO 24
#define SERVO_GPIO 17
#define TIMEOUT_MS 50
#define MIN_DISTANCE 2
#define MAX_DISTANCE 400
#define SERVO_MIN_ANGLE -90
#define SERVO_MAX_ANGLE 90
#define LOG_FILE "sensor_data.log"
#define I2C_BUS 1

struct gpiod_line_request *trigger, *echo, *servo;
struct i2c_dev *servo_dev;

void servo_write(int angle)
{
    int data = map_angle_to_servo_pulsewidth(angle);
    gpiod_write_raw(servo, data);
}

int map_angle_to_servo_pulsewidth(int angle)
{
    double pulsewidth = (double)(MAX_DISTANCE - MIN_DISTANCE) * (angle - SERVO_MIN_ANGLE) / (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE) + MIN_DISTANCE;
    return (int)(pulsewidth * 1000);
}

void log_distance(double distance)
{
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(log_file, "%s: %.2f cm\n", timestamp, distance);
    fclose(log_file);
}

void handle_signal(int signum)
{
    if (servo)
        gpiod_line_release(servo);
    if (trigger)
        gpiod_line_release(trigger);
    if (echo)
        gpiod_line_release(echo);
    if (servo_dev)
        i2c_close(servo_dev->fd);
    exit(0);
}

int main()
{
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int ret;

    // Initialize GPIO lines
    trigger = gpiod_claim_line(0, TRIGGER_GPIO, "trigger", GPIOD_LINE_REQUEST_DIRECTION_OUT);
    if (!trigger) {
        perror("Failed to claim trigger line");
        exit(1);
    }

    echo = gpiod_claim_line(0, ECHO_GPIO, "echo", GPIOD_LINE_REQUEST_INPUT);
    if (!echo) {
        perror("Failed to claim echo line");
        gpiod_line_release(trigger);
        exit(1);
    }

    servo = gpiod_claim_line(0, SERVO_GPIO, "servo", GPIOD_LINE_REQUEST_DIRECTION_OUT);
    if (!servo) {
        perror("Failed to claim servo line");
        gpiod_line_release(echo);
        gpiod_line_release(trigger);
        exit(1);
    }

    // Initialize I2C servo device
    char servo_addr[] = {0x40 << 1};
    servo_dev = i2c_open(I2C_BUS, servo_addr);
    if (servo_dev == NULL) {
        perror("Failed to open I2C device");
        gpiod_line_release(servo);
        gpiod_line_release(echo);
        gpiod_line_release(trigger);
        exit(1);
    }

    while (1) {
        gpiod_line_set_value(trigger, 1);
        usleep(10);
        gpiod_line_set_value(trigger, 0);

        struct timespec timeout = {.tv_sec = 0, .tv_nsec = TIMEOUT_MS * 1000000};
        if (nanosleep(&timeout, NULL) < 0) {
            perror("Failed to sleep");
            continue;
        }

        if (gpiod_line_get_value(echo) == 0) {
            double start_time = time(NULL);
            while (gpiod_line_get_value(echo) == 0) {
                if (difftime(time(NULL), start_time) > TIMEOUT_MS) {
                    printf("Sensor timeout\n");
                    continue;
                }
                usleep(100000);
            }
            double distance = (time(NULL) - start_time) * 148 / 2;
            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                int angle = map_angle_to_servo_pulsewidth(distance - MIN_DISTANCE);
                servo_write(angle);
                log_distance(distance);
            }
        }

        usleep(200000);
    }

    // Release resources on exit
    gpiod_line_release(servo);
    i2c_close(servo_dev->fd);
    gpiod_line_release(echo);
    gpiod_line_release(trigger);

    return 0;
}

