#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>

#define VL53L1X_I2C_ADDR 0x29
#define GPIO_LINE_ID_BUZZER 23

static int i2c_fd;
static struct i2c_dev *i2c_dev;
static gpio_handle_t *gpio_buzzer;
static struct mq_attr mq_attr;
static int mq_fd;

void i2c_error_handler(const char *msg) {
    perror(msg);
    close(i2c_fd);
    exit(EXIT_FAILURE);
}

void gpio_error_handler(const char *msg) {
    perror(msg);
    gpiod_set_value_cansleep(gpio_buzzer, 0);
    gpiod_close_with_flags(gpio_buzzer, GPIOD_CLOSE_CLEANUP_RESOURCES);
    exit(EXIT_FAILURE);
}

void sigint_handler(int signum) {
    gpiod_set_value_cansleep(gpio_buzzer, 0);
    gpiod_close_with_flags(gpio_buzzer, GPIOD_CLOSE_CLEANUP_RESOURCES);
    mq_close(mq_fd);
    close(i2c_fd);
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, sigint_handler);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        i2c_error_handler("Failed to open I2C bus");
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_I2C_ADDR) < 0) {
        i2c_error_handler("Failed to acquire bus access and/or talk to slave");
    }

    i2c_dev = (struct i2c_dev *) mmap(NULL, sizeof(struct i2c_dev), PROT_READ | PROT_WRITE, MAP_SHARED, i2c_fd, 0);
    if (i2c_dev == MAP_FAILED) {
        i2c_error_handler("Failed to mmap i2c_dev");
    }

    gpio_buzzer = gpiod_get(NULL, "gpiochip0", GPIO_LINE_ID_BUZZER, GPIOD_FLAGS_DIRECT_ACCESS);
    if (IS_ERR(gpio_buzzer)) {
        gpio_error_handler("Failed to get buzzer GPIO");
    }

    gpiod_set_value_cansleep(gpio_buzzer, 0);

    mq_attr.mq_flags = 0;
    mq_attr.mq_maxmsg = 10;
    mq_attr.mq_msgsize = sizeof(int);
    mq_attr.mq_curmsgs = 0;

    mq_fd = mq_open("/distance_queue", O_RDWR | O_CREAT | O_EXCL, S_IRUSR | S_IWUSR, &mq_attr);
    if (mq_fd == -1 && errno != EEXIST) {
        perror("Failed to create message queue");
        gpio_error_handler("Failed to create message queue");
    }

    int distance;
    while (1) {
        if (vl53l1x_get_distance(&distance) < 0) {
            printf("Failed to read distance\n");
            continue;
        }

        if (mq_send(mq_fd, &distance, sizeof(int), 0) != sizeof(int)) {
            perror("Failed to send message to queue");
            continue;
        }

        if (distance < 100) {
            gpiod_set_value_cansleep(gpio_buzzer, 1);
        }

        usleep(50000);
    }

    return 0;
}

