#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/types.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define TRIGGER_GPIO 17
#define ECHO_GPIO 27
#define BUZZER_GPIO 22
#define TIMEOUT_US 50000
#define DISTANCE_MIN 2
#define DISTANCE_MAX 400
#define BUZZER_ON 1
#define BUZZER_OFF 0
#define INT_EDGE_RISING 1
#define INT_EDGE_FALLING 0
#define TICK_PER_US (1000000 / sysconf(_SC_CLK_TCK))

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trigger, *echo, *buzzer;
    int ret;
    unsigned long long start_tick, end_tick, elapsed_tick, distance_cm;
    unsigned int echo_state;

    if (!(chip = gpiod_chip_open_byname("gpiochip0"))) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_GPIO);
    echo = gpiod_chip_get_line(chip, ECHO_GPIO);
    buzzer = gpiod_chip_get_line(chip, BUZZER_GPIO);

    if (!trigger || !echo || !buzzer) {
        perror("Failed to get GPIO lines");
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(trigger, "trigger", GPIOD_LINE_ACTIVE_HIGH);
    if (ret < 0) {
        perror("Failed to request trigger line");
        gpiod_line_release(trigger);
        gpiod_line_release(echo);
        gpiod_line_release(buzzer);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_input(echo, "echo", GPIOD_LINE_ACTIVE_HIGH);
    if (ret < 0) {
        perror("Failed to request echo line");
        gpiod_line_release(trigger);
        gpiod_line_release(echo);
        gpiod_line_release(buzzer);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(buzzer, "buzzer", GPIOD_LINE_ACTIVE_HIGH);
    if (ret < 0) {
        perror("Failed to request buzzer line");
        gpiod_line_release(trigger);
        gpiod_line_release(echo);
        gpiod_line_release(buzzer);
        gpiod_chip_close(chip);
        return 1;
    }

    gpiod_line_set_value(buzzer, BUZZER_OFF);

    while (1) {
        gpiod_line_set_value(trigger, BUZZER_ON);
        usleep(10);
        gpiod_line_set_value(trigger, BUZZER_OFF);

        start_tick = gpiod_get_ns(echo);
        usleep(TIMEOUT_US);
        echo_state = gpiod_line_get_value(echo);

        if (start_tick == 0 || echo_state == 0) {
            printf("Sensor absent or invalid reading\n");
            gpiod_line_release(trigger);
            gpiod_line_release(echo);
            gpiod_line_release(buzzer);
            gpiod_chip_close(chip);
            return 1;
        }

        end_tick = gpiod_get_ns(echo);
        elapsed_tick = end_tick - start_tick;

        if (elapsed_tick > TICK_PER_US * TIMEOUT_US) {
            printf("No echo detected\n");
            gpiod_line_release(trigger);
            gpiod_line_release(echo);
            gpiod_line_release(buzzer);
            gpiod_chip_close(chip);
            return 1;
        }

        distance_cm = (elapsed_tick * 343 / 2) / TICK_PER_US;

        if (distance_cm < DISTANCE_MIN || distance_cm > DISTANCE_MAX) {
            printf("Invalid reading: %llu us, %u cm\n", elapsed_tick, distance_cm);
            gpiod_line_release(trigger);
            gpiod_line_release(echo);
            gpiod_line_release(buzzer);
            gpiod_chip_close(chip);
            return 1;
        }

        printf("Distance: %u cm\n", distance_cm);

        if (distance_cm < 30)
            gpiod_line_set_value(buzzer, BUZZER_ON);
        else
            gpiod_line_set_value(buzzer, BUZZER_OFF);

        usleep(100000);
    }

    gpiod_line_release(trigger);
    gpiod_line_release(echo);
    gpiod_line_release(buzzer);
    gpiod_chip_close(chip);

    return 0;
}

