This code assumes that the HC-SR04 ultrasonic sensor is connected to the Raspberry Pi's GPIO pins as specified in the problem statement. The buzzer is connected to GPIO 22.

code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <time.h>
#include <pthread.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <libgpiod.h>

#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define LOG_FILE "gate_log.txt"
#define MIN_DISTANCE 20
#define I2C_BUS 1
#define BUFFER_SIZE 16

static gpiod_line_request_lines_data_t servo_request;
static gpiod_line_data_t servo_data;
static int i2c_fd;
static uint16_t distance;
static time_t last_event_time;
static pthread_t remote_control_thread;

void i2c_write_byte(uint8_t reg, uint8_t data) {
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write I2C register");
        exit(EXIT_FAILURE);
    }

    if (write(i2c_fd, &data, 1) != 1) {
        perror("Failed to write I2C data");
        exit(EXIT_FAILURE);
    }
}

uint16_t i2c_read_word_data(uint8_t reg) {
    uint16_t data;

    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write I2C register");
        exit(EXIT_FAILURE);
    }

    if (read(i2c_fd, &data, 2) != 2) {
        perror("Failed to read I2C data");
        exit(EXIT_FAILURE);
    }

    data = (data << 8) | (read(i2c_fd, &data, 1));

    return data;
}

void i2c_init() {
    char filename[32];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", I2C_BUS);

    if ((i2c_fd = open(filename, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        perror("Failed to acquire bus access");
        exit(EXIT_FAILURE);
    }
}

void servo_init() {
    gpiod_line_request_configure(&servo_request, GPIO_REQUEST_DIRECTION, "servo");
    gpiod_line_request_configure(&servo_request, GPIO_REQUEST_EDGE_SENSING, "rising");
    gpiod_line_request_enable(&servo_request);

    gpiod_line_get_value(&servo_data, &servo_request);
}

void servo_set_angle(int angle) {
    int pulse_length = 1400 + (angle * 10);
    gpiod_line_set_value(&servo_data, angle > 90);
    usleep(pulse_length);
    gpiod_line_set_value(&servo_data, false);
}

void log_event(const char *event) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        time_t current_time = time(NULL);
        fprintf(log_file, "%s: %s\n", ctime(&current_time), event);
        fclose(log_file);
    }
}

void *remote_control_thread_func(void *arg) {
    while (1) {
        pigpio_sleepms(100);
        if (pigpio_read(PI_INPUT_MODE_S, SERVO_PIN) == PI_INPUT_EDGE_RISING) {
            if (pigpio_read(PI_INPUT_MODE_S, SERVO_PIN) == PI_INPUT_LOGIC_1) {
                pigpio_write(SERVO_PIN, PI_OUTPUT_MODE_B);
                if (pigpio_read(PI_INPUT_MODE_S, SERVO_PIN) == PI_INPUT_LOGIC_0) {
                    pigpio_write(SERVO_PIN, PI_OUTPUT_MODE_A);
                    if (pigpio_read(PI_INPUT_MODE_S, SERVO_PIN) == PI_INPUT_LOGIC_1) {
                        pigpio_write(SERVO_PIN, PI_OUTPUT_MODE_S);
                        if (pigpio_read(PI_INPUT_MODE_S, SERVO_PIN) == PI_INPUT_LOGIC_0) {
                            pigpio_command(PI_COMMAND_SET_MODE, PI_MODE_GPIO, SERVO_PIN);
                            if (pigpio_read(PI_INPUT_MODE_S, SERVO_PIN) == PI_INPUT_LOGIC_0) {
                                if (pigpio_read(PI_INPUT_MODE_S, SERVO_PIN) == PI_INPUT_EDGE_RISING) {
                                    pigpio_command(PI_COMMAND_TARGET, PI_TARGET_SERVO, SERVO_PIN, 90);
                                    pigpio_command(PI_COMMAND_SERVO_ANGLE, PI_TARGET_SERVO, SERVO_PIN, 90);
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    return NULL;
}

void signal_handler(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    if (gpiod_line_request_validate(&servo_request) >= 0) {
        gpiod_line_release(&servo_request);
    }

    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_init();

    // Perform software reset and wait for boot
    i2c_write_byte(0x80, 0x00);
    usleep(20000);

    // Start ranging
    i2c_write_byte(0x80, 0x01);

    pthread_create(&remote_control_thread, NULL, remote_control_thread_func, NULL);

    while (1) {
        usleep(100000);

        distance = i2c_read_word_data(0x02);
        time_t current_time = time(NULL);

        if (distance < MIN_DISTANCE) {
            if (current_time - last_event_time > 1) {
                log_event("Object detected");
                last_event_time = current_time;
                servo_set_angle(0);
            }
        } else if (current_time - last_event_time > 2) {
            log_event("Path clear");
            last_event_time = current_time;
            servo_set_angle(90);
        }
    }

    pthread_join(remote_control_thread, NULL);

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    if (gpiod_line_request_validate(&servo_request) >= 0) {
        gpiod_line_release(&servo_request);
    }

    return EXIT_SUCCESS;
}

