code:
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/time.h>
#include <time.h>
#include <errno.h>
#include <libgpiod.h>

#define TRIG_GPIO 23
#define ECHO_GPIO 24
#define TIMEOUT_US 30000
#define NOISE_US 100
#define WAIT_US 60000
#define LOG_FILE "distance_log.txt"

struct gpiod_line *trig_line, *echo_line;
struct timespec rising_tick, falling_tick;
int trig_value = 0;

void alert_cb(struct gpiod_chip *chip, struct gpiod_line *line, unsigned int value,
              unsigned int events, void *user_data) {
    if (line == echo_line) {
        if (gpiod_get_value_cansleep(echo_line) == 0) {
            falling_tick = gpiod_get_event_time(chip, line);
        } else if (gpiod_get_value_cansleep(echo_line) == 1) {
            rising_tick = gpiod_get_event_time(chip, line);
        }
    }
}

int main(void) {
    int ret;
    struct gpiod_chip *chip;
    struct timespec current_time;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    trig_line = gpiod_get_line_byname(chip, "gpio" TRIG_GPIO);
    if (!trig_line) {
        perror("Failed to get TRIG line");
        gpiod_chip_put(chip);
        return 1;
    }

    echo_line = gpiod_get_line_byname(chip, "gpio" ECHO_GPIO);
