    if (i2c_master_writeRead(i2c_file, (const uint8_t *)&reg, 1, (uint8_t *)&value, 2) < 2) {
        perror("i2c_write_reg");
        exit(EXIT_FAILURE);
    }
}

uint16_t i2c_read_reg(uint8_t reg) {
    uint16_t value;
    if (i2c_master_writeRead(i2c_file, &reg, 1, (uint8_t *)&value, 2) < 2) {
        perror("i2c_read_reg");
        exit(EXIT_FAILURE);
    }
    return value;
}

void soft_reset() {
    i2c_write_reg(0x80, 0x0000);
    usleep(1000 * 1000); // 1ms delay
}

