        gpio_write(MOTOR_FWD_GPIO, 0);
        gpio_write(MOTOR_REV_GPIO, 1);
    } else {
        gpio_write(MOTOR_FWD_GPIO, 0);
        gpio_write(MOTOR_REV_GPIO, 0);
    }
}

