code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/time.h>
#include <errno.h>
#include <gpiod.h>

#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define GPIO_LED_0 GPIO_PIN(17, 0)
#define GPIO_LED_1 GPIO_PIN(18, 0)
#define GPIO_LED_2 GPIO_PIN(27, 0)
#define GPIO_LED_3 GPIO_PIN(22, 0)

static int i2c_file;
static struct gpiod_chip *gpio_chip;
static gpiod_line_request_lines_data_v1 lines_data = { .lines = {
    [0 ... 11] = GPIOD_LINE_REQUEST_INPUT,
    [17] = GPIOD_LINE_REQUEST_OUTPUT,
    [18] = GPIOD_LINE_REQUEST_OUTPUT,
    [22] = GPIOD_LINE_REQUEST_OUTPUT,
    [27] = GPIOD_LINE_REQUEST_OUTPUT,
};

void setup() {
    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_file, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Failed to acquire bus access");
        exit(EXIT_FAILURE);
    }

    gpio_chip = gpiod_chip_open_byname("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_array(gpio_chip, 16, &lines_data, GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW);
    gpiod_line_request_array(gpio_chip, 4, &lines_data + 12, GPIOD_LINE_REQUEST_OUTPUT);

    gpiod_line_set_value(gpio_chip, GPIO_LED_0, 0);
    gpiod_line_set_value(gpio_chip, GPIO_LED_1, 0);
    gpiod_line_set_value(gpio_chip, GPIO_LED_2, 0);
    gpiod_line_set_value(gpio_chip, GPIO_LED_3, 0);

    struct timeval tv;
    gettimeofday(&tv, NULL);
    printf("Initializing...\n");
}

void teardown() {
    gpiod_line_release_all(gpio_chip);
    close(i2c_file);
    gpiod_chip_close(gpio_chip);
    gpiod_chip_put(gpio_chip);

    signal(SIGINT, teardown);
    signal(SIGTERM, teardown);
}

int read_mpr121() {
    char buf[2];
    if (write(i2c_file, 0x00, 1) != 1) {
        perror("Failed to write soft reset command");
        return -1;
    }
    usleep(100000); // Wait for the sensor to reset

    if (write(i2c_file, 0x0A, 1) != 1) {
        perror("Failed to write register read command");
        return -1;
    }
    if (read(i2c_file, buf, 2) != 2) {
        perror("Failed to read data from MPR121");
        return -1;
    }

    return buf[0] | (buf[1] << 8);
}

void log_event(int electrode, struct timeval tv) {
    char timestamp[30];
    snprintf(timestamp, sizeof(timestamp), "%.6ld", tv.tv_sec * 1000 + tv.tv_usec / 1000);
    printf("%s: Electrode %d triggered\n", timestamp, electrode);
}

int main() {
    setup();

    int last_state[12] = {0};
    struct timeval tv;

    while (1) {
        gettimeofday(&tv, NULL);
        int state = read_mpr121();
        if (state < 0) {
            perror("Failed to read MPR121 state");
            continue;
        }

        int i;
        for (i = 0; i < 12; ++i) {
            if ((state >> i) & 1 && !(last_state[i] & 1)) {
                log_event(i, tv);

                int led_pattern = i % 4;
                gpiod_line_set_value(gpio_chip, GPIO_LED_0, led_pattern & 1);
                gpiod_line_set_value(gpio_chip, GPIO_LED_1, (led_pattern >> 1) & 1);
                gpiod_line_set_value(gpio_chip, GPIO_LED_2, (led_pattern >> 2) & 1);
                gpiod_line_set_value(gpio_chip, GPIO_LED_3, (led_pattern >> 3) & 1);
            }
            last_state[i] = (state >> i) & 1;
        }

        usleep(50000); // Polling interval
    }

    teardown();
    return 0;
}

