This program initializes the MPR121, configures it, and continuously checks for proximity events. When a proximity event is detected, it turns on the LED connected to GPIO27 for exactly one second and logs the event with a timestamp to a file named `proximity.log`. The program handles I2C communication errors gracefully and ensures that all resources are cleanly released when it receives a SIGINT or SIGTERM signal.

code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/time.h>
#include <time.h>
#include <errno.h>
#include <libgpiod.h>

#define TRIGGER_GPIO 17
#define ECHO_GPIO 18
#define LOG_FILE "distance_log.txt"
#define TIMEOUT_US 30000
#define MIN_DISTANCE 2
#define MAX_DISTANCE 400
#define SAMPLE_RATE 1000

volatile sig_atomic_t sigint_received = 0;

void sigint_handler(int signum) {
    sigint_received = 1;
}

double microseconds_to_cm(unsigned long microseconds) {
    return microseconds * 0.01 / 343.0;
}

unsigned long pulse_width_us(struct gpiod_line_state *state) {
    struct timespec ts_start, ts_end;
    unsigned long pulse_width_ns;

    clock_gettime(CLOCK_MONOTONIC, &ts_start);
    gpiod_line_set_value_cansleep(state, 1);
    usleep(10);
    gpiod_line_set_value_cansleep(state, 0);

    clock_gettime(CLOCK_MONOTONIC, &ts_end);
    pulse_width_ns = (ts_end.tv_sec - ts_start.tv_sec) * 1000000000 + ts_end.tv_nsec - ts_start.tv_nsec;

    return pulse_width_ns / 1000;
}

int main() {
    int fd, ret;
    struct gpiod_chip *chip;
    struct gpiod_line_request *trigger_req, *echo_req;
    struct gpiod_line_state *trigger_state, *echo_state;
    unsigned long pulse_width;
    double distance;
    struct timespec ts;
    FILE *log_file;

    signal(SIGINT, sigint_handler);

    if ((fd = gpiod_open_byname("gpiochip0")) < 0) {
        perror("gpiod_open_byname");
        exit(EXIT_FAILURE);
    }

    if (!(chip = gpiod_chip_get_by_fd(fd))) {
        perror("gpiod_chip_get_by_fd");
        exit(EXIT_FAILURE);
    }

    if (!(trigger_req = gpiod_line_request_create(chip, TRIGGER_GPIO))) {
        perror("gpiod_line_request_create");
        exit(EXIT_FAILURE);
    }

    if (!(echo_req = gpiod_line_request_create(chip, ECHO_GPIO))) {
        perror("gpiod_line_request_create");
        gpiod_line_request_free(trigger_req);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_enable(trigger_req) < 0 ||
        gpiod_line_request_enable(echo_req) < 0) {
        perror("gpiod_line_request_enable");
        gpiod_line_request_free(echo_req);
        gpiod_line_request_free(trigger_req);
        exit(EXIT_FAILURE);
    }

    if (!(trigger_state = gpiod_line_get_raw_value(trigger_req))) {
        perror("gpiod_line_get_raw_value");
        gpiod_line_request_free(echo_req);
        gpiod_line_request_free(trigger_req);
        exit(EXIT_FAILURE);
    }

    if (!(echo_state = gpiod_line_get_raw_value(echo_req))) {
        perror("gpiod_line_get_raw_value");
        gpiod_line_request_free(echo_req);
        gpiod_line_request_free(trigger_req);
        gpiod_line_put_value(trigger_req, 0);
        gpiod_line_request_free(trigger_req);
        exit(EXIT_FAILURE);
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen");
        gpiod_line_request_free(echo_req);
        gpiod_line_request_free(trigger_req);
        gpiod_line_put_value(trigger_req, 0);
        gpiod_line_request_free(trigger_req);
        exit(EXIT_FAILURE);
    }

    while (!sigint_received) {
        gpiod_line_put_value(trigger_req, 0);
        usleep(5);
        gpiod_line_put_value(trigger_req, 1);
        usleep(10);
        gpiod_line_put_value(trigger_req, 0);

        clock_gettime(CLOCK_MONOTONIC, &ts);
        ret = gpiod_line_wait_for_value_change_cansleep(echo_req, 1, TIMEOUT_US);
        if (ret < 0) {
            perror("gpiod_line_wait_for_value_change_cansleep");
            continue;
        }

        echo_state = gpiod_line_get_raw_value(echo_req);
        if (!echo_state) {
            perror("gpiod_line_get_raw_value");
            continue;
        }

        pulse_width = pulse_width_us(echo_state);
        distance = microseconds_to_cm(pulse_width);

        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(stderr, "Error: Distance out of range [%f cm]\n", distance);
            continue;
        }

        fprintf(log_file, "%s %f cm\n", ctime(&ts.tv_sec), distance);
        fflush(log_file);

        sleep(SAMPLE_RATE);
    }

    fclose(log_file);
    gpiod_line_request_free(echo_req);
    gpiod_line_request_free(trigger_req);
    gpiod_line_put_value(trigger_req, 0);
    gpiod_line_request_free(trigger_req);
    gpiod_chip_close(chip);
    gpiod_close(fd);

    return EXIT_SUCCESS;
}

