```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define TRIG_GPIO 17
#define ECHO_GPIO 18
#define DIVIDER_R1 1000
#define DIVIDER_R2 2000
#define SAMPLE_RATE 1000
#define MIN_PULSE_WIDTH_US 58
#define MAX_PULSE_WIDTH_US 25000
#define LOG_FILE "distance_log.txt"

static gpiod_line_request_lines_data_v1 lines_data = {
    .requests = {
        [TRIG_GPIO] = { .direction = GPIOD_LINE_REQUEST_DIRECTION_OUT, },
        [ECHO_GPIO] = { .direction = GPIOD_LINE_REQUEST_DIRECTION_IN, .debounce = 10, },
    },
};

static gpiod_line_data_v1 trig_data = { .value = 0 };
static gpiod_line_data_v1 echo_data = { .value = 0 };
static uint32_t last_echo_edge = 0;
static uint32_t pulse_start = 0;
static uint32_t pulse_end = 0;
static uint32_t pulse_duration_us = 0;
static FILE *log_file = NULL;

static void gpio_isr(struct gpiod_chip *chip, struct gpiod_line *line, unsigned int event) {
    if (event & GPIOD_LINE_EVENT_EDGE_FALLING) {
        pulse_start = gpiod_get_value_cansleep(chip, line);
        last_echo_edge = gpiod_get_event_time_ns(chip, line);
    }
}

static void gpio_isr_cleanup(struct gpiod_chip *chip, struct gpiod_line *line) {
    if (pulse_start && pulse_end) {
        pulse_duration_us = (pulse_end - pulse_start) / 1000;
        if (pulse_duration_us >= MIN_PULSE_WIDTH_US && pulse_duration_us <= MAX_PULSE_WIDTH_US) {
            double distance_m = pulse_duration_us / 58.2;
            time_t now = time(NULL);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(log_file, "%s,%lu\n", timestamp, distance_m);
        }
        pulse_start = 0;
        pulse_end = 0;
    }
}

int main() {
    struct gpiod_chip *chip;
    int ret;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    ret = gpiod_line_request_lines_v1(chip, &lines_data, 1);
    if (ret < 0) {
        perror("Failed to request GPIO lines");
        goto cleanup_chip;
    }

    ret = gpiod_line_get_value_cansleep(chip, GPIO_SPEC_GET(chip, TRIG_GPIO), &trig_data);
    if (ret < 0) {
        perror("Failed to get initial TRIG state");
        goto cleanup_lines;
    }

    log_file = fopen(LOG_FILE, "w+");
    if (!log_file) {
        perror("Failed to open log file");
        goto cleanup_lines;
    }

    gpiod_line_set_debounce(chip, GPIO_SPEC_GET(chip, ECHO_GPIO), 10);
    gpiod_line_set_event_callback(chip, GPIO_SPEC_GET(chip, ECHO_GPIO), GPIOD_LINE_EVENT_BOTH_EDGES, gpio_isr);
    gpiod_line_set_event_callback_data(chip, GPIO_SPEC_GET(chip, ECHO_GPIO), gpio_isr_cleanup);

    while (1) {
        trig_data.value = 1;
        gpiod_line_set_value(chip, GPIO_SPEC_GET(chip, TRIG_GPIO), trig_data);
        usleep(10000);
        trig_data.value = 0;
        gpiod_line_set_value(chip, GPIO_SPEC_GET(chip, TRIG_GPIO), trig_data);
        usleep(990000 - 10000);

        echo_data = gpiod_line_get_value_cansleep(chip, GPIO_SPEC_GET(chip, ECHO_GPIO), &last_echo_edge);
        if (echo_data.value) {
            pulse_end = gpiod_get_event_time_ns(chip, GPIO_SPEC_GET(chip, ECHO_GPIO));
        }
    }

cleanup_lines:
    gpiod_line_release_request_lines(chip, &lines_data, 1);
cleanup_chip:
    gpiod_chip_close(chip);

    if (log_file) {
        fclose(log_file);
    }

    return 0;
}
