    int file;
    if ((file = open("/dev/i2c-1", O_RDWR)) < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %s", strerror(errno));
        return -1;
    }
    return file;
}

void close_i2c_device() {
    close(i2c_file);
}

int write_i2c_reg(int file, unsigned char reg, unsigned char value) {
    char data[2];
    data[0] = reg;
    data[1] = value;

    if (write(file, data, 2) != 2) {
        syslog(LOG_ERR, "Failed to write to I2C register: %s", strerror(errno));
        return -1;
    }
    return 0;
}

int read_i2c_reg(int file, unsigned char reg, unsigned char *value) {
    char data[1];
    data[0] = reg;

    if (write(file, data, 1) != 1) {
        syslog(LOG_ERR, "Failed to write to I2C register: %s", strerror(errno));
        return -1;
    }

    if (read(file, data, 2) != 2) {
        syslog(LOG_ERR, "Failed to read from I2C register: %s", strerror(errno));
        return -1;
    }

    *value = data[1];
    return 0;
}

int init_sensor() {
    int ret;
    gpiod_line_request_flags_t flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW | GPIOD_LINE_REQUEST_ENABLED_HIGH;
    gpiod_line_state_t state;

    interface = gpiod_open_name_to_label("gpiochip0", "gpio27");
    if (!interface) {
        syslog(LOG_ERR, "Failed to open GPIO interface: %s", gpiod_strerror(errno));
        return -1;
    }

    ret = gpiod_claim_line(interface, GPIO_NUMBER, flags, &err);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to claim GPIO line: %s", gpiod_strerror(errno));
        return -1;
    }

    gpiod_get_line_value_cansleep(interface, GPIO_NUMBER, &state);
    if (state == GPIOD_LINE_STATE_LOW) {
        syslog(LOG_ERR, "GPIO line is already low at startup");
        return -1;
    }

    gpiod_set_value_cansleep(interface, GPIO_NUMBER, 0);
    usleep(100000); // Delay for 100ms to ensure the sensor is disabled before setting the GPIO high
    gpiod_set_value_cansleep(interface, GPIO_NUMBER, 1);

    return 0;
}

void log_distance(double distance, int status) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_string[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", timeinfo);

    syslog(status == 0 ? LOG_INFO : LOG_ERR, "%s: Distance: %.2f mm, Status: %s", time_string, distance, status == 0 ? "Success" : "Failure");
}

int main() {
    int i2c_file, ret;
    unsigned char data[2];
    double distance;

    openlog("vl53l1x_example", LOG_PID | LOG_CONS, LOG_USER);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    if (init_sensor() < 0) {
        syslog(LOG_ERR, "Failed to initialize sensor");
        exit(1);
    }

    i2c_file = open_i2c_device();
    if (i2c_file < 0) {
        syslog(LOG_ERR, "Failed to open I2C device");
        exit(1);
    }

    ret = write_i2c_reg(i2c_file, 0x80, 0x01);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to write to I2C register 0x80");
        close_i2c_device();
        exit(1);
    }

    while (1) {
        ret = read_i2c_reg(i2c_file, 0x94, data);
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to read from I2C register 0x94");
            continue;
        }

        distance = (double)((data[0] << 8) | data[1]) * 25 / 16;
        log_distance(distance, 0);
        usleep(100000); // Delay for 100ms before the next reading
    }

    close_i2c_device();
    gpiod_unclaim_line(GPIO_NUMBER);
    gpiod_release_interface(interface);
    closelog();

    return 0;
}

