#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <linux/types.h>
#include <linux/gpio/consumer.h>
#include <libgpiod.h>

#define TRIGGER_GPIO 23
#define ECHO_GPIO 24
#define SERVO_GPIO 18
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SAMPLE_COUNT 5
#define TIMEOUT_US 30000
#define TICK_PER_US (1000000 / sysconf(_SC_CLK_TCK))
#define NEW_PULSE_FLAG 0
#define PULSE_WIDTH_SHIFT 16
#define PULSE_WIDTH_MASK 0xFF0000

volatile sig_atomic_t sigint_received = 0;

struct gpiod_line *trigger, *echo, *servo;
struct timespec last_echo_time;
unsigned long long pulse_width = 0;
unsigned int new_pulse = 0;
unsigned int samples[SAMPLE_COUNT];
unsigned int sample_index = 0;
unsigned int filtered_distance = 0;
unsigned int servo_angle = 90;

void echo_cb(struct gpiod_line *line, int event, void *data) {
    struct timespec now;
    unsigned long long pulse_start, pulse_end;

    if (event != GPIOD_LINE_EVENT_EDGE_FALLING)
        return;

    clock_gettime(CLOCK_MONOTONIC, &now);
    pulse_start = now.tv_sec * TICK_PER_US + now.tv_nsec / 1000;

    while (gpiod_line_get_value_async(echo) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &now);
        if ((now.tv_sec * TICK_PER_US + now.tv_nsec / 1000) - pulse_start > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo signal\n");
            return;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &now);
    pulse_end = now.tv_sec * TICK_PER_US + now.tv_nsec / 1000;
    pulse_width = pulse_end - pulse_start;
    new_pulse = 1;
}

void servo_set_angle(unsigned int angle) {
    struct gpiod_range *range;
    struct gpiod_data_array data_array;

    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Invalid servo angle: %d\n", angle);
        return;
    }

    range = gpiod_chip_get_range(servo->chip, "gpiochip0", SERVO_GPIO);
    if (!range) {
        perror("Failed to get servo range");
        return;
    }

