    const char *i2c_bus = "/dev/i2c-1";
    if ((i2c_file = open(i2c_bus, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_file, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }

    return 0;
}

int init_gpio() {
    int ret;
    gpiod_line_request_line(gpiochip_get_byname("gpiochip0"), LED_GPIO, &led_request_data, &led_request_data.consumer_data);
    ret = gpiod_line_get_value_cansleep(led_request_data.consumer_data);
    if (ret < 0) {
        perror("Failed to get initial LED state");
    }
    gpiod_line_set_value(led_request_data.consumer_data, !ret);
    return 0;
}

int read_distance() {
    char buf[2];
    if (write(i2c_file, 0x00, 1) != 1) {
        perror("Failed to write to sensor");
        return -1;
    }
    if (read(i2c_file, buf, 2) != 2) {
        perror("Failed to read from sensor");
        return -1;
    }

    uint16_t distance = (buf[0] << 8) | buf[1];
    return (float)distance * 25.4 / 1000; // Convert from raw data to millimeters
}

void sigint_handler(int signum) {
    close(i2c_file);
    gpiod_line_release_line(led_request_data.consumer_data);
    gpiod_line_release_request(led_request_data.consumer_data);
    exit(0);
