        return 1;
    }

    float buffer[BUFFER_SIZE];
    int index = 0;
    float last_distance;

    while (1) {
        float distance = read_distance();
        if (distance < 200) {
            if (last_distance > 200) {
                gpiod_line_set_value(led_request_data.consumer_data, 1);
            }
            last_distance = distance;
