#include <gpiod.h>
#include <pthread.h>
#include <signal.h>

#define TRIGGER_GPIO 23
#define ECHO_GPIO 24
#define PWM_GPIO 18
#define SAMPLE_RATE 10000
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 200.0
#define MIN_FREQUENCY 200.0
#define MAX_FREQUENCY 2000.0
#define LOG_SCALE 1.0
#define TIMEOUT_US 200000

gpiod_line_request_linestate_vlinestate_cb_t echo_cb;
gpiod_line_request_data_cb_t pwm_cb;

struct gpiod_chip *chip;
struct gpiod_line *trigger, *echo, *pwm;
pthread_t pwm_thread;

double frequency = MIN_FREQUENCY;

void echo_cb_func(struct gpiod_line *line, int event, void *user_data) {
    if (event == GPIOD_LINE_EVENT_EDGE_FALLING) {
        gpiod_line_get_value(echo);
        pthread_mutex_lock(&pwm_mutex);
        frequency = map_distance_to_frequency(gpiod_line_get_value(echo));
        pthread_mutex_unlock(&pwm_mutex);
    }
}

void pwm_cb_func(struct gpiod_line *line, int event, void *user_data) {
    if (event == GPIOD_LINE_EVENT_LEVEL_CHANGE) {
        gpiod_line_set_value(line, gpiod_line_get_value(line) ^ 1);
    }
}

double map_distance_to_frequency(int value) {
    double time_us = (value * TIMEOUT_US) / 58;
    double distance = MIN_DISTANCE + (MAX_DISTANCE - MIN_DISTANCE) * pow(10, -(time_us / 580));
    return MIN_FREQUENCY + (MAX_FREQUENCY - MIN_FREQUENCY) * log(distance / MIN_DISTANCE) * LOG_SCALE;
}

void pwm_thread_func(void *arg) {
    struct timespec period, remain;
    int duty_cycle = 50;
    double frequency = *((double *)arg);
    double period_s = 1.0 / frequency;
    double duty_us = period_s * frequency * duty_cycle / 1000;

    period.tv_sec = (time_t)period_s;
    period.tv_nsec = (long)(1e9 * (period_s - period.tv_sec));

    while (1) {
        nanosleep(&period, &remain);
        gpiod_line_set_value(pwm, 1);
        usleep(remain.tv_sec * 1e6 + remain.tv_nsec / 1e3);
        gpiod_line_set_value(pwm, 0);
    }
}

void sigint_handler(int signum) {
    pthread_mutex_lock(&pwm_mutex);
    frequency = -1.0;
    pthread_mutex_unlock(&pwm_mutex);
    pthread_join(pwm_thread, NULL);
    gpiod_line_release(trigger);
    gpiod_line_release(echo);
    gpiod_line_release(pwm);
    gpiod_chip_release(chip);
    exit(0);
}

int main() {
    pthread_mutex_t pwm_mutex = PTHREAD_MUTEX_INITIALIZER;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_GPIO);
    if (!trigger) {
        perror("Failed to get trigger line");
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_GPIO);
    if (!echo) {
        perror("Failed to get echo line");
        goto cleanup;
    }

    gpiod_line_request_flags_set(echo, GPIOD_LINE_REQUEST_DIRECTION_IN);
    gpiod_line_request_callback(echo, GPIOD_LINE_EVENT_EDGE_FALLING, &echo_cb, NULL);

    pwm = gpiod_chip_get_line(chip, PWM_GPIO);
    if (!pwm) {
        perror("Failed to get PWM line");
        goto cleanup;
    }

    gpiod_line_request_flags_set(pwm, GPIOD_LINE_REQUEST_DIRECTION_OUT);
    gpiod_line_request_callback(pwm, GPIOD_LINE_EVENT_LEVEL_CHANGE, &pwm_cb, NULL);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    pthread_create(&pwm_thread, NULL, pwm_thread_func, &frequency);

    gpiod_line_set_value(trigger, 1);
    usleep(10000);
    gpiod_line_set_value(trigger, 0);

    while (1) {
        usleep(SAMPLE_RATE * 1000);
    }

cleanup:
    gpiod_line_release(trigger);
    gpiod_line_release(echo);
    gpiod_line_release(pwm);
    gpiod_chip_release(chip);
    return 1;
}
