I'll provide a simple example using the `libgpiod` library for GPIO handling. This code assumes you have libgpiod installed on your Raspberry Pi. If not, you can install it using the following command:

```bash
sudo apt-get install libgpiod-dev
```

Here's the C code:

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/types.h>
#include <gpiod.h>
#include <time.h>

#define TRIGGER_GPIO 17
#define ECHO_GPIO 18
#define TIMEOUT_US 50000
#define MEASUREMENT_INTERVAL_MS 500
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define MIN_SAFE_DISTANCE_CM 10.0

static gpiod_line_request_lines_data_v1 lines_data = {
    .lines = (struct gpiod_line_request_data *) malloc(2 * sizeof(struct gpiod_line_request_data)),
};

static int init_gpio(void) {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line_request *request;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return -1;
    }

    lines_data.lines[TRIGGER_GPIO].consumer = "ultrasonic_sensor";
    lines_data.lines[TRIGGER_GPIO].flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW;
    lines_data.lines[ECHO_GPIO].consumer = "ultrasonic_sensor";
    lines_data.lines[ECHO_GPIO].flags = GPIOD_LINE_REQUEST_INPUT;

    request = gpiod_chip_request_lines(chip, 2, &lines_data, NULL);
    if (!request) {
        perror("Failed to request lines");
        gpiod_chip_close(chip);
        return -1;
    }

    lines_data.lines[TRIGGER_GPIO].request = request->lines[TRIGGER_GPIO];
    lines_data.lines[ECHO_GPIO].request = request->lines[ECHO_GPIO];

    return 0;
}

static void cleanup_gpio(void) {
    if (lines_data.lines[TRIGGER_GPIO].request)
        gpiod_line_release(lines_data.lines[TRIGGER_GPIO].request);
    if (lines_data.lines[ECHO_GPIO].request)
        gpiod_line_release(lines_data.lines[ECHO_GPIO].request);
    if (lines_data.lines)
        free(lines_data.lines);
    gpiod_chip_close(lines_data.chip);
}

static void sigint_handler(int signum) {
    printf("\nExiting...\n");
    cleanup_gpio();
    exit(0);
}

static uint32_t get_time_us(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec * 1000000 + ts.tv_nsec / 1000;
}

static double get_distance_cm(uint32_t pulse_duration_us) {
    double velocity_cm_us = 148.0;
    return pulse_duration_us / 2.0 / velocity_cm_us;
}

int main(void) {
    int ret;
    uint32_t trigger_time, echo_time, pulse_duration;
    double distance;
    struct sigaction sa;

    if (init_gpio() < 0)
        return 1;

    signal(SIGINT, sigint_handler);

    while (1) {
        lines_data.lines[TRIGGER_GPIO].value = 0;
        usleep(10);
        lines_data.lines[TRIGGER_GPIO].value = 1;
        usleep(10);
        lines_data.lines[TRIGGER_GPIO].value = 0;

        trigger_time = get_time_us();
        echo_time = trigger_time;

        while ((echo_time - trigger_time) < TIMEOUT_US && lines_data.lines[ECHO_GPIO].value == 0)
            echo_time = get_time_us();

        if (echo_time == trigger_time) {
            printf("Timeout\n");
            pulse_duration = -1;
        } else {
            pulse_duration = echo_time - trigger_time;
        }

        if (pulse_duration >= 0) {
            distance = get_distance_cm(pulse_duration);
            if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
                printf("Invalid reading\n");
            } else if (distance < MIN_SAFE_DISTANCE_CM) {
                printf("Too close!\n");
            } else {
                printf("Distance: %.2f cm\n", distance);
            }
        }

        usleep(MEASUREMENT_INTERVAL_MS * 1000);
    }

    cleanup_gpio();
    return 0;
}
```

This code initializes the GPIO pins, sets up a SIGINT handler, and continuously measures the distance using the HC-SR04 ultrasonic sensor. It handles a timeout from the echo measurement by treating it as a -1 result and prints the distance if it's within the valid range (2-400 cm). If the distance is below 10 cm, it also prints "Too close!". The program exits cleanly when receiving a SIGINT signal.

I'll provide a basic example using the `libgpiod` library for GPIO management and the `spidev` library for SPI communication. Note that you'll need to install the required libraries using the following commands:

```bash
