Here's the C code for the ultrasonic sensor interface:

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <errno.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define CS_GPIO 8
#define MODE 0
#define MAX_BUFF_SIZE 256
#define SPI_BUS 0
#define SPI_DEVICE 0
#define MIN_DISTANCE 200
#define MAX_DISTANCE 5000
#define DELAY_MS 100
#define LOG_FILE "distance_log.csv"

int spi_fd;
gpiod_line_request_linestate_t cs_state;
gpiod_line_request_data_t cs_request;
gpiod_line_data_t cs_data;

void sigint_handler(int signum) {
    gpiod_line_release(cs_request);
    close(spi_fd);
    remove(LOG_FILE);
    exit(0);
}

int init_gpio() {
    gpiod_line_request_config config = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW;
    int ret = gpiod_chip_open_byname("gpiochip0");
    if (ret < 0) {
        perror("Failed to open gpiochip0");
        return -1;
    }

    ret = gpiod_line_request_get_byindex(ret, CS_GPIO, &cs_request, &config);
    if (ret < 0) {
        perror("Failed to request line");
        gpiod_chip_close(ret);
        return -1;
    }

    ret = gpiod_line_get_value_cansleep(cs_request, &cs_state);
    if (ret < 0) {
        perror("Failed to get initial line state");
        gpiod_line_release(cs_request);
        gpiod_chip_close(ret);
        return -1;
    }

    ret = gpiod_line_set_value(cs_request, !cs_state);
    if (ret < 0) {
        perror("Failed to set line state");
        gpiod_line_release(cs_request);
        gpiod_chip_close(ret);
        return -1;
    }

    return 0;
}

int init_spi() {
    char spi_dev_path[32];
    snprintf(spi_dev_path, sizeof(spi_dev_path), "/dev/spidev%d.%d", SPI_BUS, SPI_DEVICE);

    spi_fd = open(spi_dev_path, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer transfer[1] = {
        {
            .tx_buf = (unsigned char*) &cs_state,
            .rx_buf = (unsigned char*) &cs_state,
            .len = sizeof(cs_state),
            .delay_usecs = 0,
            .speed_hz = 1000000,
            .bits_per_word = 8,
        }
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 1) {
        perror("Failed to configure SPI");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int read_sensor() {
    unsigned char buff[MAX_BUFF_SIZE];
    int ret = read(spi_fd, buff, sizeof(buff));
    if (ret < 0) {
        perror("Failed to read from SPI");
        return -1;
    }

    int distance = (buff[0] << 8) | buff[1];
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Invalid distance value: %d\n", distance);
        return -1;
    }

    return distance;
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    if (init_gpio() < 0) {
        return -1;
    }

    if (init_spi() < 0) {
        return -1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        goto cleanup;
    }

    while (1) {
        int distance = read_sensor();
        if (distance < 0) {
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm_now = localtime(&now);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

        fprintf(log_file, "%s,%d\n", timestamp, distance);
        fflush(log_file);
        usleep(DELAY_MS * 1000);
    }

cleanup:
    fclose(log_file);
    gpiod_line_release(cs_request);
    close(spi_fd);
    return 0;
}
```

This code initializes the GPIO and SPI, sets up a SIGINT and SIGTERM handler, opens the log file in append mode, and continuously reads the sensor data with a 100ms delay. If there's an error during the read operation or the distance value is out of range, it logs an error message to stderr and continues running. When the program receives a SIGINT or SIGTERM signal, it closes the SPI handle, releases all resources, and flushes and closes the CSV log file.

