code:
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <sys/time.h>
#include <errno.h>
#include <libgpiod.h>

#define SI1120_ADDR 0x29
#define ALS_REG 0x82
#define PRY_REG 0x83
#define PART_ID_REG 0x00
#define PART_ID 0x1410
#define I2C_RETRY_MAX 3
#define I2C_RETRY_DELAY 10
#define LOG_FILE "si1120_log.txt"

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int lines,
                                const char *label, int flags)
{
    return gpiod_chip_get_lines_request_array(chip, lines, label, flags);
}

int main(void)
{
    int i2c_fd, ret;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct timeval tv;
    struct tm *tm;
    char log_buf[64];
    uint16_t als, pry;
    uint16_t part_id;
    struct gpiod_chip *chip;
    struct gpiod_line_request *reset_req;

    // Initialize GPIO
    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    reset_req = gpiod_line_request_get(chip, 16);
    if (!reset_req) {
        perror("Failed to get GPIO line 16");
        gpiod_chip_put(chip);
        return 1;
    }

    gpiod_line_request_direction_output(reset_req, GPIOD_LINE_ACTIVE_LOW);
    gpiod_line_request_enable(reset_req, 1);

    usleep(100000); // Delay for 100ms

    gpiod_line_request_set_value(reset_req, 0);
    usleep(10000); // Delay for 10ms
    gpiod_line_request_set_value(reset_req, 1);
    usleep(10000); // Delay for 10ms

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        gpiod_line_request_put(reset_req);
        gpiod_chip_put(chip);
        return 1;
    }

    // Initialize I2C data structure
    i2c_data.wr_buf = (char *)&part_id;
    i2c_data.wr_len = 1;
    i2c_data.rd_buf = (char *)&part_id;
    i2c_data.rd_len = 1;

    // Check part ID
    for (int i = 0; i < I2C_RETRY_MAX; ++i) {
        ret = ioctl(i2c_fd, I2C_RDWR, &i2c_data);
        if (ret >= 0)
            break;

        usleep(I2C_RETRY_DELAY * 1000);
    }

    if (ret < 0) {
        perror("Failed to read Si1120 part ID");
        close(i2c_fd);
        gpiod_line_request_put(reset_req);
        gpiod_chip_put(chip);
        return 1;
    }

    if (part_id != PART_ID) {
        fprintf(stderr, "Wrong Si1120 part ID: 0x%04x\n", part_id);
        close(i2c_fd);
        gpiod_line_request_put(reset_req);
        gpiod_chip_put(chip);
        return 1;
    }

    // Main loop
    while (1) {
        gettimeofday(&tv, NULL);
        tm = localtime(&tv.tv_sec);
        strftime(log_buf, sizeof(log_buf), "%Y-%m-%d %H:%M:%S", tm);

        i2c_data.wr_buf = (char *)&ALS_REG;
        i2c_data.wr_len = 1;
        i2c_data.rd_buf = (char *)&als;
        i2c_data.rd_len = 2;

        for (int i = 0; i < I2C_RETRY_MAX; ++i) {
            ret = ioctl(i2c_fd, I2C_RDWR, &i2c_data);
            if (ret >= 0)
                break;

            usleep(I2C_RETRY_DELAY * 1000);
        }

        if (ret < 0) {
            perror("Failed to read ALS data");
            continue;
        }

        i2c_data.wr_buf = (char *)&PRY_REG;
        i2c_data.wr_len = 1;
        i2c_data.rd_buf = (char *)&pry;
        i2c_data.rd_len = 2;

        for (int i = 0; i < I2C_RETRY_MAX; ++i) {
            ret = ioctl(i2c_fd, I2C_RDWR, &i2c_data);
            if (ret >= 0)
                break;

            usleep(I2C_RETRY_DELAY * 1000);
        }

        if (ret < 0) {
            perror("Failed to read PRY data");
            continue;
        }

        als = (als << 8) | (pry & 0xFF);
        pry = (pry >> 8) & 0xFF;

        fprintf(stderr, "%s ALS: 0x%04x PRY: 0x%02x\n", log_buf, als, pry);
        FILE *log_file = fopen(LOG_FILE, "a");
        if (log_file) {
            fprintf(log_file, "%s ALS: 0x%04x PRY: 0x%02x\n", log_buf, als, pry);
            fclose(log_file);
        } else {
            perror("Failed to open log file");
        }

        usleep(500000); // Delay for 500ms
    }

    // Cleanup
    close(i2c_fd);
    gpiod_line_request_put(reset_req);
    gpiod_chip_put(chip);

    return 0;
}

