code:
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <sys/time.h>
#include <signal.h>
#include <libgpiod.h>

#define SI1182_ADDR 0x29
#define AMBIENT_LIGHT_REG 0x03
#define PROXIMITY_REG 0x05
#define MEAS_RATE_REG 0x01
#define MEAS_RATE_VAL 0x0F

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int lines,
                                const char *label, int flags) {
    return gpiod_chip_get_line_request_list(chip, lines, label, flags);
}

int main() {
    int i2c_fd, ret;
    uint16_t proximity;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct timespec ts;
    FILE *log_file;
    char log_line[128];
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    // Initialize GPIO
    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    line = gpiod_chip_get_line(chip, 0);
    if (!line) {
        perror("Failed to get line 0");
        gpiod_chip_put(chip);
        return 1;
    }

    ret = gpiod_line_request_line(line, GPIOD_LINE_REQUEST_DIRECTION_IN,
                                  "proximity_led");
    if (ret < 0) {
        perror("Failed to request line direction");
        gpiod_line_put(line);
        gpiod_chip_put(chip);
        return 1;
    }

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open i2c-1");
        gpiod_line_release(line);
        gpiod_chip_put(chip);
        return 1;
    }

    // Initialize sensor
    i2c_data.wr_buf = &MEAS_RATE_VAL;
    i2c_data.wr_len = 1;
    i2c_data.rd_buf = NULL;
    i2c_data.rd_len = 0;

    ret = ioctl(i2c_fd, I2C_RDWR, &i2c_data);
    if (ret < 0) {
        perror("Failed to set measurement rate");
        close(i2c_fd);
        gpiod_line_release(line);
        gpiod_chip_put(chip);
        return 1;
    }

    // Read part ID
    i2c_data.wr_buf = NULL;
    i2c_data.wr_len = 0;
    i2c_data.rd_buf = (char *)malloc(2);
    i2c_data.rd_len = 2;

    ret = ioctl(i2c_fd, I2C_RDWR, &i2c_data);
    if (ret < 0 || i2c_data.rd_len != 2) {
        perror("Failed to read part ID");
        free(i2c_data.rd_buf);
        close(i2c_fd);
        gpiod_line_release(line);
        gpiod_chip_put(chip);
        return 1;
    }

    if (i2c_data.rd_buf[0] != 0x1B || i2c_data.rd_buf[1] != 0x11) {
        fprintf(stderr, "Wrong part ID: 0x%02X 0x%02X\n",
                i2c_data.rd_buf[0], i2c_data.rd_buf[1]);
        free(i2c_data.rd_buf);
        close(i2c_fd);
        gpiod_line_release(line);
        gpiod_chip_put(chip);
        return 1;
    }

    free(i2c_data.rd_buf);

    // Open log file
    log_file = fopen("biometric_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpiod_line_release(line);
        gpiod_chip_put(chip);
        return 1;
    }

    // Signal handlers
    signal(SIGINT, [](int sig) {
        fprintf(stderr, "Received SIGINT, exiting...\n");
        fclose(log_file);
        close(i2c_fd);
        gpiod_line_release(line);
        gpiod_chip_put(chip);
        exit(0);
    });

    signal(SIGTERM, [](int sig) {
        fprintf(stderr, "Received SIGTERM, exiting...\n");
        fclose(log_file);
        close(i2c_fd);
        gpiod_line_release(line);
        gpiod_chip_put(chip);
        exit(0);
    });

    // Main loop
    while (1) {
        i2c_data.wr_buf = &AMBIENT_LIGHT_REG;
        i2c_data.wr_len = 1;
        i2c_data.rd_buf = (char *)malloc(4);
        i2c_data.rd_len = 4;

        ret = ioctl(i2c_fd, I2C_RDWR, &i2c_data);
        if (ret < 0) {
            perror("Failed to read ambient light");
            free(i2c_data.rd_buf);
            continue;
        }

