    struct timespec ts;
    char log_file[] = "proximity_log.txt";
    FILE *log_fp;
    struct gpiod_chip *chip;
    struct gpiod_line_request_data gpio_req_data = {0};

    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[32];
    snprintf(timestamp, sizeof(timestamp), "%ld-%02d-%02d %02d:%02d:%02d",
             ts.tv_sec, ts.tv_nsec / 1B, (ts.tv_nsec % 1B) * 1000000000,
             ts.tv_sec % 60, ts.tv_nsec / 100000000, (ts.tv_nsec % 100000000) / 1000000);

    if ((i2c_file = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_file, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("Failed to acquire bus access");
        close(i2c_file);
        return 1;
    }

    if ((chip = gpiod_chip_open_byname("gpiochip0")) == NULL) {
        perror("Failed to open GPIO chip");
        close(i2c_file);
        return 1;
    }

    if (gpiod_line_request_callback(chip, 1, "log_gpio", &gpio_req_data,
