        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        close(i2c_file);
        return 1;
    }

    log_fp = fopen(log_file, "w");
    if (log_fp == NULL) {
        perror("Failed to open log file");
        gpiod_line_release_callback(chip, 1);
        gpiod_chip_close(chip);
        close(i2c_file);
        return 1;
    }

    while (1) {
        ret = i2c_smbus_read_word_data(i2c_file, PS1_DATA0);
        if (ret < 0) {
            perror("Failed to read PS1_DATA0");
            if (errno != EAGAIN) {
                snprintf(timestamp, sizeof(timestamp), "%ld-%02d-%02d %02d:%02d:%02d: Failed to read PS1_DATA0");
                fprintf(log_fp, "%s\n", timestamp);
                if (retries > 2) {
                    break;
                }
                usleep(100000);
                continue;
            }
        }

        ret = i2c_smbus_read_word_data(i2c_file, PS1_DATA1);
        if (ret < 0) {
            perror("Failed to read PS1_DATA1");
            if (errno != EAGAIN) {
                snprintf(timestamp, sizeof(timestamp), "%ld-%02d-%02d %02d:%02d:%02d: Failed to read PS1_DATA1");
                fprintf(log_fp, "%s\n", timestamp);
                if (retries > 2) {
                    break;
                }
                usleep(100000);
                continue;
            }
        }

        proximity_value = (uint16_t)(ret << 8 | i2c_smbus_read_word_data(i2c_file, PS1_DATA0));

        ret = i2c_smbus_write_word_data(i2c_file, PS1_CONFIG, 0x0000);
        if (ret < 0) {
            perror("Failed to write to PS1_CONFIG");
            snprintf(timestamp, sizeof(timestamp), "%ld-%02d-%02d %02d:%02d:%02d: Failed to write to PS1_CONFIG");
            fprintf(log_fp, "%s\n", timestamp);
            if (retries > 2) {
                break;
            }
            usleep(100000);
            continue;
        }

        fprintf(log_fp, "%s; %u\n", timestamp, proximity_value);
        usleep(1000000); // Sleep for 1 second between readings
    }

    fclose(log_fp);
    gpiod_line_release_callback(chip, 1);
    gpiod_chip_close(chip);
    close(i2c_file);

    signal(SIGINT, [](int signum) {
        printf("Received SIGINT, exiting gracefully...\n");
        gpiod_line_release_callback(chip, 1);
        gpiod_chip_close(chip);
        close(i2c_file);
        exit(0);
    });

    signal(SIGTERM, [](int signum) {
        printf("Received SIGTERM, exiting gracefully...\n");
        gpiod_line_release_callback(chip, 1);
        gpiod_chip_close(chip);
        close(i2c_file);
        exit(0);
    });

    return 0;
}

