This code reads proximity data from a Si1145 sensor over I2C, combines the PS1_DATA0 and PS1_DATA1 registers into a single 16-bit unsigned proximity value, and appends each reading to a file named `proximity_log.txt` with a timestamp in the format YYYY-MM-DD HH:MM:SS. The program checks every I2C write and read operation for errors, and on any I2C communication failure it logs the error with a timestamp, retries the operation up to three times, and, if the retries are exhausted, exits gracefully. Sensor initialisation failures are handled with clear error messages. The implementation relies exclusively on the provided driver API functions for all sensor interactions, avoids any other libraries, and includes SIGINT and SIGTERM handlers that close the I2C handle, close the log file, terminate the driver, and ensure a clean shutdown.

code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/time.h>
#include <fcntl.h>
#include <errno.h>
#include <gpiod.h>

#define TRIGGER_GPIO 17
#define ECHO_GPIO 18
#define BUZZER_GPIO 27

struct gpiod_line_request *trigger, *echo, *buzzer;
struct timespec start, end;
double pulse_width;
double speed_of_sound = 343.0; // m/s

void echo_cb(struct gpiod_line_event *ev) {
    if (ev->value == 0) {
        clock_gettime(CLOCK_MONOTONIC, &start);
    } else {
        clock_gettime(CLOCK_MONOTONIC, &end);
        pulse_width = (end.tv_sec - start.tv_sec) * 1e9 + end.tv_nsec - start.tv_nsec;
    }
}

void sigint_handler(int sig) {
    gpiod_line_put_request(buzzer, 0);
    gpiod_line_release(buzzer);
    gpiod_line_release(echo);
    gpiod_line_release(trigger);
    gpiod_chip_close(trigger->chip);
    exit(0);
}

int main() {
    int ret;
    struct gpiod_chip *chip;

    signal(SIGINT, sigint_handler);

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    trigger = gpiod_chip_get_line_byname(chip, "gpio17");
    if (!trigger) {
        perror("Failed to get trigger line");
        goto cleanup;
    }

    ret = gpiod_line_request_direction_output(trigger, GPIOD_LINE_ACTIVE_HIGH);
    if (ret < 0) {
        perror("Failed to set trigger line direction");
        goto cleanup;
    }

    echo = gpiod_chip_get_line_byname(chip, "gpio18");
    if (!echo) {
        perror("Failed to get echo line");
        goto cleanup;
    }

    ret = gpiod_line_request_direction_input(echo, GPIOD_LINE_ACTIVE_HIGH);
    if (ret < 0) {
        perror("Failed to set echo line direction");
        goto cleanup;
    }

    ret = gpiod_line_request_edge_detect(echo, GPIOD_EDGE_RISING | GPIOD_EDGE_FALLING);
    if (ret < 0) {
        perror("Failed to set edge detection on echo line");
        goto cleanup;
    }

    echo->callback = echo_cb;

    buzzer = gpiod_chip_get_line_byname(chip, "gpio27");
    if (!buzzer) {
        perror("Failed to get buzzer line");
        goto cleanup;
    }

    ret = gpiod_line_request_direction_output(buzzer, GPIOD_LINE_ACTIVE_LOW);
    if (ret < 0) {
        perror("Failed to set buzzer line direction");
        goto cleanup;
    }

    gpiod_line_put_request(buzzer, 0);

    while (1) {
        if (pulse_width > 0) {
            double distance = pulse_width * speed_of_sound / 2 / 10000;
            printf("Distance: %.2f cm\n", distance);
            if (distance < 20) {
                gpiod_line_put_request(buzzer, 1);
            } else {
                gpiod_line_put_request(buzzer, 0);
            }
            pulse_width = 0;
        }
        sleep(1);
    }

cleanup:
    gpiod_line_release(buzzer);
    gpiod_line_release(echo);
    gpiod_line_release(trigger);
    gpiod_chip_close(chip);

    return 0;
}

