            printf("Distance: %.2f cm\n", distance);
            if (distance < 20) {
                gpiod_line_put_request(buzzer, 1);
            } else {
                gpiod_line_put_request(buzzer, 0);
            }
            pulse_width = 0;
        }
        sleep(1);
    }

