First, make sure you have the required libraries installed:

```sh
sudo apt-get install libgpiod-dev i2c-dev
```

Here's the C code:

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/time.h>
#include <gpiod.h>

#define VL53L1X_I2C_ADDR 0x29
#define SERVO_GPIO 18
#define MIN_DISTANCE 200
#define MAX_DISTANCE 250
#define PWM_OPEN_DUTY_CLOSE 1000
#define PWM_CLOSE_DUTY_OPEN 2000
#define PWM_PERIOD_NS 2000000
#define LOG_FILE "gate_log.txt"

int init_i2c(int *file) {
    const char *dev_name = "/dev/i2c-1";
    if ((*file = open(dev_name, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(*file, I2C_SLAVE, VL53L1X_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(*file);
        return -1;
    }

    return 0;
}

int read_model_id(int file) {
    uint8_t model_id;
    if (i2c_smbus_read_byte_data(file, 0x00) != 0xAE) {
        perror("Invalid VL53L1X model ID");
        return -1;
    }

    if (i2c_smbus_read_byte_data(file, 0x01) != 0x62) {
        perror("Invalid VL53L1X revision ID");
        return -1;
    }

    return 0;
}

int set_timing_budget(int file) {
    uint8_t timing_budget[] = {0x01, 0x4D, 0x07, 0x05};
    if (i2c_master_send(file, timing_budget, sizeof(timing_budget)) != sizeof(timing_budget)) {
        perror("Failed to set timing budget");
        return -1;
    }

    return 0;
}

int start_ranging(int file) {
    uint8_t measurement_mode[] = {0x01, 0x00};
    if (i2c_master_send(file, measurement_mode, sizeof(measurement_mode)) != sizeof(measurement_mode)) {
        perror("Failed to start ranging");
        return -1;
    }

    return 0;
}

int read_distance(int file, uint16_t *distance) {
    uint16_t raw_distance;
    if (i2c_smbus_read_word_data(file, 0x0B) != (uint16_t)~0) {
        perror("Failed to read distance");
        return -1;
    }

    raw_distance = (raw_distance & 0x0FFF) >> 2;
    *distance = raw_distance * 16.0;

    return 0;
}

int init_gpio(void) {
    struct gpiod_line_request request = {
        .consumer = "gate_control",
        .flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_HIGH,
        .line = SERVO_GPIO
    };

    int ret = gpiod_chip_open_byname("gpiochip0");
    if (ret < 0) {
        perror("Failed to open GPIO chip");
        return ret;
    }

    ret = gpiod_line_request_dup(ret, &request);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(ret);
        return ret;
    }

    return ret;
}

int init_pwm(int gpio_fd, uint32_t period_ns, uint32_t duty_cycle_open, uint32_t duty_cycle_close) {
    struct gpiod_pwm_config pwm_config = {
        .period_ns = period_ns,
        .duty_cycle_ns = duty_cycle_open,
        .polarity = GPIOD_PWM_POLARITY_ACTIVE_HIGH,
        .soft_start_ns = 0,
        .soft_stop_ns = 0
    };

    int ret = gpiod_line_request_pwm(gpio_fd, &pwm_config);
    if (ret < 0) {
        perror("Failed to set up PWM");
        gpiod_line_release(gpio_fd, SERVO_GPIO);
        gpiod_chip_close(gpio_fd);
        return ret;
    }

    ret = gpiod_line_set_value(gpio_fd, SERVO_GPIO, 1);
    if (ret < 0) {
        perror("Failed to set PWM high");
        gpiod_line_release_pwm(gpio_fd, SERVO_GPIO);
        gpiod_line_release(gpio_fd, SERVO_GPIO);
        gpiod_chip_close(gpio_fd);
        return ret;
    }

    return 0;
}

void log_event(const char *event, struct timeval tv) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file) {
        fprintf(file, "%.6f: %s\n", tv.tv_sec + tv.tv_usec / 1e6, event);
        fclose(file);
    } else {
        perror("Failed to open log file");
    }
}

void signal_handler(int sig) {
    gpiod_line_release_pwm(gpiod_fd, SERVO_GPIO);
    gpiod_line_release(gpiod_fd, SERVO_GPIO);
    gpiod_chip_close(gpiod_fd);
    close(i2c_fd);
    fclose(log_file);
    exit(0);
}

int main(void) {
    int i2c_fd = -1, gpiod_fd = -1, ret;
    uint16_t distance;
    struct timeval tv;
    struct sigaction sa = {0};

    if (ret = init_i2c(&i2c_fd)) {
        return ret;
    }

    if (ret = read_model_id(i2c_fd)) {
        goto cleanup;
    }

    if (ret = set_timing_budget(i2c_fd)) {
        goto cleanup;
    }

    if (ret = start_ranging(i2c_fd)) {
        goto cleanup;
    }

    if (ret = init_gpio()) {
        goto cleanup;
    }

    if (ret = init_pwm(gpiod_fd, PWM_PERIOD_NS, PWM_OPEN_DUTY_CLOSE, PWM_CLOSE_DUTY_OPEN)) {
        goto cleanup;
    }

    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set up signal handler");
        goto cleanup;
    }

    while (1) {
        gettimeofday(&tv, NULL);

        if (read_distance(i2c_fd, &distance) < 0) {
            perror("Failed to read distance");
            continue;
        }

        if (distance > MAX_DISTANCE) {
            gpiod_line_set_value(gpiod_fd, SERVO_GPIO, 0);
            usleep(1000 * 1000);
            gpiod_line_set_value(gpiod_fd, SERVO_GPIO, 1);
            log_event("open", tv);
        } else if (distance < MIN_DISTANCE) {
            gpiod_line_set_value(gpiod_fd, SERVO_GPIO, 0);
            usleep(2000 * 1000);
            gpiod_line_set_value(gpiod_fd, SERVO_GPIO, 1);
            log_event("close", tv);
        }
    }

cleanup:
    if (gpiod_fd >= 0) gpiod_line_release(gpiod_fd, SERVO_GPIO);
    if (i2c_fd >= 0) close(i2c_fd);
    if (gpiod_fd >= 0) gpiod_chip_close(gpiod_fd);
    if (log_file) fclose(log_file);
    return ret;
}
```

This code initializes the I2C bus, reads the VL53L1X model ID, sets the timing budget, starts ranging, initializes the GPIO line for the servo, sets up a signal handler for SIGINT, and repeatedly reads the distance from the sensor. Based on the measured distance, it sets the servo pulse width and logs the gate event.

