    gpiod_line_set_value(trigger, 1);
    usleep(10);
    gpiod_line_set_value(trigger, 0);

    int timeout = TIMEOUT;
    while (gpiod_line_get_value(echo) == 0 && timeout > 0) {
        timeout -= 1;
        usleep(1000);
    }

    timeout = TIMEOUT;
    while (gpiod_line_get_value(echo) == 1 && timeout > 0) {
        timeout -= 1;
        usleep(1000);
    }

    if (timeout == 0) {
        return -1.0;
    }

    usleep(70); // Wait for the echo pulse to stabilize

    timeout = TIMEOUT;
    while (gpiod_line_get_value(echo) == 1 && timeout > 0) {
        timeout -= 1;
        usleep(1000);
    }

    uint32_t start = gpiod_get_value_ns(echo);

    timeout = TIMEOUT;
    while (gpiod_line_get_value(echo) == 0 && timeout > 0) {
        timeout -= 1;
        usleep(1000);
    }

    uint32_t end = gpiod_get_value_ns(echo);

    if (end <= start) {
        return -1.0;
    }

    double time_us = (end - start) / 1000.0;
    double distance_cm = (time_us * 343 / 2);

    if (distance_cm < MIN_DISTANCE || distance_cm > MAX_DISTANCE) {
        return -1.0;
    }

    return distance_cm;
}

void sigint_handler(int signum) {
    servo_set_angle(0);
    gpiod_line_release(trigger);
    gpiod_line_release(echo);
    close(spidev->fd);
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);

    int ret;

    // Initialize GPIO pins
    trigger = gpiod_chip_get_line(gpiod_chip_get_by_name("gpiochip0"), GPIO_TRIGGER);
    if (!trigger) {
        fprintf(stderr, "Failed to get trigger line\n");
        return 1;
    }

    ret = gpiod_line_request_active(trigger, GPIOD_LINE_REQUEST_DIRECTION_OUT | GPIOD_LINE_REQUEST_ACTIVE_LOW);
    if (ret < 0) {
        fprintf(stderr, "Failed to request trigger line\n");
        goto cleanup;
    }

    echo = gpiod_chip_get_line(gpiod_chip_get_by_name("gpiochip0"), GPIO_ECHO);
    if (!echo) {
        fprintf(stderr, "Failed to get echo line\n");
        goto cleanup;
    }

    ret = gpiod_line_request_active(echo, GPIOD_LINE_REQUEST_DIRECTION_IN | GPIOD_LINE_REQUEST_INPUT_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Failed to request echo line\n");
        goto cleanup;
    }

    // Initialize SPI device for servo control
    const char *spidev_path = "/dev/spidev0.0";
    spidev = spi_open(spidev_path, 0);
    if (!spidev) {
        fprintf(stderr, "Failed to open SPI device %s\n", spidev_path);
        goto cleanup;
    }

    // Set chip select line
    spi_set_slave_num(spidev, 0);

    // Set mode, clock speed, and bits per word
    ret = ioctl(spidev->fd, SPI_IOC_WR_MODE, &SPI_MODE_0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        goto cleanup;
    }

    ret = ioctl(spidev->fd, SPI_IOC_WR_MAX_SPEED_HZ, &8000000);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI speed\n");
        goto cleanup;
    }

    ret = ioctl(spidev->fd, SPI_IOC_WR_BITS_PER_WORD, &8);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI bits per word\n");
        goto cleanup;
    }

    // Set servo to 0°
    servo_set_angle(0);

    while (1) {
        double distance = ultrasonic_measure();
        if (distance >= 0) {
            double angle = (distance - MIN_DISTANCE) * ((double)(SERVO_MAX - SERVO_MIN) / (MAX_DISTANCE - MIN_DISTANCE)) + SERVO_MIN;
            servo_set_angle(angle);
            printf("Distance: %.2f cm, Angle: %.2f degrees\n", distance, angle);
        }
        usleep(DELAY);
    }

cleanup:
    if (trigger) {
        gpiod_line_release(trigger);
    }

    if (echo) {
        gpiod_line_release(echo);
    }

    if (spidev) {
        close(spidev->fd);
    }

    return 0;
}
```

