#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/time.h>
#include <gpiod.h>

#define SI7005_ADDR 0x40
#define CONFIG_REG 0xE5
#define MEAS_REG 0xE3

static int i2c_file;
static struct timespec wait_time = {0, 10 * 1000 * 1000};

int init_i2c() {
    const char *i2c_bus = "/dev/i2c-1";
    if ((i2c_file = open(i2c_bus, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_file, I2C_SLAVE, SI7005_ADDR) < 0) {
        perror("Failed to acquire I2C address");
        close(i2c_file);
        return -1;
    }

    return 0;
}

uint16_t read_sensor() {
    if (write(i2c_file, &CONFIG_REG, 1) != 1) {
        perror("Failed to write CONFIG register");
        close(i2c_file);
        return 0;
    }
    nanosleep(&wait_time, NULL);

    uint8_t data[2];
    if (write(i2c_file, &MEAS_REG, 1) != 1) {
        perror("Failed to write MEAS_REG register");
        close(i2c_file);
        return 0;
    }
    nanosleep(&wait_time, NULL);

    if (read(i2c_file, data, 2) != 2) {
        perror("Failed to read data from sensor");
        close(i2c_file);
        return 0;
    }

    uint16_t humidity = (data[0] << 8) | data[1];
    return humidity;
}

void cleanup() {
    if (i2c_file >= 0) {
        close(i2c_file);
    }
}

void signal_handler(int sig) {
    printf("Received SIGINT, cleaning up and exiting...\n");
    cleanup();
    exit(0);
}

int main() {
    signal(SIGINT, signal_handler);

    if (init_i2c() < 0) {
        return 1;
    }

    while (1) {
        uint16_t humidity = read_sensor();
        if (humidity > 0) {
            printf("Humidity: %u\n", humidity);
        }
        sleep(2);
    }

    cleanup();
    return 0;
}

