#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define MPU6050_ADDR 0x68
#define ACK_BIT 0x01
#define NUM_AXES 3
#define DATA_LENGTH 14

int main() {
    int i2c_fd, ret;
    char read_buf[DATA_LENGTH];
    struct i2c_rdwr_ioctl_data i2c_msg[2];
    struct gpiod_line_request *line_req;
    struct gpiod_chip *chip;
    struct gpiod_line_state *line_state;

    // Initialize I2C bus
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    // Initialize GPIO line for reset
    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(1);
    }

    line_req = gpiod_chip_get_line_request_byname(chip, "gpio_0");
    if (!line_req) {
        perror("Failed to get GPIO line request");
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(1);
    }

    ret = gpiod_line_request_direction_output(line_req, GPIOD_LINE_ACTIVE_LOW);
    if (ret < 0) {
        perror("Failed to set GPIO line direction");
        gpiod_chip_release_line_request(line_req);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(1);
    }

    // Reset MPU-6050
    gpiod_line_set_value(line_req, 1);
    usleep(100000);
    gpiod_line_set_value(line_req, 0);
    usleep(100000);

    // Check if MPU-6050 is present
    i2c_msg[0].addr = MPU6050_ADDR << 1 | I2C_DIR_READ;
    i2c_msg[0].flags = 0;
    i2c_msg[0].len = 1;
    i2c_msg[0].buf = &read_buf[0];
    i2c_msg[1].addr = MPU6050_ADDR << 1 | I2C_DIR_READ;
    i2c_msg[1].flags = I2C_M_NOSTART;
    i2c_msg[1].len = 1;
    i2c_msg[1].buf = &read_buf[1];

    ret = ioctl(i2c_fd, I2C_RDWR, i2c_msg);
    if (ret < 0) {
        perror("Failed to read WHO_AM_I register");
        gpiod_line_set_value(line_req, 1);
        gpiod_chip_release_line_request(line_req);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(1);
    }

    if (read_buf[0] != 0x68) {
        printf("MPU-6050 not found\n");
        gpiod_line_set_value(line_req, 1);
        gpiod_chip_release_line_request(line_req);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(1);
    }

    // Main loop
    while (1) {
        // Read data from MPU-6050
        i2c_msg[0].addr = MPU6050_ADDR << 1 | I2C_DIR_READ;
        i2c_msg[0].flags = 0;
        i2c_msg[0].len = DATA_LENGTH;
        i2c_msg[0].buf = read_buf;

        i2c_msg[1].addr = MPU6050_ADDR << 1 | I2C_DIR_READ;
        i2c_msg[1].flags = I2C_M_NOSTART;
        i2c_msg[1].len = DATA_LENGTH;
        i2c_msg[1].buf = read_buf + 2;

        ret = ioctl(i2c_fd, I2C_RDWR, i2c_msg);
        if (ret < 0) {
            perror("Failed to read data from MPU-6050");
            continue;
        }

        // Parse data
        int16_t acc_x = ((read_buf[2] << 8) | read_buf[1]);
        int16_t acc_y = ((read_buf[4] << 8) | read_buf[3]);
        int16_t acc_z = ((read_buf[6] << 8) | read_buf[5]);
        int16_t temp = ((read_buf[8] << 8) | read_buf[7]);
        int16_t gyro_x = ((read_buf[10] << 8) | read_buf[9]);
        int16_t gyro_y = ((read_buf[12] << 8) | read_buf[11]);
        int16_t gyro_z = ((read_buf[14] << 8) | read_buf[13]);

        printf("Accelerometer: (%d, %d, %d)\n", acc_x, acc_y, acc_z);
        printf("Temperature: %d\n", temp / 340 + 36.53);
        printf("Gyroscope: (%d, %d, %d)\n", gyro_x, gyro_y, gyro_z);

        usleep(100000);
    }

    // Cleanup
    gpiod_line_set_value(line_req, 1);
    gpiod_chip_release_line_request(line_req);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return 0;
}

