To catch SIGINT or SIGTERM, you can use a signal handler or set a loop that checks for these signals periodically. However, since the main loop already runs indefinitely, the program will exit when you send a SIGINT or SIGTERM.

I'll provide a basic example using the `libgpiod` library for GPIO management and `i2c-dev` for I2C communication. Note that you'll need to install the required libraries:

```sh
sudo apt-get install libgpiod-dev i2c-dev
```

Here's the C code:

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <time.h>
#include <stdint.h>
#include <string.h>

#define SHT40_ADDR 0x44
#define I2C_BUS 1

static uint8_t crc8_table[256];

static void init_crc8(void) {
    int i, j;
    for (i = 0; i < 256; i++) {
        uint8_t crc = i;
        for (j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x07;
            else
                crc <<= 1;
        }
        crc8_table[i] = crc;
    }
}

static uint8_t crc8(uint8_t data, uint8_t crc) {
    int i;
    for (i = 0; i < 8; i++) {
        if (data & 0x80)
            crc = crc ^ crc8_table[crc ^ data];
        data <<= 1;
    }
    return crc;
}

static int read_sht40(int i2c_fd, uint8_t *buf, size_t len) {
    int ret;
    if ((ret = write(i2c_fd, &SHT40_ADDR, 1)) != 1) {
        perror("I2C write error");
        return -1;
    }

    if ((ret = read(i2c_fd, buf, len)) != len) {
        perror("I2C read error");
        return -1;
    }

    return ret;
}

static int write_sht40(int i2c_fd, const uint8_t *buf, size_t len) {
    int ret;
    if ((ret = write(i2c_fd, buf, len)) != len) {
        perror("I2C write error");
        return -1;
    }

    return ret;
}

static void log_temperature_and_humidity(float temp, float humidity) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char time_str[32];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm);

    printf("%s: Temperature: %.2f°C, Humidity: %.2f%%\n", time_str, temp, humidity);
}

static void i2c_error_handler(int signum) {
    close(i2c_fd);
    exit(EXIT_FAILURE);
}

int main(void) {
    int i2c_fd;
    uint8_t buf[7];
    float temp, humidity;
    int ret;

    init_crc8();

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        perror("Failed to acquire I2C slave address");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, i2c_error_handler);
    signal(SIGTERM, i2c_error_handler);

    while (1) {
        ret = write_sht40(i2c_fd, (const uint8_t[]) {0x24, 0x03, 0x00, 0x00, 0x00, 0x00, 0x00}, 7);
        usleep(10000);

        ret = read_sht40(i2c_fd, buf, 6);
        if (ret != 6) {
            perror("I2C read error");
            continue;
        }

        temp = (buf[0] << 8 | buf[1]) / 16.0;
        humidity = (buf[3] << 8 | buf[4]) / 100.0;

        if (crc8(buf[1], 0) != buf[2] || crc8(buf[3], 0) != buf[5]) {
            fprintf(stderr, "CRC error\n");
            continue;
        }

        log_temperature_and_humidity(temp, humidity);
        sleep(5);
    }

    close(i2c_fd);
    return 0;
}
