#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/stat.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define SENSOR_I2C_ADDR 0x40 // Sensirion STS30-DIS I2C address
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG "error_log.txt"
#define SAMPLE_INTERVAL 5 // Sample interval in seconds

gpiod_line_request_linenum_t temp_led_request;
int i2c_file;

void log_error(const char *message) {
    FILE *error_log = fopen(ERROR_LOG, "a");
    if (error_log) {
        fprintf(error_log, "%s\n", message);
        fclose(error_log);
    }
}

int init_i2c() {
    const char *i2c_bus = "/dev/i2c-1"; // I2C bus 1
    if ((i2c_file = open(i2c_bus, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        log_error("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_file, I2C_SLAVE, SENSOR_I2C_ADDR) < 0) {
        perror("Failed to acquire I2C slave address");
        log_error("Failed to acquire I2C slave address");
        close(i2c_file);
        return -1;
    }

    return 0;
}

void cleanup() {
    if (temp_led_request) {
        gpiod_line_release_request(temp_led_request);
        temp_led_request = GPIOD_LINE_REQUEST_INVALID;
    }

    if (i2c_file >= 0) {
        close(i2c_file);
    }
}

void signal_handler(int sig) {
    printf("\nReceived signal %d, cleaning up and exiting...\n", sig);
    cleanup();
    exit(0);
}

int main() {
    struct timespec next_sample;
    int ret;

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to set signal handler");
        log_error("Failed to set signal handler");
        return -1;
    }

    if (init_i2c() < 0) {
        return 1;
    }

    // Initialize GPIO for temperature LED (assuming GPIO 18)
    const char *gpio_base = "/dev/gpiochip0";
    temp_led_request = gpiod_chip_request_line(gpio_base, 18, "temp_led", GPIOD_LINE_REQUEST_DIRECTION_OUT, NULL);
    if (temp_led_request == GPIOD_LINE_REQUEST_INVALID) {
        perror("Failed to request GPIO line");
        log_error("Failed to request GPIO line");
        cleanup();
        return 1;
    }

    gpiod_line_set_value(temp_led_request, 1); // Turn on temperature LED

    clock_gettime(CLOCK_REALTIME, &next_sample);
    next_sample.tv_sec += SAMPLE_INTERVAL;

    while (1) {
        clock_nanosleep(CLOCK_REALTIME, TIMER_ABSTIME, &next_sample, NULL);

        int temp_raw;
        ssize_t read_size = read(i2c_file, &temp_raw, sizeof(temp_raw));
        if (read_size != sizeof(temp_raw)) {
            perror("Failed to read temperature data");
            log_error("Failed to read temperature data");
            continue;
        }

        double temp_celsius = (temp_raw * 3.3) / 4096.0 - 0.5;
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        printf("%s: Temperature: %.2f°C\n", timestamp, temp_celsius);

        FILE *log_file = fopen(LOG_FILE, "a");
        if (log_file) {
            fprintf(log_file, "%s: Temperature: %.2f°C\n", timestamp, temp_celsius);
            fclose(log_file);
        }

        next_sample.tv_sec += SAMPLE_INTERVAL;
    }

    return 0;
}

