This code initializes the I2C bus, requests the Sensirion STS30-DIS sensor's I2C address, and reads temperature data every 5 seconds. It also logs errors to a separate file and handles termination signals by cleaning up resources and exiting gracefully.

code:
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <time.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48

#define PRESSURE_REG 0x00
#define TEMPERATURE_REG 0x02
#define CONFIG_REG 0x01
#define COMMAND_REG 0x03

#define CRC8_POLYNOMIAL 0x07
#define CRC8_INIT 0x00

struct i2c_rdwr_ioctl_data {
    struct i2c_msg messages[];
};

int crc8(uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; ++i) {
        crc ^= data[i];
        for (int j = 8; j > 0; --j) {
            crc = (crc & 0x80) ? (crc << 1) ^ CRC8_POLYNOMIAL : crc << 1;
        }
    }
    return crc;
}

int read_data(int i2c_fd, uint8_t reg) {
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg msg = {
        .addr = I2C_ADDR,
        .flags = 0,
        .len = 1,
        .buf = &reg,
    };
    struct i2c_msg read_msg = {
        .addr = I2C_ADDR,
        .flags = I2C_M_RD,
        .len = 9,
        .buf = malloc(9),
    };

    i2c_data.messages = &msg;
    i2c_data.messages += 1;
    i2c_data.messages[1] = read_msg;

    if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) < 0) {
        perror("Failed to read data from sensor");
        free(read_msg.buf);
        return -1;
    }

    if (crc8(read_msg.buf, 8) != read_msg.buf[8]) {
        fprintf(stderr, "Invalid CRC\n");
        free(read_msg.buf);
        return -1;
    }

    free(read_msg.buf);
    return 0;
}

void write_config(int i2c_fd) {
    if (write(i2c_fd, &CONFIG_REG, 1) != 1) {
        perror("Failed to write configuration");
    }
}

void write_command(int i2c_fd) {
    if (write(i2c_fd, &COMMAND_REG, 1) != 1) {
        perror("Failed to write command");
    }
}

void log_data(const char *filename, uint16_t pressure, uint16_t temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    FILE *file = fopen(filename, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(file, "%s,%u,%u\n", timestamp, pressure, temperature);
    fclose(file);
}

int main() {
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to address sensor");
        close(i2c_fd);
        return 1;
    }

    write_config(i2c_fd);

    while (1) {
        if (read_data(i2c_fd, PRESSURE_REG) < 0) {
            fprintf(stderr, "Sensor absent or bus error\n");
            break;
        }

        uint16_t pressure = ((uint16_t)read_msg.buf[3] << 8) | read_msg.buf[4];
        uint16_t temperature = ((uint16_t)read_msg.buf[5] << 8) | read_msg.buf[6];

        write_command(i2c_fd);
        usleep(1000000);

        log_data("pressure_log.csv", pressure, temperature);
        sleep(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, 0) < 0) {
        perror("Failed to release I2C bus");
    }

    close(i2c_fd);
    return 0;
}

