    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to address sensor");
        close(i2c_fd);
        return 1;
    }

    write_config(i2c_fd);

    while (1) {
        if (read_data(i2c_fd, PRESSURE_REG) < 0) {
