        }

        uint16_t pressure = ((uint16_t)read_msg.buf[3] << 8) | read_msg.buf[4];
        uint16_t temperature = ((uint16_t)read_msg.buf[5] << 8) | read_msg.buf[6];

        write_command(i2c_fd);
