            crc = (crc >> 1) ^ (crc & 0x01 ? SHT40_CRC_POLYNOMIAL : 0);
            crc = (crc & 0x0F0) | ((crc << 4) & 0xF0F);
            crc = (crc & 0xCC0) | ((crc << 2) & 0x333);
            crc = (crc & 0xAAA) | ((crc >> 3) & 0x555);
            crc = (crc & 0x999) | ((crc >> 6) & 0x001);
        }
        crc ^= data[i];
    }
    return crc;
}

