Now, here's the C code:

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <sys/stat.h>
#include <gpiod.h>

#define I2C_BUS 1
#define SDP31_ADDR 0x48
#define CRCI2C_POLL_COUNT 3
#define CRCI2C_RETRY_DELAY_US 100000
#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE "airflow.log"

volatile sig_atomic_t running = 1;

static int i2c_file;
static gpiod_line_request_lines_data_v1 lines_data = {0};
static gpiod_line_request_data_v1 line_req_data = {0};

int i2c_write(const uint8_t *buf, size_t len) {
    int ret;
    while (len--) {
        ret = write(i2c_file, buf++, 1);
        if (ret != 1) {
            usleep(CRCI2C_RETRY_DELAY_US);
            if (CRCI2C_POLL_COUNT > 0) {
                --CRCI2C_POLL_COUNT;
                continue;
            }
            perror("i2c_write");
            return -1;
        }
    }
    return 0;
}

int i2c_read(uint8_t *buf, size_t len) {
    int ret;
    while (len--) {
        ret = read(i2c_file, buf++, 1);
        if (ret != 1) {
            usleep(CRCI2C_RETRY_DELAY_US);
            if (CRCI2C_POLL_COUNT > 0) {
                --CRCI2C_POLL_COUNT;
                continue;
            }
            perror("i2c_read");
            return -1;
        }
    }
    return 0;
}

void trigger_measurement() {
    uint8_t cmd[] = {0x2E};
    i2c_write(cmd, sizeof(cmd));
    usleep(1000);
}

void read_data(uint8_t *data) {
    i2c_read(data, sizeof(data));
}

void convert_data(uint16_t *pressure, uint16_t *temperature) {
    uint16_t pressure_raw = (data[0] << 8) | data[1];
    uint16_t temperature_raw = (data[3] << 8) | data[4];

    *pressure = pressure_raw * 25; // Convert from raw value to Pa
    *temperature = temperature_raw * 175 / 65536.0 - 40.0; // Convert from raw value to °C
}

void log_data(const char *timestamp, uint16_t pressure, uint16_t temperature) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        return;
    }

    fprintf(log_file, "%s,%u,%u\n", timestamp, pressure, temperature);
    fflush(log_file);
    fclose(log_file);
}

void i2c_cleanup() {
    gpiod_line_release_request(lines_data.fd);
    close(i2c_file);
    gpiod_line_request_destroy(&lines_data);
}

int main() {
    int ret;
    struct timespec ts;
    uint8_t data[6] = {0};
    uint16_t pressure, temperature;
    char timestamp[32];

    // Request GPIO lines for I²C SDA and SCL
    lines_data.request_lines = 2;
    lines_data.lines = malloc(lines_data.request_lines * sizeof(gpiod_line_info));
    lines_data.lines[0].consumer = "SDP31 I²C SDA";
    lines_data.lines[1].consumer = "SDP31 I²C SCL";
    ret = gpiod_line_request_get_fd_byname("gpiochip0", lines_data);
    if (ret < 0) {
        perror("gpiod_line_request_get_fd_byname");
        goto cleanup;
    }
    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file < 0) {
        perror("open");
        goto cleanup;
    }

    if (ioctl(i2c_file, I2C_SLAVE, SDP31_ADDR) < 0) {
        perror("ioctl");
        goto cleanup;
    }

    ret = gpiod_line_request_configure_flags(&lines_data, GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW);
    if (ret < 0) {
        perror("gpiod_line_request_configure_flags");
        goto cleanup;
    }

    line_req_data.consumer = "SDP31 I²C SCL";
    ret = gpiod_line_request_get_fd_bylabel(lines_data.fd, line_req_data.consumer, &line_req_data.line);
    if (ret < 0) {
        perror("gpiod_line_request_get_fd_bylabel");
        goto cleanup;
    }

    while (running) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        snprintf(timestamp, sizeof(timestamp), "%ld.%06ld", (long)ts.tv_sec, (long)ts.tv_nsec / 1000000);

        trigger_measurement();
        usleep(SAMPLE_INTERVAL_US);
        read_data(data);

        convert_data(&pressure, &temperature);
        log_data(timestamp, pressure, temperature);
    }

cleanup:
    i2c_cleanup();
    gpiod_line_request_destroy(&lines_data);
    return 0;
}
