#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <time.h>
#include <sys/time.h>
#include <libgpiod.h>

#define SI7015_I2C_ADDR 0x40
#define SI7015_CMD_TEMP 0x40
#define SI7015_CMD_HUMID 0x20

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int nlines,
                                const char *const names[], unsigned int flags)
{
    return gpiod_chip_get_lines_request_array(chip, nlines, names, flags);
}

int main() {
    int i2c_fd, ret;
    char buf[2];
    struct timespec sleep_time = { 5, 0 };
    struct gpiod_chip *chip;
    struct gpiod_line_request *request;
    FILE *log_file;
    time_t timestamp;

    // Initialize libgpiod
    if ((chip = gpiod_chip_open_byname("gpiochip0")) == NULL) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    // Request the GPIO line for the I2C SDA and SCL
    request = gpiod_line_request_array(chip, 2, (const char*[]){"SDA", "SCL"}, GPIOD_LINE_REQUEST_INPUT);
    if (request == NULL) {
        perror("Failed to request GPIO lines");
        gpiod_chip_put(chip);
        return 1;
    }

    // Open the I2C bus
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        gpiod_line_release_request(request);
        gpiod_chip_put(chip);
        return 1;
    }

    // Initialize I2C bus
    if (ioctl(i2c_fd, I2C_SLAVE, SI7015_I2C_ADDR) < 0) {
        perror("Failed to initialize I2C bus");
        close(i2c_fd);
        gpiod_line_release_request(request);
        gpiod_chip_put(chip);
        return 1;
    }

    // Open log file
    if ((log_file = fopen("sensor_data.txt", "a")) == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpiod_line_release_request(request);
        gpiod_chip_put(chip);
        return 1;
    }

    while (1) {
        // Write command to Si7015 for temperature or humidity measurement
        ret = write(i2c_fd, &SI7015_CMD_TEMP, 1);
        if (ret != 1) {
            perror("Failed to write command to Si7015");
            fclose(log_file);
            close(i2c_fd);
            gpiod_line_release_request(request);
            gpiod_chip_put(chip);
            return 1;
        }

        // Poll-read data from Si7015
        ret = read(i2c_fd, buf, 2);
        if (ret != 2) {
            perror("Failed to read data from Si7015");
            fclose(log_file);
            close(i2c_fd);
            gpiod_line_release_request(request);
            gpiod_chip_put(chip);
            return 1;
        }

        // Check if measurement is ready
        if ((buf[0] & 0xF0) != 0x00) {
            continue;
        }

        // Extract temperature and humidity values
        int16_t temp = (buf[0] << 8) | buf[1];
        float humidity = (float)temp / 16.0;
        int16_t temp_raw = (buf[0] & 0x0F) << 8 | buf[1];
        float temperature = (float)temp_raw * 175.0 / 65536 - 45.0;

        // Print timestamped values to console
        time(&timestamp);
        struct tm *tm = localtime(&timestamp);
        printf("%02d:%02d:%02d - Temperature: %.2f°C, Humidity: %.2f%%\n",
               tm->tm_hour, tm->tm_min, tm->tm_sec, temperature, humidity);

        // Write timestamped values to log file
        fprintf(log_file, "%02d:%02d:%02d - Temperature: %.2f°C, Humidity: %.2f%%\n",
                tm->tm_hour, tm->tm_min, tm->tm_sec, temperature, humidity);

        // Sleep for 5 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Clean up on SIGINT
    signal(SIGINT, [](int sig) {
        close(i2c_fd);
        gpiod_line_release_request(request);
        gpiod_chip_put(chip);
        fclose(log_file);
        exit(0);
    });

    return 0;
}

