        if ((buf[0] & 0xF0) != 0x00) {
            continue;
        }

        // Extract temperature and humidity values
        int16_t temp = (buf[0] << 8) | buf[1];
        float humidity = (float)temp / 16.0;
        int16_t temp_raw = (buf[0] & 0x0F) << 8 | buf[1];
        float temperature = (float)temp_raw * 175.0 / 65536 - 45.0;

        // Print timestamped values to console
        time(&timestamp);
        struct tm *tm = localtime(&timestamp);
        printf("%02d:%02d:%02d - Temperature: %.2f°C, Humidity: %.2f%%\n",
               tm->tm_hour, tm->tm_min, tm->tm_sec, temperature, humidity);

        // Write timestamped values to log file
        fprintf(log_file, "%02d:%02d:%02d - Temperature: %.2f°C, Humidity: %.2f%%\n",
                tm->tm_hour, tm->tm_min, tm->tm_sec, temperature, humidity);

        // Sleep for 5 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Clean up on SIGINT
    signal(SIGINT, [](int sig) {
        close(i2c_fd);
        gpiod_line_release_request(request);
        gpiod_chip_put(chip);
        fclose(log_file);
        exit(0);
    });

    return 0;
}
```

This code reads temperature and humidity from a Si7015 sensor on I2C bus 1, logs the readings to a file named `sensor_data.txt`, and prints the timestamped values to the console. It handles errors, retries transient I2C failures, and terminates cleanly when receiving a SIGINT signal.

