int i2c_write_reg(uint8_t reg, uint8_t value) {
    uint8_t data[2] = {reg, value};
    if (write(i2c_file, data, 2) != 2)
        return -1;
    return 0;
}

int i2c_read_reg(uint8_t reg, uint8_t *buf, size_t len) {
    if (write(i2c_file, &reg, 1) != 1)
        return -1;
    if (read(i2c_file, buf, len) != len)
        return -1;
    return 0;
}

uint8_t crc8(uint8_t *data, size_t len) {
    uint8_t crc = 0;
    for (size_t i = 0; i < len; ++i) {
        for (uint8_t j = 8; j; --j) {
            crc ^= (crc & 0x01) << 1;
            crc >>= 1;
            crc ^= data[i] & 0x01 ? 0x8C : 0;
        }
        data++;
    }
    return crc;
}

int validate_data(uint8_t *data, size_t len) {
    for (size_t i = 0; i < len - 1; ++i) {
        if (data[i] != data[len - 1 - i])
            return 0;
    }
    return data[len - 1] == CRCI2C;
}

