#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <sys/time.h>
#include <errno.h>
#include <string.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x40
#define DATA_LEN 3
#define CRC_POLYNOMIAL 0x07
#define CRC_INIT 0x00

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int nlines,
                                const char *const names, unsigned int flags)
{
    return gpiod_chip_get_lines_request_array(chip, nlines, names, flags);
}

static int i2c_write_read(int fd, const uint8_t *write_buf, size_t write_len,
                          uint8_t *read_buf, size_t read_len)
{
    int ret;
    struct i2c_rdwr_ioctl_data i2c_data;
    i2c_data.msgs = calloc(1, sizeof(struct i2c_msg) * (write_len + read_len));
    if (!i2c_data.msgs) {
        perror("calloc");
        return -1;
    }

    i2c_data.nmsgs = write_len + read_len;

    for (size_t i = 0; i < write_len; ++i) {
        struct i2c_msg msg;
        msg.addr = SENSOR_ADDR;
        msg.flags = 0;
        msg.len = 1;
        msg.buf = &write_buf[i];
        i2c_data.msgs[i] = msg;
    }

    for (size_t i = write_len; i < i2c_data.nmsgs; ++i) {
        struct i2c_msg msg;
        msg.addr = SENSOR_ADDR;
        msg.flags = I2C_M_RD;
        msg.len = 1;
        msg.buf = &read_buf[i - write_len];
        i2c_data.msgs[i] = msg;
    }

    ret = ioctl(fd, I2C_RDWR, &i2c_data);
    free(i2c_data.msgs);
    if (ret < 0) {
        perror("ioctl");
        return -1;
    }

    return 0;
}

static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; ++i) {
        for (int bit = 7; bit >= 0; --bit) {
            crc = (crc >> 1) ^ (crc & 1 ? CRC_POLYNOMIAL : 0);
            crc &= 0xFF;
            crc ^= data[i] << bit;
        }
    }
    return crc;
}

static void log_error(const char *message)
{
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
    fprintf(stderr, "%s: %s\n", timestamp, message);
    fprintf(stderr, "%s\n", strerror(errno));
    fflush(stderr);
}

int main(void)
{
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        log_error("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        log_error("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    gpiod_line_request_lines(chip, 1, "gpiochip0_line0", GPIOD_LINE_REQUEST_INPUT);
    struct gpiod_line *line = gpiod_get_line(chip, "gpiochip0_line0");
    if (!line) {
        log_error("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    int file_enclosure_temp_log = open("enclosure_temp_log.txt", O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (file_enclosure_temp_log < 0) {
        log_error("Failed to open enclosure temperature log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    int file_error_log = open("error_log.txt", O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (file_error_log < 0) {
        log_error("Failed to open error log file");
        close(file_enclosure_temp_log);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    uint8_t write_buf[2] = {0x2E, 0x00};
    uint8_t read_buf[DATA_LEN];
    while (1) {
        if (i2c_write_read(i2c_fd, write_buf, sizeof(write_buf), read_buf, sizeof(read_buf)) < 0) {
            log_error("Failed to read temperature data");
            continue;
        }

        if (read_buf[0] != 0x7F || read_buf[1] != 0x03) {
            log_error("Invalid temperature data response");
            continue;
        }

        uint16_t temp = (read_buf[1] << 8) | read_buf[2];
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
        fprintf(file_enclosure_temp_log, "%s,%d\n", timestamp, temp);
        fprintf(file_error_log, "Successfully read temperature: %s,%d\n", timestamp, temp);

        if (gpiod_line_get_value(line) == 0) {
            gpiod_line_set_value(line, 1);
        }

        usleep(15000);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);
    close(file_enclosure_temp_log);
    close(file_error_log);

    return 0;
}

