        // Send measurement command
        if (write(i2c_fd, &SHT40_CMD_MEASURE_HIGH_RH, 1) != 1) {
            perror("Failed to send measurement command");
            continue;
        }

        // Wait for 8.5ms
        usleep(8500);

        // Read six bytes from the sensor
        if (read(i2c_fd, buf, 6) != 6) {
            perror("Failed to read data from sensor");
            continue;
        }

        // Validate and process the data
        uint16_t temp_raw = (buf[0] << 8) | buf[1];
        uint16_t rh_raw = (buf[3] << 8) | buf[4];
        uint8_t temp_crc = buf[2];
        uint8_t rh_crc = buf[5];

        uint8_t temp_crc_calc = crc8(temp_raw, 2, SHT40_CRC_POLYNOMIAL, SHT40_CRC_INIT);
        uint8_t rh_crc_calc = crc8(rh_raw, 2, SHT40_CRC_POLYNOMIAL, SHT40_CRC_INIT);

