#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <time.h>
#include <stdint.h>
#include <math.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x48
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

static const uint8_t command_continuous_measurement[] = {0x01, 0x00, 0x00, 0x00, 0x00, 0x00};

static uint8_t read_byte(int i2c_fd) {
    uint8_t data;
    ssize_t bytes_read = read(i2c_fd, &data, 1);
    if (bytes_read != 1) {
        perror("Error reading from I2C");
        exit(EXIT_FAILURE);
    }
    return data;
}

static void write_bytes(int i2c_fd, const uint8_t *data, size_t length) {
    ssize_t bytes_written = write(i2c_fd, data, length);
    if (bytes_written != length) {
        perror("Error writing to I2C");
        exit(EXIT_FAILURE);
    }
}

static bool crc8_check(uint8_t *data, size_t length) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (size_t i = 0; i < length; ++i) {
        for (uint8_t bit = 0x80; bit > 0; bit >>= 1) {
            crc = (crc << 1) ^ ((crc & 0x80) ? CRC_POLYNOMIAL : 0);
            crc ^= data[i] & bit;
        }
    }
    return crc == data[length];
}

static float pressure_from_raw(uint16_t raw_pressure) {
    const float sensitivity = 0.00025;
    return raw_pressure * sensitivity;
}

static float temperature_from_raw(uint16_t raw_temperature) {
    const float sensitivity = 0.0625;
    return raw_temperature * sensitivity - 40;
}

int main(void) {
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_dt_byname(NULL, "rpi,gpio-shutdown", GPIOD_LINE_REQUEST_DIRECTION_IN, NULL);

    FILE *log_file = fopen("airflow_data.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        close(i2c_fd);
        gpiod_line_release(NULL, "rpi,gpio-shutdown");
        exit(EXIT_FAILURE);
    }

    write_bytes(i2c_fd, command_continuous_measurement, sizeof(command_continuous_measurement));
    usleep(1000);

    while (1) {
        uint8_t data[6];
        data[0] = read_byte(i2c_fd);
        data[1] = read_byte(i2c_fd);
        data[2] = read_byte(i2c_fd);
        data[3] = read_byte(i2c_fd);
        data[4] = read_byte(i2c_fd);
        data[5] = read_byte(i2c_fd);

        if (!crc8_check(data, 6)) {
            fprintf(stderr, "Invalid CRC\n");
            continue;
        }

        uint16_t raw_pressure = (data[0] << 8) | data[1];
        uint16_t raw_temperature = (data[3] << 8) | data[4];

        float pressure = pressure_from_raw(raw_pressure);
        float temperature = temperature_from_raw(raw_temperature);

        time_t timestamp = time(NULL);
        char timestamp_str[32];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&timestamp));

        fprintf(log_file, "%s,%f,%f\n", timestamp_str, pressure, temperature);
        fflush(log_file);

        usleep(1000000); // 1ms delay between readings

        if (gpiod_line_get_value(NULL, "rpi,gpio-shutdown")) {
            break;
        }
    }

    fclose(log_file);
    gpiod_line_release(NULL, "rpi,gpio-shutdown");
    close(i2c_fd);

    return 0;
}

