code:
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/time.h>
#include <errno.h>
#include <gpiod.h>

#define SI7021_ADDR 0x40
#define FAN_GPIO 18
#define BUFFER_SIZE 60
#define HYSTERESIS 0.5
#define RETRIES 3

struct reading {
    struct timeval tv;
    int16_t temp;
};

gpiod_line_request_lines(1, &FAN_GPIO, GPIOD_LINE_REQUEST_DIRECTION_OUT, "fan");

int i2c_file;
struct i2c_rdwr_ioctl_data i2c_data;
struct i2c_msg i2c_msgs[] = {
    {
        .addr = SI7021_ADDR << 1,
        .flags = 0,
        .len = 0,
        .buf = NULL,
    },
    {
        .addr = SI7021_ADDR << 1,
        .flags = I2C_M_RD,
        .len = 2,
        .buf = malloc(2),
    },
};

struct reading buffer[BUFFER_SIZE];
int head = 0, tail = 0;

void i2c_read() {
    int i;
    for (i = 0; i < RETRIES; ++i) {
        i2c_data.wr_msgs = &i2c_msgs[0];
        i2c_data.rd_msgs = &i2c_msgs[1];
        if (ioctl(i2c_file, I2C_RDWR, &i2c_data) >= 0)
            break;
        usleep(100000);
    }

    if (i == RETRIES) {
        perror("I2C read failed");
        exit(EXIT_FAILURE);
    }
}

float read_temp() {
    i2c_read();
    float temp = (i2c_msgs[1].buf[0] << 8) | i2c_msgs[1].buf[1];
    temp /= 16.0;
    return temp;
}

void fan_control(float temp) {
    if (temp > 28.0 + HYSTERESIS) {
        gpiod_line_set_value(FAN_GPIO, 1);
    } else if (temp < 27.0 - HYSTERESIS) {
        gpiod_line_set_value(FAN_GPIO, 0);
    }
}

void print_reading(const struct reading *r) {
    char buf[32];
    struct timeval *tv = &r->tv;
    snprintf(buf, sizeof(buf), "%ld.%06ld °C\n", tv->tv_sec, tv->tv_usec);
    write(STDOUT_FILENO, buf, strlen(buf));
}

void buffer_reading(const struct reading *r) {
    buffer[head] = *r;
    head = (head + 1) % BUFFER_SIZE;
}

void check_sensor_absent() {
    int i;
    for (i = 0; i < BUFFER_SIZE; ++i) {
        if (buffer[i].temp != -1)
            return;
    }
    fprintf(stderr, "Sensor absent, degrading gracefully\n");
    gpiod_line_set_value(FAN_GPIO, 0);
}

void sigint_handler(int signum) {
    gpiod_line_set_value(FAN_GPIO, 0);
    close(i2c_file);
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, sigint_handler);

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_file, I2C_SLAVE, SI7021_ADDR) < 0) {
        perror("Failed to talk to the Si7021");
        exit(EXIT_FAILURE);
    }

    while (1) {
        float temp = read_temp();
        buffer_reading(&(struct reading){gettimeofday(&(buffer[tail].tv), NULL), temp});
        tail = (tail + 1) % BUFFER_SIZE;

        fan_control(temp);
        usleep(10000);

        check_sensor_absent();

        usleep(2000000);
    }

    close(i2c_file);
    gpiod_line_release(FAN_GPIO);
    return 0;
}

