code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define SCD40_ADDR 0x5A
#define CO2_THRESHOLD 1000
#define BUFFER_SIZE 20
#define CRC8_POLYNOMIAL 0x31

struct reading {
    uint16_t co2;
    float temperature;
    float humidity;
};

struct i2c_rdwr_ioctl_data {
    struct i2c_msg msgs[2];
};

struct gpio_chan *gpio_led;
struct i2c_client *i2c_client;
struct reading buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;

void i2c_write(uint8_t reg, uint8_t *data, size_t len) {
    struct i2c_rdwr_ioctl_data ioctl_data;
    struct i2c_msg msg[2];

    msg[0].addr = SCD40_ADDR << 1;
    msg[0].flags = 0;
    msg[0].len = len + 1;
    msg[0].buf = &reg;
    msg[0].buf += 1;
    memcpy(msg[0].buf, data, len);

    msg[1].addr = SCD40_ADDR << 1;
    msg[1].flags = I2C_M_NOSTART;
    msg[1].len = 0;

    ioctl_data.msgs[0] = msg[0];
    ioctl_data.msgs[1] = msg[1];

    if (ioctl(i2c_client->fd, I2C_RDWR, &ioctl_data) < 0) {
        perror("I2C write error");
        exit(EXIT_FAILURE);
    }
}

uint8_t i2c_read(uint8_t reg, uint8_t *data, size_t len) {
    struct i2c_rdwr_ioctl_data ioctl_data;
    struct i2c_msg msg[2];
    uint8_t crc = 0;

    msg[0].addr = SCD40_ADDR << 1;
    msg[0].flags = 0;
    msg[0].len = len + 2;
    msg[0].buf = &reg;
    msg[0].buf += 1;
    msg[0].buf[1] = len;

    msg[1].addr = SCD40_ADDR << 1;
    msg[1].flags = I2C_M_RD;
    msg[1].len = len + 2;
    msg[1].buf = data;

    ioctl_data.msgs[0] = msg[0];
    ioctl_data.msgs[1] = msg[1];

    if (ioctl(i2c_client->fd, I2C_RDWR, &ioctl_data) < 0) {
        perror("I2C read error");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < len; ++i) {
        crc = crc8(crc, data[i]);
    }

    if (crc != data[len]) {
        fprintf(stderr, "CRC error\n");
        return 0;
    }

    return len;
}

uint8_t crc8(uint8_t crc, uint8_t data) {
    for (size_t i = 8; i > 0; --i) {
        crc = (crc >> 1) ^ (crc & 0x01 ? CRC8_POLYNOMIAL : 0);
        crc = (crc >> 8) ^ data;
    }

    return crc;
}

void gpio_setup() {
    int ret;
    struct gpiod_line_request request = {
        .consumer = "CO2_LED",
        .direction = GPIOD_IN,
        .flags = GPIOD_LINE_ACTIVE_LOW,
    };

    gpio_led = gpiod_get_index(1, GPIO17);
    if (IS_ERR(gpio_led)) {
        perror("Failed to get GPIO17");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_dup(gpio_led, &request);
    if (ret < 0) {
        perror("Failed to request GPIO17");
        exit(EXIT_FAILURE);
    }
}

void i2c_setup() {
    int ret;
    const char *i2c_bus = "/dev/i2c-1";

    i2c_client = i2c_open(i2c_bus, SCD40_ADDR);
    if (!i2c_client) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    ret = i2c_smbus_read_byte_data(i2c_client, 0x00);
    if (ret < 0) {
        perror("Failed to read device ID");
        exit(EXIT_FAILURE);
    }

    if (ret != 0x62) {
        fprintf(stderr, "Wrong device ID\n");
        exit(EXIT_FAILURE);
    }
}

void sigint_handler(int signum) {
    i2c_close(i2c_client->fd);
    gpiod_line_release(gpio_led);
    gpiod_put_index(1, GPIO17);
    gpiod_close(gpio_led);
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    gpio_setup();
    i2c_setup();

    while (1) {
        uint8_t data[6];
        size_t len = i2c_read(0x00, data, 6);
        if (len != 6) {
            continue;
        }

        struct reading reading = {
            .co2 = (data[1] << 8) | data[2],
            .temperature = (data[3] << 8) | data[4],
            .humidity = (data[5] << 8) | data[6],
        };

        if (reading.co2 > CO2_THRESHOLD) {
            gpiod_set_value_cansleep(gpio_led, 1);
        } else {
            gpiod_set_value_cansleep(gpio_led, 0);
        }

        buffer[buffer_head] = reading;
        buffer_head = (buffer_head + 1) % BUFFER_SIZE;

        printf("CO2: %d ppm, Temperature: %.2f °C, Humidity: %.2f %%\n",
            reading.co2, reading.temperature / 100.0, reading.humidity / 100.0);

        sleep(5);
    }

    return 0;
}

