        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < len; ++i) {
        crc = crc8(crc, data[i]);
    }

    if (crc != data[len]) {
        fprintf(stderr, "CRC error\n");
        return 0;
    }

    return len;
}

uint8_t crc8(uint8_t crc, uint8_t data) {
    for (size_t i = 8; i > 0; --i) {
        crc = (crc >> 1) ^ (crc & 0x01 ? CRC8_POLYNOMIAL : 0);
        crc = (crc >> 8) ^ data;
    }

    return crc;
}

void gpio_setup() {
    int ret;
    struct gpiod_line_request request = {
        .consumer = "CO2_LED",
        .direction = GPIOD_IN,
        .flags = GPIOD_LINE_ACTIVE_LOW,
    };

    gpio_led = gpiod_get_index(1, GPIO17);
    if (IS_ERR(gpio_led)) {
        perror("Failed to get GPIO17");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_dup(gpio_led, &request);
    if (ret < 0) {
        perror("Failed to request GPIO17");
        exit(EXIT_FAILURE);
    }
}

void i2c_setup() {
    int ret;
    const char *i2c_bus = "/dev/i2c-1";

    i2c_client = i2c_open(i2c_bus, SCD40_ADDR);
    if (!i2c_client) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    ret = i2c_smbus_read_byte_data(i2c_client, 0x00);
    if (ret < 0) {
        perror("Failed to read device ID");
        exit(EXIT_FAILURE);
    }

    if (ret != 0x62) {
        fprintf(stderr, "Wrong device ID\n");
        exit(EXIT_FAILURE);
    }
}

void sigint_handler(int signum) {
    i2c_close(i2c_client->fd);
    gpiod_line_release(gpio_led);
    gpiod_put_index(1, GPIO17);
    gpiod_close(gpio_led);
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    gpio_setup();
    i2c_setup();

    while (1) {
        uint8_t data[6];
        size_t len = i2c_read(0x00, data, 6);
        if (len != 6) {
            continue;
        }

        struct reading reading = {
            .co2 = (data[1] << 8) | data[2],
            .temperature = (data[3] << 8) | data[4],
            .humidity = (data[5] << 8) | data[6],
        };

        if (reading.co2 > CO2_THRESHOLD) {
            gpiod_set_value_cansleep(gpio_led, 1);
        } else {
            gpiod_set_value_cansleep(gpio_led, 0);
        }

        buffer[buffer_head] = reading;
        buffer_head = (buffer_head + 1) % BUFFER_SIZE;

        printf("CO2: %d ppm, Temperature: %.2f °C, Humidity: %.2f %%\n",
            reading.co2, reading.temperature / 100.0, reading.humidity / 100.0);

        sleep(5);
    }

    return 0;
}
```

This code initializes the I2C bus and the CO2 warning LED, reads data from the SCD40 sensor every 5 seconds, validates the CRC-8 checksum, stores the readings in a circular buffer, and turns the LED on when the CO2 concentration exceeds the specified threshold. It also handles SIGINT and SIGTERM signals gracefully by closing the I2C handle, releasing the GPIO, and shutting down the driver cleanly.

