#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <sys/time.h>
#include <signal.h>
#include <libgpiod.h>

#define SHT35_ADDR 0x44
#define SHT35_CMD_MEASURE_HIGH_RH 0x24
#define SHT35_CMD_MEASURE_NO_CRC 0x20
#define SHT35_CRC_POLYNOMIAL 0x31

struct i2c_rdwr_ioctl_data {
    struct i2c_msg messages[2];
    unsigned int num;
};

struct gpio_chip *gpiochip;

void sigint_handler(int signum) {
    gpiod_set_value_cansleep(gpiochip, 1, 0);
    exit(0);
}

int read_sht35(int fd, uint8_t *buf) {
    struct i2c_rdwr_ioctl_data data;
    data.num = 2;
    data.messages[0].addr = SHT35_ADDR;
    data.messages[0].flags = 0;
    data.messages[0].len = 1;
    data.messages[0].buf = &SHT35_CMD_MEASURE_NO_CRC;

    data.messages[1].addr = SHT35_ADDR;
    data.messages[1].flags = I2C_M_RD;
    data.messages[1].len = 6;
    data.messages[1].buf = buf;

    if (ioctl(fd, I2C_RDWR, &data) < 0) {
        perror("Failed to read from SHT35");
        return -1;
    }

    return 0;
}

uint16_t crc16(const uint8_t *data, size_t len) {
    uint16_t crc = 0xFFFF;
    for (size_t i = 0; i < len; ++i) {
        for (int j = 8; j; --j) {
            crc = (crc & 0x8000) ? (crc << 1) ^ SHT35_CRC_POLYNOMIAL : crc << 1;
            crc ^= data[i] & 0xFF;
        }
    }
    return ~crc;
}

float sht35_to_celsius(uint16_t raw) {
    float t = (raw & 0xFFF) * 175.0 / 65536.0 - 45.0;
    return t > 85.0 ? t - 273.15 : t;
}

float sht35_to_rh(uint16_t raw) {
    float rh = (raw & 0xFFF) * 100.0 / 65536.0;
    return rh > 100.0 ? 100.0 : rh;
}

void log_data(const char *timestamp, float temp, float rh) {
    FILE *file = fopen("environmental_data.txt", "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(file, "%s,%f,%f\n", timestamp, temp, rh);
    fflush(file);
    fclose(file);
}

int main() {
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SHT35_ADDR) < 0) {
        perror("Failed to talk to SHT35");
        close(i2c_fd);
        exit(1);
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", localtime(&ts.tv_sec));

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    gpiod_library_open();
    gpiochip = gpiod_chip_open_byname("gpiochip0");
    if (!gpiochip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(1);
    }

    float temp_offset = 0.0;
    float rh_offset = 0.0;
    float temp_offset_inc = 0.004;
    float rh_offset_inc = 0.02;
    time_t one_hour_ago = time(NULL) - 3600;
    time_t current_time;

    while (1) {
        current_time = time(NULL);
        if (current_time >= one_hour_ago) {
            temp_offset += temp_offset_inc;
            rh_offset += rh_offset_inc;
            one_hour_ago += 3600;
        }

        uint8_t buf[6];
        if (read_sht35(i2c_fd, buf) < 0) {
            continue;
        }

        uint16_t temp_raw = (buf[0] << 8) | buf[1];
        uint16_t rh_raw = (buf[3] << 8) | buf[4];

        uint16_t temp_crc = crc16(buf, 2);
        uint16_t rh_crc = crc16(buf + 2, 4);

        if (temp_crc != buf[5] || rh_crc != buf[6]) {
            continue;
        }

        float temp = sht35_to_celsius(temp_raw);
        float rh = sht35_to_rh(rh_raw);
        temp += temp_offset;
        rh += rh_offset;

        log_data(timestamp, temp, rh);
        usleep(5000000);
    }

    gpiod_chip_close(gpiochip);
    gpiod_library_close();
    close(i2c_fd);

    return 0;
}

