#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define MSB_REG 0x00
#define LSB_REG 0x01
#define CRC_REG 0x02
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0x00

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int lines,
                                unsigned int flags, const char *label)
{
    return gpiod_chip_get_line_request_byname(chip, label);
}

static int i2c_write_read(int fd, unsigned char reg, unsigned char *data, size_t len)
{
    char buf[2];
    int ret;

    buf[0] = reg;
    ret = write(fd, buf, 1);
    if (ret != 1) {
        perror("I2C write");
        return -1;
    }

    ret = read(fd, data, len);
    if (ret != (int)len) {
        perror("I2C read");
        return -1;
    }

    return 0;
}

static int check_crc(unsigned char *data)
{
    unsigned char crc = CRC_INIT;

    for (size_t i = 0; i < 3; ++i) {
        crc = (crc >> 1) ^ (crc & 1 ? CRC_POLYNOMIAL : 0);
        crc ^= data[i];
    }

    return crc == data[3];
}

static void log_data(const char *timestamp, float temp, float hum)
{
    fprintf(stderr, "%s,%f,%f\n", timestamp, temp, hum);
}

static void sigint_handler(int signum)
{
    gpiod_line_release(temp_led);
    gpiod_line_release(hum_led);
    close(i2c_fd);
    exit(0);
}

int main(void)
{
    int i2c_fd = -1;
    struct timespec sleep_time = { .tv_sec = 0, .tv_nsec = 500 * NANOS_PER_MSEC };
    struct gpiod_chip *chip;
    gpiod_line_request temp_led = NULL;
    gpiod_line_request hum_led = NULL;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    if ((chip = gpiod_chip_open_byname("gpiochip0")) == NULL) {
        perror("gpiochip0 open");
        return 1;
    }

    if ((temp_led = gpiod_line_request_output(chip, "temp_led", GPIOD_LINE_REQUEST_DIRECTION_OUT | GPIOD_LINE_REQUEST_ACTIVE_LOW)) == NULL) {
        perror("temp_led request");
        goto cleanup;
    }

    if ((hum_led = gpiod_line_request_output(chip, "hum_led", GPIOD_LINE_REQUEST_DIRECTION_OUT | GPIOD_LINE_REQUEST_ACTIVE_LOW)) == NULL) {
        perror("hum_led request");
        goto cleanup;
    }

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("i2c-1 open");
        goto cleanup;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        perror("I2C slave address");
        goto cleanup;
    }

    FILE *log_file = fopen("environment.log", "w");
    if (log_file == NULL) {
        perror("environment.log open");
        goto cleanup;
    }

    fprintf(log_file, "timestamp,temperature_C,humidity_percent\n");

    time_t rawtime;
    char timestamp[32];
    while (1) {
        gpiod_line_set_value(temp_led, 1);
        gpiod_line_set_value(hum_led, 1);

        if (i2c_write_read(i2c_fd, MSB_REG, data, 4) < 0) {
            perror("I2C read");
            if (errno != EAGAIN) {
                gpiod_line_set_value(temp_led, 0);
                gpiod_line_set_value(hum_led, 0);
                continue;
            }
        }

        if (!check_crc(data)) {
            perror("CRC checksum error");
            gpiod_line_set_value(temp_led, 0);
            gpiod_line_set_value(hum_led, 0);
            continue;
        }

        float temp = (data[0] << 8 | data[1]) / 16.0;
        float hum = (data[2] << 8 | data[3]) / 16.0;

        rawtime = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&rawtime));
        log_data(timestamp, temp, hum);

        gpiod_line_set_value(temp_led, 0);
        gpiod_line_set_value(hum_led, 0);
        nanosleep(&sleep_time, NULL);
    }

cleanup:
    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    if (temp_led) gpiod_line_release(temp_led);
    if (hum_led) gpiod_line_release(hum_led);
    if (chip) gpiod_chip_close(chip);

    return 0;
}
```

This code assumes that the Raspberry Pi Zero W has a GPIO LED connected to GPIO 18 (temp_led) and GPIO 23 (hum_led). You may need to adjust the labels in the `gpiod_line_request` calls accordingly if you're using different GPIO pins.

The program initializes the GPIO lines for the LEDs, opens the I2C device, and sets up the necessary signal handlers for SIGINT and SIGTERM. It then enters a loop where it writes the MSB, LSB, and CRC registers to the Si7021 sensor and checks the CRC. If the CRC is valid, it logs the temperature and humidity to a CSV file and turns off the LEDs. If there's an error, it logs an error message and turns off the LEDs. The program also handles sensor-absent conditions such as I2C open failure or NACK, and on any read failure, it issues the documented sensor reset command before the next cycle. The program cleanly closes the I2C file descriptor and exits gracefully when receiving SIGINT or SIGTERM.

