#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define SENSOR_ID 0x01
#define CONTINUOUS_MEASUREMENT 0x01
#define SAMPLE_INTERVAL_MS 1000
#define CRCI8_POLYNOMIAL 0x31

struct i2c_rdwr_ioctl_data {
    struct i2c_msg messages[2];
};

int main() {
    int i2c_fd, ret;
    struct i2c_rdwr_ioctl_data i2c_data;
    uint8_t cmd[2] = {SENSOR_ID, CONTINUOUS_MEASUREMENT};
    uint8_t buf[12];
    uint16_t crc_pressure, crc_temperature;
    float pressure, temperature;
    FILE *file;
    gpiod_line_request_linestate_cb_t gpio_cb;
    gpiod_line_request_data_t gpio_req;
