        return 1;
    }

    err = gpiod_line_request_get_byindex(err, 14, GPIOD_LINE_REQUEST_DIRECTION_IN,
                                          GPIOD_LINE_REQUEST_EDGE_RISING, &gpio_req);
    if (err) {
        fprintf(stderr, "Failed to request GPIO line 14: %s\n", strerror(err));
        gpiod_chip_close(err);
        return 1;
    }

    gpio_cb = [](struct gpiod_line_request *request, gpiod_line_state state, void *user_data) {
        (void)request;
        (void)user_data;
        signal(SIGINT, SIG_DFL);
        signal(SIGTERM, SIG_DFL);
        exit(0);
    };

    err = gpiod_line_request_set_callback(gpio_req, gpio_cb, NULL);
    if (err) {
        fprintf(stderr, "Failed to set GPIO callback: %s\n", strerror(err));
        gpiod_line_request_free(gpio_req);
        gpiod_chip_close(err);
        return 1;
    }

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        goto cleanup_gpio;
    }

    // Initialize I2C bus
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        goto cleanup_i2c;
    }

    // Write command to initiate continuous measurement
    i2c_data.messages[0].addr = I2C_ADDR;
    i2c_data.messages[0].flags = 0;
    i2c_data.messages[0].len = 2;
    i2c_data.messages[0].buf = cmd;

    i2c_data.messages[1].addr = I2C_ADDR;
    i2c_data.messages[1].flags = I2C_M_RD;
    i2c_data.messages[1].len = 9;
    i2c_data.messages[1].buf = buf;

    ret = ioctl(i2c_fd, I2C_RDWR, &i2c_data);
    if (ret < 0) {
        perror("Failed to write command and read data");
        goto cleanup_i2c;
    }

    // Wait for conversion time (100ms)
    usleep(100000);

    // Read data and validate CRC
    crc_pressure = buf[0] + (buf[1] << 8) + (buf[2] << 16) + (buf[3] << 24);
    crc_temperature = buf[4] + (buf[5] << 8) + (buf[6] << 16) + (buf[7] << 24);

    if ((crc_pressure != crc8(buf + 8, 3) || crc_temperature != crc8(buf + 11, 3))
        || buf[8] != SENSOR_ID) {
        fprintf(stderr, "Invalid CRC or sensor ID\n");
        goto cleanup_i2c;
    }

    // Convert raw data to floating-point pressure and temperature
    pressure = (float)((buf[9] << 8) + buf[10]) / 100.0;
    temperature = (float)((buf[11] << 8) + buf[12]) / 16.0;

    // Open binary file for logging
    if ((file = fopen("airflow.dat", "ab")) == NULL) {
        perror("Failed to open log file");
        goto cleanup_i2c;
    }

