        fprintf(file, "%f %f\n", pressure, temperature);

        // Wait for sample interval
        usleep(SAMPLE_INTERVAL_MS * 1000);

        // Read data and validate CRC
        ret = read(i2c_fd, buf, 9);
        if (ret != 9) {
            perror("Failed to read data");
            goto cleanup_file;
        }

        crc_pressure = buf[0] + (buf[1] << 8) + (buf[2] << 16) + (buf[3] << 24);
        crc_temperature = buf[4] + (buf[5] << 8) + (buf[6] << 16) + (buf[7] << 24);

        if ((crc_pressure != crc8(buf + 8, 3) || crc_temperature != crc8(buf + 11, 3))
            || buf[8] != SENSOR_ID) {
            fprintf(stderr, "Invalid CRC or sensor ID\n");
            goto cleanup_file;
        }

        pressure = (float)((buf[9] << 8) + buf[10]) / 100.0;
        temperature = (float)((buf[11] << 8) + buf[12]) / 16.0;
    }

cleanup_file:
    fclose(file);

cleanup_i2c:
    close(i2c_fd);

cleanup_gpio:
    gpiod_line_request_free(gpio_req);
    gpiod_chip_close(err);

    return 0;
}

uint16_t crc8(const uint8_t *data, size_t len) {
    uint16_t crc = 0;
    for (size_t i = 0; i < len; ++i) {
        for (uint8_t j = 8; j > 0; --j) {
            crc = (crc >> 1) ^ (crc & 1 ? CRCI8_POLYNOMIAL : 0);
            crc ^= data[i] << 7;
        }
    }
    return crc;
}

