code:
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define SENSOR_ID 0x01
#define CONTINUOUS_MEASUREMENT_CMD 0x01
#define DATA_WORD_LENGTH 3
#define CRC_POLYNOMIAL 0x31
#define LOG_FILE "pressure_log.txt"
#define LOG_INTERVAL 5

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int nlines,
                                const char *const *consumer_names,
                                unsigned int flags) {
    return gpiod_chip_request_lines(chip, nlines, consumer_names, flags);
}

static int read_i2c_data(int fd, uint8_t *buf, size_t len) {
    int ret;
    ret = read(fd, buf, len);
    if (ret < 0) {
        perror("I2C read error");
        return -1;
    }
    return ret;
}

static int write_i2c_data(int fd, uint8_t *buf, size_t len) {
    int ret;
    ret = write(fd, buf, len);
    if (ret < 0) {
        perror("I2C write error");
        return -1;
    }
    return ret;
}

static uint8_t crc8(uint8_t *data, size_t len, uint8_t polynomial) {
    uint8_t crc = 0;
    for (size_t i = 0; i < len; ++i) {
        for (uint8_t bit = 8; bit > 0; --bit) {
            crc = (crc << 1) | (crc >> 7);
            if ((crc & 0x80) && (data[i] & (1 << (7 - bit))))
                crc = (crc ^ polynomial);
        }
        crc = crc & 0x7F;
    }
    return crc;
}

int main(void) {
    int i2c_fd;
    struct timespec ts;
    uint8_t data[DATA_WORD_LENGTH + 1];
    gpiod_line_data_values_t values;

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire I2C bus");
        close(i2c_fd);
        return 1;
    }

    if (write_i2c_data(i2c_fd, &SENSOR_ID, 1) < 0) {
        perror("Failed to write sensor ID");
        goto cleanup;
    }

    if (write_i2c_data(i2c_fd, &CONTINUOUS_MEASUREMENT_CMD, 1) < 0) {
        perror("Failed to start continuous measurement");
        goto cleanup;
    }

    usleep(45 * 1000);

    if (read_i2c_data(i2c_fd, data, DATA_WORD_LENGTH + 1) != (DATA_WORD_LENGTH + 1)) {
        perror("Failed to read data");
        goto cleanup;
    }

    for (size_t i = 0; i < DATA_WORD_LENGTH; ++i) {
        if (crc8(data, DATA_WORD_LENGTH, CRC_POLYNOMIAL) != data[DATA_WORD_LENGTH]) {
            fprintf(stderr, "CRC error\n");
            goto cleanup;
        }
    }

    clock_gettime(CLOCK_REALTIME, &ts);
    printf("Pressure: %d mbar, Timestamp: %ld.%09ld\n",
           (int)(data[0] << 8 | data[1]),
           ts.tv_sec, ts.tv_nsec);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        goto cleanup;
    }

    fprintf(log_file, "Pressure: %d mbar, Timestamp: %ld.%09ld\n",
            (int)(data[0] << 8 | data[1]),
            ts.tv_sec, ts.tv_nsec);
    fclose(log_file);

    clock_gettime(CLOCK_REALTIME, &ts);
    printf("Sleeping for %ld seconds...\n", LOG_INTERVAL);

    ts.tv_sec += LOG_INTERVAL;
    while (ts.tv_sec > clock_gettime(CLOCK_REALTIME, &ts).tv_sec) {
        usleep(1000 * 1000 * LOG_INTERVAL - (ts.tv_nsec + 500000000) % (1000 * 1000 * LOG_INTERVAL));
    }

cleanup:
    close(i2c_fd);
    gpiod_chip_release_lines(gpiod_chip_get_by_label("i2c-1_sda"));
    gpiod_chip_release_lines(gpiod_chip_get_by_label("i2c-1_scl"));

    if (SIGINT == signal || SIGTERM == signal) {
        printf("Exiting gracefully...\n");
    }

    return 0;
}

