        fflush(log_file);

        usleep(1000000);
    }

cleanup_i2c:
    if (i2c_fd >= 0) {
        cleanup_i2c(i2c_fd);
    }

    if (log_file) {
        fclose(log_file);
    }

    return 0;
}

