#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define STLM75_ADDR 0x49
#define LED_GPIO 17
#define BUFFER_SIZE 10

int i2c_file;
struct gpiod_line_request *led_request;
float buffer[BUFFER_SIZE];
int head = 0;
float running_avg = 0.0;

void i2c_read(void) {
    char buf[2];
    int ret;

    if ((ret = i2c_smbus_read_word_data(i2c_file, STLM75_ADDR, 0)) < 0) {
        perror("i2c_smbus_read_word_data");
        return;
    }

    buffer[head] = (float)ret * 0.0625; // Convert from 12-bit value to °C
    head = (head + 1) % BUFFER_SIZE;
}

void compute_running_avg(void) {
    float temp_sum = 0.0;
    int count = 0;

    for (int i = head; i != head + BUFFER_SIZE - 1; i = (i + 1) % BUFFER_SIZE) {
        temp_sum += buffer[i];
        count++;
    }

    running_avg = temp_sum / count;
}

void led_control(int state) {
    if (led_request) {
        gpiod_line_set_value(led_request, state);
    }
}

void cleanup(void) {
    if (led_request) {
        gpiod_line_release(led_request);
        gpiod_line_request_free(led_request);
    }

    if (i2c_file >= 0) {
        close(i2c_file);
    }
}

int main(void) {
    int ret;

    if ((i2c_file = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    if ((ret = ioctl(i2c_file, I2C_SLAVE, STLM75_ADDR)) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    if ((led_request = gpiod_chip_get_line_request_byname(gpiod_chip_get_bylabel("gpiochip0"), "gpio17")) == NULL) {
        perror("gpiod_chip_get_line_request_byname");
        exit(EXIT_FAILURE);
    }

    if ((ret = gpiod_line_request_direction_output(led_request, GPIOD_LINE_ACTIVE_HIGH)) < 0) {
        perror("gpiod_line_request_direction_output");
        exit(EXIT_FAILURE);
    }

    if ((ret = gpiod_line_request_enable(led_request)) < 0) {
        perror("gpiod_line_request_enable");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        i2c_read();
        compute_running_avg();
        led_control(running_avg > 28.0 ? 1 : 0);
        sleep(1);
    }

    return 0;
}

