        perror("Failed to request GPIO line");
        gpiod_line_free(line);
        gpiod_chip_release(chip);
        return 1;
    }

    if (signal(SIGINT, sigint_handler) == SIG_ERR || signal(SIGTERM, sigint_handler) == SIG_ERR) {
        perror("Failed to set signal handlers");
        gpiod_line_set_value(0, GPIO_FAN, 0);
        gpiod_line_free(line);
        gpiod_chip_release(chip);
        return 1;
    }

