        close(i2c_fd);
        gpiod_line_set_value(0, GPIO_FAN, 0);
        gpiod_line_free(line);
        gpiod_chip_release(chip);
        return 1;
    }

    while (1) {
        i2c_msg[0].addr = SCD30_ADDR;
        i2c_msg[0].flags = 0;
        i2c_msg[0].len = 2;
        i2c_msg[0].buf = (uint8_t*) &buf[0];
        i2c_msg[1].addr = SCD30_ADDR;
        i2c_msg[1].flags = I2C_M_RD;
        i2c_msg[1].len = 8;
        i2c_msg[1].buf = (uint8_t*) &buf[2];

        ret = ioctl(i2c_fd, I2C_RDWR, i2c_msg);
        if (ret < 0) {
            perror("Failed to read from I2C device");
            continue;
        }

        if (buf[0] != 0x40 || buf[1] != 0x13) {
            fprintf(stderr, "Invalid response from SCD30\n");
            continue;
        }

        if (buf[6] != buf[7] + buf[8] + buf[9]) {
            fprintf(stderr, "CRC error\n");
            continue;
        }

        rawtime = time(NULL);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

        fprintf(log_file, "%s,%d,%d\n", timestamp, (int) (buf[4] << 8 | buf[5]), (int) (buf[2] << 8 | buf[3]));
        fflush(log_file);

        switch ((int) (buf[4] << 8 | buf[5])) {
            case 0 ... 799:
                gpiod_line_set_value(0, GPIO_FAN, 0);
                break;
            case 800 ... 1199:
                gpiod_line_set_value(1, GPIO_FAN, 1);
                break;
            default:
                gpiod_line_set_value(1, GPIO_FAN, 1);
        }

        ts.tv_sec = 5;
        nanosleep(&ts, NULL);
    }

    fclose(log_file);
    close(i2c_fd);
    gpiod_line_set_value(0, GPIO_FAN, 0);
    gpiod_line_free(line);
    gpiod_chip_release(chip);

    return 0;
}

