    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        i2c_error_and_exit("Failed to open I2C device");
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP32_ADDR) < 0) {
