        exit(1);
    }

    if (argc == 2) {
        sample_interval_us = atoi(argv[1]) * 1000;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpio_init();
    i2c_init();

    while (1) {
        read_sensor_data();
        usleep(sample_interval_us);
    }

    gpio_cleanup();
    close(i2c_fd);
