#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <errno.h>
#include <math.h>
#include <signal.h>

#define I2C_BUS 1
#define SDA_GPIO 2
#define SCL_GPIO 3
#define SDP810_ADDR 0x48
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

struct i2c_rdwr_ioctl_data {
    struct i2c_msg msgs[2];
};

unsigned char crc8(unsigned char *data, int len) {
    unsigned char crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        for (int j = 8; j > 0; j--) {
            crc = (crc >> 1) ^ (crc & 0x01 ? CRC_POLYNOMIAL : 0);
            crc = (crc & 0x0F0) | ((crc << 4) & 0xF00);
            crc = (crc & 0xCC0) | ((crc << 2) & 0x3300);
            crc = (crc & 0xAAA) | ((crc << 1) & 0x5555);
            crc = (crc & 0x9999) | ((crc >> 3) & 0x1111);
            crc = (crc & 0x555) | ((crc >> 4) & 0xAAAA);
            crc = (crc & 0x33) | ((crc >> 5) & 0xCCC);
            crc = (crc & 0x0F) | ((crc >> 4) & 0xF0);
        }
        crc = data[i] ^ (crc & 0x0F);
    }
    return crc;
}

int read_sdp810(int i2c_fd, unsigned char *buf) {
    struct i2c_rdwr_ioctl_data rw;
    rw.msgs[0].addr = SDP810_ADDR << 1;
    rw.msgs[0].flags = 0;
    rw.msgs[0].len = 2;
    rw.msgs[0].buf = (char *) &buf[0];
    rw.msgs[1].addr = SDP810_ADDR << 1;
    rw.msgs[1].flags = I2C_M_RD;
    rw.msgs[1].len = 7;
    rw.msgs[1].buf = (char *) &buf[2];

    if (ioctl(i2c_fd, I2C_RDWR, &rw) < 0) {
        perror("Failed to read from SDP810");
        return -1;
    }

    if (crc8(buf, 3) != buf[5]) {
        fprintf(stderr, "CRC error\n");
        return -1;
    }

    return 0;
}

void cleanup(int i2c_fd, gpio_handle_t gpio_handle) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (gpio_handle >= 0) {
        gpiod_handle_release(gpio_handle);
    }
}

int main() {
    int i2c_fd, ret;
    gpio_handle_t gpio_handle;
    unsigned char buf[9];
    struct timespec ts = {1, 0};

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP810_ADDR << 1) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }

    if ((gpio_handle = gpiod_chip_open_named_global("gpiochip0")) < 0) {
        perror("Failed to open gpiochip0");
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_dt(gpio_handle, SDA_GPIO, GPIOD_LINE_REQUEST_INPUT, "SDA");
    gpiod_line_request_dt(gpio_handle, SCL_GPIO, GPIOD_LINE_REQUEST_INPUT, "SCL");

    while (1) {
        gpiod_line_get_value_async(gpio_handle, SDA_GPIO, NULL);
        gpiod_line_get_value_async(gpio_handle, SCL_GPIO, NULL);
        nanosleep(&ts, NULL);

        if (read_sdp810(i2c_fd, buf) < 0) {
            continue;
        }

        float pressure = (buf[1] | (buf[2] << 8)) * buf[4] / 100.0;
        float temperature = (buf[3] | (buf[4] << 8)) * buf[6] / 100.0;

        printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", pressure, temperature);
    }

    cleanup(i2c_fd, gpio_handle);
    return 0;
}

