    rw.msgs[0].buf = (char *) &buf[0];
    rw.msgs[1].addr = SDP810_ADDR << 1;
    rw.msgs[1].flags = I2C_M_RD;
    rw.msgs[1].len = 7;
    rw.msgs[1].buf = (char *) &buf[2];

    if (ioctl(i2c_fd, I2C_RDWR, &rw) < 0) {
        perror("Failed to read from SDP810");
        return -1;
    }

    if (crc8(buf, 3) != buf[5]) {
        fprintf(stderr, "CRC error\n");
        return -1;
    }

    return 0;
}

void cleanup(int i2c_fd, gpio_handle_t gpio_handle) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (gpio_handle >= 0) {
        gpiod_handle_release(gpio_handle);
    }
}

int main() {
    int i2c_fd, ret;
    gpio_handle_t gpio_handle;
    unsigned char buf[9];
    struct timespec ts = {1, 0};

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP810_ADDR << 1) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }

    if ((gpio_handle = gpiod_chip_open_named_global("gpiochip0")) < 0) {
        perror("Failed to open gpiochip0");
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_dt(gpio_handle, SDA_GPIO, GPIOD_LINE_REQUEST_INPUT, "SDA");
    gpiod_line_request_dt(gpio_handle, SCL_GPIO, GPIOD_LINE_REQUEST_INPUT, "SCL");

    while (1) {
        gpiod_line_get_value_async(gpio_handle, SDA_GPIO, NULL);
        gpiod_line_get_value_async(gpio_handle, SCL_GPIO, NULL);
        nanosleep(&ts, NULL);

        if (read_sdp810(i2c_fd, buf) < 0) {
            continue;
        }

        float pressure = (buf[1] | (buf[2] << 8)) * buf[4] / 100.0;
        float temperature = (buf[3] | (buf[4] << 8)) * buf[6] / 100.0;

        printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", pressure, temperature);
    }

    cleanup(i2c_fd, gpio_handle);
    return 0;
}
