#define SCL_GPIO 3
#define I2C_ADDR 0x40
#define READ_CMD 0xAC
#define MEAS_MODE 0x20

static int i2c_file;
static gpio_handle_t sda_gpio_handle, scl_gpio_handle;

int init_gpio(void) {
    int ret;

    ret = gpiod_chip_open_byname("gpiochip0");
    if (ret < 0) {
        perror("Failed to open gpiochip0");
        return ret;
    }

    ret = gpiod_get_index_byname(ret, "GPIO" SDA_GPIO);
    if (ret < 0) {
        perror("Failed to get SDA GPIO index");
        gpiod_chip_close(ret);
        return ret;
    }

    ret = gpiod_get_index_byname(ret, "GPIO" SCL_GPIO);
    if (ret < 0) {
        perror("Failed to get SCL GPIO index");
        gpiod_chip_close(ret);
        return ret;
    }

    ret = gpiod_direction_output_raw(sda_gpio_handle, 1);
    if (ret < 0) {
        perror("Failed to set SDA GPIO direction");
        gpiod_chip_close(ret);
        return ret;
    }

    ret = gpiod_direction_output_raw(scl_gpio_handle, 1);
    if (ret < 0) {
        perror("Failed to set SCL GPIO direction");
        gpiod_chip_close(ret);
        return ret;
    }

    return 0;
}

int i2c_init(void) {
    char filename[32];
    int ret;

    snprintf(filename, sizeof(filename), "/dev/i2c-%d", I2C_BUS);
    i2c_file = open(filename, O_RDWR);
    if (i2c_file < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_file, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire I2C bus address");
        close(i2c_file);
        return -1;
    }

    return 0;
}

int i2c_read(uint8_t *buf, size_t len) {
    int ret;

    ret = ioctl(i2c_file, I2C_RDWR, (char *)&struct i2c_rdwr_ioctl_data {
        .msgs = (struct i2c_msg[]) {
            {
                .addr = I2C_ADDR,
                .flags = 0,
                .len = 1,
                .buf = &READ_CMD,
            },
            {
                .addr = I2C_ADDR,
                .flags = I2C_M_RD,
                .len = len,
                .buf = buf,
            },
        }
    });

    if (ret < 0) {
        perror("Failed to read from I2C device");
        return -1;
    }

    return 0;
}

void i2c_close(void) {
    if (i2c_file >= 0) {
        ioctl(i2c_file, I2C_CLAIM_FAILURE, I2C_SLAVE);
        close(i2c_file);
    }
}

void gpio_cleanup(void) {
    gpiod_set_value_cansleep(sda_gpio_handle, 1);
    gpiod_set_value_cansleep(scl_gpio_handle, 1);
    gpiod_chip_close(sda_gpio_handle);
    gpiod_chip_close(scl_gpio_handle);
}

void sigint_handler(int signum) {
    printf("Received SIGINT or SIGTERM, exiting gracefully...\n");
    gpio_cleanup();
    i2c_close();
    exit(0);
}

int main(void) {
    uint8_t buf[2];
    struct timespec ts = { .tv_sec = 5, .tv_nsec = 0 };
    int ret;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    ret = init_gpio();
    if (ret < 0) {
        return ret;
    }

    ret = i2c_init();
    if (ret < 0) {
        gpio_cleanup();
        return ret;
    }

    gpiod_set_value_cansleep(sda_gpio_handle, 0);
    gpiod_set_value_cansleep(scl_gpio_handle, 0);
    usleep(40);
    gpiod_set_value_cansleep(sda_gpio_handle, 1);
    gpiod_set_value_cansleep(scl_gpio_handle, 1);
    usleep(40);

    ret = i2c_read(buf, 2);
    if (ret < 0) {
        gpio_cleanup();
        i2c_close();
        return ret;
    }

    printf("Temperature: %.1f°C\n", (buf[0] << 8 | buf[1]) / 16.0);

    while (1) {
        nanosleep(&ts, NULL);
        ret = i2c_read(buf, 2);
        if (ret < 0) {
            continue;
        }

        printf("Temperature: %.1f°C\n", (buf[0] << 8 | buf[1]) / 16.0);
    }

    gpio_cleanup();
    i2c_close();
    return 0;
}

