void i2c_error_handler(const char *msg) {
    perror(msg);
    if (i2c_fd >= 0) close(i2c_fd);
    exit(EXIT_FAILURE);
}

void gpio_error_handler(const char *msg) {
    fprintf(stderr, "%s\n", msg);
    if (i2c_fd >= 0) close(i2c_fd);
    exit(EXIT_FAILURE);
}

void sigint_handler(int signum) {
    gpiod_line_set_value(gpio_line_data.consumer, gpio_line_data.number, 0);
    gpiod_line_release(gpio_line_data.consumer, gpio_line_data.number);
    close(i2c_fd);
    gpiod_chip_unregister_line(gpio_chip_name, gpio_line_data.number);
    pthread_exit(NULL);
}

void sigterm_handler(int signum) {
    gpiod_line_set_value(gpio_line_data.consumer, gpio_line_data.number, 0);
    gpiod_line_release(gpio_line_data.consumer, gpio_line_data.number);
    close(i2c_fd);
    gpiod_chip_unregister_line(gpio_chip_name, gpio_line_data.number);
    gpiod_chip_shutdown(gpio_chip_name);
    pthread_exit(NULL);
}

