    if (!gpio_chip) gpio_error_handler("Failed to get GPIO chip");
    gpio_line_data.number = gpiod_chip_get_line(gpio_chip, 17);
    if (!gpio_line_data.number) gpio_error_handler("Failed to get GPIO line");
    ret = gpiod_line_request_dt(gpio_chip, gpio_line_data.number, &gpio_request_data);
    if (ret < 0) gpio_error_handler("Failed to request GPIO line");
    gpio_line_data.consumer = gpiod_get_consumer_byname("baro_sensor_trigger");
    if (!gpio_line_data.consumer) gpio_error_handler("Failed to get GPIO consumer");
    gpiod_line_set_value(gpio_line_data.consumer, gpio_line_data.number, 1);
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Open I2C device
