        // Check for default values or negative return value
        if (memcmp(meas_data, (uint8_t[]){0x00, 0x00, 0x00, 0x00, 0x00, 0x00}, 6) == 0 || meas_data[0] < 0) {
            fprintf(stderr, "Sensor not found or absent\n");
            continue;
        }

        // Parse and print data
