        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S", time_info);
        printf("%s - Temperature: %.2f°C, Pressure: %.2f Pa\n", timestamp_str, meas_data[1] * 256.0 + meas_data[2] / 16.0, meas_data[3] * 256.0 + meas_data[4] / 16.0);

        // Sleep
        nanosleep(&sleep_duration, NULL);
    }

    // Cleanup
    gpiod_line_release(gpio_line_data.consumer, gpio_line_data.number);
    gpiod_chip_unregister_line(gpio_chip_name, gpio_line_data.number);
    close(i2c_fd);
    gpiod_chip_shutdown(gpio_chip_name);

    return 0;
}
