code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <gpiod.h>

#define I2C_BUS 1
#define SDA_GPIO 2
#define SCL_GPIO 3
#define I2C_ADDR 0x48
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0x00

struct gpiod_line_request *sdap_req, *sclp_req;
struct i2c_rdwr_ioctl_data i2c_data;
struct i2c_msg i2c_msgs[3];

void log_data(const char *tag, uint16_t pressure, uint16_t temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    FILE *file;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    file = fopen("pressure_log.txt", "a");
    if (file) {
        fprintf(file, "%s,%d,%d\n", timestamp, pressure, temperature);
        fclose(file);
    }
}

uint8_t crc8(uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;

    for (size_t i = 0; i < len; ++i) {
        for (int bit = 8; bit > 0; --bit) {
            crc = (crc >> 1) ^ (crc & 0x01 ? CRC_POLYNOMIAL : 0);
            crc &= 0xFF;
            crc ^= data[i] << (7 - bit);
        }
    }

    return crc;
}

int read_sensor(uint8_t *data) {
    int ret;

    i2c_msgs[0].addr = I2C_ADDR;
    i2c_msgs[0].flags = 0;
    i2c_msgs[0].len = 1;
    i2c_msgs[0].buf = (uint8_t*)&data[0];

    i2c_msgs[1].addr = I2C_ADDR;
    i2c_msgs[1].flags = I2C_M_RD;
    i2c_msgs[1].len = 2;
    i2c_msgs[1].buf = &data[1];

    i2c_msgs[2].addr = I2C_ADDR;
    i2c_msgs[2].flags = I2C_M_RD;
    i2c_msgs[2].len = 2;
    i2c_msgs[2].buf = &data[3];

    i2c_data.wr_msgs = &i2c_msgs[0];
    i2c_data.n_msgs = 1;
    i2c_data.rd_msgs = &i2c_msgs[1];
    i2c_data.n_msgs = 2;

    ret = ioctl(i2c_fd, I2C_RDWR, &i2c_data);
    if (ret < 0) {
        perror("I2C read error");
        return -1;
    }

    if (crc8(data, 9) != data[8]) {
        fprintf(stderr, "CRC error\n");
        return -1;
    }

    return 0;
}

int main() {
    int i2c_fd, ret;
    uint8_t data[9];

    gpiod_line_request_array_init(&sdap_req, 1);
    gpiod_line_request_array_init(&sclp_req, 1);

    if (gpiod_chip_open_byname("gpiochip0") < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_direction_output(sdap_req, SDA_GPIO, GPIOD_LINE_ACTIVE_LOW);
    if (ret < 0) {
        perror("Failed to set SDA GPIO direction");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_direction_output(sclp_req, SCL_GPIO, GPIOD_LINE_ACTIVE_HIGH);
    if (ret < 0) {
        perror("Failed to set SCL GPIO direction");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_enable(sdap_req, GPIOD_LINE_REQUEST_ENABLE_LOW) < 0 ||
        gpiod_line_request_enable(sclp_req, GPIOD_LINE_REQUEST_ENABLE_HIGH) < 0) {
        perror("Failed to enable GPIO lines");
        exit(EXIT_FAILURE);
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_array_free(sdap_req);
    gpiod_line_request_array_free(sclp_req);

    while (1) {
        gpiod_line_set_value(sdap_req, 1);
        usleep(45 * 1000);
        gpiod_line_set_value(sdap_req, 0);

        if (read_sensor(data) == 0) {
            log_data("pressure", ntohs(*(uint16_t*)&data[1]), ntohs(*(uint16_t*)&data[5]));
        }
    }

    close(i2c_fd);

    gpiod_line_request_array_free(sdap_req);
    gpiod_line_request_array_free(sclp_req);
    gpiod_chip_close(gpiod_chip_get_fd());

    return 0;
}

