    if (ret != len + 1) {
        perror("i2c_write_read: write");
        return -1;
    }

    ret = read(fd, buf, len);
    if (ret != len) {
        perror("i2c_write_read: read");
        return -1;
    }

    return 0;
}

uint8_t crc8(uint8_t *data, size_t len) {
    uint8_t crc = 0;

    for (size_t i = 0; i < len; ++i) {
        for (int j = 8; j > 0; --j) {
            crc = (crc << 1) ^ crc_table[(crc >> 7) ^ data[i]];
        }
    }

    return crc;
}

void log_pressure(const char *filename, uint16_t pressure) {
    FILE *file;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    if (access(filename, F_OK) == -1) {
        file = fopen(filename, "w");
        fprintf(file, "timestamp,pressure\n");
        fclose(file);
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    file = fopen(filename, "a");
    fprintf(file, "%s,%d\n", timestamp, pressure);
    fclose(file);
}

int main() {
    int i2c_fd, gpio_fd;
    gpiod_line_request_flags_t flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_RISING;
    struct i2c_dev *i2c_dev;
    uint8_t data[3];
    uint16_t pressure;

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR_LOW) < 0) {
        perror("ioctl(I2C_SLAVE)");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    gpio_fd = gpiod_open_name("gpiochip0", GPIO_TRIGGER);
    if (gpio_fd < 0) {
        perror("gpiod_open_name");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request(gpio_fd, GPIO_TRIGGER, flags) < 0) {
        perror("gpiod_line_request");
        close(gpio_fd);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    gpiod_line_get_value_cansleep(gpio_fd, GPIO_TRIGGER);

    while (1) {
        if (i2c_write_read(i2c_fd, 0x00, data, 3) == -1) {
            perror("i2c_write_read");
            gpiod_line_release(gpio_fd, GPIO_TRIGGER);
            close(gpio_fd);
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        if (data[2] != crc8(data, 2)) {
            printf("CRC error\n");
            continue;
        }

        pressure = (data[0] << 8) | data[1];
        log_pressure("airflow_log.csv", pressure);
        printf("Pressure: %d Pa\n", pressure);

        gpiod_line_get_value_cansleep(gpio_fd, GPIO_TRIGGER);
        usleep(8000);
    }

    gpiod_line_release(gpio_fd, GPIO_TRIGGER);
    close(gpio_fd);
    close(i2c_fd);

    return 0;
}
```

This code initializes the I2C bus, opens the GPIO line for the trigger, sets up the trigger, and reads the pressure data from the sensor. It logs the pressure to a file named `airflow_log.csv` with a timestamp and handles errors during I2C communication and GPIO access. The program will continue to run indefinitely, waiting for the trigger signal and reading the pressure data.

