#define I2C_BUS 1
#define MLX90821_ADDR 0x5A
#define SAFE_TIRE_MIN 200
#define SAFE_TIRE_MAX 250
#define CSV_FILE "pressure_log.csv"

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int nlines,
                                const char *const *consumer,
                                unsigned int flags) {
    return gpiod_chip_request_lines(chip, nlines, consumer, flags);
}

static void i2c_read(int file, uint8_t *buf, size_t len) {
    ssize_t bytes_read;

    if ((bytes_read = read(file, buf, len)) < 0) {
        perror("Error reading from I2C device");
        if (errno == EAGAIN) {
            usleep(100000); // Retry after 100ms
            i2c_read(file, buf, len);
        } else {
            exit(EXIT_FAILURE);
        }
    }
}

static void log_pressure(const char *filename, uint16_t pressure) {
    FILE *file = fopen(filename, "a");
    time_t now = time(NULL);
    char timestamp[20];
    struct tm *tm_now = localtime(&now);

    if (!file) {
        perror("Error opening log file");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);
    fprintf(file, "%s,%d\n", timestamp, pressure);
    fflush(file);

    if (file && fseek(file, 0, SEEK_SET) != 0) {
        perror("Error seeking to the beginning of the log file");
    }

    if (fgetc(file) == EOF) {
        fprintf(file, "timestamp,pressure_kPa\n");
    }

    fclose(file);
}

static void signal_handler(int sig) {
    gpiod_chip_release(chip);
    remove(CSV_FILE);
    exit(EXIT_SUCCESS);
}

int main() {
    int i2c_file;
    struct gpiod_chip *chip;
    uint8_t buf[2];
    uint16_t pressure;
    struct stat file_stat;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if ((i2c_file = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Error opening I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_file, I2C_SLAVE, MLX90821_ADDR) < 0) {
        perror("Error setting I2C slave address");
        exit(EXIT_FAILURE);
    }

    if ((chip = gpiod_chip_open_by_name("gpiochip0")) == NULL) {
        perror("Error opening GPIO chip");
        exit(EXIT_FAILURE);
    }

    if (fstat(fileno(stderr), &file_stat) < 0) {
        perror("Error getting file status");
        exit(EXIT_FAILURE);
    }

    if (file_stat.st_size == 0) {
        log_pressure(CSV_FILE, 0);
    }

    while (1) {
        i2c_read(i2c_file, buf, 2);
        pressure = (buf[0] << 8) | buf[1];

        if (pressure < SAFE_TIRE_MIN || pressure > SAFE_TIRE_MAX) {
            fprintf(stderr, "Warning: Measured pressure outside safe tire range: %d kPa\n", pressure);
        }

        log_pressure(CSV_FILE, pressure);
        sleep(1);
    }

    gpiod_chip_release(chip);
    close(i2c_file);

    return EXIT_SUCCESS;
}

