#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define TEMP_ADDR 0x27
#define HUM_ADDR 0x28

#define BUFFER_SIZE 2

static const char *log_file = "environmental_data.log";
static const int log_max_size = 1048576; // 1 MB

int i2c_read(int fd, uint8_t addr, uint8_t reg, uint8_t *buf, size_t len) {
    char wr_buf[2] = {reg, 0};
    char rd_buf[len];
    int ret;

    ret = write(fd, wr_buf, 2);
    if (ret != 2) {
        perror("Write error");
        return -1;
    }

    ret = read(fd, rd_buf, len);
    if (ret != len) {
        perror("Read error");
        return -1;
    }

    for (size_t i = 0; i < len; ++i) {
        buf[i] = rd_buf[i];
    }

    return 0;
}

int i2c_write(int fd, uint8_t addr, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    int ret;

    ret = write(fd, buf, 2);
    if (ret != 2) {
        perror("Write error");
        return -1;
    }

    return 0;
}

int main() {
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TEMP_ADDR) < 0) {
        perror("Failed to acquire address 0x%x", TEMP_ADDR);
        exit(EXIT_FAILURE);
    }

    uint8_t temp_buf[BUFFER_SIZE];
    uint8_t hum_buf[BUFFER_SIZE];

    while (1) {
        if (i2c_read(i2c_fd, TEMP_ADDR, 0x00, temp_buf, BUFFER_SIZE) < 0) {
            perror("Failed to read temperature");
            continue;
        }

        if (i2c_read(i2c_fd, HUM_ADDR, 0x00, hum_buf, BUFFER_SIZE) < 0) {
            perror("Failed to read humidity");
            continue;
        }

        if ((temp_buf[0] & 0x80) || (hum_buf[0] & 0x80)) {
            fprintf(stderr, "Invalid data received\n");
            continue;
        }

        time_t now = time(NULL);
        struct tm tm = *localtime(&now);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

        FILE *log_file_ptr = fopen(log_file, "a");
        if (log_file_ptr == NULL) {
            perror("Failed to open log file");
            continue;
        }

        fprintf(log_file_ptr, "%s,Temperature: %d.%dC, Humidity: %d.%d%%\n", timestamp,
                (int)temp_buf[1] << 8 | temp_buf[0],
                (int)hum_buf[1] << 8 | hum_buf[0],
                (int)temp_buf[3] << 8 | temp_buf[2],
                (int)hum_buf[3] << 8 | hum_buf[4]);
        fclose(log_file_ptr);

        if (ftell(log_file_ptr) > log_max_size) {
            remove(log_file);
        }

        sleep(5);
    }

    close(i2c_fd);

    return 0;
}

