#include <sys/ioctl.h>
#include <time.h>
#include <errno.h>
#include <linux/types.h>
#include <gpiod.h>

#define SENT_SYNC_WIDTH 56
#define SENT_DATA_WIDTH_MIN 12
#define SENT_DATA_WIDTH_MAX 271
#define SENT_TICK_PER_US (1000000 / 3000)

struct gpiod_line_request_data {
    gpiod_line_request_linenum_data_v1 request_linenum;
    gpiod_line_request_flags_data_v1 request_flags;
};

int main() {
    int fd, ret;
    gpiod_line_handle_v1 *line;
    struct timespec ts;
    uint32_t sync_width, data_width[4], checksum;
    FILE *log_file;
    char log_filename[] = "pressure_log.txt";

    fd = gpiod_library_open();
    if (fd < 0) {
        perror("gpiod_library_open");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(fd, "gpiochip0", "gpio4");
    if (!line) {
        perror("gpiod_chip_get_line");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_direction_output(line, GPIOD_LINE_ACTIVE_LOW);
    if (ret < 0) {
        perror("gpiod_line_request_direction_output");
        exit(EXIT_FAILURE);
    }

    log_file = fopen(log_filename, "w");
    if (!log_file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    while (1) {
        gpiod_line_set_value(line, 1);
        usleep(SENT_SYNC_WIDTH * SENT_TICK_PER_US);
        gpiod_line_set_value(line, 0);

        ts.tv_sec = 0;
        ts.tv_nsec = SENT_SYNC_WIDTH * SENT_TICK_PER_US * 1000;
        nanosleep(&ts, NULL);

        gpiod_line_set_value(line, 1);
        clock_gettime(CLOCK_MONOTONIC, &ts);

        for (int i = 0; i < 4; i++) {
            ts.tv_sec = 0;
            ts.tv_nsec = 0;
            ret = gpiod_line_get_value_async(line, &sync_width, &ts);
            if (ret < 0) {
                perror("gpiod_line_get_value_async");
                continue;
            }

            if (sync_width < SENT_DATA_WIDTH_MIN || sync_width > SENT_DATA_WIDTH_MAX) {
                fprintf(stderr, "Invalid data width: %d ticks\n", sync_width);
                continue;
            }

            data_width[i] = sync_width - SENT_SYNC_WIDTH;
            usleep((data_width[i] + SENT_SYNC_WIDTH) * SENT_TICK_PER_US);
        }

        usleep((SENT_SYNC_WIDTH + data_width[3] + 1) * SENT_TICK_PER_US);
        gpiod_line_get_value_async(line, &checksum, NULL);

        ret = gpiod_line_get_value_async(line, &sync_width, NULL);
        if (ret < 0) {
            perror("gpiod_line_get_value_async");
            continue;
        }

        if (sync_width != SENT_SYNC_WIDTH) {
            fprintf(stderr, "Checksum error: %d ticks\n", sync_width);
            continue;
        }

        gpiod_line_get_value_async(line, &sync_width, NULL);
        if (ret < 0) {
            perror("gpiod_line_get_value_async");
            continue;
        }

        if (sync_width != SENT_SYNC_WIDTH) {
            fprintf(stderr, "Checksum error: %d ticks\n", sync_width);
            continue;
        }

        pressure_t pressure = (data_width[0] << 4) | (data_width[1] >> 4) |
                              ((data_width[1] & 0x0F) << 8) | (data_width[2] << 12);
        pressure /= 16;

        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, Pressure: %.2f Pa\n",
                localtime(&ts.tv_sec)->tm_year + 1900,
                localtime(&ts.tv_sec)->tm_mon + 1,
                localtime(&ts.tv_sec)->tm_mday,
                localtime(&ts.tv_sec)->tm_hour,
                localtime(&ts.tv_sec)->tm_min,
                localtime(&ts.tv_sec)->tm_sec,
                pressure);
    }

    fclose(log_file);
    gpiod_line_release(line);
    gpiod_library_close(fd);

    return 0;
}
```

This code initializes the GPIO line as an output, sends a synchronization pulse, and then reads the data nibbles and checksum nibble. It logs the pressure readings to a file named `pressure_log.txt` in the specified format. The program handles errors related to libgpiod, timeouts, and out-of-range pulse widths by printing an error message to stderr and continuing with the next iteration.

To detect SIGINT or SIGTERM, you can use signal handlers or the `pthread_cancel` function, but that's beyond the scope of this example. You can find more information on those topics in the libgpiod documentation and the pthread man page.

