#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define SHT40_CMD_MEASURE_RH_TEMP 0x24
#define SHT40_CMD_RESET 0x1E
#define SHT40_CRC_POLYNOMIAL 0x31
#define SHT40_CRC_INIT 0xFF

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int nlines,
                                const char *const names[], unsigned int flags)
{
    return gpiod_chip_get_lines_request_array(chip, nlines, names, flags);
}

static int sht40_read(int fd, uint8_t *buf, size_t len)
{
    int ret;
    ret = read(fd, buf, len);
    if (ret < 0) {
        perror("read");
        return -1;
    }
    return ret;
}

static int sht40_write(int fd, const uint8_t *buf, size_t len)
{
    int ret;
    ret = write(fd, buf, len);
    if (ret < 0) {
        perror("write");
        return -1;
    }
    return ret;
}

static uint8_t sht40_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = SHT40_CRC_INIT;
    for (size_t i = 0; i < len; ++i) {
        for (uint8_t j = 8; j > 0; --j) {
            crc = (crc >> 1) ^ (crc & 0x01 ? SHT40_CRC_POLYNOMIAL : 0);
            crc = (crc & 0x00FF) << 8 | (data[i] & 0x00FF);
        }
    }
    return crc;
}

static int sht40_measure(int i2c_fd, uint8_t *buf)
{
    int ret;

    ret = sht40_write(i2c_fd, &SHT40_CMD_MEASURE_RH_TEMP, 1);
    if (ret < 0) {
        return -1;
    }

    usleep(8500); // Wait at least 8.5ms for conversion

    ret = sht40_read(i2c_fd, buf, 6);
    if (ret < 0) {
        return -1;
    }

    if (sht40_crc8(buf, 4) != buf[4] || sht40_crc8(buf + 2, 2) != buf[5]) {
        fprintf(stderr, "CRC error\n");
        return -1;
    }

    return 0;
}

static void sigint_handler(int signum)
{
    gpiod_line_release_request(gpiod_chip_get_request_byname(gpiod_chip_get_bylabel("gpiochip0"), "GPIO_GPIO"));
    close(i2c_fd);
    gpiod_chip_shutdown(gpiod_chip_get_bylabel("gpiochip0"));
    fclose(log_file);
    exit(0);
}

int main(void)
{
    int i2c_fd, ret;
    struct gpiod_chip *gpio_chip;
    struct timespec ts;
    uint8_t buf[6];
    FILE *log_file;

    gpio_chip = gpiod_chip_get_bylabel("gpiochip0");
    if (!gpio_chip) {
        perror("gpiochip0 not found");
        return 1;
    }

    ret = gpiod_chip_open_sync(gpio_chip, GPIOD_OPEN_FLAG_READWRITE);
    if (ret < 0) {
        perror("gpiochip open");
        return 1;
    }

    ret = gpiod_line_request_array(gpio_chip, 1, (const char*[]){"GPIO_GPIO"}, GPIOD_LINE_REQUEST_INPUT);
    if (ret < 0) {
        perror("gpio line request");
        goto cleanup_gpio;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("i2c open");
        goto cleanup_gpio;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        perror("i2c slave address");
        goto cleanup_i2c;
    }

    log_file = fopen("environmental_data.txt", "a");
    if (!log_file) {
        perror("log file open");
        goto cleanup_i2c;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        ret = sht40_measure(i2c_fd, buf);
        if (ret < 0) {
            fprintf(stderr, "Measurement error\n");
            continue;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld %d.%d %d.%d %d.%d\n",
                ts.tv_sec, ts.tv_nsec,
                (int)buf[0], (int)(buf[0] >> 8),
                (int)buf[1], (int)(buf[1] >> 8),
                (int)buf[2], (int)(buf[2] >> 8));
        fflush(log_file);

        usleep(5000000); // Wait 5 seconds before the next measurement
    }

cleanup_i2c:
    close(i2c_fd);
cleanup_gpio:
    gpiod_line_release_request(gpiod_chip_get_request_byname(gpio_chip, "GPIO_GPIO"));
    gpiod_chip_shutdown(gpio_chip);

    return 0;
}

