#define BUFFER_SIZE 100
#define I2C_BUS 1

struct i2c_data {
    int fd;
    gpiod_line_request_lines_data lines;
};

struct temperature_buffer {
    float buffer[BUFFER_SIZE];
    size_t head;
    size_t tail;
