int read_shtc3(int fd, uint8_t *data) {
    int ret;
    uint8_t cmd[] = {0x24, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    uint8_t res[8];

    cmd[1] = (1 << 6) | (1 << 5); // Set measurement mode

    ret = write(fd, cmd, 8);
    if (ret != 8) {
        perror("I2C write error");
        return -1;
    }

    usleep(12400); // Wait for conversion and sampling

    ret = read(fd, res, 8);
    if (ret != 8) {
        perror("I2C read error");
        return -1;
    }

    // Calculate CRC
    uint16_t crc = 0xFFFF;
    for (int i = 0; i < 6; ++i) {
        crc = crc_table[(crc ^ res[i]) & 0xFF] ^ (crc >> 8);
    }

    if (crc != ((res[6] << 8) | res[7])) {
        fprintf(stderr, "CRC failure\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    float temp = (res[2] << 8 | res[3]) / 16.0;
    float rh = (res[4] << 8 | res[5]) / 16.0;

    if (temp < -40.0 || temp > 125.0 || rh < 0.0 || rh > 100.0) {
        fprintf(stderr, "Out-of-range value\n");
        return -1;
    }

    return 0;
}

int main() {
    int i2c_fd, gpio_fd;
    struct gpiod_line_request line_req[2];
    struct timespec ts;
    char log_file[32];
    FILE *log_fp;

    // Initialize I2C and GPIO
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("I2C open error");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SHTC3_ADDR) < 0) {
        perror("I2C slave address error");
        close(i2c_fd);
        return 1;
    }

    gpio_fd = gpiod_open_array_with_label(NULL, "gpio", 0, O_RDWR | O_NONBLOCK);
    if (gpio_fd < 0) {
        perror("GPIO open error");
        close(i2c_fd);
        return 1;
    }

    gpiod_line_request_set_function(line_req, 0, GPIOD_LINE_REQUEST_INPUT);
    gpiod_line_request_set_function(line_req + 1, 1, GPIOD_LINE_REQUEST_OUTPUT);
    gpiod_line_request_set_active_level(line_req, 0, GPIOD_LINE_ACTIVE_LOW);
    gpiod_line_request_set_active_level(line_req + 1, 1, GPIOD_LINE_ACTIVE_HIGH);

    if (gpiod_line_request_array(gpio_fd, line_req, 2) < 0) {
        perror("GPIO line request error");
        close(i2c_fd);
        close(gpio_fd);
        return 1;
    }

    gpiod_line_set_value(gpio_fd, 1, 1); // Set SCL and SDA to high

    // Open log file
    snprintf(log_file, sizeof(log_file), "shtc3_environment.log");
    log_fp = fopen(log_file, "w");
    if (!log_fp) {
        perror("Log file open error");
        close(i2c_fd);
        close(gpio_fd);
        return 1;
    }

    while (1) {
        // Set SDA and SCL to low
        gpiod_line_set_value(gpio_fd, SDA_GPIO, 0);
        gpiod_line_set_value(gpio_fd, SCL_GPIO, 0);
        usleep(4);

        // Set SCL to high
        gpiod_line_set_value(gpio_fd, SCL_GPIO, 1);
        usleep(4);

        // Set SDA to high
        gpiod_line_set_value(gpio_fd, SDA_GPIO, 1);
        usleep(4);

        // Set SDA to low
        gpiod_line_set_value(gpio_fd, SDA_GPIO, 0);
        usleep(4);

        // Set SCL to low
        gpiod_line_set_value(gpio_fd, SCL_GPIO, 0);
        usleep(4);

        if (read_shtc3(i2c_fd, NULL) < 0) {
            continue;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f°C,%.2f%%\n",
                ts.tv_year, ts.tv_mon, ts.tv_mday, ts.tv_hour, ts.tv_min, ts.tv_sec,
                temp, rh);
        fprintf(stdout, "%.2f°C, %.2f%%\n", temp, rh);

        ts.tv_nsec += 5 * 1e9;
        if (ts.tv_nsec >= 1e9) {
            ts.tv_sec++;
            ts.tv_nsec -= 1e9;
        }
        usleep((ts.tv_sec - time(NULL)) * 1e6 + ts.tv_nsec / 1e3);
    }

    // Cleanup
    fclose(log_fp);
    gpiod_line_release_array(gpio_fd, line_req, 2);
    close(gpio_fd);
    close(i2c_fd);

    return 0;
}
