#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/stat.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <libgpiod.h>

#define I2C_BUS 1  // Change this to the I2C bus number your sensor is connected to
#define SI7202_ADDR 0x1E  // Change this to the address of your Si7202 sensor

#define TEMP_REG 0x00
#define SPEED_REG 0x01

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int lines,
                                const char *const labels, unsigned int flags)
{
    return gpiod_chip_get_lines_request_array(chip, lines, labels, flags);
}

int main() {
    int i2c_fd, ret;
    char filename[256] = "mag_temp_log.csv";
    FILE *file;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg i2c_msgs[2];
    char buf[2];
    double speed, temp;
    time_t now;
    struct tm *tm;
    struct gpiod_chip *chip;
    struct gpiod_line_request *request;

    // Initialize GPIO
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    request = gpiod_chip_get_line_request(chip, "gpio-shutdown");
    if (!request) {
        perror("Failed to get GPIO shutdown line request");
        gpiod_chip_put(chip);
        return 1;
    }

    ret = gpiod_line_request_direction_output(request, GPIOD_LINE_ACTIVE_LOW);
    if (ret < 0) {
        perror("Failed to set GPIO shutdown line direction");
        gpiod_line_request_put(request);
        gpiod_chip_put(chip);
        return 1;
    }

    gpiod_line_request_enable(request);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        gpiod_line_request_put(request);
        gpiod_chip_put(chip);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI7202_ADDR) < 0) {
        perror("Failed to acquire I2C bus");
        close(i2c_fd);
        gpiod_line_request_put(request);
        gpiod_chip_put(chip);
        return 1;
    }

    // Prepare I2C read messages
    i2c_msgs[0].addr = SI7202_ADDR;
    i2c_msgs[0].flags = 0;
    i2c_msgs[0].len = 1;
    i2c_msgs[0].buf = &buf[0];
    i2c_msgs[1].addr = SI7202_ADDR;
    i2c_msgs[1].flags = I2C_M_RD;
    i2c_msgs[1].len = 1;
    i2c_msgs[1].buf = &buf[1];

    // Create or open log file
    file = fopen(filename, "a");
    if (!file) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpiod_line_request_put(request);
        gpiod_chip_put(chip);
        return 1;
    }

    // Write header if file is empty
    if (ftell(file) == 0) {
        fprintf(file, "Time,Temperature,Speed\n");
    }

    // Main loop
    while (1) {
        i2c_data.wr_msgs = &i2c_msgs[0];
        i2c_data.rd_msgs = &i2c_msgs[1];
        i2c_data.nmsgs = 2;

        ret = ioctl(i2c_fd, I2C_RDWR, &i2c_data);
        if (ret < 0) {
            perror("Failed to read from I2C device");
            temp = NAN;
            speed = NAN;
        } else {
            temp = (double)buf[0] * 256.0 / 65535 * 100 - 40;
            speed = (double)buf[1] * 256.0 / 65535 * 1000;
        }

        now = time(NULL);
        tm = localtime(&now);
        fprintf(file, "%d-%02d-%02d %02d:%02d:%02d,%f,%f\n",
                tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
                tm->tm_hour, tm->tm_min, tm->tm_sec, temp, speed);

        usleep(1000000);  // Sleep for 1 second
    }

    // Cleanup
    fclose(file);
    close(i2c_fd);
    gpiod_line_request_put(request);
    gpiod_chip_put(chip);

    return 0;
}

