To handle SIGINT (Ctrl+C), you can use a signal handler function and set it up with `signal()` or `sigaction()`. However, since this code already exits cleanly when the program is terminated, a signal handler might not be necessary in this case.

code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <sys/time.h>
#include <signal.h>
#include <errno.h>
#include <libgpiod.h>

#define TMP117_ADDR 0x48
#define TMP117_REG_CONFIG 0x00
#define TMP117_REG_TEMP_MSB 0x01
#define TMP117_REG_TEMP_LSB 0x02
#define TMP117_REG_TEMP_LSB_2 0x03

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int lines,
                                unsigned int flags, const char *label)
{
    return gpiod_chip_get_line_request_byname(chip, label);
}

int main() {
    int i2c_file, ret;
    char filename[] = "temperature_log.txt";
    struct i2c_rdwr_ioctl_data i2c_data;
    unsigned char buf[4];
    struct timespec sleep_time = {1, 0};
    struct gpiod_chip *chip;
    struct gpiod_line_request *reset_line;
    FILE *log_file;
    time_t rawtime;
    struct tm *time_info;
    char time_str[32];
    double temperature;

    signal(SIGINT, clean_exit);

    if ((i2c_file = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if ((chip = gpiod_chip_open_byname("gpiochip0")) == NULL) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    if ((reset_line = gpiod_line_request_get(chip, "reset", GPIOD_LINE_REQUEST_DIRECTION_OUT)) == NULL) {
        perror("Failed to request GPIO line for reset");
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(reset_line, 1);
    usleep(100000);
    gpiod_line_set_value(reset_line, 0);
    usleep(100000);
    gpiod_line_set_value(reset_line, 1);
    usleep(100000);

    i2c_data.wr_buf = &TMP117_REG_CONFIG;
    i2c_data.wr_len = 1;
    i2c_data.rd_buf = buf;
    i2c_data.rd_len = 4;

    while (1) {
        ret = ioctl(i2c_file, I2C_RDWR, &i2c_data);
        if (ret < 0) {
            if (errno == ENODEV) {
                printf("I2C device not found, retrying...\n");
                continue;
            } else if (errno == EIO) {
                printf("I2C bus error, retrying...\n");
                continue;
            }
            perror("I2C read/write failed");
            exit(EXIT_FAILURE);
        }

        if (i2c_data.rd_len != 4) {
            perror("Unexpected number of bytes read");
            exit(EXIT_FAILURE);
        }

        temperature = (double)buf[1] << 8 | buf[2] << 4 | buf[3] >> 4;
        temperature /= 16.0;

        if (temperature < 0) {
            temperature *= -1;
        }

        rawtime = time(NULL);
        time_info = localtime(&rawtime);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", time_info);

        log_file = fopen(filename, "a");
        if (log_file == NULL) {
            perror("Failed to open log file");
            exit(EXIT_FAILURE);
        }

        fprintf(log_file, "%s, Temperature: %.2f C\n", time_str, temperature);
        fclose(log_file);

        nanosleep(&sleep_time, NULL);
    }

    clean_exit:
    if (log_file != NULL) {
        fclose(log_file);
    }

    if (reset_line != NULL) {
        gpiod_line_release(reset_line);
    }

    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    if (i2c_file >= 0) {
        close(i2c_file);
    }

    return 0;
}

