        fclose(log_file);
    }

    if (reset_line != NULL) {
        gpiod_line_release(reset_line);
    }

    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    if (i2c_file >= 0) {
        close(i2c_file);
    }

