int main() {
    int i2c_fd, ret;
    char i2c_dev_name[32];
    struct i2c_rdwr_ioctl_data i2c_data;
    struct timespec ts;
    struct gpiod_chip *chip;
    struct gpiod_line_request *reset_line;
    unsigned char buffer[BUFFER_SIZE];
