        slpm = (buffer[0] & SLPM_MASK) << SLPM_SHIFT;
        slpm |= (buffer[1] & 0x0F) << (SLPM_SHIFT + 12);
        temp = (buffer[2] & TEMP_MASK) << TEMP_SHIFT;
        temp |= (buffer[3] & 0x0F) << (TEMP_SHIFT + 12);

