        fclose(log_file);

        // Wait for 1 second before the next read
        ts.tv_sec = 1;
        ts.tv_nsec = 0;
        nanosleep(&ts, NULL);
    }

    // Clean up resources on SIGINT or SIGTERM
    signal(SIGINT, [](int signum) {
        printf("Received SIGINT, cleaning up...\n");
        gpiod_line_release(reset_line);
        gpiod_chip_put(chip);
        close(i2c_fd);
        fclose(log_file);
        exit(EXIT_SUCCESS);
    });

    signal(SIGTERM, [](int signum) {
        printf("Received SIGTERM, cleaning up...\n");
        gpiod_line_release(reset_line);
        gpiod_chip_put(chip);
        close(i2c_fd);
        fclose(log_file);
        exit(EXIT_SUCCESS);
    });

    return 0;
}

