This code initializes the I2C bus and the GPIO line for the reset signal, resets the sensor, and reads data from the sensor every second. It handles errors during I2C communication, attempts to re-initialize the I2C handle when necessary, and logs read errors. The program writes timestamped measurements in SLPM and °C to a file named `flow_log.txt`. It also cleans up resources on receipt of SIGINT or SIGTERM.

code:
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/time.h>
#include <time.h>
#include <libgpiod.h>

#define DHT11_DATA_PIN "gpiochip0\077"
#define DHT11_DELAY_US 1000
#define DHT11_START_US 18000
#define DHT11_BIT_LOW_US 50
#define DHT11_BIT_HIGH_US (28 * 1000)
#define DHT11_BIT_CHECKSUM_US (70 * 1000)
#define DHT11_MIN_INTERVAL_US 2000000

static gpiod_line_request_lines(struct gpiod_chip *chip, const char *request_label, unsigned int num_lines, unsigned int flags) {
    return gpiod_chip_request_lines(chip, request_label, num_lines, flags, NULL);
}

static void gpiod_line_set_value(int line, int value) {
    gpiod_line_set_value_cansleep(line, value);
}

static int gpiod_line_get_value(int line) {
    return gpiod_line_get_value_cansleep(line);
}

static void gpiod_line_put(int line) {
    gpiod_line_put_cansleep(line);
}

static void gpiod_line_release(int line) {
    gpiod_line_release(line);
}

static void sleep_us(unsigned long usec) {
    struct timespec ts;
    ts.tv_sec = usec / 1000000;
    ts.tv_nsec = (usec % 1000000) * 1000;
    nanosleep(&ts, NULL);
}

static int dht11_read(int line) {
    int bit_value = 0;
    sleep_us(DHT11_BIT_LOW_US);
    gpiod_line_set_value(line, 0);
    sleep_us(DHT11_DELAY_US);
    if (gpiod_line_get_value(line)) {
        bit_value = 1;
    }
    sleep_us(DHT11_BIT_HIGH_US - DHT11_BIT_LOW_US);
    gpiod_line_set_value(line, 1);
    return bit_value;
}

static int dht11_read_data(int line) {
    int data[5];
    int i;

    gpiod_line_set_value(line, 0);
    sleep_us(DHT11_START_US);

    for (i = 0; i < 40; i++) {
        sleep_us(DHT11_DELAY_US);
        data[i / 8] <<= 1;
        if (i > 2 && i < 38) {
            data[i / 8] |= dht11_read(line);
        }
    }

    sleep_us(DHT11_DELAY_US);
    if (dht11_read(line)) {
        data[4] |= (1 << (40 - (data[4] & 0x0f)));
    }

    if (data[4] != (data[0] + data[2] + data[3] + data[4] >> 4)) {
        return -1;
    }

    return 0;
}

int main() {
    struct gpiod_chip *chip;
    int line;
    int fd;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    char line_label[32];

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    line = gpiod_line_request_lines(chip, "dht11", 1, GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_RISING);
    if (line < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    fd = open("dht11_readings.txt", O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (fd < 0) {
        perror("Failed to open output file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    while (1) {
        gpiod_line_set_value(line, 1);
        sleep_us(DHT11_START_US);
        gpiod_line_set_value(line, 0);

        if (gpiod_line_get_value(line)) {
            sleep_us(DHT11_DELAY_US);
            if (gpiod_line_get_value(line)) {
                sleep_us(DHT11_DELAY_US);
                if (gpiod_line_get_value(line)) {
                    time(&rawtime);
                    timeinfo = localtime(&rawtime);
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
                    fprintf(fd, "%s: Success\n", timestamp);

                    int data[5];
                    if (dht11_read_data(line) >= 0) {
                        fprintf(fd, "  Humidity: %d.%d\n", data[0], data[1]);
                        fprintf(fd, "  Temperature: %d.%d\n", data[2], data[3]);
                    }
                }
            }
        }

        sleep_us(DHT11_MIN_INTERVAL_US - DHT11_START_US - 2 * DHT11_DELAY_US);

        if (gpiod_line_get_value(line)) {
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
            fprintf(fd, "%s: Timeout: Line stuck high\n", timestamp);
        } else {
            sleep_us(DHT11_DELAY_US);
            if (gpiod_line_get_value(line)) {
                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
                fprintf(fd, "%s: Timeout: Response not received\n", timestamp);
            }
        }

        for (int i = 0; i < 40; i++) {
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
            if (i > 2 && i < 38) {
                if (!dht11_read(line)) {
                    fprintf(fd, "%s: Timeout: Data bit %d not received\n", timestamp, i - 3);
                }
            }
            sleep_us(DHT11_DELAY_US);
        }

        if (dht11_read(line)) {
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
            fprintf(fd, "%s: Timeout: Checksum not received\n", timestamp);
        }

        sleep_us(DHT11_DELAY_US);
        if (gpiod_line_get_value(line)) {
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
            fprintf(fd, "%s: Error: Sensor absent (line stuck high)\n", timestamp);
        } else {
            sleep_us(DHT11_DELAY_US);
            if (!gpiod_line_get_value(line)) {
                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
                fprintf(fd, "%s: Error: Sensor absent (line stuck low)\n", timestamp);
            }
        }
    }

    gpiod_line_release(line);
    close(fd);
    gpiod_chip_close(chip);

    return 0;
}

