                    }
                }
            }
        }

        sleep_us(DHT11_MIN_INTERVAL_US - DHT11_START_US - 2 * DHT11_DELAY_US);

        if (gpiod_line_get_value(line)) {
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
            fprintf(fd, "%s: Timeout: Line stuck high\n", timestamp);
        } else {
            sleep_us(DHT11_DELAY_US);
            if (gpiod_line_get_value(line)) {
                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
                fprintf(fd, "%s: Timeout: Response not received\n", timestamp);
            }
        }

        for (int i = 0; i < 40; i++) {
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
            if (i > 2 && i < 38) {
                if (!dht11_read(line)) {
                    fprintf(fd, "%s: Timeout: Data bit %d not received\n", timestamp, i - 3);
                }
            }
            sleep_us(DHT11_DELAY_US);
        }

        if (dht11_read(line)) {
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
            fprintf(fd, "%s: Timeout: Checksum not received\n", timestamp);
        }

        sleep_us(DHT11_DELAY_US);
        if (gpiod_line_get_value(line)) {
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
            fprintf(fd, "%s: Error: Sensor absent (line stuck high)\n", timestamp);
        } else {
            sleep_us(DHT11_DELAY_US);
            if (!gpiod_line_get_value(line)) {
                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
                fprintf(fd, "%s: Error: Sensor absent (line stuck low)\n", timestamp);
            }
        }
    }

    gpiod_line_release(line);
    close(fd);
    gpiod_chip_close(chip);

    return 0;
}
