        rdwr.messages[1].flags = I2C_M_RD;
        rdwr.messages[1].len = 6;
        rdwr.messages[1].buf = data;

        for (int attempts = 0; attempts < 3; attempts++) {
            ret = ioctl(i2c_fd, I2C_RDWR, &rdwr);
            if (ret >= 0)
                break;
            perror("Failed to perform I2C read");
            usleep(15000);
