        sleep(5);
    }

cleanup_log:
    fclose(log_file);

cleanup_i2c:
    close(i2c_fd);

cleanup_gpio:
    gpiod_line_release(gpio_get_line_byname("gpio2"));
    gpiod_line_release(gpio_get_line_byname("gpio3"));
    gpiod_release_lines(1);

    return 0;
}

uint8_t crc8(uint8_t crc, uint8_t data) {
    for (int i = 0; i < 8; i++) {
        crc = (crc >> 1) ^ (crc & 0x01 ? CRC8_POLYNOMIAL : 0);
        crc = (crc >> 8) ^ data;
        data <<= 1;
    }
    return crc;
}

