#include <string.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x29
#define SENSOR2_ADDR 0x2A
#define CCT_REG 0x00
#define SAMPLES 10

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int nlines,
                                const unsigned int *consumer,
                                const char *label, unsigned int flags) {
    return gpiod_chip_request_lines(chip, nlines, consumer, label, flags);
}

int main() {
    int i2c_fd[2];
    struct i2c_rdwr_ioctl_data i2c_data[2][SAMPLES];
    int ret, cct_sum = 0, samples_count = 0;
    FILE *log_file;
    struct timespec sleep_time = {1, 0};
    struct gpiod_chip *chip;
    struct gpiod_line_request_data lines[2];

    if ((chip = gpiod_chip_open_by_name("gpiochip0")) == NULL) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_lines(chip, 2, (const unsigned int[]) {14, 15},
                                 "adpd105_reset", GPIOD_LINE_REQUEST_INPUT) < 0) {
        perror("Failed to request GPIO lines");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < 2; ++i) {
        if ((i2c_fd[i] = open("/dev/i2c-1", O_RDWR)) < 0) {
            perror("Failed to open I2C bus");
            exit(EXIT_FAILURE);
        }

        if (ioctl(i2c_fd[i], I2C_SLAVE, i ? SENSOR2_ADDR : SENSOR1_ADDR) < 0) {
            perror("Failed to set I2C slave address");
            close(i2c_fd[i]);
            continue;
        }

        for (int j = 0; j < SAMPLES; ++j) {
            i2c_data[i][j].msglen = 1;
            i2c_data[i][j].buf = &CCT_REG;

            ret = ioctl(i2c_fd[i], I2C_RDWR, &i2c_data[i][j]);
            if (ret < 0) {
                perror("Failed to read CCT register");
                close(i2c_fd[i]);
                continue;
            }

            cct_sum += *(unsigned char *)i2c_data[i][j].buf;
            samples_count++;
        }

        close(i2c_fd[i]);
    }

    if (samples_count > 0) {
        double average_cct = (double)cct_sum / samples_count;

        if (!(log_file = fopen("cct_log.csv", "a"))) {
            perror("Failed to open log file");
        } else {
            struct timeval tv;
            gettimeofday(&tv, NULL);
            fprintf(log_file, "%lu,%f\n", tv.tv_sec, average_cct);
            fclose(log_file);
        }
    }

    gpiod_line_release_lines(chip, 2, lines);
    gpiod_chip_close(chip);

    return 0;
}

