#define I2C_BUS 1  // Change this to the I2C bus number your sensor is connected to
#define MLX90824_ADDR 0x60  // Change this to the address of your MLX90824 sensor

#define PRESSURE_REG 0x00
#define TEMPERATURE_REG 0x01

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int nlines,
                                const char *const names, unsigned int flags)
{
    return gpiod_chip_get_lines_request_array(chip, nlines, names, flags);
}

int main(void) {
    int i2c_fd, ret;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg i2c_msgs[2];
    char log_filename[] = "pressure_log.txt";
    FILE *log_file;
    struct timespec sleep_interval = {2, 0};
    struct gpiod_chip *chip;
    struct gpiod_line_request *request;
    struct gpiod_line_state *state;
    time_t timestamp;
    char timestamp_str[32];

    // Initialize GPIO
    if ((chip = gpiod_chip_open_by_name("gpiochip0")) == NULL) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    if ((request = gpiod_line_request_get(chip, "gpio_shutdown", GPIOD_LINE_REQUEST_DIRECTION_OUT)) == NULL) {
        perror("Failed to request GPIO line");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_enable(request) < 0) {
        perror("Failed to enable GPIO line");
        exit(EXIT_FAILURE);
    }

    // Set GPIO line to high to disable the sensor during program execution
    if (gpiod_line_set_value(request, 1) < 0) {
        perror("Failed to set GPIO line");
        exit(EXIT_FAILURE);
    }

    // Open I2C device
    if ((i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR) < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Initialize I2C messages
    i2c_msgs[0].addr = MLX90824_ADDR;
    i2c_msgs[0].flags = 0;
    i2c_msgs[0].len = 1;
    i2c_msgs[0].buf = (char *)&i2c_data.msgs[0].buf;

    i2c_msgs[1].addr = MLX90824_ADDR;
    i2c_msgs[1].flags = I2C_M_RD;
    i2c_msgs[1].len = 2;
    i2c_msgs[1].buf = (char *)&i2c_data.msgs[1].buf;

    // Initialize I2C data
    i2c_data.nmsgs = 2;
    i2c_data.msgs = i2c_msgs;

    // Open log file
    if ((log_file = fopen(log_filename, "a")) == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    while (1) {
        // Set GPIO line to low to enable the sensor
        if (gpiod_line_set_value(request, 0) < 0) {
            perror("Failed to set GPIO line");
            continue;
        }

        // Perform I2C read
        ret = ioctl(i2c_fd, I2C_RDWR, &i2c_data);
        if (ret < 0) {
            perror("Failed to perform I2C read");
            continue;
        }

        // Read pressure and temperature from I2C data
        uint16_t pressure = ((uint16_t)i2c_data.msgs[1].buf[0] << 8) | i2c_data.msgs[1].buf[1];
        int16_t temperature = ((int16_t)i2c_data.msgs[1].buf[2] << 8) | i2c_data.msgs[1].buf[3];

        // Set GPIO line to high to disable the sensor
        if (gpiod_line_set_value(request, 1) < 0) {
            perror("Failed to set GPIO line");
            continue;
        }

        // Format timestamp
        timestamp = time(NULL);
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S.%N", gmtime(&timestamp));

        // Append measurement to log file
        fprintf(log_file, "%s, Pressure: %u, Temperature: %d\n", timestamp_str, pressure, temperature);
        fflush(log_file);

        // Sleep for 2 seconds
        nanosleep(&sleep_interval, NULL);
    }

    // Close I2C device
    close(i2c_fd);

    // Close log file
    fclose(log_file);

    // Disable GPIO line
    if (gpiod_line_request_disable(request) < 0) {
        perror("Failed to disable GPIO line");
    }

    // Free GPIO line request
    gpiod_line_request_free(request);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}
