        return;
    }

    if (read(data->fd, buf, len) != len) {
        perror("Failed to read from I2C device");
    }
}

float lm75b_read_temp(struct i2c_data *data) {
    uint8_t buf[2];
    i2c_read(data, buf, 2);

    float temp = (buf[0] << 8 | buf[1]) * 0.0625;
    return temp - 40;
}

int gpio_request(const char *label, unsigned int gpio, unsigned int flags) {
    if (gpiod_chip_open_byname("gpiochip0") < 0) {
        perror("Failed to open GPIO chip");
        return -1;
