    struct i2c_msg messages[];
};

static uint16_t crc8(const uint8_t *data, size_t len)
{
    uint16_t crc = SDP810_CRC_INIT;
    for (size_t i = 0; i < len; ++i) {
        for (uint8_t bit = 8; bit > 0; --bit) {
            crc = (crc & 0x0001) ? (crc >> 1) ^ SDP810_CRC_POLYNOMIAL : crc >> 1;
            crc = (crc & 0xFF) ^ data[i] << 8;
        }
    }
    return crc;
}

