    gpiod_line_state_vlinenum_data_vlinenum_flags_t gpio_state_data = {0};
    gpiod_line_callback_data_vlinenum_data_vlinenum_flags_t gpio_callback_data = {0};
    gpiod_line_callback gpio_callback;

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        goto cleanup;
    }

    if (gpiod_library_open() < 0) {
        perror("Failed to open GPIO library");
        goto i2c_close;
    }

    if (gpiod_chip_open_by_name("gpiochip0") < 0) {
        perror("Failed to open GPIO chip");
        goto gpio_library_close;
    }

