I'll provide a simple example using the `libgpiod` library for GPIO handling and `i2c-dev` for I2C communication. This code assumes you have the necessary libraries installed and the STTS2004 is connected to the I2C bus with the address 0x48 (0x76 in 7-bit format).

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <gpiod.h>

#define I2C_BUS 1
#define LED_GPIO 17

int main(void) {
    int i2c_fd, ret;
    struct i2c_rdwr_ioctl_data i2c_data;
    char read_buf[2];
    gpiod_line_request_lines(1, &LED_GPIO, "led", GPIOD_LINE_REQUEST_DIRECTION_OUT, NULL);
    gpiod_line_set_value(LED_GPIO, 0);

    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        goto cleanup_gpio;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, STTS2004_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        goto cleanup_i2c;
    }

    i2c_data.wr_buf = (char[]) {0x03, 0x00}; // STTS2004 command to read temperature
    i2c_data.wr_len = 2;
    i2c_data.rd_buf = read_buf;
    i2c_data.rd_len = 2;

    while (1) {
        ret = ioctl(i2c_fd, I2C_RDWR, &i2c_data);
        if (ret < 0) {
            perror("Failed to read from I2C");
            goto cleanup_i2c;
        }

        if (read_buf[0] != 0x00 || read_buf[1] > 0xFF) {
            fprintf(stderr, "Invalid temperature data received\n");
            continue;
        }

        int temp = read_buf[1] << 8 | read_buf[0];
        double celsius = (double)temp / 65536 * 125 - 45;

        if (celsius > 28.0) {
            gpiod_line_set_value(LED_GPIO, 1);
        } else if (celsius < 27.0) {
            gpiod_line_set_value(LED_GPIO, 0);
        }

        printf("Temperature: %.2f°C\n", celsius);
        sleep(1);
    }

cleanup_i2c:
    close(i2c_fd);
cleanup_gpio:
    gpiod_line_release(LED_GPIO);
    return 0;
}
