#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/time.h>
#include <signal.h>
#include <libgpiod.h>

#define SENSOR_ADDR 0x48 // Sensirion SDP800-500Pa I2C address
#define CRC_POLYNOMIAL 0x31 // CRC-8 polynomial
#define CRC_INIT 0x00

struct i2c_rdwr_ioctl_data {
    struct i2c_msg messages[2];
};

static void i2c_error_handler(int signum) {
    printf("I2C error occurred, cleaning up...\n");
    gpiod_set_value_cansleep(gpio, 0);
    close(i2c_fd);
    exit(1);
}

int main() {
    int i2c_fd, ret;
    struct i2c_rdwr_ioctl_data rdwr;
    uint8_t buf[9];
    struct timeval tv;
    struct gpiod_line *gpio;
    struct gpiod_chip *chip;

    // Initialize GPIO for resetting the sensor
    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(1);
    }

    gpio = gpiod_chip_get_line(chip, "gpio18"); // Assuming the reset line is connected to GPIO18
    if (!gpio) {
        perror("Failed to get GPIO line");
        gpiod_chip_put(chip);
        exit(1);
    }

    // Set the GPIO line to output and reset the sensor
    gpiod_line_request_output(gpio, "sensor_reset", GPIOD_LINE_ACTIVE_LOW);
    gpiod_set_value_cansleep(gpio, 1);
    usleep(100000); // Delay for 100ms to ensure the sensor is reset
    gpiod_set_value_cansleep(gpio, 0);
    usleep(100000); // Delay for 100ms to ensure the sensor is ready

    // Open the I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpiod_line_release(gpio);
        gpiod_chip_put(chip);
        exit(1);
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpiod_line_release(gpio);
        gpiod_chip_put(chip);
        exit(1);
    }

    // Register the signal handler for SIGINT
    signal(SIGINT, i2c_error_handler);

    while (1) {
        // Send measurement command
        rdwr.messages[0].addr = SENSOR_ADDR;
        rdwr.messages[0].flags = 0;
        rdwr.messages[0].len = 1;
        rdwr.messages[0].buf = (uint8_t*) &0x01; // Measurement command

        rdwr.messages[1].addr = SENSOR_ADDR;
        rdwr.messages[1].flags = I2C_M_RD;
        rdwr.messages[1].len = 9;
        rdwr.messages[1].buf = buf;

        ret = ioctl(i2c_fd, I2C_RDWR, &rdwr);
        if (ret < 0) {
            perror("Failed to send I2C command");
            i2c_error_handler(0);
        }

        // Calculate and validate CRC
        uint8_t pressure_crc = buf[0] ^ buf[1] ^ (buf[1] << 7);
        uint8_t temp_crc = buf[2] ^ buf[3] ^ (buf[3] << 7);
        if (pressure_crc != buf[4] || temp_crc != buf[5]) {
            printf("CRC error, discarding data\n");
            continue;
        }

        // Log the measured values
        gettimeofday(&tv, NULL);
        printf("%ld.%06ld: Pressure: %d.%d mbar, Temperature: %d.%d °C\n",
               tv.tv_sec, tv.tv_usec, buf[0] << 8 | buf[1], buf[1] >> 6, buf[2] << 8 | buf[3], buf[3] >> 6);
        FILE *fp = fopen("flow_data.txt", "a");
        if (fp) {
            fprintf(fp, "%ld.%06ld: Pressure: %d.%d mbar, Temperature: %d.%d °C\n",
                    tv.tv_sec, tv.tv_usec, buf[0] << 8 | buf[1], buf[1] >> 6, buf[2] << 8 | buf[3], buf[3] >> 6);
            fclose(fp);
        } else {
            perror("Failed to open log file");
        }

        // Delay for 45ms
        usleep(45000);
    }

    // Cleanup on exit
    close(i2c_fd);
    gpiod_line_release(gpio);
    gpiod_chip_put(chip);

    return 0;
}

