#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <time.h>
#include <sys/time.h>
#include <errno.h>
#include <string.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <Adafruit_Si7021.h>

#define I2C_BUS 1
#define SDA_GPIO 2
#define SCL_GPIO 3
#define LOG_FILE "environment.log"
#define MAX_RETRIES 3

Adafruit_Si7021 si7021;
struct timespec sleep_duration = { .tv_sec = 0, .tv_nsec = 60 * 1000 * 1000 };
gpiod_line_request_lines_data_v1 lines_data = { 0 };
gpiod_line_request_data_v1 line_req_data = { 0 };
int i2c_fd = -1;
FILE *log_file = NULL;

void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(stderr, "%s: %s\n", time_str, message);
    fprintf(log_file, "%s: %s\n", time_str, message);
    fflush(log_file);
}

int init_gpio() {
    int ret;
    lines_data.lines = (const gpiod_line_info_v1*) malloc(2 * sizeof(gpiod_line_info_v1));
    if (!lines_data.lines) {
        log_error("Failed to allocate memory for GPIO lines");
        return -1;
    }

    ret = gpiod_get_array_data(0, &lines_data);
    if (ret < 0) {
        log_error("Failed to get GPIO data");
        free(lines_data.lines);
        return -1;
    }

    line_req_data.consumer = "Si7021 sensor";
    line_req_data.flags = GPIOD_LINE_REQUEST_DIRECTION_IN;

    ret = gpiod_chip_request_lines(0, 2, &line_req_data, &lines_data);
    if (ret < 0) {
        log_error("Failed to request GPIO lines");
        free(lines_data.lines);
        return -1;
    }

    gpiod_line_get_value_v1(lines_data.lines[SDA_GPIO].gpio, &line_req_data.lines[SDA_GPIO].value);
    gpiod_line_get_value_v1(lines_data.lines[SCL_GPIO].gpio, &line_req_data.lines[SCL_GPIO].value);

    return 0;
}

int init_i2c() {
    char i2c_dev_path[32];
    snprintf(i2c_dev_path, sizeof(i2c_dev_path), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_dev_path, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, Si7021_DEFAULT_ADDR) < 0) {
        log_error("Failed to set I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

int init_log() {
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        log_error("Failed to open log file");
        return -1;
    }

    return 0;
}

void cleanup() {
    if (log_file) {
        fclose(log_file);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    gpiod_chip_release_lines(0, 2, &line_req_data);
    free(lines_data.lines);
}

void sigint_handler(int signum) {
    cleanup();
    exit(0);
}

int main() {
    int ret, i;
    uint8_t data[6];
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[80];

    if (init_gpio() < 0) {
        return 1;
    }

    if (init_i2c() < 0) {
        goto cleanup_gpio;
    }

    if (init_log() < 0) {
        goto cleanup_i2c;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        si7021.begin();

        for (i = 0; i < MAX_RETRIES; ++i) {
            ret = si7021.readRawHumidity(data);
            if (ret == 0) {
                break;
            }
            if (i < MAX_RETRIES - 1) {
                usleep(20 * 1000);
            }
        }

        if (ret < 0) {
            log_error("Failed to read humidity");
            goto cleanup_log;
        }

        si7021.begin();

        for (i = 0; i < MAX_RETRIES; ++i) {
            ret = si7021.readRawTemperature(data);
            if (ret == 0) {
                break;
            }
            if (i < MAX_RETRIES - 1) {
                usleep(20 * 1000);
            }
        }

        if (ret < 0) {
            log_error("Failed to read temperature");
            goto cleanup_log;
        }

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s,%d,%d\n", time_str, data[0] * 256 + data[1], data[3] * 256 + data[4]);
        fprintf(stdout, "%s,%d,%d\n", time_str, data[0] * 256 + data[1], data[3] * 256 + data[4]);
        fflush(log_file);

        nanosleep(&sleep_duration, NULL);
    }

cleanup_log:
    fclose(log_file);

cleanup_i2c:
    close(i2c_fd);

cleanup_gpio:
    gpiod_chip_release_lines(0, 2, &line_req_data);
    free(lines_data.lines);

    return 0;
}

