#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <time.h>
#include <sys/time.h>
#include <errno.h>
#include <string.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define SLAVE_ADDR 0x40
#define CRC_POLYNOMIAL 0x07

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int nlines,
                                const char *const names[], unsigned int flags)
{
    return gpiod_chip_get_lines_request_array(chip, nlines, names, flags);
}

static int read_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0;
    for (size_t i = 0; i < len; ++i) {
        crc ^= data[i];
        for (int j = 0; j < 8; ++j) {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            else
                crc <<= 1;
        }
    }
    return crc;
}

int main()
{
    int i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SLAVE_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    struct timespec sleep_time = { 0, 10 * 1e6 };

    gpiod_chip *chip;
    gpiod_line_request_lines(gpiod_get_array_size(), NULL, 0, &chip);
    if (!chip) {
        perror("Failed to get GPIO chip");
        close(i2c_fd);
        return 1;
    }

    gpiod_line_request_line(chip, 0, "log_file", GPIOD_LINE_REQUEST_DIRECTION_OUT,
                            GPIOD_LINE_ACTIVE_LOW, NULL);

    FILE *log_file = fopen("temperature_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_chip_put(chip);
        close(i2c_fd);
        return 1;
    }

    struct timespec now;
    char timestamp[30];
    while (1) {
        if (clock_gettime(CLOCK_REALTIME, &now) != 0) {
            perror("Failed to get current time");
            continue;
        }

        uint8_t data[3];
        ssize_t bytes_read = read(i2c_fd, data, sizeof(data));
        if (bytes_read != 3) {
            perror("Failed to read data from sensor");
            continue;
        }

        uint8_t crc = read_crc8(data, sizeof(data) - 1);
        if (data[2] != crc) {
            fprintf(stderr, "CRC mismatch\n");
            continue;
        }

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%N",
                 localtime(&now.tv_sec));
        fprintf(log_file, "%s,%d\n", timestamp, (int)data[0] * 256 + data[1]);

        gpiod_line_set_value(chip, 0, 1);
        nanosleep(&sleep_time, NULL);
        gpiod_line_set_value(chip, 0, 0);

        usleep(495000); // Wait for 5 seconds
    }

    fclose(log_file);
    gpiod_chip_put(chip);
    close(i2c_fd);

    return 0;
}

void sigint_handler(int signum)
{
    fprintf(stderr, "Received SIGINT, cleaning up and exiting\n");
    siglongjmp(siglongjmp_buf_empty, 1);
}

void sigterm_handler(int signum)
{
    fprintf(stderr, "Received SIGTERM, cleaning up and exiting\n");
    siglongjmp(siglongjmp_buf_empty, 1);
}

int main()
{
    sigset_t set;
    sigemptyset(&set);
    sigaddset(&set, SIGINT);
    sigaddset(&set, SIGTERM);

    sigjmp_buf buf;
    if (sigsetjmp(buf, 1)) {
        // Clean up and exit on signal
        fprintf(stderr, "Cleaning up and exiting\n");
        return 0;
    }

    // Main program code here

    return 0;
}

