#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x48
#define LOG_FILE "hvac_pressure_log.txt"
#define CRC_POLYNOMIAL 0x07
#define CRC_INITIAL_VALUE 0x00

static uint8_t crc8(uint8_t *data, size_t len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (size_t i = 0; i < len; ++i) {
        for (uint8_t bit = 8; bit > 0; --bit) {
            crc = (crc >> 1) ^ (crc & 0x01 ? CRC_POLYNOMIAL : 0);
            crc = (crc & 0x00FF) << 8 | data[i];
        }
    }
    return crc;
}

int main() {
    int i2c_fd = -1;
    gpiod_line_request_flags_t flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_RISING;
    struct timespec delay = { .tv_sec = 0, .tv_nsec = 50 * 1e6 };
    struct i2c_rdwr_ioctl_data i2c_data;
    uint8_t buf[12];
    size_t bytes_written = 0;
    size_t bytes_read = 0;
    struct timespec timestamp;
    clock_gettime(CLOCK_MONOTONIC, &timestamp);

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    if (gpiod_chip_open_byname("gpiochip0") < 0) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    gpiod_line_request_desc_t *line_desc = gpiod_chip_get_line_request_byname(gpiod_chip_get_data(NULL), "gpio0");
    if (line_desc == NULL) {
        perror("Failed to find GPIO line");
        gpiod_chip_close(gpiod_chip_get_data(NULL));
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_enable(line_desc, flags) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line_desc);
        gpiod_chip_close(gpiod_chip_get_data(NULL));
        close(i2c_fd);
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpiod_line_release(line_desc);
        gpiod_chip_close(gpiod_chip_get_data(NULL));
        close(i2c_fd);
        return 1;
    }

    while (1) {
        if (gpiod_line_get_value(line_desc) == 1) {
            i2c_data.wr_buf = (uint8_t[]) { 0x03, 0x00 }; // Trigger measurement
            i2c_data.nmsgs = 1;
            if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) < 0) {
                perror("Failed to trigger measurement");
                continue;
            }

            i2c_data.wr_buf = (uint8_t[]) { 0x04, 0x00 }; // Read data
            i2c_data.nmsgs = 1;
            if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) < 0) {
                perror("Failed to read data");
                continue;
            }

            bytes_read = read(i2c_fd, buf, sizeof(buf));
            if (bytes_read != sizeof(buf)) {
                perror("Failed to read expected number of bytes");
                continue;
            }

            uint8_t crc_calculated = crc8(buf, 9);
            if (buf[10] != crc_calculated || buf[14] != crc_calculated) {
                fprintf(stderr, "Invalid CRC\n");
                continue;
            }

            clock_gettime(CLOCK_MONOTONIC, &timestamp);
            fprintf(log_file, "%lld,%d,%d,%d\n", timestamp.tv_sec * 1e9 + timestamp.tv_nsec, buf[0] << 8 | buf[1], buf[2], buf[6]);
        }

        nanosleep(&delay, NULL);
    }

    fclose(log_file);
    gpiod_line_release(line_desc);
    gpiod_chip_close(gpiod_chip_get_data(NULL));
    close(i2c_fd);

    return 0;
}

