    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    trigger_req = gpiod_line_request_get(chip, 1, "SDP810 Trigger", GPIOD_LINE_REQUEST_INPUT);
    if (!trigger_req) {
        perror("Failed to request trigger line");
        gpiod_chip_close(chip);
        return 1;
    }

    gpiod_line_request_enable(trigger_req);
    gpiod_line_get_value(trigger_req->lines[0]) ? gpiod_line_set_value(trigger_req->lines[0], 0) : gpiod_line_set_value(trigger_req->lines[0], 1);
    gpiod_chip_activate(chip);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        gpiod_line_release_request(trigger_req);
        gpiod_chip_deactivate(chip);
        return 1;
    }

    log_file = fopen("sdp810_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpiod_line_release_request(trigger_req);
        gpiod_chip_deactivate(chip);
        return 1;
    }

    i2c_msgs[0].addr = SDP810_I2C_ADDR;
    i2c_msgs[0].flags = 0;
    i2c_msgs[0].len = 1;
    i2c_msgs[0].buf = &data[0];
    i2c_msgs[1].addr = SDP810_I2C_ADDR;
    i2c_msgs[1].flags = I2C_M_RD;
    i2c_msgs[1].len = 9;
    i2c_msgs[1].buf = data;

    i2c_data.wr_msgs = &i2c_msgs[0];
    i2c_data.rd_msgs = &i2c_msgs[1];
    i2c_data.nmsgs = 2;

    while (1) {
        ret = ioctl(i2c_fd, I2C_RDWR, &i2c_data);
        if (ret < 0) {
            perror("Failed to read from I2C device");
            continue;
        }

        pressure = (data[1] << 8) | data[0];
        temperature = (data[3] << 8) | data[2];
        scale_factor = (data[5] << 8) | data[4];

        crc_calculated = crc8(data, 7, SDP810_CRC_POLYNOMIAL, SDP810_CRC_INIT);
        crc_received = data[8];

        if (crc_calculated == crc_received) {
            timestamp = time(NULL);
            fprintf(log_file, "%ld,%d,%d\n", timestamp, pressure, temperature);
        } else {
            fprintf(stderr, "CRC error: calculated %02X, received %02X\n", crc_calculated, crc_received);
        }

        nanosleep(&sleep_time, NULL);
        gpiod_line_get_value(trigger_req->lines[0]) ? gpiod_line_set_value(trigger_req->lines[0], 0) : gpiod_line_set_value(trigger_req->lines[0], 1);
    }

    fclose(log_file);
    close(i2c_fd);
    gpiod_line_release_request(trigger_req);
    gpiod_chip_deactivate(chip);

    return 0;
}

uint8_t crc8(const uint8_t *data, size_t len, uint8_t poly, uint8_t init) {
    uint8_t crc = init;
    for (size_t i = 0; i < len; ++i) {
        for (uint8_t bit = 8; bit > 0; --bit) {
            crc = (crc & 0x80) ? (crc << 1) ^ poly : crc << 1;
            crc = (crc & 0x00) | ((crc >> 7) & 0x01);
            crc ^= data[i] & 0x01;
        }
        data++;
    }
    return crc;
}
