```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <time.h>
#include <sys/time.h>
#include <gpiod.h>
#include <pthread.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1e

static gpiod_line_request_lines_data_t gpio_request_data = {
    .lines = {
        { .direction = GPIOD_LINE_DIR_IN, .edge = GPIOD_LINE_EDGE_RISING },
    },
    .count = 1,
};

static gpiod_line_handle_t gpio_handle;
static int gpio_fd;
static int i2c_fd;
static int exit_flag = 0;
static pthread_t read_thread;

void sigint_handler(int signum) {
    exit_flag = 1;
}

void i2c_write(uint8_t reg, uint16_t value) {
    uint8_t data[2] = {reg, (value >> 8) & 0xFF, value & 0xFF};

    if (write(i2c_fd, data, sizeof(data)) != sizeof(data)) {
        perror("i2c_write: ");
    }
}

uint16_t i2c_read(uint8_t reg) {
    uint8_t data[2];

    if (write(i2c_fd, &reg, 1) != 1) {
        perror("i2c_write: ");
        return 0;
    }

    if (read(i2c_fd, data, sizeof(data)) != sizeof(data)) {
        perror("i2c_read: ");
        return 0;
    }

    return (data[0] << 8) | data[1];
}

void read_sensor_data() {
    while (!exit_flag) {
        usleep(10000);

        uint16_t pressure = i2c_read(0x00);
        uint16_t temperature = i2c_read(0x02);

        if (pressure && temperature) {
            time_t rawtime;
            struct tm *timeinfo;
            char time_str[32];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(time_str, sizeof(time_str), "%Y-%m-%dT%H:%M:%S", timeinfo);

            FILE *file = fopen("environmental_data.txt", "a");
            if (file) {
                fprintf(file, "%s, Pressure: %u, Temperature: %u\n", time_str, pressure, temperature);
                fflush(file);
                fclose(file);
            } else {
                perror("fopen: ");
            }

            printf("%s, Pressure: %u, Temperature: %u\n", time_str, pressure, temperature);
        }
    }

    gpiod_line_release_request(gpio_handle);
    gpiod_line_release(gpio_handle, 0);
    close(i2c_fd);
    gpiod_chip_unregister_callbacks(gpiod_chip_get_bylabel("gpiochip0"));
    gpiod_chip_deinitialize(gpiod_chip_get_bylabel("gpiochip0"));
    gpiod_line_free_request_data(&gpio_request_data);
    gpiod_line_free(gpio_handle);
    gpiod_deinitialize();
    pthread_exit(NULL);
}

int main() {
    signal(SIGINT, sigint_handler);

    if (gpiod_library_init() < 0) {
        perror("gpiod_library_init: ");
        return 1;
    }

    gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd < 0) {
        perror("open: ");
        return 1;
    }

    if (gpiod_chip_initialize(gpio_fd, "gpiochip0") < 0) {
        perror("gpiod_chip_initialize: ");
        return 1;
    }

    if (gpiod_chip_register_callbacks(gpiod_chip_get_bylabel("gpiochip0"), &gpio_request_data, NULL) < 0) {
        perror("gpiod_chip_register_callbacks: ");
        return 1;
    }

    gpio_handle = gpiod_chip_get_line_bylabel(gpiod_chip_get_bylabel("gpiochip0"), "gpio18");
    if (!gpio_handle) {
        perror("gpiod_chip_get_line_bylabel: ");
        return 1;
    }

    if (gpiod_line_request_enable(gpio_handle, GPIOD_LINE_REQUEST_INPUT) < 0) {
        perror("gpiod_line_request_enable: ");
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open: ");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl: ");
        return 1;
    }

    pthread_create(&read_thread, NULL, read_sensor_data, NULL);
    pthread_detach(read_thread);

    while (!exit_flag) {
        usleep(5000000);
    }

    return 0;
}
```

This code initializes the GPIO and I2C subsystems, sets up a SIGINT handler, and starts a separate thread to read sensor data every 5 seconds. The read_sensor_data() function handles reading the pressure and temperature values from the sensor, appending them to a file, and printing them to stdout. It also checks for I2C read/write errors and skips samples in case of errors.

