            usleep(100000); // 100ms off
        } else {
            gpiod_set_value(led_gpio, LED_ON);
            usleep(500000); // 500ms on
            gpiod_set_value(led_gpio, LED_OFF);
            usleep(500000); // 500ms off
        }

        printf("Pressure: %d Pa, Temperature: %d °C\n", pressure, temperature);
        usleep(1000000); // 1s delay
    }

    return 0;
}

