#include <pigpio.h>

#define I2C_BUS 1
#define MLX_ADDR 0x33
#define FAN_GPIO 18
#define LOG_FILE "temperature_log.txt"
#define READ_RETRIES 3
#define HYSTERESIS 2

typedef struct {
    uint16_t ambient_temp;
    uint16_t object_temp;
    time_t timestamp;
} TemperatureData;

int init_i2c() {
    int i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX_ADDR) < 0) {
        perror("Failed to acquire I2C address");
        close(i2c_fd);
        return -1;
    }

    return i2c_fd;
}

int read_temperature(int i2c_fd, TemperatureData* data) {
    int retries = READ_RETRIES;
    uint8_t buf[6];

    while (retries > 0) {
        if (i2c_master_send(i2c_fd, (const uint8_t*)"\xEC\x06\x01\x00\x00\x90", 6) != 6) {
            usleep(10000);
            retries--;
            continue;
        }

        if (i2c_master_recv(i2c_fd, buf, 6) != 6) {
            usleep(10000);
            retries--;
            continue;
        }

        data->ambient_temp = (buf[1] << 8) | buf[0];
        data->object_temp = (buf[3] << 8) | buf[2];
        data->timestamp = time(NULL);
        return 0;
    }

    perror("Failed to read temperature data");
    return -1;
}

void log_temperature(TemperatureData data) {
    FILE* log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%lu,%d,%d\n", data.timestamp, data.ambient_temp, data.object_temp);
    fclose(log_file);
}

void control_fan(int fan_gpio, int on) {
    if (on) {
        gpioInitialise();
        gpioSetMode(fan_gpio, PI_OUTPUT);
        gpioWrite(fan_gpio, 1);
    } else {
        gpioWrite(fan_gpio, 0);
    }
}

int main() {
    int i2c_fd = -1;
    TemperatureData data;
    int fan_on = 0;

    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio library");
        exit(EXIT_FAILURE);
    }

    i2c_fd = init_i2c();
    if (i2c_fd < 0) {
        exit(EXIT_FAILURE);
    }

    while (1) {
        if (read_temperature(i2c_fd, &data) < 0) {
            continue;
        }

        if (data.object_temp > 30) {
            if (!fan_on) {
                control_fan(FAN_GPIO, 1);
                fan_on = 1;
            }
        } else if (data.object_temp < 28 && fan_on) {
            control_fan(FAN_GPIO, 0);
            fan_on = 0;
        }

        log_temperature(data);
        sleep(2);
    }

    close(i2c_fd);
    gpioTerm();
    return 0;
}

