#include <errno.h>
#include <time.h>
#include <libgpiod.h>

#define TMP102_ADDR 0x48
#define I2C_BUS 1

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int lines,
                                unsigned int flags)
{
    return gpiod_chip_get_lines_request_array(chip, lines, flags);
}

int main(void) {
    int i2c_fd, ret;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg i2c_msgs[2];
    char buf[2];
    time_t rawtime;
    struct tm *timeinfo;
    FILE *csv_file;
    gpiod_line_request_lines_data_array_t gpio_requests;
    gpiod_line_state_cb gpio_cb;
    gpiod_line_event_cb gpio_event_cb;
    struct gpiod_chip *gpiochip;
    int gpio_line;

    // Open I2C bus
    if ((i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Initialize I2C messages
    i2c_msgs[0].addr = TMP102_ADDR;
    i2c_msgs[0].flags = 0;
    i2c_msgs[0].len = 1;
    i2c_msgs[0].buf = buf;

    i2c_msgs[1].addr = TMP102_ADDR;
    i2c_msgs[1].flags = I2C_M_RD;
    i2c_msgs[1].len = 2;
    i2c_msgs[1].buf = buf;

    // Initialize I2C read/write data structure
    i2c_data.wr_msgs = &i2c_msgs[0];
    i2c_data.rd_msgs = &i2c_msgs[1];
    i2c_data.nmsgs = 2;

    // Open TMP102 sensor
    if (i2c_smbus_read_i2c_block_data(i2c_fd, 0x00, 2, buf) < 0) {
        perror("Failed to read TMP102 sensor");
        exit(EXIT_FAILURE);
    }

    // Configure TMP102 for 12-bit resolution
    buf[0] = 0x3E;
    if (i2c_smbus_write_byte_data(i2c_fd, TMP102_ADDR, buf[0]) < 0) {
        perror("Failed to configure TMP102 sensor");
        exit(EXIT_FAILURE);
    }

    // Open temperature log file
    if (!(csv_file = fopen("temperature_log.csv", "a"))) {
        perror("Failed to open temperature log file");
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO chip
    gpiochip = gpiod_chip_open_byname("gpiochip0");
    if (!gpiochip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request GPIO line for SIGINT detection
    gpio_line = 17;
    gpio_requests = gpiod_line_request_lines(gpiochip, 1,
                                             GPIOD_LINE_REQUEST_INPUT |
                                             GPIOD_LINE_REQUEST_EDGE_RISING);
    gpio_requests[0].consumer = "TempLogger";
    gpio_requests[0].line = gpio_line;
    if (gpiod_chip_request_lines(gpiochip, gpio_requests, 1) < 0) {
        perror("Failed to request GPIO line");
        exit(EXIT_FAILURE);
    }

    // Set GPIO line callbacks
    gpio_cb = gpiod_line_get_value_cb(gpio_requests[0].request);
    gpio_event_cb = gpiod_line_get_event_cb(gpio_requests[0].request);
    gpio_cb(gpio_requests[0].request, gpiod_line_get_value(gpio_requests[0].request));
    gpiod_line_set_debounce(gpio_requests[0].request, 10);
    gpiod_line_set_glitch_filter(gpio_requests[0].request, 10);
    gpiod_line_set_event_cb(gpio_requests[0].request, gpio_event_cb);

    // Main loop
    while (1) {
        // Read temperature from TMP102
        if (i2c_smbus_read_i2c_block_data(i2c_fd, 0x01, 2, buf) < 0) {
            perror("Failed to read temperature");
            continue;
        }

        // Convert raw temperature data to Celsius
        int16_t raw_temp = (buf[0] << 8) | buf[1];
        float temp_c = (float)raw_temp * 0.0625 - 40.0;

        // Format and write timestamped temperature to CSV file
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        fprintf(csv_file, "%04d-%02d-%02d %02d:%02d:%02d,%.2f\n",
                timeinfo->tm_year + 1900, timeinfo->tm_mon + 1,
                timeinfo->tm_mday, timeinfo->tm_hour, timeinfo->tm_min,
                timeinfo->tm_sec, temp_c);

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup on SIGINT
    gpiod_line_release_request(gpio_requests[0].request);
    gpiod_chip_close(gpiochip);
    fclose(csv_file);
    close(i2c_fd);

    return 0;
}

