#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define HDC2010_ADDR 0x40
#define MEASUREMENT_CONFIG 0x23
#define TIMEOUT_MS 500
#define MAX_RETRIES 5
#define SLEEP_SECONDS 5

volatile sig_atomic_t shutdown = 0;

void signal_handler(int signum) {
    shutdown = 1;
}

int i2c_write_reg(int fd, uint8_t addr, uint8_t reg, uint16_t value) {
    uint8_t data[3] = {reg, (value >> 8) & 0xFF, value & 0xFF};
    int retries = MAX_RETRIES;
    while (retries > 0) {
        if (write(fd, data, 3) != 3) {
            if (errno != EAGAIN && errno != EBUSY) {
                perror("i2c_write_reg");
                return -1;
            }
            retries--;
            usleep(100000);
            continue;
        }
        if (ioctl(fd, I2C_SMBUS_WRITE_BYTE_DATA, addr) < 0) {
            if (errno != EAGAIN && errno != EBUSY) {
                perror("I2C_SMBUS_WRITE_BYTE_DATA");
                return -1;
            }
            retries--;
            usleep(100000);
            continue;
        }
        return 0;
    }
    perror("i2c_write_reg: timeout");
    return -1;
}

uint16_t i2c_read_reg(int fd, uint8_t addr, uint8_t reg) {
    int retries = MAX_RETRIES;
    while (retries > 0) {
        if (i2c_write_reg(fd, addr, reg, 0) < 0) {
            if (errno != EAGAIN && errno != EBUSY) {
                perror("i2c_write_reg");
                return 0;
            }
            retries--;
            usleep(100000);
            continue;
        }
        uint8_t data[2];
        if (read(fd, data, 2) != 2) {
            if (errno != EAGAIN && errno != EBUSY) {
                perror("read");
                return 0;
            }
            retries--;
            usleep(100000);
            continue;
        }
        return (data[0] << 8) | data[1];
    }
    perror("i2c_read_reg: timeout");
    return 0;
}

int main() {
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, HDC2010_ADDR) < 0) {
        perror("I2C_SLAVE");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (!shutdown) {
        if (i2c_write_reg(i2c_fd, HDC2010_ADDR, MEASUREMENT_CONFIG, 0x27) < 0) {
            usleep(100000);
            continue;
