        uint16_t humidity = i2c_read_reg(i2c_fd, HDC2010_ADDR, 0x2A);

        if (temp == 0xFFFF || humidity == 0xFFFF) {
            printf("Sensor NAK or bus error\n");
            usleep(100000);
            continue;
        }

        printf("Temperature: %.1f°C, Humidity: %.1f%%\n",
