    const char *i2c_dev = "/dev/i2c-" I2C_BUS;
    if ((i2c_file = open(i2c_dev, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(i2c_file, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to acquire I2C bus");
        close(i2c_file);
        return -1;
    }

    return 0;
}

void cleanup(void) {
    if (i2c_file >= 0) {
        close(i2c_file);
    }
    gpiod_line_release_lines(&lines, 1);
}

