I'm glad you're working with the Raspberry Pi and the Bosch BMP280 pressure sensor! Here's a sample C program using the libgpiod library for I2C communication. This code should serve as a starting point for your project.

Please note that you'll need to install the libgpiod library on your Raspberry Pi before compiling this code. You can do this by running:

```bash
sudo apt-get update
sudo apt-get install libgpiod-dev
```

Now, here's the C code:

```c
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define BMP280_ADDR 0x76
#define OVER_THRESHOLD 1020
#define UNDER_THRESHOLD 980
#define SAMPLE_INTERVAL 2000
#define RETRY_ATTEMPTS 3

static const char *log_file = "pressure_log.txt";

struct bmp280_data {
    uint16_t pressure;
    uint16_t temperature;
    time_t timestamp;
};

void i2c_write_read(int fd, uint8_t reg, uint8_t *write_buf, size_t write_len, uint8_t *read_buf, size_t read_len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        exit(EXIT_FAILURE);
    }

    if (write(fd, write_buf, write_len) != write_len) {
        perror("Failed to write data");
        exit(EXIT_FAILURE);
    }

    if (read(fd, read_buf, read_len) != read_len) {
        perror("Failed to read data");
        exit(EXIT_FAILURE);
    }
}

uint16_t bmp280_read_16(int fd, uint8_t reg) {
    uint8_t data[2];
    i2c_write_read(fd, reg, NULL, 0, data, 2);
    return (data[0] << 8) | data[1];
}

void bmp280_init(int *fd) {
    *fd = open("/dev/i2c-1", O_RDWR);
    if (*fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(*fd, I2C_SLAVE, BMP280_ADDR) < 0) {
        perror("Failed to acquire I2C bus");
        exit(EXIT_FAILURE);
    }

    uint8_t chip_id = bmp280_read_16(*fd, 0xD0) >> 3;
    if (chip_id != 0x55) {
        fprintf(stderr, "Invalid BMP280 chip ID: 0x%02x\n", chip_id);
        exit(EXIT_FAILURE);
    }

    uint8_t ctrl_meas_reg = 0x27;
    uint8_t config_reg = 0xAC;
    i2c_write_read(*fd, ctrl_meas_reg, &config_reg, 1, NULL, 0);
}

void bmp280_deinit(int *fd) {
    close(*fd);
}

void bmp280_sample(struct bmp280_data *data) {
    int fd;
    bmp280_init(&fd);

    uint8_t ctrl_meas_reg = 0x2E;
    i2c_write_read(fd, ctrl_meas_reg, NULL, 0, NULL, 0);

    usleep(10000); // Wait for conversion completion

    data->temperature = bmp280_read_16(fd, 0xF7);
    data->pressure = bmp280_read_16(fd, 0xF6);

    bmp280_deinit(&fd);

    data->timestamp = time(NULL);
}

void log_sample(const struct bmp280_data *data) {
    FILE *log_file_ptr = fopen(log_file, "a");
    if (!log_file_ptr) {
        perror("Failed to open log file");
        return;
    }

    char timestamp_str[32];
    ctime_r(&data->timestamp, timestamp_str);
    timestamp_str[24] = '\0';

    fprintf(log_file_ptr, "%s Pressure: %hu hPa, Temperature: %hu °C\n", timestamp_str, data->pressure, data->temperature);
    fclose(log_file_ptr);
}

void signal_handler(int sig) {
    (void)sig;
    gpiod_chip_shutdown(NULL);
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    struct bmp280_data sample;
    while (1) {
        bmp280_sample(&sample);

        if (sample.pressure > UNDER_THRESHOLD || sample.pressure < OVER_THRESHOLD) {
            log_sample(&sample);
        }

        sleep(SAMPLE_INTERVAL / 1000);
    }

    return EXIT_SUCCESS;
}
```

This code initializes the I2C bus, verifies the BMP280 chip ID, and samples the pressure sensor every 2 seconds. It logs pressure values that exceed 1020 hPa or fall below 980 hPa to a file named `pressure_log.txt`. The program includes signal handlers for SIGINT and SIGTERM to ensure a clean shutdown that closes the I2C handle and invokes the library's call() function on all exit paths.

