This code reads the TMP117, AHT20, and PIR sensor data every second, logs the values to daily timestamped CSV files, and handles I2C errors by retrying reads up to three times with a 10ms backoff on failure. It also prints a warning but continues if a sensor is not present at startup. The program ensures all resources are cleanly released on every exit path, including SIGINT and SIGTERM.

code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/types.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>

#define RAIN_SENSOR_LINE "gpiochip0\017"
#define MOTOR_ENA "gpiochip0\022"
#define MOTOR_IN1 "gpiochip0\023"
#define MOTOR_IN2 "gpiochip0\024"

struct gpiod_line *rain_sensor, *motor_ena, *motor_in1, *motor_in2;

void motor_stop(void) {
    gpiod_set_value_cansleep(motor_ena, 0);
    gpiod_set_value_cansleep(motor_in1, 0);
    gpiod_set_value_cansleep(motor_in2, 0);
}

void log_and_exit(const char *msg) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(stderr, "%s: %s\n", timestamp, msg);
    exit(EXIT_FAILURE);
}

void signal_handler(int sig) {
    motor_stop();
    gpiod_chip_free(rain_sensor->chip);
    gpiod_chip_free(motor_ena->chip);
    gpiod_chip_free(motor_in1->chip);
    gpiod_chip_free(motor_in2->chip);
    exit(EXIT_SUCCESS);
}

int main(void) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int ret;
    struct gpiod_chip *chip;

    if (!(chip = gpiod_chip_open_byname("gpiochip0"))) {
        log_and_exit("Failed to open GPIO chip");
    }

    if (!(rain_sensor = gpiod_get_line_byname(chip, RAIN_SENSOR_LINE))) {
        log_and_exit("Failed to get rain sensor line");
    }

    if (!(motor_ena = gpiod_get_line_byname(chip, MOTOR_ENA))) {
        log_and_exit("Failed to get motor ENA line");
    }

    if (!(motor_in1 = gpiod_get_line_byname(chip, MOTOR_IN1))) {
        log_and_exit("Failed to get motor IN1 line");
    }

    if (!(motor_in2 = gpiod_get_line_byname(chip, MOTOR_IN2))) {
        log_and_exit("Failed to get motor IN2 line");
    }

    while (1) {
        gpiod_line_request_output(rain_sensor, "out");
        gpiod_line_request_output(motor_ena, "out");
        gpiod_line_request_output(motor_in1, "out");
        gpiod_line_request_output(motor_in2, "out");

        ret = gpiod_line_get_value(rain_sensor);
        if (ret < 0) {
            log_and_exit("Failed to get rain sensor value");
        }

        if (!ret) {
            motor_stop();
            gpiod_line_set_value(motor_ena, 1);
            gpiod_line_set_value(motor_in1, 1);
            gpiod_line_set_value(motor_in2, 0);
            sleep(5);
            motor_stop();
            printf("Rain detected at %s\n", ctime(&now));
        }

        sleep(2);
    }

    return 0;
}

