code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <uv.h>

#define I2C_BUS 1
#define BMP280_ADDR 0x76
#define UDP_IP "192.168.1.100"
#define UDP_PORT 5000

struct bmp280_data {
    int16_t temperature;
    uint16_t pressure;
};

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int nlines,
                                const char *const *consumer,
                                unsigned int flags) {
    return gpiod_chip_request_lines(chip, nlines, consumer, flags);
}

static int bmp280_read(int fd, struct bmp280_data *data) {
    int ret;
    uint8_t buf[6];

    ret = write(fd, 0x00, 1);
    if (ret != 1) {
        perror("Failed to write to BMP280");
        return -1;
    }

    ret = read(fd, buf, 6);
    if (ret != 6) {
        perror("Failed to read from BMP280");
        return -1;
    }

    data->temperature = (buf[0] << 8) | buf[1];
    data->temperature /= 256;
    data->temperature -= 46.85;

    data->pressure = (buf[2] << 16) | (buf[3] << 8) | buf[4];
    data->pressure /= 256;
    data->pressure = 1048576 - data->pressure;
    data->pressure /= 32768;

    return 0;
}

static void udp_send(const char *json, size_t len) {
    uv_udp_send_t req;
    uv_udp_send(uv_default_loop(), &req, json, len, UDP_IP, UDP_PORT,
                    NULL);
}

static void udp_send_cb(uv_udp_send_t *req, int status) {
    if (status < 0) {
        perror("Failed to send UDP packet");
    }
}

static void sigint_handler(int signum) {
    printf("Received SIGINT, shutting down...\n");

    gpiod_line_release(line);
    uv_close((uv_handle_t*) &udp_handle, NULL);
    gpiod_chip_release(chip);
    uv_loop_close(uv_default_loop());
    exit(0);
}

int main() {
    int i2c_fd, ret;
    struct bmp280_data data;
    struct gpiod_chip *chip;
    gpiod_line_handle *line;
    uv_udp_t udp_handle;
    uv_loop_t *loop = uv_default_loop();

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(1);
    }

    line = gpiod_line_request_array(chip, 1, "bmp280_sda", GPIOD_LINE_REQUEST_INPUT,
                                    GPIOD_LINE_ACTIVE_LOW);
    if (!line) {
        perror("Failed to request BMP280 SDA line");
        exit(1);
    }

    ret = gpiod_line_get_value_cansleep(line, &data.temperature);
    if (ret < 0) {
        perror("Failed to get initial SDA state");
        exit(1);
    }

    if (ret == 0) {
        printf("BMP280 not connected\n");
        exit(0);
    }

    gpiod_line_set_value(line, 0);

    ret = open("/dev/i2c-1", O_RDWR);
    if (ret < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP280_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(1);
    }

    uv_udp_init(loop, &udp_handle);
    uv_udp_bind(&udp_handle, UDP_IP, UDP_PORT, 0);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        gpiod_line_set_value(line, 1);
        usleep(100000);
        gpiod_line_set_value(line, 0);

        ret = bmp280_read(i2c_fd, &data);
        if (ret < 0) {
            perror("Failed to read from BMP280");
            continue;
        }

        char json[256];
        snprintf(json, sizeof(json),
                 "{\"temperature\": %.2f, \"pressure\": %.2f}",
                 data.temperature, data.pressure);

        uv_udp_send_t req;
        uv_udp_send(&req, json, strlen(json), UDP_IP, UDP_PORT,
                    udp_send_cb);

        usleep(5000000);
    }

    close(i2c_fd);
    gpiod_line_release(line);
    gpiod_chip_release(chip);
    uv_close((uv_handle_t*) &udp_handle, NULL);
    uv_loop_close(uv_default_loop());

    return 0;
}

