#include <gpiod.h>

#define MAX_TEMP_ENTRIES 20
#define FAN_GPIO 18
#define SPI_BUS 0
#define SPI_DEVICE 0
#define MAX31855_CS_GPIO 8
#define MAX31855_CH0 0x03
#define MAX31855_CH1 0x04
#define MAX31855_READ_CMD 0x03
#define MAX31855_WRITE_CMD 0x02

struct temp_entry {
    time_t timestamp;
    double temperature;
    uint8_t duty_cycle;
};

int spi_fd;
struct gpiod_chip *chip;
struct gpiod_line *fan_line;
struct temp_entry buffer[MAX_TEMP_ENTRIES];
int buffer_head = 0;
int buffer_tail = 0;

void die(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

int spi_xfer(uint8_t *tx_buf, size_t tx_len, uint8_t *rx_buf, size_t rx_len) {
    ssize_t ret;
    if ((ret = write(spi_fd, tx_buf, tx_len)) != tx_len)
        die("SPI write error");
    if ((ret = read(spi_fd, rx_buf, rx_len)) != rx_len)
        die("SPI read error");
    return ret;
}

double read_temp(uint8_t channel) {
    uint8_t buf[3];
    spi_xfer(&MAX31855_WRITE_CMD, 1, NULL, 0);
    spi_xfer(&channel, 1, buf, 3);
    if (buf[0] != MAX31855_READ_CMD || buf[1] != channel)
        die("MAX31855 read error");
    double temp = (buf[2] << 8 | buf[3]) * 0.0625;
    return temp * 100;
}

void update_fan(double temp) {
    uint32_t duty_cycle = 0;
    if (temp < 25)
        duty_cycle = 0;
    else if (temp <= 40)
        duty_cycle = (temp - 25) * 50 / 15;
    else if (temp <= 60)
        duty_cycle = 50 + (temp - 40) * 150 / 20;
    else
        duty_cycle = 255;

    gpiod_line_set_value(fan_line, duty_cycle > 255 ? 1 : duty_cycle);
}

int main() {
    int ret;
    spi_fd = open("/dev/spidev" SPI_BUS, O_RDWR);
    if (spi_fd < 0)
        die("Cannot open SPI device");

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip)
        die("Cannot open GPIO chip");

    fan_line = gpiod_chip_get_line(chip, FAN_GPIO);
    if (!fan_line)
        die("Cannot get GPIO line");

    gpiod_line_request_output(fan_line, "fan");
    gpiod_line_set_value(fan_line, 0);

    gpiod_line_set_debounce(MAX31855_CS_GPIO, 10);
    gpiod_line_request_output(MAX31855_CS_GPIO, "cs");
    gpiod_line_set_value(MAX31855_CS_GPIO, 1);

    spi_xfer(NULL, 0, NULL, 0);
    spi_xfer(&MAX31855_CS_GPIO, 1, NULL, 0);

    while (1) {
        gpiod_line_set_value(MAX31855_CS_GPIO, 0);
        double temp = read_temp(MAX31855_CH0);
        gpiod_line_set_value(MAX31855_CS_GPIO, 1);

        struct temp_entry *entry = &buffer[buffer_head];
        entry->timestamp = time(NULL);
        entry->temperature = temp;
        entry->duty_cycle = 0;

        update_fan(temp);

        buffer_head = (buffer_head + 1) % MAX_TEMP_ENTRIES;
        if (buffer_tail + 1 == buffer_head) {
            printf("Temperature,Duty cycle,Timestamp\n");
            for (int i = buffer_tail; i != buffer_head; i = (i + 1) % MAX_TEMP_ENTRIES) {
                printf("%.1f,%.0f,%s\n", buffer[i].temperature, buffer[i].duty_cycle, ctime(&buffer[i].timestamp));
            }
        }

        sleep(1);
    }

    gpiod_line_release(fan_line);
    gpiod_chip_close(chip);
    close(spi_fd);

    return 0;
}

