#define BMP180_I2C_ADDR 0x77
#define GPIO_LINE_NR 2

struct bmp180_data {
    uint16_t ut;
    int16_t up;
    int16_t p;
};

int bmp180_read_data(int fd) {
    struct i2c_rdwr_ioctl_data xfer[2];
    struct i2c_msg msgs[2];
    struct bmp180_data data;
    int ret;

    msgs[0].addr = BMP180_I2C_ADDR;
    msgs[0].flags = 0;
    msgs[0].len = 1;
    msgs[0].buf = (char *)&data.ut;

    msgs[1].addr = BMP180_I2C_ADDR;
    msgs[1].flags = I2C_M_RD;
    msgs[1].len = 3;
    msgs[1].buf = (char *)&data.up + 2;

    xfer[0].wr_msgs = &msgs[0];
    xfer[0].rd_msgs = NULL;
    xfer[0].nmsgs = 1;

    xfer[1].wr_msgs = NULL;
    xfer[1].rd_msgs = &msgs[1];
    xfer[1].nmsgs = 1;

    ret = ioctl(fd, I2C_RDWR, xfer);
    if (ret < 0) {
        perror("I2C read error");
        return -1;
    }

    if (data.ut & 0x8000) {
        perror("BMP180 calibration error");
        return -1;
    }

    data.p = (int16_t)((((int64_t)data.ut << 8) | data.up) * 266 / 4096 - 4000);

    return 0;
}

void gpio_interrupt_cb(struct gpiod_line *line, unsigned int value,
                       unsigned int events, void *user_data) {
    FILE *log_file = (FILE *)user_data;
    struct timespec ts;
    struct bmp180_data data;
    int i2c_fd;

    if (value) {
        if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
            perror("Failed to open I2C device");
            return;
        }

        if (bmp180_read_data(i2c_fd) < 0) {
            close(i2c_fd);
            return;
        }

        close(i2c_fd);

        clock_gettime(CLOCK_MONOTONIC, &ts);
        fprintf(log_file, "%lld,%d,%d\n", ts.tv_sec * 1000 + ts.tv_nsec / 1000000,
                data.p / 100.0, data.p);
    }
}

int main() {
    int gpio_fd, i2c_fd;
    struct gpiod_line_request line_req;
    FILE *log_file;

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_RDWR,
              (struct i2c_rdwr_ioctl_data){
                  .wr_msgs = (struct i2c_msg[]){
                      {
                          .addr = BMP180_I2C_ADDR,
                          .flags = 0,
                          .len = 1,
                          .buf = (char *)&(uint8_t){0x2E},
                      },
                      {
                          .addr = BMP180_I2C_ADDR,
                          .flags = I2C_M_RD,
                          .len = 1,
                          .buf = (char *)&(uint8_t){0},
                      },
                  },
                  .rd_msgs = NULL,
                  .nmsgs = 2,
              }) < 0) {
        perror("Failed to set oversampling setting");
        close(i2c_fd);
        return 1;
    }

    if ((gpio_fd = gpiod_open_name_with_flags("gpiochip0", GPIO_LINE_NR,
                                              GPIOD_OPEN_FLAG_DIRECTION_IN |
                                                  GPIOD_OPEN_FLAG_EDGE_FALLING)) < 0) {
        perror("Failed to open GPIO line");
        close(i2c_fd);
        return 1;
    }

    gpiod_line_request_configure(&line_req, gpio_fd, GPIO_LINE_NR,
                                 GPIOD_LINE_REQ_DIRECTION_INPUT |
                                     GPIOD_LINE_REQ_EDGE_FALLING |
                                     GPIOD_LINE_REQ_ACTIVE_HIGH |
                                     GPIOD_LINE_REQ_ENABLE_PULL);
    if (gpiod_line_request(gpio_fd, &line_req) < 0) {
        perror("Failed to request GPIO line");
        close(i2c_fd);
        gpiod_close(gpio_fd);
        return 1;
    }

    log_file = fopen("altitude_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(gpio_fd, &line_req);
        close(i2c_fd);
        gpiod_close(gpio_fd);
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to ignore SIGINT");
        fclose(log_file);
        gpiod_line_release(gpio_fd, &line_req);
        close(i2c_fd);
        gpiod_close(gpio_fd);
        return 1;
    }

    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    unsigned long long last_log = ts.tv_sec * 1000 + ts.tv_nsec / 1000000;

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        unsigned long long now = ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
        if (now - last_log >= 1000) {
            gpiod_line_get_value_async(gpio_fd, GPIO_LINE_NR,
                                       gpio_interrupt_cb, log_file);
            last_log = now;
        }
        usleep(100000);
    }

    fclose(log_file);
    gpiod_line_release(gpio_fd, &line_req);
    close(i2c_fd);
    gpiod_close(gpio_fd);

    return 0;
}

