#include <errno.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define BME280_ADDR 0x76
#define BME280_ID 0x60

#define I2C_RDWR(addr, wr_buf, wr_len, rd_buf, rd_len) \
    do { \
        if (write(fd, &addr, 1) != 1) { \
            perror("Failed to write I2C address"); \
            exit(EXIT_FAILURE); \
        } \
        if (wr_len) { \
            if (write(fd, wr_buf, wr_len) != wr_len) { \
                perror("Failed to write I2C data"); \
                exit(EXIT_FAILURE); \
            } \
        } \
        if (rd_len) { \
            if (read(fd, rd_buf, rd_len) != rd_len) { \
                perror("Failed to read I2C data"); \
                exit(EXIT_FAILURE); \
            } \
        } \
    } while (0)

int main(void) {
    int fd_i2c, ret;
    char buf[3];
    char *filename = "bme280_log.csv";
    FILE *fp;
    struct timespec sleep_time = {5, 0};
    struct gpiod_chip *chip;
    struct gpiod_line_request *line_req;
    struct i2c_rdwr_ioctl_data i2c_data;
    uint8_t dev_id;

    // Open I2C bus
    if ((fd_i2c = open("/dev/i2c-" I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Request GPIO2 and GPIO3 for I2C
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }
    line_req = gpiod_chip_get_line_request_byindex(chip, 2);
    if (!line_req) {
        perror("Failed to get GPIO2 line request");
        exit(EXIT_FAILURE);
    }
    gpiod_line_request_direction_output(line_req, GPIOD_LINE_ACTIVE_HIGH);
    gpiod_line_request_enable(line_req, 1);
    line_req = gpiod_chip_get_line_request_byindex(chip, 3);
    if (!line_req) {
        perror("Failed to get GPIO3 line request");
        exit(EXIT_FAILURE);
    }
    gpiod_line_request_direction_output(line_req, GPIOD_LINE_ACTIVE_HIGH);
    gpiod_line_request_enable(line_req, 1);

    // Initialize BME280 sensor
    I2C_RDWR(BME280_ADDR, NULL, 0, buf, 1);
    if (buf[0] != BME280_ID) {
        fprintf(stderr, "BME280 chip ID mismatch\n");
        exit(EXIT_FAILURE);
    }

    // Configure sensor settings
    // Replace these values with appropriate settings for your application
    uint8_t config_data[] = {
        0x2E, // Oversampling rate for temperature: 16x
        0x86, // Oversampling rate for pressure: 128x
        0x4A  // Oversampling rate for humidity: 16x
    };
    I2C_RDWR(BME280_ADDR, config_data, sizeof(config_data), NULL, 0);

    // Open log file
    if ((fp = fopen(filename, "w")) == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Read temperature, humidity, and pressure
        struct i2c_msg msgs[] = {
            {
                .addr = BME280_ADDR,
                .flags = 0,
                .len = 1,
                .buf = (char *)&config_data[0]
            },
            {
                .addr = BME280_ADDR,
                .flags = I2C_M_RD,
                .len = 6,
                .buf = buf
            }
        };
        i2c_data.wr_msgs = msgs;
        i2c_data.rd_msgs = &msgs[1];
        i2c_data.nmsgs = sizeof(msgs) / sizeof(struct i2c_msg);
        if (ioctl(fd_i2c, I2C_RDWR, &i2c_data) < 0) {
            perror("Failed to read I2C data");
            continue;
        }

        // Parse data
        int16_t temperature = ((buf[1] << 8) | buf[0]);
        uint16_t humidity = ((buf[3] << 8) | buf[2]);
        uint32_t pressure = ((buf[5] << 16) | (buf[4] << 8) | buf[3]);

        // Format and write log entry
        char timestamp[32];
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(fp, "%s,%d.%03d,%d.%02d,%d\n", timestamp,
                temperature / 100.0, (temperature % 100) * 10,
                humidity / 100.0, humidity % 100, pressure / 100);

        // Sleep for 5 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    fclose(fp);
    gpiod_line_request_disable(line_req);
    gpiod_line_request_free(line_req);
    gpiod_chip_put(chip);
    close(fd_i2c);

    return 0;
}

