Here's a C program that fulfills the user's request using the `libgpiod` and `i2c-dev` libraries. This code assumes you have the necessary libraries installed and the BMP180 sensor is connected to the I2C bus 1 with the correct address (0x77 by default).

```c
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/mman.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod/gpiod.h>

#define I2C_BUS 1
#define BMP180_ADDR 0x77
#define GPIO_LINE_24 24
#define BUFFER_SIZE (60 * 50)
#define SAMPLE_INTERVAL 50
#define PRESSURE_THRESHOLD 5

struct bmp180_data {
    uint16_t ut;
    int16_t p;
};

struct buffer {
    struct bmp180_data buffer[BUFFER_SIZE];
    size_t head;
    size_t tail;
};

struct gpiod_line *gpio_line;
struct i2c_rdwr_ioctl_data i2c_data;
struct i2c_msg i2c_msgs[2];

void i2c_write(uint8_t reg, uint8_t *data, size_t len)
{
    i2c_msgs[0].addr = BMP180_ADDR << 1;
    i2c_msgs[0].flags = 0;
    i2c_msgs[0].len = 1;
    i2c_msgs[0].buf = &reg;

    i2c_msgs[1].addr = BMP180_ADDR << 1;
    i2c_msgs[1].flags = I2C_M_RDWR;
    i2c_msgs[1].len = len + 1;
    memcpy(i2c_msgs[1].buf, data, len);

    if (ioctl(i2c_data.fd, I2C_RDWR, &i2c_data) < 0) {
        perror("I2C write error");
        exit(EXIT_FAILURE);
    }
}

uint8_t i2c_read(uint8_t reg, uint8_t *data, size_t len)
{
    i2c_msgs[0].addr = BMP180_ADDR << 1;
    i2c_msgs[0].flags = 0;
    i2c_msgs[0].len = 1;
    i2c_msgs[0].buf = &reg;

    i2c_msgs[1].addr = BMP180_ADDR << 1;
    i2c_msgs[1].flags = I2C_M_RD;
    i2c_msgs[1].len = len;
    i2c_msgs[1].buf = data;

    if (ioctl(i2c_data.fd, I2C_RDWR, &i2c_data) < 0) {
        perror("I2C read error");
        exit(EXIT_FAILURE);
    }

    return i2c_msgs[1].len - len;
}

void bmp180_init()
{
    i2c_data.rdwr = malloc(sizeof(struct i2c_rdwr_ioctl_data) +
                            sizeof(struct i2c_msg) * 2);
    i2c_data.fd = open("/dev/i2c-1", O_RDWR);

    if (i2c_data.fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_data.fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("Failed to acquire I2C address");
        exit(EXIT_FAILURE);
    }

    i2c_write(0xF4, (uint8_t[]) {0x2E}, 1); // Soft reset
    usleep(100000);

    i2c_write(0x2E, (uint8_t[]) {0x88}, 1); // Set oversampling rate
    i2c_write(0x2E, (uint8_t[]) {0x00}, 1); // Set oversampling rate
    i2c_write(0x2E, (uint8_t[]) {0x44}, 1); // Set oversampling rate
    i2c_write(0x2E, (uint8_t[]) {0x1C}, 1); // Set oversampling rate

    i2c_write(0x2E, (uint8_t[]) {0x20}, 1); // Set up pressure measurement
}

struct bmp180_data bmp180_read()
{
    struct bmp180_data data;

    i2c_read(0xF4, (uint8_t *) &data.ut, 2);
    i2c_read(0xF6, (uint8_t *) &data.p, 2);

    data.p = (data.p << 8) | (data.p >> 4);
    data.p = (data.p * 266 / 65536) - 4000;

    return data;
}

void gpio_setup()
{
    gpio_line = gpiod_get_line_byname("gpiochip0", GPIO_LINE_24);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_line(gpio_line, 0, "bmp180_alert");
    gpiod_line_set_value(gpio_line, 0);
}

void log_error(const char *message)
{
    fprintf(stderr, "%s\n", message);
}

void signal_handler(int signum)
{
    gpiod_line_set_value(gpio_line, 0);
    close(i2c_data.fd);
    gpiod_line_release_line(gpio_line);
    exit(EXIT_SUCCESS);
}

void main()
{
    struct buffer buffer;
    struct bmp180_data rolling_average;
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);

    bmp180_init();
    gpio_setup();
    signal(SIGINT, signal_handler);

    buffer.head = buffer.tail = 0;
    rolling_average = bmp180_read();

    while (1) {
        struct bmp180_data current = bmp180_read();
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);

        if (now.tv_sec - ts.tv_sec > BUFFER_SIZE / SAMPLE_INTERVAL) {
            ts = now;
            buffer.head = (buffer.head + 1) % BUFFER_SIZE;
        }

        if (buffer.head != buffer.tail) {
            buffer.buffer[buffer.head] = current;
        } else {
            double sum = 0;
            size_t count = 0;

            for (size_t i = buffer.tail; i != buffer.head; i = (i + 1) % BUFFER_SIZE) {
                sum += buffer.buffer[i].p;
                count++;
            }

            rolling_average.p = sum / count;

            if (fabs(current.p - rolling_average.p) > PRESSURE_THRESHOLD) {
                gpiod_line_set_value(gpio_line, 1);
                log_error("Pressure deviation detected\n");
            }

            gpiod_line_set_value(gpio_line, 0);
        }

        usleep(SAMPLE_INTERVAL * 1000);
    }
}
```

This code initializes the I2C bus, sets up the BMP180 sensor, initializes the GPIO line for the alert, and enters a loop that samples the pressure sensor every 50ms, computes a rolling average, and asserts an active-HIGH alert on GPIO24 if the current pressure deviates by more than 5hPa from the average. On receipt of SIGINT, the program cleanly releases resources and terminates.

