#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/stat.h>
#include <unistd.h>
#include <time.h>
#include <sys/syscall.h>
#include <linux/limits.h>
#include <gpiod.h>

#define GPIO_FAN 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"
#define PWM_FREQ 25000
#define DUTY_MIN 0
#define DUTY_MAX 255
#define TEMP_MIN 40
#define TEMP_MAX 70

gpiod_line_request_linestate_cb fan_cb;
gpiod_line_request *fan_request;
int fan_fd;

void fan_line_request_cb(struct gpiod_line_request *request, int event, void *data) {
    (void)request;
    if (event == LINE_EVENT_ACTIVE_LOW) {
        gpiod_line_set_value(fan_request, 1);
    } else if (event == LINE_EVENT_ACTIVE_HIGH) {
        gpiod_line_set_value(fan_request, 0);
    }
}

void log_entry(const char *message) {
    char timestamp[20];
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(stderr, "%s: %s\n", timestamp, message);
    fprintf(stdout, "%s: %s\n", timestamp, message);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        return;
    }

    fprintf(log_file, "%s, %s, %d\n", timestamp, message, (int)syscall(SYS_gettid));
    fclose(log_file);
}

void sigint_handler(int sig) {
    log_entry("Received SIGINT, stopping fan and cleaning up");
    gpiod_line_release(fan_request);
    gpiod_line_request_free(fan_request);
    exit(0);
}

void sigterm_handler(int sig) {
    log_entry("Received SIGTERM, stopping fan and cleaning up");
    gpiod_line_release(fan_request);
    gpiod_line_request_free(fan_request);
    exit(0);
}

int main() {
    int temp_fd, duty;
    char temp_buf[PATH_MAX];
    struct timespec delay;
    struct sigaction sa;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    fan_request = gpiod_chip_request_line(gpiod_chip_get_by_name("gpiochip0"), GPIO_FAN, "fan", GPIOD_LINE_REQUEST_DIRECTION_OUT | GPIOD_LINE_REQUEST_EDGE_BOTH, fan_line_request_cb, NULL);
    if (fan_request == NULL) {
        perror("gpiod_chip_request_line");
        exit(1);
    }

    fan_fd = gpiod_line_get_fd(fan_request);
    if (fcntl(fan_fd, F_SETFL, O_NONBLOCK) == -1) {
        perror("fcntl");
        exit(1);
    }

    while (1) {
        temp_fd = open(TEMP_FILE, O_RDONLY);
        if (temp_fd == -1) {
            perror("open");
            continue;
        }

        ssize_t bytes_read = read(temp_fd, temp_buf, sizeof(temp_buf));
        if (bytes_read == -1) {
            perror("read");
            close(temp_fd);
            continue;
        }

        int temp = atoi(temp_buf);
        if (temp < TEMP_MIN) {
