    char timestamp[20];
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(stderr, "%s: %s\n", timestamp, message);
    fprintf(stdout, "%s: %s\n", timestamp, message);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        return;
    }

    fprintf(log_file, "%s, %s, %d\n", timestamp, message, (int)syscall(SYS_gettid));
    fclose(log_file);
}

void sigint_handler(int sig) {
