        goto cleanup_chip;
    }

    if ((gpio_req = gpiod_line_request_get(chip, SCL_GPIO, "SCL", GPIOD_LINE_REQUEST_DIRECTION_IN)) == NULL) {
        perror("Failed to request SCL GPIO");
        goto cleanup_sdagpio;
    }

