        perror("Failed to write to BMP280");
        goto cleanup_i2c;
    }

    if (bmp280_dev_init(&bmp, BMP280_I2C_ADDR_ALT, i2c_fd, 3333333)) {
        perror("Failed to initialize BMP280");
        goto cleanup_i2c;
    }

