        if (fflush(file) != 0) {
            perror("Failed to flush weather_data.txt");
            continue;
        }
        nanosleep(&sleep_time, &ts);
    }

cleanup_bmp:
    bmp280_dev_free(&bmp);

cleanup_i2c:
    close(i2c_fd);

cleanup_sdaclgpio:
    gpiod_line_release(gpio_req);

cleanup_sdagpio:
    gpiod_line_release(gpio_req);

cleanup_chip:
    gpiod_chip_close(chip);

    return 0;
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        fclose(file);
