code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/mman.h>
#include <pthread.h>
#include <errno.h>
#include <time.h>
#include <libgpiod.h>

#define LM75_ADDR 0x48
#define BUFFER_SIZE 60
#define GPIO_LINE 18
#define AVERAGE_COEF 0.016666666666666667

struct i2c_data {
    int fd;
    char *map_base;
};

struct buffer {
    float samples[BUFFER_SIZE];
    size_t head;
    size_t tail;
    pthread_mutex_t lock;
};

void i2c_read(struct i2c_data *data, uint8_t *buf, size_t len) {
    if (i2c_smbus_read_i2c_block_data(data->fd, 0, len, buf) < 0) {
        perror("i2c_smbus_read_i2c_block_data");
        exit(EXIT_FAILURE);
    }
}

float lm75_get_temp(struct i2c_data *data) {
    uint8_t buf[2];
    i2c_read(data, buf, 2);

    if (buf[0] & 0x60) {
        perror("LM75: Bus error");
        exit(EXIT_FAILURE);
    }

    return (buf[1] << 8 | buf[0]) * 0.0625;
}

void gpio_setup(gpiod_line_request_flags_t flags, gpiod_line_state_t state) {
    gpiod_line_request_err_t err;
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("gpiochip0 open");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpio line get");
        exit(EXIT_FAILURE);
    }

    err = gpiod_line_request_ddc_byname(line, "alert", flags, state);
    if (err) {
        perror("gpio line request");
        exit(EXIT_FAILURE);
    }
}

void gpio_cleanup(struct gpiod_line *line) {
    gpiod_line_release(line);
    gpiod_chip_close(line->chip);
}

void *temp_thread(void *arg) {
    struct i2c_data *data = arg;
    struct buffer *buf = (struct buffer *)arg;
    float temp;
    clock_t last_update = clock();

    while (1) {
        temp = lm75_get_temp(data);
        pthread_mutex_lock(&buf->lock);
        buf->samples[buf->head] = temp;
        buf->head = (buf->head + 1) % BUFFER_SIZE;
        pthread_mutex_unlock(&buf->lock);

        float avg = 0.0;
        size_t count = 0;
        pthread_mutex_lock(&buf->lock);
        for (size_t i = buf->tail; i != buf->head; i = (i + 1) % BUFFER_SIZE) {
            avg += buf->samples[i];
            count++;
        }
        pthread_mutex_unlock(&buf->lock);
        avg /= count * AVERAGE_COEF;

        if (temp > avg + 28.0) {
            gpiod_line_set_value(buf->line, 1);
        } else {
            gpiod_line_set_value(buf->line, 0);
        }

        clock_t now = clock();
        if (now - last_update >= CLOCKS_PER_SEC) {
            printf("Average temperature: %.2f°C\n", avg);
            last_update = now;
        }

        usleep(100000);
    }

    return NULL;
}

int main() {
    int i2c_bus = open("/dev/i2c-1", O_RDWR);
    if (i2c_bus < 0) {
        perror("i2c-1 open");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_bus, I2C_SLAVE, LM75_ADDR) < 0) {
        perror("I2C slave address");
        exit(EXIT_FAILURE);
    }

    struct i2c_data data = {i2c_bus, mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_SHARED, i2c_bus, 0),};

    struct buffer buf = {
        .head = 0,
        .tail = 0,
        .lock = PTHREAD_MUTEX_INITIALIZER,
    };

    buf.line = gpiod_get_line_byname("gpiochip0", "alert");
    if (!buf.line) {
        perror("gpio line get");
        exit(EXIT_FAILURE);
    }

    pthread_t temp_thread_id;
    if (pthread_create(&temp_thread_id, NULL, temp_thread, &buf) != 0) {
        perror("pthread create");
        exit(EXIT_FAILURE);
    }

    while (1) {
        float temp = lm75_get_temp(&data);
        if (temp < 0.0) {
            perror("LM75: Sensor absent");
            if (i2c_bus != -1) {
                close(i2c_bus);
                i2c_bus = open("/dev/i2c-1", O_RDWR);
                if (i2c_bus < 0) {
                    perror("i2c-1 open");
                    exit(EXIT_FAILURE);
                }

                if (ioctl(i2c_bus, I2C_SLAVE, LM75_ADDR) < 0) {
                    perror("I2C slave address");
                    exit(EXIT_FAILURE);
                }
            }
        }
        usleep(100000);
    }

    gpio_cleanup(buf.line);
    munmap(data.map_base, 4096);
    close(i2c_bus);

    return 0;
}

