    ret = i2c_smbus_read_i2c_block_data(i2c_fd, 0xAA, 2, buf);
    if (ret != 2) {
        perror("Failed to read calibration table");
        return -1;
    }

    calibration_table.ac1 = (buf[0] << 8) | buf[1];
    calibration_table.ac2 = (buf[2] << 8) | buf[3];
    calibration_table.ac3 = (buf[4] << 8) | buf[5];
    calibration_table.ac4 = (buf[6] << 8) | buf[7];
    calibration_table.ac5 = (buf[8] << 8) | buf[9];
    calibration_table.ac6 = (buf[10] << 8) | buf[11];
    calibration_table.b1 = (buf[12] << 8) | buf[13];
    calibration_table.b2 = (buf[14] << 8) | buf[15];

