```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <bmp180.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x77
#define GPIO_LOG_PIN 27

bmp180_dev_t dev;
FILE *log_file;
time_t last_log_time = 0;
int logging = 0;

void i2c_init() {
    int file;
    if ((file = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to acquire I2C address");
        exit(EXIT_FAILURE);
    }

    if (bmp180_init(&dev, file) != BMP180_OK) {
        perror("Failed to initialize BMP180");
        exit(EXIT_FAILURE);
    }
}

void gpio_init() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(GPIO_LOG_PIN, PI_INPUT);
    gpioSetPullUp(GPIO_LOG_PIN, 1);
    gpioSetInterrupt(GPIO_LOG_PIN, INT_EDGE_FALLING, gpioCallback);
}

void gpioCallback(int gpio, uint32_t events) {
    logging = !logging;
}

void log_pressure(double pressure) {
    time_t current_time = time(NULL);

    if (difftime(current_time, last_log_time) > 2) {
        last_log_time = current_time;

        if (log_file == NULL) {
            log_file = fopen("pressure_log.txt", "w");
            if (log_file == NULL) {
                perror("Failed to open pressure log file");
                exit(EXIT_FAILURE);
            }
        }

        fprintf(log_file, "%lld, %.2f\n", (long long)current_time, pressure);
        fflush(log_file);
    }
}

void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }

    bmp180_deinit(&dev);
    gpioTerm();
}

int main() {
    i2c_init();
    gpio_init();

    while (1) {
        if (bmp180_getPressure(&dev, SLP_MODE_STANDBY) != BMP180_OK) {
            perror("Failed to read pressure data");
            continue;
        }

        if (logging) {
            log_pressure(dev.pressure / 100.0);
        }

        usleep(200000);
    }

    cleanup();
    return 0;
}
