#define CPU_TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LED_RED_GPIO 17
#define LED_GREEN_GPIO 18
#define LED_BLUE_GPIO 27

volatile sig_atomic_t sig_received = 0;

void signal_handler(int signum) {
    sig_received = 1;
    gpiod_set_value_cansleep(led_red, 255);
    gpiod_set_value_cansleep(led_green, 255);
    gpiod_set_value_cansleep(led_blue, 255);
    gpiod_release(led_red);
    gpiod_release(led_green);
    gpiod_release(led_blue);
}

int main() {
    int temp_fd = open(CPU_TEMP_FILE, O_RDONLY);
    if (temp_fd < 0) {
        perror("Failed to open temperature file");
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(temp_fd);
        return 1;
    }

    gpiod_line_request_flags_mbus(chip, LED_RED_GPIO, GPIOD_LINE_REQUEST_DIRECTION_OUT | GPIOD_LINE_REQUEST_ACTIVE_LOW | GPIOD_LINE_REQUEST_PRESENT_POLARITY_INVERTED);
    gpiod_line_request_flags_mbus(chip, LED_GREEN_GPIO, GPIOD_LINE_REQUEST_DIRECTION_OUT | GPIOD_LINE_REQUEST_ACTIVE_LOW | GPIOD_LINE_REQUEST_PRESENT_POLARITY_INVERTED);
    gpiod_line_request_flags_mbus(chip, LED_BLUE_GPIO, GPIOD_LINE_REQUEST_DIRECTION_OUT | GPIOD_LINE_REQUEST_ACTIVE_LOW | GPIOD_LINE_REQUEST_PRESENT_POLARITY_INVERTED);

    struct gpiod_line *led_red = gpiod_get_line_byname(chip, "gpio17");
    struct gpiod_line *led_green = gpiod_get_line_byname(chip, "gpio18");
    struct gpiod_line *led_blue = gpiod_get_line_byname(chip, "gpio27");

