                perror("Failed to read temperature");
            }
            continue;
        }

        int temp_mdegC = atoi(temp_buf);
        int r = (temp_mdegC < 40000) ? 0 : (temp_mdegC >= 60000) ? 255 : (temp_mdegC - 40000) * 255 / 19999;
