            if (ret < 0) {
                perror("Failed to set green LED PWM");
                goto cleanup;
            }

            ret = gpiod_set_value_cansleep(led_blue, b);
            if (ret < 0) {
                perror("Failed to set blue LED PWM");
                goto cleanup;
            }
        }

        printf("%d m°C, R: %d, G: %d, B: %d\n", temp_mdegC, r, g, b);
        usleep(500000);
    }

cleanup:
    gpiod_line_release(led_red);
    gpiod_line_release(led_green);
    gpiod_line_release(led_blue);
    gpiod_chip_release(chip);
    close(temp_fd);

    return 0;
}

