#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <curl/curl.h>

#define DHT22_DATA_PIN 4
#define DHT22_BUS_WIDTH 1
#define DHT22_BUS_DIR GPIOD_IN
#define DHT22_BUS_FLAGS (GPIOD_LINE_ACTIVE_LOW | GPIOD_LINE_REQUEST_IN)
#define DHT22_RETRY_ATTEMPTS 3
#define DHT22_RETRY_SLEEP_MS 1000
#define API_URL "http://yourserver.com/api/humidity"

typedef struct {
    uint16_t humidity;
    uint16_t temperature;
} dht22_data_t;

static gpiod_line_request_data_t *dht22_data_line_request = NULL;
static gpiod_line_data_array_t dht22_data_line_data = {0};

static size_t write_data(void *ptr, size_t size, size_t nmemb, void *userp) {
    size_t remaing = *((size_t *)userp);
    size_t total = remaing + size * nmemb;

    if (total > INT32_MAX) {
        fprintf(stderr, "HTTP response too large\n");
        return 0;
    }

    memcpy(userp, ptr, size * nmemb);
    *((size_t *)userp) = total - size * nmemb;

    return size * nmemb;
}

static int dht22_read(dht22_data_t *data) {
    int ret = 0;
    int i;
    int bit_count = 0;
    int bit_value = 0;
    int checksum = 0;

    gpiod_line_value_t data_line_value;

    for (i = 0; i < 40; i++) {
        ret = gpiod_line_get_value(dht22_data_line_request, &data_line_value);
        if (ret < 0) {
            perror("Failed to read DHT22 data line");
            return -1;
        }

        if (data_line_value == 0) {
            if (bit_count > 7) {
                fprintf(stderr, "Invalid DHT22 data format\n");
                return -1;
            }
            bit_value = !bit_value;
            bit_count++;
        }

        usleep(50);
    }

    for (i = 0; i < 40; i++) {
        if ((i >= 2 && i <= 37) || (i >= 39 && i <= 40)) {
            if (data_line_value == bit_value) {
                checksum ^= data_line_value;
            }
        }

        ret = gpiod_line_get_value(dht22_data_line_request, &data_line_value);
        if (ret < 0) {
            perror("Failed to read DHT22 data line");
            return -1;
        }
    }

    if (checksum != data_line_data[39]) {
        fprintf(stderr, "Checksum mismatch\n");
        return -1;
    }

    data->humidity = (data_line_data[0] << 8) | data_line_data[1];
    data->temperature = (data_line_data[2] << 8) | data_line_data[3];

    return 0;
}

static void dht22_cleanup() {
    if (dht22_data_line_request) {
        gpiod_line_release(dht22_data_line_request);
        gpiod_line_request_free(dht22_data_line_request);
        dht22_data_line_request = NULL;
    }
}

static void signal_handler(int signum) {
    dht22_cleanup();
    exit(0);
}

int main() {
    int ret;
    CURL *curl;
    CURLcode res;
    dht22_data_t data;
    int attempts = 0;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    ret = gpiod_library_open();
    if (ret < 0) {
        perror("Failed to open libgpiod library");
        return 1;
    }

    ret = gpiod_chip_open_byname("gpiochip0");
    if (ret < 0) {
        perror("Failed to open GPIO chip");
        goto cleanup;
    }

    ret = gpiod_chip_get_line_request_bylabel(ret, "DHT22_DATA", &dht22_data_line_request);
    if (ret < 0) {
        perror("Failed to get DHT22 data line request");
        goto cleanup;
    }

    ret = gpiod_line_request_enable(dht22_data_line_request, GPIOD_LINE_REQUEST_DIRECTION | GPIOD_LINE_REQUEST_ACTIVE_LOW);
    if (ret < 0) {
        perror("Failed to enable DHT22 data line request");
        goto cleanup;
    }

    while (attempts < DHT22_RETRY_ATTEMPTS) {
        usleep(2000000); // Wait 2 seconds before the first read attempt
        ret = dht22_read(&data);
        if (ret == 0) {
            break;
        }

        attempts++;
        if (attempts < DHT22_RETRY_ATTEMPTS) {
            fprintf(stderr, "DHT22 read error, retrying in %d ms\n", DHT22_RETRY_SLEEP_MS);
            usleep(DHT22_RETRY_SLEEP_MS * 1000);
        }
    }

    if (attempts == DHT22_RETRY_ATTEMPTS) {
        fprintf(stderr, "Failed to read DHT22 data after %d attempts\n", DHT22_RETRY_ATTEMPTS);
        goto cleanup;
    }

    curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Failed to initialize libcurl\n");
        goto cleanup;
    }

    curl_easy_setopt(curl, CURLOPT_URL, API_URL);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS,
        "{\"humidity\": " FMT_u16 ", \"temperature\": " FMT_u16 "}", data.humidity, data.temperature);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_data);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &res);

    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "HTTP request error: %s\n", curl_easy_strerror(res));
        goto cleanup;
    }

cleanup:
    dht22_cleanup();
    curl_easy_cleanup(curl);
    gpiod_chip_close(ret);
    gpiod_library_close();

    return 0;
}

