            fprintf(stderr, "DHT22 read error, retrying in %d ms\n", DHT22_RETRY_SLEEP_MS);
            usleep(DHT22_RETRY_SLEEP_MS * 1000);
        }
    }

    if (attempts == DHT22_RETRY_ATTEMPTS) {
        fprintf(stderr, "Failed to read DHT22 data after %d attempts\n", DHT22_RETRY_ATTEMPTS);
        goto cleanup;
    }

    curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Failed to initialize libcurl\n");
        goto cleanup;
    }

    curl_easy_setopt(curl, CURLOPT_URL, API_URL);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS,
        "{\"humidity\": " FMT_u16 ", \"temperature\": " FMT_u16 "}", data.humidity, data.temperature);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_data);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &res);

    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "HTTP request error: %s\n", curl_easy_strerror(res));
        goto cleanup;
    }

cleanup:
    dht22_cleanup();
    curl_easy_cleanup(curl);
    gpiod_chip_close(ret);
    gpiod_library_close();

    return 0;
}
