#define DEBOUNCE_TICKS 200000
#define CONVERSION_DELAY 26
#define LOG_FILE "pressure_log.txt"

int i2c_file;
struct gpiod_line *button_gpio;

void bmp180_write(uint8_t reg, uint8_t value) {
    if (i2c_file < 0) {
        perror("Failed to open I2C device");
        exit(1);
    }

    if (write(i2c_file, &reg, 1) != 1) {
        perror("Failed to write to I2C device");
        exit(1);
    }

    if (write(i2c_file, &value, 1) != 1) {
        perror("Failed to write to I2C device");
        exit(1);
    }
}

uint8_t bmp180_read(uint8_t reg, uint8_t *buf, size_t len) {
    if (i2c_file < 0) {
        perror("Failed to open I2C device");
        exit(1);
    }

    if (write(i2c_file, &reg, 1) != 1) {
        perror("Failed to write to I2C device");
        exit(1);
    }

    if (read(i2c_file, buf, len) != (int)len) {
        perror("Failed to read from I2C device");
        exit(1);
    }

    return len;
}

void bmp180_init() {
    bmp180_write(0xF4, 0x26); // OSS=3
    bmp180_write(0xF5, 0x00); // IIR filter
    usleep(4000);
}

uint32_t bmp180_read_ut(void) {
    uint8_t data[6];
    bmp180_read(0xF7, data, 6);

    uint32_t ut = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    ut >>= (int)(6 - data[3] & 0x03);

    return ut;
}

int32_t bmp180_read_up(void) {
    uint8_t data[3];
    bmp180_read(0xF6, data, 3);

    int32_t up = (data[0] << 8) | data[1];
    up >>= (int)(8 - data[2] & 0x03);

    return up;
}

int32_t bmp180_read_p(void) {
    uint32_t ut = bmp180_read_ut();
    int32_t up = bmp180_read_up();
    int32_t b5 = (768 * up) / ut;
    int32_t p = 1048576 - b5 * (b5 / 4096);
    p = (p * 26 + 50000) / 100;

    return p;
}

void button_isr(struct gpiod_line *line, void *user_data) {
    static uint64_t last_tick = 0;
    uint64_t current_tick = gpiod_get_event_time(line);

    if (current_tick - last_tick > DEBOUNCE_TICKS) {
        last_tick = current_tick;
        if (gpiod_line_get_value(line)) {
            // Button press
            printf("Logging toggled\n");
            log_toggle();
        }
    }
}

void log_toggle() {
    static int logging = 0;

    if (logging) {
        printf("Logging disabled\n");
        fclose(log_file);
        logging = 0;
    } else {
        printf("Logging enabled\n");
        log_file = fopen(LOG_FILE, "w");
        if (!log_file) {
            perror("Failed to open log file");
            exit(1);
        }
    }

    usleep(100000); // Debounce the button press before starting logging

    if (logging) {
        timer_t timer;
        struct itimerspec ts;

        timer_create(CLOCK_REALTIME, NULL, &timer);
        ts.it_value.tv_sec = 2;
        ts.it_value.tv_nsec = 0;
        ts.it_interval.tv_sec = 2;
        ts.it_interval.tv_nsec = 0;

        timer_settime(timer, 0, &ts, NULL);

        while (logging) {
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            ts.tv_sec += 2;

            if (timer_pending(timer)) {
                int32_t pressure = bmp180_read_p();
                if (pressure >= 0) {
                    char timestamp[20];
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
                    fprintf(log_file, "%s,%d\n", timestamp, pressure);
                } else {
                    perror("Failed to read pressure");
                }
                fflush(log_file);

                usleep(CONVERSION_DELAY * 1000);
            }

            if (ts.tv_sec < time(NULL)) {
                timer_settime(timer, 0, &ts, NULL);
            }
        }

        timer_delete(timer);
        fclose(log_file);
    }
}

int main() {
    int ret;

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file < 0) {
        perror("Failed to open I2C device");
        exit(1);
    }

    if (ioctl(i2c_file, I2C_SLAVE, BMP180_I2C_ADDR) < 0) {
        perror("Failed to talk to BMP180");
        exit(1);
    }

    bmp180_init();

    ret = gpiod_claim_line_raw_flags(button_gpio, GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_ACTIVE_LOW);
    if (ret < 0) {
        perror("Failed to claim GPIO button");
        exit(1);
    }

    gpiod_set_debounce(button_gpio, DEBOUNCE_TICKS);
    gpiod_set_irq_callback(button_gpio, button_isr, NULL);
    gpiod_enable_irq(button_gpio);

    log_toggle();

    gpiod_release_line(button_gpio);
    close(i2c_file);

    return 0;
}

