    gpiod_chip_close(dht22_data_request->chip);
}

int dht22_read() {
    int i, j, checksum;

    gpiod_line_set_value(dht22_data_request, DHT22_CHIP_SELECT_LOW);
    usleep(1000 * DHT22_WAIT_TIME_US);
    gpiod_line_set_value(dht22_data_request, DHT22_CHIP_SELECT_HIGH);

    for (i = 0; i < DHT22_DATA_LENGTH; i++) {
        usleep(DHT22_BIT_TIME_US);
        gpiod_line_get_value(dht22_data_request, &dht22_data_state);
        if (dht22_data_state == DHT22_DATA_READY_LOW) {
            usleep(DHT22_BIT_TIME_US);
            gpiod_line_get_value(dht22_data_request, &dht22_data_state);
            dht22_data[i] = (dht22_data_state == DHT22_BIT_READ_LOW) ? 1 : 0;
        }
    }

    checksum = 0;
    for (i = 0; i < DHT22_DATA_LENGTH - 1; i++) {
        checksum ^= dht22_data[i];
    }

    if (dht22_data[DHT22_CHECKSUM_POS] == checksum) {
        dht22_success = 1;
        return 1;
    }

    if (--dht22_retries > 0) {
        usleep(DHT22_RETRY_DELAY_S * 1000000);
        dht22_retries++;
        return dht22_read();
    }

    return 0;
}

void dht22_log_event(const char *event) {
    openlog("dht22", LOG_PID, LOG_USER);
    syslog(LOG_INFO, "%s", event);
    closelog();
}

void dht22_post_data() {
    CURL *curl;
    CURLcode res;
    char json[128];

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();

    if (curl) {
        snprintf(json, sizeof(json), "{\"humidity\": %d}", dht22_data[0] * 256 + dht22_data[1]);
        curl_easy_setopt(curl, CURLOPT_URL, api_url);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, strlen(json));
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER,
                         curl_slist_append(NULL, "Content-Type: application/json"));

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            dht22_log_event("Failed to POST data to API");
            if (dht22_retries > 0) {
                usleep(DHT22_RETRY_DELAY_S * 1000000);
                dht22_retries++;
                dht22_post_data();
            }
        } else {
            dht22_log_event("Successfully POSTed data to API");
        }

        curl_easy_cleanup(curl);
    }

    curl_global_cleanup();
}

int main(int argc, char **argv) {
    int ret;

    if (argc > 2) {
        api_url = argv[1];
    }

    dht22_init();

    while (1) {
        if (dht22_read()) {
            dht22_success = 1;
            dht22_post_data();
        }

        usleep(10 * 1000 * 1000);

        if (!dht22_success) {
            dht22_log_event("Failed to read data from DHT22 sensor");
        }
    }

    dht22_deinit();
    return 0;
}
