#include <sys/mman.h>
#include <errno.h>
#include <libgpiod.h>

#define FAN_GPIO 18
#define FAN_PWM_MIN 0
#define FAN_PWM_MAX 100
#define FAN_PWM_FREQ 25000
#define TEMP_THRESHOLD_LOW 40.0
#define TEMP_THRESHOLD_HIGH 70.0
#define LOG_FILE "cooling_log.csv"

struct gpiod_chip *chip;
struct gpiod_line *line;

int setup_gpio(void) {
    int ret;
    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return -1;
    }

    line = gpiod_get_line_byname(chip, "gpio18");
    if (!line) {
        perror("Failed to get line gpio18");
        gpiod_chip_put(chip);
        return -1;
    }

    ret = gpiod_line_request_output_raw(line, GPIOD_LINE_ACTIVE_LOW);
    if (ret < 0) {
        perror("Failed to request output raw for gpio18");
        gpiod_line_put(line);
        gpiod_chip_put(chip);
        return -1;
    }

    return 0;
}

void teardown_gpio(void) {
    if (line) {
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_put(chip);
        chip = NULL;
    }
}

double map_temperature(double temp) {
    double pwm = (temp - TEMP_THRESHOLD_LOW) / (TEMP_THRESHOLD_HIGH - TEMP_THRESHOLD_LOW) * (FAN_PWM_MAX - FAN_PWM_MIN) + FAN_PWM_MIN;
    return pwm;
}

int main(void) {
    int ret;
    int fd_i2c;
    uint8_t buf[2];
    double temp;
    struct timespec ts;
    FILE *log_file;

    if (setup_gpio() < 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        teardown_gpio();
        return 1;
    }

    if (fprintf(log_file, "timestamp,temperature(°C),PWM duty cycle(%)\n") < 0) {
        perror("Failed to write log file header");
        fclose(log_file);
        teardown_gpio();
        return 1;
    }

    fd_i2c = open("/dev/i2c-1", O_RDWR);
    if (fd_i2c < 0) {
        perror("Failed to open I2C device");
        fclose(log_file);
        teardown_gpio();
        return 1;
    }

    while (1) {
        ret = i2c_smbus_read_word_data(fd_i2c, 0x1e << 1);
        if (ret < 0) {
            perror("Failed to read temperature");
            continue;
        }

        temp = (double)ret / 100.0;
        if (temp < TEMP_THRESHOLD_LOW || temp > TEMP_THRESHOLD_HIGH) {
            perror("Temperature out of range");
            continue;
        }

        ret = gpiod_line_set_value(line, !!(uint32_t)map_temperature(temp));
        if (ret < 0) {
            perror("Failed to set PWM duty cycle");
            continue;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        if (fprintf(log_file, "%lld,%.1f,%.0f\n", ts.tv_sec, temp, map_temperature(temp)) < 0) {
            perror("Failed to write log file row");
            continue;
        }

        sleep(5);
    }

    close(fd_i2c);
    fclose(log_file);
    teardown_gpio();

    return 0;
}

