{
    int retries = 0;
    uint8_t buf[len + 1];
    int i2c_result;

    while (retries < MAX_I2C_RETRIES) {
        i2c_result = i2c_smbus_read_i2c_block_data(i2c_fd, addr << 1 | (reg & 1), len, buf);
        if (i2c_result == len) {
