#include <time.h>
#include <errno.h>
#include <gpiod.h>
#include <pthread.h>

#define GPIO_BASE 17
#define NUM_BITS 2
#define DEGREES_PER_PULSE 360.0 / 12

gpiod_line_request_lines_data_v1 lines_data = {
    .lines = (const gpiod_line_info_v1*) malloc(NUM_BITS * sizeof(gpiod_line_info_v1)),
};

void cleanup(int status) {
    gpiod_line_release_request(lines_data.request);
    free(lines_data.lines);
    exit(status);
}

void log_position(double position) {
    char timestamp[20];
    time_t rawtime;
    struct tm * timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s: Position: %.2f degrees\n", timestamp, position);

    FILE * file = fopen("encoder_log.txt", "a");
    if (file == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    fprintf(file, "%s: Position: %.2f degrees\n", timestamp, position);
    fclose(file);
}

void* encoder_thread(void* arg) {
    int state = 0;
    double position = 0.0;

    while (1) {
        gpiod_line_get_value_async(lines_data.lines[0].line, NULL, NULL);
        gpiod_line_get_value_async(lines_data.lines[1].line, NULL, NULL);
        pthread_testcancel();

        gpiod_line_get_value_data_v1 data0, data1;
        gpiod_line_get_value_sync(lines_data.lines[0].line, &data0);
        gpiod_line_get_value_sync(lines_data.lines[1].line, &data1);

        if (data0.value == 0 && data1.value == 1) {
            state = (state + 1) & 3;
            position += DEGREES_PER_PULSE * (state + 1);
            log_position(position);
        }
    }

    return NULL;
}

int main() {
    int ret;

    ret = gpiod_library_open();
    if (ret < 0) {
        perror("gpiod_library_open");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_chip_open_by_name("gpiochip0");
    if (ret < 0) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < NUM_BITS; i++) {
        lines_data.lines[i].request_flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ENABLED | GPIOD_LINE_REQUEST_ACTIVE_HIGH;
        lines_data.lines[i].consumer = "encoder";
        lines_data.lines[i].line = gpiod_chip_get_line_byname(lines_data.request, gpio_get_label(GPIO_BASE + i));

        if (lines_data.lines[i].line < 0) {
            perror("gpiod_chip_get_line_byname");
            exit(EXIT_FAILURE);
        }
    }

    ret = gpiod_line_request_dbus(lines_data.request, lines_data.lines, NUM_BITS);
    if (ret < 0) {
        perror("gpiod_line_request_dbus");
        exit(EXIT_FAILURE);
