    ret = pthread_create(&thread_id, NULL, encoder_thread, NULL);
    if (ret != 0) {
        perror("pthread_create");
        exit(EXIT_FAILURE);
    }

    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    ret = sigaction(SIGINT, &sa, NULL);
    if (ret != 0) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }
    ret = sigaction(SIGTERM, &sa, NULL);
    if (ret != 0) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    pthread_join(thread_id, NULL);

    ret = gpiod_line_release_request(lines_data.request);
    if (ret < 0) {
        perror("gpiod_line_release_request");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_library_close();
    if (ret < 0) {
        perror("gpiod_library_close");
        exit(EXIT_FAILURE);
    }

