#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <pthread.h>
#include <libgpiod.h>

#define GPIO_LINE_SENSOR 18
#define LOG_FILE "rpm_log.txt"
#define SAMPLES_PER_SECOND 100
#define ONE_SECOND (1000 * SAMPLES_PER_SECOND)

gpiod_line_request_lines_data_v1 lines_data = {
    .lines = (const gpiod_line_info_v1[]) {
        {
            .consumer = "RPM sensor",
            .direction = GPIOD_LINE_INPUT,
            .debounce = 10,
            .active_low = 1,
        },
    },
    .n_lines = 1,
};

pthread_mutex_t counter_mutex = PTHREAD_MUTEX_INITIALIZER;
unsigned long long pulse_counter = 0;

void isr(struct gpiod_line_event *event) {
    if (event->value == 0) {
        pthread_mutex_lock(&counter_mutex);
        pulse_counter++;
        pthread_mutex_unlock(&counter_mutex);
    }
}

void log_rpm(double rpm) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    fprintf(log_file, "%s, %lf RPM\n", timestamp, rpm);
    fflush(log_file);
    fclose(log_file);
}

void signal_handler(int sig) {
    gpiod_line_request_release(lines_data.lines[GPIO_LINE_SENSOR].request);
    pthread_mutex_destroy(&counter_mutex);
    remove(LOG_FILE);
    exit(0);
}

int main() {
    struct timespec start, end;
    double rpm;

    if (gpiod_library_open() < 0) {
        perror("gpiod_library_open");
        return 1;
    }

    gpiod_line_request_set_cb(lines_data.lines[GPIO_LINE_SENSOR].request, GPIOD_LINE_EVENT_RISING, isr);
    if (gpiod_line_request_validate(lines_data.lines[GPIO_LINE_SENSOR].request) < 0) {
        perror("gpiod_line_request_validate");
        goto cleanup;
    }
    if (gpiod_line_request_activate(lines_data.lines[GPIO_LINE_SENSOR].request) < 0) {
        perror("gpiod_line_request_activate");
        goto cleanup;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    clock_gettime(CLOCK_MONOTONIC, &start);
    while (clock_gettime(CLOCK_MONOTONIC, &end) - (end.tv_sec - start.tv_sec) < ONE_SECOND) {
        pthread_mutex_lock(&counter_mutex);
        unsigned long long current_counter = pulse_counter;
        pthread_mutex_unlock(&counter_mutex);

        rpm = (double)current_counter * SAMPLES_PER_SECOND / ONE_SECOND;
        log_rpm(rpm);
    }

    log_rpm(0.0);

cleanup:
    gpiod_line_request_release(lines_data.lines[GPIO_LINE_SENSOR].request);
    pthread_mutex_destroy(&counter_mutex);
    remove(LOG_FILE);

    return 0;
}

