#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define FLOW_SENSOR_REG_RAW_DATA 0x00
#define FLOW_SENSOR_REG_CRC 0x01
#define FLOW_SENSOR_CRC_POLYNOMIAL 0x31
#define FLOW_SENSOR_CRC_INIT 0x00

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int nlines,
                                const char *const names, unsigned int flags)
{
    return gpiod_chip_get_lines_request_array(chip, nlines, names, flags);
}

int main(void)
{
    int i2c_fd, ret;
    struct i2c_rdwr_ioctl_data i2c_data;
    uint8_t raw_data[3];
    uint16_t flow_rate;
    time_t timestamp;
    FILE *log_file;
    char log_filename[] = "flow_log.csv";

    // Initialize GPIO
    struct gpiod_chip *chip;
    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    // Request GPIO line for resetting the flow sensor
    gpiod_line_request_lines(chip, 1, "flow_sensor_reset", GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW);
    gpiod_line_get_value(chip->lines[0]); // Get initial state of the line

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        goto cleanup_gpio;
    }

    // Initialize I2C data structure
    i2c_data.wr_buf = &FLOW_SENSOR_REG_RAW_DATA;
    i2c_data.wr_len = 1;
    i2c_data.rd_buf = raw_data;
    i2c_data.rd_len = 3;

    log_file = fopen(log_filename, "a");
    if (!log_file) {
        perror("Failed to open log file");
        goto cleanup_i2c;
    }

    while (1) {
        // Reset the flow sensor
        gpiod_line_set_value(chip->lines[0], 0);
        usleep(10000);
        gpiod_line_set_value(chip->lines[0], 1);

        // Perform I2C read operation
        ret = ioctl(i2c_fd, I2C_RDWR, &i2c_data);
        if (ret < 0) {
            perror("Failed to read from I2C device");
            continue;
        }

        // Validate CRC
        uint8_t crc = raw_data[2];
        uint8_t calculated_crc = 0;
        for (size_t i = 0; i < 2; ++i) {
            calculated_crc = (calculated_crc >> 1) ^ (calculated_crc & 1 ? FLOW_SENSOR_CRC_POLYNOMIAL : 0) ^ (raw_data[i] >> 7);
        }
        if (calculated_crc != crc) {
            fprintf(stderr, "CRC validation failed\n");
            continue;
        }

        // Extract flow rate
        flow_rate = (raw_data[0] << 8) | raw_data[1];

        // Log the flow rate
        time(&timestamp);
        fprintf(log_file, "%.4s,%.3f\n", ctime(&timestamp), (float)flow_rate / 1000.0);
        fflush(log_file);
    }

cleanup_i2c:
    close(i2c_fd);

cleanup_gpio:
    gpiod_chip_release_lines(chip, 1);
    gpiod_chip_close(chip);

    fclose(log_file);

    return 0;
}

