I'll provide a basic example using the libgpiod library. This code should give you a good starting point for your project. Please note that you'll need to install the libgpiod-dev package on your Raspberry Pi to compile this code.

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <time.h>
#include <errno.h>
#include <linux/types.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define TTP223_GPIO 17
#define SENSOR_DEBOUNCE_MS 100
#define INTRUSION_THRESHOLD_S 5
#define MAX_INTRUSION_COUNT 60

struct gpiod_line_request_data ttp223_line_data;
struct gpiod_line *ttp223_line;
struct timespec intrusion_start_time;
int intrusion_count = 0;

int init_gpio() {
    int ret;
    gpiod_line_request_config config = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_RISING | GPIOD_LINE_REQUEST_ACTIVE_LOW;

    ttp223_line = gpiod_get_line_byname("ttp223_tamper");
    if (!ttp223_line) {
        perror("gpiod_get_line_byname");
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_dt(ttp223_line, 0, &config, &ttp223_line_data);
    if (ret < 0) {
        perror("gpiod_line_request_dt");
        goto cleanup;
    }

    return 0;

cleanup:
    gpiod_line_release(ttp223_line);
    return EXIT_FAILURE;
}

void cleanup() {
    if (ttp223_line) {
        gpiod_line_release(ttp223_line);
        ttp223_line = NULL;
    }
}

int main() {
    int ret;
    struct timespec current_time;
    clock_gettime(CLOCK_MONOTONIC, &intrusion_start_time);

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        if (current_time.tv_sec - intrusion_start_time.tv_sec > INTRUSION_THRESHOLD_S) {
            printf("Intrusion alert\n");
            intrusion_count++;
            intrusion_start_time = current_time;
            if (intrusion_count > MAX_INTRUSION_COUNT) {
                printf("Maximum intrusion count reached, exiting\n");
                cleanup();
                return EXIT_FAILURE;
            }
        }

        ret = gpiod_line_get_value(ttp223_line);
        if (ret < 0) {
            perror("gpiod_line_get_value");
            cleanup();
            return EXIT_FAILURE;
        }

        if (ret == 0) {
            clock_gettime(CLOCK_MONOTONIC, &intrusion_start_time);
            intrusion_count = 0;
        }

        usleep(SENSOR_DEBOUNCE_MS * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}
```

This code initializes the TTP223B sensor, continuously monitors its state, and prints an intrusion alert if the sensor remains HIGH for more than 5 seconds. It also debounces the sensor readings by waiting 100ms between each read. The program exits gracefully when it receives a SIGINT or SIGTERM signal and releases the GPIO line.

