#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <alsa/asoundlib.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <sys/ioctl.h>
#include <gpiod.h>

#define GPIO_LINE_L 17

static int gpio_line_fd;
static struct gpiod_line_request *gpio_line_req;

static int i2s_fd;
static snd_pcm_t *handle;
static snd_pcm_uframes_t frames;
static unsigned char *buffer;

void gpio_line_cb(struct gpiod_line_event *ev) {
    if (ev->value) {
        gpiod_line_set_value(gpio_line_req, 0);
    } else {
        gpiod_line_set_value(gpio_line_req, 1);
    }
}

int init_gpio() {
    gpio_line_fd = open("/dev/gpiochip0", O_RDWR | O_NONBLOCK);
    if (gpio_line_fd < 0) {
        perror("Failed to open gpiochip0");
        return -1;
    }

    gpio_line_req = gpiod_chip_get_line_request(gpio_line_fd, GPIO_LINE_L);
    if (!gpio_line_req) {
        perror("Failed to get line request for GPIO_LINE_L");
        close(gpio_line_fd);
        return -1;
    }

    gpiod_line_request_direction_input(gpio_line_req);
    gpiod_line_request_edge_both_active(gpio_line_req);
    gpiod_line_request_callback(gpio_line_req, GPIO_LINE_EDGE_FALLING, gpio_line_cb, NULL);

    return 0;
}

int init_i2s() {
    if ((i2s_fd = open("/dev/snd/pcmC0D0c", O_RDWR | O_NONBLOCK)) < 0) {
        perror("Failed to open I2S device");
        return -1;
    }

    if (snd_pcm_open(&handle, i2s_fd, SNDRV_PCM_STREAM_CAPTURE, 0) < 0) {
        perror("Failed to open PCM device");
        close(i2s_fd);
        return -1;
    }

    if (snd_pcm_nonblock(handle, 1) < 0) {
        perror("Failed to set non-blocking mode");
        snd_pcm_close(handle);
        close(i2s_fd);
        return -1;
    }

    if (snd_pcm_hw_params_any(handle, NULL) < 0) {
        perror("Failed to initialize hardware parameters");
        snd_pcm_close(handle);
        close(i2s_fd);
        return -1;
    }

    frames = snd_pcm_hw_params_buffer_size(handle);
    buffer = mmap(NULL, frames * sizeof(unsigned char) * 2, PROT_READ | PROT_WRITE, MAP_SHARED, i2s_fd, 0);
    if (buffer == MAP_FAILED) {
        perror("Failed to mmap buffer");
        snd_pcm_close(handle);
        close(i2s_fd);
        return -1;
    }

    if (snd_pcm_hw_params(handle, NULL) < 0) {
        perror("Failed to set hardware parameters");
        munmap(buffer, frames * sizeof(unsigned char) * 2);
        snd_pcm_close(handle);
        close(i2s_fd);
        return -1;
    }

    return 0;
}

void cleanup() {
    if (handle) {
        snd_pcm_drain(handle);
        snd_pcm_close(handle);
    }

    if (i2s_fd >= 0) {
        close(i2s_fd);
    }

    if (gpio_line_req) {
        gpiod_line_release(gpio_line_req);
    }

    if (gpio_line_fd >= 0) {
        close(gpio_line_fd);
    }

    if (buffer) {
        munmap(buffer, frames * sizeof(unsigned char) * 2);
    }
}

void signal_handler(int sig) {
    printf("Received SIGINT, exiting gracefully...\n");
    cleanup();
    exit(0);
}

int main() {
    signal(SIGINT, signal_handler);

    if (init_gpio() < 0) {
        return -1;
    }

    if (init_i2s() < 0) {
        cleanup();
        return -1;
    }

    while (1) {
        if (snd_pcm_readi(handle, buffer, frames) != frames) {
            perror("Failed to read from I2S device");
        } else {
            int fd = open("audio_capture.pcm", O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR);
            if (fd >= 0) {
                write(fd, buffer, frames * sizeof(unsigned char) * 2);
                close(fd);
            } else {
                perror("Failed to open or write to audio file");
            }
        }
    }

    return 0;
}

