#include <time.h>
#include <sys/time.h>
#include <errno.h>
#include <pthread.h>
#include <libgpiod.h>

#define GPIO_FLAME_SENSOR 4
#define GPIO_FAN 18
#define TIMEOUT_MS 1000
#define PWM_PERIOD_NS 10000000
#define PWM_DUTY_NS 0

static gpiod_line_request_lines_data_t flame_sensor_request_data = { .flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_DEBOUNCE };
static gpiod_line_request_lines_data_t fan_request_data = { .flags = GPIOD_LINE_REQUEST_OUTPUT };
static gpiod_line_handle_t flame_sensor_handle = GPIOD_INVALID_HANDLE;
static gpiod_line_handle_t fan_handle = GPIOD_INVALID_HANDLE;
static int flame_detected = 0;
static pthread_t log_thread;
static FILE *log_file;

void log_event(const char *event) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(time_str, sizeof(time_str), "%Y-%m-%dT%H:%M:%S.000Z", timeinfo);
    fprintf(log_file, "%s: %s\n", time_str, event);
}

void flame_sensor_cb(struct gpiod_line_event *event) {
    if (event->value == 0) {
        flame_detected = 1;
        log_event("Flame detected");
    }
}

void fan_pwm(int duty_ns) {
    struct gpiod_line_data data = { .value = duty_ns ? 1 : 0 };
    gpiod_line_set_value(fan_handle, data);
}

void flame_sensor_init() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line_request *request;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        exit(EXIT_FAILURE);
    }

    request = gpiod_chip_get_line_request(chip, GPIO_FLAME_SENSOR);
    if (!request) {
        perror("Failed to get line request for GPIO_FLAME_SENSOR");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_configure_async(request, &flame_sensor_request_data, flame_sensor_cb, NULL);
    if (ret < 0) {
        perror("Failed to configure flame sensor line");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_enable(request);
    if (ret < 0) {
        perror("Failed to enable flame sensor line");
        exit(EXIT_FAILURE);
    }

    flame_sensor_handle = gpiod_line_get_handle(request);
}

void fan_init() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line_request *request;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        exit(EXIT_FAILURE);
    }

    request = gpiod_chip_get_line_request(chip, GPIO_FAN);
    if (!request) {
        perror("Failed to get line request for GPIO_FAN");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_configure_async(request, &fan_request_data, NULL, NULL);
    if (ret < 0) {
        perror("Failed to configure fan line");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_enable(request);
    if (ret < 0) {
        perror("Failed to enable fan line");
        exit(EXIT_FAILURE);
    }

    fan_handle = gpiod_line_get_handle(request);
}

void log_init() {
    log_file = fopen("flame_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    log_event("System start");
}

void cleanup() {
    if (flame_sensor_handle != GPIOD_INVALID_HANDLE) {
        gpiod_line_request_dispose(gpiod_line_get_request(flame_sensor_handle));
    }

    if (fan_handle != GPIOD_INVALID_HANDLE) {
        gpiod_line_request_dispose(gpiod_line_get_request(fan_handle));
    }

    if (log_file) {
        fclose(log_file);
    }

    gpiod_chip_put(gpiod_chip_get_chip_data(gpiod_line_get_chip(flame_sensor_handle)));
    gpiod_chip_put(gpiod_chip_get_chip_data(gpiod_line_get_chip(fan_handle)));

    exit(0);
}

void* log_thread_func() {
    struct timespec ts = { .tv_sec = 0, .tv_nsec = 50000000 };

    while (1) {
        nanosleep(&ts, NULL);

        if (flame_detected) {
            fan_pwm(PWM_DUTY_NS);
        } else {
            fan_pwm(0);
        }

        if (flame_detected && gpiod_line_get_value(flame_sensor_handle) == 1) {
            log_event("Flame ended");
            flame_detected = 0;
        }

        if (gpiod_line_get_value(flame_sensor_handle) == -1) {
            log_event("Sensor absent");
            cleanup();
        }
    }

    return NULL;
}

int main() {
    int ret;
    struct timespec ts = { .tv_sec = 0, .tv_nsec = TIMEOUT_MS * 1000000 };

    flame_sensor_init();
    fan_init();
    log_init();

    if (pthread_create(&log_thread, NULL, log_thread_func, NULL) != 0) {
        perror("Failed to create log thread");
        cleanup();
    }

    while (1) {
        ret = gpiod_line_get_value(flame_sensor_handle);
        if (ret == -1) {
            nanosleep(&ts, NULL);
            continue;
        }

        if (ret == 0) {
            log_event("Flame detected");
            break;
        }
    }

    cleanup();

    return 0;
}

