```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <time.h>
#include <linux/types.h>
#include <gpiod.h>

#define TTP226_GPIO_BASE 2
#define NUM_SENSORS 8

static void gpiod_chip_exit(struct gpiod_chip *chip) {
    gpiod_chip_free(chip);
}

static void gpiod_line_exit(struct gpiod_line *line) {
    gpiod_line_put_request(line);
}

void handle_sigint(int signum) {
    printf("\nGracefully shutting down...\n");
    gpiod_chip_exit(chip);
    exit(0);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[NUM_SENSORS];
    int i;

    signal(SIGINT, handle_sigint);

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    for (i = 0; i < NUM_SENSORS; ++i) {
        lines[i] = gpiod_get_line_byname(chip, gpiod_get_line_label(chip, TTP226_GPIO_BASE + i));
        if (!lines[i]) {
            perror("Failed to get line");
            gpiod_chip_exit(chip);
            return 1;
        }

        gpiod_line_request_output_high(lines[i], GPIOD_LINE_REQUEST_DIRECTION_OUT);
    }

    while (1) {
        for (i = 0; i < NUM_SENSORS; ++i) {
            int value;
            if (gpiod_line_get_value(lines[i], &value)) {
                perror("Failed to read line");
                gpiod_chip_exit(chip);
                return 1;
            }

            printf("%d: %s\n", time(NULL), value ? "1" : "0");
        }
        usleep(100000);
    }

    for (i = 0; i < NUM_SENSORS; ++i) {
        gpiod_line_exit(lines[i]);
    }

    gpiod_chip_exit(chip);

    return 0;
}
```

This code opens the GPIO chip, requests the lines, sets them as outputs, and then continuously reads their values. It prints the timestamped binary state of each channel every 100ms. The program handles SIGINT (Ctrl+C) to perform a graceful shutdown and releases all resources on exit.

