#define GPIO_BUS_WIDTH 32
#define GPIO_LABEL_MAX_LEN 32

static gpiod_line_request_lines_data_v1 lines_data = {
    .lines = {
        { .direction = GPIOD_IN, .debounce = 10 },
        { .direction = GPIOD_IN, .debounce = 10 },
        { .direction = GPIOD_IN, .debounce = 10 },
        { .direction = GPIOD_IN, .debounce = 10 },
        { .direction = GPIOD_IN, .debounce = 10 },
        { .direction = GPIOD_IN, .debounce = 10 },
        { .direction = GPIOD_IN, .debounce = 10 },
        { .direction = GPIOD_IN, .debounce = 10 },
    }
};

static gpiod_line_request_lines_data_v1 *lines_data_ptr;
static gpiod_line_consumer *consumer;
static gpiod_line_handle *lines[8];

void sigint_handler(int signum) {
    gpiod_line_set_value(lines[0], 1);
    gpiod_line_put(lines[0]);
    exit(0);
}

void sigterm_handler(int signum) {
    gpiod_line_set_value(lines[0], 1);
    gpiod_line_put(lines[0]);
    exit(0);
}

int main() {
    int ret;
    gpiod_chip *chip;
    gpiod_line_request_lines_data_v1 *tmp_lines_data;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    tmp_lines_data = gpiod_line_request_data_v1_alloc(GPIO_BUS_WIDTH, GPIO_LABEL_MAX_LEN);
    if (!tmp_lines_data) {
        perror("Failed to allocate line request data");
        gpiod_chip_put(chip);
        return 1;
    }

    lines_data_ptr = tmp_lines_data;
    lines_data_ptr->request_lines = &lines_data.lines[0];
    lines_data_ptr->n_lines = 8;

    consumer = gpiod_chip_request_lines_data_v1(chip, lines_data_ptr);
    if (!consumer) {
        perror("Failed to request lines");
        gpiod_line_request_data_v1_free(tmp_lines_data);
        gpiod_chip_put(chip);
        return 1;
    }

    for (int i = 0; i < 8; ++i) {
        lines[i] = gpiod_consumer_get_line(consumer, i);
        if (!lines[i]) {
            perror("Failed to get line");
            gpiod_consumer_put(consumer);
            gpiod_line_request_data_v1_free(tmp_lines_data);
            gpiod_chip_put(chip);
            return 1;
        }
    }

    while (1) {
        for (int i = 0; i < 8; ++i) {
            ret = gpiod_line_get_value(lines[i]);
            if (ret < 0) {
                perror("Failed to get line value");
                gpiod_consumer_put(consumer);
                gpiod_line_request_data_v1_free(tmp_lines_data);
                gpiod_chip_put(chip);
                return 1;
            }

            printf("[+%6dms] CH%d=%d", usleep(100000), i + 1, ret);
        }
        printf("\n");
        usleep(100000);
    }

    for (int i = 0; i < 8; ++i) {
        gpiod_line_put(lines[i]);
    }
    gpiod_consumer_put(consumer);
    gpiod_line_request_data_v1_free(tmp_lines_data);
    gpiod_chip_put(chip);

    return 0;
}

