#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>
#include <time.h>
#include <sys/stat.h>
#include <sys/mman.h>

#define I2C_BUS 1
#define SENSOR_ADDR1 0x48
#define SENSOR_ADDR2 0x49
#define GPIO_LINE 17
#define FLOW_THRESHOLD 0.5
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

struct i2c_data {
    int fd;
    int crc;
};

void i2c_write_read(int fd, unsigned char reg, unsigned char *data, int len) {
    char buf[len + 2];
    buf[0] = reg;
    for (int i = 0; i < len; i++)
        buf[i + 1] = data[i];

    if (write(fd, buf, len + 1) != len + 1) {
        perror("I2C write error");
        exit(EXIT_FAILURE);
    }

    if (len > 1 && read(fd, buf, len) != len) {
        perror("I2C read error");
        exit(EXIT_FAILURE);
    }
}

unsigned char crc8(unsigned char *data, int len) {
    unsigned char crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        for (int j = 8; j > 0; j--) {
            crc = (crc >> 1) ^ (crc & 0x01 ? CRC_POLYNOMIAL : 0);
            crc = (crc & 0x0F0) | ((crc << 4) & 0xF00);
            crc = data[i] ^ (crc & 0x0F);
        }
    }
    return crc;
}

bool is_valid_crc(unsigned char *data, int len) {
    return crc8(data, len) == data[len];
}

void log_flow_rate(double flow_rate) {
    FILE *log_file = fopen("flow_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(log_file, "%s: %.3f ml/min\n", timestamp, flow_rate);
    fclose(log_file);
}

void gpio_setup(int gpio_line) {
    struct gpiod_line_request request = {
        .consumer = "Flow Sensor Alarm",
        .flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW,
    };
    struct gpiod_line *line = gpiod_get_line(0, "gpiochip0", GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_dump(line, &request) < 0) {
        perror("Failed to request GPIO line");
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(line, 1);
}

void gpio_cleanup(int gpio_line) {
    struct gpiod_line *line = gpiod_get_line(0, "gpiochip0", GPIO_LINE);
    if (line) {
        gpiod_line_release(line);
    }
}

int main(int argc, char *argv[]) {
    int i2c_fd[2];
    struct i2c_data sensors[2];
    struct timespec delay = {0, 100 * 1000 * 1000};

    if (argc != 2 || strcmp(argv[1], "start") != 0) {
        fprintf(stderr, "Usage: %s start\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    if (i2c_open(I2C_BUS, &i2c_fd[0]) < 0 || i2c_open(I2C_BUS, &i2c_fd[1]) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < 2; i++) {
        i2c_write_read(i2c_fd[i], 0x00, NULL, 0);
        usleep(100000);
        i2c_write_read(i2c_fd[i], 0x01, NULL, 0);
        usleep(100000);
        sensors[i].fd = i2c_fd[i];
    }

    gpio_setup(GPIO_LINE);
    double total_flow_rate = 0.0;
    int valid_reads = 0;
    while (true) {
        for (int i = 0; i < 2; i++) {
            unsigned char data[4];
            i2c_write_read(sensors[i].fd, 0x02, data, 4);

            if (is_valid_crc(data, 4)) {
                double flow_rate = (data[1] | data[2] << 8) / 10.0;
                total_flow_rate += flow_rate;
                valid_reads++;

                if (total_flow_rate / valid_reads < FLOW_THRESHOLD) {
                    gpiod_line_set_value(sensors[i].gpio_line, 0);
                } else {
                    gpiod_line_set_value(sensors[i].gpio_line, 1);
                }
            } else {
                fprintf(stderr, "Invalid CRC from sensor %d\n", i + 1);
            }
        }

        nanosleep(&delay, NULL);
        total_flow_rate /= 2.0;
        log_flow_rate(total_flow_rate);

        if (valid_reads == 2) {
            usleep(900 * 1000 * 1000);
            break;
        }
    }

    for (int i = 0; i < 2; i++) {
        close(sensors[i].fd);
        gpiod_line_release(sensors[i].gpio_line);
    }
    close(i2c_fd[0]);
    close(i2c_fd[1]);
    gpio_cleanup(GPIO_LINE);

    return 0;
}

