    if (i2c_open(I2C_BUS, &i2c_fd[0]) < 0 || i2c_open(I2C_BUS, &i2c_fd[1]) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < 2; i++) {
        i2c_write_read(i2c_fd[i], 0x00, NULL, 0);
        usleep(100000);
        i2c_write_read(i2c_fd[i], 0x01, NULL, 0);
        usleep(100000);
        sensors[i].fd = i2c_fd[i];
    }

    gpio_setup(GPIO_LINE);
    double total_flow_rate = 0.0;
    int valid_reads = 0;
    while (true) {
        for (int i = 0; i < 2; i++) {
            unsigned char data[4];
            i2c_write_read(sensors[i].fd, 0x02, data, 4);

            if (is_valid_crc(data, 4)) {
                double flow_rate = (data[1] | data[2] << 8) / 10.0;
                total_flow_rate += flow_rate;
                valid_reads++;

                if (total_flow_rate / valid_reads < FLOW_THRESHOLD) {
                    gpiod_line_set_value(sensors[i].gpio_line, 0);
                } else {
                    gpiod_line_set_value(sensors[i].gpio_line, 1);
                }
            } else {
                fprintf(stderr, "Invalid CRC from sensor %d\n", i + 1);
            }
        }

        nanosleep(&delay, NULL);
        total_flow_rate /= 2.0;
        log_flow_rate(total_flow_rate);

        if (valid_reads == 2) {
            usleep(900 * 1000 * 1000);
            break;
        }
    }

    for (int i = 0; i < 2; i++) {
        close(sensors[i].fd);
        gpiod_line_release(sensors[i].gpio_line);
    }
    close(i2c_fd[0]);
    close(i2c_fd[1]);
    gpio_cleanup(GPIO_LINE);

    return 0;
}
```

This code assumes that the Sensirion SLF3S-0600F Liquid Flow Sensors are connected to the I2C bus on the Raspberry Pi and that the GPIO17 (BCM) pin is configured as an output. The program starts by opening the I2C bus and initializing the sensors, then enters a loop where it reads the flow rates from both sensors, calculates the average, logs the average to a file, and drives the alarm based on the average flow rate. The program handles errors during I2C communication and CRC validation by logging the error and skipping the sensor's reading for that cycle.

In case of a SIGINT or SIGTERM signal, the program releases the GPIO line, closes the I2C file descriptors, and the log file before exiting.

