#define GPIO_LINE_ID 4
#define BUFFER_SIZE 100

struct detection_t {
    time_t timestamp;
    int value;
};

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_request request;
    struct detection_t buffer[BUFFER_SIZE];
    size_t buffer_head = 0;
    size_t buffer_tail = 0;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0\n");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_ID);
    if (!line) {
        fprintf(stderr, "Failed to get line %d\n", GPIO_LINE_ID);
        gpiod_chip_put(chip);
        return 1;
    }

    memset(&request, 0, sizeof(request));
    request.consumer = "obstacle_sensor";
    request.flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_HIGH;
    request.debounce = 10; // debounce delay in milliseconds

    if (gpiod_line_request_dump(line, &request) < 0) {
