        int value;
        if (gpiod_line_get_value(line, &value) < 0) {
            fprintf(stderr, "Failed to get value from line %d\n", GPIO_LINE_ID);
            break;
        }

        if (!value) {
            buffer[buffer_head].timestamp = time(NULL);
            buffer[buffer_head].value = value;
            buffer_head = (buffer_head + 1) % BUFFER_SIZE;
            printf("Obstacle detected at %s\n", ctime(&buffer[buffer_head].timestamp));
        }

        usleep(50000); // 50ms delay
    }

    gpiod_line_release(line);
    gpiod_chip_put(chip);

    size_t buffer_size = (buffer_head + BUFFER_SIZE - buffer_tail) % BUFFER_SIZE;
    for (size_t i = buffer_tail; i < buffer_size; ++i) {
        printf("Obstacle detected at %s", ctime(&buffer[i].timestamp));
        if (i + 1 < buffer_size)
            printf("  (next detection at %s)\n", ctime(&buffer[i + 1].timestamp));
        else
            printf("\n");
    }

    return 0;
}

