#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/time.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define I2C_BUS 1
#define SDA_GPIO 2
#define SCL_GPIO 3
#define I2C_ADDR 0x6C
#define SAMPLE_INTERVAL_MS 500
#define ACTIVATION_TIMEOUT_MS 1000
#define BUFFER_SIZE 6

static const char *csv_file = "fan_health.csv";

int main(void) {
    int i2c_fd, gpio_fd, ret;
    struct timespec activation_timeout;
    struct i2c_rdwr_ioctl_data i2c_msg[2];
    uint8_t mode_data[] = {0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    uint8_t data_buffer[BUFFER_SIZE];
    struct gpiod_line *sda_line, *scl_line;
    FILE *csv_file_ptr;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    // Initialize I2C and GPIO
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (gpiod_library_open() < 0) {
        perror("Failed to open GPIO library");
        close(i2c_fd);
        return 1;
    }

    sda_line = gpiod_get_line_byname("gpio" SDA_GPIO);
    scl_line = gpiod_get_line_byname("gpio" SCL_GPIO);
    if (!sda_line || !scl_line) {
        perror("Failed to get GPIO lines");
        gpiod_library_close();
        close(i2c_fd);
        return 1;
    }

    // Set SDA and SCL as output
    gpiod_line_request_output(sda_line, "i2c_sda", GPIOD_LINE_ACTIVE_LOW);
    gpiod_line_request_output(scl_line, "i2c_scl", GPIOD_LINE_ACTIVE_HIGH);

    // Set I2C speed to 400kHz
    ret = ioctl(i2c_fd, I2C_SET_SPEED, 400);
    if (ret < 0) {
        perror("Failed to set I2C speed");
        gpiod_line_release(sda_line);
        gpiod_line_release(scl_line);
        gpiod_library_close();
        close(i2c_fd);
        return 1;
    }

    // Switch sensor to the appropriate mode
    i2c_msg[0].addr = I2C_ADDR;
    i2c_msg[0].flags = 0;
    i2c_msg[0].len = sizeof(mode_data);
    i2c_msg[0].buf = mode_data;

    i2c_msg[1].addr = I2C_ADDR;
    i2c_msg[1].flags = I2C_M_RD;
    i2c_msg[1].len = 0;
    i2c_msg[1].buf = NULL;

    ret = i2c_rdwr_ioctl(i2c_fd, ARRAY_SIZE(i2c_msg), i2c_msg);
    if (ret < 0) {
        perror("Failed to send I2C command");
        gpiod_line_release(sda_line);
        gpiod_line_release(scl_line);
        gpiod_library_close();
        close(i2c_fd);
        return 1;
    }

    // Wait for the sensor to become active
    activation_timeout.tv_sec = ACTIVATION_TIMEOUT_MS / 1000;
    activation_timeout.tv_nsec = (ACTIVATION_TIMEOUT_MS % 1000) * 1000000;
    nanosleep(&activation_timeout, NULL);

    // Check if the sensor became active
    if (i2c_msg[1].len == 0) {
        fprintf(stderr, "Sensor did not become active within the one-second window\n");
        goto cleanup;
    }

    // Open CSV file and write header row
    csv_file_ptr = fopen(csv_file, "w");
    if (!csv_file_ptr) {
        perror("Failed to open CSV file");
        goto cleanup;
    }

    fprintf(csv_file_ptr, "timestamp,X,Y,Z\n");

    // Main loop
    while (1) {
        // Read acceleration registers
        i2c_msg[1].len = BUFFER_SIZE;
        i2c_msg[1].buf = data_buffer;

        ret = i2c_rdwr_ioctl(i2c_fd, ARRAY_SIZE(i2c_msg), i2c_msg);
        if (ret < 0) {
            perror("Failed to read I2C data");
            continue;
        }

        // Format and write timestamp and sensor data to CSV file
        rawtime = time(NULL);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%f", timeinfo);
        fprintf(csv_file_ptr, "%s,%d,%d,%d\n", timestamp, data_buffer[0], data_buffer[1], data_buffer[2]);

        // Sleep for the specified interval
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

cleanup:
    // Close CSV file
    if (csv_file_ptr) fclose(csv_file_ptr);

    // Release GPIO lines
    gpiod_line_release(sda_line);
    gpiod_line_release(scl_line);

    // Close I2C device
    close(i2c_fd);

    // Close GPIO library
    gpiod_library_close();

    return 0;
}

