#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/gpio/consumer.h>
#include <sys/ioctl.h>

#define SENSOR1_GPIO 23
#define SENSOR2_GPIO 24
#define LED_GPIO 25

int main(void) {
    int ret;
    int sensor1_fd, sensor2_fd, led_fd;
    struct gpiod_line_request sensor1_req, sensor2_req, led_req;

    // Initialize the GPIO library
    if (gpiod_library_get("gpiochip0") < 0) {
        perror("Failed to initialize GPIO library");
        return 1;
    }

    // Request the sensor and LED lines
    sensor1_req.flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_FALLING;
    sensor1_req.consumer = "obstacle_avoidance";
    ret = gpiod_chip_request_line(sensor1_fd, SENSOR1_GPIO, &sensor1_req);
    if (ret < 0) {
        perror("Failed to request sensor1 line");
        goto cleanup;
    }

    sensor2_req.flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_FALLING;
    sensor2_req.consumer = "obstacle_avoidance";
    ret = gpiod_chip_request_line(sensor1_fd, SENSOR2_GPIO, &sensor2_req);
    if (ret < 0) {
        perror("Failed to request sensor2 line");
        goto cleanup;
    }

    led_req.flags = GPIOD_LINE_REQUEST_OUTPUT;
    led_req.consumer = "obstacle_avoidance";
    ret = gpiod_chip_request_line(sensor1_fd, LED_GPIO, &led_req);
    if (ret < 0) {
        perror("Failed to request LED line");
        goto cleanup;
    }

    // Set the LED to off
    gpiod_line_set_value(led_fd, 0);

    // Main loop
    while (1) {
        int sensor1_value, sensor2_value;

        // Read the sensor values
        if (gpiod_line_get_value_cansleep(sensor1_fd, &sensor1_value) < 0) {
            perror("Failed to read sensor1 value");
            goto cleanup;
        }
        if (gpiod_line_get_value_cansleep(sensor2_fd, &sensor2_value) < 0) {
            perror("Failed to read sensor2 value");
            goto cleanup;
        }

        // Check if an obstacle is detected
        if (sensor1_value == 0 || sensor2_value == 0) {
            // Turn on the LED
            gpiod_line_set_value(led_fd, 1);
        } else {
            // Turn off the LED
            gpiod_line_set_value(led_fd, 0);
        }

        // Sleep for 100ms
        usleep(100000);
    }

cleanup:
    // Release the resources
    if (led_fd >= 0) {
        gpiod_line_release(led_fd);
        led_fd = -1;
    }
    if (sensor2_fd >= 0) {
        gpiod_line_release(sensor2_fd);
        sensor2_fd = -1;
    }
    if (sensor1_fd >= 0) {
        gpiod_line_release(sensor1_fd);
        sensor1_fd = -1;
    }

    // Cleanup the GPIO library
    gpiod_library_put(sensor1_fd);

    // Exit the program
    return 0;
}

