            } else {
                if (stalled) {
                    struct timespec diff;
                    timespec_sub(now, last_stall_time, diff);

                    if (diff.tv_sec + diff.tv_nsec >= STALL_DURATION * 1_ billion) {
                        stalled = 0;
                        last_stall_time = {0};
                    }
                }
            }
        } else {
            stalled = 0;
            last_stall_time = {0};
