#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <sys/time.h>
#include <errno.h>
#include <string.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define TMAG5170_ADDR 0x1E
#define TMAG5170_REG_CONFIG 0x0F
#define TMAG5170_REG_DATA_X 0x00
#define TMAG5170_REG_DATA_Y 0x02
#define TMAG5170_REG_DATA_Z 0x04
#define TMAG5170_RANGE_50mT 0x00
#define TMAG5170_CONTINUOUS_CONV 0x01

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int nlines,
                                const char *const *consumer, unsigned int flags) {
    return gpiod_chip_request_lines(chip, nlines, consumer, flags);
}

int main() {
    int i2c_fd, ret;
    struct i2c_rdwr_ioctl_data i2c_msg[3];
    struct timespec sleep_time = {0, 100 * 1000 * 1000};
    FILE *csv_file;
    char csv_filename[] = "magnetic_log.csv";
    char timestamp[32];
    uint8_t config_data = TMAG5170_CONTINUOUS_CONV | TMAG5170_RANGE_50mT;
    uint8_t data[3];

    // Initialize GPIO
    struct gpiod_chip *chip;
    gpiod_chip_open_by_name(&chip, "gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Request GPIO line for Ctrl-C handling
    int gpio_line = 18;
    ret = gpiod_line_request_line(chip, gpio_line, "magnetic_sensor_interrupt", GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_RISING);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpiod_line_release(chip, gpio_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize I2C messages
    i2c_msg[0].addr = TMAG5170_ADDR << 1;
    i2c_msg[0].flags = 0;
    i2c_msg[0].len = 1;
    i2c_msg[0].buf = &config_data;

    i2c_msg[1].addr = TMAG5170_ADDR << 1;
    i2c_msg[1].flags = I2C_M_RD;
    i2c_msg[1].len = 3;
    i2c_msg[1].buf = data;

    // Configure sensor
    ret = i2c_rdwr(i2c_fd, i2c_msg, 2);
    if (ret != 2) {
        perror("Failed to configure sensor");
        close(i2c_fd);
        gpiod_line_release(chip, gpio_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open CSV file
    csv_file = fopen(csv_filename, "a");
    if (!csv_file) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        gpiod_line_release(chip, gpio_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Write header row if the file is newly created
    if (ftell(csv_file) == 0) {
        fprintf(csv_file, "Time,X,Y,Z\n");
    }

    // Main loop
    while (1) {
        // Read sensor data
        ret = i2c_rdwr(i2c_fd, i2c_msg + 1, 1);
        if (ret != 1) {
            perror("Failed to read sensor data");
            continue;
        }

        // Format timestamp
        struct timeval tv;
        gettimeofday(&tv, NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%f", localtime(&tv.tv_sec));
        snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%06ld", tv.tv_usec);

        // Write data to CSV file
        fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, data[0], data[1], data[2]);

        // Sleep for 100ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    fclose(csv_file);
    close(i2c_fd);
    gpiod_line_release(chip, gpio_line);
    gpiod_chip_close(chip);

    return 0;
}

