#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <time.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <libgpiod.h>

#define SENSOR_GPIO 23
#define LOG_FILE "flood_log.txt"

static gpiod_line_request_lines_data_v1 lines_data = {
    .lines = (struct gpiod_line_request_data_v1[]) {
        {
            .consumer = "water_level_sensor",
            .direction = GPIOD_IN,
            .debounce = 100,
            .active_low = 1,
        },
    },
    .n_lines = 1,
};

static gpiod_line_handle *sensor_line;

void log_error(const char *message) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(stderr, "[%s] Error: %s\n", timestamp, message);
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s ALERT: %s\n", timestamp, message);
        fclose(log_file);
    }
}

void log_alert(const char *message) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(stdout, "[%s] ALERT: %s\n", timestamp, message);
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s ALERT: %s\n", timestamp, message);
        fclose(log_file);
    }
}

int init_gpio() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_context *ctx;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_error("Failed to open gpiochip0");
        return -1;
    }

    ctx = gpiod_context_allocate();
    if (!ctx) {
        gpiod_chip_put(chip);
        log_error("Failed to allocate context");
        return -1;
    }

    ret = gpiod_context_set_chip(ctx, chip);
    if (ret < 0) {
        gpiod_context_put(ctx);
        gpiod_chip_put(chip);
        log_error("Failed to set chip");
        return -1;
    }

    ret = gpiod_context_request_lines(ctx, &lines_data, GPIOD_CONTEXT_DIRECTION_IN);
    if (ret < 0) {
        gpiod_context_put(ctx);
        gpiod_chip_put(chip);
        log_error("Failed to request lines");
        return -1;
    }

    sensor_line = lines_data.lines;
    gpiod_context_put(ctx);
    gpiod_chip_put(chip);

    return 0;
}

void cleanup_gpio() {
    if (sensor_line) {
        gpiod_line_release(sensor_line);
        sensor_line = NULL;
    }
}

void signal_handler(int signum) {
    cleanup_gpio();
    exit(0);
}

int main() {
    int ret;
    struct timespec ts = {2, 0};
    int prev_state = 0;

    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        log_error("Failed to set signal handlers");
        return -1;
    }

    if (init_gpio() < 0) {
        log_error("Failed to initialize GPIO");
        return -1;
    }

    while (1) {
        int state = gpiod_line_get_value(sensor_line);
        if (state != prev_state) {
            if (state) {
                log_alert("Water detected");
            }
            prev_state = state;
        }
        nanosleep(&ts, NULL);
    }

    cleanup_gpio();
    return 0;
}

