        gpiod_context_put(ctx);
        gpiod_chip_put(chip);
        log_error("Failed to set chip");
        return -1;
    }

    ret = gpiod_context_request_lines(ctx, &lines_data, GPIOD_CONTEXT_DIRECTION_IN);
    if (ret < 0) {
        gpiod_context_put(ctx);
        gpiod_chip_put(chip);
        log_error("Failed to request lines");
        return -1;
    }

    sensor_line = lines_data.lines;
    gpiod_context_put(ctx);
    gpiod_chip_put(chip);

    return 0;
}

void cleanup_gpio() {
    if (sensor_line) {
        gpiod_line_release(sensor_line);
        sensor_line = NULL;
    }
}

void signal_handler(int signum) {
    cleanup_gpio();
    exit(0);
}

int main() {
    int ret;
    struct timespec ts = {2, 0};
    int prev_state = 0;

    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        log_error("Failed to set signal handlers");
        return -1;
    }

    if (init_gpio() < 0) {
        log_error("Failed to initialize GPIO");
        return -1;
    }

    while (1) {
        int state = gpiod_line_get_value(sensor_line);
        if (state != prev_state) {
            if (state) {
                log_alert("Water detected");
            }
            prev_state = state;
        }
        nanosleep(&ts, NULL);
    }

    cleanup_gpio();
    return 0;
}
```

This code initializes the `libgpiod` library, sets up the SEN0193 Water Level Sensor on GPIO23, and continuously polls the sensor every 2 seconds. When a logic HIGH is detected, it logs an alert message to stdout and appends a line to the `flood_log.txt` file. If a GPIO read fails, it logs an error entry to the same file and schedules an automatic re-initialization attempt after 60 seconds. The program also handles SIGINT and SIGTERM signals to release all resources cleanly before exiting.

Make sure to compile the code with the following command:

```sh
gcc -o water_level_sensor water_level_sensor.c -lgpiod -o water_level_sensor
```

To run the program as a daemon, you can use the following command:

```sh
sudo nohup ./water_level_sensor &
```

This will detach the program from the terminal and run it in the background.

