    .request_flags = GPIO_LINE_REQUEST_MAX_CONSUMERS,
};

static gpiod_line_data_t *gpio_line;
static int gpio_fd;
static volatile uint64_t pulse_counter = 0;
static struct timespec timer_interval = { .tv_sec = 1, .tv_nsec = 0 };
static struct itimerspec timer;

static void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        gpiod_line_remove_event_callback(gpio_line, &event_callback);
        timer.it_value.tv_sec = 0;
        timer.it_interval.tv_sec = 0;
        if (timerfd_settime(timer_fd, 0, &timer, NULL) == -1) {
            perror("timerfd_settime");
            exit(EXIT_FAILURE);
        }
        gpiod_line_release(gpio_line);
        gpiod_line_request_destroy(gpio_fd, &gpio_request_data);
        exit(EXIT_SUCCESS);
    }
}

static int log_rpm(const char *format, ...) {
    FILE *log_file = fopen("rpm_log.txt", "a");
    if (!log_file) {
        perror("fopen");
        return -1;
    }

    time_t rawtime;
    struct tm *time_info;
    char time_buffer[80];

    time(&rawtime);
    time_info = localtime(&rawtime);
    strftime(time_buffer, sizeof(time_buffer), format, time_info);

    va_list args;
    va_start(args, format);
    vfprintf(log_file, format, args);
    va_end(args);

    fflush(log_file);
    fclose(log_file);

    return 0;
}

static int event_callback(struct gpiod_line_event_data *data, void *user_data) {
    if (data->value == 0) {
        __sync_add_and_fetch(&pulse_counter, 1);
    }

    if (timerfd_settime(timer_fd, 0, &timer_interval, NULL) == -1) {
        perror("timerfd_settime");
        exit(EXIT_FAILURE);
    }

    return 0;
}

int main() {
    gpio_fd = gpiod_library_open();
    if (gpio_fd == -1) {
        perror("gpiod_library_open");
        exit(EXIT_FAILURE);
    }

    gpio_line = gpiod_chip_get_line(gpio_fd, "gpiochip0", 4);
    if (!gpio_line) {
        perror("gpiod_chip_get_line");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_get_dbus_name(gpio_line)) {
        if (gpiod_line_request_set_dbus_name(gpio_line, &gpio_request_data)) {
            perror("gpiod_line_request_set_dbus_name");
            exit(EXIT_FAILURE);
        }
    }

    if (gpiod_line_request_acquire(gpio_line, &gpio_request_data)) {
        perror("gpiod_line_request_acquire");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_enable_glitch_filter(gpio_line, 100000)) {
        perror("gpiod_line_enable_glitch_filter");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_enable_event_callback(gpio_line, &event_callback, NULL)) {
        perror("gpiod_line_request_enable_event_callback");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_set_active_low(gpio_line, 0)) {
        perror("gpiod_line_set_active_low");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_set_direction_input(gpio_line)) {
        perror("gpiod_line_set_direction_input");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_set_pull(gpio_line, GPIOD_PULL_UP)) {
        perror("gpiod_line_set_pull");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_enable_interrupt(gpio_line)) {
        perror("gpiod_line_request_enable_interrupt");
        exit(EXIT_FAILURE);
    }

    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);
    timer.it_value = now;

    timer_fd = timerfd_create(CLOCK_MONOTONIC, TFD_NONBLOCK | TFD_CLOEXEC);
    if (timer_fd == -1) {
        perror("timerfd_create");
        exit(EXIT_FAILURE);
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal");
        exit(EXIT_FAILURE);
    }

    while (1) {
        uint64_t rpm = (60 * (uint64_t)NSEC_PER_SEC * pulse_counter) / (now.tv_sec - timer.it_value.tv_sec);
        now = gpiod_get_monotonic_time(gpio_fd);
        timer.it_value = now;
        pulse_counter = 0;

        char rpm_str[32];
        snprintf(rpm_str, sizeof(rpm_str), "%lld\n", rpm);
        if (write(STDOUT_FILENO, rpm_str, strlen(rpm_str)) == -1) {
            perror("write");
        }

        if (log_rpm("YYYY-MM-DD HH:MM:SS %lld", rpm) == -1) {
            perror("log_rpm");
        }
    }

    return 0;
}

