code:
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <pthread.h>
#include <signal.h>
#include <libgpiod.h>

#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27
#define LOG_FILE "rotation_log.txt"

struct sensor_data {
    gpiod_line_request_linestate_cb_t cb;
    gpiod_line_request_data_t request_data[2];
    gpiod_line_data_t state[2];
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int direction;
    time_t last_event_time;
};

void signal_handler(int sig) {
    struct sensor_data *data = (struct sensor_data *) signal_ctx;

    pthread_mutex_lock(&data->mutex);
    data->direction = -1;
    pthread_cond_broadcast(&data->cond);
    pthread_mutex_unlock(&data->mutex);
}

void sensor_cb(struct gpiod_line_request *request, int event, void *user_data) {
    struct sensor_data *data = (struct sensor_data *) user_data;

    gpiod_line_get_value(request, &data->state[event]);

    pthread_mutex_lock(&data->mutex);
    if (data->state[0] != data->state[1]) {
        if (data->state[0] == 1 && data->state[1] == 0) {
            data->direction = 1;
        } else if (data->state[0] == 0 && data->state[1] == 1) {
            data->direction = -1;
        }
        data->last_event_time = time(NULL);
    }
    pthread_cond_signal(&data->cond);
    pthread_mutex_unlock(&data->mutex);
}

int main() {
    struct sensor_data data;
    int ret;
    FILE *log_file;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    pthread_mutex_init(&data.mutex, NULL);
    pthread_cond_init(&data.cond, NULL);

    data.direction = 0;
    data.last_event_time = 0;

    ret = gpiod_library_open();
    if (ret < 0) {
        perror("gpiod_library_open");
        goto cleanup;
    }

    data.request_data[0].flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_RISING | GPIOD_LINE_REQUEST_ACTIVE_LOW;
    data.request_data[1].flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_RISING | GPIOD_LINE_REQUEST_ACTIVE_LOW;

    ret = gpiod_chip_get_line_request_data_byname(gpiod_chip_get_default(), "gpio" SENSOR_A_GPIO, &data.request_data[0]);
    if (ret < 0) {
        perror("gpiod_chip_get_line_request_data_byname (A)");
        goto cleanup_libgpiod;
    }

    ret = gpiod_chip_get_line_request_data_byname(gpiod_chip_get_default(), "gpio" SENSOR_B_GPIO, &data.request_data[1]);
    if (ret < 0) {
        perror("gpiod_chip_get_line_request_data_byname (B)");
        goto cleanup_libgpiod;
    }

    data.cb = sensor_cb;

    ret = gpiod_line_request_set_callback(&data.request_data[0], &data.cb, &data);
    if (ret < 0) {
        perror("gpiod_line_request_set_callback (A)");
        goto cleanup_libgpiod;
    }

    ret = gpiod_line_request_set_callback(&data.request_data[1], &data.cb, &data);
    if (ret < 0) {
        perror("gpiod_line_request_set_callback (B)");
        goto cleanup_libgpiod;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen");
        goto cleanup_libgpiod;
    }

    while (1) {
        pthread_mutex_lock(&data.mutex);
        while (data.direction == 0) {
            pthread_cond_wait(&data.cond, &data.mutex);
        }
        pthread_mutex_unlock(&data.mutex);

        if (data.direction > 0) {
            char timestamp[32];
            struct tm *tm = localtime(&data.last_event_time);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%3d", tm);
            fprintf(log_file, "%s, Clockwise\n", timestamp);
        } else {
            char timestamp[32];
            struct tm *tm = localtime(&data.last_event_time);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%3d", tm);
            fprintf(log_file, "%s, Counter-Clockwise\n", timestamp);
        }

        fflush(log_file);
    }

cleanup_libgpiod:
    gpiod_line_request_set_callback(&data.request_data[0], NULL, NULL);
    gpiod_line_request_set_callback(&data.request_data[1], NULL, NULL);
    gpiod_library_close();

cleanup:
    pthread_mutex_destroy(&data.mutex);
    pthread_cond_destroy(&data.cond);
    fclose(log_file);

    return 0;
}

