#include <sys/stat.h>
#include <time.h>
#include <errno.h>
#include <linux/types.h>
#include <gpiod.h>
#include <syslog.h>
#include <signal.h>

#define SENSOR_LINE 23
#define LED_LINE 18
#define DEBOUNCE_MS 50
#define LOG_FACILITY LOG_USER

static gpiod_line_request_lines_data_t lines_data[] = {
    { .direction = GPIOD_IN, .edge_detected_callback = NULL },
    { .direction = GPIOD_OUT, .value = 0 },
};

static gpiod_line_request_lines_data_t *sensor_line_data = NULL;
static gpiod_line_request_lines_data_t *led_line_data = NULL;

static void sigint_handler(int signum) {
    gpiod_line_set_value(led_line_data, 0);
    gpiod_line_release(led_line_data);
    gpiod_line_request_free(sensor_line_data);
    gpiod_line_request_free(led_line_data);
    gpiod_chip_close(chip);
    exit(0);
}

int main(void) {
    int ret;
    struct timespec ts;
    gpiod_chip *chip;
    gpiod_line_request *sensor_line_req;
    gpiod_line_request *led_line_req;

    openlog("touch_led", LOG_PID | LOG_CONS, LOG_USER);

    syslog(LOG_INFO, "Starting touch_led");

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %m");
        exit(1);
    }

    sensor_line_data = &lines_data[SENSOR_LINE];
    led_line_data = &lines_data[LED_LINE];

    ret = gpiod_line_request_get(chip, SENSOR_LINE, sensor_line_data);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request sensor line %d: %m", SENSOR_LINE);
        goto cleanup;
    }

    ret = gpiod_line_request_get(chip, LED_LINE, led_line_data);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request LED line %d: %m", LED_LINE);
        goto cleanup;
    }

    sensor_line_req = sensor_line_data->request;
    led_line_req = led_line_data->request;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        gpiod_line_get_value(sensor_line_req);
        nanosleep((const struct timespec[]){{DEBOUNCE_MS * NANOSECONDS_PER_MILLISECOND, 0}}, &ts);
        if (gpiod_line_get_value(sensor_line_req)) {
            gpiod_line_set_value(led_line_req, 1);
            syslog(LOG_INFO, "Touch detected on sensor line %d", SENSOR_LINE);
        } else {
            gpiod_line_set_value(led_line_req, 0);
        }
    }

cleanup:
    gpiod_line_set_value(led_line_data, 0);
    gpiod_line_release(led_line_data);
    gpiod_line_request_free(sensor_line_data);
    gpiod_line_request_free(led_line_data);
    gpiod_chip_close(chip);
    closelog();
    return ret < 0 ? EXIT_FAILURE : EXIT_SUCCESS;
}
```

This code initializes the GPIO chip, requests the input line for the sensor and the output line for the LED, sets up SIGINT and SIGTERM handlers, and polls the sensor every 50ms. If the sensor is touched, it turns on the LED and logs the event to syslog. When the program receives SIGINT or SIGTERM, it turns off the LED and releases all resources before exiting.

