#define GPIO_TOUCH_LINE  17
#define GPIO_LED_LINE    18
#define DEBOUNCE_DELAY   50000  // Debounce delay in microseconds

static int touch_fd, led_fd;
static struct gpiod_line *touch_line, *led_line;

void die(const char *msg) {
    if (touch_line) gpiod_line_put_request(touch_line, 0);
    if (led_line) gpiod_line_put_request(led_line, 0);
    if (touch_fd >= 0) close(touch_fd);
    if (led_fd >= 0) close(led_fd);
    fprintf(stderr, "%s\n", msg);
    exit(EXIT_FAILURE);
}

int main(void) {
    int ret;

    touch_fd = gpiod_chip_open_with_label("gpiochip0");
    if (touch_fd < 0)
        die("Failed to open gpiochip0");

    ret = gpiod_chip_get_line_by_label(touch_fd, "gpio17");
    if (ret < 0)
        die("Failed to get line gpio17");
    touch_line = gpiod_line_request_one(ret, GPIOD_LINE_REQUEST_INPUT, "touch");
    if (!touch_line)
        die("Failed to request line gpio17");

    led_fd = gpiod_chip_open_with_label("gpiochip0");
    if (led_fd < 0)
        die("Failed to open gpiochip0");

    ret = gpiod_chip_get_line_by_label(led_fd, "gpio18");
    if (ret < 0)
        die("Failed to get line gpio18");
    led_line = gpiod_line_request_one(ret, GPIOD_LINE_REQUEST_OUTPUT, "led");
    if (!led_line)
        die("Failed to request line gpio18");

    gpiod_line_set_value(led_line, 0);

    struct timespec ts = {0, DEBOUNCE_DELAY};
    while (1) {
        ret = gpiod_line_get_value(touch_line);
        if (ret < 0)
            die("Failed to read line gpio17");

        if (ret == 1) {
            gpiod_line_set_value(led_line, 1);
            nanosleep(&ts, NULL);
            gpiod_line_set_value(led_line, 0);
        }

        sigset_t set;
        sigemptyset(&set);
        sigaddset(&set, SIGINT);
        sigaddset(&set, SIGTERM);
        sigsuspend(&set);
    }

    return EXIT_SUCCESS;
}

