#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <gpiod.h>

#define GPIO_LINE_RAIN_SENSOR 17
#define LOG_FILE "/var/log/rain_events.log"

static int gpio_fd;
static gpiod_line_request_lines_data_v1 lines_data = { .lines = { { .direction = GPIOD_IN, .edge_detected_callback = NULL, .debounce_timeout_ns = 10000000 } } };
static gpiod_line_handle_v1 *gpio_line_handle;

void gpio_line_cb(struct gpiod_line_request *request, struct gpiod_line *line, int value, unsigned long event_types) {
    if (value == 0) {
        log_event("Rain Detected");
    } else {
        log_event("No Rain");
    }
}

void log_event(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_string[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(stderr, "%s: %s\n", time_string, message);
    fprintf(log_file, "%s: %s\n", time_string, message);
}

int init_gpio() {
    int ret;

    gpio_fd = open("/dev/gpiochip0", O_RDWR | O_CLOEXEC);
    if (gpio_fd < 0) {
        perror("Failed to open gpiochip0");
        return -1;
    }

    ret = gpiod_chip_open_from_fd(gpio_fd, &lines_data, GPIOD_OPEN_FLAG_REQUEST_LINE);
    if (ret < 0) {
        perror("Failed to open GPIO line");
        close(gpio_fd);
        return -1;
    }

    gpio_line_handle = lines_data.lines[GPIO_LINE_RAIN_SENSOR].requested_handle;
    ret = gpiod_line_get_value(gpio_line_handle);
    if (ret < 0) {
        perror("Failed to get initial GPIO line value");
        gpiod_chip_close(gpio_fd);
        close(gpio_fd);
        return -1;
    }

    ret = gpiod_line_enable_edge_detect(gpio_line_handle, GPIOD_EDGE_RISING | GPIOD_EDGE_FALLING);
    if (ret < 0) {
        perror("Failed to enable edge detection");
        gpiod_line_release(gpio_line_handle);
        gpiod_chip_close(gpio_fd);
        close(gpio_fd);
        return -1;
    }

    return 0;
}

void cleanup() {
    if (gpio_line_handle) {
        gpiod_line_disable_edge_detect(gpio_line_handle);
        gpiod_line_release(gpio_line_handle);
    }

    if (gpio_fd >= 0) {
        gpiod_chip_close(gpio_fd);
        close(gpio_fd);
    }

    if (log_file && access(LOG_FILE, F_OK) == 0) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    int ret;
    struct sigaction sa;

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return -1;
    }

    ret = init_gpio();
    if (ret < 0) {
        return ret;
    }

    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    ret = sigaction(SIGINT, &sa, NULL);
    if (ret < 0) {
        perror("Failed to set SIGINT handler");
        cleanup();
        return -1;
    }

    ret = sigaction(SIGTERM, &sa, NULL);
    if (ret < 0) {
        perror("Failed to set SIGTERM handler");
        cleanup();
        return -1;
    }

    while (1) {
        usleep(500000);
        int value = gpiod_line_get_value(gpio_line_handle);
        if (value != lines_data.lines[GPIO_LINE_RAIN_SENSOR].requested_value) {
            lines_data.lines[GPIO_LINE_RAIN_SENSOR].requested_value = value;
            ret = gpiod_line_set_value(gpio_line_handle, value);
            if (ret < 0) {
                perror("Failed to set GPIO line value");
            }
            log_event(value ? "No Rain" : "Rain Detected");
        }
    }

    return 0;
}

