Here's the C code:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18
#define DEBOUNCE_MS 5
#define LOG_FILE "shaft_log.txt"

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int nlines,
                                const char *const *lines, unsigned int flags)
{
    return gpiod_chip_request_lines(chip, nlines, lines, flags, NULL);
}

static void gpio_cleanup(struct gpiod_line *lines, int nlines)
{
    for (int i = 0; i < nlines; ++i)
        gpiod_line_release(lines + i);
    free(lines);
}

static void log_transition(const char *timestamp, int state1, int state2)
{
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("fopen");
        return;
    }

    fprintf(file, "%s,%d,%d\n", timestamp, state1, state2);
    fclose(file);
}

int main(void)
{
    struct gpiod_chip *chip;
    struct gpiod_line *lines[2];
    int ret;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_byname");
        return 1;
    }

    lines[0] = gpiod_line_get_byname(chip, "gpio17");
    lines[1] = gpiod_line_get_byname(chip, "gpio18");
    if (!lines[0] || !lines[1]) {
        perror("gpiod_line_get_byname");
        gpiod_chip_release(chip);
        return 1;
    }

    ret = gpio_request_lines(chip, 2, (const char *[]) { "gpio17", "gpio18" },
                              GPIOD_LINE_REQUEST_INPUT);
    if (ret < 0) {
        perror("gpio_request_lines");
        gpio_cleanup(lines, 2);
        gpiod_chip_release(chip);
        return 1;
    }

    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    long last_ts = ts.tv_sec * 1000 + ts.tv_nsec / 1_000_000;
    int prev_state[2] = { 0, 0 };

    for (;;) {
        gpiod_line_get_value(lines[0]);
        gpiod_line_get_value(lines[1]);
        usleep(50000);

        gpiod_line_get_value(lines[0]);
        gpiod_line_get_value(lines[1]);
        int state[2] = { gpiod_line_get_value(lines[0]) ? 1 : 0,
                         gpiod_line_get_value(lines[1]) ? 1 : 0 };

        if (state[0] != prev_state[0] || state[1] != prev_state[1]) {
            clock_gettime(CLOCK_MONOTONIC, &ts);
            long cur_ts = ts.tv_sec * 1000 + ts.tv_nsec / 1_000_000;
            double dt = (cur_ts - last_ts) / 1000.0;
            last_ts = cur_ts;

            int transitions = 0;
            for (int i = 0; i < 2; ++i) {
                if (state[i] != prev_state[i])
                    ++transitions;
                prev_state[i] = state[i];
            }

            double rpm = (60.0 * transitions) / dt;
            printf("RPM: %.2f\n", rpm);
            log_transition(ctime(&cur_ts), state[0], state[1]);
        }
    }

    gpio_cleanup(lines, 2);
    gpiod_chip_release(chip);

    return 0;
}
```

This program initializes the GPIO lines, requests input for the sensors, and enters an infinite loop to read the state of the sensors. When a state change is detected, it calculates the RPM and logs the transition to the CSV file. It also handles errors and releases resources properly on exit.

To compile the code, save it to a file named `shaft_monitor.c` and run:

```bash
gcc -o shaft_monitor shaft_monitor.c -lgpiod -lrt
```

Then, run the compiled program:

```bash
./shaft_monitor
```

You can use `Ctrl+C` to stop the program and perform orderly cleanup.

