code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <libgpiod.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18
#define ALARM_GPIO 27
#define LOG_FILE "bridge_integrity.log"
#define THRESHOLD_TIME 2000 // 2 seconds in milliseconds

gpiod_line_request_linestate_cb_t sensor_cb;
gpiod_line_request_data_t sensor_req[2];
gpiod_line_data_t sensor_val[2];
int alarm_active = 0;

void log_event(const char *event) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(time_str, sizeof(time_str), "%Y-%m-%dT%H:%M:%S", timeinfo);
    fprintf(stderr, "%s: %s\n", time_str, event);
    fprintf(stderr, "%s\n", time_str);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }
    fprintf(log_file, "%s: %s\n", time_str, event);
    fclose(log_file);
}

void sensor_cb_handler(struct gpiod_chip *chip, struct gpiod_line_request *request,
                       enum gpiod_line_event event, void *user_data) {
    int *sensor = (int *)user_data;
    sensor_val[*sensor].value = gpiod_line_get_value(request->line);

    if (event == GPIOD_LINE_EVENT_EDGE_FALLING) {
        if (alarm_active) {
            log_event("tilt-end");
            alarm_active = 0;
            gpiod_line_set_value(sensor_req[ALARM_GPIO].line, 0);
        }
    } else if (event == GPIOD_LINE_EVENT_EDGE_RISING) {
        if (!alarm_active) {
            log_event("tilt-start");
            alarm_active = 1;
            gpiod_line_set_value(sensor_req[ALARM_GPIO].line, 1);
        }
    }
}

int main() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line_request *sensor_req_ptr[2];

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    ret = gpiod_chip_request_lines(chip, 3, &sensor_req[0], NULL);
    if (ret < 0) {
        perror("Failed to request GPIO lines");
        goto cleanup_chip;
    }

    sensor_req[SENSOR1_GPIO].flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ENABLED;
    sensor_req[SENSOR2_GPIO].flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ENABLED;
    sensor_req[ALARM_GPIO].flags = GPIOD_LINE_REQUEST_OUTPUT | GPIOD_LINE_REQUEST_INIT_LOW;

    ret = gpiod_line_request_enable(sensor_req[SENSOR1_GPIO]);
    if (ret < 0) {
        perror("Failed to enable sensor 1");
        goto cleanup_lines;
    }
    sensor_req_ptr[0] = &sensor_req[SENSOR1_GPIO];

    ret = gpiod_line_request_enable(sensor_req[SENSOR2_GPIO]);
    if (ret < 0) {
        perror("Failed to enable sensor 2");
        goto cleanup_lines;
    }
    sensor_req_ptr[1] = &sensor_req[SENSOR2_GPIO];

    ret = gpiod_line_request_enable(sensor_req[ALARM_GPIO]);
    if (ret < 0) {
        perror("Failed to enable alarm");
        goto cleanup_lines;
    }

    sensor_cb(chip, sensor_req_ptr[0], GPIOD_LINE_EVENT_NONE, &SENSOR1_GPIO);
    sensor_cb(chip, sensor_req_ptr[1], GPIOD_LINE_EVENT_NONE, &SENSOR2_GPIO);

    while (1) {
        for (int i = 0; i < 2; ++i) {
            if (sensor_val[i].value == 1) {
                log_event("threshold-exceeded");
                alarm_active = 1;
                gpiod_line_set_value(sensor_req[ALARM_GPIO].line, 1);
            }
        }

        usleep(100000); // 100ms delay
    }

cleanup_lines:
    for (int i = 0; i < 3; ++i) {
        if (sensor_req[i].line)
            gpiod_line_request_deactivate(sensor_req[i]);
    }

cleanup_chip:
    if (chip)
        gpiod_chip_release(chip);

    return 0;
}

