#include <sys/time.h>
#include <errno.h>
#include <string.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define SDA_GPIO 2
#define SCL_GPIO 3
#define ALERT_GPIO 17
#define THRESHOLD 500
#define RETRIES 3

static const char *i2c_dev_name = "/dev/i2c-" I2C_BUS;
static const char *log_file = "seismic_events.log";

int i2c_fd;
struct gpiod_chip *gpiochip;
struct gpiod_line *alert_line;

void i2c_init() {
    i2c_fd = open(i2c_dev_name, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, 0x28) < 0) { // Change the address according to your sensor
        perror("Failed to acquire bus access");
        exit(EXIT_FAILURE);
    }
}

void gpio_init() {
    gpiochip = gpiod_chip_open_byname("gpiochip0");
    if (!gpiochip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    alert_line = gpiod_get_line(gpiochip, "gpio" ALERT_GPIO);
    if (!alert_line) {
        perror("Failed to get alert GPIO line");
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_output(alert_line, "alert", GPIOD_LINE_ACTIVE_HIGH);
}

int read_sensor() {
    char buf[2];
    int retries = RETRIES;
    int x, y, z;

    do {
        if (i2c_smbus_read_word_data(i2c_fd, 0x28) < 0) {
            perror("Failed to read from sensor");
            return -1;
        }

        memcpy(buf, i2c_smbus_read_i2c_block_data(i2c_fd, 0x2A, 2), 2);

        x = buf[0] << 8 | buf[1];
        y = buf[2] << 8 | buf[3];
        z = buf[4] << 8 | buf[5];

        retries--;
    } while (retries > 0);

    if (retries == 0) {
        perror("Failed to read from sensor after retries");
        return -1;
    }

    return (x * x + y * y + z * z);
}

void log_event(time_t timestamp, int value) {
    FILE *log_file_ptr = fopen(log_file, "a");
    if (!log_file_ptr) {
        perror("Failed to open log file");
        return;
    }

    struct tm *timeinfo = localtime(&timestamp);
    char time_str[32];
    strftime(time_str, sizeof(time_str), "%Y-%m-%dT%H:%M:%S.%f", timeinfo);

    fprintf(log_file_ptr, "%s,%d\n", time_str, value);
    fclose(log_file_ptr);
}

void alert_event(int value) {
    gpiod_line_set_value(alert_line, 1);
    usleep(1000000);
    gpiod_line_set_value(alert_line, 0);
}

int main() {
    i2c_init();
    gpio_init();

    struct timespec sleep_time = { .tv_sec = 0, .tv_nsec = 100000000 }; // 100ms

    while (1) {
        int value = read_sensor();
        if (value > THRESHOLD) {
            time_t timestamp = time(NULL);
            log_event(timestamp, value);
            alert_event(value);
        }
        nanosleep(&sleep_time, NULL);
    }

    close(i2c_fd);
    gpiod_chip_close(gpiochip);
    gpiod_line_release(alert_line);
    fclose(log_file_ptr);

    return 0;
}

