    int led_gpio = LED_GPIO_NUM;

    for (int i = 0; i <= SENSOR_GPIO_NUM; ++i) {
        gpio_fd[i] = gpiod_open_name_with_consumer("gpiochip0", sensors[i], "obstacle_sensor");
        if (gpio_fd[i] < 0) {
