#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <syslog.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <gpiod.h>

#define NUM_SENSORS 5
#define GPIO_BASE "/dev/gpiod"
#define LOG_FILE "/var/log/flame_events.log"
#define LOG_FACILITY LOG_USER
#define LOG_IDENT "flame_monitor"

struct gpio_line {
    gpiod_line_request_data_t req;
    gpiod_line_data_t data;
    FILE *log_file;
    int id;
    int pin;
};

volatile sig_atomic_t terminate = 0;
struct gpiod_chip *chip;
struct gpio_line lines[NUM_SENSORS];

void sigint_handler(int signum) {
    terminate = 1;
}

void sigterm_handler(int signum) {
    terminate = 1;
}

void log_open_error(const char *file, int line, const char *function) {
    openlog(LOG_IDENT, LOG_PERROR, LOG_FACILITY);
    syslog(LOG_ERR, "%s:%d: %s: Failed to open %s", __FILE__, line, function, file);
    closelog();
}

void log_write_error(const char *file, int line, const char *function) {
    openlog(LOG_IDENT, LOG_PERROR, LOG_FACILITY);
    syslog(LOG_ERR, "%s:%d: %s: Failed to write to %s", __FILE__, line, function, file);
    closelog();
}

int open_chip() {
    int ret;
    chip = gpiod_chip_open(GPIO_BASE);
    if (!chip) {
        log_open_error(__FILE__, __LINE__, "gpiod_chip_open");
        return -1;
    }
    return 0;
}

int acquire_line(struct gpio_line *line) {
    int ret;
    ret = gpiod_line_request_direction_input(line->req.request, GPIOD_LINE_REQUEST_INPUT);
    if (ret < 0) {
        log_open_error(__FILE__, __LINE__, "gpiod_line_request_direction_input");
        return -1;
    }

    ret = gpiod_line_request_enable(line->req.request, true);
    if (ret < 0) {
        log_open_error(__FILE__, __LINE__, "gpiod_line_request_enable");
        return -1;
    }

    ret = gpiod_line_get_value(line->data, GPIOD_LINE_GET_VALUE_NO_WAIT);
    if (ret < 0) {
        log_open_error(__FILE__, __LINE__, "gpiod_line_get_value");
        return -1;
    }

    return 0;
}

void release_line(struct gpio_line *line) {
    gpiod_line_put(line->data, line->data->value);
    gpiod_line_request_enable(line->req.request, false);
    gpiod_line_release(line->req.request);
}

void log_event(struct gpio_line *line, const char *timestamp) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char log_line[256];
    snprintf(log_line, sizeof(log_line), "%s - Sensor ID:%d (GPIO %d) - Flame Detected\n", asctime(tm), line->id, line->pin);

    if (line->log_file) {
        if (flockfile(line->log_file) == -1) {
            log_write_error(__FILE__, __LINE__, "flockfile");
            return;
        }

        if (fprintf(line->log_file, "%s", log_line) <= 0) {
            log_write_error(__FILE__, __LINE__, "fprintf");
        }

        if (fflush(line->log_log_file) == EOF) {
            log_write_error(__FILE__, __LINE__, "fflush");
        }

        funlockfile(line->log_file);
    }

    openlog(LOG_IDENT, LOG_PERROR, LOG_FACILITY);
    syslog(LOG_INFO, "%s", log_line);
    closelog();
}

int main(void) {
    int i;
    struct gpiod_line_request_data_array req_array = {
        .n_requests = NUM_SENSORS,
        .requests = calloc(NUM_SENSORS, sizeof(gpiod_line_request_data_t))
    };

    if (!req_array.requests) {
        perror("Failed to allocate memory for line requests");
        return 1;
    }

    if (open_chip() < 0) {
        goto cleanup;
    }

    for (i = 0; i < NUM_SENSORS; ++i) {
        lines[i].id = i + 1;
        lines[i].pin = i + 3;
        lines[i].log_file = fopen(LOG_FILE, "a");
        if (!lines[i].log_file) {
            log_open_error(__FILE__, __LINE__, "fopen");
            continue;
        }

        snprintf(req_array.requests[i].label, sizeof(req_array.requests[i].label), "Flame Sensor %d", lines[i].id);
        req_array.requests[i].consumer = "flame_monitor";
        req_array.requests[i].flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_RISING;
        req_array.requests[i].offset = 0;
        req_array.requests[i].active_low = 0;
        req_array.requests[i].flags2 = GPIOD_LINE_REQUEST_FLAG2_NONE;
        req_array.requests[i].request = gpiod_chip_request_lines(chip, 1, &req_array.requests[i]);

        if (!acquire_line(&lines[i])) {
            continue;
        }

        log_open_error(__FILE__, __LINE__, "acquire_line");
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (!terminate) {
        for (i = 0; i < NUM_SENSORS; ++i) {
            if (acquire_line(&lines[i])) {
                continue;
            }

            int prev_value = lines[i].data->value;
            usleep(50000);
            if (gpiod_line_get_value(lines[i].data, GPIOD_LINE_GET_VALUE_NO_WAIT) != prev_value) {
                log_event(&lines[i], ctime(&now));
            }
            release_line(&lines[i]);
        }
        usleep(1000000);
    }

cleanup:
    for (i = 0; i < NUM_SENSORS; ++i) {
        if (lines[i].log_file) {
            fclose(lines[i].log_file);
        }
        release_line(&lines[i]);
    }

    gpiod_chip_release(chip);
    free(req_array.requests);
    closelog();
    return 0;
}

