        .requests = calloc(NUM_SENSORS, sizeof(gpiod_line_request_data_t))
    };

    if (!req_array.requests) {
        perror("Failed to allocate memory for line requests");
        return 1;
    }

    if (open_chip() < 0) {
        goto cleanup;
    }

    for (i = 0; i < NUM_SENSORS; ++i) {
        lines[i].id = i + 1;
        lines[i].pin = i + 3;
        lines[i].log_file = fopen(LOG_FILE, "a");
        if (!lines[i].log_file) {
            log_open_error(__FILE__, __LINE__, "fopen");
            continue;
        }

        snprintf(req_array.requests[i].label, sizeof(req_array.requests[i].label), "Flame Sensor %d", lines[i].id);
        req_array.requests[i].consumer = "flame_monitor";
        req_array.requests[i].flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_RISING;
        req_array.requests[i].offset = 0;
        req_array.requests[i].active_low = 0;
        req_array.requests[i].flags2 = GPIOD_LINE_REQUEST_FLAG2_NONE;
        req_array.requests[i].request = gpiod_chip_request_lines(chip, 1, &req_array.requests[i]);

        if (!acquire_line(&lines[i])) {
            continue;
        }

        log_open_error(__FILE__, __LINE__, "acquire_line");
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (!terminate) {
        for (i = 0; i < NUM_SENSORS; ++i) {
            if (acquire_line(&lines[i])) {
                continue;
            }

            int prev_value = lines[i].data->value;
            usleep(50000);
            if (gpiod_line_get_value(lines[i].data, GPIOD_LINE_GET_VALUE_NO_WAIT) != prev_value) {
                log_event(&lines[i], ctime(&now));
            }
            release_line(&lines[i]);
        }
        usleep(1000000);
    }

cleanup:
    for (i = 0; i < NUM_SENSORS; ++i) {
        if (lines[i].log_file) {
            fclose(lines[i].log_file);
        }
        release_line(&lines[i]);
    }

    gpiod_chip_release(chip);
    free(req_array.requests);
    closelog();
    return 0;
}
