#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <signal.h>
#include <pthread.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define VEML7700_ADDR 0x27
#define LED_GPIO 18
#define PWM_PERIOD_NS 1000000
#define PWM_FREQUENCY_HZ 1000
#define MAX_LUX 1000
#define LOG_FILE "grow_log.txt"

struct lux_data {
    time_t timestamp;
    int lux;
    int brightness;
    int error;
};

void sigint_handler(int signum) {
    printf("Received SIGINT or SIGTERM, shutting down...\n");
    gpiod_set_value_cansleep(led_gpio_request, 0);
    gpiod_release(led_gpio_request);
    gpiod_close(i2c_gpio_request);
    fclose(log_file);
    exit(0);
}

int read_lux(int fd) {
    char buf[2];
    if (read(fd, buf, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    int lux = (buf[0] << 8) | buf[1];
    return lux;
}

void set_pwm(struct gpiod_line *led, uint32_t duty_ns) {
    struct gpiod_pwm_config config = {
        .period_ns = PWM_PERIOD_NS,
        .duty_cycle_ns = duty_ns,
        .frequency_hz = PWM_FREQUENCY_HZ,
    };

    if (gpiod_pwm_configure_cansleep(led, &config) < 0) {
        perror("Error configuring PWM");
    }
}

int map_lux_to_brightness(int lux) {
    if (lux < 100) {
        return 100;
    } else if (lux < 500) {
        return 75;
    } else if (lux < 1000) {
        return 50;
    } else {
        return 25;
    }
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    int i2c_bus_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_bus_fd < 0) {
        perror("Error opening I2C bus");
        exit(1);
    }

    if (ioctl(i2c_bus_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        perror("Error setting I2C slave address");
        exit(1);
    }

    struct gpiod_line *led_gpio_request = gpiod_get_line_cansleep(LED_GPIO, GPIOD_IN_BOOT);
    if (!led_gpio_request) {
        perror("Error getting LED GPIO line");
        exit(1);
    }

    struct gpiod_line *i2c_gpio_request = gpiod_get_line_cansleep(LED_GPIO, GPIOD_OUT_INACTIVE);
    if (!i2c_gpio_request) {
        perror("Error getting I2C GPIO line");
        gpiod_release(led_gpio_request);
        exit(1);
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Error opening log file");
        gpiod_release(led_gpio_request);
        gpiod_close(i2c_gpio_request);
        exit(1);
    }

    while (1) {
        int lux = read_lux(i2c_bus_fd);
        if (lux < 0) {
            fprintf(log_file, "%s, -1, -1, E_I2C_READ\n", ctime(&time(NULL)));
            fflush(log_file);
            continue;
        }

        int brightness = map_lux_to_brightness(lux);
        gpiod_set_value_cansleep(led_gpio_request, brightness);
        set_pwm(i2c_gpio_request, PWM_PERIOD_NS * brightness / 100);

        struct lux_data data = {
            .timestamp = time(NULL),
            .lux = lux,
            .brightness = brightness,
            .error = 0,
        };

        fprintf(log_file, "%s, %d, %d, 0\n", ctime(&data.timestamp), data.lux, data.brightness);
        fflush(log_file);

        sleep(1);
    }

    fclose(log_file);
    gpiod_release(led_gpio_request);
    gpiod_close(i2c_gpio_request);
    close(i2c_bus_fd);

    return 0;
}

