#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <time.h>
#include <errno.h>
#include <sys/signals.h>
#include <linux/types.h>
#include <linux/spi/spidev.h>
#include <linux/gpio/consumer.h>
#include <linux/gpio.h>

#define GPIO_ALERT 17
#define GPIO_SENSOR_BASE 2
#define NUM_SENSORS 8

struct gpiod_line_request *lines[NUM_SENSORS];
struct gpiod_chip *chip;
int fd_alert;
FILE *log_file;

void signal_handler(int signum) {
    gpiod_line_set_value(lines[0], 0);
    gpiod_chip_put(chip);
    close(fd_alert);
    fclose(log_file);
    exit(0);
}

int init_gpio() {
    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return -1;
    }

    for (int i = 0; i < NUM_SENSORS; ++i) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_SENSOR_BASE + i);
        if (!lines[i]) {
            perror("Failed to get line");
            gpiod_chip_put(chip);
            return -1;
        }

        gpiod_line_request_direction_input(lines[i], GPIOD_LINE_ACTIVE_LOW);
        gpiod_line_request_debounce(lines[i], 10);
    }

    fd_alert = open("/dev/gpiochip0", O_WRONLY | O_NOCTTY);
    if (fd_alert < 0) {
        perror("Failed to open gpiochip0");
        for (int i = 0; i < NUM_SENSORS; ++i) {
            gpiod_line_release(lines[i]);
        }
        gpiod_chip_put(chip);
        return -1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

void log_touch_event(int channel) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_string[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s – Channel %d Touched\n", time_string, channel);

    if (ferror(log_file)) {
        perror("Failed to write to log file");
    }
}

int main() {
    int prev_states[NUM_SENSORS] = {-1};
    int current_states[NUM_SENSORS];

    if (init_gpio() < 0) {
        return -1;
    }

    log_file = fopen("touch_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        goto cleanup;
    }

    gpiod_line_set_value(lines[0], 1);

    while (1) {
        for (int i = 0; i < NUM_SENSORS; ++i) {
            gpiod_line_get_value(lines[i], &current_states[i]);
        }

        for (int i = 0; i < NUM_SENSORS; ++i) {
            if (current_states[i] != prev_states[i]) {
                log_touch_event(i + 1);
                gpiod_line_set_value(lines[0], 0);
                usleep(50 * 1000);
                gpiod_line_set_value(lines[0], 1);
                break;
            }
        }

        for (int i = 0; i < NUM_SENSORS; ++i) {
            prev_states[i] = current_states[i];
        }

        usleep(50 * 1000);
    }

cleanup:
    for (int i = 0; i < NUM_SENSORS; ++i) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_put(chip);
    close(fd_alert);
    fclose(log_file);

    return 0;
}

