    ret = gpiod_line_request_lines(chip, 1, &lines_data, &sensor_line);
    if (ret < 0) {
        perror("Failed to request line for GPIO");
        goto cleanup_line;
    }

    ret = gpiod_line_get_event_callback(sensor_line, sensor_read_cb, NULL);
    if (ret < 0) {
        perror("Failed to set event callback");
        goto cleanup_line_request;
    }

    alert_line = gpiod_chip_get_line(chip, ALERT_GPIO);
    if (!alert_line) {
        perror("Failed to get line for ALERT GPIO");
        goto cleanup_event_cb;
    }

    ret = gpiod_line_request_lines(chip, 1, &lines_data, &alert_line);
    if (ret < 0) {
        perror("Failed to request line for ALERT GPIO");
