    }

    return 0;

cleanup_alert_line:
    gpiod_line_release_event_callback(sensor_line);

cleanup_event_cb:
    gpiod_line_release(sensor_line);

cleanup_line_request:
    gpiod_line_free_data(&lines_data);

cleanup_line:
    gpiod_chip_close(chip);

cleanup_chip:
    return -1;
}

