static void log_touch_event(const char *event, time_t timestamp)
{
    char buffer[64];
    struct tm *tm_info;
    FILE *log_file = fopen(LOG_FILE, "a");

    if (!log_file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    tm_info = localtime(&timestamp);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S: ", tm_info);
    fprintf(log_file, "%s%s\n", buffer, event);
    fflush(log_file);
    fclose(log_file);
}

int main(void)
{
