    struct gpiod_line *line;
    int ret;
    uint32_t values[1];
    time_t last_event_time = 0;
    struct itimerval timer;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_byname");
        exit(EXIT_FAILURE);
    }

    line = gpiod_get_line_byname(chip, GPIO_LINE_ID);
    if (!line) {
        perror("gpiod_get_line_byname");
        gpiod_chip_put(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_direction_input(line);
    if (ret < 0) {
        perror("gpiod_line_request_direction_input");
