#define I2C_BUS 1
#define SLAVE_ADDR 0x48
#define FLOW_REG 0x00
#define CRC_REG 0x01
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0x00

#define FLOW_MIN 0
#define FLOW_MAX 10000
#define FLOW_SCALE 100

#define FILE_NAME "cooling_log.csv"
```

2. Define helper functions for I2C read and CRC calculation:

```c
int i2c_read(int file, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(file, &reg, 1) != 1) {
        perror("i2c_read: write");
        return -1;
    }

    if (read(file, buf, len) != len) {
        perror("i2c_read: read");
        return -1;
    }

    return 0;
}

uint8_t crc8(uint8_t *data, size_t len, uint8_t poly, uint8_t init) {
    uint8_t crc = init;

    for (size_t i = 0; i < len; ++i) {
        for (int bit = 8; bit > 0; --bit) {
            crc = (crc >> 1) ^ (crc & 0x01 ? poly : 0);
            if ((data[i] & (1 << (7 - bit))) != 0) {
                crc = (crc >> 1) ^ poly;
            }
        }
    }

    return crc;
}
```

3. Implement the main function:

```c
int main() {
    int i2c_file;
    int ret;
    uint8_t flow_data[3];
    uint8_t flow_value;
    uint16_t flow_rate;
    uint8_t crc;
    time_t timestamp;
    FILE *csv_file;
    char status[16];

    // Open I2C device
    if ((i2c_file = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("open: i2c-1");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_file, I2C_SLAVE, SLAVE_ADDR) < 0) {
        perror("ioctl: I2C_SLAVE");
        exit(EXIT_FAILURE);
    }

    // Create and open the CSV file
    if ((csv_file = fopen(FILE_NAME, "a")) == NULL) {
        perror("fopen: " FILE_NAME);
        exit(EXIT_FAILURE);
    }

    // Write the header if the file is empty
    if (ftell(csv_file) == 0) {
        fprintf(csv_file, "Timestamp,Flow Rate (ml/min),Status\n");
    }

    while (true) {
        // Wait at least 2ms before the first read
        usleep(2000);

        // Read three bytes from the sensor
        if (i2c_read(i2c_file, FLOW_REG, flow_data, sizeof(flow_data)) != 0) {
            fprintf(csv_file, "ERROR\n");

            // Re-initialize the I2C handle
            if (ioctl(i2c_file, I2C_SLAVE, SLAVE_ADDR) < 0) {
                perror("ioctl: I2C_SLAVE");
                exit(EXIT_FAILURE);
            }

            continue;
        }

        // Calculate the CRC
        crc = crc8(flow_data, sizeof(flow_data) - 1, CRC_POLYNOMIAL, CRC_INIT);

        // Check the CRC
        if (flow_data[sizeof(flow_data) - 1] != crc) {
            fprintf(csv_file, "ERROR\n");
            continue;
        }

        // Extract the flow value and convert it to ml/min
        flow_value = (flow_data[0] << 8) | flow_data[1];
        flow_rate = (double)flow_value / 100.0;

        // Check if the flow rate is within the plausible range
        if (flow_rate < FLOW_MIN || flow_rate > FLOW_MAX) {
            snprintf(status, sizeof(status), "INVALID");
        } else {
            snprintf(status, sizeof(status), "OK");
        }

        // Get the current timestamp
        time(&timestamp);
        struct tm *tm = localtime(&timestamp);
        char timestamp_str[32];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", tm);

        // Write the log entry
        fprintf(csv_file, "%s,%f,%s\n", timestamp_str, flow_rate, status);

        usleep(1000000); // Sleep for 1 second
    }

    // Close the I2C device and the CSV file
    close(i2c_file);
    fclose(csv_file);

    return 0;
}
```

