#include <gpiod.h>

#define LEFT_GPIO 17
#define MIDDLE_GPIO 27
#define RIGHT_GPIO 22
#define LOG_FILE "path_log.csv"

static gpiod_line_request_lines_data_t lines_data[] = {
    { .flags = GPIOD_LINE_REQUEST_INPUT, .consumer = "obstacle_avoidance" },
    { .flags = GPIOD_LINE_REQUEST_INPUT, .consumer = "obstacle_avoidance" },
    { .flags = GPIOD_LINE_REQUEST_INPUT, .consumer = "obstacle_avoidance" },
};

int main(void) {
    int fd, ret;
    gpiod_chip *chip;
    gpiod_line_set *set;
    gpiod_line_offset left, middle, right;
    FILE *log_file;
    char timestamp[32];

    // Initialize GPIO
    if ((fd = gpiod_chip_open_byname("gpiochip0")) < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    chip = gpiod_chip_get_by_fd(fd);
    if (!chip) {
        perror("Failed to get GPIO chip");
        exit(EXIT_FAILURE);
    }

    if ((ret = gpiod_chip_request_lines(chip, 3, lines_data, &set)) < 0) {
        perror("Failed to request GPIO lines");
        exit(EXIT_FAILURE);
    }

    left = gpiod_line_get_byname(set, "gpio-17");
    middle = gpiod_line_get_byname(set, "gpio-27");
    right = gpiod_line_get_byname(set, "gpio-22");

    // Open log file
    if (!(log_file = fopen(LOG_FILE, "w"))) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    // Signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        exit(EXIT_FAILURE);
    }

    while (true) {
        // Read sensor values
        int left_state = gpiod_line_get_value(left);
        int middle_state = gpiod_line_get_value(middle);
        int right_state = gpiod_line_get_value(right);

        // Format timestamp
        time_t rawtime;
        struct tm *timeinfo;
        char *time_str;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

        // Write to log file
        fprintf(log_file, "%s,%d,%d,%d\n", timestamp, left_state, middle_state, right_state);
        fflush(log_file);

        usleep(50000); // 50ms delay
    }

    // Cleanup
    gpiod_line_release(left);
    gpiod_line_release(middle);
    gpiod_line_release(right);
    gpiod_chip_release_lines(set);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}

