#include <linux/spi/spidev.h>
#include <libgpiod.h>

#define GPIO_LINE_FLAME 4
#define EVENT_FILE "flame_events.txt"

gpiod_line_request_lines_data_v1 lines_data = {
    .lines = (const gpiod_line_info_v1[]) {
        {
            .direction = GPIOD_IN,
            .edge_debounce = 50,
            .consumer = "Flame Sensor Monitor",
        },
    },
    .n_lines = 1,
};

int main(void) {
    struct timespec ts;
    int fd, line_fd;
    gpiod_line_event_cb event_cb;
    gpiod_line_event event;
    FILE *file;

    clock_gettime(CLOCK_MONOTONIC, &ts);

    fd = gpiod_library_open_sync();
    if (fd < 0) {
        perror("Failed to open libgpiod library");
        return 1;
    }

    line_fd = gpiod_chip_request_lines_sync(fd, &lines_data);
    if (line_fd < 0) {
        perror("Failed to request GPIO lines");
        gpiod_library_close_sync(fd);
        return 1;
    }

    event_cb = [](struct gpiod_chip *chip, struct gpiod_line *line,
                  enum gpiod_line_event event, void *user_data) {
        if (event == GPIOD_LINE_EVENT_EDGE_FALLING) {
            clock_gettime(CLOCK_MONOTONIC, &ts);
            printf("Flame detected at %ld.%09ld\n", (long)ts.tv_sec, ts.tv_nsec);

            file = fopen(EVENT_FILE, "a");
            if (file) {
                fprintf(file, "Flame detected at %ld.%09ld\n", (long)ts.tv_sec, ts.tv_nsec);
                fclose(file);
            } else {
                perror("Failed to open flame_events.txt");
            }
        }
    };

    gpiod_line_add_event_callback(line_fd, GPIO_LINE_FLAME, event_cb, NULL);

    while (1) {
        gpiod_line_get_events_sync(line_fd, &event, 1);
        usleep(100000);
    }

    gpiod_line_remove_event_callback(line_fd, GPIO_LINE_FLAME, event_cb);
    gpiod_chip_release_lines_sync(line_fd);
    gpiod_library_close_sync(fd);

    return 0;
}

