static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int nlines,
                                const unsigned int lines[],
                                const char *consumer, const char *label)
{
    return gpiod_chip_request_lines(chip, nlines, lines, GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_RISING, consumer, label);
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *sensor_line, *led_line;
    FILE *log_file;
    char log_filename[] = "touch_log.txt";
    int ret;

    // Open the log file
    log_file = fopen(log_filename, "w");
    if (!log_file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    // Request the GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open");
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    // Request the sensor and LED lines
    ret = gpiod_line_request_lines(chip, 2, &SENSOR_LINE, "touch_sensor", "sensor");
    if (ret < 0) {
        perror("gpiod_line_request_lines (sensor)");
        gpiod_chip_close(chip);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }
    sensor_line = gpiod_get_line_by_number(chip, SENSOR_LINE);

    ret = gpiod_line_request_lines(chip, 1, &LED_LINE, "touch_led", "led");
    if (ret < 0) {
        perror("gpiod_line_request_lines (led)");
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }
    led_line = gpiod_get_line_by_number(chip, LED_LINE);

    // Main loop
    time_t last_touch = 0;
    struct itimerval timer;
    timer.it_interval.tv_usec = 100000; // 100 ms interval
    timer.it_value.tv_usec = timer.it_interval.tv_usec;
    setitimer(ITIMER_REAL, &timer, NULL);

    while (1) {
        struct timespec ts;
        ret = gpiod_line_get_value_async(sensor_line, &ts);
        if (ret < 0) {
            perror("gpiod_line_get_value_async");
            break;
        }

        if (ts.tv_sec > last_touch + 1) {
            last_touch = ts.tv_sec;
            if (gpiod_line_get_value(sensor_line)) {
                fprintf(log_file, "%s: Touch detected, LED state: HIGH\n", ctime(&last_touch));
                gpiod_line_set_value(led_line, 1);
            } else {
                fprintf(log_file, "%s: Touch detected, LED state: LOW\n", ctime(&last_touch));
                gpiod_line_set_value(led_line, 0);
            }
        }
    }

    // Cleanup
    gpiod_line_set_value(led_line, 0);
    gpiod_line_release(led_line);
    gpiod_line_release(sensor_line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return EXIT_SUCCESS;
}
```

