static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int nlines,
                                const char *const *consumer, unsigned int flags)
{
    return gpiod_chip_request_lines(chip, nlines, consumer, flags);
}

static void gpio_cleanup(struct gpiod_chip *chip, gpiod_line_set_value_cb cb,
                         void *data)
{
    gpiod_chip_release_lines(chip, cb, data);
}

int main(void)
{
    struct gpiod_chip *chip;
    struct gpiod_line *line_sensor, *line_led;
    struct timespec debounce_timeout = { .tv_sec = 0, .tv_nsec = 200 * 1e6 };
    int ret, i;
    uint32_t value;
    FILE *log_file;
    char timestamp[32];

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    line_sensor = gpiod_chip_get_line(chip, GPIO_LINE_SENSOR);
    if (!line_sensor) {
        perror("Failed to get line for sensor");
        goto cleanup;
    }

    line_led = gpiod_chip_get_line(chip, GPIO_LINE_LED);
    if (!line_led) {
        perror("Failed to get line for LED");
        goto cleanup;
    }

    ret = gpiod_line_request_active_low(line_sensor, "touch_sensor");
    if (ret < 0) {
        perror("Failed to request line for sensor");
        goto cleanup;
    }

    ret = gpiod_line_request_active_low(line_led, "touch_led");
    if (ret < 0) {
        perror("Failed to request line for LED");
        goto cleanup;
    }

    log_file = fopen("touch_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        goto cleanup;
    }

    signal(SIGINT, [](int signum) {
        gpio_cleanup(chip, gpiod_line_set_value, line_led);
        fclose(log_file);
        gpiod_chip_put(chip);
        exit(0);
    });

    signal(SIGTERM, [](int signum) {
        gpio_cleanup(chip, gpiod_line_set_value, line_led);
        fclose(log_file);
        gpiod_chip_put(chip);
        exit(0);
    });

    while (1) {
        ret = gpiod_line_get_value(line_sensor, &value);
        if (ret < 0) {
            perror("Failed to get line value");
            continue;
        }

        if (value)
            continue;

        ret = nanosleep(&debounce_timeout, NULL);
        if (ret == -1 && errno != EINTR) {
            perror("Failed to sleep during debounce");
            continue;
        }

        ret = gpiod_line_get_value(line_sensor, &value);
        if (ret < 0) {
            perror("Failed to get line value");
            continue;
        }

        if (value)
            continue;

        time_t rawtime;
        struct tm *timeinfo;
        char *tz = "UTC";
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
        strftime(timestamp + 19, sizeof(timestamp) - 19, tz, timeinfo);

        ret = fprintf(log_file, "%s\n", timestamp);
        if (ret < 0) {
            perror("Failed to write to log file");
            fprintf(stderr, "Warning: Failed to write to log file\n");
        }

        ret = gpiod_line_set_value(line_led, 1);
        if (ret < 0) {
            perror("Failed to set LED value");
        }

        for (i = 0; i < 100000; i++)
            usleep(10); // Delay for 100ms to keep the LED on

        ret = gpiod_line_set_value(line_led, 0);
        if (ret < 0) {
            perror("Failed to set LED value");
        }
    }

cleanup:
    if (line_led)
        gpiod_line_release(line_led);
    if (line_sensor)
        gpiod_line_release(line_sensor);
    if (log_file)
        fclose(log_file);
    if (chip)
        gpiod_chip_put(chip);

    return ret < 0 ? 1 : 0;
}

