Here's the C code:

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <gpiod.h>

#define SENSOR_1_GPIO 4
#define SENSOR_2_GPIO 17
#define SENSOR_3_GPIO 27
#define LOG_FILE "magnet_log.txt"

static gpiod_line_request_lines_data_t lines_data[] = {
    { .offset = SENSOR_1_GPIO },
    { .offset = SENSOR_2_GPIO },
    { .offset = SENSOR_3_GPIO },
};

static gpiod_line_request_data_t lines_req_data[] = {
    [SENSOR_1_GPIO] = { .direction = GPIOD_LINE_REQUEST_INPUT, .flags = GPIOD_LINE_REQUEST_INPUT_ACTIVE_HIGH },
    [SENSOR_2_GPIO] = { .direction = GPIOD_LINE_REQUEST_INPUT, .flags = GPIOD_LINE_REQUEST_INPUT_ACTIVE_HIGH },
    [SENSOR_3_GPIO] = { .direction = GPIOD_LINE_REQUEST_INPUT, .flags = GPIOD_LINE_REQUEST_INPUT_ACTIVE_HIGH },
};

int main(void) {
    int fd, ret;
    gpiod_line_handle_t *lines[3];
    time_t timestamp;
    char timestamp_str[32];
    int initial_state[3] = {-1};
    struct stat log_file_stat;

    // Initialize the GPIO library
    fd = gpiod_library_open("gpiochip0");
    if (fd < 0) {
        perror("Failed to open GPIO library");
        return 1;
    }

    // Request lines
    ret = gpiod_line_request_lines(fd, 3, lines_data, lines_req_data, lines);
    if (ret < 0) {
        perror("Failed to request GPIO lines");
        goto cleanup;
    }

    // Check if every GPIO mode/pull call returns 0
    for (int i = 0; i < 3; ++i) {
        if (gpiod_line_get_flags(lines[i]) != lines_req_data[i].flags) {
            fprintf(stderr, "Failed to set GPIO mode/pull for line %d\n", i);
            goto cleanup;
        }
    }

    // Open or create the log file
    ret = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (ret < 0) {
        perror("Failed to open log file");
        goto cleanup;
    }

    // Install SIGINT and SIGTERM handlers
    signal(SIGINT, [](int sig) {
        printf("Received SIGINT, performing clean shutdown...\n");
        close(ret);
        gpiod_line_release_lines(fd, lines, 3);
        gpiod_library_release(fd);
        exit(0);
    });

    signal(SIGTERM, [](int sig) {
        printf("Received SIGTERM, performing clean shutdown...\n");
        close(ret);
        gpiod_line_release_lines(fd, lines, 3);
        gpiod_library_release(fd);
        exit(0);
    });

    // Main loop
    while (1) {
        for (int i = 0; i < 3; ++i) {
            int state = gpiod_line_get_value(lines[i]);

            // Record the initial state on the first read
            if (initial_state[i] == -1) {
                initial_state[i] = state;
                continue;
            }

            // Log state changes
            if (state != initial_state[i]) {
                time(&timestamp);
                strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S", localtime(&timestamp));
                fprintf(ret, "%s,Sensor %d: %s\n", timestamp_str, i + 1, state ? "Magnet removed" : "Magnet present");
            }

            initial_state[i] = state;
        }

        usleep(100000); // Sleep for 100ms
    }

cleanup:
    // Release lines and close the log file
    if (ret >= 0) close(ret);
    gpiod_line_release_lines(fd, lines, 3);
    gpiod_library_release(fd);

    return ret < 0 ? EXIT_FAILURE : EXIT_SUCCESS;
}
```

This code initializes the GPIO library, requests the lines, sets the pins as inputs with an internal pull-up, opens the log file, installs SIGINT and SIGTERM handlers, and enters a main loop that continuously monitors the sensors and logs state changes. It also handles errors gracefully by writing an error message to stderr and continuing operation.

