#define SI1182_HW_REV 0x01
#define SAMPLES_FOR_AVERAGE 5

static gpiod_line_request_linenum_t heart_rate_led;
static gpiod_line_request_linenum_t reset_gpio;

int init_gpio(const char *gpio_base) {
    int ret;
    gpiod_line_request_data_flags_t flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW;

    ret = gpiod_chip_open_byname(gpio_base);
    if (ret < 0) {
        perror("Failed to open GPIO chip");
        return ret;
    }

    ret = gpiod_chip_get_line_request_byname(gpio_base, "heart_rate_led", &heart_rate_led);
    if (ret < 0) {
        perror("Failed to get heart_rate_led line request");
        goto cleanup_gpio;
    }

    ret = gpiod_line_request_enable(heart_rate_led, flags);
    if (ret < 0) {
        perror("Failed to enable heart_rate_led line request");
        goto cleanup_gpio;
    }

    ret = gpiod_chip_get_line_request_byname(gpio_base, "reset", &reset_gpio);
    if (ret < 0) {
        perror("Failed to get reset line request");
        goto cleanup_gpio;
    }

    return 0;

cleanup_gpio:
    gpiod_chip_close(gpio_base);
    return ret;
}

int init_i2c(void) {
    int ret, i2c_bus = 1;
    int file = open("/dev/i2c-1", O_RDWR);
    if (file < 0) {
        perror("Failed to open I2C bus");
