```

Here's the C code:

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <errno.h>
#include <linux/gpio/consumer.h>

#define GPIO_LINE 17
#define LOG_FILE "flame_log.txt"

int main(void) {
    int ret;
    int fd_log;
    struct gpiod_line_request *request;
    struct gpiod_line *line;
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    char log_line[64];

    fd_log = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, S_IRUSR | S_IWUSR);
    if (fd_log == -1) {
        perror("open");
        return 1;
    }

    line = gpiod_chip_get_line_byname("gpiochip0", "gpio17");
    if (!line) {
        perror("gpiod_chip_get_line_byname");
        goto cleanup_log;
    }

    request = gpiod_line_request_dup(line, GPIOD_LINE_REQUEST_DIRECTION_IN | GPIOD_LINE_REQUEST_EDGE_FALLING);
    if (!request) {
        perror("gpiod_line_request_dup");
        goto cleanup_line;
    }

    gpiod_line_request_enable(request);

    while (1) {
        gpiod_line_get_value(line);
        nanosleep((const struct timespec[]){{0, 100 * NANOSECONDS_PER_MILLISECOND}, NULL}, 0);

        gpiod_line_get_value(line);
        if (gpiod_line_is_active_low(line) && gpiod_line_get_value(line)) {
            clock_gettime(CLOCK_MONOTONIC, &ts);
            snprintf(log_line, sizeof(log_line), "FLAME DETECTED at %ld.%09ld\n", (long)ts.tv_sec, ts.tv_nsec);
            write(fd_log, log_line, strlen(log_line));
            fflush(fd_log);
            printf("FLAME DETECTED\n");
        }
    }

cleanup_line:
    gpiod_line_request_free(request);
cleanup_log:
    close(fd_log);

    return 0;
}

void signal_handler(int signum) {
    gpiod_line_request_free(NULL);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);
    close(open(LOG_FILE, O_RDONLY));
    unlink(LOG_FILE);
    exit(0);
}

int main(void) {
    struct sigaction sa;

    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    return main();
}
