#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_BASE 1
#define SENSOR_1 17
#define SENSOR_2 18
#define SENSOR_3 27
#define SENSOR_4 22
#define GPIO_LINE_WIDTH_MAX 255
#define GPIO_LINE_LOW 0
#define GPIO_LINE_HIGH 1
#define CSV_FILE "tracking_log.csv"

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int n_lines,
                                const char *const *lines, unsigned int flags) {
    return gpiod_chip_request_lines(chip, n_lines, lines, flags, NULL);
}

static void gpio_line_free(struct gpiod_line *line) {
    gpiod_line_release(line);
    gpiod_line_put(line);
}

static int write_csv(const char *format, ...) {
    FILE *file = fopen(CSV_FILE, "a");
    if (!file) {
        perror("fopen");
        return -1;
    }

    time_t rawtime;
    struct tm *timeinfo;
    char time_string[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", timeinfo);

    va_list args;
    va_start(args, format);
    vfprintf(file, format, args);
    va_end(args);

    fputc('\n', file);
    fflush(file);
    fclose(file);

    return 0;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[4];
    int ret;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_byname");
        return 1;
    }

    lines[0] = CSL(chip, SENSOR_1);
    lines[1] = CSL(chip, SENSOR_2);
    lines[2] = CSL(chip, SENSOR_3);
    lines[3] = CSL(chip, SENSOR_4);

    ret = CSL_request(chip, lines, 4, 0, GPIOD_LINE_REQUEST_INPUT);
    if (ret < 0) {
        perror("CSL_request");
        goto cleanup;
    }

    if (access(CSV_FILE, F_OK) == -1) {
        ret = write_csv("timestamp,sensor1,sensor2,sensor3,sensor4\n");
        if (ret < 0) {
            perror("write_csv");
            goto cleanup;
        }
    }

    while (1) {
        int values[4] = {GPIO_LINE_HIGH, GPIO_LINE_HIGH, GPIO_LINE_HIGH, GPIO_LINE_HIGH};

        for (int i = 0; i < 4; ++i) {
            ret = gpiod_line_get_value(lines[i]);
            if (ret < 0) {
                perror("gpiod_line_get_value");
                continue;
            }

            values[i] = (ret == GPIO_LINE_LOW) ? GPIO_LINE_LOW : GPIO_LINE_HIGH;
        }

        ret = write_csv("timestamp,%d,%d,%d,%d\n",
                        time(NULL), values[0], values[1], values[2], values[3]);
        if (ret < 0) {
            perror("write_csv");
            continue;
        }

        usleep(100000);
    }

cleanup:
    for (int i = 0; i < 4; ++i) {
        gpio_line_free(lines[i]);
    }
    gpiod_chip_put(chip);

    return 0;
}
```

This code initializes the GPIO lines, opens the CSV file, and enters an infinite loop to read the sensor values every 100ms. If an error occurs during initialization or reading, it prints an error message to stderr and continues when possible. The program also handles SIGINT and SIGTERM signals to perform a graceful shutdown that releases all driver resources, closes and flushes the CSV file.

