#include <libgpiod.h>

#define DEBOUNCE_WINDOW_MS 50
#define POLL_INTERVAL_MS 100
#define LOG_FILE "/var/log/tilt_events.log"

static gpiod_chip *chip;
static gpiod_line_request_lines_data lines_data[] = {
    { .direction = GPIOD_IN, .edge_detected_callback = NULL, .flags = GPIOD_LINE_REQUEST_INPUT },
    { .direction = GPIOD_IN, .edge_detected_callback = NULL, .flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_BIAS_UP },
};

static void edge_callback(struct gpiod_chan *chan, unsigned int value, unsigned int event) {
    if (value == 0 && event == GPIOD_LINE_EVENT_EDGE_FALLING) {
        char timestamp[30];
        time_t rawtime;
        struct tm *timeinfo;
        char *log_line;
        size_t log_line_len;

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        log_line_len = snprintf(NULL, 0, "%s, Sensor %d tilted\n", timestamp, chan->number);
        log_line = malloc(log_line_len + 1);
        snprintf(log_line, log_line_len + 1, "%s, Sensor %d tilted\n", timestamp, chan->number);

        FILE *log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("fopen");
            free(log_line);
            return;
        }

        fputs(log_line, log_file);
        fclose(log_file);
        free(log_line);
    }
}

int main(void) {
    int ret;

    ret = gpiod_library_open();
    if (ret < 0) {
        perror("gpiod_library_open");
        return 1;
    }

    ret = gpiod_chip_open_by_name("gpiochip0", &chip);
    if (ret < 0) {
        perror("gpiod_chip_open_by_name");
        goto cleanup_libgpiod;
    }

    ret = gpiod_line_request_lines(chip, 2, lines_data, NULL);
    if (ret < 0) {
        perror("gpiod_line_request_lines");
        goto cleanup_chip;
    }

    struct timespec poll_interval = { .tv_sec = 0, .tv_nsec = POLL_INTERVAL_MS * 1000000 };
    struct timespec debounce_window = { .tv_sec = 0, .tv_nsec = DEBOUNCE_WINDOW_MS * 1000000 };

    while (1) {
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        struct timespec next_poll = now;
        next_poll.tv_sec += poll_interval.tv_sec;
        next_poll.tv_nsec += poll_interval.tv_nsec;
        if (next_poll.tv_nsec >= 1000000000) {
            next_poll.tv_sec++;
            next_poll.tv_nsec -= 1000000000;
        }

        for (size_t i = 0; i < 2; ++i) {
            struct timespec remaining_debounce;
            struct gpiod_event_info event_info;
            ret = gpiod_line_get_events(lines_data[i].chan, &event_info, 1, &remaining_debounce);
            if (ret < 0) {
                perror("gpiod_line_get_events");
                continue;
            }

            if (remaining_debounce.tv_sec > 0 || remaining_debounce.tv_nsec > 0) {
                nanosleep(&remaining_debounce, NULL);
                continue;
            }

            if (event_info.value == 1) {
                ret = gpiod_line_get_value(lines_data[i].chan, &event_info.value);
                if (ret < 0) {
                    perror("gpiod_line_get_value");
                    continue;
                }

                if (event_info.value == 0) {
                    lines_data[i].edge_detected_callback(lines_data[i].chan, event_info.value, event_info.event);
                }
            }
        }

        nanosleep(&poll_interval, NULL);
    }

cleanup_chip:
    gpiod_line_release_lines(chip, 2, lines_data);
cleanup_libgpiod:
    gpiod_library_close();

    return 0;
}

static void signal_handler(int signum) {
    gpiod_line_release_lines(chip, 2, lines_data);
    gpiod_library_close();
    fclose(logfile);
    exit(0);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    return main_func();
}

