    ret = gpiod_line_request_output_flags(line_mic, GPIOD_LINE_REQUEST_INPUT, GPIOD_LINE_ACTIVE_HIGH);
    if (ret < 0) {
        perror("Failed to request line for GPIO");
        goto cleanup_line_mic;
    }

    // Set up the LED line as output
    line_led = gpiod_chip_get_line(chip, GPIO_LED_LINE);
    if (!line_led) {
        perror("Failed to get line for GPIO");
        goto cleanup_line_mic;
    }
    ret = gpiod_line_request_output_flags(line_led, GPIOD_LINE_REQUEST_DIR_OUT, 0);
    if (ret < 0) {
        perror("Failed to request line for GPIO");
        goto cleanup_line_led;
    }

    // Initialize microphone file descriptor
    mic_fd = open("/dev/spidev0.0", O_RDWR);
    if (mic_fd < 0) {
        perror("Failed to open SPI device");
        goto cleanup_line_led;
    }

    // Configure SPI parameters
    struct spi_ioc_transfer xfer[1] = {
        {
            .tx_buf = (unsigned char*)&SAMPLE_PERIOD_US,
            .rx_buf = NULL,
            .len = sizeof(SAMPLE_PERIOD_US),
            .delay_usecs = SAMPLE_PERIOD_US,
            .speed_hz = 1000000, // 1 MHz
            .bits_per_word = 8,
        }
    };

    while (running) {
        // Poll the microphone line
        ret = gpiod_line_get_value(line_mic);
        if (ret < 0) {
            perror("Failed to get line value");
            continue;
        }

        // Send a command to the microphone to read a sample
        if (ioctl(mic_fd, SPI_IOC_MESSAGE(1), xfer) < 1) {
            perror("Failed to send SPI message");
            continue;
        }

        // Check if the microphone line is high (sound peak)
        if (ret == 1) {
            time_t rawtime;
            struct tm *timeinfo;
            char time_string[80];

            // Get current time
            time(&rawtime);
            timeinfo = localtime(&rawtime);

            // Format time string
            strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", timeinfo);
            printf("%s: Sound peak detected\n", time_string);

            // Turn on the LED
            gpiod_line_set_value(line_led, 1);
            usleep(LED_ON_MS * 1000); // Convert milliseconds to microseconds
            gpiod_line_set_value(line_led, 0);
        }

        usleep(SAMPLE_PERIOD_US * 1000); // Convert microseconds to nanoseconds
    }

    // Clean up resources
cleanup_line_led:
    gpiod_line_release(line_led);

cleanup_line_mic:
    gpiod_line_release(line_mic);

cleanup_chip:
    gpiod_chip_close(chip);

    // Close SPI device
    close(mic_fd);

    return 0;
}
```

This code initializes the microphone line as an input, the LED line as an output, and continuously polls the microphone line for sound peaks. When a sound peak is detected, it prints a timestamp and turns on the LED for 100 milliseconds. If the program receives a SIGINT signal, it cleanly stops the sampling loop, turns off the LED, and releases all resources before exiting.

