```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define SI1175_I2C_ADDR 0x2A
#define SI1175_REG_LSB 0x8C
#define SI1175_REG_MSB 0x8D

static int i2c_file;
static gpio_handle_t gpio_handle;

void i2c_init() {
    const char *i2c_bus = "/dev/i2c-1";
    if ((i2c_file = open(i2c_bus, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_file, I2C_SLAVE, SI1175_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access");
        exit(EXIT_FAILURE);
    }
}

void gpio_init() {
    const char *gpio_base = "/dev/gpiochip0";
    if (gpio_request_line(gpio_get_array_index(gpio_base, 18), "si1175_reset", NULL) < 0) {
        perror("Failed to request GPIO line");
        exit(EXIT_FAILURE);
    }

    gpio_direction_output(gpio_get_array_index(gpio_base, 18), 1);
}

void gpio_reset() {
    gpio_set_value(gpio_get_array_index(gpio_base, 18), 0);
    usleep(100000);
    gpio_set_value(gpio_get_array_index(gpio_base, 18), 1);
}

uint16_t read_sensor() {
    uint8_t lsb, msb;
    if (read(i2c_file, &lsb, 1) != 1) {
        perror("Failed to read LSB");
        exit(EXIT_FAILURE);
    }

    if (read(i2c_file, &msb, 1) != 1) {
        perror("Failed to read MSB");
        exit(EXIT_FAILURE);
    }

    return (msb << 8) | lsb;
}

void cleanup() {
    close(i2c_file);
    gpio_free(gpio_handle);
    gpio_unrequest_line(gpio_get_array_index(gpio_base, 18));
}

void signal_handler(int sig) {
    printf("\nExiting...\n");
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, signal_handler);

    gpio_init();
    gpio_reset();
    i2c_init();

    while (1) {
        uint16_t raw_value = read_sensor();
        printf("Raw ALS value: 0x%04X\n", raw_value);
        sleep(0.1);
    }

    return 0;
}
```

This code initializes the I2C bus and the GPIO line for the Si1175 reset, performs a reset, reads the LSB and MSB registers, combines them into a single 16-bit raw value, and logs the value to the console. It also handles errors and cleans up resources on exit paths, including a Ctrl+C signal.

