#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/types.h>
#include <gpiod.h>

#define LEFT_GPIO 2
#define MIDDLE_GPIO 3
#define RIGHT_GPIO 4
#define DELAY_MS 100

static void sigint_handler(int signum) {
    gpiod_set_value_cansleep(left_line, 0);
    gpiod_set_value_cansleep(middle_line, 0);
    gpiod_set_value_cansleep(right_line, 0);
    gpiod_release(left_line);
    gpiod_release(middle_line);
    gpiod_release(right_line);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *left_line, *middle_line, *right_line;

    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    // Request lines
    left_line = gpiod_get_line_byname(chip, "gpio" STRINGIFY(LEFT_GPIO));
    middle_line = gpiod_get_line_byname(chip, "gpio" STRINGIFY(MIDDLE_GPIO));
    right_line = gpiod_get_line_byname(chip, "gpio" STRINGIFY(RIGHT_GPIO));

    if (!left_line || !middle_line || !right_line) {
        perror("Failed to get line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set lines as input
    ret = gpiod_direction_input(left_line);
    if (ret < 0) {
        perror("Failed to set direction for left line");
        gpiod_line_put(left_line);
        gpiod_line_put(middle_line);
        gpiod_line_put(right_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_direction_input(middle_line);
    if (ret < 0) {
        perror("Failed to set direction for middle line");
        gpiod_line_put(left_line);
        gpiod_line_put(middle_line);
        gpiod_line_put(right_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_direction_input(right_line);
    if (ret < 0) {
        perror("Failed to set direction for right line");
        gpiod_line_put(left_line);
        gpiod_line_put(middle_line);
        gpiod_line_put(right_line);
        gpiod_chip_close(chip);
        return 1;
    }

    while (1) {
        usleep(DELAY_MS * 1000);

        int left_state = gpiod_get_value(left_line);
        int middle_state = gpiod_get_value(middle_line);
        int right_state = gpiod_get_value(right_line);

        if (left_state < 0 || middle_state < 0 || right_state < 0) {
            perror("Failed to get value");
            break;
        }

        printf("L: %s M: %s R: %s\n", left_state ? "1" : "0", middle_state ? "1" : "0", right_state ? "1" : "0");
    }

    // Cleanup
    gpiod_line_put(left_line);
    gpiod_line_put(middle_line);
    gpiod_line_put(right_line);
    gpiod_chip_close(chip);

    return 0;
}
