#include <stdio.h>
#include <stdlib.h>
#include <time.us.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/types.h>
#include <gpiod.h>

#define DEVICE_NAME "gpiochip0"
#define CHANNEL_COUNT 8

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int offset, unsigned int count,
                                const char *consumer, const char *label, unsigned int flags)
{
    return gpiod_chip_request_lines(chip, offset, count, consumer, label, flags);
}

int main(void) {
    struct timespec ts;
    struct gpiod_chip *chip;
    struct gpiod_line_request_data lines[CHANNEL_COUNT];
    int i;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(DEVICE_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Request lines
    for (i = 0; i < CHANNEL_COUNT; i++) {
        lines[i].consumer = "touch_poll";
        lines[i].label = "touch_poll_line";
        lines[i].flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_RISING;
        lines[i].offset = i;

        if (gpiod_line_request_lines(chip, i, 1, lines[i].consumer, lines[i].label, lines[i].flags) < 0) {
            fprintf(stderr, "Failed to request line %d\n", i);
            goto cleanup;
        }
    }

    // Install SIGINT/SIGTERM handler
    signal(SIGINT, [](int signum) {
        printf("Received SIGINT, shutting down...\n");
        gpiod_chip_release_lines(chip, CHANNEL_COUNT);
        gpiod_chip_close(chip);
        exit(0);
    });
    signal(SIGTERM, [](int signum) {
        printf("Received SIGTERM, shutting down...\n");
        gpiod_chip_release_lines(chip, CHANNEL_COUNT);
        gpiod_chip_close(chip);
        exit(0);
    });

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);

        for (i = 0; i < CHANNEL_COUNT; i++) {
            int value = gpiod_line_get_value_cansleep(lines[i].gpio);
            if (value < 0) {
                fprintf(stderr, "Failed to read line %d\n", i);
                goto cleanup;
            }
            printf("%lfs CH%d=%d", ts.tv_sec + ts.tv_nsec / 1_ billion, i + 1, value);
        }
        printf("\n");

        usleep(200 * 1000);
    }

cleanup:
    for (i = 0; i < CHANNEL_COUNT; i++) {
        gpiod_line_release(lines[i].gpio);
    }
    gpiod_chip_close(chip);

    return 0;
}

