#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <syslog.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <gpiod.h>

#define RED_GPIO 17
#define GREEN_GPIO 18
#define BLUE_GPIO 27

#define PWM_PERIOD_NS 1000000 / 1000
#define PWM_DUTY_MAX 255

static gpiod_line_request_lines_data_v1 lines[] = {
    { .direction = GPIOD_IN, .edge_debounce = 10 },
    { .direction = GPIOD_OUT_INIT_LOW, .edge_debounce = 10 },
    { .direction = GPIOD_OUT_INIT_LOW, .edge_debounce = 10 },
};

int setup_gpio(void) {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line_request *request;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0");
        return -1;
    }

    request = gpiod_chip_request_lines(chip, 3, lines, GPIOD_PROBE_ONE_TIME);
    if (!request) {
        syslog(LOG_ERR, "Failed to request GPIO lines");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_set_value(request->lines[RED_GPIO], 1);
    gpiod_line_set_value(request->lines[GREEN_GPIO], 0);
    gpiod_line_set_value(request->lines[BLUE_GPIO], 0);

    return 0;
}

int setup_pwm(struct gpiod_line_request *request) {
    int ret;
    struct gpiod_pwm_config pwm_config = {
        .period_ns = PWM_PERIOD_NS,
        .duty_cycle_max = PWM_DUTY_MAX,
        .software_enabled = 1,
    };

    ret = gpiod_line_pwm_configure_prepared(request->lines[RED_GPIO], &pwm_config);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to configure PWM for RED GPIO");
        goto err_pwm_red;
    }

    ret = gpiod_line_pwm_configure_prepared(request->lines[GREEN_GPIO], &pwm_config);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to configure PWM for GREEN GPIO");
        goto err_pwm_green;
    }

    ret = gpiod_line_pwm_configure_prepared(request->lines[BLUE_GPIO], &pwm_config);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to configure PWM for BLUE GPIO");
        goto err_pwm_blue;
    }

    return 0;

err_pwm_blue:
    gpiod_line_pwm_configure_prepared(request->lines[GREEN_GPIO], NULL);
err_pwm_green:
    gpiod_line_pwm_configure_prepared(request->lines[RED_GPIO], NULL);
err_pwm_red:
    gpiod_line_release(request);
    gpiod_chip_close(request->chip);
    return -1;
}

void fade_led(struct gpiod_line_request *request, unsigned char *colors) {
    unsigned int steps = 50;
    unsigned int step_time_us = 5000 * 1000 / steps;
    unsigned int i;

    for (i = 0; i < steps; ++i) {
