int main() {
    int i2c_fd, gpio_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg i2c_msgs[2];
    struct gpiod_line_request *gpio_req;
    uint8_t reg_values[6];
    uint16_t red, green, blue, clear;

    // Open I2C bus
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Initialize I2C messages
    i2c_msgs[0].addr = TCS34725_ADDR;
    i2c_msgs[0].flags = 0;
    i2c_msgs[0].len = 4;
    i2c_msgs[0].buf = (uint8_t[]) {0x80, 0x00, 0x00, 0x00}; // Power on and enable RGBC

    i2c_msgs[1].addr = TCS34725_ADDR;
    i2c_msgs[1].flags = I2C_M_RD;
    i2c_msgs[1].len = 6;
    i2c_msgs[1].buf = reg_values;

    // Configure integration time (154ms)
    i2c_data.wr_msgs = &i2c_msgs[0];
    i2c_data.rd_msgs = NULL;
    i2c_data.nmsgs = 1;

    if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) < 0) {
        perror("Failed to configure integration time");
        goto cleanup;
    }

    // Read calibration data
    i2c_data.wr_msgs = NULL;
    i2c_data.rd_msgs = &i2c_msgs[1];
    i2c_data.nmsgs = 1;

    if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) < 0) {
        perror("Failed to read calibration data");
        goto cleanup;
    }

    // Request GPIO line
    if ((gpio_fd = gpiod_open_name_with_label("gpiochip0", "line" GPIO_LINE)) < 0) {
        perror("Failed to open GPIO line");
        goto cleanup;
    }

    gpio_req = gpiod_chip_get_line_request(gpio_fd, GPIO_LINE);
    if (!gpio_req) {
        perror("Failed to get GPIO line request");
        goto cleanup;
    }

    // Set GPIO line direction as output
    if (gpiod_line_request_direction_output(gpio_req, GPIOD_LINE_ACTIVE_HIGH) < 0) {
        perror("Failed to set GPIO line direction");
        goto cleanup;
    }

    // Main loop
    while (1) {
        // Read sensor data
        i2c_data.wr_msgs = NULL;
        i2c_data.rd_msgs = &i2c_msgs[1];
        i2c_data.nmsgs = 1;

        if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) < 0) {
            perror("Failed to read sensor data");

            // Re-initialize sensor if read failure
            if (i2c_msgs[0].buf[0] != 0x80) {
                continue;
            }
        }

        red = (reg_values[1] << 8) | reg_values[2];
        green = (reg_values[3] << 8) | reg_values[4];
        blue = (reg_values[5] << 8) | reg_values[6];
        clear = reg_values[0];

        printf("Red: %d, Green: %d, Blue: %d, Clear: %d\n", red, green, blue, clear);

        // Control LED based on red value
        if (red > RED_THRESHOLD) {
            gpiod_line_set_value(gpio_req, 1);
        } else {
            gpiod_line_set_value(gpio_req, 0);
        }

        usleep(200000); // Sleep for 200ms
    }

cleanup:
    // Power down sensor
    i2c_msgs[0].buf[0] &= ~0x01; // Clear PON bit
    if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) < 0) {
        perror("Failed to power down sensor");
    }

    // Release GPIO line
    if (gpio_req) {
        gpiod_line_release(gpio_req);
    }

    // Close I2C file descriptor
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    // Close GPIO file descriptor
    if (gpio_fd >= 0) {
        gpiod_close(gpio_fd);
    }

    return 0;
}

