#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

#define BH1750_ADDR 0x23
#define BH1750_CMD_MEAS_ONE_TIME_HIGH_RES 0x23
#define WS2812B_BIT_DURATION 10
#define WS2812B_LED_COUNT 10
#define WS2812B_LED_DATA_PIN 18

struct gpiod_line_request *pwm_request;
struct i2c_rdwr_ioctl_data i2c_data;
struct i2c_msg i2c_msgs[2];

int init_i2c(void) {
    int file;
    if ((file = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    i2c_msgs[0].addr = BH1750_ADDR;
    i2c_msgs[0].flags = 0;
    i2c_msgs[0].len = 1;
    i2c_msgs[0].buf = &BH1750_CMD_MEAS_ONE_TIME_HIGH_RES;

    i2c_msgs[1].addr = BH1750_ADDR;
    i2c_msgs[1].flags = I2C_M_RD;
    i2c_msgs[1].len = 2;

    i2c_data.wr_msgs = i2c_msgs;
    i2c_data.nr_msgs = 2;

    return file;
}

int init_gpio(void) {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line_config config = GPIOD_LINE_ACTIVE_HIGH | GPIOD_LINE_REQUEST_IN;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    pwm_request = gpiod_chip_get_line(chip, WS2812B_LED_DATA_PIN);
    if (!pwm_request) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_enable(pwm_request, &config);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(pwm_request);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_set_value(pwm_request, 0);
    if (ret < 0) {
        perror("Failed to set initial GPIO value");
        gpiod_line_release(pwm_request);
        gpiod_line_request_deactivate(pwm_request);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

void send_ws2812b_color(unsigned char r, unsigned char g, unsigned char b) {
    unsigned long long bitmask = 1ULL << (WS2812B_BIT_DURATION * WS2812B_LED_COUNT - 1);
    unsigned long long bitshift = WS2812B_BIT_DURATION * WS2812B_LED_COUNT - 1;
    unsigned long long data = 0;

    for (int i = 0; i < WS2812B_LED_COUNT; ++i) {
        data |= (r & 0x01) << bitshift;
        bitshift -= WS2812B_BIT_DURATION;
        r >>= 1;

        data |= (g & 0x01) << (bitshift + WS2812B_BIT_DURATION);
        bitshift -= WS2812B_BIT_DURATION;
        g >>= 1;

        data |= (b & 0x01) << (bitshift + 2 * WS2812B_BIT_DURATION);
        bitshift -= 2 * WS2812B_BIT_DURATION;
        b >>= 1;

        gpiod_line_set_value(pwm_request, (data & bitmask) ? 1 : 0);
        usleep(WS2812B_BIT_DURATION * 1000);
        gpiod_line_set_value(pwm_request, 0);
        usleep(WS2812B_BIT_DURATION * 1000);
    }
}

float map_lux_to_brightness(float lux) {
    // Adjust this function to map lux values to your desired brightness range
    return log10(lux + 1);
}

int main(void) {
    int i2c_fd;
    unsigned char data[2];
    float lux;
    int retries = 3;

    i2c_fd = init_i2c();
    if (i2c_fd < 0) {
        return 1;
    }

    if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) < 0) {
        perror("Failed to perform I2C read");
        close(i2c_fd);
        return 1;
    }

    if (init_gpio() < 0) {
        close(i2c_fd);
        return 1;
    }

    while (1) {
        for (int i = 0; i < retries; ++i) {
            if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) >= 0) {
                lux = (data[0] << 8 | data[1]) * 0.01;
                break;
            }
            usleep(180 * 1000);
        }

        if (i == retries) {
            perror("Failed to read lux value after retries");
            goto cleanup;
        }

        float brightness = map_lux_to_brightness(lux);
        for (int i = 0; i < WS2812B_LED_COUNT; ++i) {
            send_ws2812b_color(brightness * (WS2812B_LED_COUNT - i), brightness, 0);
        }

        usleep(180 * 1000);
    }

cleanup:
    gpiod_line_release(pwm_request);
    gpiod_line_request_deactivate(pwm_request);
    gpiod_chip_close(gpiod_chip_get_chip_data(pwm_request->chip));
    close(i2c_fd);

    return 0;
}

