code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/mman.h>
#include <gpiod.h>
#include <pthread.h>
#include <time.h>

#define BH1750_ADDR1 0x23
#define BH1750_ADDR2 0x5C
#define APA102_MOSI_GPIO 10
#define APA102_SCLK_GPIO 11
#define NUM_SENSORS 3
#define FADE_TIME_MS 500
#define DELAY_MS 100
#define I2C_BUS 1

struct bh1750_data {
    int fd;
    int address;
};

struct apa102_data {
    gpiod_line_request_data request;
    gpiod_line_data *line;
};

struct sensor_data {
    struct bh1750_data bh1750;
    int16_t light_level;
};

struct apa102_data apa102;
struct sensor_data sensors[NUM_SENSORS];

void sigint_handler(int signum) {
    close_apa102();
    close_bh1750_sensors();
    gpiod_line_release(&apa102.request);
    exit(0);
}

int open_bh1750(int address) {
    int ret;
    char filename[32];
    snprintf(filename, sizeof(filename), "/dev/i2c-1", I2C_BUS);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if ((ret = ioctl(fd, I2C_SLAVE, address << 1)) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

void close_bh1750(struct bh1750_data *bh1750) {
    if (bh1750->fd >= 0) {
        close(bh1750->fd);
        bh1750->fd = -1;
    }
}

int read_bh1750(struct bh1750_data *bh1750) {
    int ret;
    uint8_t data[2];

    ret = write(bh1750->fd, 0x23, 1);
    if (ret != 1) {
        perror("Failed to write command to BH1750");
        return -1;
    }

    usleep(180 * 1000);

    ret = read(bh1750->fd, data, 2);
    if (ret != 2) {
        perror("Failed to read data from BH1750");
        return -1;
    }

    bh1750->light_level = (data[0] << 8) | data[1];
    return 0;
}

int average_light_levels(struct sensor_data *sensors, int num_sensors) {
    int total = 0;
    for (int i = 0; i < num_sensors; ++i) {
        if (sensors[i].light_level >= 0) {
            total += sensors[i].light_level;
        }
    }

    if (num_sensors > 0) {
        return total / num_sensors;
    }

    return 0;
}

int init_apa102() {
    int ret;
    gpiod_line_flags_t flags = GPIOD_LINE_ACTIVE_HIGH | GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REPORT_EDGE_FALLING;

    ret = gpiod_chip_open_byname("gpiochip0");
    if (ret < 0) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    ret = gpiod_line_request_dt(&apa102.request, APA102_MOSI_GPIO, "ap102_mosi", flags);
    if (ret < 0) {
        perror("Failed to request GPIO line for APA102 MOSI");
        gpiod_chip_close(ret);
        return -1;
    }

    apa102.line = gpiod_get_line_data(ret);
    if (!apa102.line) {
        perror("Failed to get GPIO line data for APA102 MOSI");
        gpiod_line_release(&apa102.request);
        gpiod_chip_close(ret);
        return -1;
    }

    return 0;
}

void set_apa102_brightness(uint32_t brightness) {
    uint8_t data[APA102_NUM_PIXELS];
    for (int i = 0; i < APA102_NUM_PIXELS; ++i) {
        data[i] = (brightness >> (i * 8)) & 0xFF;
    }

    gpiod_line_set_value(apa102.line, 0);
    gpiod_line_set_value(apa102.line, 1);

    write(apa102.line->fd, data, APA102_NUM_PIXELS);
}

void fade_apa102_brightness(uint32_t start, uint32_t end, uint32_t duration_ms) {
    uint32_t current_brightness = start;
    struct timespec start_time, current_time;

    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (current_brightness != end) {
        current_time.tv_sec = start_time.tv_sec;
        current_time.tv_nsec = start_time.tv_nsec + (duration_ms * 1000 * 1000);
        if (current_time.tv_nsec > 1000 * 1000 * 1000) {
            current_time.tv_sec++;
            current_time.tv_nsec -= 1000 * 1000 * 1000;
        }

        clock_nanosleep(CLOCK_MONOTONIC, TIMER_ABSTIME, &current_time, NULL);

        set_apa102_brightness(current_brightness);
        current_brightness += (end - start) / (duration_ms / 2);
    }

    set_apa102_brightness(end);
}

void close_apa102() {
    gpiod_line_release(&apa102.request);
    gpiod_chip_close(apa102.request.chip);
}

int main() {
    signal(SIGINT, sigint_handler);

    if (init_apa102() < 0) {
        perror("Failed to initialize APA102");
        return -1;
    }

    for (int i = 0; i < NUM_SENSORS; ++i) {
        sensors[i].bh1750.fd = open_bh1750(BH1750_ADDR1 + i);
        if (sensors[i].bh1750.fd >= 0) {
            if (read_bh1750(&sensors[i].bh1750) < 0) {
                close_bh1750(&sensors[i].bh1750);
                sensors[i].light_level = -1;
            }
        } else {
            sensors[i].light_level = -1;
        }
    }

    uint32_t target_brightness = 0;
    while (1) {
        int num_sensors = 0;
        for (int i = 0; i < NUM_SENSORS; ++i) {
            if (sensors[i].light_level >= 0) {
                ++num_sensors;
            }
        }

        int average_light_level = average_light_levels(sensors, num_sensors);
        if (num_sensors > 0) {
            target_brightness = (average_light_level * 255) / 1024;
        }

        if (target_brightness != apa102.brightness) {
            fade_apa102_brightness(apa102.brightness, target_brightness, FADE_TIME_MS);
            apa102.brightness = target_brightness;
        }

        usleep(DELAY_MS * 1000);
    }

    close_apa102();
    close_bh1750_sensors();

    return 0;
}

void close_bh1750_sensors() {
    for (int i = 0; i < NUM_SENSORS; ++i) {
        close_bh1750(&sensors[i].bh1750);
    }
}

