        return -1;
    }

    return 0;
}

void deinit_gpio(void) {
    gpiod_line_release_prologue(gpio_handle);
    gpiod_line_release(gpio_handle);
    gpiod_chip_close(chip);
    close(gpio_fd);
}

int read_lux(void) {
    int i2c_file, retries = I2C_RETRIES;
    char buf[2];

    i2c_file = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_file < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(i2c_file, I2C_SLAVE, VEML7700_ADDR) < 0) {
        perror("Failed to acquire I2C bus");
        goto i2c_close;
    }

    while (retries > 0) {
        if (write(i2c_file, (const char[]) { 0x01, 0x00 }, 2) != 2) {
