        fprintf(stderr, "Failed to communicate with VEML7700 after %d retries\n", I2C_RETRIES);
        goto i2c_close;
    }

    int lux = (buf[0] << 8) | buf[1];
    printf("Lux: %d\n", lux);
    return lux;

i2c_close:
    close(i2c_file);
    return -1;
}

