void compute_brightness(int lux, uint32_t *color) {
    double brightness = pow(lux / 32768.0, GAMMA_CORRECTION_FACTOR);
    brightness = brightness > MAX_BRIGHTNESS ? MAX_BRIGHTNESS : (brightness < 0 ? 0 : brightness);

    *color = (uint32_t)(brightness * 255);
}

void signal_handler(int sig) {
    printf("Received signal %d, exiting gracefully...\n", sig);
    deinit_gpio();
    exit(0);
}

int main(void) {
    if (init_gpio() < 0) {
