            continue;
        }

        compute_brightness(lux, &color);

        if (color > LED_ON_THRESHOLD) {
            bit_bang_ws2812b(color);
        }

        usleep(200000); // 200ms pause between iterations
    }

    deinit_gpio();
    return 0;
}

