            int led_state = gpiod_line_get_value(lines_data.lines[GPIO_LED].dev, lines_data.lines[GPIO_LED].number);
            int buzzer_state = gpiod_line_get_value(lines_data.lines[GPIO_BUZZER].dev, lines_data.lines[GPIO_BUZZER].number);
            strcat(log_str, "LED: ");
            strcat(log_str, led_state ? "ON" : "OFF");
            strcat(log_str, ", Buzzer: ");
            strcat(log_str, buzzer_state ? "ON" : "OFF");
        }
        printf("%s\n", log_str);
        usleep(50000);
    }

