#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define LED_GPIO 17
#define BUFFER_SIZE 60

struct i2c_data {
    int fd;
    char *map_base;
};

int i2c_init() {
    int ret;
    struct i2c_dev *i2c_dev;
    struct i2c_adapter *adap;
    struct i2c_client *client;

    ret = open("/dev/i2c-1", O_RDWR);
    if (ret < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    i2c_dev = mmap(NULL, sizeof(struct i2c_dev), PROT_READ | PROT_WRITE, MAP_SHARED, ret, 0);
    if (i2c_dev == MAP_FAILED) {
        perror("Failed to mmap I2C bus");
        close(ret);
        return -1;
    }
    i2c_data *data = (i2c_data *)i2c_dev;
    data->fd = ret;

    ret = ioctl(ret, I2C_SLAVE, BH1750_ADDR << 1);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        munmap(i2c_dev, sizeof(struct i2c_dev));
        close(ret);
        return -1;
    }

    adap = i2c_get_adapter(I2C_BUS);
    if (!adap) {
        perror("Failed to get I2C adapter");
        munmap(i2c_dev, sizeof(struct i2c_dev));
        close(ret);
        return -1;
    }

    client = kzalloc(sizeof(struct i2c_client), GFP_KERNEL);
    if (!client) {
        perror("Failed to allocate I2C client");
        i2c_put_adapter(adap);
        munmap(i2c_dev, sizeof(struct i2c_dev));
        close(ret);
        return -1;
    }

    client->addr = BH1750_ADDR << 1;
    client->adapter = adap;
    i2c_attach_client(adap, client);

    data->map_base = (char *)ioremap_nocache(client->addr, 2);
    if (!data->map_base) {
        perror("Failed to ioremap I2C client");
        i2c_detach_client(adap, client);
        kfree(client);
        i2c_put_adapter(adap);
        munmap(i2c_dev, sizeof(struct i2c_dev));
        close(ret);
        return -1;
    }

    return 0;
}

void i2c_cleanup(i2c_data *data) {
    if (data->map_base) {
        iounmap(data->map_base);
    }
    i2c_detach_client(data->fd, (struct i2c_client *)((char *)data->map_base - offsetof(struct i2c_client, adapter)));
    kfree((struct i2c_client *)((char *)data->map_base - offsetof(struct i2c_client, adapter)));
    i2c_put_adapter((data->fd)->adapter);
    close(data->fd);
    munmap(data, sizeof(struct i2c_data));
}

int read_lux(i2c_data *data) {
    int ret;
    uint8_t buf[2];

    ret = i2c_smbus_read_word_data(data->fd, 0x23);
    if (ret < 0) {
        perror("Failed to read lux from sensor");
        return -1;
    }

    buf[0] = ret & 0xFF;
    buf[1] = (ret >> 8) & 0xFF;

    return (buf[0] << 8) | buf[1];
}

void blink_led(int duty_cycle) {
    static const int ON_STATE = 1;
    static const int OFF_STATE = 0;
    static int prev_state = OFF_STATE;
    static struct timespec next_blink;
    struct timespec now;

    clock_gettime(CLOCK_MONOTONIC, &now);

    if (now.tv_sec > next_blink.tv_sec || (now.tv_sec == next_blink.tv_sec && now.tv_nsec >= next_blink.tv_nsec)) {
        if (duty_cycle > 0.5) {
            gpio_write(LED_GPIO, ON_STATE);
        } else {
            gpio_write(LED_GPIO, OFF_STATE);
        }

        next_blink.tv_sec = now.tv_sec + 1;
        next_blink.tv_nsec = (duty_cycle * 1e9);
        if (next_blink.tv_nsec > 1e9) {
            next_blink.tv_nsec -= 1e9;
            next_blink.tv_sec++;
        }

        prev_state = (prev_state == ON_STATE) ? OFF_STATE : ON_STATE;
    }
}

int main() {
    int ret;
    i2c_data data;
    int lux_buffer[BUFFER_SIZE];
    int buffer_index = 0;
    double average_lux = 0.0;

    ret = i2c_init();
    if (ret < 0) {
        return 1;
    }

    signal(SIGINT, i2c_cleanup);

    while (1) {
        int lux = read_lux(&data);
        if (lux < 0) {
            perror("Failed to read lux from sensor");
            continue;
        }

        lux_buffer[buffer_index] = lux;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        average_lux = 0.0;

        for (int i = 0; i < BUFFER_SIZE; i++) {
            average_lux += lux_buffer[i];
        }
        average_lux /= BUFFER_SIZE;

        blink_led(average_lux / 1000.0);

        sleep(1);
    }

    i2c_cleanup(&data);
    return 0;
}

