    if (ret < 0) {
        perror("Failed to request GPIO lines");
        goto cleanup;
    }

    usleep(100000); // Delay for the debouncing of the GPIO lines

    for (size_t i = 0; i < 8; ++i) {
        unsigned char bit = (digit_5[i] << 1) | 1;
