#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/types.h>
#include <gpiod.h>

#define LED_GPIO 24
#define BUTTON_GPIO 22
#define LED_ON (1 << LED_GPIO)
#define BUTTON_ACTIVE_LOW (1 << BUTTON_GPIO)
#define DELAY_MS 500

int main(void) {
    int ret;
    gpiod_line_request_lines(1, &LED_GPIO, "led", GPIOD_LINE_REQUEST_DIRECTION_OUT | GPIOD_LINE_REQUEST_ACTIVE_LOW);
    if (gpiod_line_get_error()) {
        perror("Failed to request line for LED");
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_lines(1, &BUTTON_GPIO, "button", GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_INPUT_PULL_DOWN);
    if (gpiod_line_get_error()) {
        perror("Failed to request line for button");
        exit(EXIT_FAILURE);
    }

    while (1) {
        gpiod_line_value_cansleep(BUTTON_GPIO, GPIOD_LINE_VALUE_INPUT);
        if (!(gpiod_line_get_value(BUTTON_GPIO))) {
            gpiod_line_value_cansleep(LED_GPIO, GPIOD_LINE_VALUE_OUTPUT_HIGH);
            usleep(DELAY_MS * 1000);
            gpiod_line_value_cansleep(LED_GPIO, GPIOD_LINE_VALUE_OUTPUT_LOW);
            usleep(DELAY_MS * 1000);
        }
    }

    gpiod_line_release(LED_GPIO);
    gpiod_line_release(BUTTON_GPIO);
    gpiod_chip_release(gpiod_chip_open_with_label("gpiochip0"));
    return 0;
}
