    { .direction = GPIOD_LINE_DIR_OUT, .flags = GPIOD_LINE_FLAG_ACTIVE_LOW },
};

static gpiod_line_request_lines_request_data_t lines_request_data = {
    .consumer = "rgb_led",
    .request_lines = lines_data,
    .n_lines = sizeof(lines_data) / sizeof(lines_data[0]),
};

static gpiod_line_handle_t *led_handles[3];

void signal_handler(int signum) {
    for (size_t i = 0; i < sizeof(led_handles) / sizeof(led_handles[0]); ++i) {
        if (led_handles[i]) {
            gpiod_line_release(led_handles[i]);
            led_handles[i] = NULL;
        }
    }
    exit(0);
}

