        led_handles[i] = lines_request_data.request_lines[i].handle;
    }

    while (1) {
        r = rand() % 101;
        g = rand() % 101;
        b = rand() % 101;

        gpiod_line_set_value(led_handles[0], r > 50);
        gpiod_line_set_value(led_handles[1], g > 50);
        gpiod_line_set_value(led_handles[2], b > 50);

        clock_nanosleep(CLOCK_MONOTONIC, 0, &pwm_ts, NULL);

        clock_nanosleep(CLOCK_MONOTONIC, 0, &ts, NULL);
    }

cleanup:
    for (size_t i = 0; i < sizeof(led_handles) / sizeof(led_handles[0]); ++i) {
        if (led_handles[i]) {
            gpiod_line_release(led_handles[i]);
            led_handles[i] = NULL;
        }
    }
    gpiod_context_put(&ctx);
    return 0;
