#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <gpiod.h>
#include <time.h>

#define I2C_BUS 1
#define ACC_ADDR 0x3C
#define XOUT_L_REG 0x28
#define YOUT_L_REG 0x2A
#define ZOUT_L_REG 0x2C
#define GPIO_LINE_ID_OUT 17
#define DEFAULT_THRESHOLD 2.0

struct i2c_data {
    int fd;
    void *map_base;
};

int i2c_init(struct i2c_data *data) {
    char filename[32];
    snprintf(filename, sizeof(filename), "/dev/i2c-1", I2C_BUS);
    data->fd = open(filename, O_RDWR);
    if (data->fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(data->fd, I2C_SLAVE, ACC_ADDR) < 0) {
        perror("Failed to acquire I2C bus");
        close(data->fd);
        return -1;
    }

    if (ioctl(data->fd, I2C_MEMADD_10BIT, ACC_ADDR << 1) < 0) {
        perror("Failed to set 10-bit I2C address");
        close(data->fd);
        return -1;
    }

    return 0;
}

void i2c_exit(struct i2c_data *data) {
    if (data->map_base) {
        munmap(data->map_base, 32);
    }
    if (data->fd >= 0) {
        ioctl(data->fd, I2C_MEMADD_10BIT, 0);
        close(data->fd);
    }
}

int i2c_read(struct i2c_data *data, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (read(data->fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }
    *val = (buf[0] << 8) | buf[1];
    return 0;
}

void gpio_setup(struct gpiod_chip *chip, struct gpiod_line *line, int direction) {
    int ret;
    ret = gpiod_chip_open_byname(chip, "gpiochip0");
    if (ret < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(line, direction);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

void gpio_pulse(struct gpiod_line *line, int on_ms) {
    struct timespec ts;
    gpiod_line_set_value(line, 1);
    nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = on_ms * 1e6}, NULL);
    gpiod_line_set_value(line, 0);
}

int main(int argc, char **argv) {
    struct i2c_data i2c;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    double threshold = DEFAULT_THRESHOLD;
    int ret;

    if (argc > 2) {
        threshold = atof(argv[2]);
    }

    ret = i2c_init(&i2c);
    if (ret < 0) {
        exit(EXIT_FAILURE);
    }

    chip = gpiod_chip_get_bylabel("gpiochip0");
    if (!chip) {
        perror("Failed to find GPIO chip");
        i2c_exit(&i2c);
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_ID_OUT);
    if (!line) {
        perror("Failed to find GPIO line");
        gpiod_chip_put(chip);
        i2c_exit(&i2c);
        exit(EXIT_FAILURE);
    }

    gpio_setup(chip, line, GPIOD_LINE_ACTIVE_HIGH);

    FILE *log_file = fopen("impact_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_put(chip);
        i2c_exit(&i2c);
        exit(EXIT_FAILURE);
    }

    uint16_t x, y, z;
    double mag;
    clock_gettime(CLOCK_MONOTONIC, &ts_start);
    while (1) {
        ret = i2c_read(&i2c, XOUT_L_REG, &x);
        if (ret < 0) {
            perror("Failed to read X data");
            break;
        }
        ret = i2c_read(&i2c, YOUT_L_REG, &y);
        if (ret < 0) {
            perror("Failed to read Y data");
            break;
        }
        ret = i2c_read(&i2c, ZOUT_L_REG, &z);
        if (ret < 0) {
            perror("Failed to read Z data");
            break;
        }

        mag = sqrt(x * x + y * y + z * z) / 16384.0;
        if (mag > threshold) {
            gpio_pulse(line, 50);
            fprintf(log_file, "%lld,%f,%f,%f\n", ts_start.tv_sec * 1e9 + ts_start.tv_nsec, x / 16384.0, y / 16384.0, z / 16384.0);
        }

        usleep(100000);
    }

    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_put(chip);
    i2c_exit(&i2c);

    return 0;
}

