    FILE *log_file = fopen("impact_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_put(chip);
        i2c_exit(&i2c);
        exit(EXIT_FAILURE);
    }

    uint16_t x, y, z;
    double mag;
    clock_gettime(CLOCK_MONOTONIC, &ts_start);
    while (1) {
        ret = i2c_read(&i2c, XOUT_L_REG, &x);
        if (ret < 0) {
            perror("Failed to read X data");
            break;
        }
        ret = i2c_read(&i2c, YOUT_L_REG, &y);
        if (ret < 0) {
            perror("Failed to read Y data");
            break;
        }
        ret = i2c_read(&i2c, ZOUT_L_REG, &z);
        if (ret < 0) {
            perror("Failed to read Z data");
            break;
        }

        mag = sqrt(x * x + y * y + z * z) / 16384.0;
        if (mag > threshold) {
            gpio_pulse(line, 50);
            fprintf(log_file, "%lld,%f,%f,%f\n", ts_start.tv_sec * 1e9 + ts_start.tv_nsec, x / 16384.0, y / 16384.0, z / 16384.0);
        }

        usleep(100000);
    }

    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_put(chip);
    i2c_exit(&i2c);

    return 0;
}
