#define GYRO_WHO_AM_I 0x75
#define GYRO_XOUT_H 0x28
#define GYRO_XOUT_L 0x29
#define GYRO_YOUT_H 0x2A
#define GYRO_YOUT_L 0x2B
#define GYRO_ZOUT_H 0x2C
#define GYRO_ZOUT_L 0x2D
#define SAMPLES_FOR_CALIBRATION 100
#define SAMPLE_RATE 20
#define DPS_THRESHOLD 50.0

static gpiod_line_request_linenum_t gyro_alert_line;
static int gyro_fd;
static int32_t gyro_zero_offsets[3] = {0};
static time_t last_log_time = 0;

void gyro_alert_handler(struct gpiod_line_event *ev) {
    if (ev->value == 0) {
        char timestamp[32];
        struct tm tm;
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime_r(&now, &tm));
        fprintf(stderr, "Gyro alert: X=%d Y=%d Z=%d at %s\n",
                gyro_zero_offsets[0], gyro_zero_offsets[1], gyro_zero_offsets[2], timestamp);
        fprintf(stderr, "Gyro data may be inaccurate.\n");
    }
}

int init_gyro() {
    gyro_fd = open("/dev/i2c-1", O_RDWR);
    if (gyro_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(gyro_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire bus access");
        close(gyro_fd);
        return -1;
    }

    uint8_t who_am_i;
    if (read(gyro_fd, &who_am_i, 1) != 1 || who_am_i != GYRO_WHO_AM_I) {
        perror("GY-50 L3G4200D not found");
        close(gyro_fd);
        return -1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(gyro_fd);
        return -1;
    }

    gpio_request_line(chip, 17, "gyro_alert", GPIOD_ASIS);
    gpio_direction_input(gyro_alert_line);
    gpio_set_debounce(gyro_alert_line, 10);
    gpio_add_event_callback(gyro_alert_line, gyro_alert_handler, NULL);

    return 0;
}

void read_gyro_data(int16_t *data) {
    if (read(gyro_fd, data, sizeof(int16_t) * 3) != sizeof(int16_t) * 3) {
        perror("Failed to read gyro data");
    }
}

void log_gyro_data() {
    time_t now = time(NULL);
    struct tm tm;
    struct timeval tv;
    gettimeofday(&tv, NULL);
    strftime(tm.tm_buf, sizeof(tm.tm_buf), "%Y-%m-%d %H:%M:%S", localtime_r(&now, &tm));

    char timestamp[32];
    snprintf(timestamp, sizeof(timestamp), "%ld.%06ld ", tv.tv_sec, tv.tv_usec);

    FILE *log_file = fopen("gyro_log.txt", "a");
    if (!log_file) {
        perror("Failed to open gyro log file");
