    last_log_time = now;
}

void cleanup() {
    gpio_free(gyro_alert_line);
    close(gyro_fd);
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        cleanup();
        exit(0);
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_gyro() < 0) {
        return 1;
    }

    for (size_t i = 0; i < SAMPLES_FOR_CALIBRATION; ++i) {
        int16_t gyro_data[3];
