        gyro_zero_offsets[0] += gyro_data[0];
        gyro_zero_offsets[1] += gyro_data[1];
        gyro_zero_offsets[2] += gyro_data[2];
    }

    gyro_zero_offsets[0] /= SAMPLES_FOR_CALIBRATION;
    gyro_zero_offsets[1] /= SAMPLES_FOR_CALIBRATION;
    gyro_zero_offsets[2] /= SAMPLES_FOR_CALIBRATION;

    struct timespec period;
    period.tv_sec = 1.0 / SAMPLE_RATE;
