#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <sys/time.h>
#include <gpiod.h>

#define ADXL345_ADDR 0x53
#define DATA_X_LSB   0x32
#define DATA_Y_LSB   0x34
#define DATA_Z_LSB   0x36
#define DEVICE_ID    0x3D
#define FULL_RES     (1 << 6)
#define TWO_G        (2.0 / 16.0)
#define GPIO_LED_LINE "gpiochip0\07717"

int main() {
    int i2c_fd, gpio_fd;
    struct i2c_rdwr_ioctl_data i2c_data[2];
    struct timespec ts;
    uint8_t device_id;
    int16_t data_x, data_y, data_z;
    double x, y, z;
    char log_buf[64];
    FILE *log_file;
    gpiod_line_request_linestate_t led_state;
    gpiod_line_request *led_request;

    // Open I2C bus
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Initialize I2C data
    i2c_data[0].addr = ADXL345_ADDR;
    i2c_data[0].flags = 0;
    i2c_data[0].len = 1;
    i2c_data[0].buf = &device_id;

    i2c_data[1].addr = ADXL345_ADDR;
    i2c_data[1].flags = I2C_M_RD;
    i2c_data[1].len = 6;
    i2c_data[1].buf = (uint8_t *)&data_x;

    // Check device ID
    if (ioctl(i2c_fd, I2C_RDWR, i2c_data) < 0) {
        perror("Failed to read device ID");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (device_id != DEVICE_ID) {
        fprintf(stderr, "Incorrect device ID\n");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Configure ADXL345 for full-resolution mode with ±2g range
    i2c_data[0].buf[0] = 0x2D;
    i2c_data[0].len = 1;
    i2c_data[1].buf[0] = FULL_RES | (FULL_RES << 1) | (FULL_RES << 2);
    i2c_data[1].len = 1;

    if (ioctl(i2c_fd, I2C_RDWR, i2c_data) < 0) {
        perror("Failed to configure ADXL345");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Open log file
    if ((log_file = fopen("accel_log.txt", "w")) == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Request GPIO line for LED
    if ((gpio_fd = gpiod_open_name_with_linestate(GPIO_LED_LINE, GPIOD_LINE_REQUEST_DIRECTION_OUT, 0)) < 0) {
        perror("Failed to open GPIO line");
        fclose(log_file);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    led_request = gpiod_get_request(gpio_fd);

    // Main loop
    while (1) {
        // Read acceleration data
        if (ioctl(i2c_fd, I2C_RDWR, i2c_data) < 0) {
            perror("Failed to read acceleration data");
            continue;
        }

        data_x = ((int16_t)i2c_data[1].buf[1] << 8) | i2c_data[1].buf[0];
        data_y = ((int16_t)i2c_data[1].buf[3] << 8) | i2c_data[1].buf[2];
        data_z = ((int16_t)i2c_data[1].buf[5] << 8) | i2c_data[1].buf[4];

        x = data_x / 16.0;
        y = data_y / 16.0;
        z = data_z / 16.0;

        // Format and write log entry
        snprintf(log_buf, sizeof(log_buf), "%lld,%.3f,%.3f,%.3f\n", (long long)ts.tv_sec * 1000 + ts.tv_nsec / 1000000, x, y, z);
        if (fwrite(log_buf, strlen(log_buf), 1, log_file) != 1) {
            perror("Failed to write log entry");
            continue;
        }

        // Check if any axis exceeds 2.0g
        if (fabs(x) > TWO_G || fabs(y) > TWO_G || fabs(z) > TWO_G) {
            led_state = GPIOD_LINE_REQUEST_ACTIVE;
            gpiod_line_set_value(led_request, led_state);
        } else {
            led_state = GPIOD_LINE_REQUEST_INACTIVE;
            gpiod_line_set_value(led_request, led_state);
        }

        // Sleep for 100ms
        ts.tv_sec = 0;
        ts.tv_nsec = 100 * 1e6;
        nanosleep(&ts, NULL);
    }

    // Cleanup
    gpiod_line_release(led_request);
    gpiod_close(gpio_fd);
    fclose(log_file);
    close(i2c_fd);

    return 0;
}

