        perror("write");
        exit(EXIT_FAILURE);
    }

    if (read(data->fd, buf, len) != len) {
        perror("read");
        exit(EXIT_FAILURE);
    }
}

void i2c_write(struct i2c_data *data, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(data->fd, buf, 2) != 2) {
        perror("write");
        exit(EXIT_FAILURE);
    }
}

void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        fclose(log_file);
        gpiod_close_all();
        exit(EXIT_SUCCESS);
    }
}

void print_data(float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z) {
    time_t rawtime;
    struct tm *time_info;
    char time_buffer[80];

    time(&rawtime);
    time_info = localtime(&rawtime);

    strftime(time_buffer, sizeof(time_buffer), "%Y-%m-%d %H:%M:%S", time_info);

    fprintf(log_file, "%s,Heading,Accel_x,Accel_y,Accel_z,Mag_x,Mag_y,Mag_z\n", time_buffer);
    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n", time_buffer, heading, accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);
}

int main() {
    struct i2c_data accel_data, mag_data;
    unsigned char buf[6];
    float accel_x, accel_y, accel_z, mag_x, mag_y, mag_z, heading;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_init(&accel_data, I2C_ADDR_ACCEL);
    i2c_init(&mag_data, I2C_ADDR_MAG);

    // Initialize the sensor and calculate the heading here
    // ...

    while (1) {
        usleep(SAMPLE_INTERVAL_MS * 1000);

        i2c_read(&accel_data, 0x3b, buf, 6);
        accel_x = (float)buf[0] / 16384.0 - 2.0;
        accel_y = (float)buf[1] / 16384.0 - 2.0;
        accel_z = (float)buf[2] / 16384.0 + 1.0;

        i2c_read(&mag_data, 0x03, buf, 6);
        mag_x = (float)buf[1] / 131.0;
        mag_y = (float)buf[3] / 131.0;
        mag_z = (float)buf[5] / 131.0;

        // Calculate the heading here
        // ...

        print_data(accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);
    }

    close(accel_data.fd);
    close(mag_data.fd);

    return 0;
}
