code:
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/time.h>
#include <time.h>
#include <pthread.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR_SENSOR1 0x30
#define I2C_ADDR_SENSOR2 0x31
#define SAMPLE_RATE 100
#define BUFFER_SIZE 16

static gpiod_line_request_linenum_t sensor_reset_line;
static gpiod_line_state_callback_t sensor_reset_cb;
static gpiod_line_data_callback_t sensor_data_cb;
static gpiod_line_data_callback_data_t sensor_data_cb_data;
static gpiod_line_request_data_t sensor_reset_request_data = { .active_low = 1 };
static gpiod_line_data_callback_data_t sensor_data_callback_data[2];
static int i2c_fds[2];
static FILE *log_file;
static pthread_t sampling_thread;
static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
    gpiod_line_request_release(sensor_reset_line);
    close(i2c_fds[0]);
    close(i2c_fds[1]);
    fclose(log_file);
    pthread_join(sampling_thread, NULL);
    gpiod_unload_driver();
    exit(0);
}

int init_i2c(int addr) {
    int ret;
    char filename[32];
    snprintf(filename, sizeof(filename), "/dev/i2c-1", I2C_BUS);
    i2c_fds[addr] = open(filename, O_RDWR);
    if (i2c_fds[addr] < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if ((ret = ioctl(i2c_fds[addr], I2C_SLAVE, addr)) < 0) {
        perror("Failed to acquire I2C bus");
        close(i2c_fds[addr]);
        return -1;
    }

    return 0;
}

int init_gpio(int line) {
    gpiod_line_request_flags_t flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW;
    int ret;

    ret = gpiod_chip_open_byname("gpiochip0");
    if (ret < 0) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    ret = gpiod_line_request_get_byname(ret, "gpio" + std::to_string(line));
    if (ret < 0) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(ret);
        return -1;
    }

    ret = gpiod_line_request_set_flags(ret, flags);
    if (ret < 0) {
        perror("Failed to set GPIO line flags");
        gpiod_line_release(ret);
        gpiod_chip_close(ret);
        return -1;
    }

    ret = gpiod_line_request_get_line(ret, &sensor_reset_line);
    if (ret < 0) {
        perror("Failed to get GPIO line handle");
        gpiod_line_release(ret);
        gpiod_chip_close(ret);
        return -1;
    }

    ret = gpiod_line_request_set_debounce(sensor_reset_line, 10);
    if (ret < 0) {
        perror("Failed to set GPIO line debounce");
        gpiod_line_release(sensor_reset_line);
        gpiod_chip_close(ret);
        return -1;
    }

    sensor_reset_cb = [](struct gpiod_chan *chan, int event, void *data) {
        if (event == GPIOD_LINE_EVENT_EDGE_FALLING) {
            gpiod_line_data_callback_set(chan, sensor_data_cb, &sensor_data_callback_data[chan->line_number]);
        }
    };

    ret = gpiod_line_add_event_callback(sensor_reset_line, sensor_reset_cb, NULL);
    if (ret < 0) {
        perror("Failed to add GPIO line event callback");
        gpiod_line_release(sensor_reset_line);
        gpiod_chip_close(ret);
        return -1;
    }

    return 0;
}

void *sample_and_log(void *arg) {
    struct timespec ts;
    int16_t samples[BUFFER_SIZE][2];
    int ret;

    while (running) {
        clock_gettime(CLOCK_REALTIME, &ts);

        for (int i = 0; i < 2; ++i) {
            ret = read_i2c_sensor(i2c_fds[i], samples[i], BUFFER_SIZE);
            if (ret < 0) {
                fprintf(stderr, "Failed to read sensor %d\n", i);
                continue;
            }
        }

        double tdoa = (ts.tv_sec * 1e9 + ts.tv_nsec - samples[1][0] * 1e-6 - samples[0][0] * 1e-6) * 1e-9;

        fprintf(log_file, "%lld,%09ld,%d,%d,%f\n", ts.tv_sec, ts.tv_nsec, samples[0][1], samples[1][1], tdoa);

        usleep(10000);
    }

    return NULL;
}

int read_i2c_sensor(int fd, int16_t samples[BUFFER_SIZE], int size) {
    int ret;
    char buf[size * 2];

    ret = read(fd, buf, size * 2);
    if (ret != size * 2) {
        perror("Failed to read from I2C sensor");
        return -1;
    }

    for (int i = 0; i < size; ++i) {
        samples[i] = ((buf[i * 2] << 8) | buf[i * 2 + 1]);
    }

    return 0;
}

int main() {
    int ret;

    signal(SIGINT, sigint_handler);

    if ((ret = init_gpio(18)) < 0) {
        perror("Failed to initialize GPIO");
        return -1;
    }

    usleep(100000);

    if ((ret = init_gpio(23)) < 0) {
        perror("Failed to initialize GPIO");
        gpiod_line_release(sensor_reset_line);
        gpiod_chip_close(ret);
        return -1;
    }

    if ((ret = init_i2c(I2C_ADDR_SENSOR1)) < 0) {
        perror("Failed to initialize I2C bus for sensor 1");
        gpiod_line_release(sensor_reset_line);
        gpiod_chip_close(ret);
        return -1;
    }

    if ((ret = init_i2c(I2C_ADDR_SENSOR2)) < 0) {
        perror("Failed to initialize I2C bus for sensor 2");
        close(i2c_fds[0]);
        gpiod_line_release(sensor_reset_line);
        gpiod_chip_close(ret);
        return -1;
    }

    log_file = fopen("audio_log.dat", "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fds[0]);
        close(i2c_fds[1]);
        gpiod_line_release(sensor_reset_line);
        gpiod_chip_close(ret);
        return -1;
    }

    sensor_data_cb = [](struct gpiod_chan *chan, int data, void *data) {
        int16_t *samples = static_cast<int16_t *>(data);
        samples[chan->line_number] = data;
    };

    sensor_data_cb_data[0] = &sensor_data_callback_data[0];
    sensor_data_cb_data[1] = &sensor_data_callback_data[1];

    ret = gpiod_line_data_callback_set(sensor_reset_line, sensor_data_cb, &sensor_data_cb_data[0]);
    if (ret < 0) {
        perror("Failed to set GPIO line data callback");
        fclose(log_file);
        close(i2c_fds[0]);
        close(i2c_fds[1]);
        gpiod_line_release(sensor_reset_line);
        gpiod_chip_close(ret);
        return -1;
    }

    pthread_create(&sampling_thread, NULL, sample_and_log, NULL);

    while (running) {
        usleep(100000);
    }

    pthread_join(sampling_thread, NULL);

    fclose(log_file);
    close(i2c_fds[0]);
    close(i2c_fds[1]);
    gpiod_line_release(sensor_reset_line);
    gpiod_chip_close(ret);

    return 0;
}

