#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/spi/spidev.h>
#include <errno.h>
#include <signal.h>

#define SPI_BUS 0
#define CS_GPIO 8
#define CHIP_SELECT (1 << CS_GPIO)
#define SPI_MODE 3
#define SPI_MAX_SPEED_HZ 1000000
#define GYRO_SCALE 0.02
#define ACCEL_SCALE 0.00025
#define DATA_READ_DELAY_US 10
#define LOG_INTERVAL_MS 100

struct spi_device_interface {
    unsigned int max_speed_hz;
    unsigned int bits_per_word;
    unsigned int mode;
    unsigned int lsb_first;
};

int spi_fd;
struct spi_device_interface spi_config = {
    .max_speed_hz = SPI_MAX_SPEED_HZ,
    .bits_per_word = 16,
    .mode = SPI_MODE,
    .lsb_first = 0,
};

void spi_init() {
    char dev_path[32];
    snprintf(dev_path, sizeof(dev_path), "/dev/spidev%d.0", SPI_BUS);

    spi_fd = open(dev_path, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &spi_config.mode) != 0) {
        perror("Failed to set SPI mode");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi_config.max_speed_hz) != 0) {
        perror("Failed to set SPI max speed");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &spi_config.bits_per_word) != 0) {
        perror("Failed to set SPI bits per word");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_LSB_FIRST, &spi_config.lsb_first) != 0) {
        perror("Failed to set SPI LSB first");
        exit(EXIT_FAILURE);
    }

    if (gpio_tc_export(CS_GPIO, true) < 0) {
        perror("Failed to export GPIO");
        exit(EXIT_FAILURE);
    }

    if (gpio_tc_direction(CS_GPIO, GPIO2_OUT) < 0) {
        perror("Failed to set GPIO direction");
        exit(EXIT_FAILURE);
    }

    gpio_tc_write(CS_GPIO, 0);
}

void spi_close() {
    gpio_tc_write(CS_GPIO, 1);
    gpio_tc_unexport(CS_GPIO);
    close(spi_fd);
}

uint16_t spi_read_reg(uint8_t reg_addr) {
    uint16_t data;
    gpio_tc_write(CS_GPIO, 0);

    // Send register address with bit 7 set
    spi_write(spi_fd, (reg_addr | (1 << 7)));
    usleep(DATA_READ_DELAY_US);

    // Capture 16-bit data response
    spi_read(spi_fd, &data, sizeof(data));

    gpio_tc_write(CS_GPIO, 1);
    return data;
}

void log_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z,
              int16_t accel_x, int16_t accel_y, int16_t accel_z) {
    printf("Gyro: X=%.2f, Y=%.2f, Z=%.2f\n",
           gyro_x * GYRO_SCALE, gyro_y * GYRO_SCALE, gyro_z * GYRO_SCALE);
    printf("Accel: X=%.6f, Y=%.6f, Z=%.6f\n",
           accel_x * ACCEL_SCALE, accel_y * ACCEL_SCALE, accel_z * ACCEL_SCALE);
}

void signal_handler(int sig) {
    spi_close();
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    spi_init();

    while (1) {
        int16_t gyro_x = spi_read_reg(0x28);
        int16_t gyro_y = spi_read_reg(0x2a);
        int16_t gyro_z = spi_read_reg(0x2c);
        int16_t accel_x = spi_read_reg(0x38);
        int16_t accel_y = spi_read_reg(0x3a);
        int16_t accel_z = spi_read_reg(0x3c);

        log_data(gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
        usleep(LOG_INTERVAL_MS * 1000);
    }

    spi_close();
    return 0;
}

