void gpio_cb(struct gpiod_line_request *req, int event, int value) {
    if (event == GPIOD_LINE_EVENT_EDGE_FALLING) {
        gpiod_line_set_value(gpio_req, 1);
    }
}

int init_gpio() {
    gpio_cb.linestate_cb = gpio_cb;
    gpio_req = gpiod_chip_get_line(gpiod_chip_get_by_name("gpiochip0"), GPIO_LINE_CE0);
    if (!gpio_req) {
        perror("Failed to get GPIO line");
        return -1;
    }

    if (gpiod_line_request_direction_input(gpio_req, GPIOD_LINE_ACTIVE_LOW) < 0) {
        perror("Failed to set GPIO direction");
        return -1;
    }

