#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <time.h>
#include <sys/mman.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68
#define ACC_REG 0x3b
#define GYRO_REG 0x43
#define BUFFER_SIZE 14

int main() {
    int i2c_fd;
    char buffer[BUFFER_SIZE];
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg messages[2];
    gpiod_line_request_linestate_vlinestate_cb data_ready_cb;
    gpiod_line_request_lines data_ready_req;
    gpiod_line_state data_ready_state;
    int ret;

    // Open I2C bus
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Initialize I2C messages
    messages[0].addr = I2C_ADDR << 1;
    messages[0].flags = 0;
    messages[0].len = 1;
    messages[0].buf = (char*)&ACC_REG;

    messages[1].addr = I2C_ADDR << 1;
    messages[1].flags = I2C_M_RD;
    messages[1].len = 6;
    messages[1].buf = buffer;

    // Set up data ready GPIO
    if (gpiod_chip_open_byname("gpiochip0") < 0) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    data_ready_req.consumer = "imu_data_ready";
    data_ready_req.flags = GPIOD_LINE_ACTIVE_HIGH | GPIOD_LINE_REQUEST_INPUT;
    data_ready_cb.consumer_data = NULL;
    data_ready_cb.line_state_cb = [](struct gpiod_line_request *req,
                                     enum gpiod_line_state state,
                                     unsigned long data) {
        data_ready_state = state;
    };

    if (gpiod_line_request_dt(&data_ready_req) < 0) {
        perror("Failed to request data ready GPIO");
        gpiod_chip_close(gpiod_chip_get_byname("gpiochip0"));
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        // Send I2C read command and wait for data ready
        ret = ioctl(i2c_fd, I2C_RDWR, &i2c_data);
        if (ret < 0) {
            perror("Failed to send I2C read command");
            if (errno != EAGAIN)
                break;
            usleep(50000);
            continue;
        }

        // Wait for data ready signal
        while (data_ready_state != GPIOD_LINE_STATE_ACTIVE) {
            usleep(10000);
            if (gpiod_line_get_value_cansleep(&data_ready_req, &data_ready_state) < 0) {
                perror("Failed to get data ready GPIO state");
                break;
            }
        }

        // Read accelerometer and gyroscope data
        ret = read(i2c_fd, buffer, 6);
        if (ret < 0) {
            perror("Failed to read I2C data");
            if (errno != EAGAIN)
                break;
            continue;
        }

        // Process data and print it
        // ...

        // Reset data ready state
        data_ready_state = GPIOD_LINE_STATE_UNDETERMINED;
    }

    // Clean up resources
    gpiod_line_release_request(&data_ready_req);
    gpiod_chip_close(gpiod_chip_get_byname("gpiochip0"));
    close(i2c_fd);

    // Handle SIGINT
    signal(SIGINT, [](int sig) {
        printf("\nExiting...\n");
        // Clean up resources as in the main loop
    });

    return 0;
}

