code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/time.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <sys/mman.h>
#include <linux/i2c.h>
#include <linux/i2c-bidirectional.h>
#include <gpiod.h>

#define ADXL345_ADDR 0x53
#define XOUT_H 0x32
#define XOUT_L 0x33
#define YOUT_H 0x34
#define YOUT_L 0x35
#define ZOUT_H 0x36
#define ZOUT_L 0x37
#define DEVID 0x3D
#define THRESHOLD 2.5
#define LED_GPIO 17
#define LOG_FILE "impact_log.txt"

struct i2c_data {
    int fd;
    struct i2c_client_addr info;
};

int i2c_write(struct i2c_data *data, uint8_t reg, uint8_t value) {
    int ret;
    char buf[2];

    buf[0] = reg;
    buf[1] = value;

    ret = write(data->fd, buf, 2);
    if (ret != 2) {
        perror("i2c_write");
        return -1;
    }

    return 0;
}

int i2c_read(struct i2c_data *data, uint8_t reg, uint8_t *buf) {
    int ret;
    char read_buf[1];

    ret = i2c_smbus_read_byte_data(data->fd, reg);
    if (ret < 0) {
        perror("i2c_read");
        return -1;
    }

    *buf = (uint8_t)ret;
    return 0;
}

int check_device_id(struct i2c_data *data) {
    uint8_t devid;

    if (i2c_read(data, DEVID, &devid) < 0) {
        return 0;
    }

    if (devid != 0x3D) {
        fprintf(stderr, "Wrong device ID: 0x%02X\n", devid);
        return 0;
    }

    return 1;
}

void log_event(double magnitude, double x, double y, double z) {
    FILE *log_file = fopen(LOG_FILE, "a");
    struct timeval tv;
    char timestamp[20];
    gettimeofday(&tv, NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));
    fprintf(log_file, "%s, %f, %f, %f, %f\n", timestamp, magnitude, x, y, z);
    fclose(log_file);
}

void gpio_setup(int gpio) {
    struct gpiod_line_request_data req = {
        .consumer = "ADXL345_LED",
        .direction = GPIOD_IN,
        .flags = GPIOD_LINE_REQUEST_INPUT,
    };
    struct gpiod_line *line;

    line = gpiod_get_line_request_array(1, &req);
    if (!line) {
        perror("gpiod_get_line_request_array");
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(line, 0);
    gpiod_line_set_debounce(line, 10);
    gpiod_line_set_value(line, 1);
    gpiod_line_set_debounce(line, 10);

    gpiod_line_set_event_callback(line, GPIOD_LINE_EVENT_EDGE_FALLING, [](struct gpiod_line *line, void *user_data) {
        double magnitude, x, y, z;
        struct i2c_data *data = user_data;

        if (i2c_read(data, XOUT_H, &x) < 0 ||
            i2c_read(data, XOUT_L, &x) < 0 ||
            i2c_read(data, YOUT_H, &y) < 0 ||
            i2c_read(data, YOUT_L, &y) < 0 ||
            i2c_read(data, ZOUT_H, &z) < 0 ||
            i2c_read(data, ZOUT_L, &z)) {
            return;
        }

        magnitude = sqrt(x * x + y * y + z * z) / 256.0;
        if (magnitude > THRESHOLD) {
            log_event(magnitude, x / 256.0, y / 256.0, z / 256.0);
            gpiod_line_set_value(line, 0);
            usleep(500000);
            gpiod_line_set_value(line, 1);
        }
    }, data);

    gpiod_line_set_active_low(line, 1);
    gpiod_line_set_flags(line, GPIOD_LINE_FLAG_ACTIVE_LOW);
}

int main() {
    int i2c_bus = 1;
    struct i2c_data data;
    int ret;

    gpiod_set_bcm2835_hwmod_enabled(LED_GPIO, 1);
    gpio_setup(LED_GPIO);

    data.fd = open("/dev/i2c-" + std::to_string(i2c_bus), O_RDWR);
    if (data.fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    if (ioctl(data.fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    data.info.addr_flag = I2C_ADDR_7BIT;
    data.info.addr = ADXL345_ADDR;

    if (check_device_id(&data) == 0) {
        close(data.fd);
        exit(EXIT_FAILURE);
    }

    ret = i2c_write(&data, 0x2D, 0x08);
    if (ret < 0) {
        perror("i2c_write");
        exit(EXIT_FAILURE);
    }

    ret = i2c_write(&data, 0x2C, 0x00);
    if (ret < 0) {
        perror("i2c_write");
        exit(EXIT_FAILURE);
    }

    struct itimerval timer;
    timer.it_interval.tv_usec = 10000;
    timer.it_value.tv_usec = 10000;
    setitimer(ITIMER_REAL, &timer, NULL);

    while (1) {
        usleep(10000);

        double x, y, z;
        if (i2c_read(&data, XOUT_H, &x) < 0 ||
            i2c_read(&data, XOUT_L, &x) < 0 ||
            i2c_read(&data, YOUT_H, &y) < 0 ||
            i2c_read(&data, YOUT_L, &y) < 0 ||
            i2c_read(&data, ZOUT_H, &z) < 0 ||
            i2c_read(&data, ZOUT_L, &z)) {
            continue;
        }

        double magnitude = sqrt(x * x + y * y + z * z) / 256.0;
        if (magnitude > THRESHOLD) {
            log_event(magnitude, x / 256.0, y / 256.0, z / 256.0);
            gpiod_line_set_value(data.info.line, 0);
            usleep(500000);
            gpiod_line_set_value(data.info.line, 1);
        }
    }

    close(data.fd);
    gpiod_line_release(data.info.line);
    gpiod_release_lines(data.info.line, 1);

    return 0;
}

