int init_i2c() {
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0)
        die("Failed to open I2C bus");

    if (ioctl(i2c_fd, I2C_SLAVE, MMA8451Q_ADDR) < 0)
