    struct i2c_rdwr_ioctl_data rw;
    struct i2c_msg msg[] = {
        {.addr = MMA8451Q_ADDR, .flags = 0, .len = 1, .buf = (char *)&id},
        {.addr = MMA8451Q_ADDR, .flags = I2C_M_RD, .len = 1, .buf = (char *)&id + 1}
    };

    rw.msgs = msg;
    rw.nmsgs = 2;

    if (ioctl(i2c_fd, I2C_RDWR, &rw) < 0)
        die("Failed to read accelerometer ID");

    if (id[0] != 0x45 || id[1] != 0x13) {
        fprintf(stderr, "Accelerometer ID mismatch\n");
        return -1;
    }

    return 0;
}

