    struct i2c_msg msg = {
        .addr = MMA8451Q_ADDR,
        .flags = 0,
        .len = 2,
        .buf = (char *)&data + 2 * axis
    };

    if (ioctl(i2c_fd, I2C_SMBUS_READ, &msg) < 0)
        die("Failed to read accelerometer data");

    return (data[2 * axis] << 8 | data[2 * axis + 1]) / 16.0;
}

