#include <errno.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <gpiod.h>

#define I2C_BUS 1
#define TMAG5273_ADDR 0x1E
#define X_REG 0x00
#define Y_REG 0x01
#define Z_REG 0x02
#define BUFFER_SIZE 64

gpiod_line_request_linenum_t xint, yint, zint;
int i2c_fd;
FILE *csv_file;
pthread_t sampling_thread;

void sigint_handler(int signum) {
    gpiod_line_release_request(xint);
    gpiod_line_release_request(yint);
    gpiod_line_release_request(zint);
    if (i2c_fd > 0) close(i2c_fd);
    if (csv_file) fclose(csv_file);
    pthread_exit(NULL);
}

int init_i2c() {
    const char *i2c_dev = "/dev/i2c-" I2C_BUS;
    i2c_fd = open(i2c_dev, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TMAG5273_ADDR) < 0) {
        perror("Failed to acquire bus access");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

int init_gpio() {
    int ret;
    const char *gpio_label = "gpiochip0";
    gpiod_chip *chip = gpiod_chip_open_by_label(gpio_label);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    xint = gpiod_chip_get_line(chip, 16);
    yint = gpiod_chip_get_line(chip, 17);
    zint = gpiod_chip_get_line(chip, 18);

    ret = gpiod_line_request_dt(xint, "tmag5273_x", GPIOD_LINE_REQUEST_INPUT, "Sample X axis");
    if (ret < 0) {
        perror("Failed to request X axis GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_dt(yint, "tmag5273_y", GPIOD_LINE_REQUEST_INPUT, "Sample Y axis");
    if (ret < 0) {
        perror("Failed to request Y axis GPIO line");
        gpiod_line_release_request(xint);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_dt(zint, "tmag5273_z", GPIOD_LINE_REQUEST_INPUT, "Sample Z axis");
    if (ret < 0) {
        perror("Failed to request Z axis GPIO line");
        gpiod_line_release_request(xint);
        gpiod_line_release_request(yint);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

void *sampling_loop(void *arg) {
    char buffer[BUFFER_SIZE];
    time_t timestamp;
    struct tm *timeinfo;

    while (1) {
        int x, y, z;

        if (gpiod_line_get_value_cansleep(xint) == 1) x = 1;
        else x = 0;
        if (gpiod_line_get_value_cansleep(yint) == 1) y = 1;
        else y = 0;
        if (gpiod_line_get_value_cansleep(zint) == 1) z = 1;
        else z = 0;

        if (write_to_csv(x, y, z) < 0) {
            perror("Failed to write to CSV file");
        }

        sleep(1);
    }

    return NULL;
}

int write_to_csv(int x, int y, int z) {
    char timestamp_str[32];
    time(&timestamp);
