#include <linux/i2c-dev.h>
#include <sys/mman.h>
#include <gpiod.h>

#define I2C_BUS 1
#define SDA_GPIO 2
#define SCL_GPIO 3
#define IMU_ADDR 0x6A
#define ACC_OUT_H 0x28
#define GYR_OUT_H 0x22
#define SAMPLE_RATE 104
#define FALL_THRESHOLD 0.2
#define IMPACT_THRESHOLD 2.5
#define DETECTION_WINDOW 1.0
#define CSV_FILE "motion_log.txt"

struct i2c_rdwr_ioctl_data {
    struct i2c_msg msgs[2];
    unsigned int num;
};

int init_i2c(void) {
    int i2c_fd;
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, IMU_ADDR) < 0) {
        perror("Failed to acquire bus access");
        close(i2c_fd);
        return -1;
    }

    return i2c_fd;
}

int read_data(int i2c_fd, uint8_t *acc_data, uint8_t *gyr_data) {
    struct i2c_rdwr_ioctl_data rw;
    rw.num = 2;

    rw.msgs[0].addr = IMU_ADDR;
    rw.msgs[0].flags = 0;
    rw.msgs[0].len = 6;
    rw.msgs[0].buf = &acc_data[0];

    rw.msgs[1].addr = IMU_ADDR;
    rw.msgs[1].flags = I2C_M_RD;
    rw.msgs[1].len = 6;
    rw.msgs[1].buf = &gyr_data[0];

    if (ioctl(i2c_fd, I2C_RDWR, &rw) < 0) {
        perror("Failed to read data from IMU");
        return -1;
    }

    return 0;
}

float calculate_magnitude(const uint8_t *data) {
    float acc_x = (data[0] << 8 | data[1]) / 16.0;
    float acc_y = (data[2] << 8 | data[3]) / 16.0;
    float acc_z = (data[4] << 8 | data[5]) / 16.0;

    return sqrt(acc_x * acc_x + acc_y * acc_y + acc_z * acc_z);
}

void fall_detection(float *acc_magnitude, float *prev_acc_magnitude, float *fall_state) {
    static float prev_prev_acc_magnitude = 0.0;
    static float detection_start_time = 0.0;

    if (*acc_magnitude < FALL_THRESHOLD && *prev_acc_magnitude > FALL_THRESHOLD) {
        if (detection_start_time == 0.0) {
            detection_start_time = get_monotonic_time();
        }
        if (get_monotonic_time() - detection_start_time > DETECTION_WINDOW) {
            *fall_state = FALL;
        }
    } else {
        detection_start_time = 0.0;
    }

