This code initializes the I2C bus, configures the IMU, opens a CSV file, and enters an infinite loop to read data, calculate the acceleration magnitude, and detect falls. It also handles errors gracefully and releases resources on SIGINT or SIGTERM.

You'll need to implement the `write_bytes_to_reg` function to write data to the IMU's registers and the `get_monotonic_time` function to get the monotonic time. These functions are not provided in this code snippet.

I'll provide a basic example using the `libgpiod` library for GPIO management and the `spidev` library for SPI communication. Note that you'll need to install the required libraries using the following commands:

```bash
sudo apt-get install libgpiod-dev
sudo apt-get install libspidev-dev
```

Here's the C code:

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <spidev.h>

#define SPI_BUS 0
#define SPI_DEVICE 0
#define GPIO_LINE_CE0 8
#define WHO_AM_I_REG 0x0F
#define SCALE_FACTOR 0.0305
#define SAMPLE_INTERVAL_MS 10
#define LOG_FILE "gyro_log.csv"

int spi_fd, gpio_fd;
struct spi_ioc_transfer transfers[2];
char log_buffer[32];
FILE *log_file;

void die(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

int init_gpio() {
    gpio_fd = gpiod_open_name("gpiochip0", "gpio8");
    if (gpio_fd < 0)
        die("Failed to open gpiochip0");

    gpiod_line_request_dt(gpio_fd, GPIO_LINE_CE0, "CE0");
    if (gpiod_line_get_value_cansleep(gpio_fd, GPIO_LINE_CE0) != 0)
        gpiod_line_set_value(gpio_fd, GPIO_LINE_CE0, 0);

    return gpio_fd;
}

int init_spi() {
    spi_fd = open("/dev/spidev" SPI_BUS, O_RDWR);
    if (spi_fd < 0)
        die("Failed to open SPI device");

    struct spi_ioc_transfer transfer = {
        .tx_buf = {0x80 | WHO_AM_I_REG, 0},
        .rx_buf = {0},
        .len = 2,
        .delay_usecs = 0,
        .speed_hz = 1000000,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 1)
        die("Failed to perform initial SPI read");

    if (transfer.rx_buf[0] != 0xAD)
        die("Invalid WHO_AM_I response");

    memset(transfers, 0, sizeof(transfers));

    return spi_fd;
}

void spi_write_read(uint16_t reg) {
    transfers[0].tx_buf = &reg;
    transfers[1].rx_buf = &reg;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(2), transfers) < 2)
        die("Failed to perform SPI read");
}

float get_angular_rate() {
    spi_write_read(WHO_AM_I_REG);

    int16_t raw_value = (transfers[1].rx_buf[0] << 8) | transfers[1].rx_buf[1];
    return raw_value * SCALE_FACTOR;
}

void log_sample(const char *timestamp, float angular_rate) {
    snprintf(log_buffer, sizeof(log_buffer), "%s,%f\n", timestamp, angular_rate);
    if (fputs(log_buffer, log_file) == EOF)
        die("Failed to write to log file");
}

void sigint_handler(int signum) {
    close(spi_fd);
    gpiod_line_set_value(gpio_fd, GPIO_LINE_CE0, 0);
    gpiod_close(gpio_fd);
    fclose(log_file);
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, sigint_handler);

    log_file = fopen(LOG_FILE, "w");
    if (!log_file)
        die("Failed to open log file");

    fprintf(log_file, "timestamp,angular_rate(deg/s)\n");

    gpio_fd = init_gpio();
    spi_fd = init_spi();

    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    long last_ts = ts.tv_sec * 1000 + ts.tv_nsec / 1_000_000;

    while (1) {
        float angular_rate = get_angular_rate();
        struct timespec current_ts;
        clock_gettime(CLOCK_MONOTONIC, &current_ts);
        long current_ts_ms = current_ts.tv_sec * 1000 + current_ts.tv_nsec / 1_000_000;

        if (current_ts_ms - last_ts >= SAMPLE_INTERVAL_MS) {
            log_sample(ctime(&current_ts.tv_sec), angular_rate);
            last_ts = current_ts_ms;
        }
    }

    close(spi_fd);
    gpiod_line_set_value(gpio_fd, GPIO_LINE_CE0, 0);
    gpiod_close(gpio_fd);
    fclose(log_file);

    return EXIT_SUCCESS;
}
```

This code initializes the GPIO line for the CE0 signal, opens the SPI device, verifies the WHO_AM_I register, and samples the angular rate at a 10ms interval. It logs the timestamped readings to a single CSV file named `gyro_log.csv`. The program handles SIGINT gracefully by closing the SPI handle, terminating the driver, and closing the log file.

