    data->i2c_msg.msgs[0].addr = I2C_ADDR << 1;
    data->i2c_msg.msgs[0].flags = 0;
    data->i2c_msg.msgs[0].len = 1;
    data->i2c_msg.msgs[0].buf = &reg;

    data->i2c_msg.msgs[1].addr = I2C_ADDR << 1;
    data->i2c_msg.msgs[1].flags = I2C_M_WRITE;
    data->i2c_msg.msgs[1].len = 1;
    data->i2c_msg.msgs[1].buf = &value;

    if (ioctl(data->fd, I2C_RDWR, &data->i2c_msg) < 0) {
        perror("I2C write error");
        return -1;
    }

    return 0;
}

int i2c_read(struct i2c_data *data, uint8_t reg, uint8_t *buf, size_t len) {
    data->i2c_msg.msgs[0].addr = I2C_ADDR << 1;
    data->i2c_msg.msgs[0].flags = 0;
    data->i2c_msg.msgs[0].len = len;
    data->i2c_msg.msgs[0].buf = buf;

    data->i2c_msg.msgs[1].addr = I2C_ADDR << 1;
    data->i2c_msg.msgs[1].flags = I2C_M_RD;
    data->i2c_msg.msgs[1].len = len;
    data->i2c_msg.msgs[1].buf = buf;

    if (ioctl(data->fd, I2C_RDWR, &data->i2c_msg) < 0) {
        perror("I2C read error");
        return -1;
    }

    return 0;
}

int main() {
    int i2c_fd;
    struct i2c_data i2c_data;
    gpiod_line_request_linestate_v2_t line_state;
    FILE *csv_file;
    struct timespec next_sample;
    uint8_t buf[2];
    int32_t x, y, z;
    int retries = 3;

    // Open I2C bus
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

