    i2c_data.fd = i2c_fd;
    i2c_data.i2c_msg.msgs = malloc(sizeof(struct i2c_msg) * 2);

    // Check sensor's WHO_AM_I register
    if (i2c_write(&i2c_data, GYRO_REG_OUT_X_L, 0x00) < 0 ||
        i2c_read(&i2c_data, GYRO_REG_OUT_WHO_AM_I, buf, 1) < 0 ||
        buf[0] != GYRO_WHO_AM_I) {
        fprintf(stderr, "Invalid sensor response\n");
        exit(EXIT_FAILURE);
    }

