    if ((csv_file = fopen("gyro_log.csv", "w")) == NULL) {
        perror("Failed to open CSV file");
        exit(EXIT_FAILURE);
    }

    // Write header to CSV file
    fprintf(csv_file, "Timestamp,X,Y,Z\n");

    // Request GPIO line for SIGINT handling
    gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    gpiod_line_get_raw_value_v2(chip, 17, &line_state); // Assuming GPIO17 for SIGINT
    gpiod_line_request_dt_v2(chip, 17, GPIOD_LINE_REQUEST_INPUT, "sigint");

    // Main loop
    clock_gettime(CLOCK_MONOTONIC_RAW, &next_sample);
    next_sample.tv_sec += SAMPLE_INTERVAL_NS / 1_ Billion;
    next_sample.tv_nsec = (SAMPLE_INTERVAL_NS % 1_ Billion) * 1_ Billion;

    while (1) {
        if (gpiod_line_get_raw_value_v2(chip, 17, &line_state) < 0) {
            perror("Failed to get GPIO line state");
            exit(EXIT_FAILURE);
        }

        if (line_state.value == 0) {
            break;
        }

        if (i2c_read(&i2c_data, GYRO_REG_OUT_X_L, buf, 6) < 0) {
            perror("Failed to read gyro data");
            continue;
        }

        x = (buf[1] << 8 | buf[0]) * SENSITIVITY;
        y = (buf[3] << 8 | buf[2]) * SENSITIVITY;
        z = (buf[5] << 8 | buf[4]) * SENSITIVITY;

        clock_gettime(CLOCK_MONOTONIC_RAW, &next_sample);
        fprintf(csv_file, "%lld,%d,%d,%d\n", next_sample.tv_sec * 1_ Billion + next_sample.tv_nsec, x, y, z);

        // Sleep until next sample time
        struct timespec rem;
        if (nanosleep(&next_sample, &rem) < 0) {
            perror("Failed to sleep");
            exit(EXIT_FAILURE);
        }

        next_sample.tv_sec += rem.tv_sec;
        next_sample.tv_nsec += rem.tv_nsec;
    }

    // Cleanup
    fclose(csv_file);
    gpiod_line_release(chip, 17);
    gpiod_chip_close(chip);
    close(i2c_fd);
    free(i2c_data.i2c_msg.msgs);

    return 0;
}

