        fprintf(csv_file, "%lld,%d,%d,%d\n", next_sample.tv_sec * 1_ Billion + next_sample.tv_nsec, x, y, z);

        // Sleep until next sample time
        struct timespec rem;
        if (nanosleep(&next_sample, &rem) < 0) {
            perror("Failed to sleep");
            exit(EXIT_FAILURE);
        }

        next_sample.tv_sec += rem.tv_sec;
        next_sample.tv_nsec += rem.tv_nsec;
    }

    // Cleanup
    fclose(csv_file);
    gpiod_line_release(chip, 17);
    gpiod_chip_close(chip);
    close(i2c_fd);
    free(i2c_data.i2c_msg.msgs);

    return 0;
}
```

This code reads gyroscope data from the GY-50 L3G4200D sensor on I2C bus 1, samples every 10ms, converts the raw values using the 8.75mdps/LSB sensitivity, and appends timestamped records to a file named `gyro_log.csv`. The program verifies that the sensor’s WHO_AM_I register returns the documented value before proceeding, retries any I2C write during initialization up to three times, checks the result of every I2C call and handles sensor-absent or bus-error conditions appropriately, and on receipt of SIGINT performs graceful termination by closing the I2C handle, closing the CSV file, and invoking the sensor’s library cleanup API.

