#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <time.h>
#include <errno.h>
#include <sys/time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SLAVE_ADDR 0x20
#define X_REG 0x00
#define Y_REG 0x01
#define Z_REG 0x02
#define SAMPLE_INTERVAL_US 100000

static int i2c_fd = -1;
static FILE *csv_file = NULL;

static void sigint_handler(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }

    if (csv_file) {
        fclose(csv_file);
        csv_file = NULL;
    }

    exit(0);
}

int main() {
    struct timeval tv;
    uint16_t x, y, z;
    char timestamp[32];
    char line[128];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        goto cleanup;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SLAVE_ADDR) < 0) {
        perror("Failed to acquire I2C slave address");
        goto close_i2c;
    }

    csv_file = fopen("vibration_log.csv", "w+");
    if (!csv_file) {
        perror("Failed to open vibration_log.csv");
        goto close_i2c;
    }

    if (fprintf(csv_file, "Timestamp,X,Y,Z\n") < 0) {
        perror("Failed to write header to vibration_log.csv");
        goto close_csv;
    }

    while (1) {
        if (gpio_tv_us(SAMPLE_INTERVAL_US, &tv) < 0) {
            perror("Failed to sleep");
            continue;
        }

        if (read(i2c_fd, &x, sizeof(x)) != sizeof(x)) {
            perror("Failed to read X axis data");
            continue;
        }

        if (read(i2c_fd, &y, sizeof(y)) != sizeof(y)) {
            perror("Failed to read Y axis data");
            continue;
        }

        if (read(i2c_fd, &z, sizeof(z)) != sizeof(z)) {
            perror("Failed to read Z axis data");
            continue;
        }

        ctime_r(&tv.tv_sec, timestamp);
        snprintf(line, sizeof(line), "%s,%d,%d,%d\n", timestamp, x, y, z);

        if (fwrite(line, 1, strlen(line), csv_file) != strlen(line)) {
            perror("Failed to write sample to vibration_log.csv");
        }
    }

    close_csv:
        if (csv_file) {
            fclose(csv_file);
        }

    close_i2c:
        if (i2c_fd >= 0) {
            ioctl(i2c_fd, I2C_SLAVE, 0);
            close(i2c_fd);
        }

    cleanup:
        gpioTerminate();

    return 0;
}

