#define HALL_SENSOR_2_LINE "line27"
#define LOG_FILE "conveyor_log.txt"

struct gpiod_chip *chip;
struct gpiod_line *line_1, *line_2;
FILE *log_file;

void gpiod_init() {
    chip = gpiod_chip_open_by_name(GPIO_BUS_BASE, GPIO_CHIP_NAME);
    if (!chip) {
        perror("Failed to open gpiochip");
        exit(EXIT_FAILURE);
    }

    line_1 = gpiod_chip_get_line(chip, HALL_SENSOR_1_LINE);
    if (!line_1) {
        perror("Failed to get line 1");
        exit(EXIT_FAILURE);
    }

    line_2 = gpiod_chip_get_line(chip, HALL_SENSOR_2_LINE);
    if (!line_2) {
        perror("Failed to get line 2");
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_output(line_1, "default");
    gpiod_line_request_output(line_2, "default");

    gpiod_line_set_value(line_1, 1);
    gpiod_line_set_value(line_2, 1);

    gpiod_line_set_debounce(line_1, 1);
    gpiod_line_set_debounce(line_2, 1);
}

void log_timestamped_state(const char *message, int state_1, int state_2) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_string[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s: Sensor 1: %d, Sensor 2: %d\n", time_string, state_1, state_2);
}

void signal_handler(int sig) {
    gpiod_line_set_value(line_1, 0);
    gpiod_line_set_value(line_2, 0);

    gpiod_line_release(line_1);
    gpiod_line_release(line_2);
    gpiod_chip_release(chip);

    fclose(log_file);

    exit(EXIT_SUCCESS);
}

int main() {
    int state_1, state_2;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    gpiod_init();

    while (1) {
        state_1 = gpiod_line_get_value(line_1);
        state_2 = gpiod_line_get_value(line_2);

        log_timestamped_state("State", state_1, state_2);

        if (state_1 && state_2) {
            printf("Conveyor halted\n");
            gpiod_line_set_value(line_1, 0);
            gpiod_line_set_value(line_2, 0);
            sleep(1); // Simulate conveyor halting for 1 second
        }

        usleep(50000); // Sleep for 50ms
    }

    gpiod_line_release(line_1);
    gpiod_line_release(line_2);
    gpiod_chip_release(chip);

    fclose(log_file);

    return 0;
