#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <sys/stat.h>
#include <signal.h>
#include <errno.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1D
#define WHO_AM_I 0x0F
#define CTRL_REG1 0x2A
#define DATA_X_LSB 0x28
#define DATA_X_MSB 0x29
#define DATA_Y_LSB 0x2A
#define DATA_Y_MSB 0x2B
#define DATA_Z_LSB 0x2C
#define DATA_Z_MSB 0x2D
#define DEG_TO_LSB 0.0078125
#define THRESHOLD_DEG 45
#define FALL_LOG_FILE "fall_log.txt"

int i2c_file;
FILE *log_file;

void i2c_error_handler(const char *function_name) {
    if (i2c_file >= 0) {
        close(i2c_file);
        i2c_file = -1;
    }
    fprintf(stderr, "Error in %s: %s\n", function_name, strerror(errno));
    exit(EXIT_FAILURE);
}

void signal_handler(int sig) {
    if (i2c_file >= 0) {
        close(i2c_file);
        i2c_file = -1;
    }

    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }

    exit(EXIT_SUCCESS);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request *line_req;
    int ret;

    // Initialize GPIO to request I2C pins
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        i2c_error_handler("gpiod_chip_open_by_name");
    }

    line_req = gpiod_chip_get_line_request_byindex(chip, 17); // SDA
    ret = gpiod_line_request_direction_output(line_req, GPIOD_LINE_ACTIVE_HIGH);
    if (ret < 0) {
        i2c_error_handler("gpiod_line_request_direction_output");
    }

    line_req = gpiod_chip_get_line_request_byindex(chip, 18); // SCL
    ret = gpiod_line_request_direction_output(line_req, GPIOD_LINE_ACTIVE_HIGH);
    if (ret < 0) {
        i2c_error_handler("gpiod_line_request_direction_output");
    }

    // Open I2C device
    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file < 0) {
        i2c_error_handler("open");
    }

    // Set I2C slave address
    if (ioctl(i2c_file, I2C_SLAVE, I2C_ADDR) < 0) {
        i2c_error_handler("ioctl(I2C_SLAVE)");
    }

    // Check sensor identity
    char who_am_i;
    ret = read(i2c_file, &who_am_i, 1);
    if (ret != 1 || who_am_i != 0x3D) {
        i2c_error_handler("read(WHO_AM_I)");
    }

    // Initialize device
    char ctrl_reg1 = 0x00;
    ret = write(i2c_file, &ctrl_reg1, 1);
    if (ret != 1) {
        i2c_error_handler("write(CTRL_REG1)");
    }

    usleep(100000); // Wait for standby mode

    ctrl_reg1 |= 0x08; // Set data rate to 100 Hz
    ret = write(i2c_file, &ctrl_reg1, 1);
    if (ret != 1) {
        i2c_error_handler("write(CTRL_REG1)");
    }

    usleep(100000); // Wait for active mode

    // Open log file
    log_file = fopen(FALL_LOG_FILE, "a");
    if (!log_file) {
        i2c_error_handler("fopen");
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    long last_ts = ts.tv_sec * 1000 + ts.tv_nsec / 1000000;

    while (1) {
        char data[6];
        ret = read(i2c_file, data, 6);
        if (ret != 6) {
            i2c_error_handler("read(data)");
            continue;
        }

        int16_t x = ((data[DATA_X_MSB] << 8) | data[DATA_X_LSB]) >> 4;
        int16_t y = ((data[DATA_Y_MSB] << 8) | data[DATA_Y_LSB]) >> 4;
        int16_t z = ((data[DATA_Z_MSB] << 8) | data[DATA_Z_LSB]) >> 4;

        double tilt_x = DEG_TO_LSB * x;
        double tilt_y = DEG_TO_LSB * y;
        double tilt_z = DEG_TO_LSB * z;

        double tilt = sqrt(tilt_x * tilt_x + tilt_y * tilt_y + tilt_z * tilt_z);

        if (tilt > THRESHOLD_DEG) {
            struct timespec current_ts;
            clock_gettime(CLOCK_MONOTONIC, &current_ts);
            long current_ts_ms = current_ts.tv_sec * 1000 + current_ts.tv_nsec / 1000000;

            fprintf(log_file, "%ld, %d, %d, %d\n", current_ts_ms - last_ts, x, y, z);
            fflush(log_file);
            last_ts = current_ts_ms;
        }

        usleep(10000); // Loop delay
    }

    return 0;
}

