Now, here's the C code:

```c
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_BUS 0
#define SPI_DEVICE 0
#define GPIO_LINE_RESET 8
#define GPIO_LINE_CS 8
#define ADXL354B_RESET_REG 0x20
#define ADXL354B_POWER_CTRL_REG 0x2D
#define ADXL354B_STATUS_REG 0x2E
#define ADXL354B_PARTID 0xAD
#define LOG_FILE "vibration_log.txt"
#define LOG_INTERVAL 100
#define SPI_MODE 0
#define SPI_SPEED_HZ 1000000

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int nlines,
                                const char *const *lines, unsigned int flags) {
    return gpiod_chip_request_lines(chip, nlines, lines, flags, NULL);
}

int main(void) {
    int spi_fd, gpio_fd;
    struct spi_device spi_dev;
    struct gpiod_line_request gpio_req;
    struct timespec ts;
    uint8_t data[3];
    uint16_t partid;
    char log_buf[32];
    FILE *log_file;
    int ret;

    // Initialize SPI device
    spi_fd = open("/dev/spidev" SPI_BUS, O_RDWR);
    if (spi_fd < 0) {
        perror("Can't open SPI device");
        return 1;
    }

    ret = read(spi_fd, &spi_dev, sizeof(spi_dev));
    if (ret != sizeof(spi_dev)) {
        perror("Can't read SPI device");
        close(spi_fd);
        return 1;
    }

    if (spi_dev.mode != SPI_MODE || spi_dev.max_speed_hz != SPI_SPEED_HZ) {
        printf("Wrong SPI mode or speed\n");
        close(spi_fd);
        return 1;
    }

    // Initialize GPIO line for CS and reset
    gpio_fd = gpiod_chip_open("gpiochip0");
    if (gpio_fd < 0) {
        perror("Can't open GPIO chip");
        close(spi_fd);
        return 1;
    }

    ret = gpio_request_lines(&gpio_chip_get_data(gpio_fd), 1, &GPIO_LINE_CS,
                              GPIOD_LINE_REQ_DIR_OUT | GPIOD_LINE_REQ_ACTIVE_LOW);
    if (ret < 0) {
        perror("Can't request GPIO line for CS");
        close(gpio_fd);
        close(spi_fd);
        return 1;
    }

    ret = gpio_request_lines(&gpio_chip_get_data(gpio_fd), 1, &GPIO_LINE_RESET,
                              GPIOD_LINE_REQ_DIR_OUT | GPIOD_LINE_REQ_ACTIVE_LOW);
    if (ret < 0) {
        perror("Can't request GPIO line for reset");
        gpiod_line_free_request(&gpio_req);
        close(gpio_fd);
        close(spi_fd);
        return 1;
    }

    // Perform ADXL354B reset sequence
    gpiod_line_set_value_cansleep(&gpio_chip_get_line_data(gpio_fd, GPIO_LINE_RESET), 1);
    usleep(1000 * 1000);
    gpiod_line_set_value_cansleep(&gpio_chip_get_line_data(gpio_fd, GPIO_LINE_RESET), 0);
    usleep(1000 * 1000);

    // Configure SPI for multi-byte read with CS active low
    ioctl(spi_fd, SPI_CPOL, 0);
    ioctl(spi_fd, SPI_CPHA, 0);
    ioctl(spi_fd, SPI_MODE_3, 0);

    // Clear CS line
    gpiod_line_set_value_cansleep(&gpio_chip_get_line_data(gpio_fd, GPIO_LINE_CS), 0);

    // Initialize log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Can't open log file");
        gpiod_line_free_request(&gpio_req);
        close(gpio_fd);
        close(spi_fd);
        return 1;
    }

    // Verify sensor presence
    gpiod_line_set_value_cansleep(&gpio_chip_get_line_data(gpio_fd, GPIO_LINE_CS), 1);
    ret = write(spi_fd, &ADXL354B_RESET_REG, 1);
    gpiod_line_set_value_cansleep(&gpio_chip_get_line_data(gpio_fd, GPIO_LINE_CS), 0);
    if (ret != 1) {
        perror("Failed to write reset register");
        fclose(log_file);
        gpiod_line_free_request(&gpio_req);
        close(gpio_fd);
        close(spi_fd);
        return 1;
    }

    usleep(1000 * 1000);

    gpiod_line_set_value_cansleep(&gpio_chip_get_line_data(gpio_fd, GPIO_LINE_CS), 1);
    ret = read(spi_fd, &data, 1);
    if (ret != 1) {
        perror("Failed to read status register");
        fclose(log_file);
        gpiod_line_free_request(&gpio_req);
        close(gpio_fd);
        close(spi_fd);
        return 1;
    }

    partid = (data[0] << 8) | data[1];
    if (partid != ADXL354B_PARTID) {
        fprintf(log_file, "Invalid part ID: 0x%04X\n", partid);
        fclose(log_file);
        gpiod_line_free_request(&gpio_req);
        close(gpio_fd);
        close(spi_fd);
        return 1;
    }

    // Clear RUN bit and wait for STABLE bit
    gpiod_line_set_value_cansleep(&gpio_chip_get_line_data(gpio_fd, GPIO_LINE_CS), 1);
    ret = write(spi_fd, &ADXL3534B_POWER_CTRL_REG, 1);
    gpiod_line_set_value_cansleep(&gpio_chip_get_line_data(gpio_fd, GPIO_LINE_CS), 0);
    if (ret != 1) {
        perror("Failed to write power control register");
        fclose(log_file);
        gpiod_line_free_request(&gpio_req);
        close(gpio_fd);
        close(spi_fd);
        return 1;
    }

    usleep(1000 * 1000);

    gpiod_line_set_value_cansleep(&gpio_chip_get_line_data(gpio_fd, GPIO_LINE_CS), 1);
    ret = read(spi_fd, &data, 1);
    if (ret != 1) {
        perror("Failed to read status register");
        fclose(log_file);
        gpiod_line_free_request(&gpio_req);
        close(gpio_fd);
        close(spi_fd);
        return 1;
    }

    if (!(data[0] & (1 << 7))) {
        fprintf(log_file, "Sensor not ready\n");
        fclose(log_file);
        gpiod_line_free_request(&gpio_req);
        close(gpio_fd);
        close(spi_fd);
        return 1;
    }

    // Set RUN bit
    gpiod_line_set_value_cansleep(&gpio_chip_get_line_data(gpio_fd, GPIO_LINE_CS), 1);
    ret = write(spi_fd, &ADXL354B_POWER_CTRL_REG, 1);
    gpiod_line_set_value_cansleep(&gpio_chip_get_line_data(gpio_fd, GPIO_LINE_CS), 0);
    if (ret != 1) {
        perror("Failed to write power control register");
        fclose(log_file);
        gpiod_line_free_request(&gpio_req);
        close(gpio_fd);
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        snprintf(log_buf, sizeof(log_buf), "%lld.%06ld: ", ts.tv_sec, ts.tv_nsec);

        gpiod_line_set_value_cansleep(&gpio_chip_get_line_data(gpio_fd, GPIO_LINE_CS), 1);
        ret = read(spi_fd, data, 6);
        gpiod_line_set_value_cansleep(&gpio_chip_get_line_data(gpio_fd, GPIO_LINE_CS), 0);
        if (ret != 6) {
            perror("Failed to read acceleration data");
            continue;
        }

        fprintf(log_file, "%sX: %d Y: %d Z: %d\n", log_buf, data[0] << 8 | data[1],
                data[2] << 8 | data[3], data[4] << 8 | data[5]);

        usleep(LOG_INTERVAL * 1000);
    }

    // Cleanup
    fclose(log_file);
    gpiod_line_free_request(&gpio_req);
    close(gpio_fd);
    close(spi_fd);

    return 0;
}
