static gpiod_line_request_lines_data_v1 lines_data = {
    .lines = (const gpiod_line_info_v1[]) {
        { .number = GPIO_LINE_NAME },
        GPIOD_LINE_REQUEST_INPUT,
        GPIOD_LINE_REQUEST_ACTIVE_LOW,
        GPIOD_LINE_REQUEST_DISABLE_PULL,
        { 0 }
    },
};

static void sigint_handler(int signum) {
    gpiod_line_release_request(gpio_request_lines(0, &lines_data));
    gpiod_chip_close(gpio_get_chip_byname(GPIO_CHIP_NAME));
    exit(0);
}

int main() {
    struct timespec ts;
    int chip_fd, line_fd;
    gpiod_line_value_v1 value;
    double sensor_reading;

    signal(SIGINT, sigint_handler);

    chip_fd = gpiod_chip_open(gpio_get_chip_byname(GPIO_CHIP_NAME));
    if (chip_fd < 0) {
        perror("Failed to open GPIO chip");
        exit(1);
    }

    line_fd = gpiod_chip_request_lines(chip_fd, &lines_data, 1);
    if (line_fd < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip_fd);
        exit(1);
    }

    while (1) {
        if (gpiod_line_get_value(line_fd, &value) < 0) {
            perror("Failed to read GPIO line value");
            break;
        }

        if (value.value == 0) {
            sensor_reading = DETECTION_RANGE;
        } else {
            sensor_reading = 0;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        printf("%ld.%09ld: Self-parking sequence started\n", ts.tv_sec, ts.tv_nsec);

        // Simulate a routine here
        sleep(5);

        clock_gettime(CLOCK_REALTIME, &ts);
        printf("%ld.%09ld: Self-parking sequence completed\n", ts.tv_sec, ts.tv_nsec);

        if (gpiod_line_release_request(line_fd) < 0) {
            perror("Failed to release GPIO line request");
            break;
        }

        line_fd = -1;
        sleep(POLL_INTERVAL);
    }

    if (line_fd != -1) {
        if (gpiod_line_release_request(line_fd) < 0) {
            perror("Failed to release GPIO line request");
        }
        line_fd = -1;
    }

    if (chip_fd != -1) {
        if (gpiod_chip_close(chip_fd) < 0) {
            perror("Failed to close GPIO chip");
        }
    }

    return 0;
}
