        return -1;
    }

    chip = gpiod_chip_open_by_index(gpio_fd, 0);
    if (!chip) {
        perror("Failed to open gpiochip");
        return -1;
    }

    sensor_1_line = gpiod_chip_get_line(chip, SENSOR_1_LINE);
    if (!sensor_1_line) {
