    clock_gettime(CLOCK_MONOTONIC, &ts);

    while (1) {
        ret = gpiod_line_get_value_cansleep(sensor_1_line, &sensor_1_state);
        if (ret < 0) {
            perror("Failed to read sensor 1 state");
            cleanup();
            return ret;
        }

        ret = gpiod_line_get_value_cansleep(sensor_2_line, &sensor_2_state);
