#include <stdio.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 3
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define GPIO_CE0_LINE "gpio8"
#define SCALE_FACTOR 0.02

static const int X_REG = 0x31;
static const int Y_REG = 0x33;
static const int Z_REG = 0x35;

int main() {
    int spi_fd, gpio_fd;
    struct spi_ioc_transfer transfers[3];
    gpiod_line_request_flags_t flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW;
    gpiod_line_data_t gpio_ce0_data;
    uint8_t data[3];
    double x, y, z;

    // Open SPI device
    if ((spi_fd = open(SPI_DEVICE, O_RDWR)) < 0) {
        perror("Can't open SPI device");
        return 1;
    }

    // Configure SPI bus settings
    spi_ioc_transfer t = {
        .tx_buf = (unsigned long)&SPI_MODE,
        .bits_per_word = SPI_BITS,
        .speed_hz = SPI_SPEED,
    };
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &t) < 1) {
        perror("Can't set SPI mode");
        close(spi_fd);
        return 1;
    }

    t.tx_buf = (unsigned long)&SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &t) < 1) {
        perror("Can't set max SPI speed");
        close(spi_fd);
        return 1;
    }

    // Open GPIO CE0 line
    if ((gpio_fd = gpiod_open_name(GPIO_CE0_LINE)) < 0) {
        perror("Can't open GPIO line");
        close(spi_fd);
        return 1;
    }

    // Request GPIO CE0 line
    if (gpiod_line_request_dtbo(gpio_fd, flags, &gpio_ce0_data) < 0) {
        perror("Can't request GPIO line");
        close(gpio_fd);
        close(spi_fd);
        return 1;
    }

    // Configure SPI transfers
    transfers[0].tx_buf = (unsigned long)&X_REG;
    transfers[0].len = 1;
    transfers[0].speed_hz = SPI_SPEED;
    transfers[0].bits_per_word = SPI_BITS;

    transfers[1].rx_buf = data;
    transfers[1].len = 2;
    transfers[1].speed_hz = SPI_SPEED;
    transfers[1].bits_per_word = SPI_BITS;

    transfers[2].tx_buf = NULL;
    transfers[2].len = 0;
    transfers[2].speed_hz = SPI_SPEED;
    transfers[2].bits_per_word = SPI_BITS;

    // Main loop
    for (;;) {
        gpiod_line_set_value(gpio_fd, gpio_ce0_data, 1);
        usleep(1000);
        if (spi_xfer(spi_fd, transfers, 3) != 3) {
            perror("SPI transfer error");
