#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x6A
#define ACC_OUT_X_L_REG 0x28
#define ACC_OUT_X_H_REG 0x29
#define ACC_OUT_Y_L_REG 0x2A
#define ACC_OUT_Y_H_REG 0x2B
#define ACC_OUT_Z_L_REG 0x2C
#define ACC_OUT_Z_H_REG 0x2D
#define GYRO_OUT_X_L_REG 0x2E
#define GYRO_OUT_X_H_REG 0x2F
#define GYRO_OUT_Y_L_REG 0x30
#define GYRO_OUT_Y_H_REG 0x31
#define GYRO_OUT_Z_L_REG 0x32
#define GYRO_OUT_Z_H_REG 0x33
#define WHO_AM_I_REG 0x0F

static int i2c_file;
static struct gpiod_chip *chip;
static gpiod_line_request_linestate_v1_callback read_cb;

int init_i2c() {
    const char *dev_name = "/dev/i2c-" I2C_BUS;
    if ((i2c_file = open(dev_name, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_file, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire bus access");
        close(i2c_file);
        return 1;
    }

    return 0;
}

int read_who_am_i() {
    uint8_t who_am_i;
    if (i2c_smbus_read_byte_data(i2c_file, WHO_AM_I_REG) != WHO_AM_I_REG) {
        perror("WHO_AM_I register mismatch");
        return 1;
    }

    if (read(i2c_file, &who_am_i, sizeof(who_am_i)) != sizeof(who_am_i)) {
        perror("Failed to read WHO_AM_I register");
        return 1;
    }

    if (who_am_i != 0x6A) {
        fprintf(stderr, "Wrong device: expected 0x6A, got 0x%02X\n", who_am_i);
        return 1;
    }

    return 0;
}

void read_acc_gyro(int16_t acc_x[3], int16_t gyro_x[3]) {
    acc_x[0] = (i2c_smbus_read_word_data(i2c_file, ACC_OUT_X_L_REG) << 8) | i2c_smbus_read_word_data(i2c_file, ACC_OUT_X_H_REG);
    acc_x[1] = (i2c_smbus_read_word_data(i2c_file, ACC_OUT_Y_L_REG) << 8) | i2c_smbus_read_word_data(i2c_file, ACC_OUT_Y_H_REG);
    acc_x[2] = (i2c_smbus_read_word_data(i2c_file, ACC_OUT_Z_L_REG) << 8) | i2c_smbus_read_word_data(i2c_file, ACC_OUT_Z_H_REG);

    gyro_x[0] = (i2c_smbus_read_word_data(i2c_file, GYRO_OUT_X_L_REG) << 8) | i2c_smbus_read_word_data(i2c_file, GYRO_OUT_X_H_REG);
    gyro_x[1] = (i2c_smbus_read_word_data(i2c_file, GYRO_OUT_Y_L_REG) << 8) | i2c_smbus_read_word_data(i2c_file, GYRO_OUT_Y_H_REG);
    gyro_x[2] = (i2c_smbus_read_word_data(i2c_file, GYRO_OUT_Z_L_REG) << 8) | i2c_smbus_read_word_data(i2c_file, GYRO_OUT_Z_H_REG);
}

void sigint_handler(int signum) {
    gpiod_line_request_cancel(chip, 0);
    close(i2c_file);
    gpiod_chip_exit(chip);
    exit(0);
}

int main() {
    int16_t acc_x[3], acc_y[3], acc_z[3], gyro_x[3], gyro_y[3], gyro_z[3];

    if (gpiod_chip_open_byname("gpiochip0", &chip) < 0) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    if (gpiod_line_request_direction_input(chip, 0, GPIOD_LINE_REQUEST_INPUT_ACTIVE_HIGH) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_exit(chip);
        return 1;
    }

    signal(SIGINT, sigint_handler);

    if (init_i2c()) {
        perror("Failed to initialize I2C");
        goto cleanup;
    }

    if (read_who_am_i()) {
        perror("Failed to read WHO_AM_I register");
        goto cleanup;
    }

    read_cb = gpiod_line_request_linestate_v1_callback(1, GPIOD_LINE_REQUEST_INPUT_ACTIVE_HIGH, NULL);
    if (gpiod_line_request_event_cb(chip, 0, read_cb, NULL) < 0) {
        perror("Failed to request GPIO line event callback");
        goto cleanup;
    }

    while (1) {
        usleep(100000); // 100ms delay

        read_acc_gyro(acc_x, gyro_x);
        printf("Accelerometer: %d, %d, %d\tGyroscope: %d, %d, %d\n", acc_x[0], acc_x[1], acc_x[2], gyro_x[0], gyro_x[1], gyro_x[2]);
    }

cleanup:
    gpiod_line_request_cancel(chip, 0);
    close(i2c_file);
    gpiod_chip_exit(chip);
    return 1;
}

