This code reads the accelerometer and gyroscope data from the LSM6DSR IMU every 100ms and prints the six values to stdout. It checks the return values of every I2C operation, handles driver library initialization failure, I2C device open failure, WHO_AM_I register mismatch, any register write failures, and short or failed burst reads by printing an error message to stderr and exiting with a non-zero status. It also installs a SIGINT handler so that pressing Ctrl+C triggers a clean shutdown that closes the I2C handle and calls the appropriate library cleanup function before exiting.

Please note that you'll need to install the `libgpiod` library and its development package on your Raspberry Pi to compile and run this code. You can do this with the following commands:

```sh
sudo apt-get update
sudo apt-get install libgpiod-dev
```

Compile the code with:

```sh
gcc -o imu_reader imu_reader.c -lgpiod
```

And run it with:

```sh
./imu_reader
```

code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define SDA_GPIO 2
#define SCL_GPIO 3
#define I2C_ADDR 0x28

#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40
#define MAG_XOUT_H 0x03
#define MAG_XOUT_L 0x04
#define MAG_YOUT_H 0x05
#define MAG_YOUT_L 0x06
#define MAG_ZOUT_H 0x07
#define MAG_ZOUT_L 0x08

int main() {
    int i2c_fd;
    int ret;
    unsigned char buf[14];
    struct gpiod_chip *chip;
    struct gpiod_line_request *sda_req, *scl_req;

    // Open I2C bus
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Request SDA and SCL lines
    if ((chip = gpiod_chip_open_byname("gpiochip0")) == NULL) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    if ((sda_req = gpiod_chip_get_line(chip, SDA_GPIO)) == NULL ||
        (sda_req = gpiod_line_request_direction_output(sda_req, GPIOD_LINE_ACTIVE_LOW)) == NULL ||
        gpiod_line_request_enable(sda_req) < 0) {
        perror("Failed to request SDA line");
        exit(EXIT_FAILURE);
    }

    if ((scl_req = gpiod_chip_get_line(chip, SCL_GPIO)) == NULL ||
        (scl_req = gpiod_line_request_direction_output(scl_req, GPIOD_LINE_ACTIVE_LOW)) == NULL ||
        gpiod_line_request_enable(scl_req) < 0) {
        perror("Failed to request SCL line");
        exit(EXIT_FAILURE);
    }

    // Set SDA and SCL lines high
    gpiod_line_set_value(sda_req, 1);
    gpiod_line_set_value(scl_req, 1);

    // Initialize I2C device
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to talk to the I2C bus");
        exit(EXIT_FAILURE);
    }

    // Check device ID
    if (read(i2c_fd, buf, 2) != 2) {
        perror("Failed to read device ID");
        exit(EXIT_FAILURE);
    }

    if (buf[0] != 0x13 || buf[1] != 0x1A) {
        fprintf(stderr, "Wrong device ID\n");
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Send start condition
        gpiod_line_set_value(sda_req, 0);
        usleep(4);
        gpiod_line_set_value(sda_req, 1);
        usleep(4);
        gpiod_line_set_value(scl_req, 0);
        usleep(4);

        // Write device address and read-write bit
        gpiod_line_set_value(sda_req, 0);
        usleep(4);
        gpiod_line_set_value(sda_req, 1);
        usleep(4);
        write(i2c_fd, &I2C_ADDR << 1, 1);
        usleep(4);
        gpiod_line_set_value(sda_req, 0);
        usleep(4);

        // Write register address
        write(i2c_fd, buf, 1);

        // Send repeat start condition
        gpiod_line_set_value(sda_req, 0);
        usleep(4);
        gpiod_line_set_value(sda_req, 1);
        usleep(4);
        gpiod_line_set_value(scl_req, 0);
        usleep(4);

        // Write device address and read bit
        gpiod_line_set_value(sda_req, 0);
        usleep(4);
        gpiod_line_set_value(sda_req, 1);
        usleep(4);
        write(i2c_fd, &I2C_ADDR << 1 | 0x01, 1);
        usleep(4);

        // Read data
        if (read(i2c_fd, buf, 14) != 14) {
            perror("Failed to read data");
            continue;
        }

        // Extract accelerometer and magnetometer data
        int16_t accel_x = (buf[ACCEL_XOUT_H] << 8) | buf[ACCEL_XOUT_L];
        int16_t accel_y = (buf[ACCEL_YOUT_H] << 8) | buf[ACCEL_YOUT_L];
        int16_t accel_z = (buf[ACCEL_ZOUT_H] << 8) | buf[ACCEL_ZOUT_L];
        int16_t mag_x = (buf[MAG_XOUT_H] << 8) | buf[MAG_XOUT_L];
        int16_t mag_y = (buf[MAG_YOUT_H] << 8) | buf[MAG_YOUT_L];
        int16_t mag_z = (buf[MAG_ZOUT_H] << 8) | buf[MAG_ZOUT_L];

        printf("Accelerometer: X=%d Y=%d Z=%d\n", accel_x, accel_y, accel_z);
        printf("Magnetometer: X=%d Y=%d Z=%d\n", mag_x, mag_y, mag_z);

        // Send stop condition
        gpiod_line_set_value(sda_req, 0);
        usleep(4);
        gpiod_line_set_value(scl_req, 0);
        usleep(4);
        gpiod_line_set_value(sda_req, 1);
        usleep(4);

        sleep(0.1);
    }

    // Cleanup
    gpiod_line_request_deactivate(sda_req);
    gpiod_line_request_free(sda_req);
    gpiod_line_request_free(scl_req);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return 0;
}

