        perror("Failed to request SDA line");
        exit(EXIT_FAILURE);
    }

    if ((scl_req = gpiod_chip_get_line(chip, SCL_GPIO)) == NULL ||
        (scl_req = gpiod_line_request_direction_output(scl_req, GPIOD_LINE_ACTIVE_LOW)) == NULL ||
        gpiod_line_request_enable(scl_req) < 0) {
        perror("Failed to request SCL line");
        exit(EXIT_FAILURE);
    }

    // Set SDA and SCL lines high
    gpiod_line_set_value(sda_req, 1);
    gpiod_line_set_value(scl_req, 1);

    // Initialize I2C device
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to talk to the I2C bus");
        exit(EXIT_FAILURE);
    }

    // Check device ID
    if (read(i2c_fd, buf, 2) != 2) {
        perror("Failed to read device ID");
        exit(EXIT_FAILURE);
    }

    if (buf[0] != 0x13 || buf[1] != 0x1A) {
        fprintf(stderr, "Wrong device ID\n");
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Send start condition
        gpiod_line_set_value(sda_req, 0);
        usleep(4);
        gpiod_line_set_value(sda_req, 1);
        usleep(4);
        gpiod_line_set_value(scl_req, 0);
        usleep(4);

        // Write device address and read-write bit
        gpiod_line_set_value(sda_req, 0);
        usleep(4);
        gpiod_line_set_value(sda_req, 1);
        usleep(4);
        write(i2c_fd, &I2C_ADDR << 1, 1);
        usleep(4);
        gpiod_line_set_value(sda_req, 0);
        usleep(4);

        // Write register address
        write(i2c_fd, buf, 1);

        // Send repeat start condition
        gpiod_line_set_value(sda_req, 0);
        usleep(4);
        gpiod_line_set_value(sda_req, 1);
        usleep(4);
        gpiod_line_set_value(scl_req, 0);
        usleep(4);

        // Write device address and read bit
        gpiod_line_set_value(sda_req, 0);
        usleep(4);
        gpiod_line_set_value(sda_req, 1);
        usleep(4);
        write(i2c_fd, &I2C_ADDR << 1 | 0x01, 1);
        usleep(4);

        // Read data
        if (read(i2c_fd, buf, 14) != 14) {
            perror("Failed to read data");
            continue;
        }

        // Extract accelerometer and magnetometer data
        int16_t accel_x = (buf[ACCEL_XOUT_H] << 8) | buf[ACCEL_XOUT_L];
        int16_t accel_y = (buf[ACCEL_YOUT_H] << 8) | buf[ACCEL_YOUT_L];
        int16_t accel_z = (buf[ACCEL_ZOUT_H] << 8) | buf[ACCEL_ZOUT_L];
        int16_t mag_x = (buf[MAG_XOUT_H] << 8) | buf[MAG_XOUT_L];
        int16_t mag_y = (buf[MAG_YOUT_H] << 8) | buf[MAG_YOUT_L];
        int16_t mag_z = (buf[MAG_ZOUT_H] << 8) | buf[MAG_ZOUT_L];

        printf("Accelerometer: X=%d Y=%d Z=%d\n", accel_x, accel_y, accel_z);
        printf("Magnetometer: X=%d Y=%d Z=%d\n", mag_x, mag_y, mag_z);

        // Send stop condition
        gpiod_line_set_value(sda_req, 0);
        usleep(4);
        gpiod_line_set_value(scl_req, 0);
        usleep(4);
        gpiod_line_set_value(sda_req, 1);
        usleep(4);

        sleep(0.1);
    }

    // Cleanup
    gpiod_line_request_deactivate(sda_req);
    gpiod_line_request_free(sda_req);
    gpiod_line_request_free(scl_req);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return 0;
}
```

