```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/time.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <math.h>
#include <gpiod.h>

#define ADXL345_ADDR 0x53
#define XOUT_REG 0x32
#define YOUT_REG 0x34
#define ZOUT_REG 0x36
#define POWER_CTL_REG 0x2D
#define MEAS_RATE_100HZ 0x21

#define LOG_FILE "/var/log/tilt_events.log"

struct i2c_dev {
    int fd;
    uint8_t addr;
};

struct i2c_dev adxl345;
struct timespec last_sample_time;
double tilt_threshold = 30.0;
double x, y, z, last_x, last_y, last_z;
double tilt_angle;

void i2c_init(void) {
    if ((adxl345.fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(adxl345.fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("Failed to acquire bus access");
        exit(EXIT_FAILURE);
    }
}

void i2c_read(uint8_t reg, uint8_t *buf, size_t len) {
    if (write(adxl345.fd, &reg, 1) != 1) {
        perror("Failed to write to I2C slave");
        exit(EXIT_FAILURE);
    }

    if (read(adxl345.fd, buf, len) != len) {
        perror("Failed to read from I2C slave");
        exit(EXIT_FAILURE);
    }
}

void i2c_write(uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(adxl345.fd, buf, 2) != 2) {
        perror("Failed to write to I2C slave");
        exit(EXIT_FAILURE);
    }
}

void log_event(void) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    struct tm tm = *localtime(&tv.tv_sec);
    char log_line[256];

    strftime(log_line, sizeof(log_line), "%Y-%m-%d %H:%M:%S.%d ", &tm);
    snprintf(log_line + strlen(log_line), sizeof(log_line) - strlen(log_line),
             "%f deg\n", tilt_angle);

    int log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    if (write(log_fd, log_line, strlen(log_line)) != strlen(log_line)) {
        perror("Failed to write to log file");
        exit(EXIT_FAILURE);
    }

    close(log_fd);
}

double calculate_tilt_angle(void) {
    double g = 9.81; // Earth's gravitational acceleration
    double a = sqrt(pow(x - last_x, 2) + pow(y - last_y, 2) + pow(z - last_z, 2));
    double angle = acos((pow(x, 2) + pow(y, 2) + pow(z, 2) - pow(last_x, 2) - pow(last_y, 2) - pow(last_z, 2)) / (2 * x * last_x + 2 * y * last_y + 2 * z * last_z)) * 180 / M_PI;
    tilt_angle = angle > 180 ? angle - 360 : angle;
    last_x = x;
    last_y = y;
    last_z = z;
    return tilt_angle;
}

void signal_handler(int sig) {
    close(adxl345.fd);
    exit(EXIT_SUCCESS);
}

int main(void) {
    signal(SIGINT, signal_handler);

    i2c_init();

    i2c_write(POWER_CTL_REG, MEAS_RATE_100HZ);

    while (1) {
        uint8_t x_buf[2], y_buf[2], z_buf[2];

        i2c_read(XOUT_REG, x_buf, 2);
        i2c_read(YOUT_REG, y_buf, 2);
        i2c_read(ZOUT_REG, z_buf, 2);

        x = (x_buf[0] << 8 | x_buf[1]) / 16.0;
        y = (y_buf[0] << 8 | y_buf[1]) / 16.0;
        z = (z_buf[0] << 8 | z_buf[1]) / 16.0;

        if (difftime(time(NULL), last_sample_time.tv_sec) >= 0.1) {
            tilt_angle = calculate_tilt_angle();
            if (tilt_angle > tilt_threshold) {
                log_event();
            }
            last_sample_time = time(NULL);
        }

        usleep(100000); // Sleep for 100ms
    }

    close(adxl345.fd);
    return 0;
}
```

This code initializes the I2C bus, sets the ADXL345 accelerometer to measure at 100Hz, and reads acceleration data every 100ms. If the tilt angle exceeds the specified threshold, it logs a timestamped event to /var/log/tilt_events.log. The program handles errors related to I2C communication, sensor-absent conditions, and bus errors, and releases resources on all exit paths, including proper handling of a Ctrl+C interrupt signal.

