    if (ret < 0) {
        perror("gpiod_chip_request_lines_data_v1");
        goto cleanup_chip;
    }

    line_data = line_request_data.lines[0];
    line_data.flags |= GPIOD_LINE_FLAG_INPUT;

    ret = gpiod_line_get_value_cansleep(line_data.consumer, &line_data.value);
    if (ret < 0) {
        perror("gpiod_line_get_value_cansleep");
        goto cleanup_request;
    }

    return 0;

cleanup_request:
    gpiod_line_release(line_data.consumer);
cleanup_chip:
    gpiod_chip_release(chip);
    return -1;
}

int main(int argc, char **argv) {
    struct timespec ts;
    int ret;

    if (argc != 2 || !isdigit(argv[1][0])) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
