        for (int i = 0; i < SAMPLES_PER_WINDOW; ++i) {
            ret = gpiod_line_get_value_cansleep(line_data.consumer, &line_data.value);
            if (ret < 0) {
                perror("gpiod_line_get_value_cansleep");
                goto cleanup;
            }

            if (line_data.value) {
                ++high_count;
            }
        }

        if (high_count > threshold) {
            printf("ALERT\n");
        } else {
            printf("High readings: %d\n", high_count);
        }

        high_count = 0;
        samples_in_window = 0;
        sleep(1);
    }

cleanup:
    gpiod_line_release(line_data.consumer);
    free(line_request_data.lines);
    return 0;
}

