#include <sys/ioctl.h>
#include <gpiod.h>

#define DOOR_A_LINE_NAME "gpiochip0\0/gpio17"
#define DOOR_B_LINE_NAME "gpiochip0\0/gpio27"
#define ACCESS_LOG_FILE "access_log.txt"
#define RANDOM_SEED_FILE "random_seed"

volatile sig_atomic_t sigint_received = 0;

void sigint_handler(int signum) {
    sigint_received = 1;
}

void gpiod_line_request_output(struct gpiod_chip *chip, struct gpiod_line *line, unsigned int flags) {
    int ret;

    ret = gpiod_line_request_output(line, flags);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        exit(EXIT_FAILURE);
    }
}

void gpiod_line_set_value(struct gpiod_line *line, int value) {
    int ret;

    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("gpiod_line_set_value");
        exit(EXIT_FAILURE);
    }
}

int gpiod_line_get_value(struct gpiod_line *line) {
    int ret;

    ret = gpiod_line_get_value(line);
    if (ret < 0) {
        perror("gpiod_line_get_value");
        exit(EXIT_FAILURE);
    }

    return ret;
}

int gpiod_line_get_consumer_by_name(struct gpiod_chip *chip, const char *consumer_name) {
    struct gpiod_line *line;
    int ret;

    line = gpiod_chip_get_line_byname(chip, consumer_name);
    if (!line) {
        perror("gpiod_chip_get_line_byname");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_get_consumer(line);
    if (ret < 0) {
        perror("gpiod_line_get_consumer");
