    }

    return ret;
}

void gpiod_line_release(struct gpiod_line *line) {
    int ret;

    ret = gpiod_line_release(line);
    if (ret < 0) {
        perror("gpiod_line_release");
        exit(EXIT_FAILURE);
    }
}

void open_access_log(FILE **file_ptr) {
    *file_ptr = fopen(ACCESS_LOG_FILE, "a");
    if (!*file_ptr) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }
}

void close_access_log(FILE *file) {
    int ret;

    ret = fclose(file);
    if (ret < 0) {
        perror("fclose");
        exit(EXIT_FAILURE);
    }
}

void log_access(FILE *file, time_t timestamp, uint64_t code) {
    char timestamp_str[32];
    char code_str[12];

    ctime_r(&timestamp, timestamp_str);
    snprintf(code_str, sizeof(code_str), "%llu", code);

    fprintf(file, "%s,%s\n", timestamp_str, code_str);
}

uint64_t generate_random_code() {
    time_t seed;
    uint64_t code;
    FILE *seed_file;
    int ret;

    seed_file = fopen(RANDOM_SEED_FILE, "r");
    if (!seed_file) {
        seed = time(NULL);
    } else {
        ret = fread(&seed, sizeof(seed), 1, seed_file);
        if (ret != 1) {
            perror("fread");
            exit(EXIT_FAILURE);
        }
        fclose(seed_file);
    }

    srand(seed);
    code = rand() % 1000000 + 100000;

    seed_file = fopen(RANDOM_SEED_FILE, "w");
    if (!seed_file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    ret = fwrite(&seed, sizeof(seed), 1, seed_file);
    if (ret != 1) {
        perror("fwrite");
        exit(EXIT_FAILURE);
    }

    fclose(seed_file);

    return code;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *door_a_line;
    struct gpiod_line *door_b_line;
    FILE *access_log;
    int door_a_state;
    int door_b_state;
    uint64_t generated_code;
    char user_input[7];
    size_t input_len;
    time_t timestamp;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_byname");
        exit(EXIT_FAILURE);
    }

    door_a_line = gpiod_line_get_line_byname(chip, DOOR_A_LINE_NAME);
    if (!door_a_line) {
        perror("gpiod_line_get_line_byname");
        exit(EXIT_FAILURE);
    }

    door_b_line = gpiod_line_get_line_byname(chip, DOOR_B_LINE_NAME);
    if (!door_b_line) {
        perror("gpiod_line_get_line_byname");
        exit(EXIT_FAILURE);
    }

    open_access_log(&access_log);

    gpiod_line_request_output(door_a_line, GPIOD_LINE_REQUEST_DIRECTION_OUT | GPIOD_LINE_REQUEST_ACTIVE_LOW, 0);
    gpiod_line_request_output(door_b_line, GPIOD_LINE_REQUEST_DIRECTION_OUT | GPIOD_LINE_REQUEST_ACTIVE_LOW, 0);

    while (!sigint_received) {
        door_a_state = gpiod_line_get_value(door_a_line);
        door_b_state = gpiod_line_get_value(door_b_line);

        if (door_a_state == 1 && door_b_state == 1) {
            generated_code = generate_random_code();
            printf("Generated code: %llu\n", generated_code);

            fflush(stdout);
            fgets(user_input, sizeof(user_input), stdin);
            input_len = strlen(user_input);

            if (input_len != 6) {
                printf("Invalid input. Please enter a six-digit number.\n");
                continue;
            }

            if (strspn(user_input, "0123456789") != input_len) {
                printf("Invalid input. Please enter a six-digit number.\n");
                continue;
            }

            if (atoll(user_input) == generated_code) {
                timestamp = time(NULL);
                log_access(access_log, timestamp, generated_code);
                printf("Access granted.\n");
            } else {
                printf("Access denied.\n");
            }
        }

        gpiod_line_set_value(door_a_line, 1);
        gpiod_line_set_value(door_b_line, 1);
        sleep(5);
        gpiod_line_set_value(door_a_line, 0);
        gpiod_line_set_value(door_b_line, 0);
    }

    gpiod_line_release(door_a_line);
    gpiod_line_release(door_b_line);
    gpiod_chip_close(chip);
    close_access_log(access_log);

    return 0;
}

