    if (!door_b_line) {
        perror("gpiod_line_get_line_byname");
        exit(EXIT_FAILURE);
    }

    open_access_log(&access_log);

    gpiod_line_request_output(door_a_line, GPIOD_LINE_REQUEST_DIRECTION_OUT | GPIOD_LINE_REQUEST_ACTIVE_LOW, 0);
    gpiod_line_request_output(door_b_line, GPIOD_LINE_REQUEST_DIRECTION_OUT | GPIOD_LINE_REQUEST_ACTIVE_LOW, 0);

    while (!sigint_received) {
        door_a_state = gpiod_line_get_value(door_a_line);
        door_b_state = gpiod_line_get_value(door_b_line);

        if (door_a_state == 1 && door_b_state == 1) {
            generated_code = generate_random_code();
            printf("Generated code: %llu\n", generated_code);

            fflush(stdout);
            fgets(user_input, sizeof(user_input), stdin);
            input_len = strlen(user_input);

            if (input_len != 6) {
                printf("Invalid input. Please enter a six-digit number.\n");
                continue;
            }

            if (strspn(user_input, "0123456789") != input_len) {
                printf("Invalid input. Please enter a six-digit number.\n");
                continue;
            }

            if (atoll(user_input) == generated_code) {
                timestamp = time(NULL);
                log_access(access_log, timestamp, generated_code);
                printf("Access granted.\n");
            } else {
                printf("Access denied.\n");
            }
        }

        gpiod_line_set_value(door_a_line, 1);
        gpiod_line_set_value(door_b_line, 1);
        sleep(5);
        gpiod_line_set_value(door_a_line, 0);
        gpiod_line_set_value(door_b_line, 0);
    }

    gpiod_line_release(door_a_line);
    gpiod_line_release(door_b_line);
    gpiod_chip_close(chip);
    close_access_log(access_log);

    return 0;
}
