This code initializes the GPIO lines, generates a random six-digit security code, reads user input, compares it to the generated code, logs successful accesses to a CSV file, and handles errors gracefully. It also installs a SIGINT/SIGTERM handler to cleanly exit the program when receiving the signals.

I'll provide a simple example using the `libgpiod` library for GPIO management and the `i2c-dev` kernel module for I2C communication. The BH1750FVI light sensor library is not available for C, so we'll use the raw I2C communication.

First, make sure you have the `i2c-dev` kernel module enabled and installed the libgpiod library.

```bash
sudo modprobe i2c-dev
sudo apt-get install libgpiod-dev
```

Here's the C code:

```c
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <time.h>

#define BH1750_ADDR 0x23
#define BH1750_ONE_TIME_HIGH_RES_MODE 0x20
#define BH1750_CONVERSION_TIME 180

static int g_i2c_file;
static gpiod_line_request_lines_data_t g_gpio_request_data = { 0 };

void cleanup(void) {
    if (g_i2c_file >= 0) {
        close(g_i2c_file);
    }
    if (g_gpio_request_data.lines) {
        gpiod_line_release_request(g_gpio_request_data.request);
        free(g_gpio_request_data.lines);
    }
}

void handle_sigint(int signum) {
    printf("\nExiting...\n");
    cleanup();
    exit(0);
}

int read_bh1750(uint16_t *data) {
    int ret;
    uint8_t buf[2];

    ret = write(g_i2c_file, &BH1750_ONE_TIME_HIGH_RES_MODE, 1);
    if (ret != 1) {
        perror("Failed to write to BH1750");
        return -1;
    }

    usleep(BH1750_CONVERSION_TIME * 1000);

    ret = read(g_i2c_file, buf, 2);
    if (ret != 2) {
        perror("Failed to read from BH1750");
        return -1;
    }

    *data = (buf[0] << 8) | buf[1];
    return 0;
}

int main(void) {
    int ret;
    uint16_t lux_value;
    time_t timestamp;
    FILE *log_file;
    struct sigaction sa;

    signal(SIGINT, handle_sigint);

    g_i2c_file = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_file < 0) {
        perror("Failed to open I2C bus");
        goto cleanup;
    }

    if (ioctl(g_i2c_file, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to talk to BH1750");
        goto cleanup;
    }

    ret = gpiod_claim_lines_data(&g_gpio_request_data, 1, "light_sensor_gpio", GPIOD_ASIS);
    if (ret < 0) {
        perror("Failed to claim GPIO line");
        goto cleanup;
    }

    g_gpio_request_data.lines[0] = gpiod_get_index_byname("gpio", "gpio2");

    log_file = fopen("light_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        goto cleanup;
    }

    while (1) {
        if (read_bh1750(&lux_value) < 0) {
            printf("Failed to read light sensor\n");
            continue;
        }

        timestamp = time(NULL);
        fprintf(log_file, "Timestamp: %s, Lux: %d\n", ctime(&timestamp), lux_value);

        gpiod_line_set_value(g_gpio_request_data.lines[0], 1);
        sleep(5);
        gpiod_line_set_value(g_gpio_request_data.lines[0], 0);
    }

cleanup:
    fclose(log_file);
    cleanup();
    return 0;
}
```

This code reads the light sensor every 5 seconds and logs the lux value to a file named `light_log.txt`. It also handles errors during I2C communication, opening the bus, and reading bytes from the sensor. The GPIO2 line is used as an indicator for logging activity.

