```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define HMC5883L_ADDR 0x1E
#define CAL_SAMPLES 100
#define PRINT_INTERVAL_MS 500

int i2c_file;
gpiod_line_request_lines_data_v1 lines_data = {0};
gpiod_line_request_lines_data_v1 *lines_data_ptr = &lines_data;
gpiod_line_request_data request_data = {0};
gpiod_line_request request = {0};

int init_i2c() {
    const char *i2c_dev = "/dev/i2c-" I2C_BUS;
    i2c_file = open(i2c_dev, O_RDWR);
    if (i2c_file < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(i2c_file, I2C_SLAVE, HMC5883L_ADDR) < 0) {
        perror("Failed to acquire I2C bus");
        close(i2c_file);
        return -1;
    }

    return 0;
}

int init_gpio() {
    int ret;
    gpiod_chip *chip;
    gpiod_line *line;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, 14);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_dt_byname(line, "rpi,gpio-shutdown", &request_data);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_dt_byname(line, "rpi,gpio-shutdown-assert-high", lines_data_ptr);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release_request(&request);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_enable(lines_data_ptr);
    if (ret < 0) {
        perror("Failed to enable GPIO line request");
        gpiod_line_release_request(&request);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

void read_magnetometer(int16_t data[3]) {
    char buf[6] = {0};
    int ret;

    ret = write(i2c_file, 0x03, 1);
    if (ret != 1) {
        perror("Failed to write to I2C device");
    }

    ret = read(i2c_file, buf, 6);
    if (ret != 6) {
        perror("Failed to read from I2C device");
    }

    data[0] = (buf[1] << 8) | buf[0];
    data[1] = (buf[3] << 8) | buf[2];
    data[2] = (buf[5] << 8) | buf[4];
}

void print_offset_corrected_data() {
    int16_t samples[CAL_SAMPLES];
    int16_t offset_x = 0, offset_y = 0, offset_z = 0;
    int i;

    for (i = 0; i < CAL_SAMPLES; i++) {
        int16_t data[3];
        read_magnetometer(data);
        samples[i] = data[0];
    }

    for (i = 0; i < CAL_SAMPLES; i++) {
        offset_x += samples[i];
        offset_y += samples[i];
        offset_z += samples[i];
    }

    offset_x /= CAL_SAMPLES;
    offset_y /= CAL_SAMPLES;
    offset_z /= CAL_SAMPLES;

    int16_t data[3];
    read_magnetometer(data);

    data[0] -= offset_x;
    data[1] -= offset_y;
    data[2] -= offset_z;

    printf("X: %d, Y: %d, Z: %d\n", data[0], data[1], data[2]);
}

void cleanup() {
    gpiod_line_release_request(&request);
    gpiod_chip_close(lines_data_ptr->chip);
    close(i2c_file);
}

int main() {
    if (init_i2c() < 0) {
        return 1;
    }

    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    struct timespec ts = {0};
    ts.tv_sec = PRINT_INTERVAL_MS / 1000;
    ts.tv_nsec = (PRINT_INTERVAL_MS % 1000) * 1000000;

    while (1) {
        nanosleep(&ts, NULL);
        print_offset_corrected_data();
    }

    cleanup();
    return 0;
}
```

