#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define LSM303D_ADDR 0x1D
#define OUT_X_L_ADDR 0x28
#define OUT_X_H_ADDR 0x29
#define INT1_PIN_NUMBER 23
#define BUFFER_SIZE 64
#define SENSITIVITY 0.061f

struct lsm303d_data {
    uint8_t x_l;
    uint8_t x_h;
    uint8_t y_l;
    uint8_t y_h;
    uint8_t z_l;
    uint8_t z_h;
};

int init_i2c(void) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        perror("Failed to acquire bus access");
        close(fd);
        return 1;
    }

    return fd;
}

int read_accel_data(int fd, struct lsm303d_data *data) {
    if (read(fd, &data->x_l, sizeof(data->x_l)) != sizeof(data->x_l)) {
        perror("Failed to read accelerometer data");
        return 1;
    }

    if (read(fd, &data->x_h, sizeof(data->x_h)) != sizeof(data->x_h)) {
        perror("Failed to read accelerometer data");
        return 1;
    }

    if (read(fd, &data->y_l, sizeof(data->y_l)) != sizeof(data->y_l)) {
        perror("Failed to read accelerometer data");
        return 1;
    }

    if (read(fd, &data->y_h, sizeof(data->y_h)) != sizeof(data->y_h)) {
        perror("Failed to read accelerometer data");
        return 1;
    }

    if (read(fd, &data->z_l, sizeof(data->z_l)) != sizeof(data->z_l)) {
        perror("Failed to read accelerometer data");
        return 1;
    }

    if (read(fd, &data->z_h, sizeof(data->z_h)) != sizeof(data->z_h)) {
        perror("Failed to read accelerometer data");
        return 1;
    }

    return 0;
}

void configure_accel(int fd) {
    uint8_t control_reg = 0x20; // Power down

    if (write(fd, &control_reg, sizeof(control_reg)) != sizeof(control_reg)) {
        perror("Failed to write to accelerometer control register");
    }

    usleep(100000); // Delay for 100ms to ensure register write takes effect

    control_reg = 0x28; // Configure for 100Hz ODR, 24bit resolution, and high-pass filter enabled
    if (write(fd, &control_reg, sizeof(control_reg)) != sizeof(control_reg)) {
        perror("Failed to write to accelerometer control register");
    }

    control_reg = 0x2A; // Configure INT1 for rising edge triggering with zero duration
    if (write(fd, &control_reg, sizeof(control_reg)) != sizeof(control_reg)) {
        perror("Failed to write to accelerometer control register");
    }

    control_reg = 0x2C; // Set INT1 threshold to 2000mg
    if (write(fd, &control_reg, sizeof(control_reg)) != sizeof(control_reg)) {
        perror("Failed to write to accelerometer control register");
    }

    control_reg = 0x20; // Power up
    if (write(fd, &control_reg, sizeof(control_reg)) != sizeof(control_reg)) {
        perror("Failed to write to accelerometer control register");
    }
}

int init_gpio(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, INT1_PIN_NUMBER);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line, GPIOD_LINE_ACTIVE_HIGH);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    return 0;
}

void print_samples(const struct lsm303d_data samples[10]) {
    printf("Timestamps and last 10 samples:\n");
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s\n", time_str);

    for (size_t i = 0; i < 10; ++i) {
        float x = (samples[i].x_h << 8 | samples[i].x_l) * SENSITIVITY;
        float y = (samples[i].y_h << 8 | samples[i].y_l) * SENSITIVITY;
        float z = (samples[i].z_h << 8 | samples[i].z_l) * SENSITIVITY;

        printf("Sample %zu: X=%.2f, Y=%.2f, Z=%.2f\n", i, x, y, z);
    }
}

void handle_int1(int fd, struct lsm303d_data *buffer, size_t *head, size_t *tail) {
    struct lsm303d_data sample;

    if (read_accel_data(fd, &sample) == 0) {
        buffer[(*head + *tail + 1) % BUFFER_SIZE] = sample;
        (*head) = ((*head + 1) % BUFFER_SIZE);
    } else {
        warn("Failed to read accelerometer data");
    }
}

int main(void) {
    int i2c_fd = -1;
    struct lsm303d_data buffer[BUFFER_SIZE];
    size_t head = 0;
    size_t tail = 0;

    if (init_gpio() != 0) {
        return 1;
    }

    i2c_fd = init_i2c();
    if (i2c_fd < 0) {
        return 1;
    }

    uint8_t who_am_i = 0;
    if (read(i2c_fd, &who_am_i, sizeof(who_am_i)) != sizeof(who_am_i)) {
        perror("Failed to read accelerometer WHO_AM_I register");
        goto cleanup;
    }

    if (who_am_i != 0x49) {
        perror("Accelerometer returned incorrect WHO_AM_I value");
        goto cleanup;
    }

    configure_accel(i2c_fd);

    while (1) {
        gpiod_line_get_value(gpiod_line_get_byname("gpiochip0", INT1_PIN_NUMBER));
        usleep(10000);
        gpiod_line_get_value(gpiod_line_get_byname("gpiochip0", INT1_PIN_NUMBER));
        if (gpiod_line_get_value(gpiod_line_get_byname("gpiochip0", INT1_PIN_NUMBER)) == 1) {
            handle_int1(i2c_fd, buffer, &head, &tail);
        }
    }

cleanup:
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    gpiod_chip_close(gpiod_chip_get_byname("gpiochip0"));
    return 1;
}

