#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define BAUD_RATE B9600
#define TIMEOUT 5000000 /* 5 seconds in microseconds */
#define RELAY_GPIO17 17
#define RELAY_GPIO27 27
#define EXPECTED_CODE "123456"
#define BUFFER_SIZE 6
#define NUM_PORTS 2

static gpiod_line_request_linestate_cb_t gpio_cb;
static gpiod_line_request_event_cb_t gpio_event_cb;
static gpiod_line_request *gpios[NUM_PORTS];
static int uart_fds[NUM_PORTS];
static char buffer[NUM_PORTS][BUFFER_SIZE];
static int buffer_index[NUM_PORTS];
static int is_running = 1;

static void gpio_cb(struct gpiod_line_request *request, int value,
                    struct gpiod_line_event_info *info)
{
    if (value == 1) {
        printf("GPIO %d triggered\n", gpiod_get_index(request));
        // Implement your logic to handle the GPIO event here
    }
}

static void gpio_event_cb(struct gpiod_line_request *request,
                          struct gpiod_line_event_info *info)
{
    printf("GPIO %d edge detected\n", gpiod_get_index(request));
    // Implement your logic to handle the GPIO edge event here
}

static void sigint_handler(int signum)
{
    is_running = 0;
    gpiod_line_request_set_value(gpios[RELAY_GPIO17], 0);
    gpiod_line_request_set_value(gpios[RELAY_GPIO27], 0);
    close(uart_fds[RELAY_GPIO17]);
    close(uart_fds[RELAY_GPIO27]);
    gpiod_line_request_release(gpios[RELAY_GPIO17]);
    gpiod_line_request_release(gpios[RELAY_GPIO27]);
    gpiod_shutdown();
    exit(0);
}

int main()
{
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    if (gpiod_library_init() < 0) {
        perror("gpiod_library_init");
        exit(EXIT_FAILURE);
    }

    gpios[RELAY_GPIO17] = gpiod_get_request_line("rpi", "gpio17", "out");
    if (!gpios[RELAY_GPIO17]) {
        perror("gpiod_get_request_line");
        exit(EXIT_FAILURE);
    }

    gpios[RELAY_GPIO27] = gpiod_get_request_line("rpi", "gpio27", "out");
    if (!gpios[RELAY_GPIO27]) {
        perror("gpiod_get_request_line");
        exit(EXIT_FAILURE);
    }

    gpio_cb(gpios[RELAY_GPIO17], 0, NULL);
    gpio_cb(gpios[RELAY_GPIO27], 0, NULL);

    gpiod_line_request_set_event_callback(gpios[RELAY_GPIO17], gpio_event_cb);
    gpiod_line_request_set_event_callback(gpios[RELAY_GPIO27], gpio_event_cb);

    for (int i = 0; i < NUM_PORTS; ++i) {
        uart_fds[i] = open("/dev/serial0", O_RDWR | O_NOCTTY | O_NDELAY);
        if (uart_fds[i] < 0) {
            perror("open");
            exit(EXIT_FAILURE);
        }

        struct termios options;
        tcgetattr(uart_fds[i], &options);
        cfsetispeed(&options, BAUD_RATE);
        cfsetospeed(&options, BAUD_RATE);
        options.c_cflag &= ~PARENB;
        options.c_cflag &= ~CSTOPB;
        options.c_cflag &= ~CSIZE;
        options.c_cflag |= CS8;
        options.c_cflag &= ~CRTSCTS;
        options.c_cflag |= CREAD | CLOCAL;
        options.c_iflag &= ~(IXON | IXOFF | IXANY);
        options.c_iflag &= ~(ICANON | ECHO | ECHOE | ISIG);
        options.c_oflag &= ~OPOST;
        options.c_cc[VMIN] = 0;
        options.c_cc[VTIME] = TIMEOUT;
        tcsetattr(uart_fds[i], TCSANOW, &options);
    }

    while (is_running) {
        for (int i = 0; i < NUM_PORTS; ++i) {
            int bytes_read = read(uart_fds[i], &buffer[i][buffer_index[i]], 1);
            if (bytes_read > 0) {
                if (isdigit(buffer[i][buffer_index[i]])) {
                    buffer[i][buffer_index[i]] -= '0';
                    ++buffer_index[i];
                } else {
                    buffer_index[i] = 0;
                }

                if (buffer_index[i] == BUFFER_SIZE) {
                    if (memcmp(buffer[i], buffer[!i], BUFFER_SIZE) == 0 &&
                        memcmp(buffer[i], EXPECTED_CODE, BUFFER_SIZE) == 0) {
                        gpiod_line_request_set_value(gpios[RELAY_GPIO17], 1);
                        gpiod_line_request_set_value(gpios[RELAY_GPIO27], 1);
                        usleep(2000000);
                        gpiod_line_request_set_value(gpios[RELAY_GPIO17], 0);
                        gpiod_line_request_set_value(gpios[RELAY_GPIO27], 0);
                    } else {
                        printf("Received codes do not match or do not match the expected code\n");
                    }

                    buffer_index[i] = 0;
                }
            } else if (errno != EAGAIN) {
                perror("read");
                is_running = 0;
            }
        }
    }

    for (int i = 0; i < NUM_PORTS; ++i) {
        close(uart_fds[i]);
    }

    gpiod_line_request_release(gpios[RELAY_GPIO17]);
    gpiod_line_request_release(gpios[RELAY_GPIO27]);
    gpiod_shutdown();

    return 0;
}

