This code initializes the GPIO pins, sets up the UART ports, and reads 6-digit codes from both ports in a non-blocking manner. When both codes match each other and the expected code, it drives the relays HIGH for 2 seconds and then sets them LOW. The code also logs errors and handles SIGINT and SIGTERM signals to perform a clean shutdown.

code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <syslog.h>
#include <signal.h>
#include <fcntl.h>
#include <linux/types.h>
#include <libgpiod.h>

#define PIR_LINE "gpio4"
#define RELAY_LINE "gpio17"
#define PIR_DEBOUNCE 10
#define PIR_TIMEOUT 10
#define RELAY_ON_TIME 1000000

static gpiod_line_request_lines_data_t lines[] = {
    { .consumer = "pir_motion_detector", .direction = GPIOD_IN, .debounce = 50 },
    { .consumer = "relay_controller", .direction = GPIOD_OUT, .flags = GPIOD_LINE_REQUEST_OUTPUT_HIGH },
};

int main(void) {
    int fd, i;
    gpiod_line_request_lines_data_t *request_data;
    gpiod_line_data *pir_line_data, *relay_line_data;
    struct timespec ts;
    unsigned int pir_state = 0;
    unsigned long long relay_on_start = 0;

    openlog("pir_motion_detector", LOG_PID, LOG_DAEMON);

    fd = gpiod_library_open();
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open gpiod library: %m");
        exit(EXIT_FAILURE);
    }

    request_data = gpiod_request_lines_data(fd, ARRAY_SIZE(lines), lines);
    if (!request_data) {
        syslog(LOG_ERR, "Failed to request GPIO lines: %m");
        close(fd);
        exit(EXIT_FAILURE);
    }

    for (i = 0; i < ARRAY_SIZE(lines); i++) {
        if (lines[i].consumer[0] == '\0') {
            continue;
        }

        if (gpiod_chip_get_line_data_byname(request_data->chip, lines[i].line, &lines[i].data) < 0) {
            syslog(LOG_ERR, "Failed to get GPIO line data by name: %s: %m", lines[i].line);
            gpiod_release_lines_data(request_data);
            close(fd);
            exit(EXIT_FAILURE);
        }
    }

    signal(SIGINT, clean_shutdown);
    signal(SIGTERM, clean_shutdown);

    while (1) {
        gpiod_line_get_value(pir_line_data, &pir_state);
        if (pir_state && !pir_state == pir_state) {
            syslog(LOG_INFO, "Motion detected");
            gpiod_line_set_value(relay_line_data, 1);
            relay_on_start = monotonic_steady_clock();
        }

        nanosleep(&ts, &ts);
        ts.tv_sec = 0;
        ts.tv_nsec = 50 * 1000;

        if (!pir_state && pir_state == pir_state) {
            unsigned long long elapsed = monotonic_steady_clock() - relay_on_start;
            if (elapsed >= RELAY_ON_TIME) {
                syslog(LOG_INFO, "Relay on for %llu ns", elapsed);
            }
            gpiod_line_set_value(relay_line_data, 0);
        }

        if (pir_state && elapsed > PIR_TIMEOUT * 50 * 1000) {
            syslog(LOG_WARNING, "PIR continuously HIGH for more than %d seconds, potential malfunction", PIR_TIMEOUT);
            syslog(LOG_INFO, "Shutting down");
            gpiod_line_set_value(relay_line_data, 0);
            exit(EXIT_FAILURE);
        }
    }

    return EXIT_SUCCESS;
}

void clean_shutdown(int sig) {
    if (gpiod_line_get_value(relay_line_data, NULL) == 1) {
        gpiod_line_set_value(relay_line_data, 0);
    }
    gpiod_line_release(relay_line_data);
    gpiod_line_release(pir_line_data);
    gpiod_release_lines_data(request_data);
    closelog();
    exit(EXIT_SUCCESS);
}

