#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/mman.h>
#include <sys/time.h>
#include <signal.h>
#include <pthread.h>
#include <linux/mpu6050.h>
#include <sys/stat.h>
#include <sys/sysmacros.h>

#define I2C_BUS 1
#define MPU6050_ADDR 0x68
#define BUFFER_SIZE 1024
#define SAMPLE_RATE 100

struct mpu6050_data {
    int16_t accel_x;
    int16_t accel_y;
    int16_t accel_z;
};

struct mpu6050_data buffer[BUFFER_SIZE];
volatile size_t head = 0;
volatile size_t tail = 0;
pthread_mutex_t buffer_lock = PTHREAD_MUTEX_INITIALIZER;

int i2c_fd;
struct i2c_rdwr_ioctl_data i2c_data;

void i2c_read(uint8_t reg, uint8_t *data, size_t len) {
    i2c_data.wr_len = 1;
    i2c_data.wr_buf = &reg;
    i2c_data.rd_len = len;
    i2c_data.rd_buf = data;

    if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) < 0) {
        perror("Failed to read from MPU6050");
        exit(EXIT_FAILURE);
    }
}

void* sample_loop(void* arg) {
    struct timespec ts;
    while (1) {
        uint8_t data[6];
        i2c_read(MPU6050_ACCEL_XOUT_H, data, 6);

        struct mpu6050_data sample;
        sample.accel_x = (data[0] << 8) | data[1];
        sample.accel_y = (data[2] << 8) | data[3];
        sample.accel_z = (data[4] << 8) | data[5];

        pthread_mutex_lock(&buffer_lock);
        buffer[head] = sample;
        head = (head + 1) % BUFFER_SIZE;
        pthread_mutex_unlock(&buffer_lock);

        ts.tv_sec = 1 / SAMPLE_RATE;
        ts.tv_nsec = (1000000000 / SAMPLE_RATE) % 1000000000;
        nanosleep(&ts, NULL);
    }
    return NULL;
}

void write_latest_sample() {
    pthread_mutex_lock(&buffer_lock);
    if (tail != head) {
        struct mpu6050_data sample = buffer[tail];
        char buf[64];
        snprintf(buf, sizeof(buf), "%d %d %d\n", sample.accel_x, sample.accel_y, sample.accel_z);
        int fd = open("/sys/kernel/mpu6050_accel/latest", O_WRONLY);
        write(fd, buf, strlen(buf));
        close(fd);
        tail = (tail + 1) % BUFFER_SIZE;
    }
    pthread_mutex_unlock(&buffer_lock);
}

void sigint_handler(int sig) {
    printf("Received SIGINT, cleaning up...\n");

    close(i2c_fd);
    munmap(i2c_data.wr_buf, i2c_data.wr_len);
    munmap(i2c_data.rd_buf, i2c_data.rd_len);
    pthread_cancel(sample_loop);
    pthread_join(sample_loop, NULL);

    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to connect to MPU6050");
        exit(EXIT_FAILURE);
    }

    mmap(&i2c_data.wr_buf, i2c_data.wr_len, PROT_READ | PROT_WRITE, MAP_SHARED, i2c_fd, 0);
    mmap(i2c_data.rd_buf, i2c_data.rd_len, PROT_READ, MAP_SHARED, i2c_fd, 0);

    pthread_t sample_thread;
    if (pthread_create(&sample_thread, NULL, sample_loop, NULL) != 0) {
        perror("Failed to create sample loop thread");
        exit(EXIT_FAILURE);
    }

    while (1) {
        write_latest_sample();
        sleep(1);
    }

    return 0;
}

