#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <fcntl.h>
#include <linux/types.h>
#include <sys/ioctl.h>
#include <gpiod.h>

#define RELAY_1_LINE "gpiochip0/gpio18"
#define RELAY_2_LINE "gpiochip0/gpio23"
#define RELAY_3_LINE "gpiochip0/gpio24"
#define RELAY_4_LINE "gpiochip0/gpio25"

static void gpiod_line_request_func(struct gpiod_line_request *request, int event, void *data) {
    struct gpiod_line *line = request->line;
    int value = gpiod_line_get_value(line);

    if (event == LINE_EVENT_EDGE_FALLING) {
        if (value == 0) {
            printf("Relay %d toggled off\n", line->number);
        } else {
            printf("Relay %d toggled on\n", line->number);
        }
    }
}

int main() {
    struct timespec delay[4] = {
        {2, 0}, {3, 0}, {5, 0}, {7, 0}
    };

    int ret;
    gpiod_line_request_data_t data[4];
    gpiod_line_request_callback_t callback = gpiod_line_request_func;
    gpiod_line_state_t state[4];

    gpiod_controller *controller;
    gpiod_chip *chip;
    gpiod_line_request *requests[4];

    controller = gpiod_controller_open_byname("gpiochip0");
    if (IS_ERR(controller)) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    chip = gpiod_controller_get_chip(controller);
    if (IS_ERR(chip)) {
        perror("Failed to get gpiochip0 chip");
        gpiod_controller_put(controller);
        return 1;
    }

    for (int i = 0; i < 4; ++i) {
        requests[i] = gpiod_chip_request_line(chip, RELAY_1_LINE + i, GPIOD_DIRECTION_OUT, GPIOD_LINE_ACTIVE_HIGH);
        if (IS_ERR(requests[i])) {
            perror("Failed to request line");
            gpiod_chip_put(chip);
            gpiod_controller_put(controller);
            return 1;
        }

        ret = gpiod_line_request_enable(requests[i]);
        if (ret < 0) {
            perror("Failed to enable line request");
            gpiod_line_request_put(requests[i]);
            gpiod_chip_put(chip);
            gpiod_controller_put(controller);
            return 1;
        }

        gpiod_line_get_state(requests[i]->line, &state[i]);
        data[i].callback_data = &state[i];
        gpiod_line_request_set_callback(requests[i], callback, &data[i]);
    }

    while (1) {
        for (int i = 0; i < 4; ++i) {
            gpiod_line_set_value(requests[i]->line, state[i].value ^ 1);
            state[i].value = state[i].value ^ 1;
            nanosleep(delay[i], NULL);
        }
    }

    for (int i = 0; i < 4; ++i) {
        gpiod_line_request_put(requests[i]);
    }
    gpiod_chip_put(chip);
    gpiod_controller_put(controller);

    return 0;
}

