#include <gpiod.h>
#include <pthread.h>

#define GPIO_SENSOR 17
#define GPIO_RELAY 27
#define DEBOUNCE_MS 1000
#define LOG_FILE "alarm_log.txt"

gpiod_line_request_lines_data_v1 lines_data = {
    .lines = (struct gpiod_line_request_data){
        [GPIO_SENSOR] = { .direction = GPIOD_IN, .edge_detected_callback = sensor_cb },
        [GPIO_RELAY] = { .direction = GPIOD_OUT, .value = 0 },
    },
    .num_lines = 2,
};

pthread_mutex_t relay_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_t sensor_thread;
time_t last_alarm = 0;

void sensor_cb(struct gpiod_line_event_data *data) {
    if (data->line != GPIO_SENSOR)
        return;

    pthread_mutex_lock(&relay_mutex);

    if (!last_alarm || time(NULL) - last_alarm > DEBOUNCE_MS) {
        gpiod_line_set_value_cansleep(data->chip, data->line, 1);
        last_alarm = time(NULL);
        printf("Alarm activated at: %s\n", ctime(&last_alarm));
    }

    pthread_mutex_unlock(&relay_mutex);
}

void relay_on() {
    gpiod_line_set_value_cansleep(lines_data.lines[GPIO_RELAY].chip,
                                  lines_data.lines[GPIO_RELAY].line, 1);
}

void relay_off() {
    gpiod_line_set_value_cansleep(lines_data.lines[GPIO_RELAY].chip,
                                  lines_data.lines[GPIO_RELAY].line, 0);
}

void log_alarm(time_t alarm_time) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        return;
    }

    fprintf(log_file, "Alarm activated at: %s", ctime(&alarm_time));
    fclose(log_file);
}

void sigint_handler(int sig) {
    relay_off();
    gpiod_line_release(lines_data.lines[GPIO_SENSOR].chip,
                       lines_data.lines[GPIO_SENSOR].line);
    gpiod_line_release(lines_data.lines[GPIO_RELAY].chip,
                       lines_data.lines[GPIO_RELAY].line);
    gpiod_line_request_release(lines_data.fd);
    exit(0);
}

int main() {
    int ret;
    struct gpiod_chip *sensor_chip, *relay_chip;
    struct gpiod_line_request_data *sensor_line, *relay_line;
    struct gpiod_line_request_data *lines;
    struct gpiod_line_request_data *line;
    struct gpiod_line_request_data *line_array[] = { &lines_data.lines[GPIO_SENSOR],
                                                     &lines_data.lines[GPIO_RELAY] };

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    ret = gpiod_library_open();
    if (ret < 0) {
        perror("gpiod_library_open");
        return 1;
    }

    sensor_chip = gpiod_chip_get_by_name("gpiochip0");
    if (!sensor_chip) {
        perror("gpiod_chip_get_by_name");
        goto cleanup;
    }

    relay_chip = gpiod_chip_get_by_name("gpiochip0");
    if (!relay_chip) {
        perror("gpiod_chip_get_by_name");
        goto cleanup;
    }

    lines = malloc(sizeof(struct gpiod_line_request_data) * lines_data.num_lines);
    if (!lines) {
        perror("malloc");
        goto cleanup;
    }

    memcpy(lines, line_array, sizeof(line_array));

    ret = gpiod_line_request_dt_mbus(sensor_chip, lines, GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_RISING);
    if (ret < 0) {
        perror("gpiod_line_request_dt_mbus");
        goto cleanup;
    }

    sensor_line = lines + GPIO_SENSOR;
    relay_line = lines + GPIO_RELAY;

    ret = gpiod_line_request_dt_mbus(relay_chip, relay_line, GPIOD_LINE_REQUEST_OUTPUT);
    if (ret < 0) {
        perror("gpiod_line_request_dt_mbus");
        goto cleanup;
    }

    ret = pthread_create(&sensor_thread, NULL, sensor_poll, &lines_data);
    if (ret) {
        perror("pthread_create");
        goto cleanup;
    }

    while (1) {
        usleep(100000);
    }

cleanup:
    for (line = lines; line < lines + lines_data.num_lines; ++line) {
        if (line->fd >= 0)
            close(line->fd);
    }

    free(lines);
    gpiod_line_request_release(lines_data.fd);
    gpiod_library_close();

    return ret < 0 ? EXIT_FAILURE : EXIT_SUCCESS;
}

void *sensor_poll(void *arg) {
    struct timespec ts = { 0, 100 * NANOSLEEP_MULTIPLIER };

    while (1) {
        nanosleep(&ts, NULL);
        gpiod_line_poll_dt_mbus(sensor_lines[GPIO_SENSOR].chip, sensor_lines[GPIO_SENSOR].line);
    }

    return NULL;
}

