#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <math.h>
#include <signal.h>
#include <gpiod.h>

#define MPU_ADDR 0x68
#define ACC_XOUT_H 0x3B
#define ACC_XOUT_L 0x3C
#define ACC_YOUT_H 0x3D
#define ACC_YOUT_L 0x3E
#define ACC_ZOUT_H 0x3F
#define ACC_ZOUT_L 0x40
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48
#define BUFFER_SIZE 100

struct gyro_data {
    int16_t x, y, z;
};

struct i2c_dev {
    int fd;
    gpiod_line_request_linestate_t line_state;
};

void i2c_init(struct i2c_dev *dev, const char *bus_name) {
    dev->fd = open(bus_name, O_RDWR);
    if (dev->fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(dev->fd, I2C_SLAVE, MPU_ADDR) < 0) {
        perror("Failed to select MPU-6050");
        close(dev->fd);
        exit(EXIT_FAILURE);
    }
}

void i2c_read(struct i2c_dev *dev, uint8_t reg, uint8_t *buf, size_t len) {
    ssize_t bytes_read;

    if ((bytes_read = read(dev->fd, buf, len)) != len) {
        perror("Failed to read from MPU-6050");
        close(dev->fd);
        exit(EXIT_FAILURE);
    }
}

void i2c_write(struct i2c_dev *dev, uint8_t reg, const uint8_t *buf, size_t len) {
    ssize_t bytes_written;

    if ((bytes_written = write(dev->fd, buf, len)) != len) {
        perror("Failed to write to MPU-6050");
        close(dev->fd);
        exit(EXIT_FAILURE);
    }
}

void gyro_data_to_rad(struct gyro_data *data, double *rad) {
    rad[0] = data->x * M_PI / 180.0;
    rad[1] = data->y * M_PI / 180.0;
    rad[2] = data->z * M_PI / 180.0;
}

double magnitude(double *rad) {
    return sqrt(rad[0] * rad[0] + rad[1] * rad[1] + rad[2] * rad[2]);
}

void signal_handler(int sig) {
    printf("Received SIGINT, exiting gracefully...\n");
    gpiod_line_set_value(gpiod_get_byname("gpiochip0", 17), 0);
    exit(EXIT_SUCCESS);
}

int main() {
    struct i2c_dev i2c;
    struct gyro_data buffer[BUFFER_SIZE];
    double rad[3];
    size_t head = 0, tail = 0;
    gpiod_line_data_t line_data;
    gpiod_line_callback_t callback;
    int i;

    i2c_init(&i2c, "/dev/i2c-1");

    signal(SIGINT, signal_handler);

    gpiod_chip_open_with_label("gpiochip0", GPIOD_CHIP_OPEN_FLAG_NONE);
    gpiod_line_get_byname("gpiochip0", 17, &line_data);
    gpiod_line_request_dt(&line_data, "MPU-6050 Alarm", GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW);
    gpiod_line_get_request_linestate(&line_data, &i2c.line_state);
    gpiod_line_add_debounce_filter(&line_data, 100000);
    callback.callback = [](struct gpiod_line_event_data *data) {
        gpiod_line_set_value(gpiod_get_byname("gpiochip0", 17), 1);
    };
    gpiod_line_set_debounced_edge_callback(&line_data, &callback);

    while (1) {
        i2c_read(&i2c, ACC_XOUT_H, (uint8_t *)&buffer[tail].x, 6);
        gyro_data_to_rad(&buffer[tail], rad);
        if (magnitude(rad) > 50.0) {
            printf("Angular velocity exceeded 50.0 degrees/second!\n");
            gpiod_line_set_value(gpiod_get_byname("gpiochip0", 17), 1);
        }
        tail = (tail + 1) % BUFFER_SIZE;

        if (head != tail) {
            i2c_read(&i2c, ACC_XOUT_H, (uint8_t *)&buffer[head].x, 6);
            gyro_data_to_rad(&buffer[head], rad);
            head = (head + 1) % BUFFER_SIZE;
        }

        gpiod_line_get_value(gpiod_get_byname("gpiochip0", 17), &line_data.value);
        if (line_data.value == i2c.line_state) {
            continue;
        }
        gpiod_line_set_value(gpiod_get_byname("gpiochip0", 17), i2c.line_state);
        break;
    }

    gpiod_line_release_request(&line_data);
    gpiod_chip_close(GPIOD_CHIP_CLOSE_FLAG_NONE);
    close(i2c.fd);

    return EXIT_SUCCESS;
}

