#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define HMC5883L_ADDR 0x1E
#define BUFFER_SIZE 100
#define TARGET_HEADING 90.0
#define DEGREE_THRESHOLD 10.0
#define GPIO_LINE "gpiochip0\0gpio17"

struct heading_data {
    double heading;
    time_t timestamp;
};

int i2c_file;
struct gpio_chip *gpio_chip;
struct gpio_line_request *gpio_line_req;

void i2c_read(uint8_t *buf) {
    ssize_t bytes_read;
    if ((bytes_read = read(i2c_file, buf, 6)) < 0) {
        perror("I2C read error");
    }
}

double get_heading() {
    uint8_t data[6];
    i2c_read(data);

    double x = (double)data[1] * 256.0 + data[0];
    double y = (double)data[3] * 256.0 + data[2];
    double z = (double)data[5] * 256.0 + data[4];

    double heading = atan2(y + 100.0, x + 100.0) * 180.0 / M_PI;
    if (heading < 0.0)
        heading += 360.0;

    return heading;
}

void gpio_setup() {
    gpio_chip = gpiod_chip_open_byname(GPIO_LINE);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    gpio_line_req = gpiod_chip_get_line_request_byname(gpio_chip, "gpio17");
    if (!gpio_line_req) {
        perror("Failed to get GPIO line request");
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_direction_output(gpio_line_req, GPIOD_LINE_ACTIVE_HIGH);
}

void gpio_cleanup() {
    gpiod_line_release(gpio_line_req);
    gpiod_chip_close(gpio_chip);
}

void signal_handler(int sig) {
    gpio_cleanup();
    exit(sig);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_file, I2C_SLAVE, HMC5883L_ADDR) < 0) {
        perror("Failed to acquire I2C bus");
        exit(EXIT_FAILURE);
    }

    gpio_setup();

    struct heading_data buffer[BUFFER_SIZE];
    time_t current_time;
    double last_heading = 0.0;
    int buffer_index = 0;

    while (1) {
        double heading = get_heading();
        time(&current_time);

        buffer[buffer_index].heading = heading;
        buffer[buffer_index].timestamp = current_time;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        if (fabs(heading - TARGET_HEADING) > DEGREE_THRESHOLD) {
            gpiod_line_set_value(gpio_line_req, 1);
        } else {
            gpiod_line_set_value(gpio_line_req, 0);
        }

        last_heading = heading;
        sleep(0.1);
    }

    gpio_cleanup();
    close(i2c_file);

    return 0;
}

