    int16_t gyro_z;
};

int i2c_read(int fd, uint8_t *buf, size_t len) {
    int ret;
    if ((ret = write(fd, &len, 1)) != 1) {
        perror("Failed to write length");
        return -1;
    }

    if ((ret = read(fd, buf, len)) != len) {
        perror("Failed to read data");
        return -1;
    }

    return 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    uint8_t data[2];
    data[0] = reg;
    memcpy(&data[1], buf, len);

    if (i2c_read(fd, data, len + 1) < 0) {
        return -1;
    }

    return write(fd, data, len + 1);
}

void log_data(struct mpu6050_data *data, int servo_pos) {
