    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, data->accel_x, data->accel_y, data->accel_z);
    fclose(log_file);
}

