void pwm_callback(struct gpiod_line *line, int event, void *data) {
    int *relay = (int *)data;
    if (event == GPIOD_LINE_EVENT_EDGE_FALLING) {
        gpiod_line_set_value(line, 1);
    }
}

void sigint_handler(int signum) {
