        gpiod_line_set_value_by_index(relays[i], 0);
        close(pwm_fd[i]);
    }
    gpiod_chip_unclaim(gpiod_chip_get_by_label("gpiochip0"));
    exit(0);
}

void sigterm_handler(int signum) {
    sigint_handler(signum);
}

