    usleep(10);
    uint64_t end = gpiod_line_get_value_cansleep(request, gpio);
    return (end - start) * 1000;
}

double map_frequency(double value, double src_min, double src_max, double dest_min, double dest_max) {
    return dest_min + (value - src_min) * (dest_max - dest_min) / (src_max - src_min);
}

void *theremin_thread(void *arg) {
    struct gpiod_chip *chip = arg;

    while (1) {
