        usleep(100000); // Wait for the pulse to settle

        uint32_t start = read_time_us(request, ECHO_GPIO);
        usleep(100000); // Wait for the echo to settle
        uint32_t end = read_time_us(request, ECHO_GPIO);

        double distance = (start + end) / 2 * 0.0343 / 2; // Convert to cm and average

        if (distance > 400) {
            fprintf(stderr, "Sensor not detected\n");
            continue;
        }

        double frequency = map_frequency(distance, 2, 400, BUZZER_MIN_FREQ, BUZZER_MAX_FREQ);
