#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <gpiod.h>

#define RED_GPIO 17
#define GREEN_GPIO 22
#define BLUE_GPIO 27
#define PWM_PERIOD_NS 1000000
#define PWM_DUTY_MAX_NS PWM_PERIOD_NS / 2

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int num_lines,
                                const char *const *lines, unsigned int flags) {
    int i;
    gpiod_line_request_line(chip, lines[i], flags);
    for (i = 1; i < num_lines; i++) {
        gpiod_line_request_line(chip, lines[i], GPIOD_LINE_REQUEST_INPUT | flags);
    }
    return num_lines;
}

int main() {
    struct gpiod_chip *chip;
    int ret;
    double proximity = 0.0;
    unsigned int red_duty, green_duty, blue_duty;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    ret = gpiod_line_request_array(chip, 3, &RED_GPIO, &GREEN_GPIO, &BLUE_GPIO,
                                   GPIOD_LINE_REQUEST_DIR_OUT | GPIOD_LINE_REQUEST_ACTIVE_HIGH);
    if (ret < 0) {
        perror("Failed to request GPIO lines");
        goto cleanup;
    }

    while (1) {
        proximity = sin(time(NULL));
        red_duty = PWM_DUTY_MAX_NS * proximity;
        green_duty = PWM_DUTY_MAX_NS * (1.0 - proximity);
        blue_duty = PWM_DUTY_MAX_NS;

        ret = gpiod_line_set_value(chip->lines[RED_GPIO], red_duty < PWM_DUTY_MAX_NS);
        if (ret < 0) {
            perror("Failed to set red GPIO");
            goto cleanup;
        }
        ret = gpiod_line_set_value(chip->lines[GREEN_GPIO], green_duty < PWM_DUTY_MAX_NS);
        if (ret < 0) {
            perror("Failed to set green GPIO");
            goto cleanup;
        }
        ret = gpiod_line_set_value(chip->lines[BLUE_GPIO], blue_duty < PWM_DUTY_MAX_NS);
        if (ret < 0) {
            perror("Failed to set blue GPIO");
            goto cleanup;
        }

        usleep(1000 * 1000);
    }

cleanup:
    gpiod_line_release_array(chip, 3, &RED_GPIO, &GREEN_GPIO, &BLUE_GPIO);
    gpiod_chip_close(chip);
    return ret < 0 ? EXIT_FAILURE : EXIT_SUCCESS;
}

