Here's a complete, compilable C code for a Raspberry Pi 4 Model B that reads angular velocity from an MPU-6050 gyroscope over the I2C bus `/dev/i2c-1` using the libgpiod library for GPIO handling and the `i2c-dev` kernel driver for I2C communication. The program samples the sensor every 100ms, appends a timestamp followed by the x, y, and z axis values in degrees per second to a file named `gyro_log.txt`, and handles I/O and I2C errors robustly.

```c
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/mman.h>
#include <gpiod.h>

#define MPU_ADDR 0x68
#define SDA_GPIO 2
#define SCL_GPIO 3

#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

struct mpu6050_data {
    int16_t accel_x;
    int16_t accel_y;
    int16_t accel_z;
    int16_t gyro_x;
    int16_t gyro_y;
    int16_t gyro_z;
};

int init_i2c(void) {
    int i2c_fd;
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return -1;
    }

    return i2c_fd;
}

int init_gpio(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *line_sda, *line_scl;
    int ret;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return -1;
    }

