    if (!line_sda) {
        perror("Failed to get SDA line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(line_sda, GPIOD_LINE_ACTIVE_LOW, "MPU-6050 SDA");
    if (ret < 0) {
        perror("Failed to request SDA line");
        gpiod_line_release(line_sda);
        gpiod_chip_close(chip);
        return -1;
    }

    line_scl = gpiod_get_line(chip, SCL_GPIO);
    if (!line_scl) {
        perror("Failed to get SCL line");
        gpiod_line_release(line_sda);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(line_scl, GPIOD_LINE_ACTIVE_HIGH, "MPU-6050 SCL");
    if (ret < 0) {
        perror("Failed to request SCL line");
        gpiod_line_release(line_scl);
        gpiod_line_release(line_sda);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_set_value(line_sda, 0);
    usleep(100000);
    gpiod_line_set_value(line_scl, 1);
    usleep(100000);
    gpiod_line_set_value(line_sda, 1);
    usleep(100000);
    gpiod_line_set_value(line_scl, 0);

    return 0;
}

int read_mpu6050(int i2c_fd, struct mpu6050_data *data) {
    uint8_t buf[14];
    ssize_t n;

    n = read(i2c_fd, buf, 14);
    if (n != 14) {
        perror("Failed to read from MPU-6050");
        return -1;
    }

    data->accel_x = (int16_t)((buf[ACCEL_XOUT_H] << 8) | buf[ACCEL_XOUT_L]);
    data->accel_y = (int16_t)((buf[ACCEL_YOUT_H] << 8) | buf[ACCEL_YOUT_L]);
    data->accel_z = (int16_t)((buf[ACCEL_ZOUT_H] << 8) | buf[ACCEL_ZOUT_L]);
    data->gyro_x = (int16_t)((buf[GYRO_XOUT_H] << 8) | buf[GYRO_XOUT_L]);
    data->gyro_y = (int16_t)((buf[GYRO_YOUT_H] << 8) | buf[GYRO_YOUT_L]);
    data->gyro_z = (int16_t)((buf[GYRO_ZOUT_H] << 8) | buf[GYRO_ZOUT_L]);

    return 0;
}

void write_to_file(const char *filename, const struct mpu6050_data *data) {
    FILE *file;
    time_t timestamp;

    if ((file = fopen(filename, "a")) == NULL) {
        perror("Failed to open gyro_log.txt");
        return;
    }

    timestamp = time(NULL);
    fprintf(file, "%s ", ctime(&timestamp));
    fprintf(file, "%d %d %d %d %d %d\n", data->accel_x, data->accel_y, data->accel_z, data->gyro_x, data->gyro_y, data->gyro_z);
    fclose(file);
}

void cleanup(int i2c_fd, FILE *file, struct gpiod_line *line_sda, struct gpiod_line *line_scl) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    if (file) {
        fclose(file);
    }

    if (line_sda) {
        gpiod_line_release(line_sda);
    }

    if (line_scl) {
        gpiod_line_release(line_scl);
    }
}

int main(void) {
    int i2c_fd;
    FILE *file;
    struct mpu6050_data data;
    struct gpiod_line *line_sda, *line_scl;
    int ret;

    if (init_gpio() < 0) {
        return 1;
    }

    if ((file = fopen("gyro_log.txt", "w")) == NULL) {
        perror("Failed to create gyro_log.txt");
        goto cleanup_gpio;
    }

    if ((i2c_fd = init_i2c()) < 0) {
