#define GPIO_BUTTON 17
#define GPIO_BUZZER 18
#define PWM_PERIOD 4096
#define PWM_DUTY_MAX PWM_PERIOD / 2

static gpiod_line_request_lines_data_v1 lines_data = { .flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_DEBOUNCE };
static gpiod_line_handle *button_handle = NULL;
static gpiod_line_handle *buzzer_handle = NULL;
static pthread_t isr_thread;
static pthread_mutex_t flag_mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile int play_melody = 0;
static volatile int melody_index = 0;

static void buzzer_isr(unsigned long context) {
    int duty = PWM_DUTY_MAX * melody[melody_index] / 100;
    gpiod_line_set_value(buzzer_handle, duty * 1000 / PWM_PERIOD);
    melody_index = (melody_index + 1) % sizeof(melody);
}

static void buzzer_pwm_setup() {
    int fd = gpiod_chip_open_byname("gpiochip0");
    if (fd < 0) {
        perror("Failed to open gpiochip0");
        exit(EXIT_FAILURE);
    }

    button_handle = gpiod_chip_get_line(fd, GPIO_BUTTON);
    if (!button_handle) {
        perror("Failed to get GPIO_BUTTON line");
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_lines(fd, &lines_data, 1, &button_handle);
    gpiod_line_set_debounce(button_handle, 50 * 1000);

    buzzer_handle = gpiod_chip_get_line(fd, GPIO_BUZZER);
    if (!buzzer_handle) {
        perror("Failed to get GPIO_BUZZER line");
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_line(buzzer_handle, GPIOD_LINE_REQUEST_DIRECTION_OUT | GPIOD_LINE_REQUEST_PRESENT_VALUE_HIGH);

    struct spi_ioc_transfer spi_xfer[2];
    struct spi_ioc_transfer *xfer = spi_xfer;
    memset(spi_xfer, 0, sizeof(spi_xfer));

    xfer->tx_buf = (unsigned char*)&PWM_PERIOD;
    xfer->len = sizeof(PWM_PERIOD);
    xfer->delay_usecs = 0;
    xfer->bits_per_word = 16;
    xfer->speed_hz = 1000000;

    xfer->tx_buf = (unsigned char*)&PWM_DUTY_MAX;
    xfer->len = sizeof(PWM_DUTY_MAX);
    xfer->delay_usecs = 0;
    xfer++;

    int spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), spi_xfer) < 1) {
        perror("Failed to configure PWM");
        exit(EXIT_FAILURE);
    }

    close(spi_fd);
}

static void buzzer_pwm_teardown() {
    if (buzzer_handle) {
        gpiod_line_release(buzzer_handle);
        buzzer_handle = NULL;
    }

    if (button_handle) {
        gpiod_line_release(button_handle);
        button_handle = NULL;
    }

    if (gpiod_chip_is_open()) {
        gpiod_chip_close(gpiod_chip_get_fd());
    }
}

static void signal_handler(int sig) {
    play_melody = 0;
    pthread_mutex_lock(&flag_mutex);
    pthread_join(isr_thread, NULL);
    pthread_mutex_unlock(&flag_mutex);
    buzzer_pwm_teardown();
    exit(0);
}

int main() {
    buzzer_pwm_setup();

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    const int melody[] = { 100, 200, 100, 50, 100, 200, 100, 50, 100, 200, 100, 50, 100, 200, 100, 50 };

    pthread_create(&isr_thread, NULL, buzzer_isr, NULL);

    while (1) {
        pthread_mutex_lock(&flag_mutex);
        if (play_melody) {
            play_melody = 0;
        } else if (gpiod_line_get_value(button_handle)) {
            play_melody = 1;
        }
        pthread_mutex_unlock(&flag_mutex);
        usleep(100000);
    }

    return 0;
}

