#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_LINE "gpiochip0\0/gpio17"
#define LOG_FILE "vibration_events.log"

volatile sig_atomic_t sigint_received = 0;
struct gpiod_line *line;
int log_fd;

void sigint_handler(int signum) {
    sigint_received = 1;
}

void log_event(int value) {
    char timestamp[32];
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%f", tm);

    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    if (dprintf(log_fd, "%s,%d\n", timestamp, value) < 0) {
        perror("dprintf");
    } else {
        fflush(log_fd);
        fsync(log_fd);
    }
}

int main(int argc, char **argv) {
    int poll_timeout = 1000;
    if (argc > 1) {
        poll_timeout = atoi(argv[1]);
    }

    struct gpiod_line_request request = GPIOD_LINE_REQUEST_DIRECTION_IN |
                                         GPIOD_LINE_REQUEST_EDGE_RISING |
                                         GPIOD_LINE_REQUEST_EDGE_FALLING;

    line = gpiod_chip_get_line_byname(gpiod_chip_get_bylabel("gpiochip0"), GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line_byname");
        return 1;
    }

    if (gpiod_line_request_configure_async(line, &request, NULL) < 0) {
        perror("gpiod_line_request_configure_async");
        goto cleanup;
    }

    sigset_t sigset;
    sigemptyset(&sigset);
    sigaddset(&sigset, SIGINT);
    sigaddset(&sigset, SIGTERM);
    pthread_sigmask(SIG_SETMASK, &sigset, NULL);

    sigint_received = 0;
    int events[5] = {0};
    int event_count = 0;

    while (!sigint_received) {
        int value;
        int ret = gpiod_line_get_value_async(line, &value);
        if (ret < 0) {
            perror("gpiod_line_get_value_async");
            goto cleanup;
        }

        if (event_count >= 5) {
            int alerts = 0;
            for (int i = 0; i < 5; ++i) {
                if (events[i] == 1) {
                    ++alerts;
                }
            }

            if (alerts >= 3) {
                time_t now = time(NULL);
                struct tm *tm = localtime(&now);
                printf("EARTHQUAKE ALERT at %s\n", asctime(tm));
            }

            memmove(events, events + 1, sizeof(events) - 1);
            events[4] = value;
            event_count = 4;
        } else {
            events[event_count++] = value;
