struct i2c_data {
    int fd;
    char *buf;
};

static int i2c_read(struct i2c_data *data, uint8_t addr, uint8_t *buf, size_t len)
{
    int ret;
    struct i2c_rdwr_ioctl_data i2c_msg[2];
    struct i2c_msg msg[2];

    i2c_msg[0].addr = addr << 1;
    i2c_msg[0].flags = 0;
    i2c_msg[0].len = 0;
    i2c_msg[1].addr = addr << 1 | I2C_M_RD;
    i2c_msg[1].flags = 0;
    i2c_msg[1].len = len;
    i2c_msg[1].buf = buf;

    i2c_rdwr_ioctl_setup(data->fd, i2c_msg, 2);
    ret = ioctl(data->fd, I2C_RDWR, &i2c_rdwr_ioctl_data);
    if (ret < 0) {
        perror("i2c_rdwr");
        return -1;
    }

    return 0;
}

static void i2c_cleanup(struct i2c_data *data)
{
    if (data->fd >= 0) {
        close(data->fd);
        free(data->buf);
    }
}

static int open_i2c(void)
{
    int ret;
    char filename[32];
    struct i2c_data data;

    snprintf(filename, sizeof(filename), "/dev/i2c-%d", I2C_BUS);
    data.fd = open(filename, O_RDWR | O_NONBLOCK);
    if (data.fd < 0) {
        perror("open");
        return -1;
    }

    data.buf = mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_SHARED, data.fd, 0);
    if (data.buf == MAP_FAILED) {
        perror("mmap");
        close(data.fd);
        return -1;
    }

    return 0;
}

static void sigint_handler(int signum)
{
    i2c_cleanup(&g_i2c_data);
    fclose(g_csv_file);
    exit(0);
}

