{
    struct timespec ts;
    int ret;
    uint8_t buf[6];
    s16 x, y, z;
    float heading;
    char csv_header[128];
    FILE *csv_file;
    struct gpiod_line *gpio_line;
    struct gpiod_line_request *gpio_request;
    int gpio_fd;

    if (open_i2c() < 0) {
        return 1;
    }

    g_i2c_data.fd = data.fd;

    gpio_fd = gpiod_open_array_with_index("gpiochip0", 0, 0, "out", GPIOD_LINE_ACTIVE_LOW);
    if (gpio_fd < 0) {
        perror("gpiod_open_array_with_index");
        i2c_cleanup(&g_i2c_data);
        return 1;
    }

    gpio_request = gpiod_chip_get_request(gpio_fd, 0);
    gpio_line = gpiod_get_line(gpio_request, 0);
    gpiod_line_set_value(gpio_line, 1);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    if (access("mag_log.csv", F_OK) == 0) {
        csv_file = fopen("mag_log.csv", "a");
    } else {
        snprintf(csv_header, sizeof(csv_header), "Timestamp, Calibrated X, Calibrated Y, Calibrated Z, Heading\n");
        csv_file = fopen("mag_log.csv", "w");
        fputs(csv_header, csv_file);
    }

    while (1) {
        ret = i2c_read(&g_i2c_data, LSM303DLHC_ADDR, buf, 6);
        if (ret < 0) {
            fprintf(stderr, "i2c_read failed: %s\n", strerror(errno));
            continue;
        }

        x = (s16)((buf[1] << 8) | buf[0]);
        y = (s16)((buf[3] << 8) | buf[2]);
        z = (s16)((buf[5] << 8) | buf[4]);

        heading = atan2f(y + Y_OFFSET, x + X_OFFSET) * 180.0 / M_PI + Z_OFFSET;
        if (heading < 0) {
            heading += 360;
        }

        ts = time(NULL);
        fprintf(csv_file, "%ld, %d, %d, %d, %d\n", (long)ts.tv_sec, x, y, z, (int)heading);
        fflush(csv_file);

        printf("%s %d\n", compass_directions[(int)(heading / 45) % 8], (int)heading);

        gpiod_line_set_value(gpio_line, 0);
        usleep(100000);
        gpiod_line_set_value(gpio_line, 1);

        clock_gettime(CLOCK_REALTIME, &ts);
        sleep(1);
    }

    i2c_cleanup(&g_i2c_data);
    fclose(csv_file);
    gpiod_line_put(gpio_line);
    gpiod_chip_close(gpio_fd);

    return 0;
}

