#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/time.h>
#include <time.h>
#include <libgpiod.h>

#define RELAY_GPIO 17
#define SENSOR_GPIO 4
#define DEBOUNCE_TIME_MS 200
#define LOG_FILE "relay_log.json"

static gpiod_line_request_lines_data_t lines_data = { .request_lines = NULL };
static gpiod_line_request_lines *lines;
static gpiod_line_data *relay, *sensor;
static int relay_state = 0;

static void sigint_handler(int signum) {
    gpiod_line_set_value(relay, !relay_state);
    gpiod_line_release(relay);
    gpiod_line_release(sensor);
    gpiod_line_request_free(&lines_data);
    free(lines_data.request_lines);
    exit(0);
}

static void log_state_change(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[32];
    FILE *log_file = fopen(LOG_FILE, "a");

    if (!log_file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    rawtime = time(NULL);
    timeinfo = localtime(&rawtime);
    strftime(time_str, sizeof(time_str), "%Y-%m-%dT%H:%M:%S.%f", timeinfo);

    fprintf(log_file, "{\"timestamp\": \"%s\", \"relay_state\": \"%s\"}\n", time_str, state ? "ON" : "OFF");
    fclose(log_file);
}

static void sensor_isr(struct gpiod_line_event *event) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    long long current_time = tv.tv_sec * 1000 + tv.tv_usec / 1000;

    if (current_time - event->timestamp < DEBOUNCE_TIME_MS)
        return;

    if (relay_state != gpiod_line_get_value(sensor)) {
        relay_state = !relay_state;
        gpiod_line_set_value(relay, relay_state);
        log_state_change(relay_state);
    }
}

int main() {
    int ret;

    signal(SIGINT, sigint_handler);

    ret = gpiod_library_open();
    if (ret < 0) {
        perror("gpiod_library_open");
        exit(EXIT_FAILURE);
    }

    lines = gpiod_chip_get_lines(gpiod_library_get_chip_by_name("gpiochip0"), "4 17");
    if (!lines) {
        perror("gpiod_chip_get_lines");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_configure_flags(lines, GPIOD_LINE_REQUEST_DIRECTION_IN, GPIOD_LINE_REQUEST_EDGE_RISING, NULL);
    if (ret < 0) {
        perror("gpiod_line_request_configure_flags");
        exit(EXIT_FAILURE);
    }

    sensor = lines->lines + SENSOR_GPIO;
    relay = lines->lines + RELAY_GPIO;

    ret = gpiod_line_request_enable(sensor, &lines_data);
    if (ret < 0) {
        perror("gpiod_line_request_enable");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_enable(relay, &lines_data);
    if (ret < 0) {
        perror("gpiod_line_request_enable");
        exit(EXIT_FAILURE);
    }

    gpiod_line_add_event_callback(sensor, sensor_isr, NULL);

    while (1) {
        usleep(100000);
    }

    gpiod_line_remove_event_callback(sensor, sensor_isr);
    gpiod_line_request_disable(sensor, &lines_data);
    gpiod_line_request_disable(relay, &lines_data);
    gpiod_line_release(sensor);
    gpiod_line_release(relay);
    gpiod_line_request_free(&lines_data);
    gpiod_library_close();

    return 0;
}

