}

void signal_handler(int signum) {
    for (int i = 0; i < RELAY_COUNT; ++i) {
        gpiod_line_set_value(lines[i], 1);
    }

    gpiod_line_release(lines[0]);
    gpiod_line_release(lines[1]);
    gpiod_line_release(lines[2]);
    gpiod_line_release(lines[3]);

    fclose(log_file);
    exit(0);
}

int main() {
    srand(time(NULL));
    int moisture = rand() % 101;

    struct gpiod_chip *chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        log_error("Failed to open gpiochip0");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_error("Failed to open log file");
        gpiod_chip_close(chip);
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    char *token;
    char *tokens[RELAY_COUNT];
    char *save_ptr;

    char *line = strdup(RELAY_GPIO_LIST);
    if (!line) {
        log_error("Failed to allocate memory for GPIO list");
        fclose(log_file);
        gpiod_chip_close(chip);
        return 1;
    }

    int i = 0;
    token = strtok_r(line, " ", &save_ptr);
    while (token) {
        tokens[i++] = token;
        token = strtok_r(NULL, " ", &save_ptr);
    }

    for (int j = 0; j < RELAY_COUNT; ++j) {
        requests[j].consumer = "irrigation_system";
        requests[j].flags = GPIOD_LINE_REQUEST_DIRECTION_OUT;

        lines_data[j].consumer_data = &requests[j];
        lines_data[j].request_data = &requests[j];

        lines[j] = gpiod_chip_request_line(chip, atoi(tokens[j]), 1, &lines_data[j]);
        if (!lines[j]) {
            log_error("Failed to request GPIO line");
            for (int k = 0; k < j; ++k) {
                gpiod_line_release(lines[k]);
            }
            fclose(log_file);
            gpiod_chip_close(chip);
            free(line);
            return 1;
        }
    }

    while (1) {
        int new_moisture = rand() % 101;
        if (new_moisture < 30 && moisture >= 30) {
            moisture = new_moisture;
            log_irrigation(0, moisture);
        }

        for (int i = 0; i < RELAY_COUNT; ++i) {
            if (i > 0 && moisture_levels[i - 1] == moisture_levels[i]) {
                usleep(1000000);
            }

            if (gpiod_line_get_value(lines[i]) == 1) {
                gpiod_line_set_value(lines[i], 0);
                usleep(5000000);
                gpiod_line_set_value(lines[i], 1);
            }
        }

        moisture = new_moisture;
        sleep(10);
    }

    for (int i = 0; i < RELAY_COUNT; ++i) {
        gpiod_line_release(lines[i]);
    }

    fclose(log_file);
    gpiod_chip_close(chip);
    free(line);

    return 0;
}
```

This code initializes the GPIO lines, sets up signal handlers for SIGINT and SIGTERM, and then enters an infinite loop where it generates a simulated moisture level every 10 seconds. If the moisture level is below 30, it activates the relays one by one with a 1-second gap between each activation and logs the event to a file. When the program receives SIGINT or SIGTERM, it deactivates all relays, releases the GPIO lines, closes the log file, and exits cleanly.

