#define VALVE_GPIO_LINE "gpiochip0\011"
#define NOZZLE_GPIO_LINE "gpiochip0\012"
#define SERVO_MIN_US 500
#define SERVO_MAX_US 2500
#define SERVO_DEGREE_PER_US (180.0 / (1500.0 - 500.0))
#define MOISTURE_THRESHOLD 50
#define WAIT_TIME_BETWEEN_ATTEMPTS 100000
#define WATERING_DELAY 2000000
#define CLOSE_DELAY 5000000
#define OPEN_DEGREE_US 1500
#define CLOSE_DEGREE_US 500

volatile sig_atomic_t sigint_received = 0;
volatile sig_atomic_t sigterm_received = 0;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        gpiod_set_value_cansleep(valve_fd, 0);
        gpiod_set_value_cansleep(nozzle_fd, 0);
        gpiod_close(valve_fd);
        gpiod_close(nozzle_fd);
        gpiod_cleanup();
        exit(0);
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request *valve_req, *nozzle_req;
    int valve_fd, nozzle_fd;
    int moisture = 20;
    int ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    valve_req = gpiod_chip_get_line_request_byname(chip, VALVE_GPIO_LINE);
    if (!valve_req) {
        perror("Failed to get line request for valve");
        goto cleanup;
    }

    nozzle_req = gpiod_chip_get_line_request_byname(chip, NOZZLE_GPIO_LINE);
    if (!nozzle_req) {
        perror("Failed to get line request for nozzle");
        goto cleanup;
    }

    valve_fd = gpiod_line_request_to_fd(valve_req);
    nozzle_fd = gpiod_line_request_to_fd(nozzle_req);

    while (1) {
        if (moisture < MOISTURE_THRESHOLD) {
            printf("Soil moisture is low, starting watering cycle\n");

            gpiod_set_value_cansleep(valve_fd, 1);

            for (int angle = 0; angle <= 180; angle += 45) {
                double us = SERVO_MIN_US + angle * SERVO_DEGREE_PER_US;
                ret = gpiod_set_value_cansleep(nozzle_fd, us);
                if (ret < 0) {
                    perror("Failed to set nozzle position");
                    printf("Warning: Nozzle position %d degrees failed, continuing\n", angle);
                    usleep(100000);
                    continue;
                }

                usleep(WATERING_DELAY);
                gpiod_set_value_cansleep(nozzle_fd, 0);
                usleep(5000000);
            }

            gpiod_set_value_cansleep(valve_fd, 0);
            usleep(CLOSE_DELAY);

            if (gpiod_get_value(valve_fd)) {
                fprintf(stderr, "Error: Valve failed to close\n");
                goto cleanup;
            }

            usleep(5000000);
        } else {
            printf("Soil moisture is above threshold, skipping watering cycle\n");
        }

        moisture = (moisture + 1) % 100;
        usleep(1000000);
    }

cleanup:
    gpiod_line_request_free(valve_req);
    gpiod_line_request_free(nozzle_req);
    gpiod_chip_put(chip);
    gpiod_cleanup();

    return 0;
}

