This code assumes that the SG90 servos are connected to GPIO17 and GPIO18, and it uses the `libgpiod` library. The program reads a simulated soil moisture value that cycles every second through the sequence 20, 40, 60, 80, 100, and when the moisture is below 50, it opens the valve and sprays water in five angles (0, 45, 90, 135, and 180 degrees) for 2 seconds each, holds the spray for 5 seconds, closes the valve, and waits 5 seconds before the next cycle. If the moisture is 50 or above, the watering cycle is skipped. The program also handles SIGINT and SIGTERM signals and stops both servos and cleans up resources when receiving these signals.

I'll provide a basic example using the `libgpiod` library for GPIO management and the `i2c-dev` kernel module for I2C communication. The MPU-6050 library used here is `i2c_mpu6050`.

First, install the required libraries:

```sh
sudo apt-get update
sudo apt-get install libi2c-dev libmpu6050-dev libgpiod-dev
```

Now, here's the C code:

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <mpu6050.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS 1
#define MPU6050_ADDR 0x68
#define SDA_GPIO 2
#define SCL_GPIO 3

static gpiod_line_request_data_t sda_req, scl_req;
static int i2c_fd;
static struct mpu6050_data data;
static FILE *log_file;

void i2c_error_handler(int error) {
    close(i2c_fd);
    perror("I2C error");
    exit(EXIT_FAILURE);
}

void gpio_error_handler(int error) {
    gpiod_line_release(&sda_req);
    gpiod_line_release(&scl_req);
    perror("GPIO error");
    exit(EXIT_FAILURE);
}

void sigint_handler(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    gpiod_line_release(&sda_req);
    gpiod_line_release(&scl_req);
    close(i2c_fd);
    exit(EXIT_SUCCESS);
}

int main() {
    int ret;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        i2c_error_handler(-1);
    }

    if ((ret = gpiod_chip_open("gpiochip0")) < 0) {
        perror("Failed to open GPIO chip");
        i2c_error_handler(-1);
    }

    if (gpiod_get_line_request_status(ret, SDA_GPIO) != GPIOD_LINE_REQUEST_AVAILABLE) {
        if (gpiod_line_request_enable(ret, SDA_GPIO, "SDA") < 0) {
            gpio_error_handler(-1);
        }
    }

    if (gpiod_get_line_request_status(ret, SCL_GPIO) != GPIOD_LINE_REQUEST_AVAILABLE) {
        if (gpiod_line_request_enable(ret, SCL_GPIO, "SCL") < 0) {
            gpio_error_handler(-1);
        }
    }

    sda_req = (gpiod_line_request_data_t){
        .consumer = "MPU-6050 SDA",
        .flags = GPIOD_LINE_REQUEST_INPUT,
        .active_low = 0,
    };

    scl_req = (gpiod_line_request_data_t){
        .consumer = "MPU-6050 SCL",
        .flags = GPIOD_LINE_REQUEST_INPUT,
        .active_low = 0,
    };

    if (gpiod_line_request_configure_async(ret, SDA_GPIO, &sda_req) < 0 ||
        gpiod_line_request_configure_async(ret, SCL_GPIO, &scl_req) < 0) {
        gpio_error_handler(-1);
    }

    log_file = fopen("gyro_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        i2c_error_handler(-1);
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    double timestamp = ts.tv_sec + ts.tv_nsec / 1e9;

    while (1) {
        if (mpu6050_read_raw(i2c_fd, &data) < 0) {
            i2c_error_handler(-1);
        }

        fprintf(log_file, "%f,%d,%d,%d\n", timestamp, data.gyro.x, data.gyro.y, data.gyro.z);

        clock_gettime(CLOCK_REALTIME, &ts);
        timestamp = ts.tv_sec + ts.tv_nsec / 1e9;
        usleep(100000); // 100ms delay
    }

    return EXIT_SUCCESS;
}
```

This code initializes the I2C bus, sets up the SDA and SCL GPIO lines, reads data from the MPU-6050 at 10 Hz, and appends the data to a CSV file named `gyro_log.txt`. It also handles errors and provides SIGINT and SIGTERM handlers to cleanly release resources on exit.

