        return 1;
    }

    gpiod_for_each_line(gpiochip0, &lock_req, NULL) {
        if (gpio_get_value(gpio_to_line(gpiochip0, GPIO_LOCK)) == 0) {
            lock_req.consumer = "stepper_motor_lock";
            lock_req.flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_DEBOUNCE;
            if (gpiod_line_request_dt(&lock_req) < 0) {
                perror("Failed to request lock line");
                return 1;
            }
            break;
        }
    }

    fd_unlock = gpiod_chip_open("gpiochip0");
    if (fd_unlock < 0) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    gpiod_for_each_line(gpiochip0, &unlock_req, NULL) {
        if (gpio_get_value(gpio_to_line(gpiochip0, GPIO_UNLOCK)) == 0) {
            unlock_req.consumer = "stepper_motor_unlock";
            unlock_req.flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_DEBOUNCE;
            if (gpiod_line_request_dt(&unlock_req) < 0) {
                perror("Failed to request unlock line");
                return 1;
            }
            break;
        }
    }

    fd_in1 = gpiod_chip_open("gpiochip0");
    if (fd_in1 < 0) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    gpiod_for_each_line(gpiochip0, &in1_req, NULL) {
        if (gpio_get_value(gpio_to_line(gpiochip0, GPIO_IN1)) == 0) {
            in1_req.consumer = "stepper_motor_in1";
            in1_req.flags = GPIOD_LINE_REQUEST_DIR_OUT;
            if (gpiod_line_request_dt(&in1_req) < 0) {
                perror("Failed to request IN1 line");
                return 1;
            }
            break;
        }
    }

    fd_in2 = gpiod_chip_open("gpiochip0");
    if (fd_in2 < 0) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    gpiod_for_each_line(gpiochip0, &in2_req, NULL) {
        if (gpio_get_value(gpio_to_line(gpiochip0, GPIO_IN2)) == 0) {
            in2_req.consumer = "stepper_motor_in2";
            in2_req.flags = GPIOD_LINE_REQUEST_DIR_OUT;
            if (gpiod_line_request_dt(&in2_req) < 0) {
                perror("Failed to request IN2 line");
                return 1;
            }
            break;
        }
    }

    fd_in3 = gpiod_chip_open("gpiochip0");
    if (fd_in3 < 0) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    gpiod_for_each_line(gpiochip0, &in3_req, NULL) {
        if (gpio_get_value(gpio_to_line(gpiochip0, GPIO_IN3)) == 0) {
            in3_req.consumer = "stepper_motor_in3";
            in3_req.flags = GPIOD_LINE_REQUEST_DIR_OUT;
            if (gpiod_line_request_dt(&in3_req) < 0) {
                perror("Failed to request IN3 line");
                return 1;
            }
            break;
        }
    }

    fd_in4 = gpiod_chip_open("gpiochip0");
    if (fd_in4 < 0) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    gpiod_for_each_line(gpiochip0, &in4_req, NULL) {
        if (gpio_get_value(gpio_to_line(gpiochip0, GPIO_IN4)) == 0) {
            in4_req.consumer = "stepper_motor_in4";
            in4_req.flags = GPIOD_LINE_REQUEST_DIR_OUT;
            if (gpiod_line_request_dt(&in4_req) < 0) {
                perror("Failed to request IN4 line");
                return 1;
            }
            break;
        }
    }

    while (1) {
        gpio_get_value(gpio_to_line(gpiochip0, GPIO_LOCK));
        gpio_get_value(gpio_to_line(gpiochip0, GPIO_UNLOCK));

        if (!lock_pressed && gpio_get_value(gpio_to_line(gpiochip0, GPIO_LOCK))) {
            debounce_start = monotonic_steady();
            while (gpio_get_value(gpio_to_line(gpiochip0, GPIO_LOCK)) &&
                   monotonic_steady() - debounce_start < BUTTON_DEBOUNCE_MS) {}

            if (gpio_get_value(gpio_to_line(gpiochip0, GPIO_LOCK))) {
                printf("Lock button pressed\n");
                lock_pressed = 1;
                unlock_pressed = 0;

