                gpiod_line_set_value(in2_fd, 0);
                gpiod_line_set_value(in3_fd, 0);
                gpiod_line_set_value(in4_fd, 1);
            }
        }

        if (!unlock_pressed && gpio_get_value(gpio_to_line(gpiochip0, GPIO_UNLOCK))) {
            debounce_start = monotonic_steady();
            while (gpio_get_value(gpio_to_line(gpiochip0, GPIO_UNLOCK)) &&
                   monotonic_steady() - debounce_start < BUTTON_DEBOUNCE_MS) {}

            if (gpio_get_value(gpio_to_line(gpiochip0, GPIO_UNLOCK))) {
                printf("Unlock button pressed\n");
                lock_pressed = 0;
