#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <time.h>
#include <errno.h>
#include <linux/types.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define TRIGGER_GPIO 17
#define ECHO_GPIO 18
#define LOG_FILE "distance_log.txt"
#define TIMEOUT_US 50000
#define SAMPLE_INTERVAL_MS 1000
#define MIN_DELAY_MS 60

gpiod_line_request_lines_data_v1 lines_data = {
    .lines = (struct gpiod_line_request_data_v1[]) {
        { .consumer = "HC-SR04 trigger", .direction = GPIOD_IN_ACTIVE_HIGH },
        { .consumer = "HC-SR04 echo", .direction = GPIOD_OUT_INACTIVE_LOW },
    },
    .n_lines = 2,
};

int main(void) {
    int fd_log, ret;
    struct timespec next_sample;
    struct gpiod_chip *chip;
    struct gpiod_line *trigger, *echo;
    struct timespec trigger_time, echo_time;
    double duration, distance;

    if (!(chip = gpiod_chip_open_byname("gpiochip0"))) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return 1;
    }

    if (!(ret = gpiod_chip_request_lines(chip, &lines_data, GPIOD_PROBE_ONE_TIME))) {
        fprintf(stderr, "Failed to request GPIO lines: %s\n", strerror(-ret));
        goto cleanup_chip;
    }

    trigger = lines_data.lines[0].line;
    echo = lines_data.lines[1].line;

    fd_log = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (fd_log == -1) {
        perror("Failed to open log file");
        goto cleanup_lines;
    }

    clock_gettime(CLOCK_MONOTONIC, &next_sample);
    next_sample.tv_sec += SAMPLE_INTERVAL_MS / 1000;
    next_sample.tv_nsec += (SAMPLE_INTERVAL_MS % 1000) * 1000000000;

    while (1) {
        clock_nanosleep(CLOCK_MONOTONIC, TIMER_ABSTIME, &next_sample, NULL);

        gpiod_line_set_value(trigger, 1);
        nanosleep((const struct timespec[]) { { 0, 10000 }, { 0, 0 } });
        gpiod_line_set_value(trigger, 0);

        if (gpiod_line_get_value(echo) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &trigger_time);
            while (gpiod_line_get_value(echo) == 0) {
                if (nanosleep((const struct timespec[]) { { TIMEOUT_US, 0 }, { 0, 0 } }, &echo_time) < 0) {
                    perror("Failed to sleep");
                    goto cleanup_log;
                }
                if (echo_time.tv_sec > trigger_time.tv_sec || (echo_time.tv_sec == trigger_time.tv_sec && echo_time.tv_nsec >= trigger_time.tv_nsec)) {
                    fprintf(stderr, "Timeout on echo line\n");
                    ret = -1;
                    goto cleanup_log;
                }
            }

            clock_gettime(CLOCK_MONOTONIC, &echo_time);
            duration = (echo_time.tv_sec - trigger_time.tv_sec) * 1000000000 + echo_time.tv_nsec - trigger_time.tv_nsec;
            distance = duration * 0.0343 / 2;

            if (fprintf(fd_log, "%.2f\n", distance) < 0) {
                perror("Failed to write to log file");
                ret = -1;
                goto cleanup_log;
            }
        }

        clock_gettime(CLOCK_MONOTONIC, &next_sample);
        next_sample.tv_sec += SAMPLE_INTERVAL_MS / 1000;
        next_sample.tv_nsec += (SAMPLE_INTERVAL_MS % 1000) * 1000000000;
        usleep(MIN_DELAY_MS * 1000);
    }

cleanup_log:
    close(fd_log);

cleanup_lines:
    gpiod_chip_release_lines(chip, &lines_data, GPIOD_PROBE_ONE_TIME);

cleanup_chip:
    gpiod_chip_close(chip);

    if (ret != -1)
        exit(0);
    else
        return 1;
}

void signal_handler(int signum) {
    if (fd_log != -1) {
        if (fprintf(fd_log, "-1\n") < 0) {
            perror("Failed to write to log file");
        }
        close(fd_log);
    }

    gpiod_chip_release_lines(chip, &lines_data, GPIOD_PROBE_ONE_TIME);
    gpiod_chip_close(chip);

    exit(0);
}

int main(void) {
    struct sigaction sa;

    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handlers");
        return 1;
    }

    return main();
}

