#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define VL53L1X_I2C_ADDR 0x29
#define RELAY_GPIO 18

int main() {
    int i2c_fd, ret;
    char i2c_bus = 1;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg i2c_msgs[2];
    uint8_t read_buf[6];
    gpiod_line_request_flags_t flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_FALLING | GPIOD_LINE_REQUEST_ACTIVE_LOW;
    gpiod_line_data_t relay_state;
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    // Open I2C bus
    if ((i2c_fd = open("/dev/i2c-" + std::to_string(i2c_bus), O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Initialize I2C messages
    i2c_msgs[0].addr = VL53L1X_I2C_ADDR;
    i2c_msgs[0].flags = 0;
    i2c_msgs[0].len = 1;
    i2c_msgs[0].buf = (char *) &0x01; // Start continuous measurement

    i2c_msgs[1].addr = VL53L1X_I2C_ADDR;
    i2c_msgs[1].flags = I2C_M_RD;
    i2c_msgs[1].len = 6;
    i2c_msgs[1].buf = read_buf; // Read distance data

    // Set up I2C data transfer
    i2c_data.wr_msgs = &i2c_msgs[0];
    i2c_data.nr_msgs = 1;
    i2c_data.rd_msgs = &i2c_msgs[1];
    i2c_data.nr_msgs = 1;

    // Perform I2C transfer
    if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) < 0) {
        perror("Failed to perform I2C transfer");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Open GPIO chip and line
    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Request GPIO line
    if (gpiod_line_request_dt(line, flags) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        // Read distance data
        uint16_t distance = (read_buf[0] << 8) | read_buf[1];

        // Check if the sensor is present and no error occurred
        if (distance != 0xFFFF) {
            printf("Distance: %.2f cm\n", (float)distance / 100.0);

            // Set relay state based on distance
            if (distance <= 50)
                gpiod_line_set_value(line, 1);
            else
                gpiod_line_set_value(line, 0);
        } else {
            fprintf(stderr, "Sensor error or not present\n");
        }

        // Wait 100ms
        usleep(100000);

        // Perform I2C transfer again
        if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) < 0) {
            perror("Failed to perform I2C transfer");
            break;
        }
    }

    // Release GPIO line
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    // Close I2C bus
    close(i2c_fd);

    // Handle SIGINT
    if (atexit(gpiod_line_set_value)) {
        perror("Failed to set GPIO line on SIGINT");
    }

    return 0;
}

