    i2c_msg[0].flags = 0;
    i2c_msg[0].len = 1;
    i2c_msg[0].buf = (char *)&XOUT_L;

    i2c_msg[1].addr = MPU6050_ADDR;
    i2c_msg[1].flags = I2C_M_RD;
    i2c_msg[1].len = 14;
    i2c_msg[1].buf = buf;

    ret = ioctl(i2c_fd, I2C_RDWR, i2c_msg);
    if (ret < 0) {
        perror("Failed to read data from MPU-6050");
        close(i2c_fd);
        gpiod_line_release(sda_req);
        gpiod_line_release(scl_req);
        exit(1);
    }

    signed char x = (buf[11] << 8) | buf[10];
    signed char y = (buf[13] << 8) | buf[12];
    signed char z = (buf[15] << 8) | buf[14];

    printf("X: %d, Y: %d, Z: %d\n", x, y, z);

    gpiod_line_release(sda_req);
    gpiod_line_release(scl_req);
    close(i2c_fd);

