    signal(SIGINT, [](int sig) {
        printf("\nInterrupted, cleaning up...\n");
        gpiod_line_release(sda_req);
        gpiod_line_release(scl_req);
        close(i2c_fd);
        exit(0);
    });

    signal(SIGTERM, [](int sig) {
        printf("\nTerminated, cleaning up...\n");
        gpiod_line_release(sda_req);
        gpiod_line_release(scl_req);
        close(i2c_fd);
        exit(0);
    });

    // Main loop to continuously read and log data
    for (;;) {
        ret = ioctl(i2c_fd, I2C_RDWR, i2c_msg);
        if (ret < 0) {
            perror("Failed to read data from MPU-6050");
            continue;
        }

        x = (buf[11] << 8) | buf[10];
        y = (buf[13] << 8) | buf[12];
        z = (buf[15] << 8) | buf[14];

        printf("X: %d, Y: %d, Z: %d\n", x, y, z);
        sleep(1);
    }

    return 0;
}

