#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <time.h>
#include <errno.h>
#include <linux/types.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define RELAY_COUNT 4
#define RELAY_PIN_MAP {17, 18, 27, 22}
#define DELAY_BETWEEN_RELAYS 1
#define DELAY_ON_RELAY 5
#define DELAY_BETWEEN_CYCLES 86400

static int gpio_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *lines[RELAY_COUNT];

void log_time(const char *message) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char time_str[32];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm);
    printf("%s: %s\n", time_str, message);
    FILE *log_file = fopen("watering_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s\n", time_str);
        fclose(log_file);
    }
}

void gpio_init() {
    gpio_fd = gpiod_open_named_chip(GPIO_CHIP_NAME, GPIOD_OPEN_FLAG_RAW_GPIO);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    chip = gpiod_chip_get_by_fd(gpio_fd);
    if (!chip) {
        perror("Failed to get GPIO chip");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < RELAY_COUNT; ++i) {
        int pin = RELAY_PIN_MAP[i];
        lines[i] = gpiod_chip_get_line(chip, pin);
        if (!lines[i]) {
            perror("Failed to get GPIO line");
            exit(EXIT_FAILURE);
        }

        gpiod_line_request_output(lines[i], GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
        gpiod_line_set_value(lines[i], 1);
    }
}

void gpio_cleanup() {
    for (size_t i = 0; i < RELAY_COUNT; ++i) {
        gpiod_line_release(lines[i]);
    }

    gpiod_chip_close(chip);
    close(gpio_fd);
}

void signal_handler(int signum) {
    gpio_cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpio_init();
    log_time("Initialization complete");

    time_t next_cycle = time(NULL);
    next_cycle += DELAY_BETWEEN_CYCLES;

    while (1) {
        time_t now = time(NULL);
        if (now >= next_cycle) {
            for (size_t i = 0; i < RELAY_COUNT; ++i) {
                gpiod_line_set_value(lines[i], 0);
                sleep(DELAY_BETWEEN_RELAYS);
                gpiod_line_set_value(lines[i], 1);
                sleep(DELAY_ON_RELAY);
            }

            next_cycle += DELAY_BETWEEN_CYCLES;
            log_time("Cycle started");
        }

        sleep(60);
    }

    gpio_cleanup();
    return EXIT_SUCCESS;
}

