This code uses the libgpiod library and sets up the GPIO lines as outputs with active-low semantics, initializes them to HIGH (inactive), and starts a main loop that activates each relay in turn for 5 seconds, repeating the sequence every 24 hours. The program logs the start time of each full cycle to a file named `watering_log.txt`. The code handles errors and releases all GPIO lines, closes the chip, and exits cleanly when receiving SIGINT or SIGTERM signals.

code:
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <time.h>
#include <linux/types.h>
#include <linux/spi/spidev.h>
#include <sys/mman.h>
#include <libgpiod.h>

#define GPIO_BASE "/dev/gpiochip"
#define NUM_RELAYS 4
#define PWM_FREQ 1000
#define DUTY_CYCLE_STEP 25
#define TOTAL_DUTY_CYCLE 255
#define LOG_FILE "smart_lighting.log"

struct gpiod_chip *gpiod_chip;
struct gpiod_line *lines[NUM_RELAYS];

void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char log_line[100];
    strftime(log_line, sizeof(log_line), "%Y-%m-%d %H:%M:%S: %s\n", tm_now, message);
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fputs(log_line, log_file);
        fclose(log_file);
    }
}

int init_gpio(void) {
    int ret;
    gpiod_chip = gpiod_chip_open(GPIO_BASE);
    if (!gpiod_chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; ++i) {
        lines[i] = gpiod_chip_get_line(gpiod_chip, i);
        if (!lines[i]) {
            perror("Failed to get GPIO line");
            return -1;
        }

        ret = gpiod_line_request_output_flags(lines[i], GPIOD_LINE_REQUEST_DIRECTION_OUT | GPIOD_LINE_REQUEST_ACTIVE_LOW);
        if (ret < 0) {
            perror("Failed to request output for GPIO line");
            return -1;
        }
    }

    return 0;
}

int init_pwm(void) {
    int ret;
    int pwm_fd = open("/dev/mem", O_RDWR | O_SYNC);
    if (pwm_fd < 0) {
        perror("Failed to open /dev/mem");
        return -1;
    }

    void *pwm_base = mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_SHARED, pwm_fd, 0x3F000000);
    if (pwm_base == MAP_FAILED) {
        perror("Failed to mmap /dev/mem");
        close(pwm_fd);
        return -1;
    }

    uint32_t *pwm_reg = (uint32_t *) (pwm_base + 0x00);
    uint32_t *pwm_ctrl = (uint32_t *) (pwm_base + 0x04);
    uint32_t *pwm_div = (uint32_t *) (pwm_base + 0x08);
    uint32_t *pwm_ldr = (uint32_t *) (pwm_base + 0x0C);

    *pwm_reg = 0;
    *pwm_ctrl = 0;
    *pwm_div = (PWM_FREQ * (SYS_CLK_FREQ / 1000)) - 1;

    for (int i = 0; i < NUM_RELAYS; ++i) {
        ret = ioctl(pwm_fd, TIOCGPUID, &i);
        if (ret < 0) {
            perror("Failed to get PWM channel");
            munmap(pwm_base, 4096);
            close(pwm_fd);
            return -1;
        }

        *pwm_reg = (1 << i);
        *pwm_ldr = TOTAL_DUTY_CYCLE;
    }

    *pwm_ctrl |= (1 << 0);

    munmap(pwm_base, 4096);
    close(pwm_fd);

    return 0;
}

void cleanup(void) {
    for (int i = 0; i < NUM_RELAYS; ++i) {
        gpiod_line_release(lines[i]);
    }

    gpiod_chip_close(gpiod_chip);
}

void handle_signal(int sig) {
    cleanup();
    exit(0);
}

int main(void) {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_gpio() < 0) {
        return 1;
    }

    if (init_pwm() < 0) {
        cleanup();
        return 1;
    }

    for (int duty_cycle = 0; duty_cycle <= TOTAL_DUTY_CYCLE; duty_cycle += DUTY_CYCLE_STEP) {
        for (int i = 0; i < NUM_RELAYS; ++i) {
            gpiod_line_set_value(lines[i], duty_cycle <= TOTAL_DUTY_CYCLE - DUTY_CYCLE_STEP);
        }

        sleep(1);
        log_event("Duty cycle updated");
    }

    cleanup();
    return 0;
}

