#include <sys/mman.h>
#include <gpiod.h>

#define MPU6050_ADDR 0x68
#define SDA_GPIO 2
#define SCL_GPIO 3
#define LED_GPIO 17
#define BUFFER_SIZE 100
#define SAMPLE_RATE 20
#define THRESHOLD 250

struct i2c_data {
    int fd;
    char *map_base;
};

int i2c_init(struct i2c_data *data) {
    const char *bus = "/dev/i2c-1";
    if ((data->fd = open(bus, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(data->fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire I2C address");
        close(data->fd);
        return -1;
    }

    return 0;
}

int read_accel(struct i2c_data *data, short *accel_data) {
    char buf[14];
    int ret;

    ret = write(data->fd, 0x3B, 1);
    if (ret != 1) {
        perror("Failed to write to I2C");
        return -1;
    }

    ret = read(data->fd, buf, 14);
    if (ret != 14) {
        perror("Failed to read from I2C");
        return -1;
    }

    accel_data[0] = (short)(((buf[0] << 8) | buf[1]) * 131.0 / 1024);
    accel_data[1] = (short)(((buf[2] << 8) | buf[3]) * 131.0 / 1024);
    accel_data[2] = (short)(((buf[4] << 8) | buf[5]) * 131.0 / 1024);

    return 0;
}

void gpio_setup(gpiod_line_request_lines_t *lines, int gpio) {
    gpiod_line_request_line(lines, gpio, GPIOD_LINE_REQUEST_DIRECTION_OUT, "led");
    gpiod_line_set_value(lines, gpio, 1);
}

void gpio_cleanup(gpiod_line_request_lines_t *lines) {
    gpiod_line_release_request(lines);
}

void signal_handler(int sig) {
    printf("Received signal %d, cleaning up and exiting...\n", sig);
    gpio_cleanup(lines);
    close(i2c_data.fd);
    exit(0);
}

int main() {
    struct i2c_data i2c_data;
    struct timespec ts;
    short accel_data[3];
    gpiod_line_request_lines_t lines;
    int ret, i, j;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (i2c_init(&i2c_data)) {
        perror("Failed to initialize I2C");
        return -1;
    }

    i2c_data.map_base = mmap(NULL, sysconf(_SC_PAGESIZE), PROT_READ | PROT_WRITE, MAP_SHARED | MAP_PRIVATE, i2c_data.fd, 0);
    if (i2c_data.map_base == MAP_FAILED) {
        perror("Failed to mmap I2C device");
        close(i2c_data.fd);
        return -1;
    }

    gpiod_line_request_configure(&lines, LED_GPIO, GPIOD_LINE_ACTIVE_HIGH | GPIOD_LINE_REQUEST_INPUT);
    gpio_setup(&lines, LED_GPIO);

    clock_gettime(CLOCK_MONOTONIC, &ts);
    int buffer_index = 0;

    while (1) {
        if (read_accel(&i2c_data, accel_data) < 0) {
            if (i < 3) {
                printf("Failed to read accelerometer data, retrying...\n");
                continue;
            } else {
                perror("Failed to read accelerometer data after retries");
                goto cleanup;
            }
        }

        for (i = 0; i < 3; i++) {
            if (fabs(accel_data[i]) > THRESHOLD) {
                gpiod_line_set_value(&lines, LED_GPIO, 1);
                break;
            }
        }

        if (i == 3) {
            gpiod_line_set_value(&lines, LED_GPIO, 0);
        }

        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        ts.tv_sec += SAMPLE_RATE / 1000;
        ts.tv_nsec = (SAMPLE_RATE % 1000) * 1000000000L / 1000;
        clock_nanosleep(CLOCK_MONOTONIC, TIMER_ABSTIME, &ts, NULL);
    }

cleanup:
    gpio_cleanup(&lines);
    munmap(i2c_data.map_base, sysconf(_SC_PAGESIZE));
    close(i2c_data.fd);

    return 0;
}

