#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <time.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_BUS 0
#define SPI_DEVICE 0
#define GPIO_LINE 8
#define CHIP_SELECT_LOW 0
#define CHIP_SELECT_HIGH 1
#define SPI_MODE 0
#define SPI_DATA_BITS 8
#define SPI_MAX_RETRIES 3
#define TIMESTAMP_LEN 29
#define BUFFER_SIZE 14

struct mpu_9250_reg {
    uint8_t addr;
    uint8_t len;
};

struct mpu_9250_reg gyro_reg[] = {
    {0x3B, 6}, // GYRO_XOUT_H
    {0x3D, 6}, // GYRO_YOUT_H
    {0x3F, 6}, // GYRO_ZOUT_H
};

int spi_init(void) {
    int spi_fd = open("/dev/spidev" SPI_BUS "." SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer transfers[ARRAY_SIZE(gyro_reg)];
    for (size_t i = 0; i < ARRAY_SIZE(gyro_reg); ++i) {
        transfers[i].tx_buf = &gyro_reg[i].addr;
        transfers[i].rx_buf = malloc(gyro_reg[i].len);
        transfers[i].len = gyro_reg[i].len;
        transfers[i].speed_hz = 1000000;
        transfers[i].bits_per_word = SPI_DATA_BITS;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfers) < 1) {
        perror("Failed to configure SPI transfer");
        return -1;
    }

    gpiod_line_request_dt(0, "gpio-cs", GPIO_LINE, GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW);
    gpiod_line_set_value(gpiochip_get_line(0, GPIO_LINE), CHIP_SELECT_LOW);

    return spi_fd;
}

void spi_cleanup(int spi_fd) {
    gpiod_line_set_value(gpiochip_get_line(0, GPIO_LINE), CHIP_SELECT_HIGH);
    gpiod_line_release(gpiochip_get_line(0, GPIO_LINE));
    close(spi_fd);
}

int spi_read(int spi_fd, uint8_t *buffer, size_t len, int retries) {
    int attempts = 0;
    while (attempts < retries) {
        gpiod_line_set_value(gpiochip_get_line(0, GPIO_LINE), CHIP_SELECT_LOW);
        if (write(spi_fd, &buffer[0], len) != len) {
            perror("Failed to write to SPI device");
            attempts++;
            continue;
        }

        usleep(10000); // Wait 10ms for response

        if (read(spi_fd, &buffer[0], len) != len) {
            perror("Failed to read from SPI device");
            attempts++;
            continue;
        }

        gpiod_line_set_value(gpiochip_get_line(0, GPIO_LINE), CHIP_SELECT_HIGH);
        return 0;
    }

    perror("Failed to communicate with SPI device");
    return -1;
}

void log_gyro_data(const char *timestamp, float x_rate, float y_rate, float z_rate) {
    FILE *log_file = fopen("gyro_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    char line[BUFFER_SIZE];
    snprintf(line, BUFFER_SIZE, "%s,%f,%f,%f\n", timestamp, x_rate, y_rate, z_rate);
    fputs(line, log_file);
    fclose(log_file);
}

void handle_signal(int signum) {
    spi_cleanup(spi_fd);
    exit(0);
}

int main(void) {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    spi_fd = spi_init();
    if (spi_fd < 0) {
        return 1;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[TIMESTAMP_LEN];
    snprintf(timestamp, TIMESTAMP_LEN, "%ld.%09ld", (long)ts.tv_sec, (long)ts.tv_nsec);

    while (1) {
        if (spi_read(spi_fd, gyro_reg[0].addr, gyro_reg[0].len, SPI_MAX_RETRIES) < 0) {
            perror("Failed to read gyro data");
            continue;
        }

        float x_rate = ((int16_t)((gyro_reg[0].rx_buf[0] << 8) | gyro_reg[0].rx_buf[1]) / 131.0);
        float y_rate = ((int16_t)((gyro_reg[1].rx_buf[0] << 8) | gyro_reg[1].rx_buf[1]) / 131.0);
        float z_rate = ((int16_t)((gyro_reg[2].rx_buf[0] << 8) | gyro_reg[2].rx_buf[1]) / 131.0);

        clock_gettime(CLOCK_REALTIME, &ts);
        snprintf(timestamp, TIMESTAMP_LEN, "%ld.%09ld", (long)ts.tv_sec, (long)ts.tv_nsec);
        log_gyro_data(timestamp, x_rate, y_rate, z_rate);
    }

    spi_cleanup(spi_fd);
    return 0;
}

