    uint32_t timestamp;
    int16_t x, y, z;
};

struct spi_device *spi_dev;
struct gpio_chip *gpio_chip_led;
struct gyro_data buffer[BUFFER_SIZE];
volatile size_t buffer_head = 0;
volatile size_t buffer_tail = 0;

int spi_init() {
    int ret;
    char spi_dev_path[32];
    snprintf(spi_dev_path, sizeof(spi_dev_path), "/dev/spidev%d.%d", SPI_BUS, SPI_DEVICE);

    spi_dev = spi_open(spi_dev_path, 0);
    if (spi_dev < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    ret = spi_setup(spi_dev, 3900000);
    if (ret < 0) {
        perror("Failed to configure SPI");
        goto cleanup;
    }

    ret = spi_set_mode(spi_dev, SPI_MODE_0);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        goto cleanup;
    }

    ret = spi_set_bits_per_word(spi_dev, 16);
    if (ret < 0) {
        perror("Failed to set SPI bits per word");
        goto cleanup;
    }

    return 0;

cleanup:
    spi_close(spi_dev);
    return -1;
}

int gyro_read() {
    int ret;
    uint8_t data[6];
    ret = spi_xfer(spi_dev, data, 6);
    if (ret != 6) {
        perror("Failed to read gyro data");
        return -1;
    }

    buffer[buffer_head].timestamp = (uint32_t)(rdtsc());
    buffer[buffer_head].x = (int16_t)(data[0] << 8 | data[1]);
    buffer[buffer_head].y = (int16_t)(data[2] << 8 | data[3]);
    buffer[buffer_head].z = (int16_t)(data[4] << 8 | data[5]);

    buffer_head = (buffer_head + 1) % BUFFER_SIZE;
    return 0;
}

