        }

        if (buffer_head == buffer_tail) {
            print_buffer();
        }
    }

cleanup:
    gpiod_chip_release_line(gpio_chip_led, GPIO_LED);
    gpiod_chip_close(gpio_chip_led);
    spi_close(spi_dev);
