#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define TEMP_OUT_H 0x41
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47
#define LED_GPIO 21

static gpiod_line_request_linestate_t led_state = GPIOD_LINE_REQUEST_ACTIVE_LOW;
static gpiod_line_request *led_request;

void sigint_handler(int signum) {
    gpiod_line_set_value(led_request, 0);
    gpiod_line_release(led_request);
    close(i2c_fd);
    exit(0);
}

int main() {
    int i2c_fd;
    struct i2c_msg msgs[2];
    char buf[14];
    ssize_t bytes_read;
    struct timespec ts;
    double roll, pitch, temp, gyro_x, gyro_y, gyro_z;
    time_t rawtime;
    struct tm *time_info;
    char time_str[20];
    char log_str[80];

    signal(SIGINT, sigint_handler);

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to talk to MPU-6050");
        exit(1);
    }

    if (gpiod_chip_open_byname("gpiochip0") < 0) {
        perror("Failed to open GPIO chip");
        exit(1);
    }

    if ((led_request = gpiod_chip_get_line_request_byname(gpiod_chip_get_fd(NULL), "gpiochip0", LED_GPIO)) == NULL) {
        perror("Failed to get LED line request");
        exit(1);
    }

    if (gpiod_line_request_enable(led_request, led_state) < 0) {
        perror("Failed to enable LED line request");
        exit(1);
    }

    msgs[0].addr = MPU6050_ADDR;
    msgs[0].flags = 0;
    msgs[0].len = 14;
    msgs[0].buf = buf;

    msgs[1].addr = MPU6050_ADDR;
    msgs[1].flags = I2C_M_RD;
    msgs[1].len = 14;
    msgs[1].buf = buf + 6;

    while (1) {
        if (i2c_master_send(i2c_fd, msgs, 2) != 2) {
            perror("Failed to send I2C messages");
            continue;
        }

        if (i2c_master_recv(i2c_fd, msgs, 2) != 2) {
            perror("Failed to receive I2C messages");
            continue;
        }

        roll = atan2(buf[0] * 16.384f, sqrt(pow(buf[1] * 16.384f, 2) + pow(buf[2] * 16.384f, 2)) * 5000.0f) * 180.0f / M_PI;
        pitch = atan2(-buf[4] * 16.384f, sqrt(pow(buf[5] * 16.384f, 2) + pow(buf[6] * 16.384f, 2)) * 5000.0f) * 180.0f / M_PI;

        if (fabs(roll) > 45.0f || fabs(pitch) > 45.0f) {
            gpiod_line_set_value(led_request, 1);
        } else {
            gpiod_line_set_value(led_request, 0);
        }

        time(&rawtime);
        time_info = localtime(&rawtime);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", time_info);
        snprintf(log_str, sizeof(log_str), "%s,%f,%f\n", time_str, roll, pitch);

        FILE *log_file = fopen("tilt_log.txt", "a");
        if (log_file) {
            fputs(log_str, log_file);
            fclose(log_file);
        }

        ts.tv_sec = 100;
        ts.tv_nsec = 0;
        nanosleep(&ts, NULL);
    }

    gpiod_line_release(led_request);
    close(i2c_fd);
    gpiod_chip_close(gpiod_chip_get_fd(NULL));

    return 0;
}

