#define LED_GPIO 17

static int i2c_file;
static gpio_handle_t led_gpio;
static struct timespec read_interval = {0, 100 * 1000 * 1000}; // 100ms

void i2c_read_si1145(void) {
    char buf[2];
    int ret;

    ret = write(i2c_file, (char*)&Si1145_AmbientLight, 1);
    if (ret != 1) {
        usleep(10000);
        ret = write(i2c_file, (char*)&Si1145_AmbientLight, 1);
        if (ret != 1) {
            usleep(10000);
            ret = write(i2c_file, (char*)&Si1145_AmbientLight, 1);
        }
    }
    if (ret != 1) {
        perror("Failed to write to Si1145");
        return;
    }

    ret = read(i2c_file, buf, 2);
    if (ret != 2) {
        perror("Failed to read from Si1145");
        return;
    }

    uint16_t ambient_light = (buf[0] << 8) | buf[1];
    uint8_t proximity = buf[2];

    gpiod_set_value_cansleep(led_gpio, proximity > 100);

    char log_str[100];
    struct tm tm;
    time_t rawtime;
    time(&rawtime);
    localtime_r(&rawtime, &tm);
    strftime(log_str, sizeof(log_str), "%Y-%m-%d %H:%M:%S,AmbientLight:%04X,Proximity:%02X\n", &tm, ambient_light, proximity);

    FILE *log_file = fopen("biometric_log.txt", "a");
    if (log_file) {
        fputs(log_str, log_file);
        fclose(log_file);
    }
}

