    close(i2c_file);
    fclose(log_file);
    gpiod_set_value_cansleep(led_gpio, 0);
    gpiod_close(led_gpio);
    exit(0);
}

int main(void) {
    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file < 0) {
        perror("Failed to open I2C device");
        exit(1);
    }

    if (ioctl(i2c_file, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("Failed to acquire bus access");
        exit(1);
    }

    led_gpio = gpiod_chip_open_named_line("gpiochip0", "gpio17");
    if (IS_ERR(led_gpio)) {
        perror("Failed to open GPIO line");
        exit(1);
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        nanosleep(&read_interval, NULL);
        i2c_read_si1145();
    }

    close(i2c_file);
    fclose(log_file);
    gpiod_set_value_cansleep(led_gpio, 0);
    gpiod_close(led_gpio);

