#define SPI_BUS 0
#define SPI_DEVICE 0
#define GPIO_LINE_CE0 8
#define X_REG 0x29
#define Y_REG 0x2B
#define SAMPLE_RATE 100
#define DELAY_US 10000
#define MAX_RETRIES 3

static gpiod_line_request_lines_data_t gpio_data = { .lines = { { .flags = GPIOD_LINE_REQUEST_INPUT, .consumer = "Gyro Sample" } } };
static int spi_fd, gpio_fd;
static struct spi_ioc_transfer transfers[2];
static FILE *csv_file;

void signal_handler(int signum) {
    close(spi_fd);
    fclose(csv_file);
    gpiod_line_release_request(gpio_data.lines[0].request);
    exit(0);
}

int init_gpio() {
    gpio_fd = gpiod_open_array_with_consumer_flags(0, &gpio_data, GPIOD_OPEN_FLAG_RETRY_PULSE_LOW);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO line");
        return -1;
    }

    gpiod_line_set_value_cansleep(gpio_fd, 1, 1);
    usleep(100000);
    gpiod_line_set_value_cansleep(gpio_fd, 1, 0);

    return 0;
}

int init_spi() {
    spi_fd = open("/dev/spidev" SPI_BUS, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer init_xfer = {
        .tx_buf = (unsigned char[]){0x00, 0x00},
        .len = 2,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .cs_change = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &init_xfer) < 1) {
        perror("Failed to configure SPI");
        return -1;
    }

    transfers[0].tx_buf = (unsigned char[]){X_REG | 0x80, 0x00};
    transfers[1].tx_buf = (unsigned char[]){Y_REG | 0x80, 0x00};
    transfers[0].len = 2;
    transfers[1].len = 2;

    return 0;
}

int read_gyro() {
    int retries = 0;
    do {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(2), transfers) < 2) {
            perror("Failed to read gyro data");
            return -1;
        }

        uint16_t x_rate = (transfers[0].rx_buf[1] << 8) | transfers[0].rx_buf[0];
        uint16_t y_rate = (transfers[1].rx_buf[1] << 8) | transfers[1].rx_buf[0];

        return x_rate | (y_rate << 16);
    } while (++retries < MAX_RETRIES);

    perror("Failed to read gyro data after retries");
    return -1;
}

int main() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    uint64_t last_time = ts.tv_sec * 1000000 + ts.tv_nsec / 1000;

    signal(SIGINT, signal_handler);

    if (init_gpio() < 0 || init_spi() < 0) {
        perror("Failed to initialize GPIO or SPI");
        return -1;
    }

    csv_file = fopen("gyro_data.csv", "w");
    if (!csv_file) {
        perror("Failed to open CSV file");
        return -1;
    }

    fprintf(csv_file, "Time(us),X_Rate,Y_Rate\n");

    while (1) {
        int gyro_data = read_gyro();
        if (gyro_data < 0) {
            perror("Failed to read gyro data");
            break;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        uint64_t current_time = ts.tv_sec * 1000000 + ts.tv_nsec / 1000;
        double elapsed = (current_time - last_time) / 1000.0;

        if (elapsed > 1.0 / SAMPLE_RATE) {
            fprintf(csv_file, "%llu,%d,%d\n", current_time, (int)(gyro_data >> 16), (int)(gyro_data & 0xFFFF));
            last_time = current_time;
        }

        usleep(DELAY_US - (elapsed * 1000000));
    }

    fclose(csv_file);
    signal_handler(SIGINT);

    return 0;
