#define SENSOR1_GPIO 23
#define SENSOR2_GPIO 24
#define ALERT_GPIO 17
#define LOG_FILE "seismic_events.txt"
#define EVENT_DURATION_MS 500
#define ALERT_DURATION_MS 2000
#define MAX_EVENT_LOG_SIZE 256

static gpiod_line_request_lines_data_t lines_data[] = {
    { .offset = SENSOR1_GPIO, .flags = GPIOD_LINE_REQUEST_INPUT },
    { .offset = SENSOR2_GPIO, .flags = GPIOD_LINE_REQUEST_INPUT },
};

static gpiod_line_event_cb_t sensor_cb = [](struct gpiod_line_event *ev) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_string[MAX_EVENT_LOG_SIZE];

    rawtime = time(NULL);
    timeinfo = localtime(&rawtime);
    strftime(time_string, sizeof(time_string), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (ev->line->number == SENSOR1_GPIO || ev->line->number == SENSOR2_GPIO) {
        FILE *log_file = fopen(LOG_FILE, "a");
        if (log_file) {
            fprintf(log_file, "%s - Seismic event detected!\n", time_string);
            fclose(log_file);
        }

        if (ev->line->number == SENSOR1_GPIO && gpiod_line_get_value(ev->line) && gpiod_line_get_value(lines_data[1].line)) {
            gpiod_line_set_value(ALERT_GPIO, 1);
            usleep(ALERT_DURATION_MS * 1000);
            gpiod_line_set_value(ALERT_GPIO, 0);
        }
    }
};

int main() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line_request *request;
    struct gpiod_line_event_cb_data cb_data = { .user_data = NULL };

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    request = gpiod_chip_request_lines(chip, 2, lines_data, GPIOD_LINE_REQUEST_INPUT);
    if (!request) {
        perror("Failed to request lines");
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_event_callback_add(request->lines[0], sensor_cb, &cb_data);
    if (ret < 0) {
        perror("Failed to add sensor1 callback");
        gpiod_line_release(request->lines[0]);
        gpiod_line_release(request->lines[1]);
        gpiod_chip_release_request(request);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_event_callback_add(request->lines[1], sensor_cb, &cb_data);
    if (ret < 0) {
        perror("Failed to add sensor2 callback");
        gpiod_line_release(request->lines[0]);
        gpiod_line_release(request->lines[1]);
        gpiod_chip_release_request(request);
        gpiod_chip_close(chip);
        return 1;
    }

    signal(SIGINT, [](int sig) {
        gpiod_line_event_callback_remove(request->lines[0], sensor_cb, NULL);
        gpiod_line_event_callback_remove(request->lines[1], sensor_cb, NULL);
        gpiod_line_release(request->lines[0]);
        gpiod_line_release(request->lines[1]);
        gpiod_chip_release_request(request);
        gpiod_chip_close(chip);
        exit(0);
    });

    signal(SIGTERM, [](int sig) {
        gpiod_line_event_callback_remove(request->lines[0], sensor_cb, NULL);
        gpiod_line_event_callback_remove(request->lines[1], sensor_cb, NULL);
        gpiod_line_release(request->lines[0]);
        gpiod_line_release(request->lines[1]);
        gpiod_chip_release_request(request);
        gpiod_chip_close(chip);
        exit(0);
    });

    while (1) {
        usleep(100000);
    }

    return 0;
}

