#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <time.h>
#include <signal.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define ADXRS290_CS_GPIO 8
#define ADXRS290_SCLK_GPIO 11
#define ADXRS290_MOSI_GPIO 10
#define ADXRS290_MISO_GPIO 9
#define WARNING_LED_GPIO 17
#define BUFFER_SIZE 100
#define THRESHOLD 20.0

struct entry {
    double timestamp;
    int16_t data;
};

struct buffer {
    struct entry buffer[BUFFER_SIZE];
    size_t head;
    size_t tail;
};

struct gpiod_line *cs_line, *led_line;
struct spidev *spidev;

struct buffer gyro_buffer;

void spi_xfer(const uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    ssize_t ret;

    ret = spidev_write(spidev, tx_buf, len);
    if (ret != len) {
        perror("spidev_write");
        exit(EXIT_FAILURE);
    }

    ret = spidev_read(spidev, rx_buf, len);
    if (ret != len) {
        perror("spidev_read");
        exit(EXIT_FAILURE);
    }
}

double read_gyro_x() {
    uint8_t addr = 0x27;
    uint8_t data[2];

    addr |= (1 << 7);

    spi_xfer(&addr, data, sizeof(data));

    return (data[1] | (data[0] << 8)) / 16.0;
}

void init_gpio() {
    if (gpiod_claim_line(cs_line, "cs") < 0) {
        perror("gpiod_claim_line");
        exit(EXIT_FAILURE);
    }

    if (gpiod_set_value_cansleep(cs_line, 0) < 0) {
        perror("gpiod_set_value_cansleep");
        exit(EXIT_FAILURE);
    }

    if (gpiod_claim_line(led_line, "led") < 0) {
        perror("gpiod_claim_line");
        exit(EXIT_FAILURE);
    }

    if (gpiod_set_value_cansleep(led_line, 0) < 0) {
        perror("gpiod_set_value_cansleep");
        exit(EXIT_FAILURE);
    }
}

void init_spi() {
    if ((spidev = spidev_open(SPI_DEV, 0)) < 0) {
        perror("spidev_open");
        exit(EXIT_FAILURE);
    }

    if (spidev_setup(spidev, SPI_SPEED, SPI_MODE) < 0) {
        perror("spidev_setup");
        exit(EXIT_FAILURE);
    }
}

void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        gpiod_release_line(cs_line);
        gpiod_release_line(led_line);
        spidev_close(spidev);
        exit(EXIT_SUCCESS);
    }
}

int main() {
    struct timespec ts;
    double last_rate = 0.0;
    double rate = 0.0;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    cs_line = gpiod_get_line_byname("gpiochip0", ADXRS290_CS_GPIO);
    if (!cs_line) {
        perror("gpiod_get_line_byname");
        exit(EXIT_FAILURE);
    }

    led_line = gpiod_get_line_byname("gpiochip0", WARNING_LED_GPIO);
    if (!led_line) {
        perror("gpiod_get_line_byname");
        exit(EXIT_FAILURE);
    }

    init_spi();

    gyro_buffer.head = 0;
    gyro_buffer.tail = 0;

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);

        rate = read_gyro_x();

        if (gyro_buffer.head != gyro_buffer.tail) {
            gyro_buffer.buffer[gyro_buffer.head].timestamp = ts.tv_sec + ts.tv_nsec * 1e-9;
            gyro_buffer.buffer[gyro_buffer.head].data = rate;
            gyro_buffer.head = (gyro_buffer.head + 1) % BUFFER_SIZE;
        }

        if (rate > THRESHOLD && rate > last_rate) {
            if (gpiod_get_value(led_line) == 0) {
                if (gpiod_set_value_cansleep(led_line, 1) < 0) {
                    perror("gpiod_set_value_cansleep");
                    exit(EXIT_FAILURE);
                }
            }
        } else if (rate < last_rate && gpiod_get_value(led_line) == 1) {
            if (gpiod_set_value_cansleep(led_line, 0) < 0) {
                perror("gpiod_set_value_cansleep");
                exit(EXIT_FAILURE);
            }
        }

        last_rate = rate;

        usleep(100000);
    }

    return 0;
}

