    if (total_duration < 1 || total_duration > 3600) {
        fprintf(stderr, "Invalid total duration. Must be between 1 and 3600 seconds.\n");
        return 1;
    }

    struct timespec delay;
    struct gpiod_chip *gpio;
    int ret;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    gpio = gpiod_chip_open_byname("gpiochip0");
    if (IS_ERR(gpio)) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    int pins[] = {GPIO_17, GPIO_18, GPIO_27};
    for (int i = 0; i < 3; ++i) {
        int gpio_line = pins[i];
        struct gpiod_line *line = gpiod_get_line_byname(gpio, gpio_line);
        if (IS_ERR(line)) {
            perror("Failed to get line");
            gpiod_chip_put(gpio);
            return 1;
        }

        ret = gpiod_direction_output(line, 1);
        if (ret < 0) {
            perror("Failed to set direction");
            gpiod_line_put(line);
            gpiod_chip_put(gpio);
            return 1;
        }

        gpiod_set_value(line, 1);
        printf("Lamp %d initialized and turned on.\n", i + 1);
        gpiod_line_put(line);
    }

    int duty_cycle_steps = 256;
    int fade_duration = total_duration / 3 / duty_cycle_steps;

    for (int i = 0; i < 3; ++i) {
        int gpio_line = pins[i];
        struct gpiod_line *line = gpiod_get_line_byname(gpio, gpio_line);
        if (IS_ERR(line)) {
            perror("Failed to get line");
            gpiod_chip_put(gpio);
            return 1;
        }

        for (int j = duty_cycle_steps; j > 0; --j) {
            int duty_cycle = 255 - j;
            ret = gpiod_set_value_cansleep(line, duty_cycle * 1000 / 255);
            if (ret < 0) {
                perror("Failed to set duty cycle");
                gpiod_line_put(line);
                gpiod_chip_put(gpio);
                return 1;
            }

            nanosleep(&delay, NULL);
            delay.tv_sec = fade_duration;
            delay.tv_nsec = 0;

            printf("Lamp %d is fading... (%d%%)\n", i + 1, duty_cycle);
        }

        gpiod_line_put(line);
    }

    printf("All lamps turned off.\n");
    gpiod_chip_put(gpio);

    return 0;
}

