This program initializes the GPIO pins, sets them as output, and turns them on. It then fades each lamp sequentially by adjusting the PWM duty cycle and waiting for the specified duration. The program handles SIGINT and SIGTERM signals gracefully by turning off all lamps and releasing any allocated resources.

code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/types.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define RELAY_GPIO_BASE 17
#define NUM_RELAYS 4

static gpiod_line_request_lines_data_t lines_data[] = {
    { .flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW },
    { .flags = GPIOD_LINE_REQUEST_OUTPUT },
    { .flags = GPIOD_LINE_REQUEST_OUTPUT },
    { .flags = GPIOD_LINE_REQUEST_OUTPUT },
};

static gpiod_line_array_t *relay_lines;

void signal_handler(int signum) {
    if (relay_lines) {
        gpiod_line_array_release(relay_lines);
        relay_lines = NULL;
    }
    exit(0);
}

int main() {
    struct sigaction sa = { .sa_handler = signal_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    int ret;
    gpiod_controller_spidev_data_t controller_data = {
        .bus = "spidev",
        .chip_select_gpio = -1,
        .max_speed_hz = 1000000,
    };
    gpiod_controller_spidev_open_flags_t flags = GPIOD_CONTROLLER_OPEN_FLAG_NONBLOCK;
    gpiod_controller *controller;

    if ((ret = gpiod_controller_open_spidev(&controller_data, &flags, &controller)) < 0) {
        perror("gpiod_controller_open_spidev");
        return 1;
    }

    int gpio_base = RELAY_GPIO_BASE;
    int gpio_count = NUM_RELAYS;
    if ((ret = gpiod_controller_claim_lines(controller, gpio_base, gpio_count, lines_data, &relay_lines)) < 0) {
        perror("gpiod_controller_claim_lines");
        goto cleanup_controller;
    }

    int state = 0;
    for (;;) {
        for (int i = 0; i < NUM_RELAYS; ++i) {
            gpiod_line_set_value(relay_lines + i, !!(state & (1 << i)));
        }
        printf("State: %d\n", state);
        sleep(10); // 10 seconds for red, yellow, and green

        state = (state + 1) & 0b1111;
        if (state == 0b1010) {
            state |= 0b00100000; // add yellow for 3 seconds
            sleep(3);
        }
    }

cleanup_controller:
    if (relay_lines) {
        gpiod_line_array_release(relay_lines);
        relay_lines = NULL;
    }
    if (controller) {
        gpiod_controller_release(controller);
        controller = NULL;
    }
    return 0;
}

