#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <time.h>
#include <linux/types.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define GPIO_17_LINE "gpiochip0/gpio17"
#define GPIO_27_LINE "gpiochip0/gpio27"
#define DISPENSE_INTERVAL 1000
#define DISPENSE_DURATION 500
#define LOG_FILE "dispense_log.txt"

int gpiod_init(void);
void gpiod_deinit(void);
int write_to_log(const char *format, ...);
void sigint_handler(int signum);

int main(void) {
    int ret;

    if ((ret = gpiod_init()) != 0) {
        fprintf(stderr, "Error initializing gpiod: %s\n", strerror(ret));
        return ret;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Error opening log file");
        gpiod_deinit();
        return 1;
    }

    gpiod_line_request_line(gpio_get_chip_data(gpiod_get_line_byname(GPIO_17_LINE)), GPIOD_LINE_REQUEST_DIRECTION_OUT | GPIOD_LINE_REQUEST_ACTIVE_LOW);
    gpiod_line_request_line(gpio_get_chip_data(gpiod_get_line_byname(GPIO_27_LINE)), GPIOD_LINE_REQUEST_DIRECTION_OUT | GPIOD_LINE_REQUEST_ACTIVE_LOW);

    sigset_t sigint_set;
    sigemptyset(&sigint_set);
    sigaddset(&sigint_set, SIGINT);
    sigprocmask(SIG_SETMASK, &sigint_set, NULL);
    signal(SIGINT, sigint_handler);

    while (1) {
        gpiod_line_set_value(gpio_get_line(gpiod_get_line_byname(GPIO_17_LINE)), 1);
        nanosleep((const struct timespec[]){{0, DISPENSE_DURATION * 1000000}}, &ts);
        gpiod_line_set_value(gpio_get_line(gpiod_get_line_byname(GPIO_17_LINE)), 0);

        gpiod_line_set_value(gpio_get_line(gpiod_get_line_byname(GPIO_27_LINE)), 1);
        nanosleep((const struct timespec[]){{0, (DISPENSE_INTERVAL - DISPENSE_DURATION) * 1000000}}, &ts);
        gpiod_line_set_value(gpio_get_line(gpiod_get_line_byname(GPIO_27_LINE)), 0);

        clock_gettime(CLOCK_REALTIME, &ts);
        write_to_log("%ld,%d,%d\n", (long)ts.tv_sec, (int)gpio_get_line(gpiod_get_line_byname(GPIO_17_LINE)) + 1, (int)gpio_get_line(gpiod_get_line_byname(GPIO_27_LINE)) + 1);
    }

    fclose(log_file);
    gpiod_deinit();
    return 0;
}

int gpiod_init(void) {
    int ret;
    struct gpiod_chip *chip;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Error opening gpiochip0");
        return -1;
    }

    ret = gpiod_chip_configure_up_down(chip, NULL, 0);
    if (ret < 0) {
        perror("Error configuring gpiochip0");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

void gpiod_deinit(void) {
    struct gpiod_chip *chip = gpiod_chip_open_byname("gpiochip0");
    if (chip) {
        gpiod_chip_unconfigure_all(chip);
        gpiod_chip_close(chip);
    }
}

int write_to_log(const char *format, ...) {
    va_list args;
    FILE *log_file;
    int ret;

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return -1;
    }

    va_start(args, format);
    ret = vfprintf(log_file, format, args);
    va_end(args);

    if (ret < 0) {
        perror("Error writing to log file");
    }

    fclose(log_file);
    return ret;
}

void sigint_handler(int signum) {
    gpiod_line_set_value(gpio_get_line(gpiod_get_line_byname(GPIO_17_LINE)), 0);
    gpiod_line_set_value(gpio_get_line(gpiod_get_line_byname(GPIO_27_LINE)), 0);
    gpiod_deinit();
    exit(0);
}

