#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <gpiod.h>

#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define ENA 24
#define ENB 25
#define PWM_FREQ 800
#define PID_PERIOD 50000
#define OBSTACLE_THRESHOLD 20
#define LOG_FILE "balance_log.txt"

gpiod_line_request_linestate_vlinestate_callback_t motor_callback;
gpiod_line_request *motors[4];
int pwm_fd[2];
float tilt_error, distance;

void motor_callback(struct gpiod_line_request *request, unsigned int value,
                    unsigned int event, void *user_data) {
    int motor = (intptr_t)user_data;
    gpiod_line_set_value(motors[motor], !value);
}

void init_motors() {
    for (int i = 0; i < 4; ++i) {
        motors[i] = gpiod_request_line(0, i, "motor", GPIOD_LINE_REQUEST_DIRECTION_OUT,
                                       GPIOD_LINE_STATE_HIGH);
        if (!motors[i]) {
            perror("Failed to request motor GPIO line");
            exit(1);
        }
        gpiod_line_set_event_callback(motors[i], motor_callback, (void *)(intptr_t)i);
    }

    if (gpio_pwm_open_with_freq(PWM_FREQ, &pwm_fd[0]) < 0 ||
        gpio_pwm_open_with_freq(PWM_FREQ, &pwm_fd[1]) < 0) {
        perror("Failed to open PWM");
        exit(1);
    }
}

void close_resources() {
    gpiod_line_release(motors[0]);
    gpiod_line_release(motors[1]);
    gpiod_line_release(motors[2]);
    gpiod_line_release(motors[3]);
    gpio_pwm_close(pwm_fd[0]);
    gpio_pwm_close(pwm_fd[1]);
}

void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[20];
    char log_line[100];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    snprintf(log_line, sizeof(log_line), "%s,%f,%f,%d,%d\n", time_str, tilt_error, distance,
             motor_a_speed, motor_b_speed);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close_resources();
        exit(1);
    }

    fputs(log_line, log_file);
    fclose(log_file);
}

int main() {
    srand(time(NULL));

    if (gpio_init() < 0) {
        perror("Failed to initialize GPIO");
        return 1;
    }

    init_motors();

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to create log file");
        close_resources();
        gpio_shutdown();
        return 1;
    }

    while (1) {
        tilt_error = random_float(-10.0, 10.0);
        distance = random_distance(2.0, 400.0);

        int motor_a_speed = PID_control(tilt_error);
        int motor_b_speed = PID_control(tilt_error);

        if (distance < OBSTACLE_THRESHOLD) {
            motor_a_speed /= 2;
            motor_b_speed /= 2;
        }

        motor_a_speed = clamp(motor_a_speed, -255, 255);
        motor_b_speed = clamp(motor_b_speed, -255, 255);

        gpio_pwm_write(pwm_fd[0], motor_a_speed);
        gpio_pwm_write(pwm_fd[1], motor_b_speed);

        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        usleep(PID_PERIOD);
    }

    close_resources();
    gpio_shutdown();

    return 0;
}

int clamp(int value, int min, int max) {
    return value < min ? min : (value > max ? max : value);
}

