#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <errno.h>
#include <libgpiod.h>
#include <sys/types.h>
#include <sys/wait.h>

#define SENSOR_GPIO 17
#define DEBOUNCE_INTERVAL_MS 200
#define VIDEO_CAPTURE_DURATION_S 5
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos"

gpiod_line_request_linestate_cb_t line_cb;
gpiod_line_request *request;
gpiod_chip *chip;

int main(void) {
    int ret;
    struct timespec debounce_timer;
    struct stat log_stat;
    char log_path[128];
    char video_path[128];
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    // Initialize GPIO
    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    request = gpiod_chip_request_line(chip, SENSOR_GPIO, "motion_sensor");
    if (!request) {
        perror("Failed to request line");
        gpiod_chip_close(chip);
        return 1;
    }

    line_cb = gpiod_line_request_get_callback(request);
    gpiod_line_request_set_debounce(request, DEBOUNCE_INTERVAL_MS * NSEC_PER_MSEC);

    // Install SIGINT handler
    signal(SIGINT, exit_handler);

    while (1) {
        // Check if the sensor line is low
        if (gpiod_line_get_value(request) == GPIOD_LINE_STATE_LOW) {
            // Debounce delay
            nanosleep(&debounce_timer, NULL);

            // Check if the sensor line is still low
            if (gpiod_line_get_value(request) == GPIOD_LINE_STATE_LOW) {
                // Capture video
                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", timeinfo);
                snprintf(video_path, sizeof(video_path), "%s/%s.h264", VIDEO_DIR, timestamp);
                snprintf(log_path, sizeof(log_path), "%s %ld\n", LOG_FILE, rawtime);

                // Create video file
                if (stat(VIDEO_DIR, &log_stat) != 0 && errno != ENOENT) {
                    perror("Failed to stat video directory");
                    goto cleanup;
                }
                if (mkdir(VIDEO_DIR, 0755) && errno != EEXIST) {
                    perror("Failed to create video directory");
                    goto cleanup;
                }
                if (open(video_path, O_WRONLY | O_CREAT | O_EXCL, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH) < 0) {
                    perror("Failed to create video file");
                    goto cleanup;
                }

                // Start video capture
                ret = system(raspivid -o /dev/null -t 5000 -hf -w 640 -h 480 -b 0 -n -sh 1 -o /dev/null 2>&1 &);
                if (ret == -1) {
                    perror("Failed to start video capture");
                    goto cleanup;
                }

                // Write log entry
                if (write(fileno(fopen(log_path, "a")), log_path, strlen(log_path)) != strlen(log_path)) {
                    perror("Failed to write log entry");
                    goto cleanup;
                }

                // Wait for video capture to finish
                int pid = wait(NULL);
                if (pid <= 0) {
                    perror("Failed to wait for video capture");
                    goto cleanup;
                }
            }
        }

        // Set debounce timer
        debounce_timer.tv_sec = 0;
        debounce_timer.tv_nsec = DEBOUNCE_INTERVAL_MS * NSEC_PER_MSEC;
    }

cleanup:
    // Release resources
    if (request) {
        gpiod_line_request_remove(request);
        gpiod_line_request_free(request);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

void exit_handler(int sig) {
    // Release resources and exit
    if (request) {
        gpiod_line_request_remove(request);
        gpiod_line_request_free(request);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

