#include <stdio.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <pthread.h>
#include <time.h>

#define I2C_BUS 1
#define MPU6050_ADDR 0x68
#define MPU6050_RA_ACCEL_XOUT_H 0x3B
#define MPU6050_RA_GYRO_XOUT_H 0x43
#define FSR 250.0
#define SAMPLE_RATE 100

gpiod_line_request_linenum_t gpio_line_request;
int i2c_fd;

void sigint_handler(int signum) {
    gpiod_line_release(gpio_line_request);
    close(i2c_fd);
    exit(0);
}

int init_i2c() {
    char filename[32];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access");
        return -1;
    }

    return 0;
}

int read_mpu6050(int16_t *data) {
    if (write(i2c_fd, &MPU6050_RA_ACCEL_XOUT_H, 1) != 1) {
        perror("Failed to write to MPU-6050");
        return -1;
    }

    if (read(i2c_fd, data, 14) != 14) {
        perror("Failed to read from MPU-6050");
        return -1;
    }

    return 0;
}

void convert_to_degrees_per_second(int16_t *data, float *gyro_data) {
    gyro_data[0] = (float)data[0] / 131.0;
    gyro_data[1] = (float)data[1] / 131.0;
    gyro_data[2] = (float)data[2] / 131.0;
    gyro_data[0] *= FSR;
    gyro_data[1] *= FSR;
    gyro_data[2] *= FSR;
}

int main() {
    int ret;
    int16_t raw_data[6];
    float gyro_data[3];
    struct timespec ts;
    FILE *log_file;
    pthread_t read_thread;

    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("Failed to set SIGINT handler");
        return -1;
    }

    if (signal(SIGTERM, sigint_handler) == SIG_ERR) {
        perror("Failed to set SIGTERM handler");
        return -1;
    }

    if (init_i2c() < 0) {
        return -1;
    }

    log_file = fopen("gyro_log.csv", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return -1;
    }

    fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");

