#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <time.h>
#include <pthread.h>
#include <libgpiod.h>

#define TRIG_LINE 4
#define ECHO_LINE 18
#define MAX_PULSE_WIDTH_US 23200
#define TIMEOUT_US 100000
#define TICK_PER_NS (1000000000ULL)
#define TICK_PER_MINUTE (TICK_PER_NS / 60)
#define TICK_PER_HOUR (TICK_PER_MINUTE * 60)
#define TICK_PER_DAY (TICK_PER_HOUR * 24)

struct gpiod_line *trig_line, *echo_line;
pthread_mutex_t mutex;
pthread_t echo_thread;
uint64_t tick_counter = 0;
FILE *log_file;

void echo_callback(struct gpiod_line *line, int event, void *data) {
    if (event != GPIOD_LINE_EVENT_RISING_EDGE) return;

    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    uint64_t pulse_start = ts.tv_sec * TICK_PER_NS + ts.tv_nsec;

    pthread_mutex_lock(&mutex);
    clock_gettime(CLOCK_MONOTONIC, &ts);
    uint64_t pulse_end = ts.tv_sec * TICK_PER_NS + ts.tv_nsec;
    pthread_mutex_unlock(&mutex);

    if (pulse_end - pulse_start > TICK_PER_NS * MAX_PULSE_WIDTH_US) {
        fprintf(stderr, "Invalid pulse width\n");
        return;
    }

    double distance_cm = (pulse_end - pulse_start) / TICK_PER_NS * 17150;
    if (distance_cm > 400) {
        fprintf(stderr, "Sensor timeout\n");
        return;
    }

    pthread_mutex_lock(&mutex);
    fprintf(log_file, "%llu,%f\n", tick_counter, distance_cm);
    pthread_mutex_unlock(&mutex);
}

void sigint_handler(int sig) {
    gpiod_line_set_debounce(echo_line, 0);
    gpiod_line_set_event_cb(echo_line, NULL);
    pthread_join(echo_thread, NULL);

    if (log_file) {
        fclose(log_file);
    }
    gpiod_unclaim_all();
    pthread_mutex_destroy(&mutex);
    exit(0);
}

int main() {
    if (gpiod_library_open() < 0) {
        perror("gpiod_library_open");
        return 1;
    }

    trig_line = gpiod_get_line_byname("gpiochip0", "gpio4");
    echo_line = gpiod_get_line_byname("gpiochip0", "gpio18");

    if (!trig_line || !echo_line) {
        perror("gpiod_get_line_byname");
        gpiod_library_close();
        return 1;
    }

    gpiod_line_request_output(trig_line, "ultrasonic_trigger", GPIOD_LINE_REQUEST_DIRECTION_OUT);
    gpiod_line_request_input(echo_line, "ultrasonic_echo", GPIOD_LINE_REQUEST_INPUT_DEBOUNCE);
    gpiod_line_set_value(trig_line, 0);

    log_file = fopen("distance_log.txt", "w");
    if (!log_file) {
        perror("fopen");
        gpiod_line_set_debounce(echo_line, 0);
        gpiod_line_set_event_cb(echo_line, NULL);
        gpiod_library_close();
        return 1;
    }

    pthread_mutex_init(&mutex, NULL);
    gpiod_line_set_event_cb(echo_line, echo_callback);
