#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <math.h>
#include <signal.h>

#define LIS3DH_ADDR 0x19
#define BUZZER_GPIO 17
#define FREE_FALL_THRESHOLD 0.2
#define IMPACT_THRESHOLD 1.5

int i2c_file;
struct gpiod_line_request *buzzer_req;

void i2c_init() {
    const char *i2c_bus = "/dev/i2c-1";
    if ((i2c_file = open(i2c_bus, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_file, I2C_SLAVE, LIS3DH_ADDR) < 0) {
        perror("Failed to acquire bus access");
        exit(EXIT_FAILURE);
    }
}

void gpio_init() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line_request_config config = {
        .direction = GPIOD_IN,
        .edge_detected_callback = NULL,
        .active_low = 0,
        .flags = GPIOD_LINE_REQUEST_INPUT,
    };

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    buzzer_req = gpiod_chip_get_line(chip, BUZZER_GPIO);
    if (!buzzer_req) {
        perror("Failed to get GPIO line");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_configure_async(buzzer_req, &config, NULL);
    if (ret < 0) {
        perror("Failed to configure GPIO line");
        exit(EXIT_FAILURE);
    }
}

void i2c_read(uint8_t *buf, size_t len) {
    ssize_t bytes_read;
    int retries = 3;

    while (retries > 0) {
        bytes_read = read(i2c_file, buf, len);
        if (bytes_read >= 0)
            break;

        if (errno != EAGAIN) {
            perror("I2C read error");
            exit(EXIT_FAILURE);
        }

        retries--;
        usleep(100000); // Wait 100ms before retrying
    }

    if (bytes_read != len) {
        perror("Short read from I2C");
        exit(EXIT_FAILURE);
    }
}

double acceleration_magnitude(uint8_t x, uint8_t y, uint8_t z) {
    double xy = x * y;
    double xz = x * z;
    double yz = y * z;
    return sqrt(xy + xz + yz);
}

void handle_impact() {
    gpiod_line_set_value(buzzer_req, 1);
    usleep(1000000); // Sleep for 1 second
    gpiod_line_set_value(buzzer_req, 0);
}

int main(int argc, char *argv[]) {
    uint8_t buf[6];
    double free_fall_threshold = FREE_FALL_THRESHOLD;
    double impact_threshold = IMPACT_THRESHOLD;

    if (argc > 2) {
        free_fall_threshold = atof(argv[1]);
        impact_threshold = atof(argv[2]);
    }

    i2c_init();
    gpio_init();

    while (1) {
        i2c_read(buf, 6);

        if (buf[0] != 0x31 || buf[1] != 0x33) {
            perror("Invalid LIS3DH ID");
            exit(EXIT_FAILURE);
        }

        if (buf[2] & 0x04) {
            printf("Detected free-fall: %f g\n", free_fall_threshold);
        }

        double acc_magnitude = acceleration_magnitude(buf[3], buf[4], buf[5]);
        if (acc_magnitude < free_fall_threshold) {
            continue;
        }

        if (acc_magnitude > impact_threshold) {
            printf("Detected impact: %f g\n", impact_threshold);
            handle_impact();
        }
    }

    close(i2c_file);
    gpiod_chip_close(buzzer_req->chip);
    gpiod_line_release(buzzer_req);
    return 0;
}

