#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <libgpiod.h>

#define LIS3DH_ADDR_DEFAULT 0x19
#define THRESHOLD_DEFAULT 2.0
#define SAMPLE_RATE_HZ 10
#define OUTPUT_DATA_RATE_HZ 100
#define AXIS_BITS 12
#define AXIS_RESOLUTION (1LL << AXIS_BITS)
#define AXIS_MAX ((1LL << AXIS_BITS) - 1)

struct i2c_client {
    int fd;
    uint8_t addr;
};

int i2c_write_byte_data(struct i2c_client *client, uint8_t reg, uint8_t value) {
    return write(client->fd, &reg, 1) == 1 &&
           write(client->fd, &value, 1) == 1;
}

int i2c_read_byte_data(struct i2c_client *client, uint8_t reg) {
    uint8_t value;
    if (read(client->fd, &value, 1) != 1)
        return -1;
    return value;
}

void i2c_init(struct i2c_client *client, uint8_t addr) {
    client->addr = addr;
    if ((client->fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(0);
    }
    if (ioctl(client->fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to acquire I2C address");
        exit(0);
    }
}

void i2c_cleanup(struct i2c_client *client) {
    if (client->fd >= 0)
        close(client->fd);
}

double axis_value_to_g(uint32_t value) {
    return (double)value / AXIS_RESOLUTION * 2.0;
}

void log_high_acceleration(const char *timestamp, uint32_t x, uint32_t y, uint32_t z) {
