#include <linux/spi/spidev.h>
#include <gpiod.h>

#define GPIO_BUS_WIDTH 8
#define LEFT_SENSOR 4
#define CENTER_SENSOR 17
#define RIGHT_SENSOR 27
#define ALERT_LED 22
#define BUFFER_SIZE 5

struct sensor_data {
    uint32_t left;
    uint32_t center;
    uint32_t right;
};

struct gpiod_line_request *line_requests[3];
struct gpiod_line_state *line_states[3];
struct sensor_data buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;

void gpiod_init() {
    int ret;

    for (int i = 0; i < 3; i++) {
        line_requests[i] = gpiod_claim_line_raw_flags(gpiochip_get_byname("gpiochip0"), i, GPIOD_LINE_REQUEST_DIRECTION_IN | GPIOD_LINE_REQUEST_EDGE_RISING);
        if (!line_requests[i]) {
            perror("Failed to claim line request");
            exit(EXIT_FAILURE);
        }

        line_states[i] = gpiod_get_line_value_cansleep(line_requests[i]);
    }

    ret = gpiod_claim_line_raw_flags(gpiochip_get_byname("gpiochip0"), ALERT_LED, GPIOD_LINE_REQUEST_DIRECTION_OUT);
    if (ret < 0) {
        perror("Failed to claim alert LED");
        exit(EXIT_FAILURE);
    }
}

void gpiod_cleanup() {
    for (int i = 0; i < 3; i++) {
        gpiod_release_line(line_requests[i]);
    }
    gpiod_release_line(line_requests[ALERT_LED]);
}

void log_sensor_data(struct sensor_data data) {
    buffer[buffer_head] = data;
    buffer_head = (buffer_head + 1) % BUFFER_SIZE;
}

int is_consecutive_no_line() {
    int count = 0;
    for (int i = buffer_tail; i != buffer_head; i = (i + 1) % BUFFER_SIZE) {
        if (buffer[i].center) {
            break;
        }
        count++;
        if (count == 5) {
            return 1;
        }
    }
    return 0;
}

int main() {
    gpiod_init();
    signal(SIGINT, gpiod_cleanup);
    signal(SIGTERM, gpiod_cleanup);

    while (1) {
        struct gpiod_line_state states[3];
        int ret = gpiod_get_lines_values_cansleep(3, line_requests, states);
        if (ret < 0) {
            perror("Failed to get sensor values");
            gpiod_cleanup();
            exit(EXIT_FAILURE);
        }

        log_sensor_data((struct sensor_data){states[LEFT_SENSOR].value, states[CENTER_SENSOR].value, states[RIGHT_SENSOR].value});

        if (states[CENTER_SENSOR].value == 0) {
            move_forward();
        } else if (states[LEFT_SENSOR].value == 1) {
            turn_left();
        } else if (states[RIGHT_SENSOR].value == 1) {
            turn_right();
        } else if (is_consecutive_no_line()) {
            gpiod_set_value_cansleep(line_requests[ALERT_LED], 1);
            usleep(2000000);
            gpiod_set_value_cansleep(line_requests[ALERT_LED], 0);
            stop();
        } else {
            stop();
        }
    }

    gpiod_cleanup();
    return 0;
}

