#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <errno.h>
#include <sys/time.h>
#include <gpiod.h>

#define SI7210_ADDR 0x1E
#define GPIO_17_LINE "gpiochip0 17"
#define THRESHOLD 500000
#define SAMPLE_INTERVAL 100000
#define POLL_MAX_ATTEMPTS 50
#define TIMEOUT_ERROR "Timeout error: Si7210 register value did not clear after %d attempts\n"

struct i2c_data {
    int fd;
    uint8_t reg_value;
};

void sigint_handler(int signum) {
    struct i2c_data *i2c = (struct i2c_data *)gpiod_get_data(gpiochip_get_byname("gpiochip0"));
    close(i2c->fd);
    gpiod_set_value_cansleep(gpio_get_line_byname(GPIO_17_LINE), 0);
    gpiod_set_value_cansleep(gpio_get_line_byname("shutdown"), 1);
    gpiod_release(gpiochip_get_byname("gpiochip0"));
    exit(0);
}

int read_si7210(struct i2c_data *i2c) {
    int ret;
    uint8_t data[2];

    ret = i2c_smbus_read_word_data(i2c->fd, 0x00);
    if (ret < 0) {
        perror("i2c_smbus_read_word_data");
        return -1;
    }

    data[0] = (ret & 0xFF00) >> 8;
    data[1] = ret & 0xFF;

    i2c->reg_value = (data[0] << 8) | data[1];
    return 0;
}

int main() {
    int i2c_fd, ret;
    struct i2c_data i2c = {-1, 0};
    struct timespec sleep_time;
    struct gpiod_line *gpio_line;
    struct gpiod_chip *gpiochip;
    FILE *file;
    char timestamp[32];
    int attempts = 0;

    signal(SIGINT, sigint_handler);

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("open /dev/i2c-1");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI7210_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        exit(1);
    }

    gpiochip = gpiod_chip_open_byname("gpiochip0");
    if (!gpiochip) {
        perror("gpiochip_open_byname");
        exit(1);
    }

    gpio_line = gpiod_get_line_byname(GPIO_17_LINE);
    if (!gpio_line) {
        perror("gpio_get_line_byname");
        exit(1);
    }

    file = fopen("magnetic_events.txt", "a");
    if (!file) {
        perror("fopen magnetic_events.txt");
        exit(1);
    }

    while (1) {
        if (read_si7120(&i2c) < 0) {
            perror("read_si7120");
            continue;
        }

        if (i2c.reg_value > THRESHOLD) {
            gpiod_set_value_cansleep(gpio_line, 1);
            fprintf(file, "%s gpio_17_set\n", ctime(&time(NULL)));
        } else {
            gpiod_set_value_cansleep(gpio_line, 0);
            fprintf(file, "%s gpio_17_reset\n", ctime(&time(NULL)));
        }

        attempts = 0;
        if (i2c.reg_value != 0) {
            while (attempts < POLL_MAX_ATTEMPTS && i2c.reg_value != 0) {
                if (read_si7120(&i2c) < 0) {
                    perror("read_si7120");
                    continue;
                }
                attempts++;
            }

            if (attempts == POLL_MAX_ATTEMPTS) {
                fprintf(file, "%s Timeout error\n", ctime(&time(NULL)));
                continue;
            }
        }

        sleep_time.tv_sec = SAMPLE_INTERVAL / 1000000000;
        sleep_time.tv_nsec = (SAMPLE_INTERVAL % 1000000000) * 1000;
        nanosleep(&sleep_time, NULL);
    }

    fclose(file);
    gpiod_set_value_cansleep(gpio_line, 0);
    gpiod_chip_close(gpiochip);
    close(i2c_fd);

    return 0;
}

