#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x40
#define SENSOR2_ADDR 0x41
#define RELAY_GPIO 18
#define FLOW_THRESHOLD 5000
#define CRC_POLYNOMIAL 0x31

static int i2c_write(int fd, uint8_t addr, const uint8_t *data, size_t len) {
    if (write(fd, &addr, 1) != 1) {
        perror("Failed to write I2C address");
        return -1;
    }

    if (write(fd, data, len) != len) {
        perror("Failed to write I2C data");
        return -1;
    }

    return 0;
}

static int i2c_read(int fd, uint8_t addr, uint8_t *buf, size_t len) {
    if (i2c_write(fd, addr, NULL, 0) != 0) {
        return -1;
    }

    if (read(fd, buf, len) != len) {
        perror("Failed to read I2C data");
        return -1;
    }

    return 0;
}

static uint8_t crc8(uint8_t data, uint8_t crc) {
    for (size_t i = 8; i > 0; --i) {
        crc = (crc >> 1) ^ (crc & 0x01 ? CRC_POLYNOMIAL : 0);
        crc = (crc >> 8) | (data << 8);
        data <<= 1;
    }

    return crc;
}

static int validate_data(const uint8_t *data, size_t len) {
    if (len != 3) {
        return -1;
    }

    uint8_t crc = data[2];
    for (size_t i = 0; i < len - 1; ++i) {
        crc = crc8(data[i], crc);
    }

    return crc == data[len - 1] ? 0 : -1;
}

int main(void) {
    int i2c_fd[2];
    gpiod_line_request_lines(1, RELAY_GPIO, GPIOD_LINE_REQUEST_DIRECTION_OUT, NULL);
    gpiod_line_set_value(1, RELAY_GPIO, 0);

    if (i2c_fd[0] = open("/dev/i2c-1", O_RDWR) < 0) {
        perror("Failed to open I2C bus");
        goto cleanup;
    }

    if (ioctl(i2c_fd[0], I2C_SLAVE, SENSOR1_ADDR) < 0) {
        perror("Failed to set I2C slave address for sensor 1");
        goto close_i2c1;
    }

    if (i2c_write(i2c_fd[0], 0x03, (const uint8_t[]){0x01, 0x00}, 2) != 0) {
        perror("Failed to start measurement for sensor 1");
        goto close_i2c1;
    }

    if (i2c_fd[1] = open("/dev/i2c-1", O_RDWR) < 0) {
        perror("Failed to open I2C bus");
        goto close_i2c0;
    }

    if (ioctl(i2c_fd[1], I2C_SLAVE, SENSOR2_ADDR) < 0) {
        perror("Failed to set I2C slave address for sensor 2");
        goto close_i2c1;
    }

    if (i2c_write(i2c_fd[1], 0x03, (const uint8_t[]){0x01, 0x00}, 2) != 0) {
        perror("Failed to start measurement for sensor 2");
        goto close_i2c1;
    }

    FILE *log_file = fopen("flow_log.txt", "a");
    if (!log_file) {
        perror("Failed to open flow log file");
        goto close_i2c;
    }

    setbuf(log_file, NULL);

    while (1) {
        uint8_t data1[3], data2[3];
        ssize_t n1 = i2c_read(i2c_fd[0], SENSOR1_ADDR, data1, sizeof(data1));
        ssize_t n2 = i2c_read(i2c_fd[1], SENSOR2_ADDR, data2, sizeof(data2));

        if (n1 < 0 || n2 < 0) {
            continue;
        }

        if (validate_data(data1, n1) < 0 || validate_data(data2, n2) < 0) {
            continue;
        }

        uint16_t flow1 = (data1[0] << 8) | data1[1];
        uint16_t flow2 = (data2[0] << 8) | data2[1];

        fprintf(log_file, "%lu, %u, %u\n", (unsigned long)time(NULL), flow1, flow2);
        fflush(log_file);

        if (flow1 < FLOW_THRESHOLD && flow2 < FLOW_THRESHOLD) {
            gpiod_line_set_value(1, RELAY_GPIO, 1);
        } else {
            gpiod_line_set_value(1, RELAY_GPIO, 0);
        }
    }

close_i2c:
    close(i2c_fd[1]);
close_i2c1:
    close(i2c_fd[0]);
close_i2c0:
    gpiod_line_release(1, RELAY_GPIO);
cleanup:
    gpiod_shutdown();

    if (log_file) {
        fclose(log_file);
    }

    return 0;
}

