        goto cleanup_chip;
    }

    request = gpiod_line_request_clone(line);
    if (!request) {
        log_error("Failed to clone line request for GPIO %d", RAIN_SENSOR_GPIO);
        goto cleanup_line;
    }

    data.flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_RISING;
    data.consumer = "rain_window";
    ret = gpiod_line_request_configure_flags(request, &data, GPIOD_LINE_REQUEST_PIXEL_MODE);
    if (ret < 0) {
        log_error("Failed to configure line request for GPIO %d", RAIN_SENSOR_GPIO);
        goto cleanup_request;
    }

    ret = gpiod_line_request_enable(request);
    if (ret < 0) {
        log_error("Failed to enable line request for GPIO %d", RAIN_SENSOR_GPIO);
        goto cleanup_request;
    }

    return 0;

cleanup_request:
    gpiod_line_request_free(request);

cleanup_line:
    gpiod_line_put(line);

cleanup_chip:
    gpiod_chip_put(chip);

    return -1;
}

