    ena_line = gpiod_chip_get_line(chip, MOTOR_ENA_GPIO);
    if (!ena_line) {
        log_error("Failed to get line for GPIO %d", MOTOR_ENA_GPIO);
        goto cleanup_device;
    }

    in1_line = gpiod_chip_get_line(chip, MOTOR_IN1_GPIO);
    if (!in1_line) {
