        goto cleanup_ena_line;
    }

    in2_line = gpiod_chip_get_line(chip, MOTOR_IN2_GPIO);
    if (!in2_line) {
        log_error("Failed to get line for GPIO %d", MOTOR_IN2_GPIO);
        goto cleanup_in1_line;
    }

    return 0;

cleanup_in2_line:
    gpiod_line_put(in2_line);

cleanup_in1_line:
    gpiod_line_put(in1_line);

cleanup_ena_line:
    gpiod_line_put(ena_line);

cleanup_device:
