This program will run continuously, monitoring the rain sensor and driving the motor when rain is detected. It logs events using syslog and handles SIGINT and SIGTERM signals gracefully.

I'll provide a simple example using the `libgpiod` library. This code assumes you have libgpiod installed on your Raspberry Pi. If not, you can install it using the following command:

```bash
sudo apt-get install libgpiod-dev
```

Here's the C code:

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/types.h>
#include <gpiod.h>
#include <signal.h>

#define SERVO_GPIO 18
#define LOCK_GPIO 21
#define UNLOCK_GPIO 22
#define DEBOUNCE_DELAY_MS 100
#define LOCK_PULSE_US 2000
#define UNLOCK_PULSE_US 1000

gpiod_line_request_linestate_vlinestate_callback_t servo_cb;
gpiod_line_request_data_t servo_req;
gpiod_line_request_data_t lock_req;
gpiod_line_request_data_t unlock_req;

void servo_callback(struct gpiod_chan *chan, unsigned int value, unsigned int event) {
    if (event == GPIOD_LINE_EVENT_EDGE_FALLING) {
        gpiod_line_set_value(chan, 0);
    }
}

void lock_button_callback(struct gpiod_chan *chan, unsigned int value, unsigned int event) {
    if (value == 0 && event == GPIOD_LINE_EVENT_EDGE_RISING) {
        gpiod_line_set_value(chan, 1);
        gpiod_line_set_debounce(lock_req.lines[0], DEBOUNCE_DELAY_MS * 1000);
    }
}

void unlock_button_callback(struct gpiod_chan *chan, unsigned int value, unsigned int event) {
    if (value == 0 && event == GPIOD_LINE_EVENT_EDGE_RISING) {
        gpiod_line_set_value(chan, 1);
        gpiod_line_set_debounce(unlock_req.lines[0], DEBOUNCE_DELAY_MS * 1000);
    }
}

int main() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line_request *servo_req_ptr;
    struct gpiod_line_request *lock_req_ptr;
    struct gpiod_line_request *unlock_req_ptr;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    servo_req.consumer = "door-lock-servo";
    servo_req.flags = GPIOD_LINE_REQUEST_DIRECTION_OUT;
    servo_req_ptr = gpiod_chip_request_lines(chip, 1, &servo_req, &servo_cb);
    if (!servo_req_ptr) {
        perror("Failed to request servo GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    lock_req.consumer = "door-lock-button";
    lock_req.flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_PULL_UP;
    lock_req_ptr = gpiod_chip_request_lines(chip, 1, &lock_req, &lock_button_callback);
    if (!lock_req_ptr) {
        perror("Failed to request lock button GPIO line");
        gpiod_line_release(servo_req_ptr->lines[0]);
        gpiod_chip_close(chip);
        return 1;
    }

    unlock_req.consumer = "door-unlock-button";
    unlock_req.flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_PULL_UP;
    unlock_req_ptr = gpiod_chip_request_lines(chip, 1, &unlock_req, &unlock_button_callback);
    if (!unlock_req_ptr) {
        perror("Failed to request unlock button GPIO line");
        gpiod_line_release(servo_req_ptr->lines[0]);
        gpiod_line_release(lock_req_ptr->lines[0]);
        gpiod_chip_close(chip);
        return 1;
    }

    signal(SIGINT, [](int signum) {
        gpiod_line_set_value(servo_req_ptr->lines[0], 0);
        gpiod_line_set_value(lock_req_ptr->lines[0], 1);
        gpiod_line_set_value(unlock_req_ptr->lines[0], 1);
        gpiod_line_release(servo_req_ptr->lines[0]);
        gpiod_line_release(lock_req_ptr->lines[0]);
        gpiod_line_release(unlock_req_ptr->lines[0]);
        gpiod_chip_close(chip);
        printf("Shutting down...\n");
        exit(0);
    });

    signal(SIGTERM, [](int signum) {
        gpiod_line_set_value(servo_req_ptr->lines[0], 0);
        gpiod_line_set_value(lock_req_ptr->lines[0], 1);
        gpiod_line_set_value(unlock_req_ptr->lines[0], 1);
        gpiod_line_release(servo_req_ptr->lines[0]);
        gpiod_line_release(lock_req_ptr->lines[0]);
        gpiod_line_release(unlock_req_ptr->lines[0]);
        gpiod_chip_close(chip);
        printf("Shutting down...\n");
        exit(0);
    });

    while (1) {
        usleep(100000);

        if (gpiod_line_get_value(lock_req_ptr->lines[0]) == 0) {
            ret = gpiod_line_set_value(servo_req_ptr->lines[0], 1);
            if (ret < 0) {
                perror("Failed to set servo pulse width");
                continue;
            }
            usleep(LOCK_PULSE_US * 1000);
            ret = gpiod_line_set_value(servo_req_ptr->lines[0], 0);
            if (ret < 0) {
                perror("Failed to reset servo pulse width");
                continue;
            }
            printf("Locking door...\n");
        }

        if (gpiod_line_get_value(unlock_req_ptr->lines[0]) == 0) {
            ret = gpiod_line_set_value(servo_req_ptr->lines[0], 1);
            if (ret < 0) {
                perror("Failed to set servo pulse width");
                continue;
            }
            usleep(UNLOCK_PULSE_US * 1000);
            ret = gpiod_line_set_value(servo_req_ptr->lines[0], 0);
            if (ret < 0) {
                perror("Failed to reset servo pulse width");
                continue;
            }
            printf("Unlocking door...\n");
        }
    }

    return 0;
}
```

This code initializes the GPIO lines for the servo, lock button, and unlock button. It sets up a callback for each button to handle debouncing and sets up SIGINT and SIGTERM handlers to clean up resources and stop the servo when the program is interrupted. The main loop polls the buttons and sends the appropriate pulse width to the servo when a button is pressed.

