#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/time.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>
#include <pthread.h>

#define PIR_GPIO 4
#define LED_GPIO 17
#define LOG_FILE "security_log.txt"

gpiod_line_request_linestate_cb_t led_state_cb;
gpiod_line_request_data_t led_request;
gpiod_line_request_data_t pir_request;
gpiod_line_request_data_t pir_request_data;
gpiod_line_request *led_request_obj;
gpiod_line_request *pir_request_obj;
gpiod_line *pir_line;
struct timespec start_time, end_time;

void led_state_cb(struct gpiod_chan *chan, int value, void *user_data) {
    if (value == 0) {
        gpiod_line_request_deactivate(led_request_obj);
        return;
    }

    clock_gettime(CLOCK_REALTIME, &start_time);
}

void pir_cb(struct gpiod_chan *chan, gpiod_event_t event, void *user_data) {
    if (event != GPIOD_EVENT_RISING_EDGE) {
        return;
    }

    gpiod_line_request_get_data(pir_request_obj, &pir_request_data);
    clock_gettime(CLOCK_REALTIME, &start_time);
    gpiod_line_request_activate(led_request_obj);
}

void log_event(const char *event_type, time_t timestamp) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        gpiod_line_request_deactivate(led_request_obj);
        exit(EXIT_FAILURE);
    }

    char timestamp_str[32];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S.%f", localtime(&timestamp));
    fprintf(log_file, "%s %s %s\n", timestamp_str, event_type, (event_type[0] == 'A' ? "" : (char*)ctime(&timestamp)));
    fclose(log_file);
}

void sigint_handler(int sig) {
    log_event("INTERRUPT", time(NULL));
    gpiod_line_request_deactivate(led_request_obj);
    gpiod_line_release(pir_line);
    gpiod_line_request_free(pir_request_obj);
    gpiod_line_request_free(led_request_obj);
    gpiod_library_unload();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpiod_library_probe() < 0) {
        perror("gpiod_library_probe");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    pir_line = gpiod_chip_get_line_byname(gpiod_chip_get_default_chip(), "gpiochip0", PIR_GPIO);
    if (!pir_line) {
        perror("gpiod_chip_get_line_byname");
        gpiod_library_unload();
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_direction_input(pir_line, &pir_request) < 0) {
        perror("gpiod_line_request_direction_input");
        gpiod_line_release(pir_line);
        gpiod_library_unload();
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_event(pir_line, &pir_request, pir_cb, NULL) < 0) {
        perror("gpiod_line_request_event");
        gpiod_line_request_free(&pir_request);
        gpiod_line_release(pir_line);
        gpiod_library_unload();
        exit(EXIT_FAILURE);
    }

    pir_request_data.flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_RISING;
    if (gpiod_line_request_configure_async(pir_request_obj, &pir_request_data) < 0) {
        perror("gpiod_line_request_configure_async");
        gpiod_line_request_free(&pir_request);
        gpiod_line_release(pir_line);
        gpiod_library_unload();
        exit(EXIT_FAILURE);
    }

    led_request_obj = gpiod_chip_get_request_byname(gpiod_chip_get_default_chip(), "request_gpio4");
    if (!led_request_obj) {
        perror("gpiod_chip_get_request_byname");
        gpiod_line_request_free(&pir_request);
        gpiod_line_release(pir_line);
        gpiod_library_unload();
        exit(EXIT_FAILURE);
    }

    led_request_data.flags = GPIOD_LINE_REQUEST_OUTPUT;
    if (gpiod_line_request_configure_async(led_request_obj, &led_request_data) < 0) {
        perror("gpiod_line_request_configure_async");
        gpiod_line_request_free(&pir_request);
        gpiod_line_release(pir_line);
        gpiod_line_request_free(led_request_obj);
        gpiod_library_unload();
        exit(EXIT_FAILURE);
    }

    led_state_cb(NULL, 1, NULL);

    while (1) {
        nanosleep((const struct timespec[]){{0, 100 * NANOSECONDS_PER_MILLISECOND}}, NULL);

        gpiod_line_request_get_data(pir_request_obj, &pir_request_data);
        if (pir_request_data.value == 1) {
            log_event("ACTIVATION", time(NULL));
            continue;
        }

        clock_gettime(CLOCK_REALTIME, &end_time);
        double duration = (end_time.tv_sec - start_time.tv_sec) + (end_time.tv_nsec - start_time.tv_nsec) / 1_billion;
        log_event("DEACTIVATION", time(NULL));
        log_event("DURATION", duration);

        gpiod_line_request_deactivate(led_request_obj);
        nanosleep((const struct timespec[]){{0, 60 * NANOSECONDS_PER_MILLISECOND}}, NULL);
        led_state_cb(NULL, 1, NULL);
    }

    return 0;
}

