static pthread_t pir_thread;
static int socket_fd = -1;

void servo_callback(struct gpiod_chan *chan, unsigned int value, unsigned int event) {
    if (event & GPIOD_LINE_REQUEST_EVENT_ACTIVE_LOW) {
        servo_angle = (value * 180) / GPIOD_LINE_REQUEST_VALUE_HIGH;
        servo_period = (PWM_MAX_PERIOD - PWM_MIN_PERIOD) * servo_angle / 180 + PWM_MIN_PERIOD;
        gpiod_line_request_set_direction(servo_request, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
        gpiod_line_request_set_value(servo_request, servo_angle == 0 || servo_angle == 180 ? GPIOD_LINE_REQUEST_VALUE_HIGH : GPIOD_LINE_REQUEST_VALUE_LOW);
    }
}

void pir_callback(struct gpiod_chan *chan, unsigned int value, unsigned int event) {
    if (event & GPIOD_LINE_REQUEST_EVENT_EDGE_FALLING) {
        pir_state = value;
        syslog(LOG_USER, "PIR: %d", pir_state);
        if (socket_fd > 0) {
            char buf[3];
            snprintf(buf, sizeof(buf), "PIR:%d", pir_state);
            send(socket_fd, buf, strlen(buf), 0);
        }
    }
}

void servo_thread_func(void *arg) {
    while (1) {
        gpiod_line_request_set_value(servo_request, servo_angle == 0 || servo_angle == 180 ? GPIOD_LINE_REQUEST_VALUE_HIGH : GPIOD_LINE_REQUEST_VALUE_LOW);
        usleep(servo_period * 1000);
        gpiod_line_request_set_value(servo_request, GPIOD_LINE_REQUEST_VALUE_LOW);
    }
}

void pir_thread_func(void *arg) {
    while (1) {
        usleep(100000); // 100ms polling interval
        gpiod_line_get_value(pir_request, &pir_state);
    }
}

void log_event(const char *event, ...) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[20];
    char log_str[256];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(time_str, sizeof(time_str), "%Y-%m-%dT%H:%M:%S", timeinfo);

    va_list args;
    va_start(args, event);
    vsnprintf(log_str, sizeof(log_str), event, args);
    va_end(args);

    openlog("servo_pir", LOG_PID, LOG_USER);
    syslog(LOG_USER, "%s: %s", time_str, log_str);
    closelog();

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s: %s\n", time_str, log_str);
        fclose(log_file);
    }
}

int main() {
    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        log_event("Failed to open GPIO chip: %s", strerror(errno));
        return 1;
    }

    servo_request = gpiod_chip_get_line_request_byname(chip, "gpio-17");
    if (!servo_request) {
        log_event("Failed to get servo GPIO request: %s", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    pir_request = gpiod_chip_get_line_request_byname(chip, "gpio-4");
    if (!pir_request) {
        log_event("Failed to get PIR GPIO request: %s", strerror(errno));
        gpiod_line_request_release(servo_request);
        gpiod_chip_close(chip);
        return 1;
    }

    gpiod_line_request_set_direction(servo_request, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    gpiod_line_request_set_value(servo_request, GPIOD_LINE_REQUEST_VALUE_LOW);

    gpiod_line_request_set_debounce(servo_request, 0);
    gpiod_line_request_set_glitch_filter(servo_request, 0);

    gpiod_line_request_set_callback(servo_request, servo_cb);
    gpiod_line_request_enable(servo_request, GPIOD_LINE_REQUEST_ENABLE_ACTIVE_LOW);

    gpiod_line_request_set_debounce(pir_request, 0);
    gpiod_line_request_set_glitch_filter(pir_request, 0);

    gpiod_line_request_set_callback(pir_request, pir_cb);
    gpiod_line_request_enable(pir_request, GPIOD_LINE_REQUEST_ENABLE_EDGE_FALLING);

    pthread_create(&servo_thread, NULL, servo_thread_func, NULL);
    pthread_create(&pir_thread, NULL, pir_thread_func, NULL);

    // Add your socket code here

    pthread_join(servo_thread, NULL);
    pthread_join(pir_thread, NULL);

    gpiod_line_request_release(servo_request);
    gpiod_line_request_release(pir_request);
    gpiod_chip_close(chip);

    return 0;
}

