#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/time.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define RELAY_GPIO 23

static gpiod_line_request_linestate_t relay_state = GPIOD_LINE_STATE_HIGH;
static gpiod_line_data_t relay_data = { .value = 0 };

static int i2c_file;
static struct i2c_rdwr_ioctl_data i2c_data;
static uint8_t buf[2];

void i2c_read_lux(void) {
    i2c_data.nmsgs = 1;
    i2c_data.msgs[0].addr = BH1750_ADDR << 1;
    i2c_data.msgs[0].flags = 0;
    i2c_data.msgs[0].len = 1;
    i2c_data.msgs[0].buf = &buf[0];

    if (ioctl(i2c_file, I2C_RDWR, &i2c_data) < 0) {
        perror("I2C read error");
        return;
    }

    if (i2c_data.msgs[0].len != 2) {
        fprintf(stderr, "Unexpected data length from BH1750\n");
        return;
    }

    uint16_t lux = (buf[0] << 8) | buf[1];
    printf("Lux: %d\n", lux);

    if (lux < 150) {
        gpiod_line_set_value(relay_data, GPIOD_LINE_STATE_LOW);
    } else {
        gpiod_line_set_value(relay_data, GPIOD_LINE_STATE_HIGH);
    }
}

void log_lux(const char *prefix, uint16_t lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *log_file = fopen("grow_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s%s Lux: %d\n", prefix, time_str, lux);
    fclose(log_file);
}

void i2c_init(void) {
    const char *i2c_dev_name = "/dev/i2c-" I2C_BUS;

    if ((i2c_file = open(i2c_dev_name, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_file, I2C_SLAVE, BH1750_ADDR << 1) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }
}

void gpio_init(void) {
    struct gpiod_chip *chip;
    struct gpiod_line_request_data request_data = {
        .consumer = "grow-light-controller",
        .direction = GPIOD_LINE_DIR_OUT,
        .flags = GPIOD_LINE_FLAG_ACTIVE_LOW,
    };

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    relay_data.consumer_data = &relay_state;
    if (gpiod_line_request_dt(chip, RELAY_GPIO, &request_data, &relay_data) < 0) {
        perror("Failed to request GPIO line");
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(relay_data, GPIOD_LINE_STATE_HIGH);
}

void cleanup(void) {
    gpiod_line_release(relay_data);
    close(i2c_file);
    gpiod_chip_close(relay_data.chip);
}

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up and exiting\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int main(void) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_init();
    gpio_init();

    struct timeval delay = { .tv_sec = 2, .tv_usec = 0 };
    struct timeval last_read = { .tv_sec = 0, .tv_usec = 0 };

    while (1) {
        struct timeval now;
        gettimeofday(&now, NULL);

        if ((now.tv_sec - last_read.tv_sec) >= 2) {
            i2c_read_lux();
            log_lux("", buf[0] << 8 | buf[1]);
            last_read = now;
        }

        usleep(120000);
        select(0, NULL, NULL, NULL, &delay);
    }

    return 0;
}

