    struct gpiod_chip *chip;
    struct gpiod_line_request_data request_data = {
        .consumer = "grow-light-controller",
        .direction = GPIOD_LINE_DIR_OUT,
        .flags = GPIOD_LINE_FLAG_ACTIVE_LOW,
    };

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    relay_data.consumer_data = &relay_state;
    if (gpiod_line_request_dt(chip, RELAY_GPIO, &request_data, &relay_data) < 0) {
        perror("Failed to request GPIO line");
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(relay_data, GPIOD_LINE_STATE_HIGH);
}

void cleanup(void) {
    gpiod_line_release(relay_data);
    close(i2c_file);
    gpiod_chip_close(relay_data.chip);
}

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up and exiting\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int main(void) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_init();
    gpio_init();

    struct timeval delay = { .tv_sec = 2, .tv_usec = 0 };
    struct timeval last_read = { .tv_sec = 0, .tv_usec = 0 };

    while (1) {
        struct timeval now;
        gettimeofday(&now, NULL);

        if ((now.tv_sec - last_read.tv_sec) >= 2) {
            i2c_read_lux();
            log_lux("", buf[0] << 8 | buf[1]);
            last_read = now;
        }

        usleep(120000);
        select(0, NULL, NULL, NULL, &delay);
    }

    return 0;
}
