code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/types.h>
#include <linux/spi/spidev.h>
#include <string.h>
#include <time.h>
#include <syslog.h>
#include <pthread.h>
#include <libgpiod.h>
#include <paho-mqtt3c/mqtt.h>

#define TAG "mqtt_relay"
#define CLIENT_ID "relay_controller_1"
#define BROKER "localhost"
#define PORT 1883
#define KEEPALIVE 60
#define GPIO_LINE "gpiochip0\0/line17"
#define TOPIC "home/lights/control"

static gpiod_line_request_lines_data_t lines_data = { .lines = { { .direction = GPIOD_LINE_DIR_OUT } } };
static gpiod_line_handle_t *gpio_line_handle;
static struct mqtt_client *client;
static pthread_t mqtt_thread;
static int gpio_fd, mqtt_rc;

void gpio_init(void) {
    gpio_fd = gpiod_open_name_with_label(GPIO_LINE, "rpi-relay");
    if (gpio_fd < 0) {
        syslog(LOG_ERR, "Failed to open GPIO line: %s", gpiod_strerror(gpio_fd));
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_lines(gpio_fd, 1, &lines_data, GPIOD_LINE_REQUEST_DIRECTION) < 0) {
        syslog(LOG_ERR, "Failed to request GPIO line direction: %s", gpiod_strerror(gpio_fd));
        exit(EXIT_FAILURE);
    }

    gpio_line_handle = lines_data.lines;
    gpiod_line_set_value(gpio_line_handle, 0);
}

void mqtt_init(void) {
    mqtt_rc = mqtt_create(&client, CLIENT_ID, MQTT_ASYNC_CLIENT, NULL);
    if (mqtt_rc != MQTT_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to create MQTT client: %s", mqtt_strerror(client, mqtt_rc));
        exit(EXIT_FAILURE);
    }

    mqtt_rc = mqtt_set_keepalive(client, KEEPALIVE, KEEPALIVE, 0);
    if (mqtt_rc != MQTT_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to set MQTT keepalive: %s", mqtt_strerror(client, mqtt_rc));
        exit(EXIT_FAILURE);
    }

    mqtt_rc = mqtt_connect(client, BROKER, PORT, MQTT_CONNECT_CLEAN_SESSION);
    if (mqtt_rc != MQTT_ERR_SUCCESS) {
        syslog(LOG_INFO, "Failed to connect to MQTT broker: %s", mqtt_strerror(client, mqtt_rc));
    } else {
        syslog(LOG_INFO, "Connected to MQTT broker");
        mqtt_rc = mqtt_subscribe(client, TOPIC, 0);
        if (mqtt_rc != MQTT_ERR_SUCCESS) {
            syslog(LOG_ERR, "Failed to subscribe to MQTT topic: %s", mqtt_strerror(client, mqtt_rc));
            mqtt_disconnect(client);
            exit(EXIT_FAILURE);
        }
    }
}

void mqtt_callback(struct mqtt_client *client, void *userdata, int rc, const char *topic, int qos, const char *payload, size_t len) {
    if (rc != MQTT_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT callback error: %s", mqtt_strerror(client, rc));
        return;
    }

    char *payload_str = malloc(len + 1);
    if (!payload_str) {
        syslog(LOG_ERR, "Failed to allocate memory for payload");
        return;
    }

    strncpy(payload_str, payload, len);
    payload_str[len] = '\0';

    if (strcmp(payload_str, "ON") == 0) {
        gpiod_line_set_value(gpio_line_handle, 1);
        syslog(LOG_INFO, "Relay ON");
    } else if (strcmp(payload_str, "OFF") == 0) {
        gpiod_line_set_value(gpio_line_handle, 0);
        syslog(LOG_INFO, "Relay OFF");
    } else {
        syslog(LOG_ERR, "Invalid or empty payload: %s", payload_str);
    }

    free(payload_str);
}

void mqtt_loop(void *arg) {
    while (1) {
        mqtt_rc = mqtt_yield(client, 1000, MQTT_YIELD_WAIT_FOR_MESSAGE);
        if (mqtt_rc != MQTT_ERR_SUCCESS) {
            if (mqtt_rc == MQTT_ERR_DISCONNECTED) {
                sleep(5);
                mqtt_init();
            }
        }
    }
}

void sigint_handler(int sig) {
    syslog(LOG_INFO, "Received SIGINT or SIGTERM, shutting down");
    gpiod_line_set_value(gpio_line_handle, 0);
    mqtt_disconnect(client);
    mqtt_destroy(client);
    gpiod_line_release(gpio_fd, &lines_data);
    gpiod_close(gpio_fd);
    gpiod_cleanup();
    syslog_close();
    exit(EXIT_SUCCESS);
}

int main(void) {
    openlog(TAG, LOG_PID | LOG_NDELAY, LOG_USER);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    gpio_init();
    mqtt_init();

    pthread_create(&mqtt_thread, NULL, mqtt_loop, NULL);

    while (1) {
        sleep(1);
    }

    return 0;
}

