```

Here's the C code:

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/types.h>
#include <gpiod.h>

#define SERVO_MIN_PWM 500
#define SERVO_MAX_PWM 2500
#define SERVO_PERIOD_US 20000
#define SERVO_DUTY_CYCLE_US(duty_us) ((duty_us * 1000000) / SERVO_PERIOD_US)

int main() {
    gpiod_line_request_lines(1, "servos", NULL, GPIOD_LINE_REQUEST_DIR_OUT, GPIOD_LINE_STATE_LOW, NULL);
    gpiod_line_request_lines(5, "pwm_channels", NULL, GPIOD_LINE_REQUEST_DIR_OUT, GPIOD_LINE_STATE_LOW, NULL);

    int servo_pins[] = {7, 8, 9, 10, 11};
    int servo_duties[] = {SERVO_DUTY_CYCLE_US(1000), SERVO_DUTY_CYCLE_US(1500), SERVO_DUTY_CYCLE_US(2000), SERVO_DUTY_CYCLE_US(500), SERVO_DUTY_CYCLE_US(2500)};

    for (int i = 0; i < 5; ++i) {
        gpiod_line_set_value_cansleep(gpiod_get_line(1, servo_pins[i]), servo_duties[i] > SERVO_MAX_PWM ? SERVO_MAX_PWM : (servo_duties[i] < SERVO_MIN_PWM ? SERVO_MIN_PWM : servo_duties[i]));
        usleep(3000000); // Wait for 3 seconds
    }

    for (int i = 0; i < 5; ++i) {
        gpiod_line_set_value_cansleep(gpiod_get_line(1, servo_pins[i]), GPIOD_LINE_STATE_LOW);
    }

    gpiod_line_release_lines(1, servo_pins, 5);
    gpiod_line_release_lines(5, servo_pins, 5);

    return 0;
}
