#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/types.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <pthread.h>
#include <sys/time.h>

#define MOTOR_A_PWM_GPIO 17
#define MOTOR_A_DIR_GPIO 18
#define MOTOR_B_PWM_GPIO 22
#define MOTOR_B_DIR_GPIO 23
#define ENCODER_A_PHASE_A_GPIO 4
#define ENCODER_A_PHASE_B_GPIO 5
#define ENCODER_B_PHASE_A_GPIO 6
#define ENCODER_B_PHASE_B_GPIO 12
#define TICKS_PER_REVOLUTION 64
#define TICK_PERIOD_US 10000
#define TICK_STALL_THRESHOLD 2000000
#define PWM_FREQ 10000
#define TARGET_RPM 50
#define PWM_MAX 255

gpiod_line_request_lines_data_v1 lines_data = {
    .lines = (struct gpiod_line_request_data_v1[]) {
        [MOTOR_A_PWM_GPIO] = { .direction = GPIOD_LINE_DIR_OUT, .active_low = 0 },
        [MOTOR_A_DIR_GPIO] = { .direction = GPIOD_LINE_DIR_OUT, .active_low = 0 },
        [MOTOR_B_PWM_GPIO] = { .direction = GPIOD_LINE_DIR_OUT, .active_low = 0 },
        [MOTOR_B_DIR_GPIO] = { .direction = GPIOD_LINE_DIR_OUT, .active_low = 0 },
        [ENCODER_A_PHASE_A_GPIO] = { .direction = GPIOD_LINE_DIR_IN, .debounce = 10 },
        [ENCODER_A_PHASE_B_GPIO] = { .direction = GPIOD_LINE_DIR_IN, .debounce = 10 },
        [ENCODER_B_PHASE_A_GPIO] = { .direction = GPIOD_LINE_DIR_IN, .debounce = 10 },
        [ENCODER_B_PHASE_B_GPIO] = { .direction = GPIOD_LINE_DIR_IN, .debounce = 10 },
    },
};

struct motor_data {
    gpiod_line_handle_v1 pwm;
    gpiod_line_handle_v1 dir;
    int32_t ticks;
    struct timespec last_tick;
};

void motor_init(struct motor_data *motor, int gpio_pwm, int gpio_dir) {
    int ret;

    ret = gpiod_chip_open_byname("gpiochip0");
    if (ret < 0) {
        perror("Failed to open gpiochip0");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_array_v1(ret, &lines_data, 1);
    if (ret < 0) {
        perror("Failed to request GPIO lines");
        exit(EXIT_FAILURE);
    }

    motor->pwm = lines_data.lines[gpio_pwm];
    motor->dir = lines_data.lines[gpio_dir];

    gpiod_line_set_value_cansleep(motor->pwm, 0);
    gpiod_line_set_value_cansleep(motor->dir, 0);

    motor->ticks = 0;
    gettimeofday(&motor->last_tick, NULL);
}

void motor_stop(struct motor_data *motor) {
    gpiod_line_set_value_cansleep(motor->pwm, 0);
    gpiod_line_set_value_cansleep(motor->dir, 0);
}

void motor_set_speed(struct motor_data *motor, double speed) {
    int pwm_duty;
    double kp = 1.0;
    double error, prev_error = 0.0, integral = 0.0;
    struct timespec now;
    double period_s = TICK_PERIOD_US * 1e-6;

    while (1) {
        gettimeofday(&now, NULL);
        if (now.tv_sec - motor->last_tick.tv_sec > TICK_STALL_THRESHOLD / 1e6) {
            printf("Encoder stall detected\n");
            motor_stop(motor);
            break;
        }

        if (gpiod_line_get_value_cansleep(ENCODER_A_PHASE_A_GPIO) == 1) {
            motor->ticks++;
            gettimeofday(&motor->last_tick, NULL);
        }

        error = TARGET_RPM * period_s - (motor->ticks * TICK_PERIOD_US * TICKS_PER_REVOLUTION * 60.0) / now.tv_sec - period_s;
        integral += error * period_s;

        pwm_duty = PWM_MAX * (kp * error + integral);
        if (pwm_duty < 0) {
            pwm_duty = 0;
        } else if (pwm_duty > PWM_MAX) {
            pwm_duty = PWM_MAX;
        }

        gpiod_line_set_value_cansleep(motor->pwm, pwm_duty * PWM_MAX / TARGET_RPM * period_s / TICK_PERIOD_US);
        gpiod_line_set_value_cansleep(motor->dir, (error > 0) ? 1 : 0);

        usleep(TICK_PERIOD_US - (period_s * 1e6));
    }

    motor_stop(motor);
}

void cleanup(void) {
    int i;

    for (i = 0; i < GPIOD_ARRAY_SIZE(lines_data.lines); i++) {
        if (lines_data.lines[i].requested) {
            gpiod_line_release_request(lines_data.lines[i].request);
        }
    }

    gpiod_chip_close(lines_data.chip);
}

void* motor_control(void *arg) {
    struct motor_data motors[2];

    motor_init(&motors[0], MOTOR_A_PWM_GPIO, MOTOR_A_DIR_GPIO);
    motor_init(&motors[1], MOTOR_B_PWM_GPIO, MOTOR_B_DIR_GPIO);

    motor_set_speed(&motors[0], TARGET_RPM);
    motor_set_speed(&motors[1], TARGET_RPM);

    while (1) {
        printf("Motor A RPM: %f, PWM duty cycle: %d\n", TARGET_RPM * 60.0 * motors[0].ticks / (now.tv_sec - motor->last_tick.tv_sec),
               (int)(motors[0].pwm_duty * 100.0));
        printf("Motor B RPM: %f, PWM duty cycle: %d\n", TARGET_RPM * 60.0 * motors[1].ticks / (now.tv_sec - motor->last_tick.tv_sec),
               (int)(motors[1].pwm_duty * 100.0));
        usleep(100000);
    }

    motor_stop(&motors[0]);
    motor_stop(&motors[1]);

    cleanup();
    return NULL;
}

int main() {
    pthread_t thread;

    if (pthread_create(&thread, NULL, motor_control, NULL) != 0) {
        perror("Failed to create motor control thread");
        exit(EXIT_FAILURE);
    }

    pthread_join(thread, NULL);

    return 0;
}

