code:
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <unistd.h>
#include <time.h>
#include <sys/mman.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

#define BH1750_ADDR 0x23
#define LED_GPIO 17

static const char *log_file = "chicken_coop_log.txt";

void log_message(const char *message) {
    FILE *log_fd = fopen(log_file, "a");
    if (log_fd) {
        fprintf(log_fd, "%s\n", message);
        fclose(log_fd);
    } else {
        perror("fopen");
    }
}

int init_i2c(int *i2c_fd) {
    const char *i2c_bus = "/dev/i2c-1";
    *i2c_fd = open(i2c_bus, O_RDWR);
    if (*i2c_fd < 0) {
        perror("open");
        return -1;
    }

    if (ioctl(*i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl");
        close(*i2c_fd);
        return -1;
    }

    return 0;
}

int read_lux(int i2c_fd, uint16_t *lux) {
    uint8_t buf[2];
    if (i2c_smbus_read_word_data(i2c_fd, 0x23, 0x24) < 0) {
        perror("i2c_smbus_read_word_data");
        return -1;
    }

    *lux = (buf[0] << 8) | buf[1];
    return 0;
}

int init_gpio(int *gpio_fd, uint32_t *gpio_line) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_byname");
        return -1;
    }

    line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(line, "light_controller", GPIOD_LINE_ACTIVE_HIGH);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    *gpio_fd = line->fd;
    *gpio_line = line->number;
    return 0;
}

void set_gpio(int gpio_fd, uint32_t gpio_line, int state) {
    struct gpiod_value_callback callback = {
        .cb = [](struct gpiod_line *line, int value, void *user_data) {
            (void)line;
            (void)user_data;
        },
    };

    gpiod_line_set_value(gpio_fd, gpio_line, state);
    gpiod_line_set_value_callback(gpio_fd, gpio_line, &callback);
}

void cleanup(int i2c_fd, int gpio_fd, uint32_t gpio_line) {
    close(i2c_fd);
    gpiod_line_release(gpio_fd, gpio_line);
    gpiod_chip_close(gpiod_chip_get_chipdata(gpiod_chip_open_byname("gpiochip0")));
}

int main() {
    int i2c_fd = -1, gpio_fd = -1;
    uint32_t gpio_line = 0;
    uint16_t lux = 0;
    time_t current_time;
    struct tm *time_info;
    int prev_relay_state = -1;

    if (init_i2c(&i2c_fd) < 0) {
        return 1;
    }

    if (init_gpio(&gpio_fd, &gpio_line) < 0) {
        cleanup(i2c_fd, gpio_fd, gpio_line);
        return 1;
    }

    while (1) {
        if (read_lux(i2c_fd, &lux) < 0) {
            log_message("Sensor non-response");
            set_gpio(gpio_fd, gpio_line, prev_relay_state);
            cleanup(i2c_fd, gpio_fd, gpio_line);
            return 1;
        }

        time(&current_time);
        time_info = localtime(&current_time);

        if (lux < 50 && prev_relay_state == -1) {
            set_gpio(gpio_fd, gpio_line, 1);
            prev_relay_state = 1;
            log_message(asctime(time_info));
            log_message(asprintf("Lux = %d, Relay = ON", lux));
        } else if (lux > 200 && prev_relay_state == 1) {
            set_gpio(gpio_fd, gpio_line, 0);
            prev_relay_state = 0;
            log_message(asctime(time_info));
            log_message(asprintf("Lux = %d, Relay = OFF", lux));
        }

        sleep(5);
    }

    cleanup(i2c_fd, gpio_fd, gpio_line);
    return 0;
}

