```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <time.h>
#include <linux/types.h>
#include <gpiod.h>

#define GPIO_BUS_WIDTH 32
#define TOUCH_GPIO 4
#define RELAY_GPIO 17

static gpiod_line_request_lines_data_v1 lines_data = {
    .lines = (uint32_t[]){TOUCH_GPIO, RELAY_GPIO},
    .count = 2,
};

static gpiod_line_request_flags_v1 flags = GPIOD_LINE_REQUEST_INPUT |
                                           GPIOD_LINE_REQUEST_DEBOUNCE;

static gpiod_line_data_v1 touch_data;
static gpiod_line_data_v1 relay_data;

void sigint_handler(int signum) {
    gpiod_line_set_value_cansleep(relay_fd, 0);
    gpiod_line_release(touch_fd);
    gpiod_line_release(relay_fd);
    exit(0);
}

int main() {
    int touch_fd, relay_fd;
    struct timespec ts;
    int touch_state = 0;
    int relay_state = 0;

    signal(SIGINT, sigint_handler);

    touch_fd = gpiod_open_name_v1("gpiochip0", TOUCH_GPIO);
    if (touch_fd < 0) {
        perror("Failed to open touch GPIO");
        return 1;
    }

    relay_fd = gpiod_open_name_v1("gpiochip0", RELAY_GPIO);
    if (relay_fd < 0) {
        perror("Failed to open relay GPIO");
        gpiod_line_release(touch_fd);
        return 1;
    }

    if (gpiod_line_request_dbus_v1(touch_fd, &lines_data, &flags, &touch_data) < 0) {
        perror("Failed to request touch GPIO");
        gpiod_line_release(relay_fd);
        gpiod_line_release(touch_fd);
        return 1;
    }

    if (gpiod_line_request_dbus_v1(relay_fd, &lines_data, &flags, &relay_data) < 0) {
        perror("Failed to request relay GPIO");
        gpiod_line_release(touch_fd);
        gpiod_line_release(relay_fd);
        return 1;
    }

    while (1) {
        gpiod_line_get_value_cansleep(touch_fd, &touch_state);
        if (touch_state) {
            if (!relay_state) {
                gpiod_line_set_value_cansleep(relay_fd, 1);
                relay_state = 1;
                printf("%s: RELAY ON\n", ctime(&ts.tv_sec));
            }
        } else {
            if (relay_state) {
                gpiod_line_set_value_cansleep(relay_fd, 0);
                relay_state = 0;
                printf("%s: RELAY OFF\n", ctime(&ts.tv_sec));
            }
        }

        nanosleep(&(struct timespec){10 * NANOSECONDS_PER_MILLISECOND, 0}, &ts);
    }

    gpiod_line_release(touch_fd);
    gpiod_line_release(relay_fd);

    return 0;
}
```

This code opens the GPIO pins for the touch sensor and relay, requests them as inputs, and sets up a debouncing mechanism for the touch sensor. It then enters an infinite loop where it reads the touch sensor state, toggles the relay state if necessary, and sleeps for 10ms before checking the sensor again. The program logs the relay state changes with an ISO-8601 timestamp.

The SIGINT handler turns off the relay, releases the GPIO lines, and exits the program.

