static gpiod_line_request_data_t flow_sensor_req;
static gpiod_line_request_data_t solenoid_req;
static pthread_mutex_t counter_mutex = PTHREAD_MUTEX_INITIALIZER;
static int pulse_count = 0;
static FILE *log_file = NULL;

void flow_sensor_cb(struct gpiod_line_request *request, int value,
                    struct gpiod_line_event_info *info) {
    pthread_mutex_lock(&counter_mutex);
    pulse_count += value;
    pthread_mutex_unlock(&counter_mutex);
}

void solenoid_cb(struct gpiod_line_request *request, int value,
                 struct gpiod_line_event_info *info) {
    // Solenoid state change handling goes here
}

void log_event(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_string[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s: %s\n", time_string, message);
}

void flow_sensor_init() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line_request_config config = {0};

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_configure_chan(chip, FLOW_SENSOR_GPIO, &config);
    if (ret < 0) {
        perror("Failed to configure flow sensor GPIO");
        gpiod_chip_release(chip);
        exit(EXIT_FAILURE);
    }

    config.flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_RISING |
                   GPIOD_LINE_REQUEST_DEBOUNCE_JITTER;
    config.debounce_jitter_ns = FLOW_SENSOR_DEBOUNCE_MS * 1000000;
    config.callback = &flow_sensor_cb;

    ret = gpiod_line_request_configure_chan(chip, FLOW_SENSOR_GPIO, &config);
    if (ret < 0) {
        perror("Failed to reconfigure flow sensor GPIO");
        gpiod_line_request_free(&flow_sensor_req);
        gpiod_chip_release(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_get_data(flow_sensor_req.request, &flow_sensor_req);
}

void solenoid_init() {
    int ret;
    struct gpiod_chip *chip;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_configure_chan(chip, SOLENOID_GPIO, NULL);
    if (ret < 0) {
        perror("Failed to configure solenoid GPIO");
        gpiod_chip_release(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_get_data(solenoid_req.request, &solenoid_req);
}

void log_init() {
    if ((log_file = fopen("water_flow.log", "w")) == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void sigint_handler(int sig) {
    log_event("Received SIGINT");
    solenoid_set_value(SOLENOID_GPIO, 1);
    fclose(log_file);
    pthread_mutex_destroy(&counter_mutex);
    gpiod_line_request_free(&flow_sensor_req);
    gpiod_line_request_free(&solenoid_req);
    gpiod_chip_release(flow_sensor_req.chip);
    gpiod_chip_release(solenoid_req.chip);
    gpiod_shutdown();
    exit(EXIT_SUCCESS);
}

void sigterm_handler(int sig) {
    log_event("Received SIGTERM");
    sigint_handler(SIGINT);
}

void flow_control() {
    double flow_rate_lpm = 0.0;
    double last_flow_rate_lpm = 0.0;
    struct timespec last_sample_time = {0};

    while (1) {
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        double elapsed_s = (now.tv_sec - last_sample_time.tv_sec) +
                           (now.tv_nsec - last_sample_time.tv_nsec) / 1000000000.0;

        pthread_mutex_lock(&counter_mutex);
        int current_pulse_count = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&counter_mutex);

        if (elapsed_s >= 1.0) {
            flow_rate_lpm = (current_pulse_count - pulse_count) / elapsed_s * 60.0;

            if (flow_rate_lpm > FLOW_THRESHOLD_LPM) {
                if (solenoid_get_value(SOLENOID_GPIO) == 1) {
                    solenoid_set_value(SOLENOID_GPIO, 0);
                    log_event("Solenoid closed");
                }
            } else if (flow_rate_lpm < FLOW_THRESHOLD_LPM - HYSTERESIS_LPM &&
                       solenoid_get_value(SOLENOID_GPIO) == 0) {
                solenoid_set_value(SOLENOID_GPIO, 1);
                log_event("Solenoid opened");
            }

            last_flow_rate_lpm = flow_rate_lpm;
            last_sample_time = now;
        }
    }
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    log_init();
    flow_sensor_init();
    solenoid_init();

    pthread_t flow_control_thread;
    if (pthread_create(&flow_control_thread, NULL, flow_control, NULL) != 0) {
        perror("Failed to create flow control thread");
        exit(EXIT_FAILURE);
    }

    flow_control();

    pthread_join(flow_control_thread, NULL);

    return EXIT_SUCCESS;
}

