int main() {
    gpiod_line_request_lines(1, "gpio23 gpio24 gpio18", GPIOD_LINE_REQUEST_DIRECTION_IN | GPIOD_LINE_REQUEST_EDGE_RISING | GPIOD_LINE_REQUEST_ACTIVE_LOW, NULL);
    gpio_init();

    int servo_fd = pigpio_open_wrap(NULL);
    if (servo_fd < 0) {
        fprintf(stderr, "Failed to open pigpio: %s\n", strerror(errno));
        return 1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(12345);
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

    int server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket < 0) {
        fprintf(stderr, "Failed to create socket: %s\n", strerror(errno));
        goto cleanup_servo;
    }

    if (bind(server_socket, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Failed to bind socket: %s\n", strerror(errno));
        goto cleanup_socket;
    }

    if (listen(server_socket, SOMAXCONN) < 0) {
        fprintf(stderr, "Failed to listen on socket: %s\n", strerror(errno));
        goto cleanup_bind;
    }

    pthread_t listener_thread;
    if (pthread_create(&listener_thread, NULL, tcp_listener, NULL) != 0) {
        fprintf(stderr, "Failed to create listener thread: %s\n", strerror(errno));
        goto cleanup_listen;
    }

    // Main loop or other code here...

cleanup_listen:
    close(server_socket);

cleanup_bind:
    gpiod_line_release_lines(1, "gpio23 gpio24 gpio18", NULL);

cleanup_socket:
    pigpio_terminate();

cleanup_servo:
    close(servo_fd);

    return 0;
}

void *tcp_listener(void *arg) {
    char buffer[BUFFER_SIZE];
    int client_socket;

    for (;;) {
        size_t client_len = sizeof(struct sockaddr_in);
        if ((client_socket = accept(server_socket, (struct sockaddr *)&server_addr, &client_len)) < 0) {
            if (errno != EAGAIN && errno != EWOULDBLOCK) {
                perror("accept");
            }
            continue;
        }

        ssize_t recv_len = recv(client_socket, buffer, BUFFER_SIZE - 1, 0);
        if (recv_len <= 0) {
            close(client_socket);
            continue;
        }

        buffer[recv_len] = '\0';
        double target_weight = strtod(buffer, NULL);
        struct dispense_data data = { target_weight, 0, 0 };

        // Dispense logic here...

        write_log(data);

        send(client_socket, buffer, recv_len, 0);
        close(client_socket);
    }

    pthread_exit(NULL);
}

