I'll provide a simple C program that uses the `libgpiod` library to achieve the requested functionality. This code assumes you have libgpiod installed on your Raspberry Pi. If not, you can install it using the following command:

```bash
sudo apt-get install libgpiod-dev
```

Here's the C code:

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/types.h>
#include <gpiod.h>

#define RELAY_GPIO 17
#define SENSOR_GPIO 4
#define DEBOUNCE_MS_DEFAULT 50

struct gpiod_line *sensor_line;
struct gpiod_line *relay_line;

void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_string[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s Relay: %s\n", time_string, state ? "ON" : "OFF");
}

void sigint_handler(int signum) {
    gpiod_line_set_value(relay_line, 0);
    gpiod_line_put(relay_line);
    gpiod_line_put(sensor_line);
    gpiod_chip_unclaim(sensor_chip);
    gpiod_chip_unclaim(relay_chip);
    exit(0);
}

int main(int argc, char *argv[]) {
    int debounce_ms = DEBOUNCE_MS_DEFAULT;
    int ret;
    struct gpiod_chip *sensor_chip;
    struct gpiod_chip *relay_chip;
    struct gpiod_line_request *sensor_req;
    struct gpiod_line_request *relay_req;
    struct timespec ts;
    int edge_detected = 0;

    if (argc > 2) {
        fprintf(stderr, "Usage: %s [-d <milliseconds>]\n", argv[0]);
        return 1;
    }

    if (argc == 2) {
        debounce_ms = atoi(argv[1]);
        if (debounce_ms <= 0) {
            fprintf(stderr, "Invalid debounce time. Must be a positive number.\n");
            return 1;
        }
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    sensor_chip = gpiod_chip_open_byname("gpiochip0");
    if (!sensor_chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    relay_chip = gpiod_chip_open_byname("gpiochip0");
    if (!relay_chip) {
        perror("Failed to open gpiochip0");
        gpiod_chip_put(sensor_chip);
        return 1;
    }

    sensor_line = gpiod_chip_get_line(sensor_chip, SENSOR_GPIO);
    if (!sensor_line) {
        perror("Failed to get line for sensor GPIO");
        gpiod_chip_put(relay_chip);
        gpiod_chip_put(sensor_chip);
        return 1;
    }

    relay_line = gpiod_chip_get_line(relay_chip, RELAY_GPIO);
    if (!relay_line) {
        perror("Failed to get line for relay GPIO");
        gpiod_line_put(sensor_line);
        gpiod_chip_put(sensor_chip);
        gpiod_chip_put(relay_chip);
        return 1;
    }

    gpiod_line_request_enable(sensor_line, GPIOD_LINE_REQUEST_INPUT);
    gpiod_line_request_edge(sensor_line, GPIOD_EDGE_RISING);
    gpiod_line_request_debounce(sensor_line, debounce_ms);
    sensor_req = gpiod_line_get_request(sensor_line);
    gpiod_line_request_put(sensor_req);

    gpiod_line_set_value(relay_line, 0);
    relay_req = gpiod_line_get_request(relay_line);
    gpiod_line_request_put(relay_req);

    while (1) {
        nanosleep(&ts, &ts);

        ret = gpiod_line_get_value(sensor_line);
        if (ret < 0) {
            perror("Failed to get sensor line value");
            break;
        }

        if (ret == 0 && !edge_detected) {
            gpiod_line_set_value(relay_line, 1);
            log_relay_state(1);
            edge_detected = 1;
        } else if (ret == 1 && edge_detected) {
            gpiod_line_set_value(relay_line, 0);
            log_relay_state(0);
            edge_detected = 0;
        }
    }

    gpiod_line_put(sensor_line);
    gpiod_line_put(relay_line);
    gpiod_chip_put(sensor_chip);
    gpiod_chip_put(relay_chip);

    return 0;
}
```

