I'll provide a simple C program using the `libgpiod` library to control an SG90 servo connected to GPIO18 (BCM18, physical pin 12) on a Raspberry Pi 4/5. The program reads keyboard input in raw terminal mode and adjusts the servo angle based on the input.

First, make sure you have libgpiod installed:

```sh
sudo apt-get install libgpiod-dev
```

Here's the code:

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define SERVO_MIN_PWM 500
#define SERVO_MAX_PWM 2500
#define SERVO_RESOLUTION 180
#define SERVO_INITIAL_ANGLE 90
#define SERVO_STEP 10
#define SERVO_GPIO_LINE "gpiochip0"
#define SERVO_GPIO_PIN "gpio18"
#define TERM_BAUD 9600

static gpiod_line_request_lines_data_v1 lines_data = { .lines = { { .direction = GPIOD_LINE_REQ_DIRECTION_OUT, } } };
static gpiod_line_data_v1 servo_data = { .flags = GPIOD_LINE_FLAG_ACTIVE_LOW };
static struct termios term_old, term_new;

void servo_pwm(int pwm)
{
    int ret;
    if (pwm < SERVO_MIN_PWM || pwm > SERVO_MAX_PWM) {
        fprintf(stderr, "Invalid PWM value: %d\n", pwm);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_set_value_cansleep(gpiod_get_line(gpiod_get_array_element_byname(gpiod_get_array_byname(NULL, SERVO_GPIO_LINE), SERVO_GPIO_PIN)), !!(pwm > SERVO_MAX_PWM / 2));
    if (ret < 0) {
        perror("gpiod_line_set_value_cansleep");
        exit(EXIT_FAILURE);
    }
    usleep(1000 * (pwm - SERVO_MIN_PWM));
}

void setup_terminal()
{
    tcgetattr(STDIN_FILENO, &term_old);
    bzero(&term_new, sizeof(term_new));
    cfsetispeed(&term_new, B9600);
    cfsetospeed(&term_new, B9600);
    term_new.c_lflag &= ~(ICANON | ECHO);
    tcsetattr(STDIN_FILENO, TCSANOW, &term_new);
}

void restore_terminal()
{
    tcsetattr(STDIN_FILENO, TCSANOW, &term_old);
}

void sigint_handler(int signum)
{
    gpiod_line_release(gpiod_get_line(gpiod_get_array_element_byname(gpiod_get_array_byname(NULL, SERVO_GPIO_LINE), SERVO_GPIO_PIN)));
    gpiod_line_request_release(gpiod_get_request(gpiod_get_array_byname(NULL, SERVO_GPIO_LINE), &lines_data));
    restore_terminal();
    exit(EXIT_SUCCESS);
}

int main()
{
    int angle = SERVO_INITIAL_ANGLE;
    int pwm;
    int ret;

    signal(SIGINT, sigint_handler);

    gpiod_context_autoclean ctx = gpiod_context_get_default();
    gpiod_line_request_array_data_v1 array_data = { .request_lines = &lines_data, };
    ret = gpiod_context_set_request_array(ctx, &array_data, 1);
    if (ret < 0) {
        perror("gpiod_context_set_request_array");
        exit(EXIT_FAILURE);
    }

    setup_terminal();

    while (1) {
        int c = getchar();
        switch (c) {
            case '+':
                angle += SERVO_STEP;
                if (angle > 180) angle = 180;
                break;
            case '-':
                angle -= SERVO_STEP;
                if (angle < 0) angle = 0;
                break;
            case 'q':
            case SIGINT:
                goto cleanup;
            default:
                continue;
        }

        pwm = SERVO_MIN_PWM + (angle * (SERVO_MAX_PWM - SERVO_MIN_PWM)) / SERVO_RESOLUTION;
        servo_pwm(pwm);
        printf("Angle: %d\n", angle);
    }

cleanup:
    gpiod_line_release(gpiod_get_line(gpiod_get_array_element_byname(gpiod_get_array_byname(NULL, SERVO_GPIO_LINE), SERVO_GPIO_PIN)));
    gpiod_line_request_release(gpiod_get_request(gpiod_get_array_byname(NULL, SERVO_GPIO_LINE), &lines_data));
    gpiod_context_put(ctx);

    return 0;
}
```

This program initializes the servo at 90°, increases the angle by 10° for each '+' key and decreases by 10° for each '-' key, clamps the angle between 0° and 180°, and ensures the computed pulse widths stay within the 500-2500µs range. It uses libgpiod to set the PWM on GPIO18 and reads keyboard input in raw terminal mode. The program also handles SIGINT and restores the terminal settings and driver library state on exit.

