#include <time.h>
#include <errno.h>
#include <string.h>
#include <libgpiod.h>

#define GPIO_LINE_NUMBER 17
#define DEBOUNCE_WINDOW 2000000
#define UPDATE_INTERVAL 5000000
#define LOG_FILE "motor_rpm.log"

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int nlines,
                                const char *const *lines, unsigned int flags)
{
    return gpiod_chip_request_lines(chip, nlines, lines, flags, NULL);
}

static void gpio_line_event_cb(struct gpiod_line *line, int event, void *user_data)
{
    struct timespec ts;
    static unsigned long long last_edge = 0;
    static unsigned long long edge_count = 0;
    static double rpm = 0.0;
    static FILE *log_file = NULL;
    static struct timespec last_update = {0};

    if (event != LINE_EVENT_EDGE_RISING)
        return;

    clock_gettime(CLOCK_MONOTONIC, &ts);
    if (ts.tv_sec - last_edge > DEBOUNCE_WINDOW) {
        edge_count++;
        last_edge = ts.tv_sec;
    }

    if (ts.tv_sec - last_update >= UPDATE_INTERVAL) {
        double elapsed_sec = (ts.tv_sec - last_update->tv_sec) +
                             (ts.tv_nsec - last_update->tv_nsec) / 1_ billion;
        rpm = (edge_count * 60.0) / elapsed_sec;
        edge_count = 0;
        last_update = ts;

        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&ts.tv_sec));
        if (log_file == NULL) {
            log_file = fopen(LOG_FILE, "w");
            if (!log_file) {
                perror("fopen");
                exit(EXIT_FAILURE);
            }
        }
        fprintf(log_file, "%s,%0.2f\n", timestamp, rpm);
        fflush(log_file);

        printf("%0.2f RPM\n", rpm);
    }
}

int main(void)
{
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("gpiochip_open_byname");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_NUMBER);
    if (!line) {
        perror("gpio_chip_get_line");
        gpiod_chip_put(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_active_low_output(line, GPIOD_LINE_REQUEST_DIRECTION_IN);
    if (ret < 0) {
        perror("gpio_line_request_active_low_output");
        gpiod_line_put(line);
        gpiod_chip_put(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_enable_edge_detect(line, GPIOD_EDGE_RISING);
    if (ret < 0) {
        perror("gpio_line_enable_edge_detect");
        gpiod_line_set_value(line, 0);
        gpiod_line_put(line);
        gpiod_chip_put(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_event_callback(line, gpio_line_event_cb, NULL);

    signal(SIGINT, [](int signum) {
        gpiod_line_set_value(line, 0);
        gpiod_line_put(line);
        gpiod_chip_put(chip);
        fclose(log_file);
        exit(EXIT_SUCCESS);
    });

    signal(SIGTERM, [](int signum) {
        gpiod_line_set_value(line, 0);
        gpiod_line_put(line);
        gpiod_chip_put(chip);
        fclose(log_file);
        exit(EXIT_SUCCESS);
    });

    while (1) {
        usleep(100000);
    }

    gpiod_line_put(line);
    gpiod_chip_put(chip);

    return EXIT_SUCCESS;
}

