#include <gpiod.h>

#define GPIO_TOUCH 4
#define GPIO_RELAY 17
#define TOUCH_THRESHOLD 10
#define POLL_INTERVAL 50
#define MAX_TOUCH_COUNT 200

volatile sig_atomic_t running = 1;
struct gpiod_line *touch_line, *relay_line;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    int ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    touch_line = gpiod_chip_get_line(chip, GPIO_TOUCH);
    if (!touch_line) {
        perror("Failed to get line for GPIO");
        gpiod_chip_close(chip);
        return 1;
    }

    relay_line = gpiod_chip_get_line(chip, GPIO_RELAY);
    if (!relay_line) {
        perror("Failed to get line for GPIO");
        gpiod_line_put(touch_line);
        gpiod_chip_close(chip);
        return 1;
    }

    gpiod_line_request_output(relay_line, GPIOD_LINE_ACTIVE_HIGH);
    gpiod_line_set_value(relay_line, 0);

    int touch_count = 0;
    struct timespec ts;
    while (running) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        ts.tv_sec += POLL_INTERVAL / 1000000000;
        ts.tv_nsec = (POLL_INTERVAL % 1000000000) * 1000;
        nanosleep(&ts, NULL);

        ret = gpiod_line_get_value(touch_line);
        if (ret < 0) {
            perror("Failed to get touch state");
            goto cleanup;
        }

        if (ret == 1) {
            touch_count++;
            if (touch_count > MAX_TOUCH_COUNT) {
                printf("Touch detected for too long, forcing relay OFF\n");
                gpiod_line_set_value(relay_line, 0);
                touch_count = 0;
            }
        } else {
            touch_count = 0;
        }

        if (touch_count > TOUCH_THRESHOLD) {
            gpiod_line_set_value(relay_line, 1);
        } else {
            gpiod_line_set_value(relay_line, 0);
        }
    }

cleanup:
    gpiod_line_put(touch_line);
    gpiod_line_put(relay_line);
    gpiod_chip_close(chip);

    return 0;
}

