    touch_line = gpiod_chip_get_line(chip, GPIO_TOUCH);
    if (!touch_line) {
        perror("Failed to get line for GPIO");
        gpiod_chip_close(chip);
        return 1;
    }

    relay_line = gpiod_chip_get_line(chip, GPIO_RELAY);
    if (!relay_line) {
        perror("Failed to get line for GPIO");
        gpiod_line_put(touch_line);
        gpiod_chip_close(chip);
        return 1;
    }

    gpiod_line_request_output(relay_line, GPIOD_LINE_ACTIVE_HIGH);
    gpiod_line_set_value(relay_line, 0);

    int touch_count = 0;
    struct timespec ts;
    while (running) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        ts.tv_sec += POLL_INTERVAL / 1000000000;
        ts.tv_nsec = (POLL_INTERVAL % 1000000000) * 1000;
        nanosleep(&ts, NULL);

        ret = gpiod_line_get_value(touch_line);
        if (ret < 0) {
            perror("Failed to get touch state");
            goto cleanup;
        }

        if (ret == 1) {
            touch_count++;
            if (touch_count > MAX_TOUCH_COUNT) {
                printf("Touch detected for too long, forcing relay OFF\n");
                gpiod_line_set_value(relay_line, 0);
                touch_count = 0;
            }
        } else {
            touch_count = 0;
        }

        if (touch_count > TOUCH_THRESHOLD) {
            gpiod_line_set_value(relay_line, 1);
        } else {
            gpiod_line_set_value(relay_line, 0);
        }
    }

cleanup:
    gpiod_line_put(touch_line);
    gpiod_line_put(relay_line);
    gpiod_chip_close(chip);

    return 0;
}
```

This code initializes the GPIO lines, sets up signal handlers for SIGINT and SIGTERM, and polls the touch sensor every 50ms. If the touch sensor is continuously HIGH for more than 10 seconds, it forces the relay OFF. The program releases resources on exit paths and handles errors from the library's API calls.

