#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <sys/time.h>
#include <getopt.h>
#include <signal.h>
#include <libgpiod.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BAUD 100000
#define RFID_CHIP_SELECT 0
#define LOCK1_GPIO 17
#define LOCK2_GPIO 27
#define BUTTON_GPIO 22
#define LOG_FILE "/var/log/door_access.log"
#define TAG_LENGTH 10
#define DEBOUNCE_MS 50
#define LOCK_ON_MS 5000

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int nlines,
                                const char *const *lines, unsigned int flags) {
    return gpiod_chip_get_lines_request_array(chip, nlines, lines, flags);
}

static void log_access(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_string[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(time_string, sizeof(time_string), "%Y-%m-%dT%H:%M:%S", timeinfo);
    fprintf(stderr, "%s: %s\n", time_string, message);
    fprintf(stderr, "%s\n", time_string);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s: %s\n", time_string, message);
        fclose(log_file);
    }
}

static int read_rfid(int spi_fd) {
    char rfid_data[TAG_LENGTH];
    struct spi_ioc_transfer tr = {
        .tx_buf = {RFID_CHIP_SELECT},
        .len = 1,
        .speed_hz = SPI_BAUD,
        .bits_per_word = 8,
    };
    struct spi_ioc_transfer *transfers = &tr;
    int ret;

    ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfers);
    if (ret < 1) {
        log_access("SPI read failure");
        return -1;
    }

    tr.rx_buf = rfid_data;
    tr.len = TAG_LENGTH;
    transfers = &tr;
    ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfers);
    if (ret < TAG_LENGTH) {
        log_access("Invalid tag (all zeros)");
        return -1;
    }

    return memcmp(rfid_data, VALID_TAG, TAG_LENGTH) == 0 ? 0 : -1;
}

static void handle_button(struct gpiod_line_request *button_req) {
    int value;
    struct timespec ts = {.tv_sec = 0, .tv_nsec = DEBOUNCE_MS * 1000};

    while (1) {
        gpiod_line_get_value(button_req, &value);
        if (value == 0) {
            nanosleep(&ts, NULL);
            if (gpiod_line_get_value(button_req, &value) == 0 && value == 0) {
                break;
            }
        }
    }
}

static void unlock_locks(struct gpiod_line_request *lock1_req,
                         struct gpiod_line_request *lock2_req) {
    gpiod_line_set_value(lock1_req, 0);
    gpiod_line_set_value(lock2_req, 0);
    usleep(LOCK_ON_MS * 1000);
    gpiod_line_set_value(lock1_req, 1);
    gpiod_line_set_value(lock2_req, 1);
}

int main(int argc, char *argv[]) {
    int spi_fd, ret;
    struct gpiod_chip *chip;
    struct gpiod_line_request *lock1_req, *lock2_req, *button_req;
    const char *valid_tag = "00112233445566";

    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return 1;
    }

    lock1_req = gpiod_line_request_get(chip, LOCK1_GPIO, "lock1");
    lock2_req = gpiod_line_request_get(chip, LOCK2_GPIO, "lock2");
    button_req = gpiod_line_request_get(chip, BUTTON_GPIO, "button");

    if (!lock1_req || !lock2_req || !button_req) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        gpiod_chip_put(chip);
        close(spi_fd);
        return 1;
    }

    gpiod_line_request_enable(lock1_req);
    gpiod_line_request_enable(lock2_req);
    gpiod_line_request_enable(button_req);

    signal(SIGINT, [](int signum) {
        gpiod_line_set_value(lock1_req, 1);
        gpiod_line_set_value(lock2_req, 1);
        fclose(log_file);
        close(spi_fd);
        gpiod_chip_put(chip);
        exit(0);
    });

    signal(SIGTERM, [](int signum) {
        gpiod_line_set_value(lock1_req, 1);
        gpiod_line_set_value(lock2_req, 1);
        fclose(log_file);
        close(spi_fd);
        gpiod_chip_put(chip);
        exit(0);
    });

    while (1) {
        if (read_rfid(spi_fd) == 0) {
            handle_button(button_req);
            unlock_locks(lock1_req, lock2_req);
            log_access("Successful entry");
        } else {
            log_access("Invalid tag");
        }
        usleep(100000);
    }

    gpiod_line_request_free(button_req);
    gpiod_line_request_free(lock1_req);
    gpiod_line_request_free(lock2_req);
    gpiod_chip_put(chip);
    close(spi_fd);

    return 0;
}

