#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <math.h>
#include <pthread.h>
#include <time.h>
#include <signal.h>
#include <sys/types.h>
#include <fcntl.h>
#include <sys/stat.h>

#include <wiringPi.h>
#include <pigpio.h>

#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20
#define ENCODER1_A 5
#define ENCODER1_B 6
#define ENCODER2_A 26
#define ENCODER2_B 19
#define PID_SAMPLE_TIME_MS 100
#define PWM_FREQ 100
#define TARGET_RPM 60
#define LOG_FILE "motor_log.csv"

volatile sig_atomic_t running = 1;
pthread_mutex_t encoder_mutex[4];
long encoder_counts[4] = {0};

void sigint_handler(int signum) {
    running = 0;
}

void sigterm_handler(int signum) {
    sigint_handler(signum);
}

void init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(MOTOR1_ENA, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENB, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN4, PI_OUTPUT);

    gpioSetMode(ENCODER1_A, PI_INPUT);
    gpioSetMode(ENCODER1_B, PI_INPUT);
    gpioSetMode(ENCODER2_A, PI_INPUT);
    gpioSetMode(ENCODER2_B, PI_INPUT);

    gpioSetEdgeDetect(ENCODER1_A, PI_BOTH_EDGE);
    gpioSetEdgeDetect(ENCODER1_B, PI_RISING_EDGE);
    gpioSetEdgeDetect(ENCODER2_A, PI_BOTH_EDGE);
    gpioSetEdgeDetect(ENCODER2_B, PI_RISING_EDGE);

    pthread_mutex_init(encoder_mutex, NULL);
}

long read_encoder(int gpio) {
    long state = gpioRead(gpio);
    long count = 0;
    long prev_state = state;

    pthread_mutex_lock(encoder_mutex + (gpio - ENCODER1_A));

    while (running) {
        long current_state = gpioRead(gpio);
        if (current_state != prev_state) {
            if (prev_state == 0 && current_state == 1) {
                count++;
            } else if (prev_state == 1 && current_state == 0) {
                count--;
            }
        }
        prev_state = current_state;
        usleep(10000);
    }

    pthread_mutex_unlock(encoder_mutex + (gpio - ENCODER1_A));

    return count;
}

void log_data(const char *format, ...) {
    va_list args;
    FILE *file = fopen(LOG_FILE, "a");

    if (!file) {
        perror("Failed to open log file");
        return;
    }

    va_start(args, format);
    vfprintf(file, format, args);
    va_end(args);

    fputc('\n', file);
    fflush(file);

    fclose(file);
}

void pid_controller(int motor) {
    double kp = 1.0;
    double ki = 0.01;
    double kd = 0.0;
    double setpoint = TARGET_RPM * 2 * M_PI;
    double error = 0.0;
    double integral = 0.0;
    double derivative = 0.0;
    double output = 0.0;
    double last_error = 0.0;
    double last_integral = 0.0;
    double last_derivative = 0.0;
    double last_counts[2] = {0};
    double dt = PID_SAMPLE_TIME_MS / 1000.0;

    while (running) {
        double current_counts[2] = {read_encoder(motor >= 1 ? ENCODER1_A : ENCODER2_A),
                                    read_encoder(motor >= 1 ? ENCODER1_B : ENCODER2_B)};

        pthread_mutex_lock(encoder_mutex + (motor >= 1 ? 0 : 2));
        error = setpoint - (current_counts[0] - last_counts[0]) * TARGET_RPM;
        integral += error * dt;
        derivative = (error - last_error) / dt;
        output = kp * error + ki * integral + kd * derivative;
        last_error = error;
        last_integral = integral;
        last_derivative = derivative;
        last_counts[0] = current_counts[0];
        pthread_mutex_unlock(encoder_mutex + (motor >= 1 ? 0 : 2));

        double duty_cycle = output * 100.0;
        if (duty_cycle < 0.0) {
            duty_cycle = 0.0;
        } else if (duty_cycle > 100.0) {
            duty_cycle = 100.0;
        }

        gpioWrite(motor >= 1 ? MOTOR1_ENA : MOTOR2_ENB, duty_cycle);

        usleep(PID_SAMPLE_TIME_MS * 1000);
    }
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    init_gpio();

    pthread_t threads[2];

    for (int i = 0; i < 2; ++i) {
        pthread_create(&threads[i], NULL, pid_controller, i + 1);
    }

    pthread_join(threads[0], NULL);
    pthread_join(threads[1], NULL);

    gpioTerm();

    log_data("RPM,P,I,D,Output\n");
    log_data("%d,%.4f,%.4f,%.4f,%.0f\n", TARGET_RPM, 1.0, 0.0, 0.0, 0.0);

    return 0;
}

