#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/time.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define MPR121_ADDR 0x5A // MPR121 I2C address
#define GPIO_17_LINE "gpiochip0 17" // GPIO 17 (BCM) line

static int mpr121_write_reg(int fd, unsigned char reg, unsigned char value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to MPR121");
        return -1;
    }
    return 0;
}

static int mpr121_read_reg(int fd, unsigned char reg, unsigned char *value) {
    char buf[1];
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write to MPR121");
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        perror("Failed to read from MPR121");
        return -1;
    }
    *value = buf[0];
    return 0;
}

static int mpr121_init(int *fd) {
    int ret;
    int i;
    char filename[32];

    snprintf(filename, sizeof(filename), "/dev/i2c-%d", 1);
    *fd = open(filename, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(*fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Failed to acquire I2C slave address");
        close(*fd);
        return -1;
    }

    // Soft reset
    ret = mpr121_write_reg(*fd, 0x0B, 0x00);
    if (ret < 0) {
        perror("Failed to perform soft reset");
        goto exit;
    }
    usleep(100000); // Wait for reset to complete

    // Configuration
    ret = mpr121_write_reg(*fd, 0x0C, 0x00); // Disable all electrodes
    if (ret < 0) {
        perror("Failed to disable electrodes");
        goto exit;
    }
    ret = mpr121_write_reg(*fd, 0x0D, 0x07); // Set filtering parameters
    if (ret < 0) {
        perror("Failed to set filtering parameters");
        goto exit;
    }
    ret = mpr121_write_reg(*fd, 0x0E, 0x0F); // Set touch and release thresholds
    if (ret < 0) {
        perror("Failed to set touch and release thresholds");
        goto exit;
    }
    ret = mpr121_write_reg(*fd, 0x0F, 0x01); // Enable run mode
    if (ret < 0) {
        perror("Failed to enable run mode");
        goto exit;
    }

    // Enable all electrodes
    for (i = 0; i < 12; i++) {
        ret = mpr121_write_reg(*fd, 0x0C | (i << 1), 0x01);
        if (ret < 0) {
            perror("Failed to enable electrode");
            goto exit;
        }
    }

    return 0;

exit:
    close(*fd);
    return -1;
}

static void gpio_cleanup(struct gpiod_chip *chip, gpiod_line_request_data_t *line_req) {
    gpiod_line_release(line_req);
    gpiod_chip_release(chip);
}

static void i2c_cleanup(int fd) {
    if (fd >= 0) {
        ioctl(fd, I2C_SLAVE, 0x00);
        close(fd);
    }
}

static void log_relay_state(const char *timestamp) {
    FILE *file = fopen("relay_log.txt", "a");
    if (file) {
        fprintf(file, "%s: Relay state: %s\n", timestamp, (gpio_get_value(relay_line_req->line) == 1) ? "HIGH" : "LOW");
        fclose(file);
    } else {
        perror("Failed to open relay_log.txt for writing");
    }
}

int main() {
    int mpr121_fd;
    struct gpiod_chip *gpio_chip;
    gpiod_line_request_data_t relay_line_req;
    unsigned char data[13];
    int ret;
    struct timeval tv;
    char timestamp[32];

    if (mpr121_init(&mpr121_fd) < 0) {
        fprintf(stderr, "Failed to initialize MPR121\n");
        return 1;
    }

    gpio_chip = gpiod_chip_open_byname("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        i2c_cleanup(mpr121_fd);
        return 1;
    }

    ret = gpiod_chip_get_line_request_data(gpio_chip, GPIO_17_LINE, &relay_line_req);
    if (ret < 0) {
        perror("Failed to get GPIO line request data");
        gpio_chip_release(gpio_chip);
        i2c_cleanup(mpr121_fd);
        return 1;
    }

    gpiod_line_request_enable(relay_line_req.line, GPIOD_LINE_REQUEST_DIRECTION_OUT | GPIOD_LINE_REQUEST_ACTIVE_LOW);

    while (1) {
        gettimeofday(&tv, NULL);
        snprintf(timestamp, sizeof(timestamp), "%ld.%06ld", (long)tv.tv_sec, (long)tv.tv_usec);

        ret = read(mpr121_fd, data, 13);
        if (ret < 0) {
            perror("Failed to read from MPR121");
            continue;
        }

        if (memcmp(data, "\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00", 12) != 0) {
            unsigned char state = data[12] & 0x0F;
            gpio_set_value(relay_line_req.line, state > 0);
            log_relay_state(timestamp);
        }

        usleep(50000); // Polling interval
    }

    gpio_cleanup(gpio_chip, &relay_line_req);
    i2c_cleanup(mpr121_fd);
    return 0;
}

