#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_BUS_WIDTH 32
#define GPIO_LINE_REQUEST_FLAGS (GPIOLIB_LINE_REQUEST_DIRECTION_OUT | GPIOLIB_LINE_REQUEST_ACTIVE_HIGH)

static gpiod_line_request *request_line(int gpio)
{
    struct gpiod_chip *chip;
    struct gpiod_line_request *request;
    int ret;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return NULL;
    }

    request = gpiod_chip_request_line(chip, gpio, "valve_control", GPIO_LINE_REQUEST_FLAGS);
    if (!request) {
        perror("Failed to request line");
        gpiod_chip_close(chip);
        return NULL;
    }

    ret = gpiod_line_request_enable(request);
    if (ret < 0) {
        perror("Failed to enable line request");
        gpiod_line_request_free(request);
        gpiod_chip_close(chip);
