#include <errno.h>
#include <linux/types.h>
#include <libgpiod.h>

#define PIR_GPIO 17
#define RELAY_GPIO 18
#define LOG_FILE "door_events.log"
#define RATE_LIMIT 2000 // 2 seconds in milliseconds

gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int nlines,
                          const char *const *lines, unsigned int flags);

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *pir, *relay;
    int ret, i;
    unsigned int val;
    time_t last_event = 0;
    struct timespec ts;

    // Initialize the GPIO library
    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    // Request lines for PIR and relay
    pir = gpiod_line_request_array(chip, 2, &PIR_GPIO, &RELAY_GPIO, GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_RISING);
    if (!pir || !relay) {
        perror("Failed to request GPIO lines");
        gpiod_chip_put(chip);
        return 1;
    }

    // Open log file
    int log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (log_fd == -1) {
        perror("Failed to open log file");
        gpiod_line_release(pir);
        gpiod_line_release(relay);
        gpiod_chip_put(chip);
        return 1;
    }

    // Set relay to off
    gpiod_line_set_value(relay, 0);

    while (1) {
        // Poll PIR sensor
        val = gpiod_line_get_value(pir);

        if (val == 1) { // Motion detected
            if (time(NULL) - last_event > RATE_LIMIT) { // Check rate limit
                last_event = time(NULL);

                // Unlock door
                gpiod_line_set_value(relay, 1);
                usleep(500 * 1000); // Wait 500ms
                gpiod_line_set_value(relay, 0);

                // Log event
                clock_gettime(CLOCK_REALTIME, &ts);
                fprintf(log_fd, "%lu.%06lu: Motion detected, door unlocked\n", (unsigned long)ts.tv_sec, (unsigned long)ts.tv_nsec / 1000000);
            }
        }

        // Sleep for 50ms
        nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = 50 * 1000 * 1000}, &ts);
    }

    // Clean up on exit or SIGINT
    close(log_fd);
    gpiod_line_release(pir);
    gpiod_line_release(relay);
    gpiod_chip_put(chip);

    return 0;
}

