I'll provide a basic example using the `libgpiod` library for GPIO handling and `time.h` for timing. The HX711 library is not included in the Raspberry Pi standard libraries, so I'll use a simplified approach to read data from the HX711. This example assumes you have the necessary dependencies installed:

```sh
sudo apt-get install libgpiod-dev libpthread-dev
```

Here's the C code:

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <time.h>
#include <string.h>
#include <errno.h>
#include <gpiod.h>

#define HX711_DATA_GPIO 4
#define HX711_CLOCK_GPIO 17
#define SOLENOID_GPIO 27

#define READ_INTERVAL_MS 500
#define TIMEOUT_MS 500
#define CALIBRATION_FILE "calibration.txt"
#define THRESHOLD_KG 10.0

struct hx711 {
    gpiod_line_request_linestate_t data_state;
    gpiod_line_request_linestate_t clock_state;
    int data_fd;
    int clock_fd;
};

struct calibration {
    double scale;
    double offset;
};

void hx711_init(struct hx711 *hx711) {
    gpiod_line_request_flags_t flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_HIGH | GPIOD_LINE_REQUEST_DISABLE;

    hx711->data_fd = gpiod_chip_open_byname("gpiochip0");
    if (hx711->data_fd < 0) {
        perror("Failed to open gpiochip0");
        exit(EXIT_FAILURE);
    }

    hx711->data_state = gpiod_line_request(hx711->data_fd, HX711_DATA_GPIO, flags);
    if (hx711->data_state < 0) {
        perror("Failed to request line for data");
        exit(EXIT_FAILURE);
    }

    hx711->clock_fd = gpiod_chip_open_byname("gpiochip0");
    if (hx711->clock_fd < 0) {
        perror("Failed to open gpiochip0");
        exit(EXIT_FAILURE);
    }

    hx711->clock_state = gpiod_line_request(hx711->clock_fd, HX711_CLOCK_GPIO, flags);
    if (hx711->clock_state < 0) {
        perror("Failed to request line for clock");
        exit(EXIT_FAILURE);
    }
}

void hx711_deinit(struct hx711 *hx711) {
    gpiod_line_release(hx711->data_fd, HX711_DATA_GPIO);
    gpiod_line_release(hx711->clock_fd, HX711_CLOCK_GPIO);
    close(hx711->data_fd);
    close(hx711->clock_fd);
}

double hx711_read(struct hx711 *hx711) {
    unsigned long long data = 0;
    unsigned long long clock_start = 0;
    unsigned long long clock_end = 0;
    unsigned long long data_start = 0;
    unsigned long long data_end = 0;
    double weight = 0.0;

    gpiod_line_set_value(hx711->clock_fd, HX711_CLOCK_GPIO, 1);
    clock_start = get_monotonic_ns();

    gpiod_line_set_value(hx711->data_fd, HX711_DATA_GPIO, 1);
    gpiod_line_set_value(hx711->clock_fd, HX711_CLOCK_GPIO, 0);

    while ((get_monotonic_ns() - clock_start) < TIMEOUT_MS * 1e6) {
        clock_end = get_monotonic_ns();
        data_start = clock_end;

        while ((get_monotonic_ns() - clock_end) < TIMEOUT_MS * 1e6) {
            if (gpiod_line_get_value(hx711->data_fd, HX711_DATA_GPIO)) {
                data_end = get_monotonic_ns();
                data |= (1ULL << ((data_end - data_start) % (8 * sizeof(unsigned long long))));
                break;
            }
        }
    }

    if (data_end == 0) {
        return NAN;
    }

    weight = (double)(data >> (8 * sizeof(unsigned long long) - 24)) / (1 << 24);

    return weight * hx711->scale + hx711->offset;
}

void load_calibration(struct calibration *calibration, FILE *file) {
    char line[128];
    if (fgets(line, sizeof(line), file) && sscanf(line, "%lf %lf", &calibration->scale, &calibration->offset) == 2) {
        return;
    }

    calibration->scale = 1.0;
    calibration->offset = 0.0;
}

void save_calibration(const struct calibration *calibration, FILE *file) {
    fprintf(file, "%.6f %.6f\n", calibration->scale, calibration->offset);
}

double startup_calibration(struct hx711 *hx711) {
    struct calibration calibration;
    double total = 0.0;
    int i;

    load_calibration(&calibration, NULL);

    for (i = 0; i < 100; ++i) {
        total += hx711_read(hx711);
        usleep(READ_INTERVAL_MS * 1000);
    }

    calibration.offset = total / 100.0;
    save_calibration(&calibration, fopen(CALIBRATION_FILE, "w"));

    return calibration.offset;
}

int main() {
    struct hx711 hx711;
    struct calibration calibration;
    double weight = 0.0;
    double offset = 0.0;
    FILE *calibration_file = NULL;
    FILE *log_file = NULL;
    int solenoid_state = 0;
    clockid_t clock_id;
    struct timespec ts;

    hx711_init(&hx711);

    calibration_file = fopen(CALIBRATION_FILE, "r");
    if (!calibration_file) {
        offset = startup_calibration(&hx711);
    } else {
        load_calibration(&calibration, calibration_file);
        fclose(calibration_file);
    }

    log_file = fopen("weight_log.txt", "w");

    clock_id = CLOCK_REALTIME;
    ts.tv_sec = 0;
    ts.tv_nsec = 0;

    while (1) {
        weight = hx711_read(&hx711);

        if (!isnan(weight)) {
            ts.tv_sec += READ_INTERVAL_MS / 1000;
            ts.tv_nsec += (READ_INTERVAL_MS % 1000) * 1e6;
            if (ts.tv_nsec >= 1e9) {
                ts.tv_sec++;
                ts.tv_nsec -= 1e9;
            }
            if (ts.tv_sec > 0 && ts.tv_nsec > 0) {
                fprintf(log_file, "%lld.%09ld: %.6f kg\n", ts.tv_sec, ts.tv_nsec, weight);
            }

            if (weight > THRESHOLD_KG) {
                solenoid_state = !solenoid_state;
                gpiod_line_set_value(hx711.data_fd, SOLENOID_GPIO, solenoid_state);
            }
        }

        nanosleep(&ts, &ts);
    }

    fclose(log_file);
    hx711_deinit(&hx711);

    return 0;
}
```

This code reads data from the HX711, computes weight using the provided scale and offset, and logs the readings to a file. It also engages the solenoid lock when the weight exceeds the specified threshold. The calibration data is loaded from a file or determined during startup if the file is missing or invalid.

To compile the code, use:

```sh
gcc -o weight_monitor weight_monitor.c -lgpiod -lpthread
```

This example assumes you have the necessary dependencies installed:

```sh
sudo apt-get install libgpiod-dev libpthread-dev
```

You may need to adjust the code to better suit your specific hardware setup and requirements.

