static gpiod_line_request_lines_data_v1 lines_data = {
    .lines = {
        [RAIN_SENSOR_GPIO] = GPIOD_LINE_REQUEST_INPUT,
        [MOTOR_IN1_GPIO] = GPIOD_LINE_REQUEST_DIRECTION_OUT,
        [MOTOR_IN2_GPIO] = GPIOD_LINE_REQUEST_DIRECTION_OUT,
        [MOTOR_PWM_GPIO] = GPIOD_LINE_REQUEST_DIRECTION_OUT,
    },
};

static gpiod_line_request *rain_sensor_request = NULL;
static gpiod_line_request *motor_requests[3] = { NULL };
static struct timespec next_check_time = { 0, 0 };

void motor_on(void) {
    gpiod_line_set_value(motor_requests[0], 1);
    gpiod_line_set_value(motor_requests[1], 0);
    gpiod_line_set_value(motor_requests[2], 1);

    struct timespec pwm_on_time = {
        .tv_sec = MOTOR_ON_DURATION_S,
        .tv_nsec = (MOTOR_ON_DURATION_S * 1e9) % 1e9
    };

    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);
    timespecadd(&now, &pwm_on_time, &now);

    while (now.tv_sec == next_check_time.tv_sec && now.tv_nsec >= next_check_time.tv_nsec) {
        gpiod_line_set_value(motor_requests[2], gpiod_line_get_value(motor_requests[2]) ^ 1);
        usleep(1e6 / 1000);
        clock_gettime(CLOCK_MONOTONIC, &now);
    }

    gpiod_line_set_value(motor_requests[0], 0);
    gpiod_line_set_value(motor_requests[1], 0);
