    motor_requests[1] = gpiod_chip_request_line_data_v1(0, MOTOR_IN2_GPIO, GPIOD_LINE_REQUEST_DIRECTION_OUT);
    motor_requests[2] = gpiod_chip_request_line_data_v1(0, MOTOR_PWM_GPIO, GPIOD_LINE_REQUEST_DIRECTION_OUT);

