#define HX711_DATA_PIN 23
#define HX711_SCK_PIN 24
#define SOLENOID_PIN 17

#define I2C_ADDR 0x48 // HX711 address

#define ADC_RESOLUTION 16
#define DATARATE 3200 // Hz
#define SAMPLES_PER_READ 256
#define SCALE_FACTOR 123 // Calibration factor for your specific setup

struct hx711 {
    int fd;
    void *mmio;
};

struct gpio_chip *gpio_chip_data;
struct gpio_desc *solenoid_desc;

struct hx711 hx711_obj;

void log_event(const char *event) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_string[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(stderr, "%s: %s\n", time_string, event);
    fprintf(stderr, "\n");

    FILE *file = fopen("stock_events.txt", "a");
    if (file) {
        fprintf(file, "%s: %s\n", time_string, event);
        fclose(file);
    }
}

int hx711_init() {
    int ret;
    int data_dir = GPIO_INPUT;
    int sck_dir = GPIO_OUTPUT;

    ret = gpiod_chip_open_byname(gpio_chip_data, "gpiochip0");
    if (ret < 0) {
        log_event("Failed to open GPIO chip");
        return -1;
    }

    ret = gpiod_direction_output_raw(gpio_chip_data, SOLENOID_PIN, 0);
    if (ret < 0) {
        log_event("Failed to set solenoid direction");
        goto cleanup_gpio;
    }

    ret = gpiod_direction_input(gpio_chip_data, HX711_DATA_PIN);
    if (ret < 0) {
        log_event("Failed to set data pin direction");
        goto cleanup_gpio;
    }

    ret = gpiod_direction_output_raw(gpio_chip_data, HX711_SCK_PIN, sck_dir);
    if (ret < 0) {
        log_event("Failed to set SCK pin direction");
        goto cleanup_gpio;
    }

    hx711_obj.fd = open("/dev/i2c-1", O_RDWR);
    if (hx711_obj.fd < 0) {
        log_event("Failed to open I2C bus");
        goto cleanup_gpio;
    }

    if (ioctl(hx711_obj.fd, I2C_SLAVE, I2C_ADDR) < 0) {
        log_event("Failed to set I2C slave address");
        goto cleanup_i2c;
    }

    hx711_obj.mmio = mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_SHARED, hx711_obj.fd, 0);
    if (hx711_obj.mmio == MAP_FAILED) {
        log_event("Failed to mmap I2C device");
        goto cleanup_i2c;
    }

    return 0;

cleanup_i2c:
    close(hx711_obj.fd);

cleanup_gpio:
    gpiod_chip_close(gpio_chip_data);

    return -1;
}

void hx711_deinit() {
    munmap(hx711_obj.mmio, 4096);
    close(hx711_obj.fd);
    gpiod_chip_close(gpio_chip_data);
}

int read_hx711() {
    int i, sum = 0;

    gpiod_set_value_cansleep(gpio_chip_data, HX711_SCK_PIN, 1);
    usleep(10);

    for (i = 0; i < SAMPLES_PER_READ; i++) {
        usleep(1000000 / DATARATE);
        sum += gpiod_get_value_cansleep(gpio_chip_data, HX711_DATA_PIN);
        gpiod_set_value_cansleep(gpio_chip_data, HX711_SCK_PIN, 0);
        usleep(10);
        gpiod_set_value_cansleep(gpio_chip_data, HX711_SCK_PIN, 1);
    }

    gpiod_set_value_cansleep(gpio_chip_data, HX711_SCK_PIN, 0);

    int value = (sum >> 3) * SCALE_FACTOR / (1 << ADC_RESOLUTION);

    return value;
}

int main() {
    int ret;
    int weight;

    gpio_chip_data = gpiod_chip_get_byname("gpiochip0");
    if (!gpio_chip_data) {
        log_event("Failed to get GPIO chip");
        return 1;
    }

    ret = hx711_init();
    if (ret < 0) {
        log_event("Failed to initialize HX711");
        goto cleanup_gpio;
    }

    while (1) {
        weight = read_hx711();
        if (weight < 100) {
            gpiod_set_value_cansleep(gpio_chip_data, SOLENOID_PIN, 1);
            usleep(5 * 1000000);
            gpiod_set_value_cansleep(gpio_chip_data, SOLENOID_PIN, 0);
        }
        printf("Weight: %d g\n", weight);
        sleep(1);
    }

cleanup_gpio:
    hx711_deinit();
    gpiod_chip_put(gpio_chip_data);

    return 0;
}

