#define DATA_GPIO 4
#define CLOCK_GPIO 17
#define LOCK_GPIO 27
#define TIMEOUT_MS 100
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "security.log"
#define THRESHOLD_KG 5.0

static int hx711_read(int data_gpio, int clock_gpio, int32_t *value) {
    int i, data = 0;

    gpiod_line_request_direction_output(data_gpio, GPIOD_LINE_ACTIVE_LOW);
    gpiod_line_set_value(data_gpio, 0);
    usleep(1);

    gpiod_line_request_direction_input(clock_gpio, GPIOD_LINE_ACTIVE_LOW);
    gpiod_line_set_debounce(clock_gpio, 1);

    for (i = 0; i < 24; i++) {
        gpiod_line_get_value(clock_gpio, &data);
        usleep(1000);

        if (data) {
            gpiod_line_get_value(data_gpio, &data);
            data <<= (i + 1);
        } else {
            gpiod_line_set_value(data_gpio, 1);
            usleep(1);
            gpiod_line_set_value(data_gpio, 0);
        }
    }

    *value = data;
    return 0;
}

static int hx711_init(int data_gpio, int clock_gpio) {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line_request_data data = {
        .consumer = "HX711",
        .direction = GPIOD_LINE_DIR_IN,
        .debounce = 1,
        .flags = GPIOD_LINE_FLAG_INPUT,
    };

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return -1;
    }

    ret = gpiod_line_request_array(chip, &data, 2, &data.consumer);
    if (ret < 0) {
        perror("Failed to request GPIO lines");
        goto cleanup_chip;
    }

    data.direction = GPIOD_LINE_DIR_OUT;
    data.flags = GPIOD_LINE_FLAG_OUTPUT;
    ret = gpiod_line_request_array(chip, &data, 1, &data.consumer);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        goto cleanup_lines;
    }

    return 0;

cleanup_lines:
    gpiod_line_release(data.lines[0]);
    gpiod_line_release(data.lines[1]);

cleanup_chip:
    gpiod_chip_close(chip);
    return -1;
}

static void sigint_handler(int signum) {
    int lock_fd = gpiod_line_get_fd(gpiod_line_get_byname("gpiochip0", "gpio27"));
    if (lock_fd >= 0) {
        gpiod_line_set_value(gpiod_line_get_byname("gpiochip0", "gpio27"), 0);
        close(lock_fd);
    }

    gpiod_chip_close(gpiod_chip_open_byname("gpiochip0"));
    exit(0);
}

int main() {
