```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_LINE "gpiochip0/gpio18/line"
#define CONFIG_FILE "watering.conf"
#define VALVE_OFF 0
#define VALVE_ON  1

volatile sig_atomic_t sig_received = 0;
struct gpiod_chip *chip;
struct gpiod_line *line;

void sigint_handler(int signum) {
    sig_received = 1;
}

int read_duration_from_file(const char *filename, int *duration) {
    FILE *file = fopen(filename, "r");
    char line[256];
    char *endptr;
    long int val;

    if (!file) {
        perror("fopen");
        return -1;
    }

    if (getline(&line, sizeof(line), file) == -1) {
        perror("getline");
        fclose(file);
        return -1;
    }

    val = strtol(line, &endptr, 10);
    if (*endptr != '\0' || val < 1 || val > 3600) {
        fprintf(stderr, "Invalid duration: %s\n", line);
        fclose(file);
        return -1;
    }

    *duration = (int)val;
    fclose(file);
    return 0;
}

int main(void) {
    int duration, ret, fd;
    struct timespec ts;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    if ((ret = read_duration_from_file(CONFIG_FILE, &duration)) < 0) {
        perror("read_duration_from_file");
        return 1;
    }

    if ((fd = open(CONFIG_FILE, O_RDONLY)) < 0) {
        perror("open");
        return 1;
    }

    if ((chip = gpiod_chip_open_by_name("gpiochip0")) == NULL) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    if ((line = gpiod_chip_get_line_by_name(chip, GPIO_LINE)) == NULL) {
        perror("gpiod_chip_get_line_by_name");
        goto close_chip;
    }

    if (gpiod_line_request_output(line, NULL) < 0) {
        perror("gpiod_line_request_output");
        goto release_line;
    }

    gpiod_line_set_value(line, VALVE_OFF);

    printf("Valve off\n");

    ts.tv_sec = duration;
    ts.tv_nsec = 0;
    gpiod_line_set_value(line, VALVE_ON);
    printf("Valve on (for %d seconds)\n", duration);

    nanosleep(&ts, NULL);

    gpiod_line_set_value(line, VALVE_OFF);
    printf("Valve off\n");

release_line:
    gpiod_line_release(line);
close_chip:
    gpiod_chip_close(chip);
    close(fd);

    while (!sig_received) {
        usleep(100000);
    }

    gpiod_line_set_value(line, VALVE_OFF);

    printf("Valve off (shutdown requested)\n");

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(fd);

    return 0;
}
```

This code reads the watering duration from a configuration file, initializes the GPIO line as an output, sets the line low (valve off), activates the valve by setting the line high, waits the configured duration using a signal-safe interruptible sleep, then sets the line low again. It also handles errors, installs a SIGINT/SIGTERM handler, and releases the GPIO line and chip resources on exit.

