#include <errno.h>
#include <libgpiod.h>

#define LEFT_SENSOR_GPIO 4
#define MIDDLE_SENSOR_GPIO 17
#define RIGHT_SENSOR_GPIO 27
#define LEFT_MOTOR_PWM_GPIO 22
#define RIGHT_MOTOR_PWM_GPIO 23
#define STOP_MOTOR_PWM_VALUE 0
#define BASE_SPEED 150
#define TURN_SPEED 75
#define SAMPLE_INTERVAL_US 10000
#define LOG_FILE "trace_log.txt"

struct gpiod_chip *chip;
struct gpiod_line *lines[3];
struct gpiod_line *left_motor_pwm;
struct gpiod_line *right_motor_pwm;
FILE *log_file;

void sigint_handler(int signum) {
    gpiod_line_set_value(left_motor_pwm, STOP_MOTOR_PWM_VALUE);
    gpiod_line_set_value(right_motor_pwm, STOP_MOTOR_PWM_VALUE);
    fclose(log_file);
    gpiod_chip_release(chip);
    exit(0);
}

int init_gpio() {
    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return -1;
    }

    lines[LEFT_SENSOR_GPIO] = gpiod_get_line_byname(chip, "gpio" STRINGIFY(LEFT_SENSOR_GPIO));
    lines[MIDDLE_SENSOR_GPIO] = gpiod_get_line_byname(chip, "gpio" STRINGIFY(MIDDLE_SENSOR_GPIO));
    lines[RIGHT_SENSOR_GPIO] = gpiod_get_line_byname(chip, "gpio" STRINGIFY(RIGHT_SENSOR_GPIO));

    left_motor_pwm = gpiod_get_line_byname(chip, "gpio" STRINGIFY(LEFT_MOTOR_PWM_GPIO));
    right_motor_pwm = gpiod_get_line_byname(chip, "gpio" STRINGIFY(RIGHT_MOTOR_PWM_GPIO));

    if (!left_motor_pwm || !right_motor_pwm) {
        perror("Failed to get motor PWM lines");
        gpiod_chip_release(chip);
        return -1;
    }

    if (gpiod_line_request_output(left_motor_pwm, "motor_left_pwm", GPIOD_LINE_REQUEST_DIRECTION_OUT) < 0 ||
        gpiod_line_request_output(right_motor_pwm, "motor_right_pwm", GPIOD_LINE_REQUEST_DIRECTION_OUT) < 0) {
        perror("Failed to request output for motor PWM lines");
        gpiod_chip_release(chip);
        return -1;
    }

    return 0;
}

int init_log() {
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        return -1;
    }

    return 0;
}

void log_state(const char *timestamp, int left_sensor, int middle_sensor, int right_sensor, int left_speed, int right_speed) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp_str[32];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S.%f", tm);

    fprintf(log_file, "%s,%d,%d,%d,%d,%d\n", timestamp_str, left_sensor, middle_sensor, right_sensor, left_speed, right_speed);
}

int main() {
    signal(SIGINT, sigint_handler);

    if (init_gpio() < 0 || init_log() < 0) {
        perror("Failed to initialize GPIO or log file");
        return -1;
    }

    int left_speed = BASE_SPEED;
    int right_speed = BASE_SPEED;
    uint64_t last_sample_time = 0;

    while (1) {
        uint64_t current_time = gpiod_get_ns(chip);
        if (current_time - last_sample_time >= SAMPLE_INTERVAL_US) {
            int left_sensor_state = gpiod_line_get_value(lines[LEFT_SENSOR_GPIO]);
            int middle_sensor_state = gpiod_line_get_value(lines[MIDDLE_SENSOR_GPIO]);
            int right_sensor_state = gpiod_line_get_value(lines[RIGHT_SENSOR_GPIO]);

            if (!middle_sensor_state) {
                left_speed = BASE_SPEED;
                right_speed = BASE_SPEED;
            } else if (left_sensor_state) {
                left_speed = TURN_SPEED;
            } else if (right_sensor_state) {
                right_speed = TURN_SPEED;
            }

            gpiod_line_set_value(left_motor_pwm, left_speed);
            gpiod_line_set_value(right_motor_pwm, right_speed);

            last_sample_time = current_time;
            char timestamp[32];
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
            log_state(timestamp, left_sensor_state, middle_sensor_state, right_sensor_state, left_speed, right_speed);
        }
    }

    return 0;
}

