#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/time.h>
#include <errno.h>
#include <string.h>
#include <sys/mman.h>
#include <gpiod.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define RELAY_GPIO 23

static const char *log_file = "grow_log.txt";

int i2c_file;
struct i2c_rdwr_ioctl_data data;
struct i2c_msg messages[2];

gpiod_line_request_linestate_cb_t relay_cb;
gpiod_line_request_data_t relay_req;
gpiod_line_state relay_state;

void relay_cb_handler(struct gpiod_line_request *req, int event, void *user_data) {
    if (event == LINEREQUEST_EVENT_ACTIVE_LOW_LEVEL_CHANGE) {
        FILE *log_file = fopen(log_file, "a");
        if (log_file) {
            struct timeval tv;
            gettimeofday(&tv, NULL);
            fprintf(log_file, "%lu: Relay state changed to %s\n", tv.tv_sec * 1000 + tv.tv_usec / 1000, relay_state.value_current ? "ON" : "OFF");
            fclose(log_file);
        }
    }
}

int read_lux() {
    messages[0].addr = BH1750_ADDR;
    messages[0].flags = 0;
    messages[0].len = 1;
    messages[0].buf = (char *) &data.write_buf;
    messages[0].buf_len = sizeof(data.write_buf);

    messages[1].addr = BH1750_ADDR;
    messages[1].flags = I2C_M_RD;
    messages[1].len = 2;
    messages[1].buf = (char *) &data.read_buf;
    messages[1].buf_len = sizeof(data.read_buf);

    if (ioctl(i2c_file, I2C_RDWR, &data) < 0) {
        perror("I2C read error");
        return -1;
    }

    return (data.read_buf[0] << 8) | data.read_buf[1];
}

int main() {
    int ret;

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_file, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to acquire bus access");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_chip_open_byname("gpiochip0");
    if (ret < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_enable(ret, RELAY_GPIO, GPIOD_LINE_REQUEST_DIRECTION_OUT | GPIOD_LINE_REQUEST_ACTIVE_LOW);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        exit(EXIT_FAILURE);
    }

    relay_req.consumer = "Grow Lamp Controller";
    relay_req.label = "Grow Lamp";
    relay_req.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUT | GPIOD_LINE_REQUEST_ACTIVE_LOW;
    relay_req.flags = GPIOD_LINE_REQUEST_LEGACY_FLAGS_NONE;

    ret = gpiod_line_request_set_cb(ret, RELAY_GPIO, relay_cb_handler, NULL);
    if (ret < 0) {
        perror("Failed to set GPIO line callback");
        exit(EXIT_FAILURE);
    }

    FILE *log_file = fopen(log_file, "w");
    if (log_file) {
        fclose(log_file);
    } else {
        perror("Failed to create log file");
        exit(EXIT_FAILURE);
    }

    while (1) {
        int lux = read_lux();
        if (lux < 150) {
            gpiod_line_set_value(ret, RELAY_GPIO, 1);
            printf("Lux: %d, Relay: ON\n", lux);
        } else {
            gpiod_line_set_value(ret, RELAY_GPIO, 0);
            printf("Lux: %d, Relay: OFF\n", lux);
        }
        usleep(180 * 1000);
    }

    gpiod_line_request_release(ret, RELAY_GPIO);
    gpiod_chip_close(ret);
    close(i2c_file);

    return 0;
}

