```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/gpio/consumer.h>
#include <time.h>
#include <signal.h>

#define SERVO_GPIO 18
#define LOCK_GPIO 21
#define UNLOCK_GPIO 22
#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500
#define DEBOUNCE_DELAY_MS 100

static gpiod_line_request_linestate_cb_t servo_cb;
static gpiod_line_request_callback servo_req;
static gpiod_line_request_linestate_cb_t lock_cb;
static gpiod_line_request_callback lock_req;
static gpiod_line_request_linestate_cb_t unlock_cb;
static gpiod_line_request_callback unlock_req;

void servo_state_cb(struct gpiod_line_request *req, int value,
                    struct gpiod_line_event_info *info) {
    if (value == 0) {
        servo_set_pulse(1000);
    }
}

void lock_state_cb(struct gpiod_line_request *req, int value,
                   struct gpiod_line_event_info *info) {
    if (value == 0) {
        if (servo_get_pulse() > SERVO_MIN_PULSE && servo_get_pulse() < SERVO_MAX_PULSE) {
            printf("Locking door...\n");
            servo_set_pulse(SERVO_MAX_PULSE);
        } else {
            printf("Error: Servo pulse width out of range.\n");
        }
    }
}

void unlock_state_cb(struct gpiod_line_request *req, int value,
                     struct gpiod_line_event_info *info) {
    if (value == 0) {
        if (servo_get_pulse() > SERVO_MIN_PULSE && servo_get_pulse() < SERVO_MAX_PULSE) {
            printf("Unlocking door...\n");
            servo_set_pulse(SERVO_MIN_PULSE);
        } else {
            printf("Error: Servo pulse width out of range.\n");
        }
    }
}

void servo_set_pulse(unsigned int pulse) {
    if (pulse < SERVO_MIN_PULSE || pulse > SERVO_MAX_PULSE) {
        printf("Error: Invalid servo pulse width.\n");
        return;
    }

    gpiod_line_request_set_value(&servo_req, pulse > SERVO_MAX_PULSE / 2);
}

unsigned int servo_get_pulse() {
    return gpiod_line_request_get_value(&servo_req) ? SERVO_MAX_PULSE : 0;
}

void setup_gpio() {
    int ret;

    ret = gpiod_library_open("gpiochip0");
    if (ret < 0) {
        perror("Failed to open gpiochip0");
        exit(EXIT_FAILURE);
    }

    servo_req.consumer = "door_lock_servo";
    ret = gpiod_chip_request_line(gpiod_library_get_chip_data(NULL), SERVO_GPIO, &servo_req);
    if (ret < 0) {
        perror("Failed to request servo GPIO line");
        exit(EXIT_FAILURE);
    }
    gpiod_line_request_set_direction(&servo_req, GPIOD_LINE_REQ_DIRECTION_OUT);
    servo_cb.consumer = "door_lock_servo";
    servo_cb.callback = servo_state_cb;
    gpiod_line_request_set_callback(&servo_req, &servo_cb);

    lock_req.consumer = "door_lock_lock";
    ret = gpiod_chip_request_line(gpiod_library_get_chip_data(NULL), LOCK_GPIO, &lock_req);
    if (ret < 0) {
        perror("Failed to request lock GPIO line");
        exit(EXIT_FAILURE);
    }
    gpiod_line_request_set_direction(&lock_req, GPIOD_LINE_REQ_DIRECTION_IN);
    lock_cb.consumer = "door_lock_lock";
    lock_cb.callback = lock_state_cb;
    gpiod_line_request_set_callback(&lock_req, &lock_cb);

    unlock_req.consumer = "door_lock_unlock";
    ret = gpiod_chip_request_line(gpiod_library_get_chip_data(NULL), UNLOCK_GPIO, &unlock_req);
    if (ret < 0) {
        perror("Failed to request unlock GPIO line");
        exit(EXIT_FAILURE);
    }
    gpiod_line_request_set_direction(&unlock_req, GPIOD_LINE_REQ_DIRECTION_IN);
    unlock_cb.consumer = "door_lock_unlock";
    unlock_cb.callback = unlock_state_cb;
    gpiod_line_request_set_callback(&unlock_req, &unlock_cb);
}

void cleanup_gpio() {
    gpiod_line_request_set_callback(&servo_req, NULL);
    gpiod_line_request_free(&servo_req);

    gpiod_line_request_set_callback(&lock_req, NULL);
    gpiod_line_request_free(&lock_req);

    gpiod_line_request_set_callback(&unlock_req, NULL);
    gpiod_line_request_free(&unlock_req);

    gpiod_library_close(gpiod_library_get_fd(NULL));
}

void signal_handler(int signum) {
    printf("Received SIGINT, cleaning up and exiting...\n");
    cleanup_gpio();
    exit(EXIT_SUCCESS);
}

int main() {
    struct timespec debounce_delay;
    int ret;

    signal(SIGINT, signal_handler);

    setup_gpio();

    while (1) {
        gpiod_line_get_value_with_timeout(&lock_req, &debounce_delay);
        nanosleep(&debounce_delay, NULL);

        if (gpiod_line_get_value(&lock_req) == 0) {
            printf("Lock button pressed.\n");
        }

        gpiod_line_get_value_with_timeout(&unlock_req, &debounce_delay);
        nanosleep(&debounce_delay, NULL);

        if (gpiod_line_get_value(&unlock_req) == 0) {
            printf("Unlock button pressed.\n");
        }
    }

    cleanup_gpio();
    return 0;
}
```

