**alarm_node.c**

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/types.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <zmq.h>
#include <signal.h>
#include <time.h>

#define GPIO_ALARM 27

gpiod_line_request_line_data_t line_data = { .direction = GPIOD_OUT };
gpiod_line_request_line_data_vdev_cb_data_t vdev_cb_data = { .user_data = NULL };
gpiod_line_request_line_data_vdev_cb_t vdev_cb = { .open = gpiod_line_request_line_open, .close = gpiod_line_request_line_close };
gpiod_line_request_line_data_cb_t cb = { .vdev_cb = &vdev_cb, .user_data = &vdev_cb_data };

void alarm_on() {
    gpiod_line_set_value(&line_data, 1);
}

void alarm_off() {
    gpiod_line_set_value(&line_data, 0);
}

void alarm_blink() {
    alarm_on();
    sleep(1);
    alarm_off();
}

void handle_sound_alert(void *context, const char *topic, const char *message) {
    alarm_blink();
}

int main(int argc, char *argv[]) {
    if (argc != 1) {
        fprintf(stderr, "Usage: %s\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    int gpio_fd = gpiod_open_name("gpiochip0", GPIO_ALARM);
    if (gpio_fd < 0) {
        perror("gpiod_open_name");
        exit(EXIT_FAILURE);
    }

    int rc = gpiod_line_request_line(&gpio_fd, &line_data, &cb);
    if (rc < 0) {
        perror("gpiod_line_request_line");
        exit(EXIT_FAILURE);
    }

    void *context = zmq_ctx_new();
    void *socket = zmq_socket(context, ZMQ_SUB);
    int rc = zmq_connect(socket, "tcp://localhost:5555");
    if (rc != 0) {
        perror("zmq_connect");
        exit(EXIT_FAILURE);
    }

    rc = zmq_setsockopt(socket, ZMQ_SUBSCRIBE, "SOUND_ALERTS", strlen("SOUND_ALERTS"));
    if (rc != 0) {
        perror("zmq_setsockopt");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, clean_shutdown);
    signal(SIGTERM, clean_shutdown);

    while (1) {
        zmq_pollitem_t items[] = { { socket, 0, ZMQ_POLLIN, 0 } };
        int rc = zmq_poll(items, 1, -1);
        if (rc > 0 && items[0].revents & ZMQ_POLLIN) {
            char topic[16] = { 0 };
            char message[32] = { 0 };
            rc = zmq_recv(socket, topic, sizeof(topic), 0);
            if (rc > 0) {
                rc = zmq_recv(socket, message, sizeof(message), 0);
                if (rc > 0) {
                    handle_sound_alert(NULL, topic, message);
                }
            }
        }
    }

    return 0;
}

void clean_shutdown(int sig) {
    gpiod_line_release_request_line(&line_data);
    gpiod_close(line_data.fd);
    zmq_ctx_term(zmq_ctx_new());
    exit(EXIT_SUCCESS);
}
