Here's the C code:

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/types.h>
#include <gpiod.h>
#include <pthread.h>
#include <mosquitto.h>
#include <time.h>

#define GPIO_NR 17
#define NEC_MARK 1
#define NEC_SPACE 0
#define NEC_HEADER 9000
#define NEC_BIT_MARK 560
#define NEC_BIT_SPACE 1690
#define NEC_BIT_COUNT 32
#define NEC_CHECKSUM_BIT_COUNT 8
#define NEC_CHECKSUM_INVERTED 0x5a

typedef struct {
    uint32_t address;
    uint32_t command;
    uint8_t checksum;
} nec_frame_t;

void nec_decode(uint32_t *frame, const uint32_t *pulse_buffer, size_t buffer_size) {
    size_t i;
    uint32_t bit;

    for (i = 0; i < NEC_BIT_COUNT; ++i) {
        bit = 0;
        if (pulse_buffer[i] > pulse_buffer[i + 1]) {
            bit = NEC_MARK;
        }
        frame[i / 8] |= (bit << (7 - (i % 8)));
    }

    frame[NEC_BIT_COUNT / 8] = ~frame[NEC_BIT_COUNT / 8];
}

void nec_checksum(const nec_frame_t *frame, uint8_t *checksum) {
    size_t i;
    uint32_t sum = 0;

    for (i = 0; i < NEC_BIT_COUNT; ++i) {
        sum += (frame->command >> (7 - (i % 8))) & 1;
    }

    *checksum = ~sum & 0xff;
}

void nec_alert_cb(struct gpiod_line *line, int event, void *user_data) {
    static uint32_t pulse_buffer[NEC_BIT_COUNT];
    static size_t pulse_buffer_index = 0;

    if (event == GPIOD_LINE_EVENT_FALLING_EDGE) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        pulse_buffer[pulse_buffer_index] = (ts.tv_sec * 1000000000 + ts.tv_nsec) - pulse_buffer[0];

        if (pulse_buffer_index >= NEC_BIT_COUNT) {
            nec_frame_t frame;
            nec_decode(&frame, pulse_buffer, NEC_BIT_COUNT);
            nec_checksum(&frame, NULL);

            if (frame.checksum == NEC_CHECKSUM_INVERTED) {
                printf("NEC address: 0x%08x, command: 0x%08x\n", frame.address, frame.command);
                char json[256];
                snprintf(json, sizeof(json), "{\"address\": %08lx, \"command\": %08lx}", frame.address, frame.command);
                mqtt_publish(json);
            }

            memset(pulse_buffer, 0, sizeof(pulse_buffer));
            pulse_buffer_index = 0;
        }

        if (pulse_buffer_index < NEC_HEADER) {
            pulse_buffer_index = 0;
        } else if (pulse_buffer[0] != NEC_HEADER) {
            memset(pulse_buffer, 0, sizeof(pulse_buffer));
            pulse_buffer_index = 0;
        } else {
            pulse_buffer_index++;
        }
    }
}

void mqtt_init() {
    mosquitto_lib_init();
    mosquitto_connect_options_set_keepalive(&options, 60, 0);
    mosquitto_connect_options_set_clean_session(&options, 1);
    mosquitto_connect_options_set_will(&options, NULL, NULL, 0, 0, 0);
    mosquitto_connect_options_set_id(&options, "nec_decoder");
    mosquitto_connect(&client, "localhost", 1883, &options);
}

void mqtt_publish(const char *message) {
    int rc = mosquitto_publish(client, 0, "ir/decoded", strlen(message), message, 0, 0);
    if (rc != MOSQ_ERR_SUCCESS) {
        printf("Failed to publish message: %s\n", mosquitto_strerror(rc));
    }
}

int main() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_request *request;
    gpiod_line_flags_t flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_FALLING;
    mosquitto_lib_options_t options;
    mosquitto_t *client;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_NR);
    if (!line) {
        perror("Failed to get line");
        gpiod_chip_close(chip);
        return 1;
    }

    request = gpiod_line_request_get(line);
    ret = gpiod_line_request_set_flags(request, flags);
    if (ret < 0) {
        perror("Failed to set line flags");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_enable(request);
    if (ret < 0) {
        perror("Failed to enable line request");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    gpiod_line_set_debounce(line, 0);
    gpiod_line_set_glitch_filter(line, 0);

    mqtt_init();

    mosquitto_loop_start(client);

    gpiod_line_set_event_callback(line, nec_alert_cb, NULL);

    while (1) {
        usleep(100000);
    }

    gpiod_line_set_event_callback(line, NULL, NULL);
    gpiod_line_request_disable(request);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    mosquitto_lib_cleanup();

    return 0;
}
