#define MULTICAST_IP "239.255.255.250"

struct sensor_data {
    int id;
    double lux;
};

struct i2c_data {
    int fd;
    int addr;
};

struct sensor_data sensors[NUM_SENSORS];
struct i2c_data i2c_dev[NUM_SENSORS];
struct ev_loop *loop;
struct ev_io watchers[NUM_SENSORS];
int terminate = 0;

void i2c_read(struct ev_loop *loop, ev_io *w, int revents) {
    int i = EV_IO_GET_FD(w) - I2C_BUS;
    if (revents & EV_ERROR) {
        printf("I2C read error on sensor %d\n", i + 1);
        sensors[i].lux = NAN;
    } else {
        ssize_t len = read(i2c_dev[i].fd, &sensors[i].lux, sizeof(sensors[i].lux));
        if (len != sizeof(sensors[i].lux)) {
            printf("Partial read on sensor %d\n", i + 1);
            sensors[i].lux = NAN;
        }
    }
    ev_io_stop(loop, w);
    ev_io_set(watchers + i, I2C_BUS + i, EV_READ | EV_PERSIST);
    ev_io_start(loop, watchers + i);
}

void udp_send(ev_loop *loop, ev_timer *w, int revents) {
    static char buf[NUM_SENSORS * 16];
    int i;
    snprintf(buf, sizeof(buf), "%d", getpid());
    for (i = 0; i < NUM_SENSORS; ++i) {
        if (!isnan(sensors[i].lux)) {
            strcat(buf, ",");
            snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), "%d,%.2f", sensors[i].id, sensors[i].lux);
        }
    }

    int sockfd = socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP);
    if (sockfd < 0) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    struct sockaddr_in serv_addr;
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(UDP_PORT);
    inet_pton(AF_INET, MULTICAST_IP, &serv_addr.sin_addr);

    if (sendto(sockfd, buf, strlen(buf), 0, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("sendto");
    }

    close(sockfd);
}

int main() {
    gpiod_line_request_dt_byname(NULL, "rpi,gpio-i2c1-sda");
    gpiod_line_request_dt_byname(NULL, "rpi,gpio-i2c1-scl");
    gpiod_line_request_dt_byname(NULL, "rpi,gpio-i2c1-sda1");
    gpiod_line_request_dt_byname(NULL, "rpi,gpio-i2c1-scl1");

    for (int i = 0; i < NUM_SENSORS; ++i) {
        i2c_dev[i].fd = open("/dev/i2c-1", O_RDWR);
        if (i2c_dev[i].fd < 0) {
            perror("open");
            exit(EXIT_FAILURE);
        }

        if (ioctl(i2c_dev[i].fd, I2C_SLAVE, SENSOR_ADDRS[i]) < 0) {
            perror("ioctl");
            exit(EXIT_FAILURE);
        }

        ev_io_init(&watchers[i], i2c_read, i2c_dev[i].fd);
        ev_io_start(loop = ev_default_loop(0), &watchers[i]);
    }

    signal(SIGINT, [](int signum) { terminate = 1; });
    signal(SIGTERM, [](int signum) { terminate = 1; });

    struct ev_timer timer;
    ev_timer_init(&timer, udp_send, 1.0, 1.0);
    ev_timer_start(loop, &timer);

    ev_run(loop, 0);

    for (int i = 0; i < NUM_SENSORS; ++i) {
        close(i2c_dev[i].fd);
    }

    return 0;
}

