#include <linux/i2c-dev.h>
#include <time.h>
#include <sys/time.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define AWM7300_ADDR 0x48
#define AWM7300_REG_LOW_WORD 0x00
#define AWM7300_REG_HIGH_WORD 0x01
#define AWM7300_MASK 0x0FFF
#define AWM7300_SLPM_CONVERSION_FACTOR 100.0

static gpiod_line_request_linestate_t gpio_state;
static gpiod_line_data_flags_t gpio_flags = GPIOD_LINE_REPORT_EDGE_FALLING | GPIOD_LINE_ACTIVE_LOW;
static int i2c_fd;
static FILE *log_file;

void sigint_handler(int signum) {
    gpiod_line_set_value(gpio_line, 0);
    close(i2c_fd);
    fclose(log_file);
    exit(0);
}

int i2c_write_read(uint8_t reg, uint8_t *write_buf, size_t write_len, uint8_t *read_buf, size_t read_len) {
    ssize_t ret;

    if ((ret = write(i2c_fd, write_buf, write_len)) != write_len) {
        perror("I2C write");
        return -1;
    }

    if (read_len > 0) {
        if ((ret = read(i2c_fd, read_buf, read_len)) != read_len) {
            if (errno == EAGAIN || errno == EBUSY) {
                usleep(100000);
                return i2c_write_read(reg, write_buf, write_len, read_buf, read_len);
            } else {
                perror("I2C read");
                return -1;
            }
        }
    }

    return 0;
}

uint16_t read_awm7300() {
    uint8_t buf[2];
    int ret;

    ret = i2c_write_read(AWM7300_REG_LOW_WORD, NULL, 0, buf, 2);
    if (ret < 0) {
        return 0;
    }

    return (buf[0] << 8) | buf[1];
}

float convert_awm7300_to_slpm(uint16_t value) {
    return (value & AWM7300_MASK) * AWM7300_SLPM_CONVERSION_FACTOR;
}

int main() {
    int ret;
    struct timespec ts;
    uint16_t flow_value;
    float flow_rate;
    char log_line[64];

    signal(SIGINT, sigint_handler);

    gpiod_line_request_list lines[] = {
        GPIOD_LINE_REQUEST_BANK(0),
        GPIOD_LINE_REQUEST_NAME("gpio", 17),
        GPIOD_LINE_REQUEST_DIRECTION_IN,
        GPIOD_LINE_REQUEST_EDGE_FALLING,
        GPIOD_LINE_REQUEST_ACTIVE_LOW,
        GPIOD_LINE_REQUEST_FLAGS(gpio_flags),
    };
    gpiod_line_request_data_vlinestate_t line_data = {
        .linestate = &gpio_state,
    };
    gpiod_line_request_data_vlinestate_array_t line_data_array = {
        .lines = lines,
        .n_lines = ARRAY_SIZE(lines),
        .data = &line_data,
    };

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Open I2C bus");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AWM7300_ADDR) < 0) {
        perror("I2C slave address");
        exit(1);
    }

    ret = gpiod_line_request_array_probe(&line_data_array);
    if (ret < 0) {
        perror("GPIO line request");
        exit(1);
    }

    log_file = fopen("airflow_log.txt", "w");
    if (!log_file) {
        perror("Open log file");
        exit(1);
    }

    while (1) {
        gpio_state = gpiod_get_value_cansleep(gpio_line);
        if (gpio_state == 1) {
            flow_value = read_awm7300();
            if (flow_value > 0) {
                flow_rate = convert_awm7300_to_slpm(flow_value);
                ts.tv_sec = time(NULL);
                ts.tv_nsec = 0;
                strftime(log_line, sizeof(log_line), "%Y-%m-%d %H:%M:%S ", localtime(&ts.tv_sec));
                snprintf(log_line + strlen(log_line), sizeof(log_line) - strlen(log_line), "%.2f SLPM\n", flow_rate);
                fputs(log_line, log_file);
                fflush(log_file);
            }
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        ts.tv_sec += 1;
        usleep((ts.tv_sec - clock_gettime(CLOCK_REALTIME, NULL).tv_sec) * 1000000 + (ts.tv_nsec / 1000));
    }

    close(i2c_fd);
    fclose(log_file);
    gpiod_line_release_array(&line_data_array);

    return 0;
}

