code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <sys/time.h>
#include <errno.h>
#include <gpiod.h>

#define I2C_BUS 1
#define ADAFRUIT_AS7341_ADDR 0x40
#define CFG6_REG 0x06
#define ENABLE_REG 0x05
#define SP_EN_BIT 0x01
#define PON_BIT 0x08
#define F1_REG 0x00
#define F8_REG 0x07
#define NUM_CHANNELS 10
#define LUX_SCALE 0.0018

static const char *log_file = "spectral_log.csv";

int init_i2c(void) {
    int file = open("/dev/i2c-1", O_RDWR);
    if (file < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(file, I2C_SLAVE, ADAFRUIT_AS7341_ADDR) < 0) {
        perror("Failed to acquire bus access");
        close(file);
        return -1;
    }

    return file;
}

int read_sensor_id(int file) {
    uint8_t id;
    if (i2c_smbus_read_byte_data(file, 0x00) != 0x44) {
        fprintf(stderr, "Invalid sensor ID\n");
        return -1;
    }

    if (i2c_smbus_read_byte_data(file, 0x01) != 0x11) {
        fprintf(stderr, "Invalid sensor revision\n");
        return -1;
    }

    return 0;
}

void power_on(int file) {
    uint8_t value = gpiod_get_value_cansleep(gpio_get_fd(18));
    if (value == 0) {
        gpiod_set_value_cansleep(gpio_get_fd(18), 1);
    }

    if (i2c_smbus_write_byte_data(file, ENABLE_REG, PON_BIT) < 0) {
        perror("Failed to set PON bit");
    }
}

void configure_sensor(int file) {
