        perror("Failed to open I2C device after all retries");
        exit(EXIT_FAILURE);
    }

    if (argc > 1 && strcmp(argv[1], "-a") == 0) {
        if (sscanf(argv[2], "%x", &addr) != 1) {
            fprintf(stderr, "Invalid I2C address\n");
            exit(EXIT_FAILURE);
        }
        argv += 2;
        argc -= 2;
    }

    if (argc > 1 && strcmp(argv[1], "-i") == 0) {
        if (sscanf(argv[2], "%lf", &interval) != 1) {
            fprintf(stderr, "Invalid sampling interval\n");
            exit(EXIT_FAILURE);
        }
        argv += 2;
        argc -= 2;
    }

    if (argc > 1 && strcmp(argv[1], "-f") == 0) {
        strncpy(output_file, argv[2], sizeof(output_file));
