        x_raw = i2c_read_word_data(i2c_fd, 0x02);
        y_raw = i2c_read_word_data(i2c_fd, 0x04);
        z_raw = i2c_read_word_data(i2c_fd, 0x06);

        if (x_raw == 0xFFFF || y_raw == 0xFFFF || z_raw == 0xFFFF) {
            log_error("Sensor not present or bus error");
            break;
        }

        x = (double)x_raw / 65536 * 2 * 3.9;
        y = (double)y_raw / 65536 * 2 * 3.9;
        z = (double)z_raw / 65536 * 2 * 3.9;

        double timestamp = time(NULL);
        if (timestamp - last_timestamp >= interval) {
            log_data(output_file);
            last_timestamp = timestamp;
        }

        usleep(interval * 1000000);
    }

    i2c_write_byte_data(i2c_fd, 0x0A, 0x01); // Power off
    close(i2c_fd);

    return 0;
}

