#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <netinet/in.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <endian.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define UDP_PORT 5000
#define TTL 1
#define BUFFER_SIZE 256

static gpiod_line_request_linestate_cb_t gpio_cb;
static gpiod_line_data_t gpio_data;
static struct sockaddr_in udp_addr;
static int udp_sockfd, i2c_fd;

void signal_handler(int sig) {
    close(i2c_fd);
    close(udp_sockfd);
    exit(0);
}

float bh1750_read_lux(int i2c_fd) {
    char buf[2];
    int ret;

    ret = i2c_smbus_read_word_data(i2c_fd, BH1750_ADDR, 0x23);
    if (ret < 0) {
        perror("i2c_smbus_read_word_data");
        return -1.0;
    }

    buf[0] = (char)(ret >> 8);
    buf[1] = (char)(ret & 0xFF);

    return (float)be16toh(*(uint16_t*)buf) / 1.2;
}

void udp_send(float lux) {
    char buffer[BUFFER_SIZE];
    snprintf(buffer, BUFFER_SIZE, "%f\n", lux);

    sendto(udp_sockfd, buffer, strlen(buffer), 0, (struct sockaddr*)&udp_addr, sizeof(udp_addr));
}

int main() {
    int ret;
    float lux;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("open /dev/i2c-1");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        exit(1);
    }

    if ((udp_sockfd = socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP)) < 0) {
        perror("socket");
        exit(1);
    }

    memset(&udp_addr, 0, sizeof(udp_addr));
    udp_addr.sin_family = AF_INET;
    udp_addr.sin_port = htons(UDP_PORT);
    udp_addr.sin_addr.s_addr = htonl(INADDR_ANY);

    if (bind(udp_sockfd, (struct sockaddr*)&udp_addr, sizeof(udp_addr)) < 0) {
        perror("bind");
        exit(1);
    }

    ret = setsockopt(udp_sockfd, IPPROTO_IP, IP_MULTICAST_TTL, &TTL, sizeof(TTL));
    if (ret < 0) {
        perror("setsockopt IP_MULTICAST_TTL");
        exit(1);
    }

    inet_pton(AF_INET, "239.255.255.250", &udp_addr.sin_addr);

    while (1) {
        lux = bh1750_read_lux(i2c_fd);
        if (lux < 0.0) {
            printf("Error reading sensor data, retrying in 1 second...\n");
            sleep(1);
            continue;
        }

        udp_send(lux);
        sleep(1);
    }

    close(i2c_fd);
    close(udp_sockfd);

    return 0;
}

