#define LINE_BUFFER_SIZE 1024

static gpiod_line_request_lines_data_v1_0_array lines = {
    { .flags = GPIOD_LINE_REQUEST_INPUT, .consumer = "mmWave Radar Sensor" },
};
static gpiod_line_request_data_v1_0 request_data = {
    .lines = &lines,
    .n_lines = 1,
};

static int uart_fd, gpio_fd;
static char line_buffer[LINE_BUFFER_SIZE];
static char buffer[BUFFER_SIZE];
static size_t buffer_pos = 0;

void sigint_handler(int signum) {
    close(uart_fd);
    gpiod_line_release(gpio_fd, lines[0].consumer);
    exit(0);
}

void sigterm_handler(int signum) {
    sigint_handler(signum);
}

int setup_uart() {
    struct termios options;
    tcgetattr(uart_fd, &options);

    cfsetispeed(&options, B115200);
    cfsetospeed(&options, B115200);

    options.c_cflag |= (CLOCAL | CREAD);
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;

    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_iflag &= ~(ICANON | ECHO | ECHOE | ISIG);

    options.c_oflag &= ~OPOST;

    options.c_cc[VMIN] = 0;
    options.c_cc[VTIME] = UART_TIMEOUT;

    if (tcsetattr(uart_fd, TCSANOW, &options) == -1) {
        perror("tcsetattr");
        return -1;
    }

    return 0;
}

int read_uart() {
    fd_set read_fds;
    struct timeval timeout;
    int ret;

    FD_ZERO(&read_fds);
    FD_SET(uart_fd, &read_fds);

    timeout.tv_sec = UART_TIMEOUT;
    timeout.tv_usec = 0;

    ret = select(uart_fd + 1, &read_fds, NULL, NULL, &timeout);
    if (ret == -1) {
        perror("select");
        return -1;
    }

    if (ret == 0) {
        fprintf(stderr, "UART timeout\n");
        return -1;
    }

    ret = read(uart_fd, buffer, BUFFER_SIZE - 1);
    if (ret == -1) {
        perror("read");
        return -1;
    }

    buffer[ret] = '\0';
    strncat(line_buffer, buffer, ret);

    size_t line_len = strlen(line_buffer);
    size_t newline_pos = line_buffer[line_len - 1] == '\n' ? line_len - 1 : -1;

    if (newline_pos != -1) {
        char *line = strndup(line_buffer, newline_pos);
        if (!line) {
            perror("strndup");
            return -1;
        }

        struct tm tm;
        char timestamp[32];
        strptime(line, "<%Y-%m-%d %H:%M:%S,", &tm);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
        double range = strtod(line + 18, NULL);

        printf("Timestamp: %s, Range: %.2f meters\n", timestamp, range);
        free(line);

        memset(line_buffer, 0, LINE_BUFFER_SIZE);
    }

    return 0;
}

int main() {
    gpio_fd = gpiod_library_open();
    if (gpiod_library_get_error_code(gpio_fd) != 0) {
        perror("gpiod_library_open");
        exit(1);
    }

    if (gpiod_chip_request_lines(gpio_fd, "gpiochip0", &request_data) == -1) {
        perror("gpiod_chip_request_lines");
        exit(1);
    }

    gpio_tdms_clock_set_request(gpio_fd, lines[0].number, GPIOD_TDMS_CLOCK_SOURCE_GPIO, 0);

    uart_fd = open("/dev/serial0", O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd == -1) {
        perror("open");
        exit(1);
    }

    if (setup_uart() == -1) {
        close(uart_fd);
        exit(1);
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (1) {
        if (read_uart() == -1) {
            break;
        }

        usleep(500000);
    }

    close(uart_fd);
    gpiod_line_release(gpio_fd, lines[0].consumer);
    gpiod_library_close(gpio_fd);

    return 0;
}

